window.NT_ASSISTANT_CORPUS = {"version":2,"pdfPages":181,"records":[{"id":"s1","kind":"lesson","lesson":"1.1.1","title":"Giới thiệu tổng quát về ô tô · Phân loại ô tô theo kết cấu","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân biệt nhóm ô tô."},{"id":"s2","kind":"simulation","lesson":"1.1.1","title":"Trình tự phân biệt nhóm ô tô","text":"1. Xác định đối tượng chuyên chở. Đọc mục đích sử dụng: người, hành lý hay hàng hóa. 2. Quan sát các khoang của xe. Ô tô du lịch có khoang động cơ, khoang chở người và khoang hành lý. 3. Đối chiếu kết cấu phục vụ công dụng. Ô tô tải cần không gian chứa hàng lớn; ô tô khách ưu tiên chở người. 4. Kết luận theo đúng tiêu chí. Phân loại công dụng và phân loại HTTL là hai tiêu chí riêng."},{"id":"s3","kind":"figure","lesson":"1.1.1","title":"Phân loại ô tô theo kết cấu — sơ đồ học tập biên soạn từ bài 1.1.1","text":"A. Ô tô du lịch. Có các khoang động cơ, chở người và hành lý. B. Ô tô khách. Được thiết kế để chở người với số ghế theo nhóm xe. C. Ô tô tải. Mục đích chính là vận tải hàng hóa. D. HTTL cơ khí. Bao gồm ly hợp, hộp số, trục truyền các đăng và cầu chủ động.","figure":{"image":"tuong_tac/diagrams/vehicles.svg","caption":"Phân loại ô tô theo kết cấu — sơ đồ học tập biên soạn từ bài 1.1.1"}},{"id":"s4","kind":"part","lesson":"1.1.1","title":"Ô tô du lịch","text":"Có các khoang động cơ, chở người và hành lý.","keywords":["Ô tô du lịch"],"figure":{"image":"tuong_tac/diagrams/vehicles.svg","caption":"Phân loại ô tô theo kết cấu — sơ đồ học tập biên soạn từ bài 1.1.1"}},{"id":"s5","kind":"part","lesson":"1.1.1","title":"Ô tô khách","text":"Được thiết kế để chở người với số ghế theo nhóm xe.","keywords":["Ô tô khách"],"figure":{"image":"tuong_tac/diagrams/vehicles.svg","caption":"Phân loại ô tô theo kết cấu — sơ đồ học tập biên soạn từ bài 1.1.1"}},{"id":"s6","kind":"part","lesson":"1.1.1","title":"Ô tô tải","text":"Mục đích chính là vận tải hàng hóa.","keywords":["Ô tô tải"],"figure":{"image":"tuong_tac/diagrams/vehicles.svg","caption":"Phân loại ô tô theo kết cấu — sơ đồ học tập biên soạn từ bài 1.1.1"}},{"id":"s7","kind":"part","lesson":"1.1.1","title":"HTTL cơ khí","text":"Bao gồm ly hợp, hộp số, trục truyền các đăng và cầu chủ động.","keywords":["HTTL cơ khí"],"figure":{"image":"tuong_tac/diagrams/vehicles.svg","caption":"Phân loại ô tô theo kết cấu — sơ đồ học tập biên soạn từ bài 1.1.1"}},{"id":"s8","kind":"figure","lesson":"1.1.1","title":"Hình 1.1.Phân loại ô tô","text":"Hình 1.1.Phân loại ô tô","anchor":"block-1781142838340-bifg739be","figure":{"number":"1.1","caption":"Hình 1.1.Phân loại ô tô"}},{"id":"s9","kind":"html","lesson":"1.1.1","title":"Giới thiệu tổng quát về ô tô · Phân loại ô tô theo kết cấu","text":"Ô tô du lịch được dùng để chuyên chở người (tối đa 9 người kể cả người lái), hành lý hay đồ đạc gọn nhẹ. Kết cấu của ô tô du lịch gồm 3 khoang: Động cơ, Chở người (hành khách), hành lý. Tùy vào khả năng sử dụng của ô tô du lịch có thể phân chia ra các hình dáng vỏ khác nhau theo tên gọi khác nhau. Đây là loại đa dạng về hình dáng, công suất, tính năng kỹ thuật. Ô tô khách là loại ô tô được thiết kế để chở người với số ghế từ 9 đến 50 chỗ. Tùy theo số ghế và mục đích sử dụng thì ô tô khách cũng được chia thành nhiều nhóm khác nhau. Ô tô tải là phương tiện cơ động với mục đích chính là vận tải hàng hóa. Ô tô tải là một trong những nhóm xe cơ giới đa dạng về trọng tải và đặc điểm kết cấu. Kết cấu của ô tô tải cần có không gian chứa hàng lớn.","anchor":"block-1781142838340-bifg739be"},{"id":"s10","kind":"html","lesson":"1.1.1","title":"Giới thiệu tổng quát về ô tô · Phân loại ô tô theo kết cấu","text":"Ngoài ra, kết cấu của ô tô cũng được phân loại theo kết cấu của hệ thống truyền lực: HTTL cơ khí: bao gồm ly hợp, hộp số, trục truyền các đăng, cầu chủ động; loại này được dùng phổ biến. HTTL cơ khí - thuỷ lực: bao gồm các bộ truyền cơ khí, và hộp số tự động; loại này được dùng phổ biến trên ô tô du lịch và vận tải nặng. HTTL điện từ. bao gồm nguồn điện, các động cơ điện, Rơle điện từ, dây dẫn. HTTL thuỷ lực: bao gồm bơm thuỷ lực, các động cơ thuỷ lực, van điều khiển, ống dẫn. HTTL liên hợp: bao gồm một số bộ phận cơ khí, một số bộ phận thuỷ lực, một số bộ phận điện tử. Phổ biến hơn cả là HTTL cơ khí; và cơ khí - thuỷ lực, điều khiển bằng điện tử. Xe (ô tô) chia thành nhiều nhóm khác nhau.","anchor":"block-1781142838340-bifg739be"},{"id":"s11","kind":"lesson","lesson":"1.1.2","title":"Giới thiệu tổng quát về ô tô · Phân loại ô tô theo tên gọi và kiểu thân xe","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự nhận biết hình dáng vỏ xe."},{"id":"s12","kind":"note","lesson":"1.1.2","title":"Dẫn chiếu phân loại và tiêu chuẩn","text":"Bản trước ghi “ISO 654” trong tiêu đề nhưng chưa có căn cứ xác nhận mã này cho bảng phân loại. Bản nâng cấp bỏ mã khỏi tiêu đề, giữ cách nhận dạng kiểu thân xe. ISO 3833:1977 là tài liệu định nghĩa các loại phương tiện đường bộ; không coi toàn bộ bảng trong bài đã được kiểm chứng phù hợp tiêu chuẩn này."},{"id":"s13","kind":"simulation","lesson":"1.1.2","title":"Trình tự nhận biết hình dáng vỏ xe","text":"1. Quan sát hình dáng thân xe. Nhận diện số khoang, cửa và phần đuôi xe. 2. Kiểm tra quan hệ cốp và kính sau. Cốp tách riêng gợi ý Sedan; cốp liền kính sau gợi ý Hatchback. 3. Đối chiếu cửa và khoang hàng. Coupe có hai cửa theo mô tả; Pick up là ô tô bán tải. 4. Chọn tên gọi phù hợp. Dùng đúng tên gọi được ghi dưới hình trong bài 1.1.2."},{"id":"s14","kind":"figure","lesson":"1.1.2","title":"Tên gọi các kiểu ô tô — sơ đồ học tập biên soạn từ bài 1.1.2","text":"A. Sedan. Có khoang hành lý riêng, nắp ca pô và cốp thấp hơn nóc khoang hành khách. B. Hatchback. Nắp cốp liền với kính sau và nối lên trần khoang hành khách. C. Coupe. Có thiết kế giống Sedan nhưng hai cửa và kiểu dáng thể thao theo bài học. D. Pick up. Ô tô bán tải, thuộc các tên gọi được trình bày trong bài.","figure":{"image":"tuong_tac/diagrams/bodynames.svg","caption":"Tên gọi các kiểu ô tô — sơ đồ học tập biên soạn từ bài 1.1.2"}},{"id":"s15","kind":"part","lesson":"1.1.2","title":"Sedan","text":"Có khoang hành lý riêng, nắp ca pô và cốp thấp hơn nóc khoang hành khách.","keywords":["Sedan"],"figure":{"image":"tuong_tac/diagrams/bodynames.svg","caption":"Tên gọi các kiểu ô tô — sơ đồ học tập biên soạn từ bài 1.1.2"}},{"id":"s16","kind":"part","lesson":"1.1.2","title":"Hatchback","text":"Nắp cốp liền với kính sau và nối lên trần khoang hành khách.","keywords":["Hatchback"],"figure":{"image":"tuong_tac/diagrams/bodynames.svg","caption":"Tên gọi các kiểu ô tô — sơ đồ học tập biên soạn từ bài 1.1.2"}},{"id":"s17","kind":"part","lesson":"1.1.2","title":"Coupe","text":"Có thiết kế giống Sedan nhưng hai cửa và kiểu dáng thể thao theo bài học.","keywords":["Coupe"],"figure":{"image":"tuong_tac/diagrams/bodynames.svg","caption":"Tên gọi các kiểu ô tô — sơ đồ học tập biên soạn từ bài 1.1.2"}},{"id":"s18","kind":"part","lesson":"1.1.2","title":"Pick up","text":"Ô tô bán tải, thuộc các tên gọi được trình bày trong bài.","keywords":["Pick up"],"figure":{"image":"tuong_tac/diagrams/bodynames.svg","caption":"Tên gọi các kiểu ô tô — sơ đồ học tập biên soạn từ bài 1.1.2"}},{"id":"s19","kind":"figure","lesson":"1.1.2","title":"Hình 1.2 Sedan","text":"Hình 1.2 Sedan","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.2","caption":"Hình 1.2 Sedan"}},{"id":"s20","kind":"figure","lesson":"1.1.2","title":"Hình 1.3.Hatchback","text":"Hình 1.3.Hatchback","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.3","caption":"Hình 1.3.Hatchback"}},{"id":"s21","kind":"figure","lesson":"1.1.2","title":"Hình 1.4.Coupe","text":"Hình 1.4.Coupe","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.4","caption":"Hình 1.4.Coupe"}},{"id":"s22","kind":"figure","lesson":"1.1.2","title":"Hình 1.5. MPV","text":"Hình 1.5. MPV","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.5","caption":"Hình 1.5. MPV"}},{"id":"s23","kind":"figure","lesson":"1.1.2","title":"Hình 1.6. Mẫu ô tô Van","text":"Hình 1.6. Mẫu ô tô Van","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.6","caption":"Hình 1.6. Mẫu ô tô Van"}},{"id":"s24","kind":"figure","lesson":"1.1.2","title":"Hình 1.7.Mẫu ô tô Minivan","text":"Hình 1.7.Mẫu ô tô Minivan","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.7","caption":"Hình 1.7.Mẫu ô tô Minivan"}},{"id":"s25","kind":"figure","lesson":"1.1.2","title":"Hình 1.8.Mẫu ô tô SUV","text":"Hình 1.8.Mẫu ô tô SUV","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.8","caption":"Hình 1.8.Mẫu ô tô SUV"}},{"id":"s26","kind":"figure","lesson":"1.1.2","title":"Hình 1.9.Mẫu ô tô CUV","text":"Hình 1.9.Mẫu ô tô CUV","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.9","caption":"Hình 1.9.Mẫu ô tô CUV"}},{"id":"s27","kind":"figure","lesson":"1.1.2","title":"Hình 1.10. Mẫu ô tô pick up (Bán tải)","text":"Hình 1.10. Mẫu ô tô pick up (Bán tải)","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.10","caption":"Hình 1.10. Mẫu ô tô pick up (Bán tải)"}},{"id":"s28","kind":"figure","lesson":"1.1.2","title":"Hình 1.11. Mẫu ô tô Limousine","text":"Hình 1.11. Mẫu ô tô Limousine","anchor":"block-1781142944871-i9l9zw09r","figure":{"number":"1.11","caption":"Hình 1.11. Mẫu ô tô Limousine"}},{"id":"s29","kind":"html","lesson":"1.1.2","title":"Phân loại ô tô theo tên gọi và kiểu thân xe · Đối với ô tô du lịch","text":"Mẫu ô tô phổ biến nhất, với 4 chỗ, 4 cửa, có nắp ca pô và cốp thấp hơn nóc khoang hành khách. Các mẫu ô tô Sedan ở Việt Nam rất phong phú: Toyota Camry/Vios/Altis, Kia Forte/K5, Honda Civic/Accord, Hyundai Sonata, Mercedes C/E/S, Audi A4/A6/… Là loại ô tô mà nắp cốp liền với kính sau và nối thẳng lên trần khoang hành khách... Có thiết kế giống với Sedan nhưng chỉ có 2 cửa, mang kiểu dáng thể thao... Dùng chung thiết kế khung ô tô con nhưng có không gian rộng hơn... Van: Ô tô chở người hoặc chở hàng hóa từ 7 đến 15 chỗ ngồi... Minivan: Nhỏ hơn Van, có từ 6 – 8 chỗ...","anchor":"block-1781142944871-i9l9zw09r"},{"id":"s30","kind":"figure","lesson":"1.1.2","title":"Hình 1.12.Ô tô tải","text":"Hình 1.12.Ô tô tải","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.12","caption":"Hình 1.12.Ô tô tải"}},{"id":"s31","kind":"figure","lesson":"1.1.2","title":"Hình 1.13.Ô tô cứu thương | Hình 1.14.Ô tô cẩu","text":"Hình 1.13.Ô tô cứu thương | Hình 1.14.Ô tô cẩu","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.13","caption":"Hình 1.13.Ô tô cứu thương | Hình 1.14.Ô tô cẩu"}},{"id":"s32","kind":"figure","lesson":"1.1.2","title":"Hình 1.13.Ô tô cứu thương","text":"Hình 1.13.Ô tô cứu thương","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.13","caption":"Hình 1.13.Ô tô cứu thương"}},{"id":"s33","kind":"figure","lesson":"1.1.2","title":"Hình 1.14.Ô tô cẩu","text":"Hình 1.14.Ô tô cẩu","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.14","caption":"Hình 1.14.Ô tô cẩu"}},{"id":"s34","kind":"figure","lesson":"1.1.2","title":"Hình 1.15. Ô tô thang cứu hộ | Hình 1.16. Ô tô cứu hỏa","text":"Hình 1.15. Ô tô thang cứu hộ | Hình 1.16. Ô tô cứu hỏa","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.15","caption":"Hình 1.15. Ô tô thang cứu hộ | Hình 1.16. Ô tô cứu hỏa"}},{"id":"s35","kind":"figure","lesson":"1.1.2","title":"Hình 1.15. Ô tô thang cứu hộ","text":"Hình 1.15. Ô tô thang cứu hộ","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.15","caption":"Hình 1.15. Ô tô thang cứu hộ"}},{"id":"s36","kind":"figure","lesson":"1.1.2","title":"Hình 1.16. Ô tô cứu hỏa","text":"Hình 1.16. Ô tô cứu hỏa","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.16","caption":"Hình 1.16. Ô tô cứu hỏa"}},{"id":"s37","kind":"figure","lesson":"1.1.2","title":"Hình 1.17. Ô tô chở xăng, dầu | Hình 1.18.Ô tô chở LPG","text":"Hình 1.17. Ô tô chở xăng, dầu | Hình 1.18.Ô tô chở LPG","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.17","caption":"Hình 1.17. Ô tô chở xăng, dầu | Hình 1.18.Ô tô chở LPG"}},{"id":"s38","kind":"figure","lesson":"1.1.2","title":"Hình 1.17. Ô tô chở xăng, dầu","text":"Hình 1.17. Ô tô chở xăng, dầu","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.17","caption":"Hình 1.17. Ô tô chở xăng, dầu"}},{"id":"s39","kind":"figure","lesson":"1.1.2","title":"Hình 1.18.Ô tô chở LPG","text":"Hình 1.18.Ô tô chở LPG","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.18","caption":"Hình 1.18.Ô tô chở LPG"}},{"id":"s40","kind":"figure","lesson":"1.1.2","title":"Hình 1.19. Ô tô trộn bê tông | Hình 1.20. Ô tô đua McLaren Senna","text":"Hình 1.19. Ô tô trộn bê tông | Hình 1.20. Ô tô đua McLaren Senna","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.19","caption":"Hình 1.19. Ô tô trộn bê tông | Hình 1.20. Ô tô đua McLaren Senna"}},{"id":"s41","kind":"figure","lesson":"1.1.2","title":"Hình 1.19. Ô tô trộn bê tông","text":"Hình 1.19. Ô tô trộn bê tông","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.19","caption":"Hình 1.19. Ô tô trộn bê tông"}},{"id":"s42","kind":"figure","lesson":"1.1.2","title":"Hình 1.20. Ô tô đua McLaren Senna","text":"Hình 1.20. Ô tô đua McLaren Senna","anchor":"block-1781143030050-ruplj42te","figure":{"number":"1.20","caption":"Hình 1.20. Ô tô đua McLaren Senna"}},{"id":"s43","kind":"html","lesson":"1.1.2","title":"Phân loại ô tô theo tên gọi và kiểu thân xe · Đối với Ô tô tải","text":"Với mục đích chính là vận chuyển hàng hóa, nên giữa buồng lái và khoang hàng hóa có sự cách biệt. Tùy theo dạng hàng hóa mà khoang hàng hóa có thiết kế khác nhau đảm bảo khả năng vận chuyển. Ô tô đa dụng được dùng với mục đích chuyên chở đa năng kể cả các vật thể có hình khối không tháo rời, khong gian chở hàng được ngăn cách với buồng lái. Ô tô tải thùng kín nhằm chuyên chở riêng biệt, được bắt chặt với khung xe. Thùng hàng có cửa mở ( 1,2 hay ba mặt). Ô tô tải cơ động cao dùng để vận tải ở địa hình phức tạp, có khả năng vượt chướng ngại lớn ( nền đường xấu, trơn trượt…) Phần lớn xe có dạng thân ngắn, với công thức bánh xe 4x4, 6x6, 8x8..) Với yêu cầu đặc biệt cho các mục đích khác nhau, thì ô tô chuyên dùng được thiết kế để đáp ứng đúng 1 nhiệm vụ đặt ra với các yêu cầu đặc trưng của từng nhiệm vụ.","anchor":"block-1781143030050-ruplj42te"},{"id":"s44","kind":"html","lesson":"1.1.2","title":"Phân loại ô tô theo tên gọi và kiểu thân xe · Đối với Ô tô tải","text":"Phần lớn ô tô chuyên dùng được chế tạo trên cơ sở ô tô tải (ô tô chassis có hay không có buồng lái) và lắp đặt các thiết bị chuyên dùng lên xe.","anchor":"block-1781143030050-ruplj42te"},{"id":"s45","kind":"figure","lesson":"1.1.2","title":"Hình 1.21.Mẫu ô tô 29. 35, 45 chỗ: County, Samco, Isuzu, Univers…","text":"Hình 1.21.Mẫu ô tô 29. 35, 45 chỗ: County, Samco, Isuzu, Univers…","anchor":"block-1781143164260-7t9325v7u","figure":{"number":"1.21","caption":"Hình 1.21.Mẫu ô tô 29. 35, 45 chỗ: County, Samco, Isuzu, Univers…"}},{"id":"s46","kind":"figure","lesson":"1.1.2","title":"Hình 1.22. Ô tô khách, ô tô buýt","text":"Hình 1.22. Ô tô khách, ô tô buýt","anchor":"block-1781143164260-7t9325v7u","figure":{"number":"1.22","caption":"Hình 1.22. Ô tô khách, ô tô buýt"}},{"id":"s47","kind":"html","lesson":"1.1.2","title":"Phân loại ô tô theo tên gọi và kiểu thân xe · Ô tô khách, ô tô buýt","text":"Mẫu ô tô 16 chỗ: Toyota Hiace, Mercedes Sprinter, Ford Transit Mục đích chính là dùng vận chuyển hành khách trên đường bộ. Kích thước ô tô phụ thuộc vào số lượng hành khách và hàng hóa mà ô tô có khả năng vận chuyển.","anchor":"block-1781143164260-7t9325v7u"},{"id":"s48","kind":"lesson","lesson":"1.1.3","title":"Giới thiệu tổng quát về ô tô · Phân loại ô tô theo công thức bánh xe","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự xác định công thức bánh xe."},{"id":"s49","kind":"simulation","lesson":"1.1.3","title":"Trình tự xác định công thức bánh xe","text":"1. Quy đổi cụm bánh kép. Mỗi cụm bánh kép được xem như một bánh khi lập công thức. 2. Đếm tổng số bánh theo quy ước. Giá trị đếm được là A. 3. Đếm số bánh xe chủ động. Xác định các vị trí nhận mô men dẫn động để có B. 4. Viết công thức A×B. Ví dụ A=6, B=4 thì công thức là 6×4."},{"id":"s50","kind":"figure","lesson":"1.1.3","title":"Công thức bánh xe A×B — sơ đồ học tập biên soạn từ bài 1.1.3","text":"A. A. Số bánh xe theo quy ước: mỗi cụm bánh kép được tính như một bánh. B. B. Số bánh xe nhận mô men dẫn động, cũng tính bánh kép theo quy ước. C. 4×2. Có bốn vị trí bánh xe, hai vị trí chủ động. D. 6×4. Có sáu vị trí bánh xe, bốn vị trí chủ động.","figure":{"image":"tuong_tac/diagrams/wheelcode.svg","caption":"Công thức bánh xe A×B — sơ đồ học tập biên soạn từ bài 1.1.3"}},{"id":"s51","kind":"part","lesson":"1.1.3","title":"A","text":"Số bánh xe theo quy ước: mỗi cụm bánh kép được tính như một bánh.","keywords":["A"],"figure":{"image":"tuong_tac/diagrams/wheelcode.svg","caption":"Công thức bánh xe A×B — sơ đồ học tập biên soạn từ bài 1.1.3"}},{"id":"s52","kind":"part","lesson":"1.1.3","title":"B","text":"Số bánh xe nhận mô men dẫn động, cũng tính bánh kép theo quy ước.","keywords":["B"],"figure":{"image":"tuong_tac/diagrams/wheelcode.svg","caption":"Công thức bánh xe A×B — sơ đồ học tập biên soạn từ bài 1.1.3"}},{"id":"s53","kind":"part","lesson":"1.1.3","title":"4×2","text":"Có bốn vị trí bánh xe, hai vị trí chủ động.","keywords":["4×2","4x2"],"figure":{"image":"tuong_tac/diagrams/wheelcode.svg","caption":"Công thức bánh xe A×B — sơ đồ học tập biên soạn từ bài 1.1.3"}},{"id":"s54","kind":"part","lesson":"1.1.3","title":"6×4","text":"Có sáu vị trí bánh xe, bốn vị trí chủ động.","keywords":["6×4","6x4"],"figure":{"image":"tuong_tac/diagrams/wheelcode.svg","caption":"Công thức bánh xe A×B — sơ đồ học tập biên soạn từ bài 1.1.3"}},{"id":"s55","kind":"html","lesson":"1.1.3","title":"Giới thiệu tổng quát về ô tô · Phân loại ô tô theo công thức bánh xe","text":"Công thức bánh xe được ký hiệu: AxB. Trong đó A là tổng số bánh xe, B là số bánh xe chủ động. Đối với xe có bánh kép, thì bánh kép đó xem như là 1 bánh xe. Các loại ô tô thường có các công thức sau: 4x2; 4x4; 6x2; 6x4; 6x6; 8x4; 8x8.","anchor":"block-1781143377242-pl37oi9wd"},{"id":"s56","kind":"figure","lesson":"1.1.3","title":"Hình 1.23. Động cơ đặt trước, dẫn động cầu sau","text":"Hình 1.23. Động cơ đặt trước, dẫn động cầu sau","anchor":"block-1781143395437-a2u6d5as8","figure":{"number":"1.23","caption":"Hình 1.23. Động cơ đặt trước, dẫn động cầu sau"}},{"id":"s57","kind":"html","lesson":"1.1.3","title":"Phân loại ô tô theo công thức bánh xe · Động cơ đặt trước, cầu sau chủ động (4x2, FR, RWD)","text":"Hình 1.23. Động cơ đặt trước, dẫn động cầu sau","anchor":"block-1781143395437-a2u6d5as8"},{"id":"s58","kind":"figure","lesson":"1.1.3","title":"Hình 1.24. Động cơ đặt trước, dẫn động cầu trước","text":"Hình 1.24. Động cơ đặt trước, dẫn động cầu trước","anchor":"block-1781143443776-nj2tetztf","figure":{"number":"1.24","caption":"Hình 1.24. Động cơ đặt trước, dẫn động cầu trước"}},{"id":"s59","kind":"html","lesson":"1.1.3","title":"Phân loại ô tô theo công thức bánh xe · Động cơ đặt trước, cầu trước chủ động (4x2, FF, FWD)","text":"Phương án này được sử dụng khá phổ biến trên các dòng ô tô du lịch, ô tô khách từ 9- 16 chỗ. Các loại ôtô bố trí theo sơ đồ này động cơ được đặt dọc hoặc ngang, có hệ thống thuyền lực gọn và các bánh ô tô trước có độ ổn định cao khi quay vòng.","anchor":"block-1781143443776-nj2tetztf"},{"id":"s60","kind":"figure","lesson":"1.1.3","title":"Hình 1.25.Audi R8 V10 plus","text":"Hình 1.25.Audi R8 V10 plus","anchor":"block-1781143491749-ed4dg0mvh","figure":{"number":"1.25","caption":"Hình 1.25.Audi R8 V10 plus"}},{"id":"s61","kind":"figure","lesson":"1.1.3","title":"Hình 1.26. Siêu xe Bugatti Veyron 1000 mã lực","text":"Hình 1.26. Siêu xe Bugatti Veyron 1000 mã lực","anchor":"block-1781143491749-ed4dg0mvh","figure":{"number":"1.26","caption":"Hình 1.26. Siêu xe Bugatti Veyron 1000 mã lực"}},{"id":"s62","kind":"figure","lesson":"1.1.3","title":"Hình 1.27. Porsche 911 có động cơ đặt hoàn toàn phía sau cầu sau, hộp số bố trí phía trước động cơ và ngay trên cầu sau.","text":"Hình 1.27. Porsche 911 có động cơ đặt hoàn toàn phía sau cầu sau, hộp số bố trí phía trước động cơ và ngay trên cầu sau.","anchor":"block-1781143491749-ed4dg0mvh","figure":{"number":"1.27","caption":"Hình 1.27. Porsche 911 có động cơ đặt hoàn toàn phía sau cầu sau, hộp số bố trí phía trước động cơ và ngay trên cầu sau."}},{"id":"s63","kind":"figure","lesson":"1.1.3","title":"Hình 1.28. Hệ thống truyền lực trên xe buýt, xe khách.","text":"Hình 1.28. Hệ thống truyền lực trên xe buýt, xe khách.","anchor":"block-1781143491749-ed4dg0mvh","figure":{"number":"1.28","caption":"Hình 1.28. Hệ thống truyền lực trên xe buýt, xe khách."}},{"id":"s64","kind":"figure","lesson":"1.1.3","title":"Hình 1.29. Bố trí Động cơ đặt trước, công thức bánh xe 4x4","text":"Hình 1.29. Bố trí Động cơ đặt trước, công thức bánh xe 4x4","anchor":"block-1781143491749-ed4dg0mvh","figure":{"number":"1.29","caption":"Hình 1.29. Bố trí Động cơ đặt trước, công thức bánh xe 4x4"}},{"id":"s65","kind":"html","lesson":"1.1.3","title":"Phân loại ô tô theo công thức bánh xe · Động cơ đặt sau, cầu sau chủ động (4x2, RR, RWD)","text":"Phương pháp này hệ thống truyền lực rất gọn, không cần sử dụng trục các đăng để truyền mô men xoắn từ hộp số tới cầu chủ động, vì động cơ, ly hợp, hộp số cầu sau chủ động liền hành một khối. Một số ô tô được bố trí kiểu này: Ferrari 458, 488, Porsche 911, Porsche Cayman/Boxster, Audi R8, Bugatti Veyron, Bugatti Chiron, Lamborghini Aventador, Lamborghini Huracan, Pagani Zonda, Pagani Huayra, Alfa Romeo 4C.. Đều là những chiếc ô tô có động cơ đặt sau. Ngoài ra, trên cá dòng xe buýt, xe khách cũng bố trí động cơ đặt sau, cầu sau chủ động. Sơ đồ thứ 1: Bố trí động cơ nằm ngang sau cầu sâu, cầu sau chủ động sử dụng hai bộ truyền bánh răng côn truyền lực giữa hộp số và cầu sau. Đảm bảo động lực học và độ tin cậy tốt nhất trong quá trình sử dụng, và thường bố trí kiểu này. Sơ đồ này phụ hợp cho xe khách, xe buýt.","anchor":"block-1781143491749-ed4dg0mvh"},{"id":"s66","kind":"html","lesson":"1.1.3","title":"Phân loại ô tô theo công thức bánh xe · Động cơ đặt sau, cầu sau chủ động (4x2, RR, RWD)","text":"Sơ đồ thứ 2: Bố trí động cơ nằm dọc sau xe, khung xe cần thấp, phù hợp với cấu trúc dang khung dàn. Động cơ nằm nghiêng nhằm nâng cao góc thoát phía sau xe. Sơ đồ thứ 3: động cơ nằm sau lệch về 1 bên, thuận lợi trong bảo dưỡng, sửa chữa, nhưng tạo nên sự mất cân bằng tải trọng tác dụng lên các bánh xe cầu sau và trên trục dọc. Tuy nhiên cấu trúc này cho phép dành nhiều không gian chở người, sàn thấp, phù hợp vận tải ngắn, hoặc tại sân bay. Động cơ đặt trước, công thức bánh xe 4x4 (4WD hoặc AWD) Phương án bố trí này được sử dụng nhiều trên xe tải và các xe du lịch. Mục đích là nâng cao tính cơ động cho xe sử dụng 2 cầu chủ động.","anchor":"block-1781143491749-ed4dg0mvh"},{"id":"s67","kind":"figure","lesson":"1.1.3","title":"Hình 1.30. Hệ thống truyền lực ô tô vận tải đa dụng","text":"Hình 1.30. Hệ thống truyền lực ô tô vận tải đa dụng","anchor":"block-1781143572101-i256k443z","figure":{"number":"1.30","caption":"Hình 1.30. Hệ thống truyền lực ô tô vận tải đa dụng"}},{"id":"s68","kind":"html","lesson":"1.1.3","title":"Phân loại ô tô theo công thức bánh xe · Động cơ đặt trước, công thức bánh xe 6x4, 6x6, 8x4, 8x8","text":"Động cơ, li hợp và hộp số (1,2,3) đặt liền khối với động cơ và bắt chung với khung của ô tô nhờ các gối đỡ đàn hồi. Hộp số của ô tô tải lớn sử dụng nhiều cấp số truyền ( 5,6 hoặc nhiều hơn). Ô tô vận tải đa năng sử dụng dầm cầu cứng với các bánh kép chủ động trên cầu sau, tạo điều kiện chịu tải tốt và tăng bền cho hệ thống truyền lực. Các loại ô tô cơ động cao dùng nhiều trong quân sự, lâm nghiệp và vận tải chuyên dùng trong điều kiện địa hình chưa hoàn thiện. Cấu trúc hệ thống truyền lực cho ô tô cơ động cao 2, 3 và 4 cầu chủ động cần có thêm hộp phân phối để phân chia mô men ra các cầu. Toàn bộ các bánh xe đều là bánh chủ động nhằm năng cao tối đa trọng lượng bám của ô tô. 1,2,3-Động cơ, li hợp, hộp số; 4-Bán trục; 5-Cầu xe; 6-Bánh xe chủ động; 7-Trục truyền; 8-Gối đỡ trung gian; 9-Hộp phân phối; 10-Trục nối các đăng; 11-Trục nối xuyên tâm.","anchor":"block-1781143572101-i256k443z"},{"id":"s69","kind":"lesson","lesson":"1.2.1","title":"Giới thiệu tổng quát về ô tô · Động cơ","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích đường truyền từ nguồn động lực."},{"id":"s70","kind":"note","lesson":"1.2.1","title":"Phạm vi của nguồn động lực","text":"Đường truyền minh họa trong bài chủ yếu ứng với ô tô sử dụng động cơ đốt trong. Ô tô điện dùng mô-tơ điện và bộ biến đổi công suất; không được suy rộng rằng mọi ô tô đều có ly hợp ma sát và hộp số nhiều cấp."},{"id":"s71","kind":"simulation","lesson":"1.2.1","title":"Đường truyền từ nguồn động lực","text":"1. Động cơ phát mô men quay. Động cơ là nguồn động lực của ô tô. 2. Mô men đi vào hệ thống truyền lực. Các bộ phận truyền lực đưa mô men tới bánh xe chủ động. 3. Bánh xe chủ động nhận mô men. Tác động giữa bánh xe và mặt đường tạo điều kiện cho xe chuyển động. 4. Thiết bị phụ nhận dẫn động. Động cơ còn dẫn động máy phát điện, máy nén khí và thiết bị khác theo bài."},{"id":"s72","kind":"figure","lesson":"1.2.1","title":"Nguồn động lực trên ô tô — sơ đồ học tập biên soạn từ bài 1.2.1","text":"A. Động cơ xăng. Một trong hai loại động cơ đốt trong thông dụng được nêu trong bài. B. Động cơ Diesel. Một loại nguồn động lực đốt trong được nêu trong bài. C. Động cơ điện. Được đề cập như một xu hướng nguồn động lực ô tô. D. Máy phát điện. Có thể được dẫn động bởi động cơ ô tô.","figure":{"image":"tuong_tac/diagrams/powerplant.svg","caption":"Nguồn động lực trên ô tô — sơ đồ học tập biên soạn từ bài 1.2.1"}},{"id":"s73","kind":"part","lesson":"1.2.1","title":"Động cơ xăng","text":"Một trong hai loại động cơ đốt trong thông dụng được nêu trong bài.","keywords":["Động cơ xăng"],"figure":{"image":"tuong_tac/diagrams/powerplant.svg","caption":"Nguồn động lực trên ô tô — sơ đồ học tập biên soạn từ bài 1.2.1"}},{"id":"s74","kind":"part","lesson":"1.2.1","title":"Động cơ Diesel","text":"Một loại nguồn động lực đốt trong được nêu trong bài.","keywords":["Động cơ Diesel"],"figure":{"image":"tuong_tac/diagrams/powerplant.svg","caption":"Nguồn động lực trên ô tô — sơ đồ học tập biên soạn từ bài 1.2.1"}},{"id":"s75","kind":"part","lesson":"1.2.1","title":"Động cơ điện","text":"Được đề cập như một xu hướng nguồn động lực ô tô.","keywords":["Động cơ điện"],"figure":{"image":"tuong_tac/diagrams/powerplant.svg","caption":"Nguồn động lực trên ô tô — sơ đồ học tập biên soạn từ bài 1.2.1"}},{"id":"s76","kind":"part","lesson":"1.2.1","title":"Máy phát điện","text":"Có thể được dẫn động bởi động cơ ô tô.","keywords":["Máy phát điện"],"figure":{"image":"tuong_tac/diagrams/powerplant.svg","caption":"Nguồn động lực trên ô tô — sơ đồ học tập biên soạn từ bài 1.2.1"}},{"id":"s77","kind":"figure","lesson":"1.2.1","title":"Hình 1.32. Động cơ ô tô.","text":"Hình 1.32. Động cơ ô tô.","anchor":"block-1781143684121-gzmtzujgy","figure":{"number":"1.32","caption":"Hình 1.32. Động cơ ô tô."}},{"id":"s78","kind":"html","lesson":"1.2.1","title":"Giới thiệu tổng quát về ô tô · Động cơ","text":"Động cơ là trái tim của ô tô, là nguồn động lực phát ra năng lượng để ô tô hoạt động. Chức năng cơ bản của động cơ: Cung cấp mô men quay cho các bánh xe chủ động để xe chuyển động. Dẫn động máy phát điện, máy nén khí, động cơ thủy lực và một số thiết bị cơ khí khác trên xe. Động cơ sử dụng thường là động cơ đốt trong, trong đó thông dụng là động cơ xăng và động cơ Diesel. Tuy nhiên, điểm yếu của hai loại động cơ là vấn đề ô nhiễm môi trường do khí thải của chúng gây ra. Ngày nay, với sự phát triển của khoa học, động cơ ô tô có xu hướng sử dụng động cơ điện, động Điều này khắc phục nhược điểm của động cơ đốt trong tạo ra là tạo ra khí thải ô nhiễm môi trường, gây ồn.","anchor":"block-1781143684121-gzmtzujgy"},{"id":"s79","kind":"lesson","lesson":"1.2.2","title":"Giới thiệu tổng quát về ô tô · Hệ thống truyền lực","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Hệ thống truyền lực."},{"id":"s80","kind":"simulation","lesson":"1.2.2","title":"Nguyên lý: Hệ thống truyền lực","text":"1. Động cơ phát mô men. Mô men từ động cơ đi tới ly hợp. 2. Ly hợp nối với hộp số. Ly hợp đóng để truyền mô men; hộp số biến đổi mô men và tốc độ. 3. Các đăng truyền tới cầu xe. Theo sơ đồ bố trí, trục các đăng nối các cụm truyền lực. 4. Bánh xe chủ động nhận mô men. Cầu xe phân phối mô men tới bánh xe chủ động."},{"id":"s81","kind":"figure","lesson":"1.2.2","title":"Hình 1.33 — Hệ thống truyền động của ô tô","text":"A. Hộp số. Biến đổi mô men quay và tốc độ quay để phù hợp điều kiện chuyển động. B. Trục các đăng. Truyền mô men giữa các cụm có đường tâm không nằm trên một đường thẳng. C. Cầu xe. Nhận mô men từ hệ thống truyền lực để dẫn động bánh xe chủ động. D. Ly hợp. Nối hoặc ngắt mô men truyền từ động cơ tới hộp số.","figure":{"image":"content/resources/T1_image51.jpg","caption":"Hình 1.33 — Hệ thống truyền động của ô tô","number":"1.33"}},{"id":"s82","kind":"part","lesson":"1.2.2","title":"Hộp số","text":"Biến đổi mô men quay và tốc độ quay để phù hợp điều kiện chuyển động.","keywords":["Hộp số"],"figure":{"image":"content/resources/T1_image51.jpg","caption":"Hình 1.33 — Hệ thống truyền động của ô tô","number":"1.33"}},{"id":"s83","kind":"part","lesson":"1.2.2","title":"Trục các đăng","text":"Truyền mô men giữa các cụm có đường tâm không nằm trên một đường thẳng.","keywords":["Trục các đăng"],"figure":{"image":"content/resources/T1_image51.jpg","caption":"Hình 1.33 — Hệ thống truyền động của ô tô","number":"1.33"}},{"id":"s84","kind":"part","lesson":"1.2.2","title":"Cầu xe","text":"Nhận mô men từ hệ thống truyền lực để dẫn động bánh xe chủ động.","keywords":["Cầu xe"],"figure":{"image":"content/resources/T1_image51.jpg","caption":"Hình 1.33 — Hệ thống truyền động của ô tô","number":"1.33"}},{"id":"s85","kind":"part","lesson":"1.2.2","title":"Ly hợp","text":"Nối hoặc ngắt mô men truyền từ động cơ tới hộp số.","keywords":["Ly hợp"],"figure":{"image":"content/resources/T1_image51.jpg","caption":"Hình 1.33 — Hệ thống truyền động của ô tô","number":"1.33"}},{"id":"s86","kind":"figure","lesson":"1.2.2","title":"Hình 1.33. Hệ thống truyền động của ô tô.","text":"Hình 1.33. Hệ thống truyền động của ô tô.","anchor":"block-1781143707264-s4bd425jv","figure":{"number":"1.33","caption":"Hình 1.33. Hệ thống truyền động của ô tô."}},{"id":"s87","kind":"html","lesson":"1.2.2","title":"Giới thiệu tổng quát về ô tô · Hệ thống truyền lực","text":"Hệ thống truyền lực bao gồm tất cả các bộ phận nối từ động cơ tới bánh xe chủ động. Là hệ thống tạo ra lực kéo (lực đẩy) cho ô tô hoạt động. Hệ thống truyền lực có các chức năng sau: Để truyền lực, mô men do động cơ sinh ra đến bánh xe chủ động. Biến đổi mô men quay và tốc độ quay của động cơ để đảm bảo sự phù hợp giữa chế độ làm việc của động cơ và mô men cản chuyển động của ô tô. Đổi chiều chuyển động của các bánh xe chủ động để thực hiện chuyển động lùi. Hệ thống truyền lực được cấu thành từ các bộ phận cơ bản sau: Ly hợp, Hộp số, các đăng, cầu xe.","anchor":"block-1781143707264-s4bd425jv"},{"id":"s88","kind":"lesson","lesson":"1.2.3","title":"Giới thiệu tổng quát về ô tô · Hệ thống lái","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Hệ thống lái."},{"id":"s89","kind":"simulation","lesson":"1.2.3","title":"Nguyên lý: Hệ thống lái","text":"1. Người lái quay vành tay lái. Thao tác điều khiển đưa chuyển động vào hệ thống lái. 2. Trục lái truyền chuyển động. Trục lái nối vành tay lái với cơ cấu lái. 3. Cơ cấu lái tác động dẫn động lái. Lực và chuyển động được truyền tới các thanh dẫn động. 4. Bánh xe dẫn hướng đổi góc. Bánh xe dẫn hướng quay theo yêu cầu để thay đổi hướng chuyển động."},{"id":"s90","kind":"figure","lesson":"1.2.3","title":"Hình 9.9 — Bố trí chung của hệ thống lái","text":"A. Vành tay lái. Nhận lực và chuyển động điều khiển của người lái. B. Trục lái. Nối vành tay lái với cơ cấu lái. C. Dẫn động lái. Truyền tác động của cơ cấu lái tới bánh xe dẫn hướng. D. Cơ cấu lái. Biến đổi lực và chuyển động từ trục lái.","figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s91","kind":"part","lesson":"1.2.3","title":"Vành tay lái","text":"Nhận lực và chuyển động điều khiển của người lái.","keywords":["Vành tay lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s92","kind":"part","lesson":"1.2.3","title":"Trục lái","text":"Nối vành tay lái với cơ cấu lái.","keywords":["Trục lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s93","kind":"part","lesson":"1.2.3","title":"Dẫn động lái","text":"Truyền tác động của cơ cấu lái tới bánh xe dẫn hướng.","keywords":["Dẫn động lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s94","kind":"part","lesson":"1.2.3","title":"Cơ cấu lái","text":"Biến đổi lực và chuyển động từ trục lái.","keywords":["Cơ cấu lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s95","kind":"figure","lesson":"1.2.3","title":"Hình 1.34. Hệ thống lái","text":"Hình 1.34. Hệ thống lái","anchor":"block-1781143748795-ohporekhu","figure":{"number":"1.34","caption":"Hình 1.34. Hệ thống lái"}},{"id":"s96","kind":"html","lesson":"1.2.3","title":"Giới thiệu tổng quát về ô tô · Hệ thống lái","text":"Hệ thống lái là hệ thống giúp người điều khiển ô tô chuyển hướng theo ý muốn của người điều khiển bằng cách tác động làm quay bánh xe phía trước đi một góc nhất định.","anchor":"block-1781143748795-ohporekhu"},{"id":"s97","kind":"lesson","lesson":"1.2.4","title":"Giới thiệu tổng quát về ô tô · Hệ thống phanh","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Hệ thống phanh."},{"id":"s98","kind":"simulation","lesson":"1.2.4","title":"Nguyên lý: Hệ thống phanh","text":"1. Người lái yêu cầu giảm tốc. Lực điều khiển được đưa vào dẫn động phanh. 2. Dẫn động tác động cơ cấu phanh. Dẫn động truyền tác động tới cơ cấu phanh bánh xe. 3. Cơ cấu phanh tạo mô men cản. Tiếp xúc ma sát tại cơ cấu phanh chống lại sự quay của bánh xe. 4. Xe giảm tốc hoặc được giữ đứng yên. Công dụng hệ thống còn bao gồm giữ xe khi đỗ theo thiết kế."},{"id":"s99","kind":"figure","lesson":"1.2.4","title":"Hình 10.2 — Cơ cấu phanh tang trống","text":"A. Mâm phanh. Giá cố định để lắp các chi tiết của cơ cấu phanh. B. Guốc phanh. Mang má phanh áp sát mặt trong trống phanh khi phanh. C. Trống phanh. Phần quay cùng bánh xe, tiếp xúc với má phanh. D. Cam phanh. Đẩy guốc phanh ra theo sơ đồ dẫn động bằng cam. E. Lò xo hồi vị. Kéo guốc phanh về sau khi thôi tác động phanh.","figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s100","kind":"part","lesson":"1.2.4","title":"Mâm phanh","text":"Giá cố định để lắp các chi tiết của cơ cấu phanh.","keywords":["Mâm phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s101","kind":"part","lesson":"1.2.4","title":"Guốc phanh","text":"Mang má phanh áp sát mặt trong trống phanh khi phanh.","keywords":["Guốc phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s102","kind":"part","lesson":"1.2.4","title":"Trống phanh","text":"Phần quay cùng bánh xe, tiếp xúc với má phanh.","keywords":["Trống phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s103","kind":"part","lesson":"1.2.4","title":"Cam phanh","text":"Đẩy guốc phanh ra theo sơ đồ dẫn động bằng cam.","keywords":["Cam phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s104","kind":"part","lesson":"1.2.4","title":"Lò xo hồi vị","text":"Kéo guốc phanh về sau khi thôi tác động phanh.","keywords":["Lò xo hồi vị"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s105","kind":"figure","lesson":"1.2.4","title":"Hình 1.35. Hệ thống phanh","text":"Hình 1.35. Hệ thống phanh","anchor":"block-1781143780813-m742v5m8l","figure":{"number":"1.35","caption":"Hình 1.35. Hệ thống phanh"}},{"id":"s106","kind":"html","lesson":"1.2.4","title":"Giới thiệu tổng quát về ô tô · Hệ thống phanh","text":"Là hệ thống nhằm giảm tốc độ ô tô theo ý muốn của người điều khiển. Duy trì vận tốc ở một giá trị nhất định, đảm bảo xe không chuyển động khi đang đứng trên dốc, hoặc trong lúc đỗ xe. Là hệ thống rất quan trọng ảnh hưởng đến tính năng an toàn của ô tô. Được định kỳ đánh giá, kiểm tra chất lượng sau mỗi đợt bảo dưỡng.","anchor":"block-1781143780813-m742v5m8l"},{"id":"s107","kind":"lesson","lesson":"1.2.5","title":"Giới thiệu tổng quát về ô tô · Khung vỏ","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quan hệ đỡ tải của khung, vỏ."},{"id":"s108","kind":"simulation","lesson":"1.2.5","title":"Quan hệ đỡ tải của khung, vỏ","text":"1. Các cụm tạo tải trọng lên khung. Khung, vỏ là nơi giá đỡ các cụm và hệ thống trên ô tô. 2. Khung, vỏ tiếp nhận tải trọng. Kết cấu chịu lực đỡ và định vị các cụm lắp trên xe. 3. Tải được truyền qua hệ thống treo. Liên kết với hệ thống treo đưa tải xuống cầu và bánh xe. 4. Bánh xe truyền tải xuống mặt đường. Khung, vỏ đồng thời tạo không gian bảo vệ người trên xe."},{"id":"s109","kind":"figure","lesson":"1.2.5","title":"Hình 12.6 — Cấu tạo một số khung xe tải","text":"A. Dầm dọc. Thành phần chịu lực chính chạy theo chiều dài khung. B. Dầm ngang. Liên kết hai dầm dọc và gia cường độ cứng vững. C. Giá đỡ. Tạo vị trí lắp và định vị các cụm tổng thành.","figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s110","kind":"part","lesson":"1.2.5","title":"Dầm dọc","text":"Thành phần chịu lực chính chạy theo chiều dài khung.","keywords":["Dầm dọc"],"figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s111","kind":"part","lesson":"1.2.5","title":"Dầm ngang","text":"Liên kết hai dầm dọc và gia cường độ cứng vững.","keywords":["Dầm ngang"],"figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s112","kind":"part","lesson":"1.2.5","title":"Giá đỡ","text":"Tạo vị trí lắp và định vị các cụm tổng thành.","keywords":["Giá đỡ"],"figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s113","kind":"figure","lesson":"1.2.5","title":"Hình 1.36. Khung, vỏ ô tô","text":"Hình 1.36. Khung, vỏ ô tô","anchor":"block-1781143805651-dmv7lpi1b","figure":{"number":"1.36","caption":"Hình 1.36. Khung, vỏ ô tô"}},{"id":"s114","kind":"html","lesson":"1.2.5","title":"Giới thiệu tổng quát về ô tô · Khung vỏ","text":"Là nơi giá đỡ cho các cụm chi tiết, hệ thống của ô tô. Đối với các xe du lịch, xe khách thì khung vỏ là cụm chi tiết đảm bảo sự an toàn cho con người trong ô tô.","anchor":"block-1781143805651-dmv7lpi1b"},{"id":"s115","kind":"lesson","lesson":"1.2.6","title":"Giới thiệu tổng quát về ô tô · Hệ thống treo","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Hệ thống treo."},{"id":"s116","kind":"simulation","lesson":"1.2.6","title":"Nguyên lý: Hệ thống treo","text":"1. Bánh xe gặp mấp mô. Bánh xe chịu kích động từ mặt đường. 2. Bộ phận đàn hồi biến dạng. Liên kết mềm giữa bánh xe và khung vỏ giúp giảm chấn động. 3. Giảm chấn dập dao động. Giảm chấn phối hợp phần tử đàn hồi để dao động giảm nhanh. 4. Khung, vỏ được đỡ êm dịu. Hệ thống treo đỡ khối lượng khung vỏ và các bộ phận trên đó."},{"id":"s117","kind":"figure","lesson":"1.2.6","title":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","text":"A. Lò xo xoắn. Đàn hồi theo hành trình biến dạng, đỡ tải trọng thẳng đứng. B. Giảm chấn. Tiêu tán năng lượng dao động thành nhiệt. C. Đòn trên. Tham gia cơ cấu dẫn hướng bánh xe. D. Đòn dưới. Tham gia truyền lực và xác định quỹ đạo bánh xe.","figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s118","kind":"part","lesson":"1.2.6","title":"Lò xo xoắn","text":"Đàn hồi theo hành trình biến dạng, đỡ tải trọng thẳng đứng.","keywords":["Lò xo xoắn"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s119","kind":"part","lesson":"1.2.6","title":"Giảm chấn","text":"Tiêu tán năng lượng dao động thành nhiệt.","keywords":["Giảm chấn"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s120","kind":"part","lesson":"1.2.6","title":"Đòn trên","text":"Tham gia cơ cấu dẫn hướng bánh xe.","keywords":["Đòn trên"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s121","kind":"part","lesson":"1.2.6","title":"Đòn dưới","text":"Tham gia truyền lực và xác định quỹ đạo bánh xe.","keywords":["Đòn dưới"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s122","kind":"figure","lesson":"1.2.6","title":"Hình 1.37. Hệ thống treo","text":"Hình 1.37. Hệ thống treo","anchor":"block-1781143827088-zkbmudcfw","figure":{"number":"1.37","caption":"Hình 1.37. Hệ thống treo"}},{"id":"s123","kind":"figure","lesson":"1.2.6","title":"Hình 1.38. Lốp xe (vận hành)","text":"Hình 1.38. Lốp xe (vận hành)","anchor":"block-1781143827088-zkbmudcfw","figure":{"number":"1.38","caption":"Hình 1.38. Lốp xe (vận hành)"}},{"id":"s124","kind":"html","lesson":"1.2.6","title":"Giới thiệu tổng quát về ô tô · Hệ thống treo","text":"Hệ thống treo có chức năng là giá đỡ toàn bộ khối lượng của khung – vỏ xe và các bộ phận được lắp đặt trên đó, nó có vai trò như khớp nối mềm liên kết các bánh xe với khung vỏ xe. Là hệ thống đảm bảo độ êm dịu chuyển động cho ô tô. Là bộ phận tiếp xúc trực tiếp với mặt đường chịu nhiều lực tác động, đồng thời cũng là bộ phận góp phần đảm bảo độ êm dịu chuyển động của ô tô.","anchor":"block-1781143827088-zkbmudcfw"},{"id":"s125","kind":"lesson","lesson":"1.2.7","title":"Giới thiệu tổng quát về ô tô · Hệ thống điện","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quan hệ khởi động và cung cấp điện."},{"id":"s126","kind":"simulation","lesson":"1.2.7","title":"Quan hệ khởi động và cung cấp điện","text":"1. Accu cấp điện cho khởi động. Hệ thống khởi động gồm accu, máy khởi động và các relay. 2. Máy khởi động nhận điện. Relay điều khiển và bảo vệ tham gia mạch; máy khởi động đưa tác động quay tới động cơ. 3. Động cơ dẫn động máy phát. Khi động cơ làm việc, máy phát được dẫn động cơ khí. 4. Bộ tiết chế điều chỉnh nạp. Hệ thống cung cấp điện có accu, máy phát và bộ tiết chế."},{"id":"s127","kind":"figure","lesson":"1.2.7","title":"Các hệ thống điện ô tô — sơ đồ học tập biên soạn từ bài 1.2.7","text":"A. Hệ thống khởi động. Cung cấp tác động khởi động với các relay điều khiển và bảo vệ. B. Hệ thống cung cấp điện. Cung cấp điện và điều chỉnh chế độ nạp. C. Hệ thống đánh lửa. Tạo tác động đánh lửa theo mạch được nêu trong bài. D. Hệ thống chiếu ánh sáng và tín hiệu. Phục vụ chiếu sáng và phát tín hiệu của xe.","figure":{"image":"tuong_tac/diagrams/electric.svg","caption":"Các hệ thống điện ô tô — sơ đồ học tập biên soạn từ bài 1.2.7"}},{"id":"s128","kind":"part","lesson":"1.2.7","title":"Hệ thống khởi động","text":"Cung cấp tác động khởi động với các relay điều khiển và bảo vệ.","keywords":["Hệ thống khởi động"],"figure":{"image":"tuong_tac/diagrams/electric.svg","caption":"Các hệ thống điện ô tô — sơ đồ học tập biên soạn từ bài 1.2.7"}},{"id":"s129","kind":"part","lesson":"1.2.7","title":"Hệ thống cung cấp điện","text":"Cung cấp điện và điều chỉnh chế độ nạp.","keywords":["Hệ thống cung cấp điện"],"figure":{"image":"tuong_tac/diagrams/electric.svg","caption":"Các hệ thống điện ô tô — sơ đồ học tập biên soạn từ bài 1.2.7"}},{"id":"s130","kind":"part","lesson":"1.2.7","title":"Hệ thống đánh lửa","text":"Tạo tác động đánh lửa theo mạch được nêu trong bài.","keywords":["Hệ thống đánh lửa"],"figure":{"image":"tuong_tac/diagrams/electric.svg","caption":"Các hệ thống điện ô tô — sơ đồ học tập biên soạn từ bài 1.2.7"}},{"id":"s131","kind":"part","lesson":"1.2.7","title":"Hệ thống chiếu ánh sáng và tín hiệu","text":"Phục vụ chiếu sáng và phát tín hiệu của xe.","keywords":["Hệ thống chiếu ánh sáng và tín hiệu"],"figure":{"image":"tuong_tac/diagrams/electric.svg","caption":"Các hệ thống điện ô tô — sơ đồ học tập biên soạn từ bài 1.2.7"}},{"id":"s132","kind":"figure","lesson":"1.2.7","title":"Hình 1.39. Hệ thống điện ô tô","text":"Hình 1.39. Hệ thống điện ô tô","anchor":"block-1781143864536-buz0a6k4m","figure":{"number":"1.39","caption":"Hình 1.39. Hệ thống điện ô tô"}},{"id":"s133","kind":"html","lesson":"1.2.7","title":"Giới thiệu tổng quát về ô tô · Hệ thống điện","text":"Ôtô hiện nay được trang bị nhiều chủng loại thiết bị điện và điện tử khác nhau. Từng nhóm các thiết bị điện có cấu tạo và tính năng riêng, phục vụ một số mục đích nhất định, tạo thành những hệ thống điện riêng biệt trong mạch điện của ôtô. Hệ thống khởi động (starting system):Bao gồm accu, máy khởi động điện (starting motor), các relay điều khiển và relay bảo vệ khởi động. Đối với động cơ diesel có trang bị thêm hệ thống xông máy (glow system). Hệ thống cung cấp điện (charging system):gồm accu, máy phát điện(alternators), bộ tiết chế điện (voltage regulator), các relay và đèn báo nạp. Hệ thống đánh lửa (Ignition system):Bao gồm các bộ phận chính: accu, khóađiện (ignition switch), bộ chia điện (distributor), biến áp đánh lửa hay bobine(ignition coils), hộp điều khiển đánh lửa (igniter), bougie (spark plugs).","anchor":"block-1781143864536-buz0a6k4m"},{"id":"s134","kind":"html","lesson":"1.2.7","title":"Giới thiệu tổng quát về ô tô · Hệ thống điện","text":"Hệ thống chiếu ánhsáng và tín hiệu (lighting and signal system):gồm các đènchiếu sáng, các đèn tín hiệu, còi, các công tắc và các relay. Hệ thống đo đạc và kiểm tra (gauging system):chủ yếu là các đồng hồ báo trên tableau và các đèn báo gồm có: đồng hồ tốc độ động cơ (tachometer), đồng hồ đo tốc độ xe (speedometer), đồng hồ đo nhiên liệu và nhiệt độ nước. Hệ thống điều khiển động cơ (engine control system):gồm hệ thống điều khiểnxăng, lửa, góc phối cam, ga tự động (cruise control). Ngoài ra, trên các động cơ diesel ngày nay thường sử dụng hệ thống điều khiển nhiên liệu bằng điện tử (EDC – electronic diesel control hoặc common rail injection) Hệ thống điều khiển ôtô:baogồmhệ thống điều khiển phanh chống hãm ABS(antilock brake system), hộp số tự động, tay lái, gối hơi (SRS), lực kéo (tractioncontrol).","anchor":"block-1781143864536-buz0a6k4m"},{"id":"s135","kind":"html","lesson":"1.2.7","title":"Giới thiệu tổng quát về ô tô · Hệ thống điện","text":"Hệ thống điều hòa nhiệt độ (air conditioning system):bao gồm máy nén(compressor), giàn nóng (condenser), lọc ga (dryer), van tiết lưu (expansionvalve), giàn lạnh (evaporator) và các chi tiết điều khiển như relay, thermostat,hộp điều khiển, công tắc A/C… Hệ thống gạt nước, xịt nước (wiper and washer system). Hệ thống điều khiển cửa (door lock control system). Hệ thống điều khiển kính (power window system). Hệ thống điều khiển kính chiếu hậu (mirror control). Hệ thống định vị (navigation system)…","anchor":"block-1781143864536-buz0a6k4m"},{"id":"s136","kind":"lesson","lesson":"1.3.1","title":"Giới thiệu tổng quát về ô tô · Thông số về hình học, kiểu dáng xe, khung vỏ","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự nhận biết thông số hình học."},{"id":"s137","kind":"simulation","lesson":"1.3.1","title":"Trình tự nhận biết thông số hình học","text":"1. Chọn tâm bánh trước và sau. Xác định hai tâm cầu để xét chiều dài cơ sở. 2. Chọn tâm lốp trái và phải. Quan sát cùng một cầu để xét chiều rộng cơ sở. 3. Chọn điểm thấp nhất của gầm. Đo khoảng cách từ điểm này tới mặt đất để có khoảng sáng gầm. 4. Đánh lái hết cỡ để xét vòng quay. Xét bán kính từ tâm quay tới bánh ngoài cùng theo tài liệu."},{"id":"s138","kind":"figure","lesson":"1.3.1","title":"Thông số hình học cơ bản — sơ đồ học tập biên soạn từ bài 1.3.1","text":"A. Chiều dài cơ sở. Khoảng cách từ tâm bánh xe trước đến tâm bánh xe sau; xe nhiều cầu lấy hai cầu xa nhất. B. Chiều rộng cơ sở. Khoảng cách từ tâm lốp bên trái đến tâm lốp bên phải. C. Khoảng sáng gầm. Khoảng cách từ mặt đất đến điểm thấp nhất của gầm xe. D. Bán kính quay vòng tối thiểu. Được xác định khi đánh lái hết cỡ, đo tới bánh xe ngoài cùng theo bài.","figure":{"image":"tuong_tac/diagrams/dimensions.svg","caption":"Thông số hình học cơ bản — sơ đồ học tập biên soạn từ bài 1.3.1"}},{"id":"s139","kind":"part","lesson":"1.3.1","title":"Chiều dài cơ sở","text":"Khoảng cách từ tâm bánh xe trước đến tâm bánh xe sau; xe nhiều cầu lấy hai cầu xa nhất.","keywords":["Chiều dài cơ sở"],"figure":{"image":"tuong_tac/diagrams/dimensions.svg","caption":"Thông số hình học cơ bản — sơ đồ học tập biên soạn từ bài 1.3.1"}},{"id":"s140","kind":"part","lesson":"1.3.1","title":"Chiều rộng cơ sở","text":"Khoảng cách từ tâm lốp bên trái đến tâm lốp bên phải.","keywords":["Chiều rộng cơ sở"],"figure":{"image":"tuong_tac/diagrams/dimensions.svg","caption":"Thông số hình học cơ bản — sơ đồ học tập biên soạn từ bài 1.3.1"}},{"id":"s141","kind":"part","lesson":"1.3.1","title":"Khoảng sáng gầm","text":"Khoảng cách từ mặt đất đến điểm thấp nhất của gầm xe.","keywords":["Khoảng sáng gầm"],"figure":{"image":"tuong_tac/diagrams/dimensions.svg","caption":"Thông số hình học cơ bản — sơ đồ học tập biên soạn từ bài 1.3.1"}},{"id":"s142","kind":"part","lesson":"1.3.1","title":"Bán kính quay vòng tối thiểu","text":"Được xác định khi đánh lái hết cỡ, đo tới bánh xe ngoài cùng theo bài.","keywords":["Bán kính quay vòng tối thiểu"],"figure":{"image":"tuong_tac/diagrams/dimensions.svg","caption":"Thông số hình học cơ bản — sơ đồ học tập biên soạn từ bài 1.3.1"}},{"id":"s143","kind":"html","lesson":"1.3.1","title":"Thông số về hình học, kiểu dáng xe, khung vỏ · Chiều rộng cơ sở","text":"Chiều rộng cơ sở được tính bằng khoảng cách từ tâm lốp bên trái đến tâm lốp bên phải. Chiều rộng cơ sở càng lớn thì độ ổn định của ô tô càng cao và xe dễ điều khiển hơn. Nhưng khi chiều rộng cơ sở lớn sẽ ảnh hưởng khả năng di chuyển ở những con đường hẹp và chật chội.","anchor":"block-1781143917782-gfzfjnin2"},{"id":"s144","kind":"figure","lesson":"1.3.1","title":"Hình 1.40. Thông số kích thước cơ bản của ô tô.","text":"Hình 1.40. Thông số kích thước cơ bản của ô tô.","anchor":"block-1781143939605-ekawsk1ry","figure":{"number":"1.40","caption":"Hình 1.40. Thông số kích thước cơ bản của ô tô."}},{"id":"s145","kind":"html","lesson":"1.3.1","title":"Thông số về hình học, kiểu dáng xe, khung vỏ · Chiều dài cơ sở","text":"Chiều dài cơ sở là khoảng cách từ tâm bánh xe trước đến tâm bánh xe sau. Đối với xe nhiều cầu, chiều dài cơ sở là khoảng cách giữa 2 đường tâm của 2 cầu xa nhất. Chiều dài cơ sở càng lớn thì xe càng ổn định khi di chuyển cũng như tăng không gian bên trong tạo cảm giác thỏa mái hơn. Chiều dài cơ sở càng lớn thì khoang hành khách càng rộng rãi.","anchor":"block-1781143939605-ekawsk1ry"},{"id":"s146","kind":"html","lesson":"1.3.1","title":"Thông số về hình học, kiểu dáng xe, khung vỏ · Bán kính quay vòng tối thiểu","text":"Bán kính quay vòng tối thiểu được tạo bằng cách cho xe quay vòng đánh lái hết cỡ và được tính từ tâm vòng quay đến bánh xe ngoài cùng. Bán kính quay vòng tối thiểu càng nhỏ thì càng tốt, càng dễ dàng di chuyển trong những con đường nhỏ hẹp.","anchor":"block-1781144007811-nzy0jwtyh"},{"id":"s147","kind":"html","lesson":"1.3.1","title":"Thông số về hình học, kiểu dáng xe, khung vỏ · Khoảng sáng gầm xe","text":"Khoảng sáng gầm là khoảng cách từ mặt đất đến điểm thấp nhất của gầm xe. Khoảng sáng gầm cho người xem biết về xe phù hợp với kiểu đường nào, khả năng lội nước, khả năng vượt chướng ngại vật..","anchor":"block-1781144031059-hctgol76z"},{"id":"s148","kind":"lesson","lesson":"1.3.2","title":"Giới thiệu tổng quát về ô tô · Thông số về kết cấu","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự đọc nhóm thông số kết cấu."},{"id":"s149","kind":"simulation","lesson":"1.3.2","title":"Trình tự đọc nhóm thông số kết cấu","text":"1. Đọc nhóm thông số động cơ. Xác định dung tích xi lanh trong bảng thông số. 2. Đọc công suất được công bố. Ghi nhận công suất theo đơn vị trong tài liệu. 3. Đọc mô men xoắn. Phân biệt mô men xoắn với công suất, không dùng thay tên cho nhau. 4. Đọc dạng dẫn động. Đối chiếu FWD, RWD, 4WD hoặc AWD trong nhóm hệ thống truyền lực."},{"id":"s150","kind":"figure","lesson":"1.3.2","title":"Thông số kết cấu ô tô — sơ đồ học tập biên soạn từ bài 1.3.2","text":"A. Dung tích xi lanh. Thể tích xi lanh quét bởi pit-tông từ điểm chết trên đến điểm chết dưới. B. Công suất. Thông số biểu đạt sức mạnh của động cơ theo bảng thông số trong bài. C. Mô men xoắn. Thông số tác động quay gắn với khả năng chịu tải theo bài học. D. Hệ thống truyền lực. Nhóm thông số mô tả dạng dẫn động của xe.","figure":{"image":"tuong_tac/diagrams/parameters.svg","caption":"Thông số kết cấu ô tô — sơ đồ học tập biên soạn từ bài 1.3.2"}},{"id":"s151","kind":"part","lesson":"1.3.2","title":"Dung tích xi lanh","text":"Thể tích xi lanh quét bởi pit-tông từ điểm chết trên đến điểm chết dưới.","keywords":["Dung tích xi lanh"],"figure":{"image":"tuong_tac/diagrams/parameters.svg","caption":"Thông số kết cấu ô tô — sơ đồ học tập biên soạn từ bài 1.3.2"}},{"id":"s152","kind":"part","lesson":"1.3.2","title":"Công suất","text":"Thông số biểu đạt sức mạnh của động cơ theo bảng thông số trong bài.","keywords":["Công suất"],"figure":{"image":"tuong_tac/diagrams/parameters.svg","caption":"Thông số kết cấu ô tô — sơ đồ học tập biên soạn từ bài 1.3.2"}},{"id":"s153","kind":"part","lesson":"1.3.2","title":"Mô men xoắn","text":"Thông số tác động quay gắn với khả năng chịu tải theo bài học.","keywords":["Mô men xoắn"],"figure":{"image":"tuong_tac/diagrams/parameters.svg","caption":"Thông số kết cấu ô tô — sơ đồ học tập biên soạn từ bài 1.3.2"}},{"id":"s154","kind":"part","lesson":"1.3.2","title":"Hệ thống truyền lực","text":"Nhóm thông số mô tả dạng dẫn động của xe.","keywords":["Hệ thống truyền lực"],"figure":{"image":"tuong_tac/diagrams/parameters.svg","caption":"Thông số kết cấu ô tô — sơ đồ học tập biên soạn từ bài 1.3.2"}},{"id":"s155","kind":"html","lesson":"1.3.2","title":"Thông số về kết cấu · Công suất động cơ","text":"Dung tích xi lanh được biết đến như số “chấm” của ô tô (1.0, 1.5, 2.0 …) là phần thể tích xi lanh quét bởi pit-tông khi đi từ điểm chết trên đến điểm chết dưới của động cơ. Công suất và mô men xoắn là đơn vị biểu đạt sức mạnh của xe ô tô. Công suất càng cao thì sức mạnh của động cơ, của xe càng lớn. Mô men xoắn càng cao thì khả năng chịu tải càng lớn, xe mạnh mẽ, tăng tốc nhanh.","anchor":"block-1781144106794-w9akszinn"},{"id":"s156","kind":"html","lesson":"1.3.2","title":"Thông số về kết cấu · Kiểu bố trí động cơ","text":"Đây là hệ thống trong xe kết nối hộp số hoặc hộp số với trục truyền động và được chia thành ba loại chính: Dẫn động bánh trước (FWD), Dẫn động bánh sau (RWD), Dẫn động bốn bánh (4×4 / 4WD / AWD). Bảng 1.1.","anchor":"block-1781144129628-iv6426kuv"},{"id":"s157","kind":"html","lesson":"1.3.2","title":"Thông số về kết cấu · Kiểu bố trí động cơ","text":"Bảng tóm tắt các thông số cơ bản của ô tô tải, ô tô buýt, xe chuyên dùng và ô tô du lịch Ký hiệu, chữ viết tắt | Đơn vị | Giải thích Typ ô tô | | Kiểu ô tô do nhà sản xuất ký hiệu Loại | | Sử dụng cho ô tô buýt Bus: xe chở người trong thành phố Bus: xe chở người trong thành phố Kiểu động cơ | | do nhà sản xuất ký hiệu Bố trí | | Động cơ chữ I hoặc V; số lượng xi lanh OHV, OHC, DOHC: Kiểu bố trí trục cam Động cơ chữ I hoặc V; số lượng xi lanh OHV, OHC, DOHC: Kiểu bố trí trục cam Nemax/ne | Kw/v/p | Công suất lớn nhất / ở số vòng quay(Kw/ vòng / phút) Memax/ne | Nm | Mô men xoắn lớn nhất / ở số vòng quay (Nm/vòng/phút) V | dm3 (lít) | Thể tích công tác của động cơ NL | | Loại nhiên liệu: Động cơ xăng, Diesel hoặc Điện hoặc Hybrid ( Động cơ đốt trong + Động cơ điện) DxRxC | mm | Kích thước bao ngoài: Dài x rộng x Cao Số lượng người | | Số lượng người cho phép","anchor":"block-1781144129628-iv6426kuv"},{"id":"s158","kind":"html","lesson":"1.3.2","title":"Thông số về kết cấu · Kiểu bố trí động cơ","text":"Tổng số chỗ (chỗ ngồi + đứng + lái xe) Tổng số chỗ (chỗ ngồi + đứng + lái xe) Rqvmin | m | Bán kính quay vòng nhỏ nhất Kiểu hộp số | | MT: hộp số cơ khí AT: Hộp số tự động DCT hoặc DSG: hộp số ly hợp kép Kiểu truyền lực | | Dùng cho xe du lịch AWD: dẫn động toàn thời gian 4WD: dẫn động 4 bánh (gián đoạn hoặc toàn thời gian FF: động cơ đặt trước, dẫn động cầu trước FR: động cơ đặt trước, dẫn động cầu sau 4WD: dẫn động 4 bánh (gián đoạn hoặc toàn thời gian FF: động cơ đặt trước, dẫn động cầu trước FR: động cơ đặt trước, dẫn động cầu sau Công thức bánh xe AxB | | Tổng số bánh xe x số bánh xe chủ động (bánh kép thì coi là 1 bánh xe) Tổng số bánh xe x số bánh xe chủ động Kích thước lốp | | Theo tiêu chuẩn quốc tê1 Vmax | km/h | Vận tốc lớn nhất của ô tô Dung tích bình nhiên liệu | lít | Các hệ thống an toàn và ổn định | | ABS: chống bó cứng bánh xe EBD: phân phối","anchor":"block-1781144129628-iv6426kuv"},{"id":"s159","kind":"html","lesson":"1.3.2","title":"Thông số về kết cấu · Kiểu bố trí động cơ","text":"lực phanh điện tử BA: hỗ trợ phanh khẩn cấp TRC: kiểm soát lực kéo ESP: cân bằng điện tử TEMS: hệ thống treo điều khiển điện tử EBD: phân phối lực phanh điện tử TEMS: hệ thống treo điều khiển điện tử","anchor":"block-1781144129628-iv6426kuv"},{"id":"s160","kind":"lesson","lesson":"2.1.1","title":"Ly hợp · Chức năng","text":"Giải thích lúc nào cần nối và ngắt mômen. Liên hệ các bộ phận với chức năng truyền mômen và khởi hành êm."},{"id":"s161","kind":"simulation","lesson":"2.1.1","title":"Đóng → ngắt → đóng lại: ly hợp ma sát thường đóng","text":"1. Đóng ly hợp. Bàn đạp được nhả. Lò xo ép kẹp đĩa ma sát giữa bánh đà và đĩa ép; mômen truyền tới trục sơ cấp. 2. Bắt đầu đạp bàn đạp. Dẫn động đưa ổ bi bạc mở tới đầu trong lò xo màng. Lực ép bắt đầu thay đổi. 3. Ngắt hoàn toàn. Đĩa ép tách khỏi đĩa ma sát, đường truyền mômen bị ngắt. Trục bị động vẫn có thể quay do quán tính. 4. Nhả bàn đạp từ từ. Lực tác động lên bạc mở giảm; lò xo ép đưa đĩa ép trở lại. Các bề mặt có thể trượt trong giai đoạn tiếp nối. 5. Đóng trở lại. Các bề mặt được ép chặt; đường truyền mômen được thiết lập trở lại."},{"id":"s162","kind":"figure","lesson":"2.1.1","title":"Hình 2.1 — Ly hợp ma sát lò xo màng","text":"A. Bánh đà. Gắn với trục khuỷu; tạo một bề mặt ma sát và truyền mômen từ động cơ vào bộ ly hợp. B. Đĩa ép. Ép đĩa ma sát vào bánh đà khi ly hợp đóng; dịch ra để giải phóng lực ép khi ngắt. C. Lò xo màng. Tạo lực ép và làm việc như đòn bẩy khi ổ bi bạc mở tác động vào đầu trong. D. Đĩa ma sát. Nhận mômen qua các bề mặt ma sát rồi truyền tới moayơ và trục sơ cấp hộp số. E. Ổ bi bạc mở. Tiếp nhận tác động của càng mở và truyền lực tới đầu trong lò xo màng. F. Đòn bẩy. Truyền chuyển động của dẫn động điều khiển đến ổ bi bạc mở.","figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s163","kind":"part","lesson":"2.1.1","title":"Bánh đà","text":"Gắn với trục khuỷu; tạo một bề mặt ma sát và truyền mômen từ động cơ vào bộ ly hợp.","keywords":["Bánh đà"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s164","kind":"part","lesson":"2.1.1","title":"Đĩa ép","text":"Ép đĩa ma sát vào bánh đà khi ly hợp đóng; dịch ra để giải phóng lực ép khi ngắt.","keywords":["Đĩa ép"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s165","kind":"part","lesson":"2.1.1","title":"Lò xo màng","text":"Tạo lực ép và làm việc như đòn bẩy khi ổ bi bạc mở tác động vào đầu trong.","keywords":["Lò xo màng"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s166","kind":"part","lesson":"2.1.1","title":"Đĩa ma sát","text":"Nhận mômen qua các bề mặt ma sát rồi truyền tới moayơ và trục sơ cấp hộp số.","keywords":["Đĩa ma sát","đĩa bị động","đĩa ly hợp"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s167","kind":"part","lesson":"2.1.1","title":"Ổ bi bạc mở","text":"Tiếp nhận tác động của càng mở và truyền lực tới đầu trong lò xo màng.","keywords":["Ổ bi bạc mở","bạc mở","vòng bi bạc mở","ổ bi mở"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s168","kind":"part","lesson":"2.1.1","title":"Đòn bẩy","text":"Truyền chuyển động của dẫn động điều khiển đến ổ bi bạc mở.","keywords":["Đòn bẩy","càng mở","càng ngắt","càng mở ly hợp"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s169","kind":"html","lesson":"2.1.1","title":"Ly hợp · Chức năng","text":"- Truyền momen xoắn động cơ tới hộp số cơ khí: Momen cần thiết cho mọi trạng thái vận hành của ô tô phải được truyền tới hộp số trong toàn bộ phạm vi momen xoắn của động cơ. - Giúp cho ô tô khởi chạy êm ái, không rung giật: Khi khởi chạy, việc thích ứng đột ngột tốc độ quay giữa bánh đà đang quay và trục sơ cấp của hộp số đang đứng yên được thực hiện nhờ có sự trượt bề mặt đĩa ma sát với bề mặt bánh đà và đĩa ép. - Giúp chuyển số nhanh, không bị trở ngại: Để thiết lập sự đồng đều tốc độ giữa trục sơ cấp và thứ cấp của hộp số trong quá trình sang số, cần phải ngắt kết nối ly hợp giữa động cơ và hộp số tay. Dao động xoắn của trục khuỷu gia tăng do sự xuất hiện momen quán tính khối lượng quay của trục khuỷu.","anchor":"block-1781144594907-6nm7vq0to"},{"id":"s170","kind":"html","lesson":"2.1.1","title":"Ly hợp · Chức năng","text":"Bộ phận giảm chấn trong đĩa ly hợp hấp thụ một phần các dao động này để tránh tiếng ồn và sự mài mòn bề mặt đĩa ma sát. - Bảo vệ chống quá tải cho động cơ và các bộ phận của hệ thống truyền động: Khi có sự quá tải, thí dụ khi phanh gấp nhưng không ngắt ly hợp sẽ được ngăn ngừa nhờ sự trượt của ly hợp.","anchor":"block-1781144594907-6nm7vq0to"},{"id":"s171","kind":"lesson","lesson":"2.1.2","title":"Ly hợp · Phân loại","text":"Phân biệt phương pháp truyền mômen với phương pháp dẫn động. Nhận dạng ly hợp ma sát thường đóng dùng lò xo màng."},{"id":"s172","kind":"simulation","lesson":"2.1.2","title":"Đóng → ngắt → đóng lại: ly hợp ma sát thường đóng","text":"1. Đóng ly hợp. Bàn đạp được nhả. Lò xo ép kẹp đĩa ma sát giữa bánh đà và đĩa ép; mômen truyền tới trục sơ cấp. 2. Bắt đầu đạp bàn đạp. Dẫn động đưa ổ bi bạc mở tới đầu trong lò xo màng. Lực ép bắt đầu thay đổi. 3. Ngắt hoàn toàn. Đĩa ép tách khỏi đĩa ma sát, đường truyền mômen bị ngắt. Trục bị động vẫn có thể quay do quán tính. 4. Nhả bàn đạp từ từ. Lực tác động lên bạc mở giảm; lò xo ép đưa đĩa ép trở lại. Các bề mặt có thể trượt trong giai đoạn tiếp nối. 5. Đóng trở lại. Các bề mặt được ép chặt; đường truyền mômen được thiết lập trở lại."},{"id":"s173","kind":"figure","lesson":"2.1.2","title":"Hình 2.1 — Ly hợp ma sát lò xo màng","text":"A. Bánh đà. Gắn với trục khuỷu; tạo một bề mặt ma sát và truyền mômen từ động cơ vào bộ ly hợp. B. Đĩa ép. Ép đĩa ma sát vào bánh đà khi ly hợp đóng; dịch ra để giải phóng lực ép khi ngắt. C. Lò xo màng. Tạo lực ép và làm việc như đòn bẩy khi ổ bi bạc mở tác động vào đầu trong. D. Đĩa ma sát. Nhận mômen qua các bề mặt ma sát rồi truyền tới moayơ và trục sơ cấp hộp số. E. Ổ bi bạc mở. Tiếp nhận tác động của càng mở và truyền lực tới đầu trong lò xo màng. F. Đòn bẩy. Truyền chuyển động của dẫn động điều khiển đến ổ bi bạc mở.","figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s174","kind":"part","lesson":"2.1.2","title":"Bánh đà","text":"Gắn với trục khuỷu; tạo một bề mặt ma sát và truyền mômen từ động cơ vào bộ ly hợp.","keywords":["Bánh đà"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s175","kind":"part","lesson":"2.1.2","title":"Đĩa ép","text":"Ép đĩa ma sát vào bánh đà khi ly hợp đóng; dịch ra để giải phóng lực ép khi ngắt.","keywords":["Đĩa ép"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s176","kind":"part","lesson":"2.1.2","title":"Lò xo màng","text":"Tạo lực ép và làm việc như đòn bẩy khi ổ bi bạc mở tác động vào đầu trong.","keywords":["Lò xo màng"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s177","kind":"part","lesson":"2.1.2","title":"Đĩa ma sát","text":"Nhận mômen qua các bề mặt ma sát rồi truyền tới moayơ và trục sơ cấp hộp số.","keywords":["Đĩa ma sát","đĩa bị động","đĩa ly hợp"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s178","kind":"part","lesson":"2.1.2","title":"Ổ bi bạc mở","text":"Tiếp nhận tác động của càng mở và truyền lực tới đầu trong lò xo màng.","keywords":["Ổ bi bạc mở","bạc mở","vòng bi bạc mở","ổ bi mở"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s179","kind":"part","lesson":"2.1.2","title":"Đòn bẩy","text":"Truyền chuyển động của dẫn động điều khiển đến ổ bi bạc mở.","keywords":["Đòn bẩy","càng mở","càng ngắt","càng mở ly hợp"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s180","kind":"html","lesson":"2.1.2","title":"Phân loại · a. Phân loại theo phương pháp truyền mô men:","text":"- Ly hợp ma sát: Truyền mô men bằng các bề mặt ma sát; - Ly hợp thuỷ lực: Truyền mô men bằng chất lỏng; - Ly hợp nam châm điện: Truyền mô men bằng năng lượng từ trường của nam châm điện; - Ly hợp kết hợp: Thường kết hợp giữa ly hợp thuỷ lực với ly hợp ma sát để tạo ra khả năng nối động lực êm dịu và cắt động lực dứt khoát.","anchor":"block-1781144733065-da9obd1sn"},{"id":"s181","kind":"html","lesson":"2.1.2","title":"Phân loại · b. Phân loại theo hình dạng của chi tiết ma sát:","text":"- Ly hợp loại đĩa: Có thể có một, hai hoặc nhiều đĩa bị động; - Ly hợp hình nón: Đĩa bị động có dạng hình nón; - Ly hợp loại má phanh tang trống.","anchor":"block-1781144767536-fud704d24"},{"id":"s182","kind":"html","lesson":"2.1.2","title":"Phân loại · c. Phân loại theo phương pháp tạo ra lực ép:","text":"- Loại lò xo: Các lò xo có thể bố trí xung quanh hoặc bố trí trung tâm; - Loại nửa ly tâm: Lực ép sinh ra ngoài lực ép của lò xo còn có lực ly tâm của khối lượng phụ; - Loại ly tâm: Lực ép được tạo bởi lò xo còn lực ly tâm dùng để đóng và mở ly hợp.","anchor":"block-1781144850686-hscw00hvt"},{"id":"s183","kind":"html","lesson":"2.1.2","title":"Phân loại · d. Theo kết cấu của cơ cấu ép:","text":"- Ly hợp thường đóng; - Ly hợp thường mở.","anchor":"block-1781144893052-caqgea4nl"},{"id":"s184","kind":"html","lesson":"2.1.2","title":"Phân loại · e. Theo phương pháp dẫn động ly hợp:","text":"+ Ly hợp dẫn động cơ khí trợ lực khí nén; + Ly hợp dẫn động thuỷ lực trợ lực khí nén; + Ly hợp dẫn động thuỷ lực trợ lực chân không. Trong các loại ly hợp trên, hiện nay trên ô tô thường sử dụng loại ly hợp ma sát thường đóng có một hoặc hai đĩa bị động. Ly hợp thuỷ lực cũng đang được áp dụng nhiều trên ô tô, vì nó có ưu điểm cơ bản là giảm được đáng kể tải trọng động và va đập trong hệ thống truyền lực. Tuy nhiên giáo trình chỉ tập trung nghiên cứu tới ly hợp dùng các loại đĩa ma sát.","anchor":"block-1781144918614-rppqvaxnc"},{"id":"s185","kind":"lesson","lesson":"2.2.1","title":"Ly hợp · Ly hợp 1 đĩa ma sát","text":"Chỉ ra bộ phận chủ động, bị động và cơ cấu mở. Giải thích trình tự ngắt ly hợp kiểu ép bằng lò xo màng."},{"id":"s186","kind":"simulation","lesson":"2.2.1","title":"Đóng → ngắt → đóng lại: ly hợp ma sát thường đóng","text":"1. Đóng ly hợp. Bàn đạp được nhả. Lò xo ép kẹp đĩa ma sát giữa bánh đà và đĩa ép; mômen truyền tới trục sơ cấp. 2. Bắt đầu đạp bàn đạp. Dẫn động đưa ổ bi bạc mở tới đầu trong lò xo màng. Lực ép bắt đầu thay đổi. 3. Ngắt hoàn toàn. Đĩa ép tách khỏi đĩa ma sát, đường truyền mômen bị ngắt. Trục bị động vẫn có thể quay do quán tính. 4. Nhả bàn đạp từ từ. Lực tác động lên bạc mở giảm; lò xo ép đưa đĩa ép trở lại. Các bề mặt có thể trượt trong giai đoạn tiếp nối. 5. Đóng trở lại. Các bề mặt được ép chặt; đường truyền mômen được thiết lập trở lại."},{"id":"s187","kind":"figure","lesson":"2.2.1","title":"Hình 2.1 — Ly hợp ma sát lò xo màng","text":"A. Bánh đà. Gắn với trục khuỷu; tạo một bề mặt ma sát và truyền mômen từ động cơ vào bộ ly hợp. B. Đĩa ép. Ép đĩa ma sát vào bánh đà khi ly hợp đóng; dịch ra để giải phóng lực ép khi ngắt. C. Lò xo màng. Tạo lực ép và làm việc như đòn bẩy khi ổ bi bạc mở tác động vào đầu trong. D. Đĩa ma sát. Nhận mômen qua các bề mặt ma sát rồi truyền tới moayơ và trục sơ cấp hộp số. E. Ổ bi bạc mở. Tiếp nhận tác động của càng mở và truyền lực tới đầu trong lò xo màng. F. Đòn bẩy. Truyền chuyển động của dẫn động điều khiển đến ổ bi bạc mở.","figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s188","kind":"part","lesson":"2.2.1","title":"Bánh đà","text":"Gắn với trục khuỷu; tạo một bề mặt ma sát và truyền mômen từ động cơ vào bộ ly hợp.","keywords":["Bánh đà"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s189","kind":"part","lesson":"2.2.1","title":"Đĩa ép","text":"Ép đĩa ma sát vào bánh đà khi ly hợp đóng; dịch ra để giải phóng lực ép khi ngắt.","keywords":["Đĩa ép"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s190","kind":"part","lesson":"2.2.1","title":"Lò xo màng","text":"Tạo lực ép và làm việc như đòn bẩy khi ổ bi bạc mở tác động vào đầu trong.","keywords":["Lò xo màng"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s191","kind":"part","lesson":"2.2.1","title":"Đĩa ma sát","text":"Nhận mômen qua các bề mặt ma sát rồi truyền tới moayơ và trục sơ cấp hộp số.","keywords":["Đĩa ma sát","đĩa bị động","đĩa ly hợp"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s192","kind":"part","lesson":"2.2.1","title":"Ổ bi bạc mở","text":"Tiếp nhận tác động của càng mở và truyền lực tới đầu trong lò xo màng.","keywords":["Ổ bi bạc mở","bạc mở","vòng bi bạc mở","ổ bi mở"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s193","kind":"part","lesson":"2.2.1","title":"Đòn bẩy","text":"Truyền chuyển động của dẫn động điều khiển đến ổ bi bạc mở.","keywords":["Đòn bẩy","càng mở","càng ngắt","càng mở ly hợp"],"figure":{"image":"content/resources/T1_image69.jpg","caption":"Hình 2.1 — Ly hợp ma sát lò xo màng","number":"2.1"}},{"id":"s194","kind":"figure","lesson":"2.2.1","title":"Hình 2.1. Cấu tạo ly hợp ma sát lò xo ép bố trí trung tâm","text":"Hình 2.1. Cấu tạo ly hợp ma sát lò xo ép bố trí trung tâm","anchor":"block-1781145140273-qigcpgrow","figure":{"number":"2.1","caption":"Hình 2.1. Cấu tạo ly hợp ma sát lò xo ép bố trí trung tâm"}},{"id":"s195","kind":"figure","lesson":"2.2.1","title":"Hình 2.2. Sơ đồ cấu tạo ly hợp ma sát lò xo ép bố trí trung tâm tự động hiệu chỉnh đĩa ép (SAC)","text":"Hình 2.2. Sơ đồ cấu tạo ly hợp ma sát lò xo ép bố trí trung tâm tự động hiệu chỉnh đĩa ép (SAC)","anchor":"block-1781145140273-qigcpgrow","figure":{"number":"2.2","caption":"Hình 2.2. Sơ đồ cấu tạo ly hợp ma sát lò xo ép bố trí trung tâm tự động hiệu chỉnh đĩa ép (SAC)"}},{"id":"s196","kind":"figure","lesson":"2.2.1","title":"Hình 2.3. Cấu tạo ly hợp ma sát lò xo ép bố trí xung quanh","text":"Hình 2.3. Cấu tạo ly hợp ma sát lò xo ép bố trí xung quanh","anchor":"block-1781145140273-qigcpgrow","figure":{"number":"2.3","caption":"Hình 2.3. Cấu tạo ly hợp ma sát lò xo ép bố trí xung quanh"}},{"id":"s197","kind":"html","lesson":"2.2.1","title":"Ly hợp · Ly hợp 1 đĩa ma sát","text":"Một bộ ly hợp ma sát có cấu tạo ba phần cơ bản như sau: - Nhóm các chi tiết chủ động gồm: bánh đà động cơ, đĩa ép, vỏ ly hợp, cần tách (với ly hợp lò xo ép bố trí xug quanh), lò xo ép và các lò xo lá. Khi ly hợp ở trạng thái mở hoàn toàn thì các chi tiết thuộc nhóm này sẽ quay cùng tốc độ với bánh đà. - Nhóm các chi tiết bị động bao gồm: Đĩa ma sát, trục ly hợp. Khi ly hợp ngắt hoàn toàn các chi tiêt thuộc nhóm này sẽ đứng yên. - Nhóm các chi tiết thuộc phần dẫn động điều khiển: Ổ bi bạc mở, đòn bẩy và bộ phận dẫn động ( bàn đạp, thanh đòn liên kết, trợ lực ly hợp,…) * Ly hợp ma sát khô một đĩa bị động lò xo ép bố trí trung tâm Sơ đồ cấu tạo được thể hiện trên Hình 2.1 1- Bánh đà; 2- Vỏ ly hợp; 3- Đĩa ép; 4- Vòng tựa; 5- Chốt giữ khoảng cách; 6- Lò xo màng; 7- Đòn bẩy; 8- Ổ bi bạc mở; 9- Lò xo lá; 10- Bề mặt ma sát; 11- Đĩa ma sát; 12- Moay ơ đĩa ma sát.","anchor":"block-1781145140273-qigcpgrow"},{"id":"s198","kind":"html","lesson":"2.2.1","title":"Ly hợp · Ly hợp 1 đĩa ma sát","text":"Lò xo màng (6) được làm bằng thép lò xo, nó hoạt động như đòn bẩy hai đầu với điểm tựa là các vòng (4); vòng tựa ở mỗi phía của lò xo màng được giữ chặt bởi chốt (5) bắt chặt vào nắp ly hợp. Dùng các lò xo lá (9) để nối lò xo màng với đĩa ép ly hợp. Một số kiểu xe gần đây đã áp dụng nắp ly hợp kiểu DST (lật ngược lò xo màng), ở loại nắp ly hợp này, người ta lật ngược các đầu của nắp ly hợp để trực tiếp giữ lò xo ở vị trí thích hợp. Các lò xo lá (9) được lắp theo chiều tiếp tuyến để truyền mônen xoắn từ vỏ ly hợp sang đĩa ép.Khi nối động lực lò xo màng (6) sẽ ép chặt đĩa ép, đĩa bị động và bánh đà liền thành một khối. Mô men xoắn từ bánh đà sang đĩa ma sát và tới hệ thống truyền lực dưới dạng mô men ma sát.","anchor":"block-1781145140273-qigcpgrow"},{"id":"s199","kind":"html","lesson":"2.2.1","title":"Ly hợp · Ly hợp 1 đĩa ma sát","text":"Khi cắt động lực người lái đạp vào bàn đạp ly hợp, qua phần dẫn động làm ổ bi bạc mở (8) dịch chuyển đi vào tác dụng lên đầu trong của lò xo màng, Lò xo màng lúc này đóng vai trò như một đòn bẩy với điểm tựa tại vòng tựa (4) làm cho đầu ngoài cùng với đĩa ép dịch chuyển đi ra. Đĩa ép được lách khỏi đĩa ma sát. Động lực lừ động cơ tới hệ thống truyền lực bị cắt. Trên Hình 2.2 là ly hợp hiệu chỉnh đĩa ép tự động SAC (Self Adjusting Clutch) sẽ tự động hiệu chỉnh đĩa ép khi bố ma sát bị mòn. 1- Vòng hiệu chỉnh; 2- Vỏ ly hợp; 3- Lò xo đĩa cảm biến; 4- Ổ tựa lò xo màng; 5- Vòng hiệu chỉnh; 6- Lò xo nén; 7- Nêm hiệu chỉnh; 8- Lò xo màng; 9- Bánh đà; 10- Đĩa ma sát; 11- Đĩa ép; 12- Lò xo đĩa cảm biến. Một số chi tiết bổ sung thêm là lò xo đĩa cảm biến (3), vòng hiệu chỉnh (1).","anchor":"block-1781145140273-qigcpgrow"},{"id":"s200","kind":"html","lesson":"2.2.1","title":"Ly hợp · Ly hợp 1 đĩa ma sát","text":"Lò xo màng không được tán rivê chặt vào thân ly hợp, mà phải được để tựa quay được trên lò xo đĩa cảm biến và vòng hiệu chỉnh. Khi bề mặt ma sát mòn, đĩa ép dịch về phía bánh đà. Nếu lực giữ tại điểm tựa của lò xo đĩa cảm biến bị vượt quá khi ngắt ly hợp, thì lò xo màng di chuyển về phía bánh đà cho tới khi lực ngắt ly hợp và lực lò xo đĩa cảm biến bằng nhau. Do vậy, nó còn được gọi là ly hợp hiệu chỉnh theo tải trọng (LAC = Load Adjusted Clutch).","anchor":"block-1781145140273-qigcpgrow"},{"id":"s201","kind":"html","lesson":"2.2.1","title":"Ly hợp · Ly hợp 1 đĩa ma sát","text":"Khe hở tạo thành sẽ được cân bằng bời vòng hiệu chỉnh. - Lực ngắt nhỏ hơn so với ly hợp lò xo màng thông thường; - Lực ép không đổi trong suốt quá trình hao mòn của bố ma sát; - Tuổi thọ dài hơn do phạm vi mòn lớn * Ly hợp ma sát khô một đĩa bị động lò xo ép bố trí xung quanh Ly hợp ma sát khô thường đóng, lò xo ép bố trí xung quanh được thể hiện trên Hình 2.3.Việc truyền mô men xoắn được thực hiện nhờ các bề mặt ma sát giữa phần chủ động và bị động. Loại này khác so với ly hợp lò xo màng ở lực ép sinh ra bởi nhiều lò xo ép bố trí xung quanh và có thêm chi tiết cần tách để đóng- mở ly hợp.","anchor":"block-1781145140273-qigcpgrow"},{"id":"s202","kind":"html","lesson":"2.2.1","title":"Ly hợp · Ly hợp 1 đĩa ma sát","text":"Dần động điều khiển đóng, mở ly hợp được thực hiện bởi dẫn động điều khiển bằng thủy lực hoặc có trợ lực 1- Bánh đà; 2- Bề mặt ma sát; 3- Đĩa ma sát; 4- Cần tách; 5- Trục khuỷu; 6- Trục ly hợp; 7- Moaay ơ đĩa ma sát; 8- Lò xo giảm chấn; 9- Lò xo lá; 10- Vỏ ly hợp; 11- Lò xo ép; 12- Ổ bi bạc mở; 13- Bạc dẫn hướng; 14- Lò xo hồi vị; 15- Nắp; 16- Đòn bẩy. Nhìn chung, những ly hợp ma sát khô, thường đóng loại một đĩa có kết cấu đơn giản, ít khi xảy ra hiện tượng dính ly hợp (không ngắt hoàn toàn giữa phần chủ động và bị động của ly hợp), kích thước chiều trục nhỏ so với loại hai đĩa. Tuy nhiên, để có thể truyền được momen lớn thì yêu cầu kích thước hướng kính phải lớn.","anchor":"block-1781145140273-qigcpgrow"},{"id":"s203","kind":"figure","lesson":"2.2.1","title":"Hình 2.4. Bánh đà","text":"Hình 2.4. Bánh đà","anchor":"block-1781145200514-484d8n5yt","figure":{"number":"2.4","caption":"Hình 2.4. Bánh đà"}},{"id":"s204","kind":"figure","lesson":"2.2.1","title":"Hình 2.5. Bánh đà kép","text":"Hình 2.5. Bánh đà kép","anchor":"block-1781145200514-484d8n5yt","figure":{"number":"2.5","caption":"Hình 2.5. Bánh đà kép"}},{"id":"s205","kind":"figure","lesson":"2.2.1","title":"Hình 2.6. Đĩa ma sát","text":"Hình 2.6. Đĩa ma sát","anchor":"block-1781145200514-484d8n5yt","figure":{"number":"2.6","caption":"Hình 2.6. Đĩa ma sát"}},{"id":"s206","kind":"figure","lesson":"2.2.1","title":"Hình 2.7. Sơ đồ cấu tạo của đĩa ép kiểu ly hợp lò xo hình trụ","text":"Hình 2.7. Sơ đồ cấu tạo của đĩa ép kiểu ly hợp lò xo hình trụ","anchor":"block-1781145200514-484d8n5yt","figure":{"number":"2.7","caption":"Hình 2.7. Sơ đồ cấu tạo của đĩa ép kiểu ly hợp lò xo hình trụ"}},{"id":"s207","kind":"figure","lesson":"2.2.1","title":"Hình 2.8. Sơ đồ cấu tạo của đĩa ép kiểu ly hợp lò xo màng","text":"Hình 2.8. Sơ đồ cấu tạo của đĩa ép kiểu ly hợp lò xo màng","anchor":"block-1781145200514-484d8n5yt","figure":{"number":"2.8","caption":"Hình 2.8. Sơ đồ cấu tạo của đĩa ép kiểu ly hợp lò xo màng"}},{"id":"s208","kind":"figure","lesson":"2.2.1","title":"Hình 2.9. Khớp ngắt ly hợp","text":"Hình 2.9. Khớp ngắt ly hợp","anchor":"block-1781145200514-484d8n5yt","figure":{"number":"2.9","caption":"Hình 2.9. Khớp ngắt ly hợp"}},{"id":"s209","kind":"figure","lesson":"2.2.1","title":"Hình 2.10. Sơ đồ cấu tạo các loại cần tách của ly hợp","text":"Hình 2.10. Sơ đồ cấu tạo các loại cần tách của ly hợp","anchor":"block-1781145200514-484d8n5yt","figure":{"number":"2.10","caption":"Hình 2.10. Sơ đồ cấu tạo các loại cần tách của ly hợp"}},{"id":"s210","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Bánh đà của động cơ Hình 2.4 vừa là chi tiết của động cơ vừa là chi tiết của bộ phận chủ động. Bánh đà bắt chặt với trục khuỷu nhờ các bulông định tâm, trên bề mặt được gia công nhẵn làm bề mặt tựa của ly hợp. Mép ngoài của mặt bánh đà có các lỗ ren để bắt với vỏ ly hợp đồng thời có các chốt định tâm bảo đảm đồng tâm giữa bánh đà và vỏ, bảo đảm khả năng truyền tốt moment. Bánh đà làm bằng gang có khả năng dẫn nhiệt cao, phần lõm phía trong có các lỗ thoát dầu, mỡ, bụi, các lỗ được khoan xiên tạo điều kiện cho dầu mỡ thoát ra ngoài theo lực ly tâm. Trên Hình 2.5 thể hiện đặc điểm cấu tạo của loại bánh đà kép. Bánh đà kép chủ yếu được thiết kế để giảm tiếng ồn và sự dao động, rung lắc trong quá trình hoạt động.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s211","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Bánh đà kép là một loại vật liệu “xốp/đàn hồi” cơ học, trong đó sự rung lắc và độ xóc trong đường truyền lực được loại bỏ bởi 2 khối bánh đà chính (1) và phụ (6) được kết nối với nhau bằng một loạt lò xo (2) có độ cứng/hệ số biến dạng cao. Bất kỳ sự nhấp nhô nào đều được hấp thụ (ít nhất là một phần) bởi các lò xo giữa các khối bánh đà. Vì vậy, có thể coi rằng công dụng của bánh đà kép như một bộ giảm chấn: mỗi bánh đà là một liên kết chắc chắn, nhưng giữa chúng có một lò xo “mềm” làm hạn chế sự rung lắc trong quá trình tăng tốc, chuyển số,… Xét về hoạt động của bánh đà “khi nguồn năng lượng có sẵn ở tốc độ thay đổi nhưng được yêu cầu ở tốc độ đồng đều. Ví dụ: các máy móc điều khiển bằng động cơ đốt trong kiểu pittông, chúng ta hình dung đến chức năng của bộ đồng tốc (governor).","anchor":"block-1781145200514-484d8n5yt"},{"id":"s212","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"1- Bánh đà chính; 2- Lò xo vòng; 3- Mặt bích; 4- Khối lượng con lắc; 5- Con lăn; 6- Bánh đà phụ. Đĩa ma sát Hình 2.6 có chức năng truyền momen xoắn động cơ từ bánh đà sang trục sơ cấp hộp số; giúp cho việc khởi chạy êm dịu, không rung giật; làm giảm các giao động xoắn. Đĩa ma sát bao gồm: Moayơ, các tấm ma sát, các lò xo giảm chấn, lò xo đệm và xương đĩa. Các bề mặt ma sát gắn với lò xương đĩa, khi ly hợp ăn khớp chính nhờ các xương đĩa này mà sự rung động được giảm thấp. Trên cả hai mặt của đĩa ma sát có các rãnh nhằm ngăn không cho đĩa bị dính với bánh đà hoặc đĩa ép khi ly hợp nhả. Các rãnh còn giúp cho việc làm nguội các mặt tiếp xúc và loại bỏ các bột mài màn ra ngoài. 1- Đinh tán; 2,10- Lò xo giảm chấn; 3- Xương đĩa; 4,9- Đinh tán xương đĩa; 5,13- Lò xo đệm; 6,11- Vòng đàn hồi; 7- Chốt chặn; 8,17- Đĩa dẫn động; 12,19- Moay ơ; 18- Bề mặt ma sát.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s213","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Bề mặt đĩa ma sát được làm bằng sợi hữu cơ tổng hợp, thí dụ như sợi aramid, sợi thủy tinh hoặc sợi các bon. Để tăng thêm độ cứng của bề mặt ma sát những sợi đồng được đan hoặc ép thêm vào. Do amiăng là loại vật liệu tác động xấu đến sức khoẻ con người nên dần thay thế bằng vật liệu khác. Hiện nay một số đĩa ma sát dùng bề mặt ma sát bằng vật liệu kim loại hoặc gốm. Bộ phận làm giảm dao động xoắn bao gồm các lò xo giảm chấn (2) và thiết bị ma sát có nhiệm vụ làm giảm sự rung động của động cơ, loại bỏ tiếng ồn của hộp số như tiếng lách cách của hộp số và sự mòn bánh răng nhờ đó công suất truyền đến hộp số được êm dịu hơn. Moayơ (12) thiết kế để có thề xoay được so với đĩa dẫn động. Moayơ tựa vào đĩa dẫn động thông qua những lò xo giảm chấn tỳ trên mặt bích của moayơ. Khi chịu tải, moayơ có thề xoay có giới hạn so với phần xương đĩa (3) mang bề mặt ma sát.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s214","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Momen được truyền bởi các lò xo giảm chấn phải lớn hơn momen cực đại cùa động cơ để ngăn mặt bích moayơ va đập vào các chốt chặn (7). Thiết bị ma sát được bố trí trong moayơ, bao gồm các vòng đàn hồi (6) và lò xo đệm (5). Khi hiện tượng xoắn xảy ra, thiết bị ma sát làm giảm các dao động xoắn nhờ ma sát. Lực ép dọc trục cần thiết để tạo ma sát được tạo ra bởi lò xo đệm. Bộ phận đàn hồi cho bề ma sát là các phân khúc đàn hồi được bố trí giữa hai bề mặt ma sát. Chúng được làm từ tấm thép lò xo gợn sóng để hình thành lên xương đĩa (3), giúp các bề ma sát kết nối êm dịu khi đóng ly hợp và không rung giật khi khởi chạy. Đĩa ma sát có hành trình dịch chuyển khoảng 1,5mm khi ly hợp thay đổi từ trạng thái ăn khớp đến không ăn khớp. Đĩa ép ly hợp được làm bằng vật liệu chịu tải, đảm bảo độ phẳng cao, được điều khiển để đóng hoặc mở ly hợp.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s215","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Đĩa ép, với một hoặc nhiều lò xo gắn với vỏ ly hợp. Vỏ ly hợp được gắn với bánh đà bằng các bulông và cùng quay với nó. Khi ly hợp ở trạng thái đóng, lực ép sinh ra từ lò xo đẩy đĩa ép tiếp xúc với đĩa ma sát và bánh đà. Đĩa ép gồm hai loại: Loại sử dụng lò xo trụ và lò xo màng. - Loại sử dụng lò xo trụ: Được thể hiện trên Hình 2.7 Loại này sử dụng những lò xo trụ nhỏ giống như lò xo xupáp. Bề mặt đĩa ép (3) là một vòng tròn lớn mà đĩa ma sát tiếp xúc vào, thường được chế tạo bằng gang hoặc thép. Bề mặt của đĩa ép có các vấu để định vị các lò xo; ngoài ra còn có kết cấu để liên kết với cần tách được gắn với vỏ ly hợp. Trong suốt quá trình hoạt động của ly hợp, đĩa ép di chuyển về phía trước và bên trong vỏ ly hợp. Cần tách được lắp bên trong đĩa ép, nó được nâng lên và dịch chuyển bề mặt đĩa ép ra xa so với bánh đà.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s216","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Các lò xo hình trụ nằm xung quanh đĩa ép và xen giữa những cần tách để giữ chúng từ vị trí tự do về vị trí làm việc. Lực giữ trong cụm đĩa ép được tạo ra bởi một số lò xo xoắn hình trụ, các lò xo được bố trí vòng tròn trên đĩa ép nằm giữa đĩa ép và vỏ ly hợp. Khi nhấn bàn đạp ly hợp, đẩy ổ bi bạc mở vào cần tách, đĩa ép tách khỏi đĩa ma sát và nén các lò xo ép tỳ vào vỏ ly hợp, ly hợp khi đó ở trạng thái ngắt. Nhả bàn đạp ly hợp thì lò xo xoắn giãn ra đẩy đĩa ép vào tiếp xúc với bánh đà. Ly hợp ở trạng thái đóng. Lò xo phải đủ cứng để giữ cho ly hợp không bị trượt. Tuy nhiên nếu lò xo quá cứng thì sẽ ảnh hưởng tới tuổi thọ làm việc của bộ ly hợp 1- Trục bị động; 2- Đĩa ma sát; 3- Đĩa ép; 4- Vỏ ly hợp; 5- Đai ốc hiệu chỉnh; 6- Đòn bẩy; 7- Ống lót; 8- Lò xo ép. - Với loại sử dụng lò xo màng: Được thể hiện trên Hình 2.8. Thường sử dụng những lò xo lá đơn.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s217","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Chức năng giống như chức năng của kiểu lò xo trụ. Lò xo lá là một lò xoắn vòng tròn lớn, được uốn cong lên hoặc lõm xuống và được chia thành những viên phân theo hướng kính của lò xo. Đầu phía ngoài lò xo màng được gắn vào đĩa ép bằng chốt, một vòng tựa được gắn phía sau lò xo màng có nhiệm vụ định vị cạnh ngoài của lò xo. 1- Lò xo màng; 2- Đĩa ép; 3- Ổ bi đỡ phía trong; 4- Ổ bi đỡ phía ngoài; 5- Trục bị động; 6- Ổ bi bạc mở; 7- Đai ốc điều chỉnh. Lò xo ép kiểu màng hoạt động khi ổ bi bạc mở tác dụng đẩy đầu trong của nó thì đầu phía ngoài di chuyển ngược lại. Điều này sẽ tách đĩa ma sát khỏi đĩa ép và bánh đà. Khi không có tác dụng lên bàn đạp thì lò xo màng tạo lực ép đẩy đĩa ma sát vào tiếp xúc với bánh đà.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s218","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"1- Đầu trong của lò xo màng; 2- Vòng ngoài ổ bi; 3- Vòng trong ổ bi; 4- Ống dẫn hướng; 5- Đòn bẩy; 6- Ổ bi bạc mở; 7- Trục bị động ly hợp (Trục sơ cấp hộp số). Cơ cấu đóng-ngắt ly hợp Error! Reference source not found. có nhiệm vụ điều khiển lò xo màng hoặc cần tách. Cơ cấu đóng-ngắt ly hợp dạng cơ khí được dẫn hướng trung tâm. Nó được dẫn trên ống dẫn hướng được gắn trên trục hộp số và đồng tâm với trục sơ cấp của hộp sổ. Ổ bi của cơ cấu là ổ bi cầu bịt kín với vòng ngoài (2) cố định và vòng trong (3) xoay được. Khi ở trạng thái ngắt ly hợp thì vòng trong tỳ trực tiếp không có khe hở vào đầu trong của lò xo màng hoặc đầu các cần tách. Khớp ngắt ly hợp có tác dụng làm giảm ma sát giữa cần đẩy và càng mở ly hợp, tránh được sự mài mòn.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s219","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Khớp ngắt ly hợp là một bộ phận kín trong đó chứa mỡ bôi trơn, nó trượt trên trục hoặc trong ống bao lồng bên ngoài trục từ phía trước của hộp số. Ở một vài loại xe đặc biệt có sử dụng khớp ngắt ly hợp bằng than chì. Nó là một khối tròn bằng than chì chống ma sát ép lên trên đĩa phẳng và đẩy cần đẩy ly hợp. Khớp ngắt ly hợp thường được tách rời với đòn bẩy (5). Một vòng hãm nhỏ để giữ khớp ngắt trên càng mở, khi đó sự chuyển động ở hướng khác sẽ đẩy khớp ngắt chạy dài trên trục hộp số, lúc này khớp ngắt sẽ không còn hoạt động trong suốt quá trình động cơ truyền công suất. Nó sẽ giảm bớt sự mài mòn và hư hỏng của khớp ngắt ly hợp. Ly hợp và hộp số là hai cụm được bố trí liền nhau, vì vậy trục bị động của ly hợp đồng thời là trục chủ động của hộp số Error! Reference source not found..","anchor":"block-1781145200514-484d8n5yt"},{"id":"s220","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Trục bị động (5) được đặt đồng tâm với trục khuỷu của động cơ nhờ hai ổ bi: Một ổ bi phía trong (3) đặt tại lỗ tâm trục khuỷu (hốc bánh đà) và ổ bi phía ngoài (4) còn lại đặt tại vỏ hộp số. Ổ bi có nhiệm vụ đỡ trục sơ cấp hộp số và giúp cho trục sơ cấp nằm giữa đĩa ma sát với bánh đà. Đầu cuối của trục sơ cấp có một ngỗng trục nhỏ ở cuối trục, ngỗng trục này trượt bên trong ổ bi, ổ bi ngăn cản trục hộp số và đĩa ly hợp lắc lên hay lắc xuống khi mà đĩa ma sát tách rời. Các cần tách của ly hợp được bố trí xung quanh đĩa ép của ly hợp sử dụng lò xo ép bố trí xung quanh; có đầu ngoài được lắp với đĩa ép bằng chốt và vòng bi kim, ở giữa tựa trên thân ly hợp Error! Reference source not found.. Số lượng các cần tách tuỳ thuộc vào kích thước của ly hợp nhưng không nhỏ hơn 3. Trên Hình 2.10a, cần tách (2) lắp trên đĩa ép (1) và giá đỡ qua các ổ lăn kim.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s221","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Giá đỡ lắp ghép với thân ly hợp bằng đai ốc (4) có mặt tiếp xúc với thân ly hợp là mặt cầu để gối đỡ để có thể xoay tự do trên thân ly hợp, tránh sự bẻ cong các cần tách khi đóng mở ly hợp. Ở Hình 2.10b, cần tách (2) lắp trên đĩa ép qua ổ bi kim (3), lắp trên quang treo (10) băng chốt tự lựa (8) và con lăn (9). Chốt (8) và con lăn (9) đảm bảo sự xoay tự do của các cần tách trên giá đỡ khi đóng mở ly hợp. 1- Đĩa ép; 2- Cần tách; 3- Ổ bi kim; 4- Bu long treo cần tách; 5- Lò xo; 6- Tấm chặn đầu ổ bi bạc mở; 7- Vỏ ly hợp; 8- Chốt tự lựa; 9- Con lăn 10- Quang treo cần tách. Khi mở ly hợp, ổ bi bạc mở phải tỳ cùng một lúc lên các cần tách, muốn vậy các đầu trong cần tách phải cùng phía nằm trên một mặt phẳng. Điều chỉnh chiều cao đầu trong các cần tách đai ốc (4) lắp cần tách với thân ly hợp, hoặc bằng vít điều chỉnh lắp ở đầu trong của các cần tách.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s222","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · a. Cấu tạo một số chi tiết của ly hợp","text":"Hình dạng của cần tách phải đảm bảo được khả năng chống uốn theo phương chịu lực Vật liệu chế tạo cần tách thường dùng các loại thép cácbon thấp hoặc trung bình như thép C8, C30 sau đó được xyanua hóa bề mặt làm việc. Các lò xo lá liên kết truyền lực với vỏ ly hợp đối với loại một đĩa ma sát và liên kết đĩa ép trung gian với bánh đà ở loại hai đĩa ma sát. Chúng vừa đóng vai trò truyền momen từ vỏ ly hợp và bánh đà đồng thời là cơ cấu chống dính cho ly hợp ở cả loại một đĩa ma sát và hai đĩa ma sát. Vỏ ly hợp được định vị với thân động cơ theo vỏ của bánh đà bằng các chốt định vị và được định vị với vỏ hộp số theo mặt bích của nắp ổ bi trục chủ động hộp số. Hình dạng, kích thước và vị trí các lỗ thông gió của vỏ ly hợp phụ thuộc vào kết cấu của ly hợp. Vỏ ly hợp thường được đúc bằng gang liền một khối hoặc thành hai nửa rồi ghép lại.","anchor":"block-1781145200514-484d8n5yt"},{"id":"s223","kind":"figure","lesson":"2.2.1","title":"Hình 2.11. Sơ đồ ly hợp ma sát sử dụng cơ cấu ép bằng lò xo màng","text":"Hình 2.11. Sơ đồ ly hợp ma sát sử dụng cơ cấu ép bằng lò xo màng","anchor":"block-1781145279406-ffzcwjd3x","figure":{"number":"2.11","caption":"Hình 2.11. Sơ đồ ly hợp ma sát sử dụng cơ cấu ép bằng lò xo màng"}},{"id":"s224","kind":"figure","lesson":"2.2.1","title":"Hình 2.12. Sơ đồ ly hợp ma sát sử dụng cơ cấu ép bằng lò xo trụ","text":"Hình 2.12. Sơ đồ ly hợp ma sát sử dụng cơ cấu ép bằng lò xo trụ","anchor":"block-1781145279406-ffzcwjd3x","figure":{"number":"2.12","caption":"Hình 2.12. Sơ đồ ly hợp ma sát sử dụng cơ cấu ép bằng lò xo trụ"}},{"id":"s225","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · b. Nguyên lý làm việc","text":"Ly hợp ma sát trong hệ thống truyền lực của ô tô là loại ly hợp ma sát khô thường đóng, có một hoặc hai đĩa bị động với lực ép được tạo nên bởi lò xo ép bố trí xung quanh hoặc lò xo ép bố trí trung tâm. Hình 2.11 là sơ đồ nguyên lý làm việc của loại ly hợp một đĩa ma sát sử dụng cơ cấu tạo lực ép là lò xo màng. Trên ô tô thường dùng hai loại ly hợp ngắt bằng cách ép Hình 2.11a và ngắt bằng cách kéo Hình 2.11b. a- Ngắt ly hợp bằng cách ép; b- Ngắt ly hợp bằng cách kéo; 1- Bánh đà; 2- Đĩa ép; 3- Lò xo ép; 4- Đòn bẩy; 5- Vỏ ly hợp; 6- Đĩa ma sát; 7- Ổ bi bạc mở; 8- Trục bị động ly hợp. Lò xo ép sẽ ép chặt đĩa ép, đĩa ma sát và bánh đà liền thành một khối. Kết quà là, lực ma sát được tạo ra giữa đĩa ép, đĩa ma sát và bánh đà. Lực ma sát này sẽ tạo nên momen xoắn truyền qua đĩa ly hợp đến hộp số nhiều cấp. Đĩa ly hợp được kết nối chặt với trục sơ cấp hộp số.","anchor":"block-1781145279406-ffzcwjd3x"},{"id":"s226","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · b. Nguyên lý làm việc","text":"Momen xoắn truyền được phụ thuộc vào: - Hệ số ma sát cùa cặp bề mặt ma sát, - Bán kính trung bình cùa đĩa ma sát. 1- Trục khuỷu; 2- Đĩa ma sát; 3- Đĩa ép; 4- Lò xo ép; 5- Moay ơ ly hợp; 6- Ổ bi bạc mở; 7- Đòn bẩy; 8- Cần tách. - Ngắt bằng cách ép Hình 2.11a: Khi đạp bàn đạp ly hợp, đòn bẩy ly hợp ép ổ bi bạc mở ly hợp về phía bánh đà. Do vậy, các lưỡi gà của lò xo màng cũng bị ép ở vành bên trong về phía bánh đà. Nhờ các vòng tựa giữ chặt đầu ngoài với vỏ ly hợp nên lò xo màng tác dụng như đòn bẩy hai đầu. Vành bên ngoài của lò xo di chuyển tách dòng truyền lực từ bánh đà khỏi bề mặt đĩa ma sát. Bằng cách này, lực ép lên đĩa ép mất đi, và các lò xo lá tách đĩa ép khỏi đĩa ma sát.","anchor":"block-1781145279406-ffzcwjd3x"},{"id":"s227","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · b. Nguyên lý làm việc","text":"Một khe hở được hình thành giữa các bề mặt ma sát và đĩa ép, và dòng truyền lực bị cắt. - Ngắt bằng cách ép Hình 2.11b: Đầu trong của lò xo màng ăn khớp vào rãnh tròn trên ổ bi bạc mở ly hợp và khi tác động lên bàn đạp ly hợp thì bị bộ phận này bị kéo về phía hộp số. Loại này đầu trong lò xo màng không được cố định với vỏ ly hợp nên khi tác dụng lên bàn đạp ly hợp lực ép sẽ được ngắt; kết quả là lò xo lá tách đĩa ép khỏi đĩa ma sát. Lò xo màng tạo ra một cơ cấu đòn bẩy một đầu tạo nên tỷ số đòn bẩy ờ lò xo màng (a:b) lớn hơn so với thiết kế kiểu ép Hình 2.11a. Do vậy lực ngắt ly hợp ở loại này nhỏ hơn. Tại những thời điểm chuyển từ trạng thái đóng sang trạng thái ngắt ly hợp và ngược lại. Khi đó bề mặt đĩa ma sát phía trong tiếp xúc với bề bánh đà và phía ngoài tiếp xúc với đĩa ép sẽ xuất hiện sự trượt do ma sát.","anchor":"block-1781145279406-ffzcwjd3x"},{"id":"s228","kind":"html","lesson":"2.2.1","title":"Ly hợp 1 đĩa ma sát · b. Nguyên lý làm việc","text":"Trạng thái làm việc này cũng chính là chức năng đảm bảo cơ cấu an toàn cho các chi tiết của hệ thống truyền lực khi gặp quá tải. Đới với ly hợp ma sát sử dụng cơ cấu ép bằng lò xo trụ bố trí xung quanh Hình 2.12Nguyên lý làm việc cũng tương tự như loại trên. Chỉ khác ở trạng thái ngắt, ổ bi bạc mở sẽ tác động vào cần tách thay vì đầu trong của lò xo màng. Cần tách đóng vai trò như một đòn bẩy có đầu ngoài liên kết với đĩa ép. Khi các bề mặt ma sát mòn, lực ép lúc đầu gia tăng tới trị số cực đại, sau đó giảm liên tục. Khi vượt quá giới hạn mòn, lực ép suy giám đáng kể và ly hợp có thể bị trượt.","anchor":"block-1781145279406-ffzcwjd3x"},{"id":"s229","kind":"lesson","lesson":"2.2.2","title":"Ly hợp · Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát","text":"Nhận dạng đĩa ép trung gian và các đĩa ma sát. Phân biệt ly hợp lò xo thường đóng với cụm nhiều đĩa đóng bằng áp suất dầu."},{"id":"s230","kind":"note","lesson":"2.2.2","title":"Trạng thái đóng của ly hợp","text":"Phải tách ly hợp ma sát thường đóng bằng lò xo khỏi cụm nhiều đĩa đóng bằng áp suất dầu trong ví dụ. Áp suất có thể dùng để mở hoặc để đóng tùy kết cấu; không suy luận chiều tác động chỉ từ tên “dẫn động thủy lực”."},{"id":"s231","kind":"simulation","lesson":"2.2.2","title":"Ly hợp hai đĩa ma sát thường đóng","text":"1. Cụm hai đĩa được ép chặt. Bánh đà, hai đĩa ma sát, đĩa ép trung gian và đĩa ép ngoài tạo các cặp tiếp xúc truyền mômen. 2. Tác động cơ cấu mở. Ổ bi bạc mở tác động vào cần tách hoặc lò xo màng, làm đĩa ép ngoài dịch ra. 3. Tách các mặt ma sát. Cơ cấu chống dính giúp đĩa ép trung gian tách khỏi các đĩa ma sát. Đường truyền mômen bị ngắt. 4. Đóng lại. Khi thôi tác động cơ cấu mở, lực lò xo kẹp chặt cụm đĩa và mômen được truyền trở lại."},{"id":"s232","kind":"simulation","lesson":"2.2.2","title":"Ly hợp nhiều đĩa đóng bằng áp suất dầu","text":"1. Chưa cấp áp suất tác động. Các đĩa chưa được piston ép chặt; nhánh ly hợp này chưa truyền mômen. 2. Cấp dầu điều khiển. Dầu có áp vào buồng tác động, tạo lực trên piston. 3. Piston ép chồng đĩa. Piston ép các đĩa chủ động và bị động xen kẽ; mômen được truyền qua moayơ. 4. Giảm áp để ngắt. Van điều khiển giảm áp trong buồng tác động; lực ép được giải phóng và đường truyền mômen bị ngắt."},{"id":"s233","kind":"figure","lesson":"2.2.2","title":"Hình 2.13b — Ly hợp hai đĩa ma sát","text":"A. Bánh đà. Bộ phận chủ động gắn với trục khuỷu; tạo mặt ma sát phía trong. B. Đĩa ma sát phía trong. Đĩa bị động phía bánh đà, cùng đĩa phía ngoài truyền mômen tới trục bị động. C. Đĩa ép trung gian. Nằm giữa hai đĩa ma sát và tạo thêm các bề mặt truyền mômen. D. Đĩa ma sát phía ngoài. Đĩa bị động thứ hai, ở phía cụm đĩa ép ngoài. E. Lò xo màng. Tạo lực ép cho cả cụm và đổi trạng thái khi cơ cấu mở tác động.","figure":{"image":"content/resources/T1_image81.jpg","caption":"Hình 2.13b — Ly hợp hai đĩa ma sát","number":"2.13b"}},{"id":"s234","kind":"part","lesson":"2.2.2","title":"Bánh đà","text":"Bộ phận chủ động gắn với trục khuỷu; tạo mặt ma sát phía trong.","keywords":["Bánh đà"],"figure":{"image":"content/resources/T1_image81.jpg","caption":"Hình 2.13b — Ly hợp hai đĩa ma sát","number":"2.13b"}},{"id":"s235","kind":"part","lesson":"2.2.2","title":"Đĩa ma sát phía trong","text":"Đĩa bị động phía bánh đà, cùng đĩa phía ngoài truyền mômen tới trục bị động.","keywords":["Đĩa ma sát phía trong"],"figure":{"image":"content/resources/T1_image81.jpg","caption":"Hình 2.13b — Ly hợp hai đĩa ma sát","number":"2.13b"}},{"id":"s236","kind":"part","lesson":"2.2.2","title":"Đĩa ép trung gian","text":"Nằm giữa hai đĩa ma sát và tạo thêm các bề mặt truyền mômen.","keywords":["Đĩa ép trung gian","đĩa trung gian"],"figure":{"image":"content/resources/T1_image81.jpg","caption":"Hình 2.13b — Ly hợp hai đĩa ma sát","number":"2.13b"}},{"id":"s237","kind":"part","lesson":"2.2.2","title":"Đĩa ma sát phía ngoài","text":"Đĩa bị động thứ hai, ở phía cụm đĩa ép ngoài.","keywords":["Đĩa ma sát phía ngoài"],"figure":{"image":"content/resources/T1_image81.jpg","caption":"Hình 2.13b — Ly hợp hai đĩa ma sát","number":"2.13b"}},{"id":"s238","kind":"part","lesson":"2.2.2","title":"Lò xo màng","text":"Tạo lực ép cho cả cụm và đổi trạng thái khi cơ cấu mở tác động.","keywords":["Lò xo màng"],"figure":{"image":"content/resources/T1_image81.jpg","caption":"Hình 2.13b — Ly hợp hai đĩa ma sát","number":"2.13b"}},{"id":"s239","kind":"figure","lesson":"2.2.2","title":"Hình 2.14 — Ly hợp nhiều đĩa","text":"A. Đĩa ma sát. Các đĩa bị động ăn khớp với moayơ, xen kẽ với các đĩa chủ động. B. Vỏ ly hợp. Mang các rãnh liên kết với các đĩa chủ động. C. Piston. Dịch chuyển dưới áp suất dầu để ép chặt chồng đĩa. D. Đường dầu áp suất. Dẫn dầu có áp vào buồng tác động lên piston. E. Trục sơ cấp hộp số. Nhận mômen từ cụm đĩa qua moayơ. F. Đĩa ép. Các đĩa chủ động xen kẽ với đĩa ma sát để tạo nhiều cặp tiếp xúc.","figure":{"image":"content/resources/T1_image82.jpg","caption":"Hình 2.14 — Ly hợp nhiều đĩa","number":"2.14"}},{"id":"s240","kind":"part","lesson":"2.2.2","title":"Đĩa ma sát","text":"Các đĩa bị động ăn khớp với moayơ, xen kẽ với các đĩa chủ động.","keywords":["Đĩa ma sát","đĩa bị động"],"figure":{"image":"content/resources/T1_image82.jpg","caption":"Hình 2.14 — Ly hợp nhiều đĩa","number":"2.14"}},{"id":"s241","kind":"part","lesson":"2.2.2","title":"Vỏ ly hợp","text":"Mang các rãnh liên kết với các đĩa chủ động.","keywords":["Vỏ ly hợp"],"figure":{"image":"content/resources/T1_image82.jpg","caption":"Hình 2.14 — Ly hợp nhiều đĩa","number":"2.14"}},{"id":"s242","kind":"part","lesson":"2.2.2","title":"Piston","text":"Dịch chuyển dưới áp suất dầu để ép chặt chồng đĩa.","keywords":["Piston","pít tông","pittông"],"figure":{"image":"content/resources/T1_image82.jpg","caption":"Hình 2.14 — Ly hợp nhiều đĩa","number":"2.14"}},{"id":"s243","kind":"part","lesson":"2.2.2","title":"Đường dầu áp suất","text":"Dẫn dầu có áp vào buồng tác động lên piston.","keywords":["Đường dầu áp suất","đường dầu","áp suất dầu"],"figure":{"image":"content/resources/T1_image82.jpg","caption":"Hình 2.14 — Ly hợp nhiều đĩa","number":"2.14"}},{"id":"s244","kind":"part","lesson":"2.2.2","title":"Trục sơ cấp hộp số","text":"Nhận mômen từ cụm đĩa qua moayơ.","keywords":["Trục sơ cấp hộp số","trục sơ cấp","trục bị động"],"figure":{"image":"content/resources/T1_image82.jpg","caption":"Hình 2.14 — Ly hợp nhiều đĩa","number":"2.14"}},{"id":"s245","kind":"part","lesson":"2.2.2","title":"Đĩa ép","text":"Các đĩa chủ động xen kẽ với đĩa ma sát để tạo nhiều cặp tiếp xúc.","keywords":["Đĩa ép"],"figure":{"image":"content/resources/T1_image82.jpg","caption":"Hình 2.14 — Ly hợp nhiều đĩa","number":"2.14"}},{"id":"s246","kind":"figure","lesson":"2.2.2","title":"Hình 2.13. Cấu tạo ly hợp ma sát hai đĩa bị động","text":"Hình 2.13. Cấu tạo ly hợp ma sát hai đĩa bị động","anchor":"block-1781145432894-7ti43zd0x","figure":{"number":"2.13","caption":"Hình 2.13. Cấu tạo ly hợp ma sát hai đĩa bị động"}},{"id":"s247","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · a. Ly hợp 2 đĩa ma sát","text":"Ly hợp ma sát hai đĩa ma sát Hình 2.13 có thể truyền mô men gấp hai lần ly hợp loại một đĩa ma sát với cùng lực ép và cùng đường kính bề mặt ma sát.","anchor":"block-1781145432894-7ti43zd0x"},{"id":"s248","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · a. Ly hợp 2 đĩa ma sát","text":"Vì vậy, đối với một số ôtô vận tải, khi cần phải truyền mô men lớn người ta sử dụng ly hợp ma sát khô hai đĩa bị động. a- Ly hợp 2 đĩa ma sát loại lò xo trụ bố trí xung quanh; b- Ly hợp 2 đĩa ma sát loại lò xo màng bố trí trung tâm;1- Bánh đà; 2- Đệm; 3- Ống dẫn hướng; 4- Lò xo chống chính; 5- Đĩa ma sát phía trong; 6- Chốt chống dính; 7- Đĩa ép trung gian; 8- Đinh tán; 9- Đĩa ma sát phía ngoài; 10- Đĩa ép ngoài; 11- Cần tách; 12- Quang treo cần tách; 13- Lò xo ép; 14- Vòng đệm; 15- Bulong; 16- Vòng tỳ; 17- Bạc tỳ; 18- Ống dẫn mơ bôi trơn; 19-Lò xo hồi vị ổ bi bạc mở; 20-Ổ bi bạc mở; 21- Trục bị động ly hợp; 22- Trục đòn bẩy; 23- Vỏ ly hợp; 24- Lò xo ép dãy trong; 25- Lò xo ép dãy ngoài; 26- Moay o đĩa ma sát; 27- Lò xo lá truyền lực.","anchor":"block-1781145432894-7ti43zd0x"},{"id":"s249","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · a. Ly hợp 2 đĩa ma sát","text":"So với ly hợp ma sát khô một đĩa bị động, ly hợp ma sát khô hai đĩa bị động có những ưu nhược điểm sau: - Nếu cùng một kích thước đĩa bị động và cùng một lực ép như nhau thì ly hợp hai đĩa truyền được mômen lớn hơn ly hợp một đĩa; - Nếu phải truyền một mômen như nhau thì ly hợp hai đĩa có kích thước nhỏ gọn hơn ly hợp một đĩa; - Ly hợp hai đĩa khi đóng êm dịu hơn nhưng khi mở lại kém dứt khoát hơn ly hợp một đĩa do xuất hiện sự dính bề mặt giữa phần chủ động với phần bị động; - Ly hợp hai đĩa có kết cấu phức tạp hơn ly hợp một đĩa. Nhìn chung cấu tạo của ly hợp hai đĩa cũng bao gồm các bộ phận và các chi tiết cơ bản như đối với ly hợp một đĩa. Điểm khác biệt là ở ly hợp hai đĩa có hai đĩa ma sát 1 và 21 cùng liên kết then hoa với trục bị động ly hợp 22. Vì có hai đĩa ma sát nên ngoài đĩa ép 4 còn có thêm đĩa ép trung gian 2.","anchor":"block-1781145432894-7ti43zd0x"},{"id":"s250","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · a. Ly hợp 2 đĩa ma sát","text":"Ở ly hợp hai đĩa phải bố trí cơ cấu truyền mômen từ thân hoặc bánh đà sang đĩa ép và cả đĩa trung gian. Với nhược điểm của ly hợp hai đĩa bị động là mở không dứt khoát, vì vậy những loại ly hợp này phải bố trí cơ cấu để tạo điều kiện cho ly hợp khi mở được dứt khoát. Như trên Hình 2.13a thì cơ cấu này được thực hiện bởi lò xo 4 và chốt chống dính 6. Khi mở ly hợp, lò xo 2 sẽ đẩy đĩa ép trung gian 7 tách khỏi đĩa ma sát bên trong và hành trình dịch chuyển của đĩa trung gian bị giới hạn do chốt chống dính 6 nên sẽ không tiếp xúc với đĩa ma sát bên ngoài 9. Kết quả là không xảy ra hiện tượng dính ly hợp. Đối với ly hợp sử dụng lò xo ép bố trí trung tâm Hình 2.13b thì sử dụng cơ cấu chống dính bằng lò xo lá truyền lực 27. Trên đĩa ép ngoài thì một đầu lò xo lá 27 được liên kết với đĩa ép và đầu còn lại liên kết với vỏ ly hợp.","anchor":"block-1781145432894-7ti43zd0x"},{"id":"s251","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · a. Ly hợp 2 đĩa ma sát","text":"Đối với đĩa ép trung gian thì một đầu liên kết với đĩa ép và đầu kia liên kết với bánh đà. Khi ngắt ly hợp thì dưới tác dụng đàn hồi của lò xo lá cả hai đĩa ép đều hồi vị về vị trí ban đầu để giải phóng sự tiếp xúc với đĩa ma sát. Lò xo lá vừa có tác dụng chống dính và tạo liên kết truyền momen xoắn từ bánh đà và vỏ ly hợp sang đĩa ép trung gian và đĩa ép ngoài. Nguyên lý làm việc của ly hợp hai đĩa ma sát nhìn chúng cũng tương tự như loại ly hợp một đĩa ma sát. Ở trạng thái này, các lò xo ép 13 một đầu tựa vào vỏ ly hợp 23, đầu kia tì vào đĩa ép ngoài 10 sẽ ép chặt toàn bộ các đĩa ma sát 5, 9 và đĩa ép trung gian 7 với bánh đà tạo thành một khối cứng giữa các chi tiết chủ động và bị động của ly hợp, mômen xoắn được truyền từ động cơ tới bộ phận chủ động, bị động và tới trục bị động ly hợp.","anchor":"block-1781145432894-7ti43zd0x"},{"id":"s252","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · a. Ly hợp 2 đĩa ma sát","text":"Khi ngắt ly hợp, Hình 2.13a người lái tác dụng một lực vào bàn đạp ly hợp tại buồng lái, thông qua trục đòn bẩy 22 đẩy ổ bi bạc mở 20 dịch chuyển sang trái. Khi khe hở giữa vòng tỳ 16 và đầu cần tách 11 được khắc phục thì ổ bi bạc mở tiếp tục ép lên đầu cần tách để kéo đĩa ép ngoài 10 nén lò xo ép 13, làm đĩa ép dịch chuyển sang phải tạo khe hở giữa các đĩa bị động với các đĩa ép, đĩa trung gian và bánh đà. Với sơ đồ như Hình 2.13b ổ bi bạc mở sẽ tác dụng trực tiếp vào đầu phái trong của lò xo màng 13, lò xo màng ngoài nhiệm vụ tạo lực ép còn đóng vai trò như là cần tách. Do đó trục bị động ly hợp được quay tự do ngắt đường truyền mômen từ động cơ tới trục ly hợp. Tương tự như ly hợp loại một đĩa ma sát.Tại những thời điểm trạng thái làm việc.","anchor":"block-1781145432894-7ti43zd0x"},{"id":"s253","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · a. Ly hợp 2 đĩa ma sát","text":"Các bề mặt cảu đĩa ma sát tiếp xúc với bề bánh đà và phía ngoài tiếp xúc với bề mặt đĩa ép trung gian, bánh đà và đĩa ép ngoài sẽ xuất hiện sự trượt do ma sát. Nhờ có sự trượt bề mặt do ma đảm bảo làm cơ cấu an toàn cho các chi tiết của hệ thống truyền lực khi gặp quá tải.","anchor":"block-1781145432894-7ti43zd0x"},{"id":"s254","kind":"figure","lesson":"2.2.2","title":"Hình 2.14. Cấu tạo ly hợp nhiều đĩa ma sát","text":"Hình 2.14. Cấu tạo ly hợp nhiều đĩa ma sát","anchor":"block-1781145482924-l46eqb7mi","figure":{"number":"2.14","caption":"Hình 2.14. Cấu tạo ly hợp nhiều đĩa ma sát"}},{"id":"s255","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · b. Ly hợp nhiều đĩa ma sát","text":"Đặc điểm cấu tạo của ly hợp nhiều đĩa được thể hiện Hình 2.14. Loại ly hợp này được sử dụng trên xe hai bánh, trên ô tô có hộp số tay chuyển số trực tiếp và hộp số tự động. 1-Đĩa ma sát; 2- Vỏ ly hợp; 3- Piston; 4- Áp suất dầu; 5- Trục sơ cấp hộp số; 6- Moay o đĩa ma sát; 7- Đĩa ép. Nhiều đĩa ma sát 1 được bố trí nối tiếp nhau xen kẽ giữa các đĩa ép 7. Trên vỏ ly hợp có các rãnh để ăn khớp với đĩa ép, còn đĩa ma sát ăn khớp với các rãnh của moayơ đĩa ma sát 6. Một xi lanh thủy lực với piston 3 đặt trong moayơ. Đĩa ma sát được nối với trục sơ cấp hộp số thông qua khớp then hoa với moayơ . Khi ngưới lái đạp bàn đạp ly hợp dầu thủy lực có áp suất đi vào xi lanh thông qua một xi lanh chính hoặc các van. Được tác động bởi áp suất dầu, piston ép các đĩa ép và đĩa ma sát với nhau, vì vậy bánh đà, đĩa ma sát, đĩa ép và vỏ ly hợp tạo thành một khối thống nhất.","anchor":"block-1781145482924-l46eqb7mi"},{"id":"s256","kind":"html","lesson":"2.2.2","title":"Ly hợp 2 đĩa ma sát và ly hợp nhiều đĩa ma sát · b. Ly hợp nhiều đĩa ma sát","text":"Momen xoắn được truyền từ động cơ tới bộ phận chủ động, bị động và tới trục bị động ly hợp. Khi đạp bàn đạp ly hợp, áp suất dầu được giảm đi nhờ các van. Không còn lực tác động lên piston, đĩa ép không còn tiếp xúc với đĩa ma sát và dòng truyền lực bị cắt. Tương tự như những loại ly hợp đã trình bày ở trên.","anchor":"block-1781145482924-l46eqb7mi"},{"id":"s257","kind":"lesson","lesson":"2.3.1","title":"Ly hợp · Dẫn động điều khiển bằng cơ khí","text":"Theo dõi đường truyền lực bàn đạp → cáp → cơ cấu mở. Giải thích vai trò của hành trình tự do và hồi vị."},{"id":"s258","kind":"simulation","lesson":"2.3.1","title":"Dẫn động cơ khí: mở và hồi vị","text":"1. Bàn đạp được nhả. Cáp chưa tạo lực mở. Ly hợp thường đóng đang truyền mômen. 2. Đạp bàn đạp. Lực chân làm bàn đạp quay và kéo cáp. 3. Cáp kéo cơ cấu mở. Cáp và đòn liên kết đưa ổ bi bạc mở tới lò xo màng hoặc cần tách. 4. Ly hợp ngắt. Cơ cấu tách giải phóng lực ép. Đường truyền mômen sang hộp số bị ngắt. 5. Thôi tác động bàn đạp. Lò xo hồi vị và lò xo ép đưa các cơ cấu trở lại; ly hợp đóng."},{"id":"s259","kind":"figure","lesson":"2.3.1","title":"Hình 2.15 — Dẫn động điều khiển bằng cơ khí","text":"A. Bàn đạp ly hợp. Nhận lực chân người lái và làm quay đòn dẫn động. B. Cáp kéo. Truyền lực kéo từ bàn đạp tới đòn liên kết của cơ cấu mở. C. Đòn liên kết. Truyền chuyển động tới cơ cấu mở và ổ bi bạc mở. D. Ổ bi bạc mở. Trượt trên bạc dẫn hướng và tác động vào cơ cấu tách. E. Lò xo hồi vị bàn đạp. Đưa bàn đạp trở về vị trí ban đầu khi người lái thôi tác động.","figure":{"image":"content/resources/T1_image83.jpeg","caption":"Hình 2.15 — Dẫn động điều khiển bằng cơ khí","number":"2.15"}},{"id":"s260","kind":"part","lesson":"2.3.1","title":"Bàn đạp ly hợp","text":"Nhận lực chân người lái và làm quay đòn dẫn động.","keywords":["Bàn đạp ly hợp","bàn đạp"],"figure":{"image":"content/resources/T1_image83.jpeg","caption":"Hình 2.15 — Dẫn động điều khiển bằng cơ khí","number":"2.15"}},{"id":"s261","kind":"part","lesson":"2.3.1","title":"Cáp kéo","text":"Truyền lực kéo từ bàn đạp tới đòn liên kết của cơ cấu mở.","keywords":["Cáp kéo"],"figure":{"image":"content/resources/T1_image83.jpeg","caption":"Hình 2.15 — Dẫn động điều khiển bằng cơ khí","number":"2.15"}},{"id":"s262","kind":"part","lesson":"2.3.1","title":"Đòn liên kết","text":"Truyền chuyển động tới cơ cấu mở và ổ bi bạc mở.","keywords":["Đòn liên kết","đòn bẩy","càng mở"],"figure":{"image":"content/resources/T1_image83.jpeg","caption":"Hình 2.15 — Dẫn động điều khiển bằng cơ khí","number":"2.15"}},{"id":"s263","kind":"part","lesson":"2.3.1","title":"Ổ bi bạc mở","text":"Trượt trên bạc dẫn hướng và tác động vào cơ cấu tách.","keywords":["Ổ bi bạc mở","bạc mở","vòng bi bạc mở"],"figure":{"image":"content/resources/T1_image83.jpeg","caption":"Hình 2.15 — Dẫn động điều khiển bằng cơ khí","number":"2.15"}},{"id":"s264","kind":"part","lesson":"2.3.1","title":"Lò xo hồi vị bàn đạp","text":"Đưa bàn đạp trở về vị trí ban đầu khi người lái thôi tác động.","keywords":["Lò xo hồi vị bàn đạp","lò xo hồi vị"],"figure":{"image":"content/resources/T1_image83.jpeg","caption":"Hình 2.15 — Dẫn động điều khiển bằng cơ khí","number":"2.15"}},{"id":"s265","kind":"figure","lesson":"2.3.1","title":"Hình 2.15. Dẫn động điều khiển ly hợp bằng cơ khí","text":"Hình 2.15. Dẫn động điều khiển ly hợp bằng cơ khí","anchor":"block-1781145574622-kmyaum5fw","figure":{"number":"2.15","caption":"Hình 2.15. Dẫn động điều khiển ly hợp bằng cơ khí"}},{"id":"s266","kind":"html","lesson":"2.3.1","title":"Dẫn động điều khiển bằng cơ khí · a. Đặc điểm cấu tạo","text":"Căn cứ vào bố trí chung của ô tô loại dẫn động ly hợp bằng cơ khí Hình 2.15, bao gồm một số chi tiết cơ bản như sau: Bàn đạp ly hợp, cần kéo hoặc cáp kéo, đòn bẩy (càng mở), cần tách và lò xo hồi vị được lắp đặt với nhau dựa trên nguyên lý đòn bẩy. Trong cơ cấu điều khiển ly hợp giữa ổ bi bạc mở và đầu trong lò xo màng hoặc cần tách luôn phải có khe hở khi ly hợp ở trạng thái đóng hoàn toàn, để ly hợp có thể làm việc tốt khi các bề mặt ma sát bị mòn, thông thường khe hở vào khoảng 1-3mm và khe hở ở bàn đạp ly hợp từ 10 mm đến 30 mm.Trong quá trình làm việc giá trị khe hở này giảm dần và được xác định bằng hành trình tự do của bàn đạp ly hợp. Trong quá trình sử dụng hành trình tự do của bàn đạp ly hợp cần được điều chỉnh trong phạm vi cho phép, nếu hành trình tự do quá lớn sẽ làm cho ly hợp cắt động lực không dứt khoát, khi quá nhỏ sẽ làm cho ly hợp bị trượt.","anchor":"block-1781145574622-kmyaum5fw"},{"id":"s267","kind":"html","lesson":"2.3.1","title":"Dẫn động điều khiển bằng cơ khí · a. Đặc điểm cấu tạo","text":"1-Ống dẫn cáp; 2,22- Đầu ống; 3- Đai ốc; 4- Tấm gá; 5- Vòng đệm; 6- Ống xoay; 7- Đầu chụp; 8- Khớp nối; 9- Đòn liên kết; 10- Vỏ ly hợp; 11- Bulong; 12- Đĩa ép; 13- Bánh đà; 14- Đĩa ma sát; 15- Trục bị động; 16- Bề mặt gá; 17-Vỏ bảo vệ; 18- Lò xo ép; 19- Bi; 20- Ổ bi bạc mở; 21- Bạc dẫn hướng; 23- Ống tỳ; 24- Đầu cáp; 25- Chốt liên kết; 26- Lò xo hồi vị bàn đạp; 27- Bàn đạp ly hợp. Khi bề mặt ma sát mòn, đĩa ép dịch chuyển về phía bánh đà. Đầu trong của lò xo màng có tác dụng như đòn bẩy hai đầu sẽ di chuyền ra bên ngoài về phía cơ cấu đóng-ngắt ly hợp. Điều nãy làm giảm khe hở ở cơ cấu đóng-ngắt ly hợp và ở bàn đạp. Vì vậy, khe hở phải được hiệu chình kịp thời, bởi vi sự gia tăng độ mòn bề mặt ma sát làm khe hở biến mất hoàn gây ra sự trượt ly hợp trong quá trình làm việc.","anchor":"block-1781145574622-kmyaum5fw"},{"id":"s268","kind":"html","lesson":"2.3.1","title":"Dẫn động điều khiển bằng cơ khí · a. Đặc điểm cấu tạo","text":"Khe hở giữa đầu trong lò xo màng hoặc cần tách với ổ bi bạc mở quá nhỏ sẽ dẫn tới những ảnh hưởng sau: - Ly hợp bị trượt do lực ép của lò xo màng nhỏ; - Bề mặt ma sát ly hợp bị quá nhiệt; - Quá nhiệt tại một số điểm trên bề mặt ma sát của bánh đà. Để khắc phục vấn đề này, khe hở được hiệu chỉnh tại đòn bẩy ly hợp hoặc tại bàn đạp ly hợp. Qua việc vặn một đai ốc hiệu chình, chiều dài hiệu dụng cùa cáp được tăng lên. Cơ cấu đóng-ngắt ly hợp di chuyến xa khỏi lò xo màng hoặc cần tách.","anchor":"block-1781145574622-kmyaum5fw"},{"id":"s269","kind":"html","lesson":"2.3.1","title":"Dẫn động điều khiển bằng cơ khí · b. Nguyên lý làm việc","text":"Các lò xo ép sẽ ép chặt đĩa ép, đĩa bị động và bánh đà liền thành một khối. Mô men xoắn từ phần chủ động được truyền sang phần bị động và tới hệ thống truyền lực dưới dạng mô men ma sát. Người lái đạp vào bàn đạp ly hợp, thông qua phần dẫn động làm vòng bi bạc mở dịch chuyển đi vào tác dụng lên đầu trong lò xo màng hoặc cần tách với loại ly hợp lò xo ép bố trí xung quanh. Đầu ngoài lò xo màng hoặc cần tách cùng với đĩa ép dịch chuyển đi ra. Đĩa ép được tách khỏi đĩa bị động, các lò xo ép bị nén lại.","anchor":"block-1781145627374-wa5bjb06k"},{"id":"s270","kind":"lesson","lesson":"2.3.2","title":"Ly hợp · Dẫn động điều khiển ly hợp bằng thủy lực","text":"Nhận dạng xi lanh chính, xi lanh công tác và đường dầu. Theo dõi quá trình biến lực bàn đạp thành lực mở ly hợp."},{"id":"s271","kind":"simulation","lesson":"2.3.2","title":"Dẫn động thủy lực: đường truyền áp suất","text":"1. Bàn đạp được nhả. Chưa tạo áp suất mở ly hợp. Ly hợp thường đóng đang truyền mômen. 2. Đạp bàn đạp, đẩy piston chính. Lực từ bàn đạp làm piston xi lanh chính dịch chuyển để tạo áp suất. 3. Áp suất truyền trong đường dầu. Áp suất thủy lực truyền qua đường ống tới xi lanh công tác. 4. Xi lanh công tác tác động càng mở. Piston và chốt đẩy đưa càng mở tác động lên bạc mở; lực ép được giải phóng. 5. Nhả bàn đạp, hồi vị. Cơ cấu hồi vị đưa các piston trở về; áp suất mở giảm và ly hợp đóng trở lại."},{"id":"s272","kind":"figure","lesson":"2.3.2","title":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","text":"A. Bàn đạp ly hợp. Truyền lực qua cần đẩy tới piston xi lanh chính. B. Xi lanh chính. Biến lực từ bàn đạp thành áp suất dầu điều khiển. C. Đường ống dẫn dầu. Nối xi lanh chính với xi lanh công tác, truyền áp suất thủy lực. D. Xi lanh công tác. Biến áp suất dầu thành lực trên piston và chốt đẩy. E. Chốt đẩy. Truyền lực từ piston xi lanh công tác tới càng ngắt. F. Vít xả khí. Dùng để xả không khí lẫn trong dẫn động thủy lực khi bảo dưỡng.","figure":{"image":"content/resources/T1_image84.jpg","caption":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","number":"2.16"}},{"id":"s273","kind":"part","lesson":"2.3.2","title":"Bàn đạp ly hợp","text":"Truyền lực qua cần đẩy tới piston xi lanh chính.","keywords":["Bàn đạp ly hợp","bàn đạp"],"figure":{"image":"content/resources/T1_image84.jpg","caption":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","number":"2.16"}},{"id":"s274","kind":"part","lesson":"2.3.2","title":"Xi lanh chính","text":"Biến lực từ bàn đạp thành áp suất dầu điều khiển.","keywords":["Xi lanh chính","xilanh chính"],"figure":{"image":"content/resources/T1_image84.jpg","caption":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","number":"2.16"}},{"id":"s275","kind":"part","lesson":"2.3.2","title":"Đường ống dẫn dầu","text":"Nối xi lanh chính với xi lanh công tác, truyền áp suất thủy lực.","keywords":["Đường ống dẫn dầu","ống dẫn dầu","đường dầu"],"figure":{"image":"content/resources/T1_image84.jpg","caption":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","number":"2.16"}},{"id":"s276","kind":"part","lesson":"2.3.2","title":"Xi lanh công tác","text":"Biến áp suất dầu thành lực trên piston và chốt đẩy.","keywords":["Xi lanh công tác","xi lanh con","xilanh công tác"],"figure":{"image":"content/resources/T1_image84.jpg","caption":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","number":"2.16"}},{"id":"s277","kind":"part","lesson":"2.3.2","title":"Chốt đẩy","text":"Truyền lực từ piston xi lanh công tác tới càng ngắt.","keywords":["Chốt đẩy","cần đẩy"],"figure":{"image":"content/resources/T1_image84.jpg","caption":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","number":"2.16"}},{"id":"s278","kind":"part","lesson":"2.3.2","title":"Vít xả khí","text":"Dùng để xả không khí lẫn trong dẫn động thủy lực khi bảo dưỡng.","keywords":["Vít xả khí"],"figure":{"image":"content/resources/T1_image84.jpg","caption":"Hình 2.16 — Dẫn động điều khiển bằng thủy lực","number":"2.16"}},{"id":"s279","kind":"figure","lesson":"2.3.2","title":"Hình 2.17 — Xi lanh chính","text":"A. Piston. Dịch chuyển theo cần đẩy và làm tăng áp suất trong buồng công tác. B. Cần đẩy piston. Nhận tác động của bàn đạp để đẩy piston. C. Vòng làm kín sơ cấp. Làm kín buồng tạo áp suất ở phía trước piston. D. Đầu nối với xi lanh công tác. Nối đường dầu có áp tới xi lanh công tác.","figure":{"image":"content/resources/T1_image85.jpg","caption":"Hình 2.17 — Xi lanh chính","number":"2.17"}},{"id":"s280","kind":"part","lesson":"2.3.2","title":"Piston","text":"Dịch chuyển theo cần đẩy và làm tăng áp suất trong buồng công tác.","keywords":["Piston","pít tông","pittông"],"figure":{"image":"content/resources/T1_image85.jpg","caption":"Hình 2.17 — Xi lanh chính","number":"2.17"}},{"id":"s281","kind":"part","lesson":"2.3.2","title":"Cần đẩy piston","text":"Nhận tác động của bàn đạp để đẩy piston.","keywords":["Cần đẩy piston","cần đẩy"],"figure":{"image":"content/resources/T1_image85.jpg","caption":"Hình 2.17 — Xi lanh chính","number":"2.17"}},{"id":"s282","kind":"part","lesson":"2.3.2","title":"Vòng làm kín sơ cấp","text":"Làm kín buồng tạo áp suất ở phía trước piston.","keywords":["Vòng làm kín sơ cấp"],"figure":{"image":"content/resources/T1_image85.jpg","caption":"Hình 2.17 — Xi lanh chính","number":"2.17"}},{"id":"s283","kind":"part","lesson":"2.3.2","title":"Đầu nối với xi lanh công tác","text":"Nối đường dầu có áp tới xi lanh công tác.","keywords":["Đầu nối với xi lanh công tác"],"figure":{"image":"content/resources/T1_image85.jpg","caption":"Hình 2.17 — Xi lanh chính","number":"2.17"}},{"id":"s284","kind":"figure","lesson":"2.3.2","title":"Hình 2.18 — Xi lanh công tác","text":"A. Chốt đẩy. Đưa lực của piston tới đòn bẩy ly hợp. B. Piston. Nhận áp suất dầu để tạo chuyển động tịnh tiến. C. Vít xả khí. Mở đường thoát cho không khí khi xả khí hệ thống. D. Đầu nối ống dầu. Nối xi lanh công tác với đường dầu từ xi lanh chính.","figure":{"image":"content/resources/T1_image86.jpg","caption":"Hình 2.18 — Xi lanh công tác","number":"2.18"}},{"id":"s285","kind":"part","lesson":"2.3.2","title":"Chốt đẩy","text":"Đưa lực của piston tới đòn bẩy ly hợp.","keywords":["Chốt đẩy","cần đẩy"],"figure":{"image":"content/resources/T1_image86.jpg","caption":"Hình 2.18 — Xi lanh công tác","number":"2.18"}},{"id":"s286","kind":"part","lesson":"2.3.2","title":"Piston","text":"Nhận áp suất dầu để tạo chuyển động tịnh tiến.","keywords":["Piston","pít tông","pittông"],"figure":{"image":"content/resources/T1_image86.jpg","caption":"Hình 2.18 — Xi lanh công tác","number":"2.18"}},{"id":"s287","kind":"part","lesson":"2.3.2","title":"Vít xả khí","text":"Mở đường thoát cho không khí khi xả khí hệ thống.","keywords":["Vít xả khí"],"figure":{"image":"content/resources/T1_image86.jpg","caption":"Hình 2.18 — Xi lanh công tác","number":"2.18"}},{"id":"s288","kind":"part","lesson":"2.3.2","title":"Đầu nối ống dầu","text":"Nối xi lanh công tác với đường dầu từ xi lanh chính.","keywords":["Đầu nối ống dầu","đầu nối","đầu nối ống dẫn"],"figure":{"image":"content/resources/T1_image86.jpg","caption":"Hình 2.18 — Xi lanh công tác","number":"2.18"}},{"id":"s289","kind":"figure","lesson":"2.3.2","title":"Hình 2.16. Dẫn động điều khiển ly hợp bằng thủy lực","text":"Hình 2.16. Dẫn động điều khiển ly hợp bằng thủy lực","anchor":"block-1781145693690-9sek73off","figure":{"number":"2.16","caption":"Hình 2.16. Dẫn động điều khiển ly hợp bằng thủy lực"}},{"id":"s290","kind":"figure","lesson":"2.3.2","title":"Hình 2.17. Đặc điểm cấu tạo của xi lanh chính","text":"Hình 2.17. Đặc điểm cấu tạo của xi lanh chính","anchor":"block-1781145693690-9sek73off","figure":{"number":"2.17","caption":"Hình 2.17. Đặc điểm cấu tạo của xi lanh chính"}},{"id":"s291","kind":"figure","lesson":"2.3.2","title":"Hình 2.18. Đặc điểm cấu tạo của xi lanh công tác","text":"Hình 2.18. Đặc điểm cấu tạo của xi lanh công tác","anchor":"block-1781145693690-9sek73off","figure":{"number":"2.18","caption":"Hình 2.18. Đặc điểm cấu tạo của xi lanh công tác"}},{"id":"s292","kind":"html","lesson":"2.3.2","title":"Dẫn động điều khiển ly hợp bằng thủy lực · a. Đặc điểm cấu tạo","text":"Các thành phần thủy lực của dẫn động điều khiển ly hợp được thể hiện trên Hình 2.15. Bàn đạp ly hợp được liên kết với cần đẩy 3 của xi lanh chính 12 để tạo và gia tăng áp lực thủy lực tới xi lanh công tác 6. Trên thân của xi lanh chính 12 có một đường ống nối tới bình chứa dầu và một đường ống dẫn dầu bằng kim loại 10 nối với đoạn ống dẫn mềm 4 tới xi lanh công tác 6. Một chốt đẩy 8 được liên kết vào piston xi lanh công tác để tác động lên đòn bẩy của bộ ly hợp, ngoài ra trên xi lanh công tác 6 có một vít xả khí 5 để thực hiện thao tác xả không khí lẫn trong hệ thống thủy lực khi bảo dưỡng. Xi lanh công tác thông thường được gắn trên vỏ hộp số cơ khí 9. 1-Lò xo trợ lực trung tâm; 2- Cần chặn; 3- Cần đẩy piston; 4- Ống nối mềm; 5- Vít xả khí; 6- Xi lanh công tác; 7- Trục sơ cấp hộp số; 8- Chốt đẩy; 9- Vỏ hộp số; 10- Đường ống dẫn dầu; 11- Xi lanh chính.","anchor":"block-1781145693690-9sek73off"},{"id":"s293","kind":"html","lesson":"2.3.2","title":"Dẫn động điều khiển ly hợp bằng thủy lực · a. Đặc điểm cấu tạo","text":"1-Đường dẫn dầu; 2- Ống mềm nối với xi lanh chính; 3- Piston; 4- Vòng làm kín thứ cấp; 5- Cần đẩy piston; 6- Vòng làm kín sơ cấp; 7- Đầu nối với xi lanh công tác. 1-Chốt đẩy; 2- Đầu nối ống dẫn tới xi lanh chính; 3- Vít xả khí; 4- Vòng làm kín; 5- Piston.","anchor":"block-1781145693690-9sek73off"},{"id":"s294","kind":"html","lesson":"2.3.2","title":"Dẫn động điều khiển ly hợp bằng thủy lực · b. Nguyên lý làm việc","text":"Trong xi lanh chính Hình 2.17 của ly hợp, sự dịch chuyển của piston tạo ra áp suất thủy lực. Khi đạp lên bàn đạp ly hợp, Piston bị cần đẩy dịch chuyển về bên trái. Dầu phanh trong xi lanh chảy qua van nạp đến bình chứa và đồng thời đến xi lanh công tác. Khi piston dịch chuyển tiếp về bên trái, thanh nối sẽ tách khỏi bộ phận hãm lò xo, van nạp đóng đường dầu đi vào bình chứa bằng lò xo côn, do đó tạo thành áp suất truyền đến piston của xi lanh công tác. Nếu không khí xâm nhập vào đường dẫn dầu, không khí bị tăng áp và không tạo ra được đủ áp suất dầu. Khi đó tác dụng của ly hợp sẽ giảm và không thể chuyển số được. Xi lanh công tác Hình 2.18 làm dịch chuyển piston bằng áp suất thủy lực từ xi lanh chính để điều khiển đòn bẩy ly hợp thông qua cần đẩy hoặc chốt đẩy.","anchor":"block-1781145731902-rakhtqz69"},{"id":"s295","kind":"html","lesson":"2.3.2","title":"Dẫn động điều khiển ly hợp bằng thủy lực · b. Nguyên lý làm việc","text":"Lò xo trong xi lanh công tác luôn luôn ép cần đẩy vào đòn bẩy bằng lực của lò xo để đảm bảo giữ hành trình tự do của bàn đạp ly hợp không thay đổi. Khi vị trí của đầu lò xo đĩa hoặc cần tách thay đổi do đĩa ma sát bị mòn, cần phải điều chình hành trình tự do của bàn đạp tại vị trí cần đẩy. Lò xo màng đẩy piston xi lanh con và xi lanh chính trở về trạng thái ban đầu qua qua ổ bi bạc mở, càng ngắt ly hợp và chốt đẩy. Lực đạp được truyền qua bàn đạp ly hợp và thanh liên kết tới piston xi lanh chính. Áp suất dầu thủy lực tạo ra trong buồng áp suất của xi lanh chính lan truyền trong đường ống dẫn và ống nối mềm. Áp suất này tạo lực trên piston xi lanh con, tác động lên cơ cấu đóng - ngắt ly hợp thông qua chốt đẩy và đòn bẩy để ngắt ly hợp.","anchor":"block-1781145731902-rakhtqz69"},{"id":"s296","kind":"lesson","lesson":"2.3.3","title":"Ly hợp · Dẫn động điều khiển ly hợp có trợ lực","text":"Nhận dạng đường cơ khí và nguồn khí nén phụ trợ. Giải thích thứ tự điều khiển van cấp/xả khí."},{"id":"s297","kind":"simulation","lesson":"2.3.3","title":"Trợ lực khí nén hỗ trợ dẫn động cơ khí","text":"1. Bàn đạp được nhả. Đường cấp khí đóng, đường xả mở; bộ trợ lực chưa tạo lực mở ly hợp. 2. Bàn đạp điều khiển van. Dẫn động cơ khí đưa van phân phối tới vị trí đóng đường xả trước. 3. Mở đường cấp khí. Khí nén từ nguồn đi vào buồng trợ lực; lực khí nén bổ sung cho lực người lái. 4. Ngắt ly hợp. Piston/màng và cần đẩy tác động cơ cấu mở, làm mất lực ép giữa các bề mặt ma sát. 5. Nhả bàn đạp, xả khí. Van cấp đóng; đường xả mở để giảm áp buồng trợ lực, các cơ cấu hồi vị."},{"id":"s298","kind":"figure","lesson":"2.3.3","title":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","text":"A. Bàn đạp ly hợp. Điều khiển dẫn động cơ khí và van phân phối. B. Van phân phối. Đóng đường xả và mở đường cấp khí khi cần trợ lực; xả khí khi hồi vị. C. Ống dẫn khí nén. Đưa khí nén từ nguồn tới cụm phân phối và bộ trợ lực. D. Màng cao su piston. Nhận áp suất khí nén để tạo lực phụ trợ. E. Cần đẩy piston. Truyền lực phụ trợ tới cơ cấu mở ly hợp. F. Ổ bi bạc mở. Truyền lực tới cơ cấu tách để ngắt ly hợp.","figure":{"image":"content/resources/T1_image87.jpg","caption":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","number":"2.19b"}},{"id":"s299","kind":"part","lesson":"2.3.3","title":"Bàn đạp ly hợp","text":"Điều khiển dẫn động cơ khí và van phân phối.","keywords":["Bàn đạp ly hợp","bàn đạp"],"figure":{"image":"content/resources/T1_image87.jpg","caption":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","number":"2.19b"}},{"id":"s300","kind":"part","lesson":"2.3.3","title":"Van phân phối","text":"Đóng đường xả và mở đường cấp khí khi cần trợ lực; xả khí khi hồi vị.","keywords":["Van phân phối","van điều khiển"],"figure":{"image":"content/resources/T1_image87.jpg","caption":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","number":"2.19b"}},{"id":"s301","kind":"part","lesson":"2.3.3","title":"Ống dẫn khí nén","text":"Đưa khí nén từ nguồn tới cụm phân phối và bộ trợ lực.","keywords":["Ống dẫn khí nén","đường dẫn khí nén","ống khí"],"figure":{"image":"content/resources/T1_image87.jpg","caption":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","number":"2.19b"}},{"id":"s302","kind":"part","lesson":"2.3.3","title":"Màng cao su piston","text":"Nhận áp suất khí nén để tạo lực phụ trợ.","keywords":["Màng cao su piston","màng cao su"],"figure":{"image":"content/resources/T1_image87.jpg","caption":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","number":"2.19b"}},{"id":"s303","kind":"part","lesson":"2.3.3","title":"Cần đẩy piston","text":"Truyền lực phụ trợ tới cơ cấu mở ly hợp.","keywords":["Cần đẩy piston","cần đẩy"],"figure":{"image":"content/resources/T1_image87.jpg","caption":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","number":"2.19b"}},{"id":"s304","kind":"part","lesson":"2.3.3","title":"Ổ bi bạc mở","text":"Truyền lực tới cơ cấu tách để ngắt ly hợp.","keywords":["Ổ bi bạc mở","bạc mở","vòng bi bạc mở"],"figure":{"image":"content/resources/T1_image87.jpg","caption":"Hình 2.19b — Dẫn động cơ khí có trợ lực khí nén","number":"2.19b"}},{"id":"s305","kind":"figure","lesson":"2.3.3","title":"Hình 2.19. Dẫn động điều khiển ly hợp bằng cơ khí trợ lực khí nén","text":"Hình 2.19. Dẫn động điều khiển ly hợp bằng cơ khí trợ lực khí nén","anchor":"block-1781145803710-7gkr0iyqb","figure":{"number":"2.19","caption":"Hình 2.19. Dẫn động điều khiển ly hợp bằng cơ khí trợ lực khí nén"}},{"id":"s306","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · a. Dẫn động điều khiển cơ khí có trợ lực khí nén","text":"a- Sơ đồ nguyên lý; b- Sơ đồ cấu tạo; 1-Bàn đạp ly hợp; 2,7,10- Thanh liên kết; 3- Van phân phối; 4- Van cấp khí; 5- Van xả khí; 6- Lò xo; 8-Cần đẩy bộ trợ lực; 9- Ổ bi bạc mở; 11- Cần đẩy piston; 12- Màng cao su piston; 13- Ống dẫn khí nén; 14- Đòn quay. Đặc điểm cấu tạo của dẫn động điều khiển cơ khí có trợ lực khí nén được thể hiện trên Hình 2.19. Với loại dẫn động này thông qua dẫn động cơ khí để điều khiển bộ trợ lực cấp khí nén tới xi lanh lực. Một áp lực tại đây sẽ tác động lên ổ bi bạc mở để tiến hành ngắt ly hợp. Loại dẫn động này thường được sử dụng trên các xe có máy nén khí để tận dụng công suất của máy nén khí. Dẫn động kiểu này được sử dụng phổ biến và có ưu điểm làm việc tin cậy vì khi trợ lực khí nén hỏng thì vẫn điều khiển được ly hợp. Tuy nhiên khi đó người lái phải tác dụng lực lên bàn đạp lớn.","anchor":"block-1781145803710-7gkr0iyqb"},{"id":"s307","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · a. Dẫn động điều khiển cơ khí có trợ lực khí nén","text":"Khi tiến hành ngắt ly hợp: Người lái tác dụng một lực Q lên bàn đạp ly hợp 1 làm cho đòn quay quay quanh khớp của nó để tác động lên thanh kéo 2. Thông qua các thanh đòn tác động lên cần đẩy 8 cùng với nắp và thân van phân phối 3 dịch chuyển sang phải (theo chiều mũi tên). - Nếu đường dẫn khí nén gặp trục trặc: Vỏ của van phân phối dưới tác dụng lực của người lái tác dụng lên bàn đạp sẽ tiếp tục dịch chuyển làm xoay đòn quay 14. Khi đó thông thanh liên kết tới ổ bi bạc mở để ngắt ly hợp. - Khi hệ thống khí nén làm việc ổn định: Vỏ van phân phối dịch chuyển sẽ kéo theo van nạp khí. Khi hết hành trình dịch dịch chuyển sẽ trượt trên van xả khí 5 làm cho cho đầu van xả khí 5 tỳ vào van nạp khí 4, đóng đường xả khí ra bên ngoài. Khi đó van khí 4 được đẩy mở ra hình thành 1 khe hở giữa van 4 và vách ngăn của van phân phối.","anchor":"block-1781145803710-7gkr0iyqb"},{"id":"s308","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · a. Dẫn động điều khiển cơ khí có trợ lực khí nén","text":"Khí nén từ bình chứa sẽ theo đường dẫn 13 tác dụng lên màng cao su 12 của xi lanh lực. Hay nói cách khác, khí nén từ khoang A qua van 4 vào khoang B rồi theo đường ống dẫn tới xi lanh lực để đẩy piston xi lanh lực dịch chuyển khiến cho đòn quay tác động lên bạc mở đẩy bạc mở 17 sang trái tạo lực phụ trợ để tiến hành mở hợp. Khi người lái thôi tác dụng lực Q lên bàn đạp ly hợp, dưới tác dụng của lò xo hồi vị bàn đạp trở về trạng thái ban đầu. Đồng thời dưới tác động của lò xo van phân phối 6 thì thân van phân phối 3 trở về vị trí ban đầu, van khí 4 đóng lại. Khí nén từ xy lanh lực 7 theo đường ống , khoang B và theo rãnh đường xả khí của piston van phân phối (dọc piston 5) ra ngoài môi trường, ly hợp ở trạng thái đóng hoàn toàn.","anchor":"block-1781145803710-7gkr0iyqb"},{"id":"s309","kind":"figure","lesson":"2.3.3","title":"Hình 2.20. Sơ đồ dẫn động điều khiển thủy lực có trợ lực chân không","text":"Hình 2.20. Sơ đồ dẫn động điều khiển thủy lực có trợ lực chân không","anchor":"block-1781145809618-5tr1gykb2","figure":{"number":"2.20","caption":"Hình 2.20. Sơ đồ dẫn động điều khiển thủy lực có trợ lực chân không"}},{"id":"s310","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · b. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực chân không","text":"Đặc điểm cấu tạo của loại trợ lực này được thể hiện trên Hình 2.20. Tương tự như dẫn động điều khiển bằng thủy lực. Chỉ khác là sử dụng thêm một bộ trợ lực chân không đặt phía trước của xi lanh chính. Sử dụng dẫn động điều khiển ly hợp bằng thủy lực có trợ lực chân không thì tính năng của trợ lực thay đổi phụ thuộc vào kích thước diện tích tác dụng của chân không và áp suất khí quyển. Diện tích này lớn hơn sẽ có trợ lực lớn hơn. Bên trong trợ lực chân không được nối với cổ hút động cơ hoặc bơm chân không ở động cơ diesel. Van 1 chiều được thiết kế chỉ cho không khí trong bầu trợ lực đi vào động cơ.","anchor":"block-1781145809618-5tr1gykb2"},{"id":"s311","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · b. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực chân không","text":"1- Cần điều khiển; 2- Thân van; 3- Piston; 4- Màng cao su; 5- Vỏ bầu trợ lực; 6- Ống chân không; 7- Cần đẩy piston xi lanh chính; 8- Lò xo hồi vị; 9- Trục nối; 10- Chạc liên kết; 11- Van; A, B- Các khoang; I, II- Đường dẫn khí Trong bầu trợ lực chân không được chia bởi màng cao su thành hai phần, buồng áp suất thay đổi và buồng áp suất không đổi. Vòng trong của màng cao su được gắn lên thân van cùng với piston trợ lực. Cần điều khiển được nối với xi lanh chính. Người lái chưa tác dụng lực lên bàn đạp ly hợp. Khi đó vân chân không mở nối thông khoang A và khoang B. Không có sự chênh lệch áp suất giữa 2 phía của màng cao su 4 trong bầu trợ lực vì vậy màng cao su 4 bị lò xo đẩy sang vị trí tận cùng bên phải. Cần đẩy 7 không tác dụng làm piston xi lanh chính dịch chuyển. Do đó không có áp lực dầu sinh ra từ xi lanh chính tới xi lanh công tác.","anchor":"block-1781145809618-5tr1gykb2"},{"id":"s312","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · b. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực chân không","text":"Người lái tiến hành đạp ly hợp. Thông qua cụm van điều khiển sẽ làm cho khoang A ngăn cách với khoang B. Khoang A chứa chân chông, không khí đi vào khoang B hính thành sự chênh lệch áp suất đẩy màng cao su 4 dịch chuyển sang trái nén lò xo do. Cần đẩy 7 bắt đầu dịch chuyển đẩy piston xi lanh chính tạo áp lực dầu tới xi lanh công tác và tới cơ cấu ngắt ly hợp.","anchor":"block-1781145809618-5tr1gykb2"},{"id":"s313","kind":"figure","lesson":"2.3.3","title":"Hình 2.21. Dẫn động điều khiển ly hợp bằng thủy lực kiểu đẩy sử dụng trợ lực khí nén","text":"Hình 2.21. Dẫn động điều khiển ly hợp bằng thủy lực kiểu đẩy sử dụng trợ lực khí nén","anchor":"block-1781145882116-ljpdwwlbu","figure":{"number":"2.21","caption":"Hình 2.21. Dẫn động điều khiển ly hợp bằng thủy lực kiểu đẩy sử dụng trợ lực khí nén"}},{"id":"s314","kind":"figure","lesson":"2.3.3","title":"Hình 2.22. Dẫn động điều khiển ly hợp bằng thủy lực kiểu kéo có sử dụng trợ lực khí nén","text":"Hình 2.22. Dẫn động điều khiển ly hợp bằng thủy lực kiểu kéo có sử dụng trợ lực khí nén","anchor":"block-1781145882116-ljpdwwlbu","figure":{"number":"2.22","caption":"Hình 2.22. Dẫn động điều khiển ly hợp bằng thủy lực kiểu kéo có sử dụng trợ lực khí nén"}},{"id":"s315","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"1- Bánh đà; 2- Cơ cấu chống dính; 3- Đĩa ma sát phía ngoài; 4- Đĩa ép trung gian; 5- Cần tách; 6- Quang treo cần tách; 7- Lò xo cần tách; 8- Ống dẫn mỡ bôi trơn; 9- Ổ bi bạc mở; 10- Lò xo hồi vị ổ bi bạc mở; 11- Bạc dẫn hướng; 12- Đòn bẩy; 13- Vòng tỳ; 14-Chốt; 15- Lò xo ép; 16- Đế tản nhiệt lò xo ép; 17- Đĩa ép ngoài; 18- Vỏ ly hợp; 19- Vỏ bảo vệ; 20- Đĩa ma sát phía trong; 21- Chốt lệch tâm; 22- Bình chứa dầu; 23- Cần đẩy piston; 24- Xi lanh chính; 25- Piston xi lanh chính; 26- Đầu nối ra xi lanh công tác; 27- Đòn quay; 28- Bộ trợ lực; 29- Đai ốc điều chỉnh; 30- Cẩn đẩy trợ lực; 31- Piston thủy lực trợ lực; 32- Lò xo hồi vị; 33- Cuppen; 34- Phớt làm kín; 35- Piston trợ lực; 36- Lò xo hồi vị piston trợ lực; 37- Nắp chụp; 38- Van nạp; 39- Lò xo hồi vị cốc van; 40- Cốc van; 41- Vít xả khí nén khi nhả bàn đạp; 42- Vít xả khí; 43- Piston điều khiển;44- Van xả;","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s316","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"45- Cổng cân bằng. I- Đường vào của khí nén; II- Dầu từ xi lanh chính tới; III- Đường kiểm soát khí nén từ bên ngoài; 1- Cần đẩy trợ lực; 2- Vỏ chụp chống bụi; 3- Đệm làm kín; 4- Ống thông áp suất; 5- Piston khí nén; 6- Xi lanh khí nén; 7- Lò xo nén; 8- Piston thủy lực; 9- Thân xi lanh thủy lực; 10- Miếng nhựa dẫn hướng; 11- Vòng đệm chỉ báo; 12- Thanh chỉ báo độ mòn; 13- Cuppen; 14-Đĩa ma sát; 15- Đòn bẩy (càng ngắt); 16- Piston điều khiển; 17- Piston điều khiển van cấp khí; 18- Nắp cụm điều khiển; 19- Cuppen làm kín; 20-Đế xả; 21- Lò xo hồi vị của piston điểu khiển van cấp khí; 22- Lò xo hồi vị của van cấp khí; 23- Van cấp khí; 24- Thân của phần điều khiển; 25- Khoang điều khiển tại trạng thái tùy động.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s317","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Đặc điểm cấu tạo của bộ trợ lực khí nén kiểu đẩy như trên Hình 2.21 Xi lanh chính (24) được lắp trong giá treo của bàn đạp ly hợp trên ca bin, thân xi lanh chính được tạo thành 2 phần: Phần trên là khoang chứa dầu công tác (lượng dầu chiếm 3/4 thế tích), phần dưới là xi lanh. Trong xi lanh có đặt piston 25, piston được khoan lổ ở giữa, phía ngoài lắp phớt làm kín, phía dưới có lò xo hồi vị. Xi lanh thuỷ lực trợ lực khí nén 28 (bộ trợ lực) được lắp bên ngoài vỏ ly hợp.Thân xi lanh thuỷ khí được làm thành 2 phần: Thân trước điều khiển khí nén và thân sau điều khiển thủy lực lắp chật với nhau bằng các bu lông, tạo nên hai phần trên và dưới: - Ở phần dưới: Phía trước là xi lanh khí, trong xi lanh có pit tông khí 35 và lò xo hổi vị của pit tông 36.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s318","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Phía sau là xi lanh thuỷ lực, trong xi lanh có piston 31, trên thân có lổ dầu được nối với xi lanh chính bằng đường ống. - Ở phần trên: Tại bề mật lắp ghép giữa thân trước và thân sau có kẹp chặt màng cao su, màng cao su được gắn chặt với cốc van xả 40 và màng chia phần trên thành 2 khoang. Trong khoang trước có lò xo hồi vị của màng 39, cụm van nạp 38 và van xả 44, trên thân được khoan đường dẫn khí xuống xi lanh khí nén và về phía trước màng cao su. Trên nắp chụp 37 có lỗ khí nén được nối với bình chứa khí bằng đường ống. Khoang phía sau là xi lanh điều khiển có piston điều khiển 43. Trên thân được khoan lỗ dẫn dầu thông với xi lanh thuỷ lực, phía trên được đậy bằng vít xả khí 42 để xả khí lẫn trong dầu, trên thân còn có vít 41 nối thông với khí trời được đậy bằng nắp.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s319","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Đặc điểm cấu tạo của bộ trợ lực kiểu kéo Hình 2.22 Bao gồm 3 bộ phận chính: Xi lanh khí nén; bộ phận điều khiển bằng thủy lực và bộ phận báo hiệu mòn cho đĩa bị động. Bộ trợ lực khí nén của bộ truyền động điều khiển ly hợp có nhiệm vụ giảm lực trên bàn đạp ly hợp, nó được liên kết vào vỏ hộp số từ bên dưới. Van cấp khí 22 ban đầu được đóng bởi một lò xo 21 để cắt đường cấp khí nén từ xi lanh khí nén. Lúc này, khoang bên phải của xi lanh khí nén được nối thông với khí quyển. Một lò xo hồi vị nhỏ 21 tác động lên piston điều khiển khí nén 17, di chuyển nó cùng với piston thủy lực 16 của cụm điều khiển đến vị trí trên cùng cho đến khi nó dừng lại trong vỏ. Vị trí này được thể hiện trên Hình 2.23 là khi đã có áp suất thủy lực tác dụng lên piston 16. Như vậy, xi lanh khí nén ở vị trí ban đầu được kết nối thông qua tiết diện lỗ của van 5 với đế xả 20.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s320","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Thanh chỉ báo độ mòn 12 cùng với vòng đệm chống mòn 11 là một thanh hình trụ, được nén chặt trong một miếng nhựa dẫn hướng 10 và được gắn vào các giá đỡ của nó. Chỉ báo độ mòn đối với đĩa ma sát mới là ở vị trí ban đầu khi vòng đệm chỉ báo 11 chỉ tiếp xúc với miếng nhựa dẫn hướng 10. Khi có sự mài mòn lớn của đĩa ma sát, piston khí nén 5 bắt đầu trượt trên xi lanh của nó, đẩy nó về phía xi lanh thủy lực. Khi đó để đĩa ma sát vẫn làm việc tốt thì giới hạn bởi khoảng cách từ vòng đệm tới miếng nhựa là 23-25mm, khe hở ngày càng tăng khi khi đĩa ma sát càng bị mìn nhiều, vượt quá giá trị trên yêu cầu phải thay thế các bề mặt ma sát của đĩa bị động. Với sự trợ giúp của lò xo nén 7, piston khí nén 6 của bộ trợ lực với cần đẩy 1 luôn được kết nối mà không có sự va đập với các chi tiết khác.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s321","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Ngoài ra đảm bảo rằng piston khí nén 5 giám sát sự mài mòn của bề mặt đĩa ma sát bằng cách di chuyển sâu hơn vào thanh chỉ báo độ mòn 12 để tác động lên nó. Với sơ đồ kiểu đẩy như trên Hình 2.21 Khi người lái không tác dụng vào bàn đạp ly hợp, lò xo hồi vị kéo bàn đạp về vị trí ban đầu, dầu từ xi lanh thuỷ lực và xi lanh điều khiển trở về xi lanh chính và đi qua lỗ trên piston 25 vào bình chứa dầu. Do áp lực dầu trên piston điều khiển giảm nên áp lực khí nén và lò xo hồi vị cốc van 39 đẩy màng cao su và piston điều khiển về vị trí ban đầu, cốc van xả 44 mở van nạp 38 đóng. Khí nén trong xi lanh khí được dẫn qua cốc van xả 44 và vít xả 41 ra khí trời, lò xo hồi vị 36 đẩy piston khí về vị trí ban đầu. Ly hợp ở trạng thái đóng hoàn toàn.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s322","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Khi người lái đạp vào bàn đạp ly hợp, piston xi lanh chính nén dầu tới xi lanh thuỷ lực và xi lanh điều khiển, áp lực dầu tác dụng lên piston 31 tạo nên lực đẩy trên cần piston 30 để mở ly hợp. Đồng thời áp lực khí nén lác dụng lên piston điều khiển 43 và làm piston dịch chuyển, cốc van xả 44 đóng, van nạp 38 mở. Khí nén được dẫn lừ bình chứa khí qua van nạp lới xi lanh khí và về phía trước của màng cao su qua cổng cân bằng 45. Áp lực khí nén tác dụng lên piston khí 35 làm piston dịch chuyển và tạo nên lực đẩy trên cần pit lông 30 để mở ly hợp. Như vậy lực mở ly hợp được lạo bởi hai thành phần, đó là áp lực dầu do lực tác dụng của người lái tạo nên và áp lực khí nén. Trạng thái giữ bàn đạp (rà ly hợp): Còn được gọi là trạng thái tùy động của ly hợp. Trạng thái này được người lái xe sử dụng nhiều nhất trong quá trình vận hành ô tô.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s323","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Khi người lái đạp vào bàn đạp ly hợp với lực không đổi, trong xi lanh khí áp suất khí nén tăng cho tới khi áp lực khí nén qua cổng cân bằng để tác dụng trên màng cao su làm piston điều khiển 43 dịch chuyển sang trái cho tới khi van nạp 38 đóng và cốc van xả vẫn đóng. Lực lác dụng ở hai bên màng cao su được cân bằng, áp suất khí nén trong xi lanh khí khi đó có giá trị không đổi và tỷ lệ với áp suất dầu trong hệ thống. Như vậy lực để mở ly hợp luôn tỷ lệ với áp lực dầu trong đường ống do sự tác dụng của người lái lên bàn đạp. Trong trường hợp hệ thống khí nén bị trục trặc hoặc trong trường hợp không có áp suất trong hệ thống khí nén, piston thủy lực trợ lực 31 sẽ dịch chuyển để ngắt ly hợp chỉ dưới tác dụng của áp suất của chất lỏng từ xi lanh chính tới. Trong trường hợp này, người lái phải tác dụng lực lớn lên bàn đạp ly hợp.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s324","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Với sơ đồ kiểu kéo như trên Hình 2.22: Khi nhả bàn đạp ly hợp, áp suất lên piston thủy lực 8 của hệ thống thủy lực giảm, điều này sẽ di chuyển piston về vị trí ban đầu của nó, van cấp khí nén 23 của hệ thống diều khiển đóng lại, và áp suất phía sau piston khí nén 5 đi qua tiết diện lỗ của van cấp khí 23 qua đế xả vào khí quyển. Sau khi dừng hoạt động bàn đạp ly hợp, áp suất chất lỏng trong bộ điều khiển được trả về xi lanh chính. Khi nhấn bàn đạp ly hợp, áp suất chất lỏng từ xi lanh chính được truyền qua đường ống dẫn đến bộ trợ lực thủy lực khí nén, tại đây nó tác dụng lên piston thủy lực 8 và piston 16 của bộ dẫn động làm chuyển động của piston cấp khí 17 nén lò xo 21 cho đến khi tiếp xúc và đẩy van cấp khí 23 xuống phía dưới. Khi đó đường xả ra khí quyển bị đóng lại.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s325","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Van cấp khí 23 mở đường dẫn áp suất khí nén đến xi lanh khí nén 6 để tác động vào piston 5, làm tăng tác dụng lực của cần đẩy 1 lên đòn bẩy của ly hợp. Sự tăng áp suất đi vào xi lanh khí nén của bộ trợ lực sẽ tự động thay đổi, tùy thuộc vào nỗ lực của người lái trên bàn đạp ly hợp. Trạng thái giữ bàn đạp (rà ly hợp): Còn được gọi là trạng thái tùy động của ly hợp. Khi người lái đạp bàn đạp ly hợp tới một vị trí nhất định sau đó giữ nguyên vị trí thì dưới tác động của piston điều khiển 16, piston điều khiển van cấp khí 17 di chuyển và nén lò xo hồi vị của van cấp khí 22, van cấp khí 23 được mở ra để khí nén được cung cấp cho xi lanh khí nén, áp suất tăng lên sẽ thông qua khe hở giữa piston điều khiển van cấp khí 17 và thân van 24.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s326","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Áp suất gia tăng tại khoang 25 sẽ tác động lên tiết diện bề mặt hình khuyên phía dưới cùng của piston điều khiển 17 cho đến khi cân bằng với áp lực trên piston điều khiển 16 của thiết bị trợ lực thủy lực. Lò xo hồi vị của van cấp khí 22 (lò xo lớn) sẽ có xu hướng đẩy và đóng van cấp khí 23, đồng thời đường xả khí nén ra khí quyển vẫn đóng vì áp lực tác dụng ngược lên piston 17 vẫn đang cân bằng với áp lực thủy lực từ xi lanh chính tới tác dụng lên piston 16. Áp suất tại xi lanh khí nén sẽ có giá trị không đổi. Như vậy để thay đổi áp suất khí nén tùy thuộc vào lực tác động của người lái lên bàn đạp ly hợp. Trong trường hợp hệ thống khí nén bị trục trặc hoặc trong trường hợp không có áp suất trong hệ thống khí nén, piston thủy lực 8 sẽ được dịch chuyển để ngắt ly hợp chỉ dưới tác dụng của áp suất của chất lỏng từ xi lanh chính tới.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s327","kind":"html","lesson":"2.3.3","title":"Dẫn động điều khiển ly hợp có trợ lực · c. Dẫn động điều khiển ly hợp bằng thủy lực trợ lực khí nén","text":"Trong trường hợp này, người lái phải tác dụng lực lớn lên bàn đạp ly.","anchor":"block-1781145882116-ljpdwwlbu"},{"id":"s328","kind":"lesson","lesson":"2.4.1","title":"Ly hợp · Hệ thống ly hợp tự động (ACS – Automatic Clutch System) với ly hợp ma sát một đĩa","text":"Theo dõi tín hiệu đầu vào → điều khiển → chấp hành. Giải thích quá trình ngắt/nối lại ly hợp khi sang số."},{"id":"s329","kind":"simulation","lesson":"2.4.1","title":"ACS: nhận dạng sang số → ngắt → nối lại","text":"1. Tiếp nhận tín hiệu. Cảm biến nhận dạng dự tính sang số gửi thông tin; bộ điều khiển còn nhận tốc độ và các tín hiệu liên quan. 2. Bộ điều khiển xử lý. Bộ điều khiển tính toán lệnh đóng/ngắt và phát lệnh tới cơ cấu chấp hành. 3. Cơ cấu chấp hành tạo áp suất. Động cơ điện và bộ truyền trục vít – bánh vít tác động xi lanh chính; áp suất được truyền tới xi lanh con. 4. Ly hợp ngắt để sang số. Xi lanh con tác động cơ cấu mở. Đường truyền mômen bị ngắt trong giai đoạn sang số. 5. Nối lại có điều khiển. Sau khi nhận dạng số đã gài, bộ điều khiển điều chỉnh cơ cấu chấp hành để ly hợp đóng lại với độ trượt phù hợp."},{"id":"s330","kind":"figure","lesson":"2.4.1","title":"Hình 2.23 — Hệ thống ly hợp tự động ACS","text":"A. Bộ điều khiển ly hợp. Xử lý tín hiệu đầu vào để tính toán trạng thái và hành trình đóng/ngắt ly hợp. B. Động cơ điện. Nhận lệnh điều khiển và dẫn động bộ truyền trục vít – bánh vít. C. Bộ truyền trục vít bánh vít. Truyền chuyển động từ động cơ điện tới cơ cấu tạo áp suất. D. Xi lanh chính. Tạo áp suất thủy lực cho cơ cấu đóng/ngắt trung tâm. E. Xi lanh con. Tác động trực tiếp lên cơ cấu đóng/ngắt ly hợp. F. Tín hiệu đầu vào. Gồm tín hiệu sang số, tốc độ, vị trí ga và các thông tin CAN-bus theo sơ đồ.","figure":{"image":"content/resources/T1_image91.jpg","caption":"Hình 2.23 — Hệ thống ly hợp tự động ACS","number":"2.23"}},{"id":"s331","kind":"part","lesson":"2.4.1","title":"Bộ điều khiển ly hợp","text":"Xử lý tín hiệu đầu vào để tính toán trạng thái và hành trình đóng/ngắt ly hợp.","keywords":["Bộ điều khiển ly hợp","bộ điều khiển"],"figure":{"image":"content/resources/T1_image91.jpg","caption":"Hình 2.23 — Hệ thống ly hợp tự động ACS","number":"2.23"}},{"id":"s332","kind":"part","lesson":"2.4.1","title":"Động cơ điện","text":"Nhận lệnh điều khiển và dẫn động bộ truyền trục vít – bánh vít.","keywords":["Động cơ điện"],"figure":{"image":"content/resources/T1_image91.jpg","caption":"Hình 2.23 — Hệ thống ly hợp tự động ACS","number":"2.23"}},{"id":"s333","kind":"part","lesson":"2.4.1","title":"Bộ truyền trục vít bánh vít","text":"Truyền chuyển động từ động cơ điện tới cơ cấu tạo áp suất.","keywords":["Bộ truyền trục vít bánh vít","trục vít bánh vít"],"figure":{"image":"content/resources/T1_image91.jpg","caption":"Hình 2.23 — Hệ thống ly hợp tự động ACS","number":"2.23"}},{"id":"s334","kind":"part","lesson":"2.4.1","title":"Xi lanh chính","text":"Tạo áp suất thủy lực cho cơ cấu đóng/ngắt trung tâm.","keywords":["Xi lanh chính","xilanh chính"],"figure":{"image":"content/resources/T1_image91.jpg","caption":"Hình 2.23 — Hệ thống ly hợp tự động ACS","number":"2.23"}},{"id":"s335","kind":"part","lesson":"2.4.1","title":"Xi lanh con","text":"Tác động trực tiếp lên cơ cấu đóng/ngắt ly hợp.","keywords":["Xi lanh con","xi lanh công tác","cơ cấu đóng ngắt trung tâm"],"figure":{"image":"content/resources/T1_image91.jpg","caption":"Hình 2.23 — Hệ thống ly hợp tự động ACS","number":"2.23"}},{"id":"s336","kind":"part","lesson":"2.4.1","title":"Tín hiệu đầu vào","text":"Gồm tín hiệu sang số, tốc độ, vị trí ga và các thông tin CAN-bus theo sơ đồ.","keywords":["Tín hiệu đầu vào","tín hiệu cảm biến","các tín hiệu đầu vào"],"figure":{"image":"content/resources/T1_image91.jpg","caption":"Hình 2.23 — Hệ thống ly hợp tự động ACS","number":"2.23"}},{"id":"s337","kind":"figure","lesson":"2.4.1","title":"Hình 2.23. Sơ đồ hệ thống ly hợp tự động ACS","text":"Hình 2.23. Sơ đồ hệ thống ly hợp tự động ACS","anchor":"block-1781146103372-fdep3wo12","figure":{"number":"2.23","caption":"Hình 2.23. Sơ đồ hệ thống ly hợp tự động ACS"}},{"id":"s338","kind":"html","lesson":"2.4.1","title":"Hệ thống ly hợp tự động (ACS – Automatic Clutch System) với ly hợp ma sát một đĩa · a. Đặc điểm cấu tạo","text":"Đây là một hệ thống ly hợp tự động trong đó việc đóng và ngắt ly hợp được kích hoạt nhờ tín hiệu từ các cảm biến. Quá trình đóng-ngắt ly hợp của người lái xe là tự động nên không có bàn đạp ly hợp. Quá trình điều khiển hoạt động của ly hợp phụ thuộc vào một số tín hiệu cảm biến như sau: - Tin hiệu điều khiển phanh ABS và chống trượt TCS. Các thành phần của hệ thống ly hợp (ACS): - Ly hợp lò xo màng tự hiệu chỉnh với cơ cấu đóng-ngắt bằng thủy lực. (Đã trình bày ở phần ly hợp ma sát); - Các cảm biến hành trình ngắt, nhận dạng tay số và nhận dạng dự tính quá trình sang số; + Nhận dạng dự tinh sang số: Được nhận dạng nhờ cảm biên (chiết áp xoay) trên cần sang số. + Nhận dạng tay số: Được nhận dạng nhờ hai cảm biến góc xoay không tiếp xúc trên thanh chuyển số trong hộp số.","anchor":"block-1781146103372-fdep3wo12"},{"id":"s339","kind":"html","lesson":"2.4.1","title":"Hệ thống ly hợp tự động (ACS – Automatic Clutch System) với ly hợp ma sát một đĩa · a. Đặc điểm cấu tạo","text":"Ngoài các tín hiệu cảm biến tay số và dự tính sang số, bộ điều khiển còn nhận các tín hiệu từ CAN bus đến từ các bộ điều khiển động cơ và điều khiển ABS/TCS. - Bộ điều khiến hệ thống ly hợp; - Bộ chấp hành (cơ cấu tác động): + Động cơ điện với bộ truyền trục vít bánh vít. +Xi lanh chính, cơ cấu đóng-ngắt ly hợp bằng thủy lực (xi lanh con). Hệ thống ly hợp tự động có đặc điểm như sau: Không cần bàn đạp ly hợp; Động cơ không bị tắt khi khởi chạy và phanh; Tính năng chống ăn mòn tốt cho ổ bi bạc mở và bố ma sát ly hợp; Dao động xoắn của động cơ được giảm nhờ trượt trong ly hợp; Không có những phản ứng xấu khi thay đổi tải.","anchor":"block-1781146103372-fdep3wo12"},{"id":"s340","kind":"html","lesson":"2.4.1","title":"Hệ thống ly hợp tự động (ACS – Automatic Clutch System) với ly hợp ma sát một đĩa · b. Nguyên lý làm việc","text":"Để nhận dạng trạng thái làm việc tương ứng của hệ thống, bộ điều khiển nhận các tín hiệu đầu vào từ các cảm biến, các tín hiệu này được bộ điều khiền xử lý nhờ phần mềm ly hợp và sau đó truyền tín hiệu đầu ra tới các thiết bị tác động (cơ cấu tác động). Ly hợp ở trạng thái đóng hay mở tùy thuộc vào tín hiệu cho cơ cấu tác động. Bộ điều khiển tính toán độ trượt tối ưu cho việc khởi chạy từ các tín hiệu đầu vào khác nhau như tốc độ quay bánh xe, tốc độ quay động cơ và tốc độ quay trục đầu vào hộp số. Cảm biến trên cần chuyển số báo hiệu dự tính sang số của người lái xe. Bộ điều khiển tác động việc tạo ra áp suất trong xi lanh chính thông qua động cơ điện có bộ truyền trục vít. Áp suất này mở ly hợp thông qua cơ cẩu đóng ngắt trung tâm thủy lực (xi lanh con). Sau khi chuyển số các cảm biến nhận dạng tay số cho biết số nào đã được gài.","anchor":"block-1781146140712-7rj0p8ppz"},{"id":"s341","kind":"html","lesson":"2.4.1","title":"Hệ thống ly hợp tự động (ACS – Automatic Clutch System) với ly hợp ma sát một đĩa · b. Nguyên lý làm việc","text":"Sau đó, bộ điều khiển chuyển một tín hiệu tới động cơ điện để tác động vào bộ truyền trục vít. Trong bộ phận này hành trình ngắt được truyền từ cảm biến tới bộ điều khiển. Ly hợp làm việc ở trạng thái đóng với độ trượt được điều chỉnh. Người lái xe không nhất thiết phải nhấc chân ra khỏi bàn đạp ga trong khi sang số. Lượng nhiên liệu phun vào được tự động giảm bớt và sau đó tăng trở lại. Đề làm giảm các dao động xoắn, bộ điều khiển tính toán sự khác biệt từ các tín hiệu của tốc độ quay động cơ và tốc độ quay của đầu vào hộp số, sao cho một độ trượt có kiếm soát được thiết lập nếu cần. Để tránh những ảnh hường xấu khi thay đổi tải, ly hợp có thề được ngắt trong một thời gian ngắn khi bàn đạp ga được đạp nhanh. Xe có thể tăng tốc êm dịu nhờ độ trượt được điều chỉnh này.","anchor":"block-1781146140712-7rj0p8ppz"},{"id":"s342","kind":"html","lesson":"2.4.1","title":"Hệ thống ly hợp tự động (ACS – Automatic Clutch System) với ly hợp ma sát một đĩa · b. Nguyên lý làm việc","text":"Chế độ xuống số thấp trên đường trơn trượt: Nếu các bánh xe có xu hướng bị bó cứng khi phanh trên đường trơn trượt, ly hợp sẽ ngắt để tránh cho xe khỏi bị trượt.","anchor":"block-1781146140712-7rj0p8ppz"},{"id":"s343","kind":"lesson","lesson":"2.4.2","title":"Ly hợp · Hệ thống ly hợp tự động với ly hợp kép","text":"Xác định C1–IS1 và C2–IS2 theo sơ đồ bài học. Giải thích chọn trước số và chuyển tiếp mômen."},{"id":"s344","kind":"simulation","lesson":"2.4.2","title":"Chuyển từ số 1 sang số 2","text":"1. Đang chạy số 1. C1 nối mômen tới IS1 và số 1. C2 chưa truyền mômen. 2. Chọn trước số 2. Số 2 được chọn ở nhánh IS2 khi C2 vẫn ngắt; C1 tiếp tục truyền mômen cho số 1. 3. Chuyển tiếp có kiểm soát. Khả năng truyền mômen của C1 giảm dần, C2 tăng dần. Đây là giai đoạn trùng lặp có kiểm soát, không phải khóa cứng cả hai nhánh. 4. Đang chạy số 2. C1 ngắt; C2 nối mômen tới IS2 và số 2. 5. Chọn trước số 3. Số 3 được chọn ở nhánh IS1 khi C1 vẫn ngắt; C2 duy trì truyền mômen cho số 2."},{"id":"s345","kind":"figure","lesson":"2.4.2","title":"Hình 2.24 — Ly hợp kép và hai trục sơ cấp","text":"A. Ly hợp C1. Nối mômen tới trục đặc IS1, phụ trách các cấp số lẻ trong sơ đồ bài học. B. Ly hợp C2. Nối mômen tới trục rỗng IS2, phụ trách các cấp số chẵn và số lùi trong sơ đồ. C. Trục đặc IS1. Nhận mômen qua C1 và nối với nhóm số lẻ. D. Trục rỗng IS2. Nhận mômen qua C2 và nối với nhóm số chẵn.","figure":{"image":"content/resources/T1_image92.jpg","caption":"Hình 2.24 — Ly hợp kép và hai trục sơ cấp","number":"2.24"}},{"id":"s346","kind":"part","lesson":"2.4.2","title":"Ly hợp C1","text":"Nối mômen tới trục đặc IS1, phụ trách các cấp số lẻ trong sơ đồ bài học.","keywords":["Ly hợp C1","c1"],"figure":{"image":"content/resources/T1_image92.jpg","caption":"Hình 2.24 — Ly hợp kép và hai trục sơ cấp","number":"2.24"}},{"id":"s347","kind":"part","lesson":"2.4.2","title":"Ly hợp C2","text":"Nối mômen tới trục rỗng IS2, phụ trách các cấp số chẵn và số lùi trong sơ đồ.","keywords":["Ly hợp C2","c2"],"figure":{"image":"content/resources/T1_image92.jpg","caption":"Hình 2.24 — Ly hợp kép và hai trục sơ cấp","number":"2.24"}},{"id":"s348","kind":"part","lesson":"2.4.2","title":"Trục đặc IS1","text":"Nhận mômen qua C1 và nối với nhóm số lẻ.","keywords":["Trục đặc IS1","is1","trục đặc"],"figure":{"image":"content/resources/T1_image92.jpg","caption":"Hình 2.24 — Ly hợp kép và hai trục sơ cấp","number":"2.24"}},{"id":"s349","kind":"part","lesson":"2.4.2","title":"Trục rỗng IS2","text":"Nhận mômen qua C2 và nối với nhóm số chẵn.","keywords":["Trục rỗng IS2","is2","trục rỗng"],"figure":{"image":"content/resources/T1_image92.jpg","caption":"Hình 2.24 — Ly hợp kép và hai trục sơ cấp","number":"2.24"}},{"id":"s350","kind":"figure","lesson":"2.4.2","title":"Hình 2.24. Hộp số tay chuyển số trực tiếp với ly hợp kép","text":"Hình 2.24. Hộp số tay chuyển số trực tiếp với ly hợp kép","anchor":"block-1781146191168-4v3vit0xb","figure":{"number":"2.24","caption":"Hình 2.24. Hộp số tay chuyển số trực tiếp với ly hợp kép"}},{"id":"s351","kind":"html","lesson":"2.4.2","title":"Hệ thống ly hợp tự động với ly hợp kép · a. Đặc điểm cấu tạo chung","text":"Đặc điểm cấu tạo của bộ ly hợp kép như trên Hình 2.24 Ly hợp kép giúp cho quá trình chuyển số không gây gián đoạn lực kéo, được sử dụng trong hộp số tay tự động như hộp số chuyển số trực tiếp (DSG). Sự thay đổi số và ly hợp có thể tiên hành tự động hoặc bởi người lái xe. Ly hợp kép bao gồm hai ly hợp đơn hoạt động độc lập với nhau C1 và C2 được bố trí chung trong một vỏ. Mỗi một moayơ cùa đĩa ly hợp C1 và C2 được nối với một trục sơ cấp hộp số IS1 (trục đặc) hoặc IS2 (trục rỗng). Các bánh răng gắn cứng của các số 1, 3, 5 và 7 (nếu có) được bố trí trên trục IS1; trong khi các bánh rang gắn cứng của các số 2, 4, 6 và số lùi trên trục IS2. C1 và C2 có thề là ly hợp ướt hoặc ly hợp khô.","anchor":"block-1781146191168-4v3vit0xb"},{"id":"s352","kind":"figure","lesson":"2.4.2","title":"Hình 2.25. Quá trình sang số khi lên số cao","text":"Hình 2.25. Quá trình sang số khi lên số cao","anchor":"block-1781146212013-0rz0ryrw5","figure":{"number":"2.25","caption":"Hình 2.25. Quá trình sang số khi lên số cao"}},{"id":"s353","kind":"html","lesson":"2.4.2","title":"Hệ thống ly hợp tự động với ly hợp kép · b. Nguyên lý làm việc chung","text":"Nguyên lý hoạt động tùy thuộc vào điều kiện vận hành, phần mềm điều khiển hộp sổ cài trong bộ điều khiển sẽ quyết định: - Ly hợp và số nào được chọn để vận hành xe; Chế độ khởi động động cơ và chạy không tải: Cả hai ly hợp ma sát đều ngắt. Không số nào được chọn. Người lái xe có thề dùng cần chọn chế độ để chọn lựa 3 chế độ lái: Tiện nghi; thông thường và thể thao. Khi chọn chế độ chạy cài sẵn D, hoặc chế độ sang số nhờ nhấn lẫy chuyển số trên vành tay lái, số 1 và 2 được chọn. Khi đạp ga, ly hợp C1 sẽ đóng cho số 1. Đường truyền lực giữa động cơ và hộp số được thiết lập. Xe bắt đầu quá trình khởi hành. Ly hợp của số đang chạy đóng (nối) trong khi ly hợp của số 2 dự kiến mở (ngắt). Khi chuyền từ số 1 sang số 2, ly hợp C1 chịu trách nhiệm số 1 sẽ ngắt, đồng thời ly hợp C2 chịu trách nhiệm số 2 sẽ đóng ( Hình 2.25).","anchor":"block-1781146212013-0rz0ryrw5"},{"id":"s354","kind":"html","lesson":"2.4.2","title":"Hệ thống ly hợp tự động với ly hợp kép · b. Nguyên lý làm việc chung","text":"Trong khi hai ly hợp có thời gian trùng lặp, momen xoắn động cơ sẽ giảm bớt đẻ việc sang số thoải mái hơn và giảm mòn cho các ly hợp. Quá trình đóng ngắt ly hợp C1 và C2 được điều khiển sao cho việc lên số cao hay xuống số thấp có thề thực hiện mà không làm mất mát lực kéo. ở đây có thời gian trùng lặp cùa hai ly hợp từ 0,03 giây đến 0,05 giây. Điều này có nghĩa cả hai ly hợp có kết nối lực. Toàn bộ quá trình sang số kéo dài từ 0,1 giây tới 0,4 giây. Sau khi số 2 đã được gài, số 3 sẽ được chọn sẵn trong lúc ly hợp C1 bị ngắt ra. Thí dụ, nếu cần chuyển từ số 3 về số 2 thì số thấp hơn kế tiếp sẽ được chọn trước. Ly hợp C1, chịu trách nhiệm số 3 (ly hợp ngắt), sẽ bị ngắt. Đồng thời ly hợp C2, chịu trách nhiệm số 2 (ly hợp nối), sẽ được đóng (Hình 2.25). Khi tắt động cơ, cả hai ly hợp đều đóng và hộp số về vị trí trung gian.","anchor":"block-1781146212013-0rz0ryrw5"},{"id":"s355","kind":"html","lesson":"2.4.2","title":"Hệ thống ly hợp tự động với ly hợp kép · b. Nguyên lý làm việc chung","text":"Xe không thể giữ đứng yên thông qua hộp số. cần có một khóa đỗ xe cơ học ngăn xe di chuyển. Khi chạy theo quán tính (chế độ tự đẩy), xe sẽ di chuyền không cần sự hỗ trợ của động cơ. Cả hai ly hợp C1 và C2 đều ngắt. Tùy vào tốc độ xe, hai số phù hợp được chọn trước. Vì lý do an toàn, khi cơ cấu chấp hành ly hợp bị hỏng, ly hợp kép phải tự động ngắt để tránh làm hỏng hộp số. Khi các ly hợp không kích hoạt, lực ép bằng không (thường mở). Lực ép lớn nhất khi ly hợp được tác động hoặc kết nối. Với ly hợp ma sát khô, lò xo màng tạo nên lực ép; với ly hợp ma sát ướt, lực này sinh ra thông qua áp suất dầu.","anchor":"block-1781146212013-0rz0ryrw5"},{"id":"s356","kind":"lesson","lesson":"2.4.3","title":"Ly hợp · Kết cấu hệ thống ly hợp kép","text":"Phân biệt dầu điều khiển với dầu tiếp xúc các mặt ma sát. Nhận dạng buồng áp suất, buồng cân bằng và cơ cấu đóng."},{"id":"s357","kind":"note","lesson":"2.4.3","title":"Ly hợp kép khô và ướt","text":"“Khô / ướt” mô tả môi trường làm việc của bề mặt ma sát. Cụm khô vẫn có thể dùng chấp hành thủy lực. Trạng thái thường mở, trục đặc / rỗng và phân nhóm số phải đọc theo sơ đồ của cụm đang xét; không áp dụng cho mọi hộp số ly hợp kép."},{"id":"s358","kind":"simulation","lesson":"2.4.3","title":"Ly hợp kép ướt: tác động C1","text":"1. C1 chưa nhận áp suất đóng. Cụm C1 chưa được ép chặt; nhánh C1 chưa truyền mômen trong minh họa. 2. Cấp dầu vào buồng áp suất. Dầu điều khiển có áp được dẫn tới buồng áp suất của C1. 3. Piston ép cụm đĩa C1. Áp suất tác động lên piston, kẹp các đĩa và thiết lập đường truyền mômen tới trục đặc. 4. Giảm áp để ngắt C1. Giải phóng áp suất tác động làm mất lực ép và ngắt nhánh C1."},{"id":"s359","kind":"simulation","lesson":"2.4.3","title":"Ly hợp kép khô: tác động C2","text":"1. C2 chưa được tác động. Cụm C2 chưa được cơ cấu đóng ép chặt. 2. Xi lanh con tác động càng đóng. Dầu điều khiển tác động xi lanh con để dịch chuyển càng đóng C2. Dầu nằm trong dẫn động, không ngâm các mặt ma sát khô. 3. Ép đĩa C2. Càng đóng ngắn tác động cơ cấu ép C2, thiết lập đường truyền mômen tới trục rỗng. 4. Thôi tác động C2. Giải phóng tác động của cơ cấu đóng; nhánh C2 ngắt."},{"id":"s360","kind":"figure","lesson":"2.4.3","title":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","text":"A. Đường cấp dầu áp suất. Đưa dầu điều khiển tới buồng áp suất của ly hợp được chọn. B. Buồng áp suất. Dầu có áp tác dụng lên piston để ép cụm đĩa. C. Buồng cân bằng dầu. Bù tác động lực ly tâm của dầu, hạn chế ly hợp tự nối ở tốc độ cao. D. Piston tác động. Biến áp suất dầu thành lực ép cụm đĩa. E. Ly hợp C1. Cụm ly hợp ngoài; nối với trục đặc theo sơ đồ của bài. F. Ly hợp C2. Cụm ly hợp trong; nối với trục rỗng theo sơ đồ của bài.","figure":{"image":"content/resources/T1_image94.jpg","caption":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","number":"2.26"}},{"id":"s361","kind":"part","lesson":"2.4.3","title":"Đường cấp dầu áp suất","text":"Đưa dầu điều khiển tới buồng áp suất của ly hợp được chọn.","keywords":["Đường cấp dầu áp suất","đường dầu","áp suất dầu"],"figure":{"image":"content/resources/T1_image94.jpg","caption":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","number":"2.26"}},{"id":"s362","kind":"part","lesson":"2.4.3","title":"Buồng áp suất","text":"Dầu có áp tác dụng lên piston để ép cụm đĩa.","keywords":["Buồng áp suất"],"figure":{"image":"content/resources/T1_image94.jpg","caption":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","number":"2.26"}},{"id":"s363","kind":"part","lesson":"2.4.3","title":"Buồng cân bằng dầu","text":"Bù tác động lực ly tâm của dầu, hạn chế ly hợp tự nối ở tốc độ cao.","keywords":["Buồng cân bằng dầu","buồng cân bằng"],"figure":{"image":"content/resources/T1_image94.jpg","caption":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","number":"2.26"}},{"id":"s364","kind":"part","lesson":"2.4.3","title":"Piston tác động","text":"Biến áp suất dầu thành lực ép cụm đĩa.","keywords":["Piston tác động","piston","pít tông"],"figure":{"image":"content/resources/T1_image94.jpg","caption":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","number":"2.26"}},{"id":"s365","kind":"part","lesson":"2.4.3","title":"Ly hợp C1","text":"Cụm ly hợp ngoài; nối với trục đặc theo sơ đồ của bài.","keywords":["Ly hợp C1","c1"],"figure":{"image":"content/resources/T1_image94.jpg","caption":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","number":"2.26"}},{"id":"s366","kind":"part","lesson":"2.4.3","title":"Ly hợp C2","text":"Cụm ly hợp trong; nối với trục rỗng theo sơ đồ của bài.","keywords":["Ly hợp C2","c2"],"figure":{"image":"content/resources/T1_image94.jpg","caption":"Hình 2.26 — Ly hợp kép ma sát ướt, nhánh C1","number":"2.26"}},{"id":"s367","kind":"figure","lesson":"2.4.3","title":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","text":"A. Đĩa ép C1. Ép đĩa ly hợp C1 khi càng đóng dài tác động. B. Đĩa ly hợp C1. Đĩa ma sát nối với trục đặc. C. Càng đóng ly hợp C1. Nhận lực từ xi lanh con để tác động vào cơ cấu đóng C1. D. Xi lanh con. Dẫn động càng đóng ly hợp bằng thủy lực. E. Càng đóng ly hợp C2. Càng đóng ngắn tác động vào cơ cấu đóng C2. F. Đĩa ép C2. Ép đĩa ly hợp C2 để nối mômen tới trục rỗng.","figure":{"image":"content/resources/T1_image96.jpg","caption":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","number":"2.28"}},{"id":"s368","kind":"part","lesson":"2.4.3","title":"Đĩa ép C1","text":"Ép đĩa ly hợp C1 khi càng đóng dài tác động.","keywords":["Đĩa ép C1"],"figure":{"image":"content/resources/T1_image96.jpg","caption":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","number":"2.28"}},{"id":"s369","kind":"part","lesson":"2.4.3","title":"Đĩa ly hợp C1","text":"Đĩa ma sát nối với trục đặc.","keywords":["Đĩa ly hợp C1"],"figure":{"image":"content/resources/T1_image96.jpg","caption":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","number":"2.28"}},{"id":"s370","kind":"part","lesson":"2.4.3","title":"Càng đóng ly hợp C1","text":"Nhận lực từ xi lanh con để tác động vào cơ cấu đóng C1.","keywords":["Càng đóng ly hợp C1"],"figure":{"image":"content/resources/T1_image96.jpg","caption":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","number":"2.28"}},{"id":"s371","kind":"part","lesson":"2.4.3","title":"Xi lanh con","text":"Dẫn động càng đóng ly hợp bằng thủy lực.","keywords":["Xi lanh con","xi lanh công tác"],"figure":{"image":"content/resources/T1_image96.jpg","caption":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","number":"2.28"}},{"id":"s372","kind":"part","lesson":"2.4.3","title":"Càng đóng ly hợp C2","text":"Càng đóng ngắn tác động vào cơ cấu đóng C2.","keywords":["Càng đóng ly hợp C2"],"figure":{"image":"content/resources/T1_image96.jpg","caption":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","number":"2.28"}},{"id":"s373","kind":"part","lesson":"2.4.3","title":"Đĩa ép C2","text":"Ép đĩa ly hợp C2 để nối mômen tới trục rỗng.","keywords":["Đĩa ép C2"],"figure":{"image":"content/resources/T1_image96.jpg","caption":"Hình 2.28 — Ly hợp kép ma sát khô: a) đóng C1; b) đóng C2","number":"2.28"}},{"id":"s374","kind":"figure","lesson":"2.4.3","title":"Hình 2.26. Đường truyền lực khi ly hợp ngoài C1 được tác động","text":"Hình 2.26. Đường truyền lực khi ly hợp ngoài C1 được tác động","anchor":"block-1781146278112-73eg6gsfw","figure":{"number":"2.26","caption":"Hình 2.26. Đường truyền lực khi ly hợp ngoài C1 được tác động"}},{"id":"s375","kind":"figure","lesson":"2.4.3","title":"Hình 2.27. Đường truyền lực khi ly hợp trong C2 được tác động","text":"Hình 2.27. Đường truyền lực khi ly hợp trong C2 được tác động","anchor":"block-1781146278112-73eg6gsfw","figure":{"number":"2.27","caption":"Hình 2.27. Đường truyền lực khi ly hợp trong C2 được tác động"}},{"id":"s376","kind":"html","lesson":"2.4.3","title":"Kết cấu hệ thống ly hợp kép · a. Ly hợp kép ma sát ướt","text":"1- Áp suất dầu từ nguồn cung cấp thủy lực; 2- Buồng áp suất; 3- Buồng cân bằng dầu; 4- Piston tác động. Đặc điểm cấu tạo của ly hợp kép ma sát ướt được thể hiện trên Hình 2.26 Hai ly hợp nhiều đĩa C1 và C2 nằm trong bể dầu. Ly hợp bên ngoài C1 và các đĩa bên trong được kết nối chặt với trục đặc; ly hợp bên trong C2 được nối với trục rỗng. Mỗi ly hợp có một piston tác động xoay với buồng áp suất và buồng cân bằng dầu và một đơn vị cung cấp thủy lực. Một số đặc điểm của ly hợp kép ma sát ướt: - Không cần hiệu chỉnh lại do mòn; - Tổn hao công suất do vận hành bơm. Để nối ly hợp, dầu thủy lực có áp được dẫn vào một trong các buồng áp suất nhờ bộ điều khiển thùy lực. Piston tác động ép các đĩa trong và ngoài vào nhau. Nối kết lực được hình thành và momen xoắn được truyền đi.","anchor":"block-1781146278112-73eg6gsfw"},{"id":"s377","kind":"html","lesson":"2.4.3","title":"Kết cấu hệ thống ly hợp kép · a. Ly hợp kép ma sát ướt","text":"Hình 2.26 mô tà đường truyền lực khi ly hợp bên ngoài C1 được kết nối, Hình 2.27 minh họa đường truyền lực khi ly hợp bên trong C2 được kết nối. 1- Áp suất dầu từ nguồn cung cấp thủy lực; 2- Buồng áp suất; 3- Buồng cân bằng dầu; 4- Piston tác động. Khi không có áp suất dầu, các ly hợp bị ngắt. Do lực ly tâm hình thành vì dầu chuyển động quay tròn, ly hợp đang bị ngắt có thể tự kết nối ở tốc độ quay động cơ cao. Vì vậy, các buồng chứa dầu cân bằng không có áp suất được bố trí phía sau các piston tác động. Lực ly tâm trong buồng cân bằng dầu tác động ngược lại các lực ly tâm trong buồng áp suất và cân bằng các lực này. Quá trình làm mát dầu như sau: Dầu được đưa vào ly hợp nhiều đĩa thông qua mạch bơm có điều chinh với bộ làm mát dầu. Nhờ các van điều tiết và van hút, bơm dầu được điều chỉnh theo yêu cầu.","anchor":"block-1781146278112-73eg6gsfw"},{"id":"s378","kind":"figure","lesson":"2.4.3","title":"Hình 2.28. Sơ đồ cấu tạo ly hợp kép ma sát khô với sự tác động bằng điện thủy lực","text":"Hình 2.28. Sơ đồ cấu tạo ly hợp kép ma sát khô với sự tác động bằng điện thủy lực","anchor":"block-1781146317920-6eh2iagmo","figure":{"number":"2.28","caption":"Hình 2.28. Sơ đồ cấu tạo ly hợp kép ma sát khô với sự tác động bằng điện thủy lực"}},{"id":"s379","kind":"figure","lesson":"2.4.3","title":"Hình 2.29. Vòng căng giữa bánh đà và ly hợp kép","text":"Hình 2.29. Vòng căng giữa bánh đà và ly hợp kép","anchor":"block-1781146317920-6eh2iagmo","figure":{"number":"2.29","caption":"Hình 2.29. Vòng căng giữa bánh đà và ly hợp kép"}},{"id":"s380","kind":"html","lesson":"2.4.3","title":"Kết cấu hệ thống ly hợp kép · b. Ly hợp kép ma sát khô","text":"Đặc điểm cấu tạo của ly hợp kép ma sát khô được thể hiện trên Hình 2.28. Hai đĩa ly hợp được bố trí song song; C1 được kết nối cố định với trục đặc, C2 được kết nối cố định với trục rỗng; Một đĩa dẫn động được đặt trên trục rỗng của trục hộp số; hai lò xo đĩa với SAC (tự hiệu chỉnh); hai đĩa ép; hai càng đóng ly hợp với ổ bi đóng ly hợp; hai xi lanh con. Một số đặc điểm của ly hợp kép ma sát khô như sau: - Được dùng trên các động cơ có Momen tới 250 Nm, do khả năng làm mát ly hợp kém; - Cần có cơ cấu hiệu chỉnh hao mòn (SAC); - Ít tổn hao năng lượng vì không cần bơm để tạo lực ép và làm mát cho ly hợp. Đối với ly hợp C1 ( Hình 2.28a): Ly hợp này có lò xo đĩa với đòn bẩy hai đầu. Khi càng đóng ly hợp dài được tác động, đĩa ép bên phải được ép vào đĩa dẫn động, C1 được nối. Đường truyền lực được truyền tới trục bên trong.","anchor":"block-1781146317920-6eh2iagmo"},{"id":"s381","kind":"html","lesson":"2.4.3","title":"Kết cấu hệ thống ly hợp kép · b. Ly hợp kép ma sát khô","text":"Đối với ly hợp C2 ( Hình 2.28b): Ly hợp này có lò xo đĩa với đòn bẩy một đầu. Khi càng đóng ly hợp ngắn được tác động, đĩa ép bên trái được ép vào đĩa dẫn động, C2 được nối. Đường truyền lực được truyền tới trục rỗng. Sự tác động ở cả hai ly hợp C1 và C2 được thực hiện thông qua 2 xi lanh con được kích hoạt bởi van điện từ. Áp suất dầu cần thiết được lấy từ bộ truyền động điện-thủy lực hoặc theo yêu cầu từ một máy bơm riêng. Hai bộ hiệu chỉnh hoạt động theo nguyên lý SAC được cài đặt trên hai ly hợp. Nhờ vậy lực ngắt không đổi cũng như hành trình đóng ly hợp ngắn và cố định được duy trì. Việc kết nối giữa bánh đà và ly hợp kép: Việc kết nối được thực hiện thông qua hai vành răng ăn khớp vào nhau. Để ngăn cản tiếng ồn và khe hở giữa các profin răng, một vòng căng được lắp giữa các vành răng để không còn khe hở ( Hình 2.29).","anchor":"block-1781146317920-6eh2iagmo"},{"id":"s382","kind":"lesson","lesson":"3.1.1","title":"Hộp số chính · Chức năng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Chức năng."},{"id":"s383","kind":"simulation","lesson":"3.1.1","title":"Nguyên lý: Chức năng","text":"1. Nhận mô men ở trục sơ cấp. Hộp số nhận mô men từ ly hợp. 2. Chọn cấp số truyền. Cặp bánh răng được chọn làm thay đổi mô men và tốc độ quay. 3. Truyền ra bánh xe chủ động. Đường truyền từ trục thứ cấp đi tới các cụm phía sau hộp số. 4. Chuyển về số trung gian khi cần ngắt. Số trung gian cho phép ngắt dòng truyền lực lâu dài khi động cơ vẫn làm việc."},{"id":"s384","kind":"figure","lesson":"3.1.1","title":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","text":"A. Trục sơ cấp. Nhận mô men từ ly hợp, mang bánh răng liền trục sơ cấp. B. Trục thứ cấp. Truyền mô men ra khỏi hộp số. C. Trục trung gian. Mang các bánh răng truyền trung gian. D. Khớp đồng tốc gài số 3,4. Gài bánh răng số 3 hoặc nối trực tiếp trục sơ cấp với trục thứ cấp. E. Bánh răng gài số lùi. Tham gia đường truyền đảo chiều quay của trục thứ cấp.","figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s385","kind":"part","lesson":"3.1.1","title":"Trục sơ cấp","text":"Nhận mô men từ ly hợp, mang bánh răng liền trục sơ cấp.","keywords":["Trục sơ cấp"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s386","kind":"part","lesson":"3.1.1","title":"Trục thứ cấp","text":"Truyền mô men ra khỏi hộp số.","keywords":["Trục thứ cấp"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s387","kind":"part","lesson":"3.1.1","title":"Trục trung gian","text":"Mang các bánh răng truyền trung gian.","keywords":["Trục trung gian"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s388","kind":"part","lesson":"3.1.1","title":"Khớp đồng tốc gài số 3,4","text":"Gài bánh răng số 3 hoặc nối trực tiếp trục sơ cấp với trục thứ cấp.","keywords":["Khớp đồng tốc gài số 3,4"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s389","kind":"part","lesson":"3.1.1","title":"Bánh răng gài số lùi","text":"Tham gia đường truyền đảo chiều quay của trục thứ cấp.","keywords":["Bánh răng gài số lùi"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s390","kind":"html","lesson":"3.1.1","title":"Hộp số chính · Chức năng","text":"Thay đổi lực kéo tiếp tuyến và số vòng quay của bánh xe chủ động để phù hợp với lực cản của đường và vận tốc của ôtô theo nhu cầu sử dụng. Thực hiện chuyển động lùi cho ôtô. Có thể ngắt dòng truyền lực trong thời gian dài khi động cơ vẫn làm việc.","anchor":"block-1781146415111-szni1qjv5"},{"id":"s391","kind":"lesson","lesson":"3.1.2","title":"Hộp số chính · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân loại hộp số."},{"id":"s392","kind":"simulation","lesson":"3.1.2","title":"Trình tự phân loại hộp số","text":"1. Xét trạng thái trục. Phân biệt trục cố định với trục di động. 2. Đếm số trục chính. Phân biệt hai trục, ba trục hoặc hai trục bị động theo sơ đồ. 3. Xét số cấp số truyền. Số cấp truyền là một tiêu chí khác số trục. 4. Xét phương pháp điều khiển. Kết luận từng tiêu chí riêng: bằng tay hay tự động."},{"id":"s393","kind":"figure","lesson":"3.1.2","title":"Phân loại hộp số chính — sơ đồ học tập biên soạn từ bài 3.1.2","text":"A. Trục cố định. Một dạng phân loại theo đặc điểm bố trí trục hộp số. B. Trục di động. Các trục bánh răng hành tinh có thể di động theo cần dẫn. C. Hộp số hai trục. Có hai trục chính theo cách phân loại trong bài. D. Hộp số ba trục. Có trục chủ động, trục bị động và trục trung gian.","figure":{"image":"tuong_tac/diagrams/gearclasses.svg","caption":"Phân loại hộp số chính — sơ đồ học tập biên soạn từ bài 3.1.2"}},{"id":"s394","kind":"part","lesson":"3.1.2","title":"Trục cố định","text":"Một dạng phân loại theo đặc điểm bố trí trục hộp số.","keywords":["Trục cố định"],"figure":{"image":"tuong_tac/diagrams/gearclasses.svg","caption":"Phân loại hộp số chính — sơ đồ học tập biên soạn từ bài 3.1.2"}},{"id":"s395","kind":"part","lesson":"3.1.2","title":"Trục di động","text":"Các trục bánh răng hành tinh có thể di động theo cần dẫn.","keywords":["Trục di động"],"figure":{"image":"tuong_tac/diagrams/gearclasses.svg","caption":"Phân loại hộp số chính — sơ đồ học tập biên soạn từ bài 3.1.2"}},{"id":"s396","kind":"part","lesson":"3.1.2","title":"Hộp số hai trục","text":"Có hai trục chính theo cách phân loại trong bài.","keywords":["Hộp số hai trục"],"figure":{"image":"tuong_tac/diagrams/gearclasses.svg","caption":"Phân loại hộp số chính — sơ đồ học tập biên soạn từ bài 3.1.2"}},{"id":"s397","kind":"part","lesson":"3.1.2","title":"Hộp số ba trục","text":"Có trục chủ động, trục bị động và trục trung gian.","keywords":["Hộp số ba trục"],"figure":{"image":"tuong_tac/diagrams/gearclasses.svg","caption":"Phân loại hộp số chính — sơ đồ học tập biên soạn từ bài 3.1.2"}},{"id":"s398","kind":"figure","lesson":"3.1.2","title":"Hình 3.1. Trạng thái trục hộp số","text":"Hình 3.1. Trạng thái trục hộp số","anchor":"block-1781146424278-4aehjz4m2","figure":{"number":"3.1","caption":"Hình 3.1. Trạng thái trục hộp số"}},{"id":"s399","kind":"html","lesson":"3.1.2","title":"Phân loại · a. Theo trạng thái của trục hộp số trong quá trình làm việc","text":"Hộp số có trục di động (hộp số hành tinh)","anchor":"block-1781146424278-4aehjz4m2"},{"id":"s400","kind":"figure","lesson":"3.1.2","title":"Hình 3.2. Số lượng trục trong hộp số (2 trục, 3 trục, 2 trục bị động)","text":"Hình 3.2. Số lượng trục trong hộp số (2 trục, 3 trục, 2 trục bị động)","anchor":"block-1781146472253-ozt17qsh4","figure":{"number":"3.2","caption":"Hình 3.2. Số lượng trục trong hộp số (2 trục, 3 trục, 2 trục bị động)"}},{"id":"s401","kind":"html","lesson":"3.1.2","title":"Phân loại · b. Theo số trục của hộp số (không kể trục số lùi)","text":"Hộp số hai trục (trục chủ động, trục bị động); Hộp số ba trục (trục chủ động, trục bị động, trục trung gian)","anchor":"block-1781146472253-ozt17qsh4"},{"id":"s402","kind":"figure","lesson":"3.1.2","title":"Hình 3.3. Các phương pháp điều khiển.","text":"Hình 3.3. Các phương pháp điều khiển.","anchor":"block-1781146531353-xn6sfzhl2","figure":{"number":"3.3","caption":"Hình 3.3. Các phương pháp điều khiển."}},{"id":"s403","kind":"html","lesson":"3.1.2","title":"Phân loại · c. Phân loại theo phương pháp dẫn động điều khiển hộp số","text":"Điều khiển bằng tay; Điều khiển tự động; Điều khiển bán tự động Hình 3.3. Các phương pháp điều khiển.","anchor":"block-1781146531353-xn6sfzhl2"},{"id":"s404","kind":"figure","lesson":"3.1.2","title":"Hình 3.4. Hộp số vô cấp","text":"Hình 3.4. Hộp số vô cấp","anchor":"block-1781146572059-uvpkf33kw","figure":{"number":"3.4","caption":"Hình 3.4. Hộp số vô cấp"}},{"id":"s405","kind":"html","lesson":"3.1.2","title":"Phân loại · d. Theo số lượng truyền","text":"5 cấp, 6 cấp, 8, 9, 10, 12, 18 cấp…vô cấp…","anchor":"block-1781146572059-uvpkf33kw"},{"id":"s406","kind":"lesson","lesson":"3.2.1","title":"Hộp số chính · Một số ký hiệu vẽ quy ước","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự đọc ký hiệu vẽ quy ước."},{"id":"s407","kind":"simulation","lesson":"3.2.1","title":"Trình tự đọc ký hiệu vẽ quy ước","text":"1. Xác định ký hiệu trục và bánh răng. Đọc phần biểu diễn liên kết thay vì chỉ nhìn hình dáng. 2. Kiểm tra khả năng quay tương đối. Lắp cố định quay cùng trục; quay trơn cho phép quay tương đối. 3. Kiểm tra khả năng trượt dọc trục. Bánh răng lắp trượt then hoa có thể dịch chuyển dọc trục. 4. Đối chiếu cơ cấu gài hoặc đồng tốc. Chỉ kết luận đường truyền khi cơ cấu gài nối đúng phần tử."},{"id":"s408","kind":"figure","lesson":"3.2.1","title":"Kiểu liên kết bánh răng với trục — sơ đồ học tập biên soạn từ bài 3.2.1","text":"A. Bánh răng lắp cố định với trục. Bánh răng quay cùng trục, không trượt dọc trục. B. Bánh răng trượt dọc trên trục. Liên kết bằng then hoa cho phép dịch chuyển theo đường trục. C. Bánh răng quay trơn. Chưa bị cố định với trục nếu cơ cấu gài chưa nối. D. Bộ đồng tốc. Giúp cân bằng tốc độ và nối bánh răng được chọn với trục.","figure":{"image":"tuong_tac/diagrams/gearsymbols.svg","caption":"Kiểu liên kết bánh răng với trục — sơ đồ học tập biên soạn từ bài 3.2.1"}},{"id":"s409","kind":"part","lesson":"3.2.1","title":"Bánh răng lắp cố định với trục","text":"Bánh răng quay cùng trục, không trượt dọc trục.","keywords":["Bánh răng lắp cố định với trục"],"figure":{"image":"tuong_tac/diagrams/gearsymbols.svg","caption":"Kiểu liên kết bánh răng với trục — sơ đồ học tập biên soạn từ bài 3.2.1"}},{"id":"s410","kind":"part","lesson":"3.2.1","title":"Bánh răng trượt dọc trên trục","text":"Liên kết bằng then hoa cho phép dịch chuyển theo đường trục.","keywords":["Bánh răng trượt dọc trên trục"],"figure":{"image":"tuong_tac/diagrams/gearsymbols.svg","caption":"Kiểu liên kết bánh răng với trục — sơ đồ học tập biên soạn từ bài 3.2.1"}},{"id":"s411","kind":"part","lesson":"3.2.1","title":"Bánh răng quay trơn","text":"Chưa bị cố định với trục nếu cơ cấu gài chưa nối.","keywords":["Bánh răng quay trơn"],"figure":{"image":"tuong_tac/diagrams/gearsymbols.svg","caption":"Kiểu liên kết bánh răng với trục — sơ đồ học tập biên soạn từ bài 3.2.1"}},{"id":"s412","kind":"part","lesson":"3.2.1","title":"Bộ đồng tốc","text":"Giúp cân bằng tốc độ và nối bánh răng được chọn với trục.","keywords":["Bộ đồng tốc"],"figure":{"image":"tuong_tac/diagrams/gearsymbols.svg","caption":"Kiểu liên kết bánh răng với trục — sơ đồ học tập biên soạn từ bài 3.2.1"}},{"id":"s413","kind":"figure","lesson":"3.2.1","title":"Hình 3.6. Bánh răng lắp cố định với trục","text":"Hình 3.6. Bánh răng lắp cố định với trục","anchor":"block-1781146788535-26k2i7auf","figure":{"number":"3.6","caption":"Hình 3.6. Bánh răng lắp cố định với trục"}},{"id":"s414","kind":"html","lesson":"3.2.1","title":"Một số ký hiệu vẽ quy ước · a. Bánh răng lắp cố định với trục","text":"Bánh răng và trục lắp cứng với nhau, khi trục quay thì bánh răng quay theo.","anchor":"block-1781146788535-26k2i7auf"},{"id":"s415","kind":"figure","lesson":"3.2.1","title":"Hình 3.7. Bánh răng trượt dọc trên trục","text":"Hình 3.7. Bánh răng trượt dọc trên trục","anchor":"block-1781146809430-mtl79jvwu","figure":{"number":"3.7","caption":"Hình 3.7. Bánh răng trượt dọc trên trục"}},{"id":"s416","kind":"html","lesson":"3.2.1","title":"Một số ký hiệu vẽ quy ước · b. Bánh răng trượt dọc trên trục","text":"Bánh răng quay theo trục, đồng thời có thể bánh răng dịch chuyển dọc trên trục theo khớp then hoa.","anchor":"block-1781146809430-mtl79jvwu"},{"id":"s417","kind":"figure","lesson":"3.2.1","title":"Hình 3.8. Bánh răng quay trơn","text":"Hình 3.8. Bánh răng quay trơn","anchor":"block-1781146852516-bakcha6hv","figure":{"number":"3.8","caption":"Hình 3.8. Bánh răng quay trơn"}},{"id":"s418","kind":"html","lesson":"3.2.1","title":"Một số ký hiệu vẽ quy ước · c. Loại bánh răng lắp trơn trên trục","text":"Hình 3.8. Bánh răng quay trơn","anchor":"block-1781146852516-bakcha6hv"},{"id":"s419","kind":"figure","lesson":"3.2.1","title":"Hình 3.9. Bộ đồng tốc loại 1 vành côn ma sát","text":"Hình 3.9. Bộ đồng tốc loại 1 vành côn ma sát","anchor":"block-1781146877045-6iqj5f6ga","figure":{"number":"3.9","caption":"Hình 3.9. Bộ đồng tốc loại 1 vành côn ma sát"}},{"id":"s420","kind":"figure","lesson":"3.2.1","title":"Hình 3.10. Bánh răng ăn khớp","text":"Hình 3.10. Bánh răng ăn khớp","anchor":"block-1781146877045-6iqj5f6ga","figure":{"number":"3.10","caption":"Hình 3.10. Bánh răng ăn khớp"}},{"id":"s421","kind":"figure","lesson":"3.2.1","title":"Hình 3.11. Bố trí số lùi","text":"Hình 3.11. Bố trí số lùi","anchor":"block-1781146877045-6iqj5f6ga","figure":{"number":"3.11","caption":"Hình 3.11. Bố trí số lùi"}},{"id":"s422","kind":"html","lesson":"3.2.1","title":"Một số ký hiệu vẽ quy ước · d. Bộ đồng tốc và ống gài","text":"Tỷ số truyền =$/frac{Số/ răng/ bánh/ răng/ bị/ động}{Số/ răng/ bánh/ răng/ chủ/ động} = /frac{Số/ vòng/ quay/ bánh/ răng/ chủ/ động}{Số/ vòng/ quay/ bánh/ răng/ bị/ động}$ Giữa 2 trục (2 bánh răng) ăn khớp, bố trí 1 bánh răng trung gian để làm thay đổi chiều quay của trục thứ cấp. Do đó chiều quay của trục thứ cấp sẽ quay ngược chiều.","anchor":"block-1781146877045-6iqj5f6ga"},{"id":"s423","kind":"lesson","lesson":"3.2.2","title":"Hộp số chính · Hộp số 3 trục","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích các đường truyền của hộp số 3 trục."},{"id":"s424","kind":"note","lesson":"3.2.2","title":"Đường truyền số truyền thẳng","text":"Hộp số ba trục trong ví dụ có thể nối trục sơ cấp với thứ cấp để tạo số truyền thẳng. Cách đó không tồn tại nguyên dạng ở hộp số hai trục. Tỷ số truyền bằng 1 không đồng nghĩa mọi cặp bánh răng trong hộp số ngừng quay."},{"id":"s425","kind":"simulation","lesson":"3.2.2","title":"Các đường truyền của hộp số 3 trục","text":"1. Số trung gian. Các khớp gài chưa nối bánh răng được chọn với trục thứ cấp. 2. Gài một số tiến gián tiếp. Mô men qua trục sơ cấp, trục trung gian và cặp bánh răng được chọn tới trục thứ cấp. 3. Gài số truyền thẳng. Khớp gài nối trục sơ cấp trực tiếp với trục thứ cấp; tỷ số truyền bằng 1. 4. Gài số lùi. Bánh răng trung gian số lùi tham gia đường truyền để đảo chiều trục thứ cấp."},{"id":"s426","kind":"figure","lesson":"3.2.2","title":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","text":"A. Trục sơ cấp. Nhận mô men từ ly hợp, mang bánh răng liền trục sơ cấp. B. Trục thứ cấp. Truyền mô men ra khỏi hộp số. C. Trục trung gian. Mang các bánh răng truyền trung gian. D. Khớp đồng tốc gài số 3,4. Gài bánh răng số 3 hoặc nối trực tiếp trục sơ cấp với trục thứ cấp. E. Bánh răng gài số lùi. Tham gia đường truyền đảo chiều quay của trục thứ cấp.","figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s427","kind":"part","lesson":"3.2.2","title":"Trục sơ cấp","text":"Nhận mô men từ ly hợp, mang bánh răng liền trục sơ cấp.","keywords":["Trục sơ cấp"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s428","kind":"part","lesson":"3.2.2","title":"Trục thứ cấp","text":"Truyền mô men ra khỏi hộp số.","keywords":["Trục thứ cấp"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s429","kind":"part","lesson":"3.2.2","title":"Trục trung gian","text":"Mang các bánh răng truyền trung gian.","keywords":["Trục trung gian"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s430","kind":"part","lesson":"3.2.2","title":"Khớp đồng tốc gài số 3,4","text":"Gài bánh răng số 3 hoặc nối trực tiếp trục sơ cấp với trục thứ cấp.","keywords":["Khớp đồng tốc gài số 3,4"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s431","kind":"part","lesson":"3.2.2","title":"Bánh răng gài số lùi","text":"Tham gia đường truyền đảo chiều quay của trục thứ cấp.","keywords":["Bánh răng gài số lùi"],"figure":{"image":"content/resources/T1_image127.jpg","caption":"Hình 3.13 — Sơ đồ hộp số 3 trục 5 cấp số","number":"3.13"}},{"id":"s432","kind":"figure","lesson":"3.2.2","title":"Hình 3.12. Sơ đồ hộp số 3 trục 4 cấp số","text":"Hình 3.12. Sơ đồ hộp số 3 trục 4 cấp số","anchor":"block-1781147109554-uhu3qtjmv","figure":{"number":"3.12","caption":"Hình 3.12. Sơ đồ hộp số 3 trục 4 cấp số"}},{"id":"s433","kind":"figure","lesson":"3.2.2","title":"Hình 3.13. Sơ đồ hộp số 3 trục 5 cấp số","text":"Hình 3.13. Sơ đồ hộp số 3 trục 5 cấp số","anchor":"block-1781147109554-uhu3qtjmv","figure":{"number":"3.13","caption":"Hình 3.13. Sơ đồ hộp số 3 trục 5 cấp số"}},{"id":"s434","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · a. Cấu tạo","text":"1-Trục sơ cấp; 2-Bánh răng liền trục sơ cấp; 3-Khớp đồng tốc gài số 3,4; 4-Bánh răng số 3; 5- Bánh răng số 2; 6- Khớp đồng tốc gài số 1,2; 7- Vành răng số lùi liền khớp 6; 8- Bánh răng số 1; 9- Bánh răng số 5 cố định trên trục thứ cấp; 10- Trục thứ cấp; 11- Khớp đồng tốc gài số 5; 12- Bánh răng quay trơn trên trục 18 (chủ động số 5 ); 13, 14, 16, 17; 19- Bánh răng (liền trục 18); 15-Bánh răng gài số lùi; 18- Trục trung gian.","anchor":"block-1781147109554-uhu3qtjmv"},{"id":"s435","kind":"figure","lesson":"3.2.2","title":"Hình 3.14. Đi số 1","text":"Hình 3.14. Đi số 1","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.14","caption":"Hình 3.14. Đi số 1"}},{"id":"s436","kind":"figure","lesson":"3.2.2","title":"Hình 3.15. Đi số 2","text":"Hình 3.15. Đi số 2","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.15","caption":"Hình 3.15. Đi số 2"}},{"id":"s437","kind":"figure","lesson":"3.2.2","title":"Hình 3.16. Đi số 3","text":"Hình 3.16. Đi số 3","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.16","caption":"Hình 3.16. Đi số 3"}},{"id":"s438","kind":"figure","lesson":"3.2.2","title":"Hình 3.17. Đi số 4","text":"Hình 3.17. Đi số 4","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.17","caption":"Hình 3.17. Đi số 4"}},{"id":"s439","kind":"figure","lesson":"3.2.2","title":"Hình 3.18. Đi số 5","text":"Hình 3.18. Đi số 5","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.18","caption":"Hình 3.18. Đi số 5"}},{"id":"s440","kind":"figure","lesson":"3.2.2","title":"Hình 3.19. Đi số lùi","text":"Hình 3.19. Đi số lùi","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.19","caption":"Hình 3.19. Đi số lùi"}},{"id":"s441","kind":"figure","lesson":"3.2.2","title":"Hình 3.20. Hộp số xe ZIL-131","text":"Hình 3.20. Hộp số xe ZIL-131","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.20","caption":"Hình 3.20. Hộp số xe ZIL-131"}},{"id":"s442","kind":"figure","lesson":"3.2.2","title":"Hình 3.21. Hộp số xe GAZ – 66","text":"Hình 3.21. Hộp số xe GAZ – 66","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.21","caption":"Hình 3.21. Hộp số xe GAZ – 66"}},{"id":"s443","kind":"figure","lesson":"3.2.2","title":"Hình 3.22. Mặt cắt dọc hộp số xe URAL","text":"Hình 3.22. Mặt cắt dọc hộp số xe URAL","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.22","caption":"Hình 3.22. Mặt cắt dọc hộp số xe URAL"}},{"id":"s444","kind":"figure","lesson":"3.2.2","title":"Hình 3.23. Hộp số Kraz 255B","text":"Hình 3.23. Hộp số Kraz 255B","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.23","caption":"Hình 3.23. Hộp số Kraz 255B"}},{"id":"s445","kind":"figure","lesson":"3.2.2","title":"Hình 3.24. Sơ đồ hộp số 10 cấp số","text":"Hình 3.24. Sơ đồ hộp số 10 cấp số","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.24","caption":"Hình 3.24. Sơ đồ hộp số 10 cấp số"}},{"id":"s446","kind":"figure","lesson":"3.2.2","title":"Hình 3.25. Kết cấu hộp số KAMAZ 5320","text":"Hình 3.25. Kết cấu hộp số KAMAZ 5320","anchor":"block-1781147139469-ph4xu9lrv","figure":{"number":"3.25","caption":"Hình 3.25. Kết cấu hộp số KAMAZ 5320"}},{"id":"s447","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"Hộp số của động cơ đặt dọc được sử dụng phổ biến hiện nay là loại hộp số 5 cấp số như minh họa ở hình trên. Sau đây trình bày nguyên tắc hoạt động của một hộp số dọc năm cấp số. Cắt ly hợp, gạt khớp trượt 6 sang phải cho ăn khớp với vành răng đầu mayơ của bánh răng 8. Tốc độ ra ở cấp số truyền này giảm, mô men tăng. Tỷ số truyền ở tay số 1: $/mathbf{i}_{/mathbf{1}}/mathbf{=}/frac{/mathbf{Z}_{/mathbf{19}}}{/mathbf{Z}_{/mathbf{2}}}/frac{/mathbf{Z}_{/mathbf{8}}}{/mathbf{Z}_{/mathbf{13}}}/mathbf{> 1}$ Cắt ly hợp, gạt khớp gài 6 sang trái cho ăn khớp với vành răng đầu mayơ của bánh răng 5. Lúc này trục thứ cấp quay cùng bánh răng 5. Sơ đồ truyền động thể hiện ở hình dưới.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s448","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"Tốc độ ra của cấp số truyền này giảm, mô men tăng. $i_{2} = /frac{Z_{19}}{Z_{2}}/frac{Z_{5}}{Z_{16}} > 1$ Cắt ly hợp, gạt khớp gài 6 về vị trí trung gian, sau đó gạt khớp gài 3 sang phải ăn khớp với vành răng đầu moay-ơ của bánh răng 4. Lúc này, trục thứ cấp quay cùng bánh răng 4. Sơ đồ truyền động thể hiện ở hình dưới. Tốc độ ra ở cấp số truyền này giảm, momen tăng. $i_{3} = /frac{Z_{19}}{Z_{2}}/frac{Z_{4}}{Z_{17}} > 1$ Cắt ly hợp, gạt khớp gài 3 sang trái ăn khớp với vành răng ở đầu trục sơ cấp. Trục thứ cấp có cùng tốc độ và mômen với trục sơ cấp. Tỷ số truyền của số 4 là: i4= 1. Cắt ly hợp, gạt khớp gài 3 về vị trí trung gian, sau đó gạt khớp gài 11 sang trái ăn khớp với vành răng đầu mayơ của bánh răng 12. Lúc này, bánh răng 12 quay cùng trục trung gian và truyền chuyển động sang bánh răng 9 làm trục thứ cấp quay.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s449","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"Sơ đồ truyền động thể hiện ở hình dưới. $i_{5} = /frac{Z_{19}}{Z_{2}}/frac{Z_{9}}{Z_{12}} < 1$ . nên số 5 gọi là số truyền tăng, tức là trục thứ cấp quay nhanh hơn trục sơ cấp. Ở chế độ này, tất cả các khớp gài số tiến phải nằm ở vị trí trung gian, gạt bánh răng cài số lùi 15 vào vị trí ăn khớp với bánh răng 14 trên trục sơ cấp và vành răng 7 trên khớp gài ở trục thứ cấp. Lúc này, truyền động từ trục trung gian đến trục thứ cấp được thực hiện nhờ 3 bánh răng ăn khớp14 – 15 – 7(không phải 2 như các số tiến) nên làm trục thứ cấp quay theo chiều ngược lại với các trường hợp số tiến. $i_{R} = - /frac{Z_{19}}{Z_{2}}/frac{Z_{6}}{Z_{14}} < 0$ Trên ô tô Zil –130, Zil –131 sử dụng loại hộp số cơ khí 3 trục có 5 cấp số tiến, 1 cấp số lùi, số 5 là số truyền thẳng.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s450","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"Trục làm liền với bánh răng chủ động và được lắp quay trên hai ổ bi cầu, một lỗ ở lỗ tâm trục khuỷu và một ổ trên vỏ hộp số. Trên bánh răng có lỗ hướng kính để thoát dầu bôi trơn trong ỗ đỡ đầu trục bị động và mặt côn, vành răng phụ để gài số 5 bằng bộ đồng tốc. Trục lắp quay trơn trên một ổ lăn trụ ở lỗ tâm trục chủ động và một ổ bi cầu ở vỏ hộp số. Trên trục có lắp di trượt bánh răng (12) và bộ đồng tốc (4), (9) bằng then hoa, các bánh răng (5), (6), (10) được lắp quay trơn trên trục. Ở các bánh răng (5), (6), (10) có lỗ hướng kính để hứng dầu bôi trơn và vành răng phụ, mặt côn để gài số bằng bộ đồng tốc. Các bộ đồng tốc (4) (gài số 4 –5) và (9) (gài số 2 -3) là loại đồng tốc quán tính chốt dọc trục. Trục lắp quay trơn trên một ổ lăn trụ và một số ổ bi cầu ở vỏ hộp số, bánh răng số 1 được làm liền trục.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s451","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"Các bánh răng (21), (22), (23), (24) được lắp chặt với trục bằng then bán nguyệt. Loại đồng tốc quán tính hoàn toàn có phần tử khóa dạng chốt dọc trục. Ưu điểm của loại đồng tốc này là kết cấu đơn giản, đảm bảo ra vào số nhẹ nhàng êm dịu. 1-Trục sơ cấp; 2-ổ bi trục sơ cấp; 3-Nắp ổ trục sơ cấp; 4-Đồng tốc số 4 và số 5;5 và 23 - Cặp bánh răng số truyền 4; 6 và 22-Cặp bánh răng số truyền 3; 7-Càng gài số truyền 4 và 5; 8-Càng gài số truyền 2 và 3; 9- Đồng tốc của số truyền 2 và 3; 10-Lò xo định vị; 11-Càng gài số truyền 1 và số lùi; 12- Bánh răng gài số 1 và số lùi; 13-Ổ đỡ trục thứ cấp trên vỏ hộp số; 14 – Lỗ thông hơi; 16- Bích trục truyền các đăng; 17- Ổ đỡ trục trung gian trên vỏ hộp số; 18- Vỏ hộp số (phần đáy các te); 19-Trục thứ cấp (trục bị động); 20-Bánh răng số 1; 21- Bánh răng đi số lùi; 24- Bánh thường tiếp dẫn động cho trục trung gian.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s452","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"Hộp số xe Gaz 66 là hộp số 3 trục, 4 cấp số. Kết cấu hộp số tương tự hộp số xe Zil 130, 131. Bộ đồng tốc (4) là loại đồng tốc quán tính chốt con chạy. Các bánh răng lắp đồng trục với bộ đồng tốc trên trục bị động, quay trơn trơn trục. Các bánh răng trên trục trung gian được chế tạo liền với nhau. Trục trung gian được quay trên 2 ổ đỡ nằm ở vỏ hộp số.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s453","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"Bánh răng di trượt D gài số 1 và số lùi 1 – Trục sơ cấp; 2 – Nắp ổ; 3 - Ổ bi trục sơ cấp; 4 – Moay ơ đồng tốc; 5 – Khớp đồng tốc; 6 – Càng gạt đồng tốc gài số III và số IV; 7 – Lò xo; 8 – Tay gài số; 9 – Chụp cao su bảo vệ; 10 – Càng gài số I và số II; 11 - Ổ bi trục thứ cấp; 12 – Nắp ổ; 13 – Mặt bích; 14 – Trục thứ cấp; 15 - Ống lót; 16 – Trục trung gian; 17 – Đai ốc hãm; 18 – Nắp ổ; 19 – Trục khối bánh răng số lùi; 20 – Khối bánh răng số lùi; 21 Tấm giữ chất bẩn; 22 - Ổ đỡ trục trung gian 1 – Ổ bi; 2 – Vòng chặn dầu; 3 – Trục sơ cấp; 4 – Ổ thanh lăn trục; 5 – Bánh răng trục sơ cấp; 6 – Đồng tốc số truyền 4 và 5; 7 – Cần gài số; 8 – Khối bánh răng số lùi; 9 – Chốt tỳ hình cầu của cần gài số; 10 – Càng gài số truyền 2 và 3; 11 - Bánh răng số truyền 5 trên trục thứ cấp; 12 - Bánh răng số truyền 3 trên trục thứ cấp; 13 - Đồng tốc số truyền 2 và 3; 14 - Bánh","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s454","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"răng số truyền 2 trên trục thứ cấp; 15 - Bánh răng số lùi trên trục thứ cấp; 16 - Khớp gài số truyền 1 và số lùi; 17 - Nắp vỏ hộp số; 18 - Ổ bi; 19 - Trục thứ cấp; 20 - Ổ thanh lăn trụ; 21 - Bánh răng số truyền II trên trục trung gian; 22 - Bánh răng số lùi trên trục trung gian; 23 - Nút tháo dầu; 24 - Bánh răng số truyền II trên trục trung gian; 25 - Bánh răng số truyền 3 trên trục trung gian; 26 - Bánh răng số truyền V trên trục trung gian; 27 - Trục trung gian; 28 - Vỏ hộp số; 29 - Bánh răng dẫn động trục trung gian; 30 - Ổ thanh lăn trụ; 31 - Vỏ ly hợp.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s455","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"1 - Trục sơ cấp; 2 – Bánh răng chủ động; 3 – Đồng tốc số truyền IV và V; 4 – Cần sang số; 5 – Lò xo định vị; 6 – Bánh răng bị động số truyền V; 7 – Bánh răng bị động số truyền III; 8 – Trục sang số; 9 – Đồng tốc số truyền II và III; 10 – Bánh răng bị động số truyền II; 11 – Nâng gạt bánh răng khi sang số; 12 – Bánh răng bị động số truyền I; 13 – Mặt bích; 14 – Trục thứ cấp; 15 – Trục trung gian; 16 – Nút xả dầu; 17 – Bánh răng trung gian số truyền I; 18 – Bánh răng trung gian số truyền II; 19 – Bộ phận lọc dầu bôi trơn; 20 – Bánh răng trung gian số truyền III; 21 – Bánh răng trung gian số truyền V; 22 – Bánh răng trích công suất; 23 – Bánh răng trung gian; 24 – Bơm dầu bôi trơn; 25 - Nạng gài số I và số lùi; 26 – Lò xo định vị cần sang số; 27 – Chốt; 28 – Nắp hộp số; 29 – Chốt khóa hãm; 30 – Bi khóa hãm; 31 – Vành răng bộ đồng tốc; 32 – Vành ma sát bộ đồng","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s456","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"tốc; 33 – Rãnh then hoa; 34 – Lò xo định vị; 35 – Trục số lùi; 36 – Cụm bánh răng số lùi Để tăng số cấp số của hộp số, ở một số loại hộp số được bố trí kết hợp giữa hộp số chính và hộp số phụ (hộp chia). Hộp số phụ có thể được đặt phía trước hộp số chính, hoặc được đặt phía sau hộp số chính. Trong sơ đồ a hộp số chính là hộp số 3 trục có 5 cấp số tiến và một cấp số lùi, hộp số phụ có 2 cấp số, kết hợp tạo thành hộp số có 10 cấp số tiến và 2 cấp số lùi. Trong sơ đồ b hộp số chính là hộp số 3 trục có 5 cấp số tiến và một cấp số lùi, hộp số phụ có 2 cấp số, kết hợp tạo thành hộp số có 10 cấp số tiến và 2 cấp số lùi. Hộp số nhiều cấp thường được sử dụng trên các loại ô tô vận tải có tải trọng trung bình và lớn, vì các loại ô tô này có tải trọng luôn thay đổi và có đặc tính động lực kém nên cần phải có nhiều cấp số truyền hơn.","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s457","kind":"html","lesson":"3.2.2","title":"Hộp số 3 trục · b. Nguyên lý làm việc","text":"1-Trục chủ động, 2-Trục chủ động của hộp số chính, 3-Trục trung gian, 4-Trục bị động, 5-Trục số lùi. 1 – Trục vào bộ chia số; 2 – Trục vào hộp số chính; 3 – Bánh răng số truyền tăng bộ chia số; 4 – Vành răng số truyền thẳng bộ chia số; 5 – Trục bị động; 6 – Đồng tốc số IV và số V; 7 – Bánh răng số truyền IV; 8 – Bánh răng số truyền III; 9 – Đồng tốc số II và III; 10 – Bánh răng số truyền II; 11 – Bánh răng số truyền I; 12 - Ống gài số I và số lùi; 13 – Bánh răng số lùi; 14 – Mặt bích lắp trục các đăng; 15 – Vít đo tốc độ; 16 – Trục trung gian","anchor":"block-1781147139469-ph4xu9lrv"},{"id":"s458","kind":"lesson","lesson":"3.2.3","title":"Hộp số chính · Hộp số 2 trục – transaxles","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích đường truyền trong hộp số hai trục."},{"id":"s459","kind":"simulation","lesson":"3.2.3","title":"Đường truyền trong hộp số hai trục","text":"1. Trục sơ cấp nhận mô men. Hộp số hai trục nhận mô men từ ly hợp. 2. Đồng tốc nối bánh răng được chọn. Cơ cấu gài cố định bánh răng của cấp số đã chọn với trục. 3. Cặp bánh răng truyền tới trục thứ cấp. Đường truyền qua cặp bánh răng ứng với cấp số, không qua trục trung gian như hộp số ba trục. 4. Truyền lực chính nhận đầu ra. Ở dạng transaxles, vỏ hộp số liền với vỏ truyền lực chính."},{"id":"s460","kind":"figure","lesson":"3.2.3","title":"Hình 3.26 — Hộp số hai trục trên dòng xe Kia, kiểu M5CF1","text":"A. Trục sơ cấp. Nhận mô men từ ly hợp, mang các bánh răng phía chủ động. B. Trục thứ cấp. Nhận mô men qua cặp bánh răng đã chọn và truyền tới truyền lực chính. C. Truyền lực chính. Nhận đầu ra hộp số; vỏ được bố trí liền với vỏ hộp số.","figure":{"image":"content/resources/T1_image140.jpg","caption":"Hình 3.26 — Hộp số hai trục trên dòng xe Kia, kiểu M5CF1","number":"3.26"}},{"id":"s461","kind":"part","lesson":"3.2.3","title":"Trục sơ cấp","text":"Nhận mô men từ ly hợp, mang các bánh răng phía chủ động.","keywords":["Trục sơ cấp"],"figure":{"image":"content/resources/T1_image140.jpg","caption":"Hình 3.26 — Hộp số hai trục trên dòng xe Kia, kiểu M5CF1","number":"3.26"}},{"id":"s462","kind":"part","lesson":"3.2.3","title":"Trục thứ cấp","text":"Nhận mô men qua cặp bánh răng đã chọn và truyền tới truyền lực chính.","keywords":["Trục thứ cấp"],"figure":{"image":"content/resources/T1_image140.jpg","caption":"Hình 3.26 — Hộp số hai trục trên dòng xe Kia, kiểu M5CF1","number":"3.26"}},{"id":"s463","kind":"part","lesson":"3.2.3","title":"Truyền lực chính","text":"Nhận đầu ra hộp số; vỏ được bố trí liền với vỏ hộp số.","keywords":["Truyền lực chính"],"figure":{"image":"content/resources/T1_image140.jpg","caption":"Hình 3.26 — Hộp số hai trục trên dòng xe Kia, kiểu M5CF1","number":"3.26"}},{"id":"s464","kind":"figure","lesson":"3.2.3","title":"Hình 3.26. Các kiểu hộp số 2 trục trên dòng xe Kia","text":"Hình 3.26. Các kiểu hộp số 2 trục trên dòng xe Kia","anchor":"block-1781147243533-v2ae9tn5l","figure":{"number":"3.26","caption":"Hình 3.26. Các kiểu hộp số 2 trục trên dòng xe Kia"}},{"id":"s465","kind":"html","lesson":"3.2.3","title":"Hộp số 2 trục – transaxles · a. Cấu tạo","text":"Hộp số đặt ngang thường là hộp số hai trục được sử dụng trên những ô tô có cầu trước chủ động và động cơ đặt phía trước, hoặc có cầu sau chủ động và động cơ đặt phía sau, vỏ hộp số được đúc liền với vỏ truyền lực chính.","anchor":"block-1781147243533-v2ae9tn5l"},{"id":"s466","kind":"figure","lesson":"3.2.3","title":"Hình 3.27. Đi số 1 | Hình 3.28. Đi số 2","text":"Hình 3.27. Đi số 1 | Hình 3.28. Đi số 2","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.27","caption":"Hình 3.27. Đi số 1 | Hình 3.28. Đi số 2"}},{"id":"s467","kind":"figure","lesson":"3.2.3","title":"Hình 3.27. Đi số 1","text":"Hình 3.27. Đi số 1","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.27","caption":"Hình 3.27. Đi số 1"}},{"id":"s468","kind":"figure","lesson":"3.2.3","title":"Hình 3.28. Đi số 2","text":"Hình 3.28. Đi số 2","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.28","caption":"Hình 3.28. Đi số 2"}},{"id":"s469","kind":"figure","lesson":"3.2.3","title":"Hình 3.29. Đi số 3 | Hình 3.30. Đi số 4","text":"Hình 3.29. Đi số 3 | Hình 3.30. Đi số 4","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.29","caption":"Hình 3.29. Đi số 3 | Hình 3.30. Đi số 4"}},{"id":"s470","kind":"figure","lesson":"3.2.3","title":"Hình 3.29. Đi số 3","text":"Hình 3.29. Đi số 3","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.29","caption":"Hình 3.29. Đi số 3"}},{"id":"s471","kind":"figure","lesson":"3.2.3","title":"Hình 3.30. Đi số 4","text":"Hình 3.30. Đi số 4","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.30","caption":"Hình 3.30. Đi số 4"}},{"id":"s472","kind":"figure","lesson":"3.2.3","title":"Hình 3.31. Đi số 5 | Hình 3.32. Đi số lùi","text":"Hình 3.31. Đi số 5 | Hình 3.32. Đi số lùi","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.31","caption":"Hình 3.31. Đi số 5 | Hình 3.32. Đi số lùi"}},{"id":"s473","kind":"figure","lesson":"3.2.3","title":"Hình 3.31. Đi số 5","text":"Hình 3.31. Đi số 5","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.31","caption":"Hình 3.31. Đi số 5"}},{"id":"s474","kind":"figure","lesson":"3.2.3","title":"Hình 3.32. Đi số lùi","text":"Hình 3.32. Đi số lùi","anchor":"block-1781147335532-4uuh28bxn","figure":{"number":"3.32","caption":"Hình 3.32. Đi số lùi"}},{"id":"s475","kind":"html","lesson":"3.2.3","title":"Hộp số 2 trục – transaxles · b. Nguyên lý làm việc","text":"Cũng tương tự như hộp số của động cơ đặt dọc, quá trình cài số và dòng truyền công suất của hộp số của động cơ đặt ngang được mô tả ở các hình bên dưới: Đi số 1: Dòng truyền lực từ trục sơ cấp đến cặp bánh răng số 1 -> Bộ đồng tốc số 1,2 đến trục thứ cấp. Đi số 2: Dòng truyền lực từ trục sơ cấp đến cặp bánh răng số 2 -> Bộ đồng tốc số 1,2 đến trục thứ cấp. Đi số 3: Dòng truyền lực từ trục sơ cấp đến cặp bánh răng số 3 -> Bộ đồng tốc số 3, 4 đến trục thứ cấp. Đi số 4: Dòng truyền lực từ trục sơ cấp đến cặp bánh răng số 4 -> Bộ đồng tốc số 3, 4 đến trục thứ cấp. Đi số 5: Dòng truyền lực từ trục sơ cấp đến cặp bánh răng số 5 -> Bộ đồng tốc số 5 đến trục thứ cấp. Đi số lùi: Dòng truyền lực từ trục sơ cấp đến cặp bánh răng số lùi.","anchor":"block-1781147335532-4uuh28bxn"},{"id":"s476","kind":"lesson","lesson":"3.2.4","title":"Hộp số chính · Cấu tạo bánh răng, trục, ổ đỡ","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quan hệ truyền lực và định vị trục."},{"id":"s477","kind":"simulation","lesson":"3.2.4","title":"Quan hệ truyền lực và định vị trục","text":"1. Bánh răng truyền mô men. Cặp bánh răng ăn khớp truyền mô men giữa các trục. 2. Trục tiếp nhận các tải tác dụng. Trục và ổ đỡ phải chịu các lực do ăn khớp gây ra. 3. Ổ đỡ cố định định vị hướng trục. Lực hướng trục được tiếp nhận ở ổ đỡ cố định. 4. Ổ đỡ di động bù giãn nở. Vòng được phép dịch chuyển giúp tránh căng cứng do giãn nở."},{"id":"s478","kind":"figure","lesson":"3.2.4","title":"Bánh răng, trục và ổ đỡ — sơ đồ học tập biên soạn từ bài 3.2.4","text":"A. Bánh răng trụ răng thẳng. Bánh răng răng thẳng được dùng ở bộ phận gài số lùi được mô tả. B. Bánh răng trụ răng nghiêng. Hoạt động êm hơn và phát sinh lực dọc trục. C. Ổ đỡ cố định. Chịu lực hướng trục và không được di động theo hướng trục. D. Ổ đỡ di động. Có một vòng được phép di động theo hướng trục để bù dung sai và giãn nở.","figure":{"image":"tuong_tac/diagrams/gearparts.svg","caption":"Bánh răng, trục và ổ đỡ — sơ đồ học tập biên soạn từ bài 3.2.4"}},{"id":"s479","kind":"part","lesson":"3.2.4","title":"Bánh răng trụ răng thẳng","text":"Bánh răng răng thẳng được dùng ở bộ phận gài số lùi được mô tả.","keywords":["Bánh răng trụ răng thẳng"],"figure":{"image":"tuong_tac/diagrams/gearparts.svg","caption":"Bánh răng, trục và ổ đỡ — sơ đồ học tập biên soạn từ bài 3.2.4"}},{"id":"s480","kind":"part","lesson":"3.2.4","title":"Bánh răng trụ răng nghiêng","text":"Hoạt động êm hơn và phát sinh lực dọc trục.","keywords":["Bánh răng trụ răng nghiêng"],"figure":{"image":"tuong_tac/diagrams/gearparts.svg","caption":"Bánh răng, trục và ổ đỡ — sơ đồ học tập biên soạn từ bài 3.2.4"}},{"id":"s481","kind":"part","lesson":"3.2.4","title":"Ổ đỡ cố định","text":"Chịu lực hướng trục và không được di động theo hướng trục.","keywords":["Ổ đỡ cố định"],"figure":{"image":"tuong_tac/diagrams/gearparts.svg","caption":"Bánh răng, trục và ổ đỡ — sơ đồ học tập biên soạn từ bài 3.2.4"}},{"id":"s482","kind":"part","lesson":"3.2.4","title":"Ổ đỡ di động","text":"Có một vòng được phép di động theo hướng trục để bù dung sai và giãn nở.","keywords":["Ổ đỡ di động"],"figure":{"image":"tuong_tac/diagrams/gearparts.svg","caption":"Bánh răng, trục và ổ đỡ — sơ đồ học tập biên soạn từ bài 3.2.4"}},{"id":"s483","kind":"figure","lesson":"3.2.4","title":"Hình 3.33. Bánh răng trong hộp số","text":"Hình 3.33. Bánh răng trong hộp số","anchor":"block-1781147453111-39fipmlyj","figure":{"number":"3.33","caption":"Hình 3.33. Bánh răng trong hộp số"}},{"id":"s484","kind":"html","lesson":"3.2.4","title":"Cấu tạo bánh răng, trục, ổ đỡ · a. Bánh răng","text":"Trong hộp số sử dụng hai loại bánh răng: Bánh răng trụ răng thẳng và bánh răng trụ răng nghiên. Bánh răng thẳng dùng trong bánh răng gài số lùi, vì nó ít làm việc và dùng cho việc cài số. Các bánh răng còn lại đều dùng bánh răng trụ răng nghiêng. Bánh răng của hộp số được làm từ thép chất lượng cao, chúng được tôi cẩn thận để tạo độ nhẵn, bề mặt các răng cứng, nhưng bên trong rất dẻo. Chúng được gia công nhiệt bề mặt. Các răng, các vùng nguy hiểm được gia công trên máy chính xác. Bánh răng trụ răng nghiên là loại cao cấp, chúng hoạt động êm dịu và khỏe hơn bởi vì khi các răng làm việc có nhiều răng tiếp xúc cùng một lúc. Bánh răng trụ răng nghiên phải được gắn vững chắc vì khi các răng làm việc xuất hiện lực dọc trục có xu hướng đẩy các bánh răng trượt theo trục. Khe hở dọc trục giữa các bánh răng và trục được chỉnh bằng cách sử dụng đệm đồng hay thép.","anchor":"block-1781147453111-39fipmlyj"},{"id":"s485","kind":"html","lesson":"3.2.4","title":"Cấu tạo bánh răng, trục, ổ đỡ · a. Bánh răng","text":"Một số đệm được lắp vào đầu của trục bánh răng giữa bánh răng di động và vỏ hộp số đứng yên. Phải có khe hở giữa các răng để cho phép bôi trơn, tháo lắp và sự sai khác về kích thước của các bánh răng. Khe hở này rất nhỏ.","anchor":"block-1781147453111-39fipmlyj"},{"id":"s486","kind":"figure","lesson":"3.2.4","title":"Hình 3.34. Trục chủ động hộp số ba trục","text":"Hình 3.34. Trục chủ động hộp số ba trục","anchor":"block-1781147484534-fvcy2z6i8","figure":{"number":"3.34","caption":"Hình 3.34. Trục chủ động hộp số ba trục"}},{"id":"s487","kind":"figure","lesson":"3.2.4","title":"Hình 3.35. Cụm bánh răng, trục chủ động trên hộp số 2 trục 02T Volkswagen","text":"Hình 3.35. Cụm bánh răng, trục chủ động trên hộp số 2 trục 02T Volkswagen","anchor":"block-1781147484534-fvcy2z6i8","figure":{"number":"3.35","caption":"Hình 3.35. Cụm bánh răng, trục chủ động trên hộp số 2 trục 02T Volkswagen"}},{"id":"s488","kind":"figure","lesson":"3.2.4","title":"Hình 3.36. Trục bị động hộp số 3 trục","text":"Hình 3.36. Trục bị động hộp số 3 trục","anchor":"block-1781147484534-fvcy2z6i8","figure":{"number":"3.36","caption":"Hình 3.36. Trục bị động hộp số 3 trục"}},{"id":"s489","kind":"figure","lesson":"3.2.4","title":"Hình 3.37. Cụm bánh răng, trục bị động trên hộp số 2 trục 02T Volkswagen","text":"Hình 3.37. Cụm bánh răng, trục bị động trên hộp số 2 trục 02T Volkswagen","anchor":"block-1781147484534-fvcy2z6i8","figure":{"number":"3.37","caption":"Hình 3.37. Cụm bánh răng, trục bị động trên hộp số 2 trục 02T Volkswagen"}},{"id":"s490","kind":"figure","lesson":"3.2.4","title":"Hình 3.38. Trục trung gian hộp số 3 trục","text":"Hình 3.38. Trục trung gian hộp số 3 trục","anchor":"block-1781147484534-fvcy2z6i8","figure":{"number":"3.38","caption":"Hình 3.38. Trục trung gian hộp số 3 trục"}},{"id":"s491","kind":"html","lesson":"3.2.4","title":"Cấu tạo bánh răng, trục, ổ đỡ · b. Trục","text":"Trục chủ động sơ cấp được đúc bằng thép liền khối với bánh răng chủ động. Phần trước có rãnh then hoa ráp vào moay-ơ đĩa ly hợp. Trục sơ cấp hộp số quay tựa trong vòng bi nơi vách trước vỏ hộp số và gối đầu vào trong vòng bi trung tâm đuôi trục khuỷu. Bánh răng đi số 1, 2 và số lùi được chế tạo liền với trục chủ động. Trên trục có phay rãnh dọc để ăn khớp then hoa với bộ đồng tốc. Các bánh răng gài số thì quay trơn trên trục qua ổ lăn kim hoặc bạc trượt. Hai đầu của trục tựa lên hai gối đỡ ổ bi cầu và ổ bi trụ trên vỏ hộp số. Một số bánh răng có đường kính nhỏ gần bằng đường kính trục thì được chế tạo liền. Các bánh răng khác được lắp ghép chặt với trục qua then bán nguyệt.","anchor":"block-1781147484534-fvcy2z6i8"},{"id":"s492","kind":"html","lesson":"3.2.4","title":"Cấu tạo bánh răng, trục, ổ đỡ · b. Trục","text":"Trục số lùi: có 2 kiểu kết cấu khác nhau -Kiểu thứ 1: Trục của số lùi lắp cố định trên vỏ hộp số, bánh răng lắp trên trục nhờ ổ bi kim hoặc bạc trượt. -Kiểu thứ 2: Trục của số lùi lắp trên 2 ổ bị trụ và ổ bi cầu trên vỏ hộp số.","anchor":"block-1781147484534-fvcy2z6i8"},{"id":"s493","kind":"figure","lesson":"3.2.4","title":"Hình 3.39. Ổ đỡ","text":"Hình 3.39. Ổ đỡ","anchor":"block-1781147533082-s0mm7aqth","figure":{"number":"3.39","caption":"Hình 3.39. Ổ đỡ"}},{"id":"s494","kind":"html","lesson":"3.2.4","title":"Cấu tạo bánh răng, trục, ổ đỡ · c. Ổ đỡ (ổ lăn)","text":"Dạng đơn giản nhất của ổ đỡ bao gồm hai vòng lăn ( Vòng ngoài và vòng trong), những con lăn và lồng con lăn (lồng – vòng cách). Những con lăn trên đường chạy của các vòng lăn, qua đó ma sát trượt được được thay thế bằng ma sát lăn nhỏ hơn rất nhiều. Lồng (vòng cách) để giữ các con lăn nằm ở những khoảng cách nhất định. Ổ bi thích hợp cho vận tốc cao (ổ bi rãnh sâu đến 100.000 vòng/phút). Khả năng chịu tải trọng của ổ bi thấp vì lực nén lên ổ đỡ tập trung vào một điểm (điểm tiếp xúc). Ổ đũa được phân biệt theo hình dạng con lăn: Ô đũa trụ, ổ đũa kim, ổ đũa côn, ổ đũa hình trống. Vì lực nén lên ổ đỡ không qua một điểm tiếp xúc mà truyền qua một đường thẳng (dải tiếp xúc) nên khả năng chịu tải trọng của ổ đũa lớn hơn rõ rệt so với ổ bị, đồng thời ma sát và sự tỏa nhiệt ổ trục trong lúc hoạt động tăng lên.","anchor":"block-1781147533082-s0mm7aqth"},{"id":"s495","kind":"html","lesson":"3.2.4","title":"Cấu tạo bánh răng, trục, ổ đỡ · c. Ổ đỡ (ổ lăn)","text":"Bố trí ổ đỡ: Khi một trục được lắp trên nhiều ổ đỡ thì những lực hướng trục chỉ tác dụng lên một ổ đỡ, gọi là ổ đỡ cố định. Ổ đỡ cố định này không được phép di động theo hướng trục. Mọi dung sai sản xuất và giãn nở do nhiệt của trục và vỏ bọc theo hướng trục phải được cân bằng trên nhưng ổ đỡ còn lại, là những ổ đỡ di động, để ngăn cản sự căng cứng của những con lăn trong các vòng lăn. Ở những ổ đỡ cố định, vòng ngoài cũng như vòng trong phải gắn chặt trong vỏ bọc hoặc trên trục. Ổ những ổ đỡ di động, chỉ có vòng trong hoặc vòng ngoài được phép cố định, nghĩa là một vòng phải di động theo hướng trục.","anchor":"block-1781147533082-s0mm7aqth"},{"id":"s496","kind":"lesson","lesson":"3.3.1","title":"Hộp số chính · Cơ cấu điều khiển","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Cơ cấu điều khiển."},{"id":"s497","kind":"simulation","lesson":"3.3.1","title":"Nguyên lý: Cơ cấu điều khiển","text":"1. Chọn cửa gài số. Cần số chọn bánh răng di động hoặc bộ đồng tốc cần thiết. 2. Dịch chuyển trục trượt. Thao tác đúng hướng đưa chuyển động tới trục trượt. 3. Càng gài số đẩy cơ cấu gài. Càng gài đẩy ống gài số hoặc bánh răng tới vị trí yêu cầu. 4. Định vị ở vị trí gài đủ. Viên bi và lò xo định vị giữ vị trí đã chọn."},{"id":"s498","kind":"figure","lesson":"3.3.1","title":"Cơ cấu điều khiển và định vị trong hộp số","text":"A. Cần số. Nhận thao tác chọn và dịch chuyển cơ cấu gài số. B. Trục trượt. Dẫn hướng chuyển động của càng gài số. C. Càng gài số. Đẩy ống gài hoặc bánh răng tới vị trí gài số. D. Cơ cấu định vị. Giữ trục trượt ở vị trí xác định, tránh tự ra hoặc vào số. E. Chốt hãm. Tham gia cơ cấu ngăn gài đồng thời hai số.","figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s499","kind":"part","lesson":"3.3.1","title":"Cần số","text":"Nhận thao tác chọn và dịch chuyển cơ cấu gài số.","keywords":["Cần số"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s500","kind":"part","lesson":"3.3.1","title":"Trục trượt","text":"Dẫn hướng chuyển động của càng gài số.","keywords":["Trục trượt"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s501","kind":"part","lesson":"3.3.1","title":"Càng gài số","text":"Đẩy ống gài hoặc bánh răng tới vị trí gài số.","keywords":["Càng gài số"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s502","kind":"part","lesson":"3.3.1","title":"Cơ cấu định vị","text":"Giữ trục trượt ở vị trí xác định, tránh tự ra hoặc vào số.","keywords":["Cơ cấu định vị"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s503","kind":"part","lesson":"3.3.1","title":"Chốt hãm","text":"Tham gia cơ cấu ngăn gài đồng thời hai số.","keywords":["Chốt hãm"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s504","kind":"figure","lesson":"3.3.1","title":"Hình 3.40. Các kiểu bố trí tay số trên ô tô","text":"Hình 3.40. Các kiểu bố trí tay số trên ô tô","anchor":"block-1781147595681-wamkoxo5s","figure":{"number":"3.40","caption":"Hình 3.40. Các kiểu bố trí tay số trên ô tô"}},{"id":"s505","kind":"html","lesson":"3.3.1","title":"Cơ cấu điều khiển · a. Tay số","text":"Trong quá trình sang số, cần số phải thực hiện cùng lúc hai động tác: Động tác thứ nhất, chọn bánh răng di động hay bộ đồng tốc cần thiết. Động tác thứ hai, dịch đúng hướng bánh răng di động hay bộ đồng tốc đã chọn để cài răng. Ở các ôtô đời cũ, cần chuyển số thường được bố trí nơi cột tay lái. Trường hợp này cần có thêm hệ thống cơ khí nối cần sang số với cơ cấu sang số tại nắp hộp số. Đa số ôtô đời mới bố trí cần số trên sàn xe. Cần số di chuyển theo một khớp cầu ở nắp hộp số, trên khớp cầu có vít chống xoay. Điều khiển sang số có 2 kiểu: Điều khiển trực tiếp và điều khiển gián tiếp qua các thanh nối, dây cáp. Dạng điều khiển trực tiếp: Có cần số đặt trực tiếp vào cửa sổ trong nắp hộp số, Cần số trực tiếp kéo thanh trượt di chuyển, thanh trượt di chuyển mang theo nạng gài số thực hiện quá trình chuyển số.","anchor":"block-1781147595681-wamkoxo5s"},{"id":"s506","kind":"html","lesson":"3.3.1","title":"Cơ cấu điều khiển · a. Tay số","text":"Dạng điều khiển gián tiếp: Loại này liên kết với cần số bằng dây cáp hoặc thanh nối. Cơ cấu điều khiển hộp số bao gồm các chi tiết: cần số, cần chọn và chuyển số, nạng gài số, thanh trượt. Trong cơ cấu này người ta bố trí các cơ cấu an toàn: cơ cấu khóa hãm (tránh cài số kép), cơ cấu tránh gài nhầm số lùi, cơ cấu khóa chuyển số, cơ cấu khóa số lùi.","anchor":"block-1781147595681-wamkoxo5s"},{"id":"s507","kind":"html","lesson":"3.3.1","title":"Cơ cấu điều khiển · b. Trục trượt (trục càng)","text":"Là các thanh nhôm hoặc thép tròn, bên trên có khoang các lỗ bi để các viên bi định vị và các chốt hãm ép vào. Gắp sang số và khớp gạt số gắn cố định trên thanh trượt. Khi chọn số thanh trượt di chuyển dọc theo lỗ khoang trên nắp hộp số, nó làm nhiệm vụ định hướng cho các gắp sang số và các khớp gạt.","anchor":"block-1781147621341-rhdna1rv2"},{"id":"s508","kind":"figure","lesson":"3.3.1","title":"Hình 3.41. Càng gạt và trục trượt","text":"Hình 3.41. Càng gạt và trục trượt","anchor":"block-1781147661917-bnjb73a0e","figure":{"number":"3.41","caption":"Hình 3.41. Càng gạt và trục trượt"}},{"id":"s509","kind":"html","lesson":"3.3.1","title":"Cơ cấu điều khiển · c. Càng gạt","text":"Có dạng các càng cua, kẹp vào rãnh ngoài của các ống răng bộ đồng tốc gài số để đẩy ống gài số di chuyển đến vị trí gài đúng số yêu cầu khi cần. Thường mỗi gắp số được lắp trên một thanh trượt, nhưng cũng có thể hai càng gạt lắp trên cùng một thanh trượt.","anchor":"block-1781147661917-bnjb73a0e"},{"id":"s510","kind":"lesson","lesson":"3.3.2","title":"Hộp số chính · Cơ cấu an toàn, cơ cấu gài số","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quá trình đồng tốc và gài số."},{"id":"s511","kind":"simulation","lesson":"3.3.2","title":"Quá trình đồng tốc và gài số","text":"1. Ống trượt tiến tới bánh răng. Thao tác gài làm ống trượt và vành ma sát dịch chuyển. 2. Mặt côn tạo mô men ma sát. Mặt côn vành đồng ma sát tỳ vào mặt côn bánh răng. 3. Tốc độ được làm đồng đều. Mô men ma sát làm giảm chênh lệch tốc độ trước khi ăn khớp răng gài. 4. Răng gài ăn khớp hoàn toàn. Ống trượt nối bánh răng với trục; cơ cấu định vị giữ vị trí gài."},{"id":"s512","kind":"figure","lesson":"3.3.2","title":"Cơ cấu điều khiển và định vị trong hộp số","text":"A. Cần số. Nhận thao tác chọn và dịch chuyển cơ cấu gài số. B. Trục trượt. Dẫn hướng chuyển động của càng gài số. C. Càng gài số. Đẩy ống gài hoặc bánh răng tới vị trí gài số. D. Cơ cấu định vị. Giữ trục trượt ở vị trí xác định, tránh tự ra hoặc vào số. E. Chốt hãm. Tham gia cơ cấu ngăn gài đồng thời hai số.","figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s513","kind":"part","lesson":"3.3.2","title":"Cần số","text":"Nhận thao tác chọn và dịch chuyển cơ cấu gài số.","keywords":["Cần số"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s514","kind":"part","lesson":"3.3.2","title":"Trục trượt","text":"Dẫn hướng chuyển động của càng gài số.","keywords":["Trục trượt"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s515","kind":"part","lesson":"3.3.2","title":"Càng gài số","text":"Đẩy ống gài hoặc bánh răng tới vị trí gài số.","keywords":["Càng gài số"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s516","kind":"part","lesson":"3.3.2","title":"Cơ cấu định vị","text":"Giữ trục trượt ở vị trí xác định, tránh tự ra hoặc vào số.","keywords":["Cơ cấu định vị"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s517","kind":"part","lesson":"3.3.2","title":"Chốt hãm","text":"Tham gia cơ cấu ngăn gài đồng thời hai số.","keywords":["Chốt hãm"],"figure":{"image":"content/resources/T1_image169.jpg","caption":"Cơ cấu điều khiển và định vị trong hộp số"}},{"id":"s518","kind":"figure","lesson":"3.3.2","title":"Hình 3.42. Trục trượt với các rãnh của cơ cấu định vị","text":"Hình 3.42. Trục trượt với các rãnh của cơ cấu định vị","anchor":"block-1781147706893-wtwo0a4mg","figure":{"number":"3.42","caption":"Hình 3.42. Trục trượt với các rãnh của cơ cấu định vị"}},{"id":"s519","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · a. Cơ cấu định vị","text":"Trong hộp số, cơ cấu định vị được dùng để xác định những vị trí của các bánh răng gài số, khớp gài hoặc bộ đồng tốc, đảm bảo các bánh răng gài số ăn khớp hết chiều dài răng và tránh hiện tượng tự ra, vào số ngẫu hiên (hiện tượng nhảy số). Cơ cấu định vị thường đươc bố trí trên nắp hộp số tương ứng với các trục trượt trong hộp số (Hình 3.43), bao gồm: trên trục trượt có các rãnh lõm tương ứng với vị trí của bánh răng gài số, khớp gài hoặc bộ đồng tốc mà nó điều khiển. Trên nắp hộp số được khoan các lỗ, trong đó có lắp viên bi và lò xo. Khi trục trượt ở vị trí xác định, viên bi được lò xo đẩy tỳ vào rãnh lõm. Để cho trục trượt dịch chuyển, người lái phải tác dụng lực thắng được sức căng của lò xo trong cơ cấu định vị.","anchor":"block-1781147706893-wtwo0a4mg"},{"id":"s520","kind":"figure","lesson":"3.3.2","title":"Hình 3.43. Cơ cấu khóa hãm trên các loại hộp số 3 trục","text":"Hình 3.43. Cơ cấu khóa hãm trên các loại hộp số 3 trục","anchor":"block-1781147738699-ludmub8ee","figure":{"number":"3.43","caption":"Hình 3.43. Cơ cấu khóa hãm trên các loại hộp số 3 trục"}},{"id":"s521","kind":"figure","lesson":"3.3.2","title":"Hình 3.44. Cơ cấu khóa hãm trên các hộp số 2 trục","text":"Hình 3.44. Cơ cấu khóa hãm trên các hộp số 2 trục","anchor":"block-1781147738699-ludmub8ee","figure":{"number":"3.44","caption":"Hình 3.44. Cơ cấu khóa hãm trên các hộp số 2 trục"}},{"id":"s522","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · b. Cơ cấu khóa hãm (Chống gài 2 số cùng lúc).","text":"Cơ cấu này ngăn ngừa khả năng chuyển sang hai số cùng một lúc. Tấm khóa càng chuyển số được chống xoay bởi một bu lông, mà nó cho phép cần chuyển và chọn số trượt theo một hướng đã chọn nhưng không theo hướng chuyển số.","anchor":"block-1781147738699-ludmub8ee"},{"id":"s523","kind":"figure","lesson":"3.3.2","title":"Hình 3.45. Cơ cấu báo hiệu số lùi trên xe Zil 130-131","text":"Hình 3.45. Cơ cấu báo hiệu số lùi trên xe Zil 130-131","anchor":"block-1781147780119-hj26kc6lo","figure":{"number":"3.45","caption":"Hình 3.45. Cơ cấu báo hiệu số lùi trên xe Zil 130-131"}},{"id":"s524","kind":"figure","lesson":"3.3.2","title":"Hình 3.46. Cơ cấu ngăn ngừa về số lùi từ số 5 trên kiểu hộp số 2 trục","text":"Hình 3.46. Cơ cấu ngăn ngừa về số lùi từ số 5 trên kiểu hộp số 2 trục","anchor":"block-1781147780119-hj26kc6lo","figure":{"number":"3.46","caption":"Hình 3.46. Cơ cấu ngăn ngừa về số lùi từ số 5 trên kiểu hộp số 2 trục"}},{"id":"s525","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · c. Cơ cấu bảo hiểm gài số lùi","text":"Trong hộp số cơ cấu an toàn số lùi dùng để giúp cho người lái không gài nhầm số lùi với các số tiến nhằm đảm bảo an toàn trong chuyển động. Cơ cấu an toàn số lùi có thể là loại tấm chắn hoặc loại chốt –lò xo. Loại tấm chắn có một tấm chắn đặt tại rãnh của trục trượt gài số lùi, khi gài số lùi người lái phải bóp lẫy điều khiển trên cần số để nâng tấm chắn lên thì mới đưa đuôi cần số vào cửa gài số lùi, khi gài số lùi người lái phải tác dụng một lực lớn hơn khi gài các số tiến để khắc phục sức căng lò xo. Khi hộp số đã được chuyển sang số 5, cần chuyển số bên trong quay theo chiều mũi tên B trên Hình 3.46, nhả chốt hạn chế số lùi ra. Kết quả là, chốt hạn chế. số lùi được trở về vị trí ban đầu nhờ lò xo hồi.","anchor":"block-1781147780119-hj26kc6lo"},{"id":"s526","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · c. Cơ cấu bảo hiểm gài số lùi","text":"Sau khi cần chuyển số trở về vị trí trung gian giữa số 3 và số 4 và tiếp theo chuyển sang vị trí chọn số 5/ số lùi (mũi tên D),cần chuyển số bên trong và chốt hạn chế số lùi sẽ có hình dạng đưa ra dưới đây. Nếu cố chuyển cần sang số trực tiếp từ số 5 sang số lùi (chỉ ra bởi mũi tên C). Cần chuyển số bên trong đập vào chốt hạn chế số lùi, tránh cho hộp số chuyển từ số 5 sang số lùi.","anchor":"block-1781147780119-hj26kc6lo"},{"id":"s527","kind":"figure","lesson":"3.3.2","title":"Hình 3.47. Đồng tốc Kia","text":"Hình 3.47. Đồng tốc Kia","anchor":"block-1781147816524-727v7d39s","figure":{"number":"3.47","caption":"Hình 3.47. Đồng tốc Kia"}},{"id":"s528","kind":"figure","lesson":"3.3.2","title":"Hình 3.48. Đồng tốc quán tính chốt dọc trục của xe Zil 130 – 131","text":"Hình 3.48. Đồng tốc quán tính chốt dọc trục của xe Zil 130 – 131","anchor":"block-1781147816524-727v7d39s","figure":{"number":"3.48","caption":"Hình 3.48. Đồng tốc quán tính chốt dọc trục của xe Zil 130 – 131"}},{"id":"s529","kind":"figure","lesson":"3.3.2","title":"Hình 3.49. Cơ cấu đồng tốc chốt quán tính hướng kính - Ural 375D","text":"Hình 3.49. Cơ cấu đồng tốc chốt quán tính hướng kính - Ural 375D","anchor":"block-1781147816524-727v7d39s","figure":{"number":"3.49","caption":"Hình 3.49. Cơ cấu đồng tốc chốt quán tính hướng kính - Ural 375D"}},{"id":"s530","kind":"figure","lesson":"3.3.2","title":"Hình 3.50. Loại 1 mặt côn ma sát","text":"Hình 3.50. Loại 1 mặt côn ma sát","anchor":"block-1781147816524-727v7d39s","figure":{"number":"3.50","caption":"Hình 3.50. Loại 1 mặt côn ma sát"}},{"id":"s531","kind":"figure","lesson":"3.3.2","title":"Hình 3.51. Ở vị trí số trung gian","text":"Hình 3.51. Ở vị trí số trung gian","anchor":"block-1781147816524-727v7d39s","figure":{"number":"3.51","caption":"Hình 3.51. Ở vị trí số trung gian"}},{"id":"s532","kind":"figure","lesson":"3.3.2","title":"Hình 3.52. Giữa quá trình đồng tốc","text":"Hình 3.52. Giữa quá trình đồng tốc","anchor":"block-1781147816524-727v7d39s","figure":{"number":"3.52","caption":"Hình 3.52. Giữa quá trình đồng tốc"}},{"id":"s533","kind":"figure","lesson":"3.3.2","title":"Hình 3.53. Kết thúc quá trình đồng tốc và gài số","text":"Hình 3.53. Kết thúc quá trình đồng tốc và gài số","anchor":"block-1781147816524-727v7d39s","figure":{"number":"3.53","caption":"Hình 3.53. Kết thúc quá trình đồng tốc và gài số"}},{"id":"s534","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · d. Đồng tốc","text":"Bộ đồng tốc trong hộp số được dùng để nhanh chóng làm đồng đều tốc độ giữa bánh răng gài số với trục, và cố định bánh răng gài số với trục khi đã gài số. Đảm bảo việc gài số dễ dàng, êm dịu, không có va đập. Trong hộp số ô tô hiện nay thường sử dụng các loại đồng tốc quán tính chốt dọc trục và đồng tốc quán tính con chạy. Ống trượt lắp di trượt trên trục bị động của hộp số bắng then hoa. Hai bên có các vành răng gài số. Trên mặt bích của ống trượt có 6 lỗ để gắn ba chốt cứng và ba chốt mềm xếp xen kẽ nhau. Các lỗ lắp chốt cứng đượcc gia công mặt vát ở hai bên. Các chốt cứng ở phần giữa được gia công mặt vát tạo thành mặt hãm, các chốt mềm được làm thành hai nữa, ở giữa có các lò xo. Hai vành đồng ma sát được gắn chặt với hai đầu chốt cứng và chốt mềm, bề mặt làm việc của các vành đồng dạng hình côn, trên đó có các vòng ren và rãnh để cắt màng dầu và cặn bẩn.","anchor":"block-1781147816524-727v7d39s"},{"id":"s535","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · d. Đồng tốc","text":"Khi gài số, người lái gạt cần số để ống trượt dịch chuyển về phía bánh răng gài số, qua các chốt mềm làm vành đồng ma sát dịch chuyển cùng với ống trượt. Tới khi mặt côn của vành đồng được tỳ sát vào mặt côn của bánh răng gài số, tại bề mặt ma sát xuất hiện mô men ma sát làm cho vành đồng ma sát quay tốc độ góc bánh răng gài số. Trong giai đoạn bánh răng gài số và trục chưa đồng đều tốc độ: Vì vành đồng ma sát quay cùng tốc độ với bánh răng gài số, nên vành đồng bị xoay đi một góc tương đối so với ống trượt làm cho mặt vát trên các chốt cứng tỳ sát vào mặt vát của lỗ trên mặt bích ống trượt. Khi bánh răng gài số và trục đã đồng đều tốc độ: Tại bề mặt tiếp xúc giữa bánh răng gài số và vành đồng ma sát không còn tồn tại mô men ma sát. Lúc này người lái chỉ cần khắc phục được sức căng của lo xo ở chốt mềm, đẩy ống trượt tiếp tục dịch chuyển.","anchor":"block-1781147816524-727v7d39s"},{"id":"s536","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · d. Đồng tốc","text":"Vành răng của ống trượt ăn khớp với vành răng phụ của bánh răng gài số, bánh răng được cố định với trục và quá trình gài số được thực hiện. Ống trượt (3) được lắp di trượt trên trục bị động bằng then hoa, hai bên có các vành răng để gài số. Theo chu vi có 8 vấu hướng kính trong đó có 4 vấu dài và 4 vấu ngắn xen kẽ nhau. Bốn vấu dài là các chốt cứng (2) có tiết diện hình chữ nhật được gia công mặt vát ở các góc, 4 vấu ngắn là các chốt mềm (5) gồm lò xo và cốc lò xo đặt trong các lỗ khoan trên các vấu. Thân của bộ đồng tốc (7) dạng hình trụ, ở hai đầu được tán chặc hai vành đồng ma sát, trên trân có 4 rãnh dài ở giữa mỗi rãnh được gia công mặt vát để tạo thành mặt hãm, mặt trụ phía trong thân có rãnh lõm đựoc tiếp xúc với cóc lò xo của chốt mềm.","anchor":"block-1781147816524-727v7d39s"},{"id":"s537","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · d. Đồng tốc","text":"Trên các vành đồng ma sát có các bề mặt ma sát hình côn trên đó có các vòng ren và rãnh để cắt màng dầu và gạt cặn bẩn. Vòng ngoài (6) được gắn chặt với các chốt cứng, trên đó có rãnh vòng để lắp với càng gài số. Bộ đồng tốc quán tính chốt con chạy có 2 kiểu thiết kế: loại 1 mặt côn ma sát với đồng tốc mặt trong hoặc mặt ngoài; Loại 2 hoặc 3 mặt côn ma sát. Bộ đồng tốc (Hình 3.50) bao gồm ống trượt gài số, thân đồng tốc (moay ơ đồng tốc), 3 chốt ép (con chạy), 2 lò xo vòng, vòng đồng tốc và bánh răng gài số. Ống trượt gài số: Ống này có vấu khớp ở mặt trong ăn khớp với đường rãnh ở mặt ngoài thân đồng tốc. Ba chốt ép (con chạy) được dẫn hướng bởi thân đồng tốc và ép vào vấu khớp của ống trượt gài số nhờ 2 lò xo vòng. Nhờ vậy, ống trượt gài số được giữ ở vị trí trung tâm trên thân đồng tốc.","anchor":"block-1781147816524-727v7d39s"},{"id":"s538","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · d. Đồng tốc","text":"Thân đồng tốc (Moay ơ đồng tốc): Ăn khớp then hoa với trục của bánh răng gài số, ngoài có răng ăn khớp với răng của ống trượt gài số. Vòng đồng tốc (vành đồng ma sát): có mặt côn ma sát bên trong và răng khóa bên ngoài. Ba rãnh cắt trên vòng đồng tốc giữ nó không bị xoay với các chốt ép. Bánh răng gài số: Có bề mặt ma sát hình côn nằm ở phía ngoài hướng về vòng đồng tốc; phía sau là các răng gài số. Mỗi bánh răng số được ăn khớp tương ứng với bánh răng bị động và quay tự quanh trục. Moay-ơ ly hợp lắp với vành trượt bởi các then hoa và lắp vào trục. Vành đồng tốc quay tự do trong chế độ này. *Giai đoạn thứ nhất của cần chuyển số bắt đầu(bắt đầu sự đồng tốc) Khi di chuyển cần gạt số, càng gạt, mà ăn khớp với rãnh trên ống trượt, ấn ống trượt theo hướng được chỉ ra bởi mũi tên.","anchor":"block-1781147816524-727v7d39s"},{"id":"s539","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · d. Đồng tốc","text":"Vì vành trượt và khóa đồng tốc được ăn khớp qua vấu ở giữa của khóa, nên sự chuyển động của ống trượt được truyền tới khóa đồng tốc, ấn vành đồng tốc ép vào phần côn của bánh răng để bắt đầu đồng tốc. Do sự khác nhau về tốc độ giữa ống trượt và bánh răng và do ma sát giữa vành đồng tốc và phần côn của bánh răng, vành đồng đồng tốc chuyển động theo chiều quay của bánh răng. Độ dịch chuyển này bằng với sự chênh lệch về độ rộng khe và độ rộng của khóa. Do vậy, khi nhìn từ trên xuống, các then hoa bên trong ống trượt và vành đồng tốc chưa đúng vị trí ăn khớp với nhau. *Giai đoạn hai – Cần chuyển số được ấn mạnh hơn (trong quá trình đồng tốc): Khi cần gạt số di chuyển thêm, lực tác dụng lên ống trượt vượt qua lực của lò xo khóa hãm bộ đồng tốc và ống trượt vượt qua phần vấu của khóa.","anchor":"block-1781147816524-727v7d39s"},{"id":"s540","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · d. Đồng tốc","text":"Tuy nhiên, các then của ống trượt và của vành đồng tốc chưa được thẳng hàng hoàn toàn, vì vậy lực tác dụng lên ống trượt nhờ càng số ấn vành đồng tốc ép vào phần côn của bánh răng qua vành đồng tốc và ống trượt mạnh hơn. Điều này làm cho tốc độ của bánh răng số trở nên đồng tốc với tốc độ của ống trượt. Các rãnh hẹp được tạo ra trên tất cả khu vực bên trong vòng đồng tốc tiếp xúc với phần côn của bánh răng. Khi vòng đồng tốc bị ép vào phần côn, các rãnh làm tăng áp suất bề mặt cắt qua màng dầu để tăng ma sát giúp sự đồng tốc tốt hơn. Giai đoạn ba – cần số được ấn thêm nữa (hoàn toàn đồng tốc): Khi tốc độ của ống trượt và bánh răng trở nên bằng nhau, vòng đồng tốc bắt đầu quay tự do theo chiều quay. Kết quả là, then hoa phía trong ống trượt ăn khớp với then hoa trên vành đồng tốc như chỉ ra ở Hình 3.53.","anchor":"block-1781147816524-727v7d39s"},{"id":"s541","kind":"html","lesson":"3.3.2","title":"Cơ cấu an toàn, cơ cấu gài số · e. Vỏ hộp số","text":"Vỏ hộp số thường được chế tạo bằng gang xám bao gồm: Nắp và thân hộp số lắp ghép với nhau bằng bu lông. Hình dạng, kích thước vỏ hộp số phụ thuộc vào sơ đồ bố trí, kích thước của các trục và các bánh răng. Thân hộp số được dùng để gá lắp các trục qua các ổ lăn., nắp hộp số thường dùng để lắp các trục trượt, cơ cấu định vị, cơ cấu khoá hãm và các lỗ đổ dầu, lỗ thông hơi.","anchor":"block-1781147881652-e87jfdwy6"},{"id":"s542","kind":"lesson","lesson":"4.1.1","title":"Hộp số tự động · Chức năng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quan hệ điều khiển tự động chọn số."},{"id":"s543","kind":"simulation","lesson":"4.1.1","title":"Quan hệ điều khiển tự động chọn số","text":"1. Thu nhận điều kiện chuyển động. Trạng thái xe và yêu cầu công suất cung cấp thông tin điều khiển. 2. Chọn tỷ số truyền thích hợp. Bộ điều khiển xác định tỷ số truyền theo điều kiện chuyển động. 3. Cơ cấu chấp hành chuyển số. Các phần tử chấp hành thực hiện thay đổi đường truyền. 4. Tiếp tục truyền mô men. Quá trình được tổ chức để chuyển số êm dịu theo loại hộp số."},{"id":"s544","kind":"figure","lesson":"4.1.1","title":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","text":"A. Ly hợp 1. Nối hoặc ngắt nhánh truyền lực tới các cấp số lẻ trong hình 4.1. B. Ly hợp 2. Nối hoặc ngắt nhánh truyền lực tới các cấp số chẵn trong hình 4.1. C. Trục chủ động 1. Nhận mô men từ ly hợp 1 theo nhánh màu đỏ. D. Trục chủ động 2. Nhận mô men từ ly hợp 2 theo nhánh màu xanh.","figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s545","kind":"part","lesson":"4.1.1","title":"Ly hợp 1","text":"Nối hoặc ngắt nhánh truyền lực tới các cấp số lẻ trong hình 4.1.","keywords":["Ly hợp 1"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s546","kind":"part","lesson":"4.1.1","title":"Ly hợp 2","text":"Nối hoặc ngắt nhánh truyền lực tới các cấp số chẵn trong hình 4.1.","keywords":["Ly hợp 2"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s547","kind":"part","lesson":"4.1.1","title":"Trục chủ động 1","text":"Nhận mô men từ ly hợp 1 theo nhánh màu đỏ.","keywords":["Trục chủ động 1"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s548","kind":"part","lesson":"4.1.1","title":"Trục chủ động 2","text":"Nhận mô men từ ly hợp 2 theo nhánh màu xanh.","keywords":["Trục chủ động 2"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s549","kind":"html","lesson":"4.1.1","title":"Hộp số tự động · Chức năng","text":"Hộp số tự động cho phép đơn giản hóa việc điều khiển hộp số. Quá trình chuyển số êm dịu, không cần cắt công suất truyền từ động cơ truyền xuống khi sang số. Hộp số tự động lựa chọn tỷ số truyền phù hợp với điều kiện chuyển động, do đó tạo điều kiện sử dụng tối ưu công suất của động cơ.","anchor":"block-1781160086335-cirbkek25"},{"id":"s550","kind":"lesson","lesson":"4.1.2","title":"Hộp số tự động · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân biệt hộp số tự động."},{"id":"s551","kind":"simulation","lesson":"4.1.2","title":"Trình tự phân biệt hộp số tự động","text":"1. Xác định cơ cấu truyền chính. Quan sát biến mô, bộ bánh răng hoặc bộ truyền vô cấp. 2. Xét các cấp số truyền. Phân biệt tỷ số theo cấp với thay đổi liên tục. 3. Xét cơ cấu thực hiện chuyển số. Đối chiếu bộ điều khiển và các cơ cấu chấp hành. 4. Gọi đúng loại hộp số. Chọn tên loại được dùng trong mục 4.1.2."},{"id":"s552","kind":"figure","lesson":"4.1.2","title":"Các loại hộp số tự động — sơ đồ học tập biên soạn từ bài 4.1.2","text":"A. Hộp số tự động có cấp với biến mô thủy lực. Có các tỷ số truyền theo cấp, được trình bày ở mục 4.3. B. Hộp số tự động vô cấp (CVT). Dạng truyền động vô cấp được trình bày ở mục 4.4. C. Hộp số cơ khí được tự động hóa. Bộ điều khiển và chấp hành thực hiện đóng ngắt, gài số.","figure":{"image":"tuong_tac/diagrams/autotypes.svg","caption":"Các loại hộp số tự động — sơ đồ học tập biên soạn từ bài 4.1.2"}},{"id":"s553","kind":"part","lesson":"4.1.2","title":"Hộp số tự động có cấp với biến mô thủy lực","text":"Có các tỷ số truyền theo cấp, được trình bày ở mục 4.3.","keywords":["Hộp số tự động có cấp với biến mô thủy lực"],"figure":{"image":"tuong_tac/diagrams/autotypes.svg","caption":"Các loại hộp số tự động — sơ đồ học tập biên soạn từ bài 4.1.2"}},{"id":"s554","kind":"part","lesson":"4.1.2","title":"Hộp số tự động vô cấp (CVT)","text":"Dạng truyền động vô cấp được trình bày ở mục 4.4.","keywords":["Hộp số tự động vô cấp (CVT)"],"figure":{"image":"tuong_tac/diagrams/autotypes.svg","caption":"Các loại hộp số tự động — sơ đồ học tập biên soạn từ bài 4.1.2"}},{"id":"s555","kind":"part","lesson":"4.1.2","title":"Hộp số cơ khí được tự động hóa","text":"Bộ điều khiển và chấp hành thực hiện đóng ngắt, gài số.","keywords":["Hộp số cơ khí được tự động hóa"],"figure":{"image":"tuong_tac/diagrams/autotypes.svg","caption":"Các loại hộp số tự động — sơ đồ học tập biên soạn từ bài 4.1.2"}},{"id":"s556","kind":"html","lesson":"4.1.2","title":"Hộp số tự động · Phân loại","text":"Hiện nay trên ô tô sử dụng các loại hộp số tự động sau: Hộp số tự động có cấp với biến mô thủy lực.","anchor":"block-1781160105309-xtr72k2z1"},{"id":"s557","kind":"lesson","lesson":"4.2.1","title":"Hộp số tự động · Kết cấu của hộp số cơ khí được tự động hóa","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích ví dụ chuyển từ số 2 sang số 3."},{"id":"s558","kind":"simulation","lesson":"4.2.1","title":"Ví dụ chuyển từ số 2 sang số 3","text":"1. Nhánh số 2 đang truyền mô men. Ly hợp 2 đóng, nhánh số chẵn đang truyền mô men. 2. Chọn trước số 3 trên nhánh còn lại. Ly hợp 1 còn ngắt; cơ cấu điều khiển chọn bánh răng số 3. 3. Chuyển tác động giữa hai ly hợp. Giảm tác động ly hợp 2 đồng thời tăng tác động ly hợp 1. Đây là bước chuyển tiếp, không khóa cứng hai nhánh. 4. Nhánh số 3 tiếp nhận mô men. Ly hợp 1 đóng và nhánh số lẻ truyền mô men tới đầu ra."},{"id":"s559","kind":"figure","lesson":"4.2.1","title":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","text":"A. Ly hợp 1. Nối hoặc ngắt nhánh truyền lực tới các cấp số lẻ trong hình 4.1. B. Ly hợp 2. Nối hoặc ngắt nhánh truyền lực tới các cấp số chẵn trong hình 4.1. C. Trục chủ động 1. Nhận mô men từ ly hợp 1 theo nhánh màu đỏ. D. Trục chủ động 2. Nhận mô men từ ly hợp 2 theo nhánh màu xanh.","figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s560","kind":"part","lesson":"4.2.1","title":"Ly hợp 1","text":"Nối hoặc ngắt nhánh truyền lực tới các cấp số lẻ trong hình 4.1.","keywords":["Ly hợp 1"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s561","kind":"part","lesson":"4.2.1","title":"Ly hợp 2","text":"Nối hoặc ngắt nhánh truyền lực tới các cấp số chẵn trong hình 4.1.","keywords":["Ly hợp 2"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s562","kind":"part","lesson":"4.2.1","title":"Trục chủ động 1","text":"Nhận mô men từ ly hợp 1 theo nhánh màu đỏ.","keywords":["Trục chủ động 1"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s563","kind":"part","lesson":"4.2.1","title":"Trục chủ động 2","text":"Nhận mô men từ ly hợp 2 theo nhánh màu xanh.","keywords":["Trục chủ động 2"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s564","kind":"figure","lesson":"4.2.1","title":"Hình 4.1.Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","text":"Hình 4.1.Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","anchor":"block-1781160147168-vgs6eqcwm","figure":{"number":"4.1","caption":"Hình 4.1.Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt"}},{"id":"s565","kind":"html","lesson":"4.2.1","title":"Hộp số tự động · Kết cấu của hộp số cơ khí được tự động hóa","text":"Hộp số ly hợp kép không có bàn đạp ly hợp để người lái sử dụng mỗi khi chuyển số. Sự khác biệt đầu tiên của hộp số ly hợp kép so với các loại hộp số khác đó là sử dụng bộ đôi ly hợp ma sát. Hai ly hợp được lồng vào nhau, một phần ly hợp nằm trong và một ly hợp nằm phía ngoài. Bộ đôi ly hợp ở đây thuộc loại ly hợp ma sát khô hoặc ly hợp ma sát ướt và sự tách - nối của nó được điều khiển bằng dẫn động điện cơ hoặc thủy lực – điện từ. Hai ly hợp này hoạt động hoàn toàn độc lập với nhau, một điều khiển các bánh răng cấp số lẻ (1, 3, 5 và bánh răng gài số lùi), trong khi ly hợp còn lại có nhiệm vụ điều khiển bánh răng gài số chẵn (2, 4, 6 và số lùi). Với kết cấu như vậy, khi quá trình tăng số (1 - 2 - 3…) hoặc giảm số (5 - 4) xảy ra sẽ không bị mất mát công suất.","anchor":"block-1781160147168-vgs6eqcwm"},{"id":"s566","kind":"html","lesson":"4.2.1","title":"Hộp số tự động · Kết cấu của hộp số cơ khí được tự động hóa","text":"Đồng thời, việc gài các số truyền thực hiện một cách tự động tùy thuộc vào chế độ hoạt động của động cơ và sức cản của mặt đường (nếu người lái chọn chế độ tự động hoàn toàn). Vì vậy nó luôn đảm bảo được lực kéo phù hợp với sức cản chuyển động, bảo đảm được chất lượng động lực học và tính kinh tế nhiên liệu của ô tô. Sự khác biệt thứ hai của hộp số ly hợp kép đó chính là hệ thống trục sơ cấp gồm hai trục đồng trục lồng nhau. Trục thứ nhất (màu đỏ): một đầu (bên trái) liên kết với ly hợp thứ nhất (màu đỏ) bằng then hoa, trên thân trục bao gồm 3 bánh răng có kích thước khác nhau ăn khớp với các bánh răng trên trục thứ cấp thứ nhất tạo ra các cấp số: 1, 3, 5. Trục còn lại (màu xanh), một đầu lắp với ly hợp thứ 2 (màu xanh), trên thân trục gồm 2 bánh răng ăn khớp với 2 bánh răng trên trục thứ cấp thứ hai tạo ra 2 cấp số 2, 4 và thêm một số lùi.","anchor":"block-1781160147168-vgs6eqcwm"},{"id":"s567","kind":"html","lesson":"4.2.1","title":"Hộp số tự động · Kết cấu của hộp số cơ khí được tự động hóa","text":"Cấu tạo của hộp số ly hợp kép được thể hiện trên Hình 4.1. Cấu tạo đặc biệt của hệ trục trung tâm và bộ đôi ly hợp cho phép quá trình chuyển số nhanh hơn và êm hơn hộp số tay truyền thống. Chúng ta hãy cùng hình dung lại thao tác sang số của hộp số tay: Khi người điều khiển muốn chuyển số, đầu tiên cần phải giảm ga sau đó tác động vào bàn đạp ly hợp để ngắt ly hợp, do vậy mômen động cơ không truyền tới trục sơ cấp của hộp số và người lái thực hiện việc chuyển số. Tiếp theo sau, người lái nhả bàn đạp và ly hợp được nối lại đồng thời công suất động cơ truyền tới hộp số. Mômen được phân bố theo trạng thái: ON - OFF - ON trong suốt quá trình chuyển số. Như vậy, độ êm dịu của xe khi sang số phụ thuộc rất nhiều vào kĩ năng của người điều khiển. Khoảng thời gian OFF càng bé thì xe bớt bị rung giật, đồng thời không bị tổn hao công suất máy.","anchor":"block-1781160147168-vgs6eqcwm"},{"id":"s568","kind":"html","lesson":"4.2.1","title":"Hộp số tự động · Kết cấu của hộp số cơ khí được tự động hóa","text":"Tuy nhiên, hộp số ly hợp kép hoàn toàn có thể khắc phục được yếu điểm trên của hộp số tay nhờ vào sự hoạt động độc lập của hai ly hợp.","anchor":"block-1781160147168-vgs6eqcwm"},{"id":"s569","kind":"lesson","lesson":"4.2.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích ví dụ chuyển từ số 2 sang số 3."},{"id":"s570","kind":"simulation","lesson":"4.2.2","title":"Ví dụ chuyển từ số 2 sang số 3","text":"1. Nhánh số 2 đang truyền mô men. Ly hợp 2 đóng, nhánh số chẵn đang truyền mô men. 2. Chọn trước số 3 trên nhánh còn lại. Ly hợp 1 còn ngắt; cơ cấu điều khiển chọn bánh răng số 3. 3. Chuyển tác động giữa hai ly hợp. Giảm tác động ly hợp 2 đồng thời tăng tác động ly hợp 1. Đây là bước chuyển tiếp, không khóa cứng hai nhánh. 4. Nhánh số 3 tiếp nhận mô men. Ly hợp 1 đóng và nhánh số lẻ truyền mô men tới đầu ra."},{"id":"s571","kind":"figure","lesson":"4.2.2","title":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","text":"A. Ly hợp 1. Nối hoặc ngắt nhánh truyền lực tới các cấp số lẻ trong hình 4.1. B. Ly hợp 2. Nối hoặc ngắt nhánh truyền lực tới các cấp số chẵn trong hình 4.1. C. Trục chủ động 1. Nhận mô men từ ly hợp 1 theo nhánh màu đỏ. D. Trục chủ động 2. Nhận mô men từ ly hợp 2 theo nhánh màu xanh.","figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s572","kind":"part","lesson":"4.2.2","title":"Ly hợp 1","text":"Nối hoặc ngắt nhánh truyền lực tới các cấp số lẻ trong hình 4.1.","keywords":["Ly hợp 1"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s573","kind":"part","lesson":"4.2.2","title":"Ly hợp 2","text":"Nối hoặc ngắt nhánh truyền lực tới các cấp số chẵn trong hình 4.1.","keywords":["Ly hợp 2"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s574","kind":"part","lesson":"4.2.2","title":"Trục chủ động 1","text":"Nhận mô men từ ly hợp 1 theo nhánh màu đỏ.","keywords":["Trục chủ động 1"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s575","kind":"part","lesson":"4.2.2","title":"Trục chủ động 2","text":"Nhận mô men từ ly hợp 2 theo nhánh màu xanh.","keywords":["Trục chủ động 2"],"figure":{"image":"content/resources/T1_image197.jpg","caption":"Hình 4.1 — Hộp số ly hợp kép 6 cấp sử dụng ly hợp ma sát ướt","number":"4.1"}},{"id":"s576","kind":"html","lesson":"4.2.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Quá trình chuyển số như sau: Giả sử ở thời điểm hiện tại, xe đang di chuyển ở số 2, lúc này ly hợp 2 đóng (màu xanh), ly hợp 1 mở, khi đó dòng công suất được từ động cơ qua ly hợp 2, qua trục và bộ đồng tốc tới trục sơ cấp và tới bộ vi sai. Xe tiếp tục gia tăng tốc độ, máy tính sẽ tìm kiếm vị trí số kế tiếp, và bánh răng số 3 được chọn. Khi người điều khiển chuyển số, ngay lập tức ly hợp 2 sẽ được ngắt, đồng thời ly hợp 1 đóng, và dòng công suất sẽ vẫn tiếp tục truyền từ động cơ tới trục thứ cấp và dẫn động bộ vi sai. Như vậy, thời gian chuyển từ số 2 lên 3 rất bé, do vậy dòng mômen gần như không bị ngắt quãng. Cũng theo nguyên lý đó, khi người lái giảm số chu trình sẽ diễn ra ngược lại. Toàn bộ quá trình chuyển số sẽ được máy tính kiểm soát và ra lệnh cho cơ cấu chấp hành chọn bánh răng và đóng hoặc ngắt từng ly hợp.","anchor":"block-1781160170591-jdw93263r"},{"id":"s577","kind":"html","lesson":"4.2.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Nếu người lái chọn chế độ tự động hoàn toàn hoặc chế độ điều khiển số tay. Ở chế độ tự động thì bộ đôi ly hợp hoạt động như một biến mô thủy lực của hộp số tự động truyền thống, còn nếu sử dụng chế độ số tay, người lái cũng không phải mất thêm thao tác dùng chân trái để điều hành bàn đạp ly hợp.","anchor":"block-1781160170591-jdw93263r"},{"id":"s578","kind":"lesson","lesson":"4.3.1","title":"Hộp số tự động · Cấu tạo chung","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích vòng tuần hoàn dầu trong biến mô."},{"id":"s579","kind":"note","lesson":"4.3.1","title":"Biến mô và khóa biến mô","text":"Biến mô có thể khuếch đại mô men trong vùng làm việc có độ trượt thích hợp; không dùng một hệ số khuếch đại cố định cho mọi chế độ. Khi ly hợp khóa biến mô đóng, đường truyền gần cơ khí trực tiếp. Tốc độ đầu vào / đầu ra và mô men cần xét cùng nhau khi phân tích tổn hao."},{"id":"s580","kind":"simulation","lesson":"4.3.1","title":"Vòng tuần hoàn dầu trong biến mô","text":"1. Bánh bơm được động cơ dẫn động. Bánh bơm đưa năng lượng vào dầu trong biến mô. 2. Dầu tác động bánh tua-bin. Dòng dầu làm bánh tua-bin quay và truyền mô men tới hộp số. 3. Stato đổi hướng dòng dầu trở về. Ở chế độ biến mô, stato được khớp một chiều giữ theo chiều tác động. 4. Stato được giải phóng ở chế độ ly hợp. Khi điều kiện dòng dầu thay đổi, khớp một chiều cho stato quay theo."},{"id":"s581","kind":"figure","lesson":"4.3.1","title":"Hình 4.3 — Cấu tạo biến mô thủy lực","text":"A. Bánh bơm. Nhận chuyển động từ động cơ và đưa năng lượng vào dòng dầu. B. Bánh tua-bin. Nhận năng lượng dòng dầu và truyền mô men tới trục sơ cấp hộp số. C. Stato. Đổi hướng dòng dầu từ bánh tua-bin trở về bánh bơm. D. Khớp một chiều. Giữ hoặc giải phóng stato theo chiều tác động của dòng dầu.","figure":{"image":"content/resources/T1_image199.jpg","caption":"Hình 4.3 — Cấu tạo biến mô thủy lực","number":"4.3"}},{"id":"s582","kind":"part","lesson":"4.3.1","title":"Bánh bơm","text":"Nhận chuyển động từ động cơ và đưa năng lượng vào dòng dầu.","keywords":["Bánh bơm"],"figure":{"image":"content/resources/T1_image199.jpg","caption":"Hình 4.3 — Cấu tạo biến mô thủy lực","number":"4.3"}},{"id":"s583","kind":"part","lesson":"4.3.1","title":"Bánh tua-bin","text":"Nhận năng lượng dòng dầu và truyền mô men tới trục sơ cấp hộp số.","keywords":["Bánh tua-bin"],"figure":{"image":"content/resources/T1_image199.jpg","caption":"Hình 4.3 — Cấu tạo biến mô thủy lực","number":"4.3"}},{"id":"s584","kind":"part","lesson":"4.3.1","title":"Stato","text":"Đổi hướng dòng dầu từ bánh tua-bin trở về bánh bơm.","keywords":["Stato"],"figure":{"image":"content/resources/T1_image199.jpg","caption":"Hình 4.3 — Cấu tạo biến mô thủy lực","number":"4.3"}},{"id":"s585","kind":"part","lesson":"4.3.1","title":"Khớp một chiều","text":"Giữ hoặc giải phóng stato theo chiều tác động của dòng dầu.","keywords":["Khớp một chiều"],"figure":{"image":"content/resources/T1_image199.jpg","caption":"Hình 4.3 — Cấu tạo biến mô thủy lực","number":"4.3"}},{"id":"s586","kind":"figure","lesson":"4.3.1","title":"Hình 4.2. Cấu tạo hộp số tự động có cấp với biến mô thủy lực","text":"Hình 4.2. Cấu tạo hộp số tự động có cấp với biến mô thủy lực","anchor":"block-1781160259221-flw14nq2x","figure":{"number":"4.2","caption":"Hình 4.2. Cấu tạo hộp số tự động có cấp với biến mô thủy lực"}},{"id":"s587","kind":"html","lesson":"4.3.1","title":"Hộp số tự động · Cấu tạo chung","text":"Một hộp số tự động có cấp với biến mô thủy lực gồm các bộ phận chính sau: Bộ biến mô: Để truyền và khuyếch đại mômen do động cơ sinh ra. Bộ truyền bánh răng hành tinh: Để chuyển số như giảm tốc, đảo chiều, tăng tốc, và vị trí số trung gian. Bộ điều khiển thủy lực: Để điều khiển áp suất thuỷ lực sao cho bộ biến mô và bộ truyền bánh răng hành tinh hoạt động êm. ECU động cơ và ECT: Để điều khiển các van điện từ và bộ điều khiển thuỷ lực nhằm tạo ra điều kiện chạy xe tối ưu. Hộp số này sử dụng áp suất thuỷ lực để tự động chuyển số theo các tín hiệu điều khiển của ECU. ECU điều khiển các van điện từ theo tình trạng của động cơ và của xe do các bộ cảm biến xác định, do đó điều khiển áp suất thuỷ lực. Sau đây chúng ta sẽ nghiên cứu từng bộ phận chính của hộp số tự động có cấp với biến mô thủy lực.","anchor":"block-1781160259221-flw14nq2x"},{"id":"s588","kind":"figure","lesson":"4.3.1","title":"Hình 4.3. Cấu tạo biến mô thủy lực","text":"Hình 4.3. Cấu tạo biến mô thủy lực","anchor":"block-1781160275652-3l30114um","figure":{"number":"4.3","caption":"Hình 4.3. Cấu tạo biến mô thủy lực"}},{"id":"s589","kind":"figure","lesson":"4.3.1","title":"Hình 4.4. Bánh bơm","text":"Hình 4.4. Bánh bơm","anchor":"block-1781160275652-3l30114um","figure":{"number":"4.4","caption":"Hình 4.4. Bánh bơm"}},{"id":"s590","kind":"figure","lesson":"4.3.1","title":"Hình 4.5. Bánh tua – bin","text":"Hình 4.5. Bánh tua – bin","anchor":"block-1781160275652-3l30114um","figure":{"number":"4.5","caption":"Hình 4.5. Bánh tua – bin"}},{"id":"s591","kind":"figure","lesson":"4.3.1","title":"Hình 4.6. Stato và khớp một chiều","text":"Hình 4.6. Stato và khớp một chiều","anchor":"block-1781160275652-3l30114um","figure":{"number":"4.6","caption":"Hình 4.6. Stato và khớp một chiều"}},{"id":"s592","kind":"figure","lesson":"4.3.1","title":"Hình 4.7. Cấu tạo khớp một chiều","text":"Hình 4.7. Cấu tạo khớp một chiều","anchor":"block-1781160275652-3l30114um","figure":{"number":"4.7","caption":"Hình 4.7. Cấu tạo khớp một chiều"}},{"id":"s593","kind":"figure","lesson":"4.3.1","title":"Hình 4.8. Cơ cấu ly hợp khóa biên mô","text":"Hình 4.8. Cơ cấu ly hợp khóa biên mô","anchor":"block-1781160275652-3l30114um","figure":{"number":"4.8","caption":"Hình 4.8. Cơ cấu ly hợp khóa biên mô"}},{"id":"s594","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · a. Bộ biến mô (Biến mô thủy lực)","text":"Bộ biến mô thủy lực trong hộp số tự động nhằm thực hiện các chức năng sau: - Đóng vai trò như một ly hợp thuỷ lực để truyền (hay không truyền) mômen từ động cơ đến hộp số. - Hấp thụ các dao động xoắn của động cơ và hệ thống truyền lực. - Có tác dụng như một bánh đà để làm đồng đều chuyển động quay của động cơ. - Dẫn động bơm dầu của hệ thống điều khiển thuỷ lực. Bộ biến mô gồm bánh bơm, bánh tuabin, khớp một chiều, stato và vỏ biến mô chứa tất cả các bộ phận đó. Bộ biến mô được điền đầy hộp số tự động do bơm dầu cung cấp. Động cơ quay và bánh bơm quay, và dầu bị đẩy ra từ bánh bơm thành một dòng mạnh làm quay bánh tua bin. Bánh bơm được gắn liền với vỏ biến mô, có rất nhiều cánh có biên dạng cong được bố trí theo hướng kính ở bên trong. Vành dẫn hướng được bố trí trên cạnh trong của cánh bơm để dẫn hướng cho dòng chảy của dầu.","anchor":"block-1781160275652-3l30114um"},{"id":"s595","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · a. Bộ biến mô (Biến mô thủy lực)","text":"Vỏ biến mô được nối với trục khuỷu của động cơ qua tấm dẫn động. Bánh tua-bin: cũng như cánh bơm, rôto tuabin có rất nhiều cánh dẫn được bố trí bên trong rôto tuabin. Hướng cong của các cánh dẫn này ngược chiều với cánh dẫn trên cánh bơm. Rôto tuabin được lắp với trục sơ cấp của hộp số. Stato được đặt giữa bánh bơm và bánh tuabin. Nó được lắp trên trục stato, trục này lắp cố định vào vỏ hộp số qua khớp một chiều. Các cánh dẫn của stato nhận dòng dầu khi nó đi ra khỏi bánh tuabin và hướng cho nó đập vào mặt sau của cánh dẫn trên bánh bơm làm cho bánh bơm được cường hoá. Khớp một chiều cho phép stato quay cùng chiều với trục khuỷu động cơ. Tuy nhiên nếu stato có xu hướng quay theo chiều ngược lại, khớp một chiều sẽ khoá stato lại và không cho nó quay. Do vậy stato quay hay bị khoá phụ thuộc vào hướng của dòng dầu đập vào các cánh dẫn của nó.","anchor":"block-1781160275652-3l30114um"},{"id":"s596","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · a. Bộ biến mô (Biến mô thủy lực)","text":"Khi vành ngoài của khớp một chiều quay theo hướng mũi tên A ở Hình 4.7nó sẽ ép vào phần đầu của các con lăn. Do khoảng cách l1 ngắn hơn l nên con lăn bị nghiêng đi cho phép vành ngoài quay. Khi vành ngoài quay theo chiều ngược lại theo hướng mũi tên B ở hình 3.57, con lăn không thể nghiêng đi do khoảng cách l2 dài hơn l. Kết quả làm cho con lăn có tác dụng như một miếng chêm khoá vành ngoài và giữ không cho nó quay. Lò xo giữ được lắp thêm để trợ giúp cho con lăn, nó giữ cho các con lăn luôn nghiêng một chút theo hướng khoá vành ngoài. Cơ cấu ly hợp khóa biến mô: khi ô tô chuyển động trên đường tốt, vận tốc của ô tô khá cao, khi này mômen cản chuyển động nhỏ nên số vòng quay của bánh tuabin xấp xỉ bằng số vòng quay của bánh bơm. Biến mô đã làm việc ở chế độ ly hợp (stato được giải phóng) nhưng hiệu suất còn nhỏ hơn 1 (từ 0,8 đến 0,9).","anchor":"block-1781160275652-3l30114um"},{"id":"s597","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · a. Bộ biến mô (Biến mô thủy lực)","text":"Để hiệu suất truyền động của biến mô đạt giá trị cao nhất, ở chế độ này người ta sử dụng một ly hợp để khoá cứng biến mô. Khi cơ cấu ly hợp khóa biến mô hoạt động đường truyền mômen từ động cơ tới hộp số được thực hiện trực tiếp thông qua ly hợp khoá biến mô như truyền qua một ly hợp ma sát bình thường và lúc đó hiệu suất truyền bằng 1. Ly hợp khóa biến mô được lắp trên moayơ của bánh tuabin và nằm ở phía trước của rôto tuabin. Trong ly hợp khóa biến mô cũng bố trí lò xo giảm chấn để khi ly hợp truyền mômen được êm dịu, không gây va đập. Vật liệu ma sát ở ly hợp này cũng giống như vật liệu ma sát sử dụng cho phanh và đĩa ly hợp. Khi ly hợp khoá biến mô hoạt động, nó sẽ quay cùng với cánh bơm và rôto tuabin. Việc đóng và mở của ly hợp khoá biến mô được quyết định bởi sự thay đổi của hướng dòng dầu thủy lực trong biến mô.","anchor":"block-1781160275652-3l30114um"},{"id":"s598","kind":"figure","lesson":"4.3.1","title":"Hình 4.9. Cấu tạo chung bộ bánh răng hành tinh","text":"Hình 4.9. Cấu tạo chung bộ bánh răng hành tinh","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.9","caption":"Hình 4.9. Cấu tạo chung bộ bánh răng hành tinh"}},{"id":"s599","kind":"figure","lesson":"4.3.1","title":"Hình 4.10. Chế độ giảm tốc","text":"Hình 4.10. Chế độ giảm tốc","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.10","caption":"Hình 4.10. Chế độ giảm tốc"}},{"id":"s600","kind":"figure","lesson":"4.3.1","title":"Hình 4.11. Chế độ tăng tốc","text":"Hình 4.11. Chế độ tăng tốc","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.11","caption":"Hình 4.11. Chế độ tăng tốc"}},{"id":"s601","kind":"figure","lesson":"4.3.1","title":"Hình 4.12. Chế độ đảo chiều","text":"Hình 4.12. Chế độ đảo chiều","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.12","caption":"Hình 4.12. Chế độ đảo chiều"}},{"id":"s602","kind":"figure","lesson":"4.3.1","title":"Hình 4.13. Chế độ nối trực tiếp","text":"Hình 4.13. Chế độ nối trực tiếp","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.13","caption":"Hình 4.13. Chế độ nối trực tiếp"}},{"id":"s603","kind":"figure","lesson":"4.3.1","title":"Hình 4.14. Cấu tạo phanh dải","text":"Hình 4.14. Cấu tạo phanh dải","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.14","caption":"Hình 4.14. Cấu tạo phanh dải"}},{"id":"s604","kind":"figure","lesson":"4.3.1","title":"Hình 4.15. Hoạt động phanh dải","text":"Hình 4.15. Hoạt động phanh dải","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.15","caption":"Hình 4.15. Hoạt động phanh dải"}},{"id":"s605","kind":"figure","lesson":"4.3.1","title":"Hình 4.16. Cấu tạo phanh nhiều đĩa ướt","text":"Hình 4.16. Cấu tạo phanh nhiều đĩa ướt","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.16","caption":"Hình 4.16. Cấu tạo phanh nhiều đĩa ướt"}},{"id":"s606","kind":"figure","lesson":"4.3.1","title":"Hình 4.17. Hoạt động phanh nhiều đĩa ướt ở chế độ ăn khớp","text":"Hình 4.17. Hoạt động phanh nhiều đĩa ướt ở chế độ ăn khớp","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.17","caption":"Hình 4.17. Hoạt động phanh nhiều đĩa ướt ở chế độ ăn khớp"}},{"id":"s607","kind":"figure","lesson":"4.3.1","title":"Hình 4.18. Hoạt động phanh nhiều đĩa ướt ở chế độ nhả khớp","text":"Hình 4.18. Hoạt động phanh nhiều đĩa ướt ở chế độ nhả khớp","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.18","caption":"Hình 4.18. Hoạt động phanh nhiều đĩa ướt ở chế độ nhả khớp"}},{"id":"s608","kind":"figure","lesson":"4.3.1","title":"Hình 4.19. Cấu tạo ly hợp","text":"Hình 4.19. Cấu tạo ly hợp","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.19","caption":"Hình 4.19. Cấu tạo ly hợp"}},{"id":"s609","kind":"figure","lesson":"4.3.1","title":"Hình 4.20. Chế độ ăn khớp ly hợp","text":"Hình 4.20. Chế độ ăn khớp ly hợp","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.20","caption":"Hình 4.20. Chế độ ăn khớp ly hợp"}},{"id":"s610","kind":"figure","lesson":"4.3.1","title":"Hình 4.21. Chế độ nhả khớp ly hợp","text":"Hình 4.21. Chế độ nhả khớp ly hợp","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.21","caption":"Hình 4.21. Chế độ nhả khớp ly hợp"}},{"id":"s611","kind":"figure","lesson":"4.3.1","title":"Hình 4.22. Triệt tiêu áp suất dầu ly tâm","text":"Hình 4.22. Triệt tiêu áp suất dầu ly tâm","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.22","caption":"Hình 4.22. Triệt tiêu áp suất dầu ly tâm"}},{"id":"s612","kind":"figure","lesson":"4.3.1","title":"Hình 4.23. Ly hợp và khớp một chiều","text":"Hình 4.23. Ly hợp và khớp một chiều","anchor":"block-1781160371768-jxpqd3znd","figure":{"number":"4.23","caption":"Hình 4.23. Ly hợp và khớp một chiều"}},{"id":"s613","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Bộ bánh răng hành tinh trong hộp số tự động có các chức năng sau: - Cung cấp một số tỉ số truyền để thay đổi mômen và tốc độ của bánh xe chủ động phù hợp với sức cản của đường và nhu cầu sử dụng tốc độ của ô tô. - Đảo chiều quay của trục ra để thực hiện lùi xe. - Tạo vị trí trung gian cho phép xe dừng lâu dài khi động cơ vẫn hoạt động. Cấu tạo chung của bộ bánh răng hành tinh: Một bộ các bánh răng hành tinh là một loạt các bánh răng ăn khớp với nhau trong đó bao gồm: Bánh răng mặt trời, bánh răng bao, các bánh răng hành tinh và cần dẫn. Bánh răng mặt trời có vành răng ngoài và được đặt trên một trục quay. Bánh răng mặt bao có vành răng trong và cũng được đặt trên một trục quay khác đồng trục với bánh răng mặt trời. Các bánh răng hành tinh nằm giữa và ăn khớp với bánh răng mặt trời và bánh răng bao.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s614","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Trục của các bánh răng hành tinh được liên kết với một cần dẫn cũng có trục quay đồng trục với bánh răng bao và bánh răng mặt trời. Như vậy ba trục có cùng đường tâm quay ở dạng trục lồng và được gọi là đường tâm trục của cơ cấu hành tinh. Các trục đều có thể quay tương đối với nhau. Số lượng bánh răng hành tinh có thể là 2, 3, 4 tuỳ thuộc vào cấu trúc của chúng. Các bánh răng hành tinh vừa quay xung quanh trục của nó vừa quay xung quanh trục của cơ cấu hành tinh. Nguyên lý hoạt động của cơ cấu hành tinh Một cơ cấu hành tinh bao gồm ba loại bánh răng: Một bánh răng mặt trời, một bánh răng bao và một số bánh răng hành tinh lắp trên một cần dẫn. Cơ cấu hành tinh là cơ cấu ba bậc tự do tương ứng với ba chuyển động của các trục bánh răng mặt trời, bánh răng bao và cần dẫn.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s615","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Vì vậy để có một chuyển động từ đầu vào đến đầu ra thì một trong ba bậc tự do trên phải được hạn chế. Nguyên lý truyền động của cơ cấu hành tinh được thể hiện qua ba trường hợp sau đây: Ở chế độ này, trạng thái và tên gọi của các phần tử trong cơ cấu hành tinh được thể hiện như sau: Đầu vào: Bánh răng bao (phần tử chủ động) Đầu ra: Cần dẫn (Phần tử bị động) Khi bánh răng bao quay theo chiều kim đồng hồ, các bánh răng hành tinh sẽ quay xung quanh bánh răng mặt trời trong khi cũng quay quanh trục của nó theo chiều kim đồng hồ.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s616","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Điều đó làm cho tốc độ quay của cần dẫn giảm xuống tuỳ thuộc số răng của bánh răng bao và bánh răng mặt trời Ở chế độ này, trạng thái và tên gọi của các phần tử trong cơ cấu hành tinh được thể hiện như sau: Đầu vào: Cần dẫn (phần tử chủ động) Đầu ra: Bánh răng bao (phần tử bị động) Khi cần dẫn quay theo chiều kim đồng hồ, các bánh răng hành tinh sẽ quay xung quanh bánh răng mặt trời trong khi chúng cũng quay quanh trục của nó theo chiều kim đồng hồ.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s617","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Điều đó làm cho bánh răng bao tăng tốc tuỳ thuộc số răng của bánh răng bao và bánh răng mặt trời Ở chế độ này, trạng thái và tên gọi của các phần tử trong cơ cấu hành tinh được thể hiện như sau: Đầu vào: Bánh răng mặt trời (phần tử chủ động) Đầu ra: Bánh răng bao (phần tử bị động) Khi bánh răng mặt trời quay theo chiều kim đồng hồ, các bánh răng hành tinh lúc này do cần dẫn bị cố định nên tự quay quanh trục của nó theo chiều ngược chiều kim đồng hồ. Điều đó làm cho bánh răng bao cũng quay ngược chiều kim đồng hồ. Lúc này bánh răng bao giảm tốc phụ thuộc vào số răng của bánh răng bao và bánh răng mặt trời Ở chế độ này, trạng thái và tên gọi của các phần tử trong cơ cấu hành tinh được thể hiện như sau: Đầu vào: Bánh răng mặt trời, bánh răng bao Do bánh răng bao và bánh răng mặt trời quay cùng nhau với cùng một tốc độ nên cần dẫn cũng quay với cùng tốc độ đó.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s618","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Trong hộp số tự động không phải chỉ có một bộ truyền hành tinh mà có thể hai hoặc nhiều hơn. Vì vậy để có được các tỉ số truyền khác nhau, tức là để cố định hoặc giải phóng một phần tử trong cơ cấu hành tinh người ta phải sử dụng các phanh hoặc ly hợp. Phanh hãm giữ cố định một trong các bộ phận của bộ truyền hành tinh để đạt được tỉ số truyền cần thiết. Có 2 loại phanh: + Phanh dải (B1): Ở loại này, một dải phanh được bao quanh trống phanh, trống này được gắn với một trong các bộ phận của bộ truyền hành tinh. Khi phanh, dải phanh cố định sẽ xiết vào trống phanh để giữ cố định bộ phận đó của bộ truyền hành tinh. Một đầu của dải phanh được hãm chặt vào vỏ hộp số bằng một chốt, còn đầu kia tiếp xúc với píttông phanh qua cần đẩy píttông chuyển động bằng áp suất thuỷ lực. Pít tông phanh có thể chuyển động trên cần đẩy píttông nhờ việc nén các lò xo.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s619","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Người ta bố trí các cần đẩy pít tông có hai chiều dài khác nhau để có thể điều chỉnh khe hở giữa dải phanh và trống phanh. Khi áp suất thuỷ lực tác động lên pít tông thì pít tông di chuyển sang phía trái trong xi lanh và nén các lò xo. Cần đẩy pít tông chuyển sang bên trái cùng với pít tông và đẩy một đầu của dải phanh. Do đầu kia của dải phanh bị cố định vào vỏ hộp số nên đường kính của dải phanh giảm xuống và dải phanh xiết vào trống làm cho nó không chuyển động được. Tại thời điểm này, sinh ra một lực ma sát lớn giữa dải phanh và trống phanh làm cho trống phanh hoặc một phần tử của bộ truyền bánh răng hành tinh không thể chuyển động được. Khi dầu có áp suất được dẫn ra khỏi xi lanh thì pít tông và cần đẩy pít tông bị đẩy ngược lại do lực của lò xo ngoài và trống được dải phanh nhả ra.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s620","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Ngoài ra, lò xo trong có hai chức năng: để hấp thu phản lực từ trống phanh và để giảm va đập sinh ra khi dải phanh xiết trống phanh. + Phanh nhiều đĩa ướt (B2 và B3): Ở loại phanh này các đĩa thép được lắp cố định với vỏ hộp số và đĩa ma sát quay cùng một khối với từng bộ phận của bộ truyền hành tinh. Khi cần phanh, chúng bị ép vào nhau để giữ cho một trong các bộ phận của bộ truyền hành tinh cố định. Phanh B2 hoạt động thông qua khớp một chiều số 1 để ngăn không cho các bánh răng mặt trời trước và sau quay ngược chiều kim đồng hồ. Các đĩa ma sát được gài bằng then hoa vào vòng lăn ngoài của khớp một chiều số 1 và các đĩa thép được cố định vào vỏ hộp số.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s621","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Vòng lăn trong của khớp một chiều số 1 (các bánh răng mặt trời trước và sau) được thiết kế sao cho khi quay ngược chiều kim đồng hồ thì nó sẽ bị khoá, nhưng khi quay theo chiều kim đồng hồ thì nó có thể xoay tự do. Mục đích của phanh B3 là ngăn không cho cần dẫn sau quay. Các đĩa ma sát ăn khớp với moay ơ B3 của cần dẫn sau. Moay ơ B3 và cần dẫn sau được bố trí liền một cụm và quay cùng nhau. Các đĩa thép được cố định vào vỏ hộp số. Số lượng các đĩa ma sát và đĩa thép khác nhau tuỳ theo kiểu hộp số tự động. Thậm chí trong các hộp số tự động cùng kiểu, số lượng đĩa ma sát cũng có thể khác nhau tuỳ thuộc vào động cơ được lắp với hộp số. * Hoạt động của phanh nhiều đĩa ướt (B2 và B3) Khi áp suất thuỷ lực tác động lên xi lanh pít tông sẽ dịch chuyển và ép các đĩa thép và đĩa ma sát tiếp xúc với nhau.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s622","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Do đó tạo nên một lực ma sát lớn giữa mỗi đĩa thép và đĩa ma sát. Kết quả là cần dẫn hoặc bánh răng mặt trời bị khoá vào vỏ hộp số. Khi dầu có áp suất được xả ra khỏi xi lanh thì pít tông bị lò xo phản hồi đẩy về vị trí ban đầu của nó và làm nhả phanh. Khi dầu có áp suất được xả ra khỏi xi lanh thì pít tông bị lò xo phản hồi đẩy về vị trí ban đầu của nó và làm nhả phanh. Ly hợp dùng để nối truyền động từ biến mô đến các bộ truyền hành tinh. Ly hợp nhiều đĩa loại ướt thường được sử dụng trong hộp số tự động. Nó bao gồm một số đĩa thép và một số đĩa ma sát được bố trí xen kẽ với nhau. Để điều khiển đóng mở ly hợp người ta sử dụng áp suất thuỷ lực. Ly hợp C1 hoạt động để truyền công suất từ bộ biến mô tới bánh răng bao trước qua trục sơ cấp. Các đĩa ma sát và đĩa thép được bố trí xen kẽ với nhau.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s623","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Các đĩa ma sát được nối bằng then với bánh răng bao trước và các đĩa thép được khớp nối bằng then với tang trống của ly hợp số tiến. Bánh răng bao trước được lắp bằng then với bích bánh răng bao, còn tang trống của ly hợp số tiến được lắp bằng then với moay ơ của ly hợp số truyền thẳng. Ly hợp C2 truyền công suất từ trục sơ cấp tới tang của ly hợp truyển thẳng (bánh răng mặt trời). Các đĩa ma sát được lắp bằng then với moay ơ của ly hợp truyền thẳng còn các đĩa thép được lắp bằng then với tang trống ly hợp truyền thẳng. Tang trống ly hợp truyền thẳng ăn khớp với tang trống đầu vào của bánh răng mặt trời và tang trống này lại được ăn khớp với các bánh răng mặt trời trước và sau.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s624","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Kết cấu được thiết kế sao cho ba cụm đĩa ma sát, đĩa thép và các tang trống quay cùng với nhau.. * Hoạt động của ly hợp (C1 và C2) Khi dầu có áp suất chảy vào trong xi lanh pít tông, nó sẽ đẩy viên bi van của pít tông đóng kín van một chiều và làm pít tông di động trong xi lanh và ép các đĩa thép tiếp xúc với các đĩa ma sát. Do lực ma sát lớn giữa các đĩa thép và đĩa ma sát nên các đĩa thép dẫn và đĩa ma sát bị dẫn quay cùng một tốc độ. Có nghĩa là ly hợp được ăn khớp, trục sơ cấp được nối với bánh răng bao,và công suất từ trục sơ cấp được truyền tới bánh răng bao. Khi dầu có áp suất được xả thì áp suất dầu trong xi lanh giảm xuống. Điều này cho phép viên bi rời khỏi van một chiều nhờ lực li tâm tác động lên nó,và dầu trong xi lanh được xả ra ngoài qua van một chiều.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s625","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Ly hợp triệt tiêu áp suất dầu thủy lực ly tâm: trong cơ cấu của một ly hợp thông thường để ngăn cản sự sinh ra áp suất do lực ly tâm tác động lên dầu trong buồng áp suất dầu của pít tông khi nhả ly hợp, người ta bố trí một viên bi một chiều để xả dầu. Do đó, trước khi có thể tác động tiếp vào ly hợp cần có thời gian để dầu điền đầy buồng áp suất dầu của pít tông. Trong khi chuyển số, ngoài áp suất do thân van kiểm soát, thì áp suất tác động lên dầu trong buồng áp suất dầu của pít tông cũng có ảnh hưởng, mà áp suất này lại phụ thuộc vào sự dao động tốc độ của động cơ. Để triệt tiêu ảnh hưởng này người ta bố trí đối diện với buồng áp suất thuỷ lực của pít tông một khoang triệt tiêu áp suất dầu thuỷ lực. Bằng việc sử dụng dầu bôi trơn như dầu dùng cho trục thì một lực li tâm tương đương sẽ tác động, làm triệt tiêu lực li tâm tác động lên bản thân pít tông.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s626","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Vì vậy, không cần phải xả chất lỏng bằng cách dùng viên bi mà vẫn đạt được một đặc tuyến thay đổi tốc độ êm và rất nhạy. Khi bộ truyền bánh răng hành tinh được thiết kế mà không tính đến va đập khi chuyển số thì B2, F1 và F2 là không cần thiết. Chỉ cần C1, C2, B1 và B3 là đủ. Ngoài ra, rất khó thực hiện việc áp suất thuỷ lực tác động lên phanh đúng vào thời điểm áp suất thuỷ lực vận hành li hợp được xả. Do đó, khớp một chiều số 1 (F1) tác động qua phanh B2 để ngăn không cho bánh răng mặt trời trước và sau quay ngược chiều kim đồng hồ. Khớp một chiều số 2 (F2) ngăn không cho cần dẫn sau quay ngược kim đồng hồ. Vòng lăn ngoài của khớp một chiều sô 2 được cố định vào vỏ hộp số. Nó được lắp ráp sao cho nó sẽ khoá khi vòng lăn trong (cần dẫn sau) xoay ngược chiều kim đồng hồ và quay tự do khi vòng lăn trong xoay theo chiều kim đồng hồ.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s627","kind":"html","lesson":"4.3.1","title":"Cấu tạo chung · b. Bộ bánh răng hành tinh","text":"Với cách này có thể sử dụng các khớp một chiều để chuyển các số bằng cách luôn ấn hoặc nhả áp suất thuỷ lực lên một phần tử. Nghĩa là, chức năng của khớp một chiều là đảm bảo chuyển số được êm. Sau đây chúng ta cùng nghiên cứu hoạt động của bộ truyền bánh răng hành tinh sau khi đã tìm hiểu về các cơ cấu truyền mô men (các ly hợp) và các cơ cấu hãm cố định một thành phần của bộ truyền bánh răng hành tinh (các phanh). Ta sẽ giải thích điều kiện hoạt động của mỗi số bằng sơ đồ nguyên lý của bộ truyền bánh răng hành tinh.","anchor":"block-1781160371768-jxpqd3znd"},{"id":"s628","kind":"lesson","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích ví dụ giảm tốc của bộ truyền hành tinh."},{"id":"s629","kind":"note","lesson":"4.3.2","title":"Điều kiện của bộ truyền hành tinh","text":"Phải chỉ rõ phần tử dẫn, bị dẫn và phần tử bị giữ. Ví dụ đang dùng: mặt trời giữ, bánh răng bao dẫn, cần dẫn ra. Quan hệ lý tưởng: (n_mặt_trời − n_cần_dẫn) / (n_bao − n_cần_dẫn) = −Z_bao / Z_mặt_trời. Không gán cùng đường truyền cho mọi số của AT."},{"id":"s630","kind":"simulation","lesson":"4.3.2","title":"Ví dụ giảm tốc của bộ truyền hành tinh","text":"1. Giữ bánh răng mặt trời. Trong ví dụ chế độ giảm tốc, bánh răng mặt trời là phần tử được giữ. 2. Dẫn động bánh răng bao. Bánh răng bao quay và tác động lên các bánh răng hành tinh. 3. Bánh răng hành tinh chuyển động. Các bánh răng hành tinh vừa quay vừa chuyển động quanh mặt trời. 4. Cần dẫn tạo đầu ra giảm tốc. Tốc độ cần dẫn nhỏ hơn tốc độ bánh răng bao theo tỷ số răng của bộ truyền."},{"id":"s631","kind":"figure","lesson":"4.3.2","title":"Bộ bánh răng hành tinh — sơ đồ học tập biên soạn từ bài 4.3.2","text":"A. Bánh răng mặt trời. Một trong ba phần tử cơ bản quyết định trạng thái truyền động. B. Bánh răng bao. Phần tử ngoài ăn khớp các bánh răng hành tinh. C. Bánh răng hành tinh. Có thể quay quanh trục của mình và chuyển động quanh bánh răng mặt trời. D. Cần dẫn. Phần tử mang các bánh răng hành tinh và có thể làm đầu vào hoặc đầu ra.","figure":{"image":"tuong_tac/diagrams/planetary.svg","caption":"Bộ bánh răng hành tinh — sơ đồ học tập biên soạn từ bài 4.3.2"}},{"id":"s632","kind":"part","lesson":"4.3.2","title":"Bánh răng mặt trời","text":"Một trong ba phần tử cơ bản quyết định trạng thái truyền động.","keywords":["Bánh răng mặt trời"],"figure":{"image":"tuong_tac/diagrams/planetary.svg","caption":"Bộ bánh răng hành tinh — sơ đồ học tập biên soạn từ bài 4.3.2"}},{"id":"s633","kind":"part","lesson":"4.3.2","title":"Bánh răng bao","text":"Phần tử ngoài ăn khớp các bánh răng hành tinh.","keywords":["Bánh răng bao"],"figure":{"image":"tuong_tac/diagrams/planetary.svg","caption":"Bộ bánh răng hành tinh — sơ đồ học tập biên soạn từ bài 4.3.2"}},{"id":"s634","kind":"part","lesson":"4.3.2","title":"Bánh răng hành tinh","text":"Có thể quay quanh trục của mình và chuyển động quanh bánh răng mặt trời.","keywords":["Bánh răng hành tinh"],"figure":{"image":"tuong_tac/diagrams/planetary.svg","caption":"Bộ bánh răng hành tinh — sơ đồ học tập biên soạn từ bài 4.3.2"}},{"id":"s635","kind":"part","lesson":"4.3.2","title":"Cần dẫn","text":"Phần tử mang các bánh răng hành tinh và có thể làm đầu vào hoặc đầu ra.","keywords":["Cần dẫn"],"figure":{"image":"tuong_tac/diagrams/planetary.svg","caption":"Bộ bánh răng hành tinh — sơ đồ học tập biên soạn từ bài 4.3.2"}},{"id":"s636","kind":"figure","lesson":"4.3.2","title":"Hình 4.24. Hoạt động của số 1","text":"Hình 4.24. Hoạt động của số 1","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.24","caption":"Hình 4.24. Hoạt động của số 1"}},{"id":"s637","kind":"figure","lesson":"4.3.2","title":"Hình 4.25. Hoạt động của số 2","text":"Hình 4.25. Hoạt động của số 2","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.25","caption":"Hình 4.25. Hoạt động của số 2"}},{"id":"s638","kind":"figure","lesson":"4.3.2","title":"Hình 4.26. Hoạt động của số 3","text":"Hình 4.26. Hoạt động của số 3","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.26","caption":"Hình 4.26. Hoạt động của số 3"}},{"id":"s639","kind":"figure","lesson":"4.3.2","title":"Hình 4.27. Hoạt động của số lùi","text":"Hình 4.27. Hoạt động của số lùi","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.27","caption":"Hình 4.27. Hoạt động của số lùi"}},{"id":"s640","kind":"figure","lesson":"4.3.2","title":"Hình 4.28. Cơ cấu khóa đỗ xe","text":"Hình 4.28. Cơ cấu khóa đỗ xe","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.28","caption":"Hình 4.28. Cơ cấu khóa đỗ xe"}},{"id":"s641","kind":"figure","lesson":"4.3.2","title":"Hình 4.29. Bộ truyền hành tinh 3 tốc độ kèm bộ truyền hành tinh O/D","text":"Hình 4.29. Bộ truyền hành tinh 3 tốc độ kèm bộ truyền hành tinh O/D","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.29","caption":"Hình 4.29. Bộ truyền hành tinh 3 tốc độ kèm bộ truyền hành tinh O/D"}},{"id":"s642","kind":"figure","lesson":"4.3.2","title":"Hình 4.30. Chế độ số truyền tăng O/D","text":"Hình 4.30. Chế độ số truyền tăng O/D","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.30","caption":"Hình 4.30. Chế độ số truyền tăng O/D"}},{"id":"s643","kind":"figure","lesson":"4.3.2","title":"Hình 4.31. Không ở chế độ số truyền tăng O/D","text":"Hình 4.31. Không ở chế độ số truyền tăng O/D","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.31","caption":"Hình 4.31. Không ở chế độ số truyền tăng O/D"}},{"id":"s644","kind":"figure","lesson":"4.3.2","title":"Hình 4.32. Bộ truyền hành tinh loại 3 tốc độ và bộ truyền số truyền tăng","text":"Hình 4.32. Bộ truyền hành tinh loại 3 tốc độ và bộ truyền số truyền tăng","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.32","caption":"Hình 4.32. Bộ truyền hành tinh loại 3 tốc độ và bộ truyền số truyền tăng"}},{"id":"s645","kind":"figure","lesson":"4.3.2","title":"Hình 4.33. Bộ truyền hành tinh Loại 3 tốc độ và bộ truyền số truyền tăng","text":"Hình 4.33. Bộ truyền hành tinh Loại 3 tốc độ và bộ truyền số truyền tăng","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.33","caption":"Hình 4.33. Bộ truyền hành tinh Loại 3 tốc độ và bộ truyền số truyền tăng"}},{"id":"s646","kind":"figure","lesson":"4.3.2","title":"Hình 4.34. Bộ truyền hành tinh loại 4 tốc độ và O/D","text":"Hình 4.34. Bộ truyền hành tinh loại 4 tốc độ và O/D","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.34","caption":"Hình 4.34. Bộ truyền hành tinh loại 4 tốc độ và O/D"}},{"id":"s647","kind":"figure","lesson":"4.3.2","title":"Hình 4.35. Bộ truyền hành tinh loại 5 tốc độ + O/D","text":"Hình 4.35. Bộ truyền hành tinh loại 5 tốc độ + O/D","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.35","caption":"Hình 4.35. Bộ truyền hành tinh loại 5 tốc độ + O/D"}},{"id":"s648","kind":"figure","lesson":"4.3.2","title":"Hình 4.36. Bộ truyền hành tinh loại 4 tốc độ CR - CR (các xe FF)","text":"Hình 4.36. Bộ truyền hành tinh loại 4 tốc độ CR - CR (các xe FF)","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.36","caption":"Hình 4.36. Bộ truyền hành tinh loại 4 tốc độ CR - CR (các xe FF)"}},{"id":"s649","kind":"figure","lesson":"4.3.2","title":"Hình 4.37. Bộ truyền hành tinh loại 4 tốc độ ravigneaux (các xe FF)","text":"Hình 4.37. Bộ truyền hành tinh loại 4 tốc độ ravigneaux (các xe FF)","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.37","caption":"Hình 4.37. Bộ truyền hành tinh loại 4 tốc độ ravigneaux (các xe FF)"}},{"id":"s650","kind":"figure","lesson":"4.3.2","title":"Hình 4.38. Bộ truyền hành tinh loại 3 tốc độ + U/D (các xe FF)","text":"Hình 4.38. Bộ truyền hành tinh loại 3 tốc độ + U/D (các xe FF)","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.38","caption":"Hình 4.38. Bộ truyền hành tinh loại 3 tốc độ + U/D (các xe FF)"}},{"id":"s651","kind":"figure","lesson":"4.3.2","title":"Hình 4.39. Bộ truyền hành tinh loại 4 tốc độ và U/D (các xe FF)","text":"Hình 4.39. Bộ truyền hành tinh loại 4 tốc độ và U/D (các xe FF)","anchor":"block-1781160585719-5x9tu3g5n","figure":{"number":"4.39","caption":"Hình 4.39. Bộ truyền hành tinh loại 4 tốc độ và U/D (các xe FF)"}},{"id":"s652","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Trục sơ cấp làm quay bánh răng bao của bộ truyền hành tinh trước theo chiều kim đồng hồ nhờ C1. Bánh răng hành tinh của bộ truyền hành tinh trước quay và chuyển động xung quanh làm cho bánh răng mặt trời quay ngược chiều kim đồng hồ. Trong bánh răng hành tinh sau, cần dẫn sau được F2 cố định, nên bánh răng mặt trời làm cho bánh răng bao của bộ truyền hành tinh sau quay theo chiều kim đồng hồ thông qua bánh răng hành tinh của bộ truyền hành tinh sau. Cần dẫn trước và bánh răng bao của bộ truyền hành tinh sau làm cho trục thứ cấp quay theo chiều kim đồng hồ. Bằng cách này tạo ra được tỷ số giảm tốc lớn. Ngoài ra, ở dãy \"L\", B3 hoạt động và phanh bằng động cơ sẽ hoạt động. Độ dài của mũi tên chỉ tốc độ quay và chiều rộng của mũi tên chỉ mô men. Mũi tên càng dài thì tốc độ quay càng lớn, và mũi tên càng rộng thì mô men càng lớn.","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s653","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Trục sơ cấp làm quay bánh răng bao cảu bộ truyền hành tinh trước theo chiều kim đồng hồ nhờ C1. Do bánh răng mặt trời bị B2 và F1 cố định nên công suất không được truyền tới bộ truyền bánh răng hành tinh sau. Cần dẫn trước làm cho trục thứ cấp quay theo chiều kim đồng hồ. Tỷ số giảm tốc thấp hơn so với số 1. Ngoài ra, ở dãy \"2\", B1 hoạt động và phanh bằng động cơ hoạt động. Trục sơ cấp làm quay bánh răng bao của bộ hành tinh trước theo chiều kim đồng hồ nhờ C1, và đồng thời làm quay bánh răng mặt trời theo chiều kim đồng hồ nhờ C2. Do bánh răng bao của bộ truyền hành tinh trước và bánh răng mặt trời quay với nhau cùng một tốc độ nên toàn bộ truyền bánh răng hành tinh cũng quay với cùng tốc độ và công suất được dẫn từ cần dẫn phía trước tới trục thứ cấp. Khi gài số ba, tỉ số giảm tốc là 1.","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s654","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Tuy ở số 3 tại dãy \"D\" phanh động cơ có hoạt động, nhưng do tỉ số giảm tốc là 1 lực phanh động cơ tương đối nhỏ. Trục sơ cấp làm quay bánh răng mặt trời theo chiều kim đồng hồ nhờ C2. Ở bộ truyền bánh răng hành tinh sau do cần dẫn sau bị B3 cố định nên bánh răng bao của bộ truyền hành tinh sau quay ngược chiều kim đồng hồ thông qua bánh răng hành tinh của bộ truyền hành tinh sau, và trục thứ cấp được quay ngược chiều kim đồng hồ. Bằng cách này, trục thứ cấp được quay ngược lại, và xe lùi với một tỉ số giảm tốc lớn.","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s655","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Việc phanh bằng động cơ xảy ra khi hộp số tự động được chuyển sang số lùi, vì số lùi không sử dụng khớp một chiều để truyền lực dẫn động. * Dãy \"P\" (Parking- đỗ xe) hoặc \"N\" (Neutral- Vị trí trung gian: số không) Khi cần số ở \"N\" hoặc \"P\" thì li hợp số tiến (C1) và li hợp truyền thẳng (C2) không hoạt động, vì vậy công suất từ trục thứ cấp không được truyền tới trục dẫn động bộ vi sai. Ngoài ra, khi cần số ở \"P\" vấu hãm của khoá phanh đỗ sẽ ăn khớp với bánh răng đỗ xe mà bánh răng này được nối với trục dẫn động bộ vi sai bằng then nên ngăn không cho xe chuyển động. Khi cần số của một hộp số tự động của một xe FR ở dãy \"P\" thì vấu hãm của khoá phanh đỗ được ăn khớp với bánh răng bao bộ truyền hành tinh trước hoặc sau mà bánh răng bao này được nối bằng then với trục thứ cấp nên ngăn cản sự chuyển động của xe.","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s656","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Tuy nhiên, trên các xe 4WD loại FR thì không thể ngăn chuyển động của xe nếu cơ cấu hộp số phụ ở vị trí số trung gian, dù hộp số tự động đã được đặt ở \"P\". Vì lí do đó hãy nhớ gài phanh đỗ xe khi đỗ xe. Bộ truyền bánh răng hành tinh số O/D (số truyền tăng) Bộ truyền hành tinh số truyền tăng là một bộ truyền hành tinh độc lập với tỷ số truyền tốc độ nhỏ hơn 1.0 (khoảng 0,7 - 0,8). Nó được phối hợp với một bộ truyền bánh răng hành tinh bình thường 3 tốc độ và tương đương với tốc độ số 4. Bộ truyền hành tinh số truyền tăng bao gồm một bộ bánh răng hành tinh, phanh (B0), li hợp (C0), và khớp một chiều (F0). Công suất được dẫn vào cần dẫn bộ truyền tăng dẫn ra bánh răng bao bộ truyền tăng. Bình thường, khi tốc độ xe lớn hơn 40km/giờ ở dãy \"D\" thì việc chuyển sang số truyền tăng có thể thực hiện được.","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s657","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Cũng có thể không cần chuyển sang số truyền tăng mà vẫn lái được xe nếu điều đó phù hợp với lái xe. Các chế độ hoạt động của bộ truyền hành tinh O/D kết hợp bộ truyền hành tinh 3 tốc độ như sau: Ở chế độ số truyền tăng, thì phanh O/D (B0) khoá bánh răng mặt trời O/D, do đó các bánh răng hành tinh của bộ truyền hành tinh O/D vừa chuyển động theo chiều kim đồng hồ xung quanh bánh răng mặt trời O/D, vừa quay xung quanh trục của chúng. Vì vậy bánh răng bao của bộ truyền hành tinh O/D quay theo chiều kim đồng hồ nhanh hơn cần dẫn của bộ truyền bánh rănh hành tinh O/D. Bộ truyền bánh răng hành tinh O/D hoạt động như một cơ cấu dẫn động trực tiếp, và quay như một cụm đơn nhất để dẫn công suất ra(tốc độ quay và mômen).","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s658","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Các loại bộ truyền bánh răng hành tinh Trên một hộp số tự động, người ta kết hợp các bộ truyền hành tinh 3 tốc độ theo nhiều cách khác nhau để tạo nên các hộp số tự động có nhiều cấp số khác nhau. Theo cách kết hợp này, ta có các kiểu bộ truyền hành tinh sau: Loại 3 tốc độ và bộ truyền số truyền tăng (Các xe FF) Bằng việc phối hợp bộ truyền bánh răng hành tinh 3 tốc độ với bộ truyền bánh răng số truyền tăng có thể tạo ra bốn tỉ số truyền tiến và một tỉ số lùi (xe FF) Loại 3 tốc độ và bộ truyền số truyền tăng (Các xe FR): Bộ truyền bánh răng O/D cho các xe FR được đặt giữa bộ biến mô và bộ truyền bánh răng hành tinh 3 tốc độ mà vị trí của bộ truyền 3 tốc độ này khác với vị trí của nó ở các xe FF. Tuy nhiên, hình dạng cũng giống như đối với các xe FF. Vì vây, có thể tạo ra bốn tỉ số truyền số tiến và một tỉ số lùi.","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s659","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Loại 4 tốc độ và O/D (các xe FR): Một bộ truyền hành tinh trung tâm được đặt giữa bộ truyền hành tinh trước và bộ truyền hành tinh sau. Bằng việc phối hợp các bộ truyền đó với một bộ truyền hành tinh O/D ta có thể lập được năm tỉ số truyền tiến và một tỷ số truyền lùi. Một bộ truyền hành tinh trung tâm được đặt giữa bộ truyền hành tinh trước và bộ truyền hành tinh sau. Bộ truyền hành tinh trước có hai bánh răng hành tinh được bố trí giữa bánh răng bao và bánh răng mặt trời. Bằng việc phối hợp các bộ truyền hành tinh này, có thể lập được năm tỉ số truyền tiến và một tỉ số truyền lùi. Loại 4 tốc độ CR - CR (các xe FF): Có thể lập được bốn tỉ số truyền tiến và một tỉ số truyền lùi bằng hai bộ bánh răng hành tinh. Một bộ truyền bánh răng hành tinh CR-CR là một bộ bánh răng hành tinh nối cần dẫn trước và sau với bánh răng bao.","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s660","kind":"html","lesson":"4.3.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Loại 4 tốc độ ravigneaux (các xe FF): Một bánh răng hành tinh dài và một bánh răng hành tinh ngắn được đặt giữa bánh răng bao và bánh răng mặt trời trước. Bánh răng hành tinh dài còn ăn khớp với bánh răng mặt trời sau. Có thể lập được bốn tỉ số truyền tiến và một tỉ số truyền lùi. Loại 3 tốc độ + U/D (các xe FF): Một bộ truyền bánh răng hành tinh được đặt trên trục trung gian. Hệ thống này vận hành như một bộ giảm tốc \"thấp tốc\". Giống như loại 3 tốc độ + O/D, hệ thống này cho phép lập được bốn tỉ số truyền tiến và một tỉ số truyền lùi. Tỉ số truyền của hộp số đối với số cao nhất cũng bằng tỉ số truyền của số O/D đối với tỷ số giảm tốc tổng bao gồm cả tỷ số truyền bánh răng vi sai. Loại 4 tốc độ và U/D (các xe FF):","anchor":"block-1781160585719-5x9tu3g5n"},{"id":"s661","kind":"lesson","lesson":"4.3.3","title":"Hộp số tự động · Hệ thống điều khiển hộp số điện – thủy lực","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích tạo áp suất và chuyển mạch dầu."},{"id":"s662","kind":"simulation","lesson":"4.3.3","title":"Tạo áp suất và chuyển mạch dầu","text":"1. Bơm dầu tạo nguồn áp suất. Dầu có áp được đưa vào mạch điều khiển. 2. Van điều áp điều chỉnh áp suất. Áp suất cơ bản được điều chỉnh theo yêu cầu. 3. ECU điều khiển van điện từ. Tín hiệu điện làm thay đổi trạng thái van điện từ và van chuyển số. 4. Dầu tới ly hợp hoặc phanh. Đường dẫn dầu đã chọn làm ly hợp và phanh của bộ truyền hoạt động."},{"id":"s663","kind":"figure","lesson":"4.3.3","title":"Điều khiển hộp số điện – thủy lực — sơ đồ học tập biên soạn từ bài 4.3.3","text":"A. Bơm dầu. Được động cơ dẫn động để tạo áp suất cần cho hoạt động hộp số. B. Van điều áp sơ cấp. Điều chỉnh áp suất dầu do bơm tạo ra. C. Van điện từ. Tác động các van chuyển số để đổi đường dẫn dầu. D. Bộ tích năng. Làm giảm chấn động khi áp suất tới ly hợp, phanh tăng dần.","figure":{"image":"tuong_tac/diagrams/ect.svg","caption":"Điều khiển hộp số điện – thủy lực — sơ đồ học tập biên soạn từ bài 4.3.3"}},{"id":"s664","kind":"part","lesson":"4.3.3","title":"Bơm dầu","text":"Được động cơ dẫn động để tạo áp suất cần cho hoạt động hộp số.","keywords":["Bơm dầu"],"figure":{"image":"tuong_tac/diagrams/ect.svg","caption":"Điều khiển hộp số điện – thủy lực — sơ đồ học tập biên soạn từ bài 4.3.3"}},{"id":"s665","kind":"part","lesson":"4.3.3","title":"Van điều áp sơ cấp","text":"Điều chỉnh áp suất dầu do bơm tạo ra.","keywords":["Van điều áp sơ cấp"],"figure":{"image":"tuong_tac/diagrams/ect.svg","caption":"Điều khiển hộp số điện – thủy lực — sơ đồ học tập biên soạn từ bài 4.3.3"}},{"id":"s666","kind":"part","lesson":"4.3.3","title":"Van điện từ","text":"Tác động các van chuyển số để đổi đường dẫn dầu.","keywords":["Van điện từ"],"figure":{"image":"tuong_tac/diagrams/ect.svg","caption":"Điều khiển hộp số điện – thủy lực — sơ đồ học tập biên soạn từ bài 4.3.3"}},{"id":"s667","kind":"part","lesson":"4.3.3","title":"Bộ tích năng","text":"Làm giảm chấn động khi áp suất tới ly hợp, phanh tăng dần.","keywords":["Bộ tích năng"],"figure":{"image":"tuong_tac/diagrams/ect.svg","caption":"Điều khiển hộp số điện – thủy lực — sơ đồ học tập biên soạn từ bài 4.3.3"}},{"id":"s668","kind":"figure","lesson":"4.3.3","title":"Hình 4.40. Sơ đồ điều khiển thủy lực","text":"Hình 4.40. Sơ đồ điều khiển thủy lực","anchor":"block-1781160682799-g8079bsnx","figure":{"number":"4.40","caption":"Hình 4.40. Sơ đồ điều khiển thủy lực"}},{"id":"s669","kind":"html","lesson":"4.3.3","title":"Hộp số tự động · Hệ thống điều khiển hộp số điện – thủy lực","text":"Hệ thống điều khiển hộp số điện – thủy lực có ba chức năng sau: Tạo ra áp suất thủy lực: Bơm dầu có chức năng tạo ra áp suất thuỷ lực. Bơm dầu sản ra áp suất thuỷ lực cần thiết cho hoạt động của hộp số tự động bằng việc dẫn động vỏ bộ biến mô (động cơ). Điều chỉnh áp suất thủy lực: Áp suất thuỷ lực tạo ra từ bơm dầu được điều chỉnh bằng van điều áp sơ cấp. Ngoài ra, van bướm ga cũng tạo ra áp suất thuỷ lực thích hợp với công suất phát ra của động cơ. Chuyển các số (làm cho các ly hợp và phanh hoạt động): Khi li hợp và phanh của bộ truyền bánh răng hành tinh được đưa vào vận hành thì việc chuyển các số được thực hiện. Đường dẫn dầu được tạo ra tuỳ thuộc vào vị trí chuyển số do van điều khiển thực hiện. Khi tốc độ xe tăng thì các tín hiệu được chuyển tới các van điện từ từ ECU động cơ & ECT.","anchor":"block-1781160682799-g8079bsnx"},{"id":"s670","kind":"html","lesson":"4.3.3","title":"Hộp số tự động · Hệ thống điều khiển hộp số điện – thủy lực","text":"Các van điện từ sẽ vận hành các van chuyển số để chuyển các số tốc độ. Các bộ phận chính của bộ điều khiển thuỷ lực gồm có:","anchor":"block-1781160682799-g8079bsnx"},{"id":"s671","kind":"figure","lesson":"4.3.3","title":"Hình 4.41. Cấu tạo bơm dầu","text":"Hình 4.41. Cấu tạo bơm dầu","anchor":"block-1781160736583-v2myiuhh9","figure":{"number":"4.41","caption":"Hình 4.41. Cấu tạo bơm dầu"}},{"id":"s672","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · a. Bơm dầu","text":"Bơm dầu được dẫn động từ bộ biến mô (động cơ) để cung cấp áp suất thuỷ lực cần thiết cho sự vận hành của hộp số tự động.","anchor":"block-1781160736583-v2myiuhh9"},{"id":"s673","kind":"figure","lesson":"4.3.3","title":"Hình 4.42. Thân van","text":"Hình 4.42. Thân van","anchor":"block-1781160772764-5809uniay","figure":{"number":"4.42","caption":"Hình 4.42. Thân van"}},{"id":"s674","kind":"figure","lesson":"4.3.3","title":"Hình 4.43. Van điều áp sơ cấp","text":"Hình 4.43. Van điều áp sơ cấp","anchor":"block-1781160772764-5809uniay","figure":{"number":"4.43","caption":"Hình 4.43. Van điều áp sơ cấp"}},{"id":"s675","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · b. Thân van","text":"Thân van bao gồm một thân van trên và một thân van dưới. Thân van giống như một mê cung gồm rất nhiều đường dẫn để dầu hộp số chảy qua. Rất nhiều van được lắp vào các đường dẫn đó, trong các van có áp suất thuỷ lực điều khiển và chuyển mạch chất lỏng từ đường dẫn này sang đường dẫn khác. Số lượng van phụ thuộc vào kiểu xe, một số kiểu xe có các van khác với các van nêu trên.Thông thường, thân van gồm: + Van chuyển số ( 1-2, 2-3, 3-4) Van điều áp sơ cấp điều chỉnh áp suất thuỷ lực (áp suất cơ bản) tới từng bộ phận phù hợp với công suất động cơ để tránh tổn thất công suất bơm. Hoạt động: Khi áp suất thuỷ lực từ bơm dầu tăng thì lò xo van bị nén, và đường dẫn dầu ra cửa xả được mở, và áp suất dầu cơ bản được giữ không đổi.","anchor":"block-1781160772764-5809uniay"},{"id":"s676","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · b. Thân van","text":"Ngoài ra, một áp suất bướm ga cũng được điều chỉnh bằng van, và khi góc mở của bướm ga tăng lên thì áp suất cơ bản tăng để ngăn không cho li hợp và phanh bị trượt. Ở vị trí “R”, áp suất cơ bản được tăng lên hơn nữa để ngăn không cho ly hợp và phanh bị trượt.","anchor":"block-1781160772764-5809uniay"},{"id":"s677","kind":"figure","lesson":"4.3.3","title":"Hình 4.44. Van điều khiển","text":"Hình 4.44. Van điều khiển","anchor":"block-1781160825062-bztj4bl6y","figure":{"number":"4.44","caption":"Hình 4.44. Van điều khiển"}},{"id":"s678","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · c. Van điều khiển","text":"Van điều khiển được nối với cần chuyển số và thanh nối hoặc cáp. Khi thay đổi vị trí của cần chuyển số sẽ chuyển mạch đường dẫn dầu của van điều khiển và cho dầu hoạt động trong từng vị trí chuyển số.","anchor":"block-1781160825062-bztj4bl6y"},{"id":"s679","kind":"figure","lesson":"4.3.3","title":"Hình 4.45. Van chuyển số 1-2","text":"Hình 4.45. Van chuyển số 1-2","anchor":"block-1781160860592-xtk1zhyan","figure":{"number":"4.45","caption":"Hình 4.45. Van chuyển số 1-2"}},{"id":"s680","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · d. Van chuyển số","text":"Ta chuyển số bằng cách thay đổi sự vận hành của các ly hợp và phanh. Các van chuyển số chuyển mạch đường dẫn dầu làm cho áp suất thuỷ lực tác động lên các phanh và ly hợp. Có các van chuyển số 1-2, 2-3 và 3-4. Hoạt động (Ví dụ van chuyển số 1-2): Khi áp suất thuỷ lực tác động lên phía trên van chuyển số thì hộp số được giữ ở số 1 vì van chuyển số ở dưới cùng và các đường dẫn dầu tới các li hợp và phanh bị cắt. Tuy nhiên, khi áp suất thuỷ lực tác động bị cắt do hoạt động của van điện từ thì lực lò xo sẽ đẩy van lên, và đường dẫn dầu tới B2 mở ra, và hộp số được chuyển sang số 2.","anchor":"block-1781160860592-xtk1zhyan"},{"id":"s681","kind":"figure","lesson":"4.3.3","title":"Hình 4.46. Van điện từ","text":"Hình 4.46. Van điện từ","anchor":"block-1781160941449-3jbtxb6h3","figure":{"number":"4.46","caption":"Hình 4.46. Van điện từ"}},{"id":"s682","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · e. Van điện từ","text":"Van điện từ hoạt động nhờ các tín hiệu từ ECU động cơ & ECT để vận hành các van chuyển số và điều khiển áp suất thuỷ lực. Có hai loại van điện từ. Một van điện từ chuyển số mở và đóng các đường dẫn dầu theo các tín hiệu từ ECU (mở đường dẫn dầu theo tín hiệu mở, và đóng lại theo tín hiệu đóng). Một van điện từ tuyến tính điều khiển áp suất thuỷ lực tuyến tính theo dòng điện phát đi từ ECU. Các van điện từ chuyển số được sử dụng để chuyển số và các van điện từ tuyến tính được sử dụng cho chức năng điều khiển áp suất thuỷ lực. Còn có một van điện từ chuyển số kiểu nâng lõi cuộn dây để mở đường dẫn dầu khi tín hiệu bị ngắt, và đóng đường dẫn dầu khi tín hiệu được đóng.","anchor":"block-1781160941449-3jbtxb6h3"},{"id":"s683","kind":"figure","lesson":"4.3.3","title":"Hình 4.47. Van bướm ga","text":"Hình 4.47. Van bướm ga","anchor":"block-1781160969076-emlqq8cgx","figure":{"number":"4.47","caption":"Hình 4.47. Van bướm ga"}},{"id":"s684","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · f. Van bướm ga","text":"Van bướm ga tạo ra áp suất bướm ga tuỳ theo góc độ của bàn đạp ga thông qua cáp bướm ga và cam bướm ga. Áp suất bướm ga tác động lên van điều áp sơ cấp, và như vậy sẽ điều chỉnh áp suất cơ bản theo độ mở của van bướm ga. Một số kiểu xe điều khiển áp suất bướm ga bằng một van điện từ tuyến tính (SLT) thay cho van bướm ga. Các kiểu xe như vậy điều khiển áp suất bướm ga bằng ECU động cơ & ECT chuyển các tín hiệu tới van điện từ tuyến tính theo các tín hiệu từ cảm biến vị trí van bướm ga (góc mở bàn đạp ga).","anchor":"block-1781160969076-emlqq8cgx"},{"id":"s685","kind":"figure","lesson":"4.3.3","title":"Hình 4.48. Van rờ le khóa biến mô và van tín hiệu khóa biến mô","text":"Hình 4.48. Van rờ le khóa biến mô và van tín hiệu khóa biến mô","anchor":"block-1781161023711-vey3prgyu","figure":{"number":"4.48","caption":"Hình 4.48. Van rờ le khóa biến mô và van tín hiệu khóa biến mô"}},{"id":"s686","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · g. Van rờ le khóa biến mô và van tín hiệu khóa biến mô:","text":"Các van này đóng-mở khoá biến mô. Van rơ-le khoá biến mô đảo chiều dòng dầu thông qua bộ biến mô (ly hợp khoá biến mô) theo một áp suất tín hiệu từ van tín hiệu khoá biến mô. Khi áp suất tín hiệu tác động lên phía dưới của van rơle khoá biến mô thì van rơle khoá biến mô được đẩy lên. Điều này làm mở đường dẫn dầu sang phía sau của ly hợp khoá biến mô và làm cho nó hoạt động. Nếu áp suất tín hiệu bị cắt thì van rơle khoá biến mô bị đẩy xuống phía dưới do áp suất cơ bản và lực lò xo tác động lên đỉnh van rơle, và sẽ mở đường dẫn dầu vào phía trước của ly hợp khoá biến mô làm cho nó được nhả ra.","anchor":"block-1781161023711-vey3prgyu"},{"id":"s687","kind":"figure","lesson":"4.3.3","title":"Hình 4.49. Van điều áp thứ cấp","text":"Hình 4.49. Van điều áp thứ cấp","anchor":"block-1781161109343-d3dgm84dz","figure":{"number":"4.49","caption":"Hình 4.49. Van điều áp thứ cấp"}},{"id":"s688","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · h. Van điều áp thứ cấp","text":"Van này điều chỉnh áp suất bộ biến mô và áp suất bôi trơn. Sự cân bằng của hai lực này điều chỉnh áp suất dầu của bộ biến mô và áp suất bôi trơn. Áp suất bộ biến mô được cung cấp từ van điều áp sơ cấp và được truyền tới van rơle khoá biến mô.","anchor":"block-1781161109343-d3dgm84dz"},{"id":"s689","kind":"figure","lesson":"4.3.3","title":"Hình 4.50. Van ngắt giảm áp","text":"Hình 4.50. Van ngắt giảm áp","anchor":"block-1781161135588-jam5284qy","figure":{"number":"4.50","caption":"Hình 4.50. Van ngắt giảm áp"}},{"id":"s690","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · i. Van ngắt giảm áp","text":"Van này điều chỉnh áp suất ngắt giảm áp tác động lên van bướm ga, và được kích hoạt do áp suất cơ bản và áp suất bướm ga. Tác động áp suất ngắt giảm áp lên van bướm ga bằng cách này sẽ làm giảm áp suất bướm ga để ngăn ngừa tổn thất công suất không cần thiết từ bơm dầu.","anchor":"block-1781161135588-jam5284qy"},{"id":"s691","kind":"figure","lesson":"4.3.3","title":"Hình 4.51. Áp suất điều biến bướm ga","text":"Hình 4.51. Áp suất điều biến bướm ga","anchor":"block-1781161172473-2man94m3p","figure":{"number":"4.51","caption":"Hình 4.51. Áp suất điều biến bướm ga"}},{"id":"s692","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · j. Van điều biến bướm ga","text":"Van này tạo ra áp suất điều biến bướm ga. áp suất điều biến bướm ga hơi thấp hơn so với áp suất bướm ga khi van bướm ga mở to. Việc này làm cho áp suất điều biến bướm ga tác động lên van điều áp sơ cấp để cho các thay đổi trong áp suất cơ bản phù hợp hơn với công suất phát ra của động cơ.","anchor":"block-1781161172473-2man94m3p"},{"id":"s693","kind":"figure","lesson":"4.3.3","title":"Hình 4.52. Bộ tích năng","text":"Hình 4.52. Bộ tích năng","anchor":"block-1781161212996-qgtdn8hkl","figure":{"number":"4.52","caption":"Hình 4.52. Bộ tích năng"}},{"id":"s694","kind":"figure","lesson":"4.3.3","title":"Hình 4.53. Hoạt động của các van ở số 1","text":"Hình 4.53. Hoạt động của các van ở số 1","anchor":"block-1781161212996-qgtdn8hkl","figure":{"number":"4.53","caption":"Hình 4.53. Hoạt động của các van ở số 1"}},{"id":"s695","kind":"figure","lesson":"4.3.3","title":"Hình 4.54. Hoạt động của các van ở số 2","text":"Hình 4.54. Hoạt động của các van ở số 2","anchor":"block-1781161212996-qgtdn8hkl","figure":{"number":"4.54","caption":"Hình 4.54. Hoạt động của các van ở số 2"}},{"id":"s696","kind":"figure","lesson":"4.3.3","title":"Hình 4.55. Hoạt động của các van ở số 3","text":"Hình 4.55. Hoạt động của các van ở số 3","anchor":"block-1781161212996-qgtdn8hkl","figure":{"number":"4.55","caption":"Hình 4.55. Hoạt động của các van ở số 3"}},{"id":"s697","kind":"figure","lesson":"4.3.3","title":"Hình 4.56. Hoạt động của các van ở số O/D","text":"Hình 4.56. Hoạt động của các van ở số O/D","anchor":"block-1781161212996-qgtdn8hkl","figure":{"number":"4.56","caption":"Hình 4.56. Hoạt động của các van ở số O/D"}},{"id":"s698","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · k. Bộ tích năng","text":"Bộ tích năng hoạt động để giảm chấn động khi chuyển số. Có sự khác biệt về diện tích bề mặt của phía hoạt động và phía sau của piston bộ tích năng. Khi áp suất cơ bản từ van điều khiển tác động lên phía hoạt động thì pít tông từ từ đi lên và áp suất cơ bản truyền tới các li hợp và phanh sẽ tăng dần. Một vài kiểu điều khiển áp suất thuỷ lực tác động lên bộ tích năng bằng một van điện từ tuyến tính để quá trình chuyển số được êm dịu hơn. Hoạt động của các van trong bộ điều khiển thủy lực khi chuyển số Ở đây, điều kiện của mỗi số được giải thích bằng việc sử dụng các van điện từ và van chuyển số. Để chuyển từ số trung gian sang số 1 thì đường dẫn dầu tới C1 được mở bằng cách chuyển mạch van điều khiển. Do van điện từ số 1 bật “ON” và van điện từ số 2 bị tắt “OFF” nên đường dẫn dầu tới C0 được mở.","anchor":"block-1781161212996-qgtdn8hkl"},{"id":"s699","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · k. Bộ tích năng","text":"(Van điện từ số 1 được bật “ON” và van điện từ số 2 bị ngắt “OFF”). Sự hoạt động của C1 và F2 tạo ra đường dẫn dầu cho số 1. Ở các dãy “D” và “2” phanh động cơ không bị tác động do hoạt động của F2. ở vị trí “L”, đường dẫn từ B3 được mở và phanh bằng động cơ hoạt động. Áp suất thuỷ lực đến bộ truyền bánh răng hành tinh như sau: C1 từ van điều khiển, C0 từ van chuyển số 3-4, B3 từ van chuyển số 2-3. Van điện từ số 2 được chuyển từ tắt “OFF” sang bật “ON” theo các tín hiệu từ ECU. (Van điện từ số 1 bật, và van điện từ số 2 bật). Áp suất thuỷ lực cấp lên phía trên các van chuyển số 1-2 và 3-4 được xả ra và van chuyển số 1-2 được đẩy lên do lực lò xo. Do đó, đường dẫn dầu mở vào B2. C1 và B2 (F1) hoạt động để chuyển số sang số 2. Ở dãy “D” phanh bằng động cơ không bị tác động do hoạt động của F1.","anchor":"block-1781161212996-qgtdn8hkl"},{"id":"s700","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · k. Bộ tích năng","text":"ở dãy “2” đường dẫn dầu vào B2 được mở, và phanh động cơ được tác động. Áp suất thuỷ lực đến bộ truyền bánh răng hành tinh C1 từ van điều khiển C0 từ van chuyển số 3-4 B2 từ van chuyển số 1-2 B1 từ van chuyển số 1-2. Van điện từ số 1 được chuyển từ bật “ON” sang tắt “OFF” theo các tín hiệu từ ECU. (Van điện từ số 1 tắt “OFF” và van điện từ số 2 bật “ON”). Áp suất thuỷ lực bắt đầu được tác động lên phía trên van chuyển số 2-3 và đẩy van chuyển số 2-3 xuống. Do đó, đường dẫn dầu mở vào C2. C1 và C2 hoạt động để chuyển sang số 3. Áp suất thuỷ lực đến bộ truyền bánh răng hành tinh C1 từ van điều khiển C0 từ van chuyển số 3-4 B2 từ van chuyển số 1-2 C2 từ van chuyển số 2-3. Van điện từ số 2 được chuyển từ bật “ON” sang tắt “OFF” theo các tín hiệu từ ECU. (Van điện từ số 1 tắt, và van điện từ số 2 tắt).","anchor":"block-1781161212996-qgtdn8hkl"},{"id":"s701","kind":"html","lesson":"4.3.3","title":"Hệ thống điều khiển hộp số điện – thủy lực · k. Bộ tích năng","text":"Áp suất thuỷ lực bắt đầu tác động lên phía trên của van chuyển số 1-2 và 3-4 và đẩy van chuyển số 3-4 xuống. (áp suất cơ bản từ van chuyển số 2-3 tác động vào dưới van chuyển số 1- 2, do đó van chuyển số 1-2 không di động). Vì vậy, đường dẫn dầu đang tác động lên C0 từ B0 được chuyển mạch và tốc độ được chuyển lên số truyền tăng O/D. Khi công tắc số truyền tăng tắt “OFF”, nó không thể chuyển lên số o/D. Vì ECU không gửi tín hiệu ngắt van điện từ số 2. Áp suất thuỷ lực đến bộ truyền bánh răng hành tinh C1 từ van điều khiển C0 từ van chuyển số 3-4 B2 từ van chuyển số 1-2 C2 từ van chuyển số 2-3.","anchor":"block-1781161212996-qgtdn8hkl"},{"id":"s702","kind":"lesson","lesson":"4.4.1","title":"Hộp số tự động · Các phần tử của hộp số","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích điều chỉnh bán kính làm việc của CVT."},{"id":"s703","kind":"note","lesson":"4.4.1","title":"Phạm vi của CVT đai / xích","text":"Bài mô tả CVT dùng puli và đai. Không suy rộng thành cơ chế của mọi hệ truyền lực có tỷ số truyền biến thiên, đặc biệt hệ phân chia công suất thường gọi e-CVT. “Vô cấp” là biến thiên liên tục trong một dải tỷ số truyền hữu hạn."},{"id":"s704","kind":"simulation","lesson":"4.4.1","title":"Điều chỉnh bán kính làm việc của CVT","text":"1. Xác định trạng thái tỷ số truyền lớn. Bán kính sơ cấp nhỏ, bán kính thứ cấp lớn; hai trạng thái tồn tại đồng thời. 2. Ra lệnh chuyển sang tỷ số truyền nhỏ hơn. Điều khiển làm hai mặt côn sơ cấp gần nhau, phía thứ cấp phối hợp tách ra. 3. Hai bán kính làm việc thay đổi phối hợp. Đai ra xa tâm sơ cấp và vào gần tâm thứ cấp đồng thời theo ràng buộc hình học. 4. Xác lập tỷ số truyền theo bán kính mới. Bỏ qua trượt: i = n sơ cấp / n thứ cấp = r thứ cấp / r sơ cấp; tỷ số biến thiên liên tục trong giới hạn thiết kế."},{"id":"s705","kind":"figure","lesson":"4.4.1","title":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","text":"A. Puli V sơ cấp. Nhận mô men đầu vào và tạo bán kính làm việc phía chủ động. B. Puli V thứ cấp. Nhận mô men qua đai truyền và đưa tới trục đầu ra. C. Đai truyền. Truyền mô men giữa hai cặp bề mặt ma sát hình côn. D. Bánh răng mặt trời. Là phần tử của bộ bánh răng hành tinh đổi chiều quay.","figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s706","kind":"part","lesson":"4.4.1","title":"Puli V sơ cấp","text":"Nhận mô men đầu vào và tạo bán kính làm việc phía chủ động.","keywords":["Puli V sơ cấp"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s707","kind":"part","lesson":"4.4.1","title":"Puli V thứ cấp","text":"Nhận mô men qua đai truyền và đưa tới trục đầu ra.","keywords":["Puli V thứ cấp"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s708","kind":"part","lesson":"4.4.1","title":"Đai truyền","text":"Truyền mô men giữa hai cặp bề mặt ma sát hình côn.","keywords":["Đai truyền"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s709","kind":"part","lesson":"4.4.1","title":"Bánh răng mặt trời","text":"Là phần tử của bộ bánh răng hành tinh đổi chiều quay.","keywords":["Bánh răng mặt trời"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s710","kind":"figure","lesson":"4.4.1","title":"Hình 4.57. Bộ truyền đai vô cấp trên hộp số xe Ford CTX","text":"Hình 4.57. Bộ truyền đai vô cấp trên hộp số xe Ford CTX","anchor":"block-1781161309826-osbdqsbw2","figure":{"number":"4.57","caption":"Hình 4.57. Bộ truyền đai vô cấp trên hộp số xe Ford CTX"}},{"id":"s711","kind":"html","lesson":"4.4.1","title":"Hộp số tự động · Các phần tử của hộp số","text":"So với hộp số tự động có cấp, hộp số tự động vô cấp có nhiều ưu điểm hơn, đặc biệt là khả năng tận dụng triệt để công suất của động cơ. Tuy nhiên nó vẫn bị hạn chế bởi khả năng truyền mômen xoắn và công nghệ chế tạo phức tạp. Hộp số tự động vô cấp thường có các bộ phận chính như sau: + Bộ bánh răng hành tinh để đổi chiều quay trục sơ cấp. + Truyền động vô cấp nhờ ma sát. Xét cấu tạo và nguyên lý của hộp số tự động vô cấp Ford CTX. Hộp số gồm có hai trục: trục sơ cấp và trục thứ cấp, bộ phận quan trọng nhất của hộp số Ford CTX là hai cặp bề mặt ma sát hình côn chế tạo bằng thép. Ở mỗi cặp có một bề mặt cố định và một bề mặt di động theo chiều dọc trục, mômen xoắn được truyền từ cặp bề mặt ma sát chủ động sang cặp bề mặt ma sát bị động nhờ một đai truyền dẻo bằng thép được chế tạo theo một nguyên lý hoàn toàn mới.","anchor":"block-1781161309826-osbdqsbw2"},{"id":"s712","kind":"html","lesson":"4.4.1","title":"Hộp số tự động · Các phần tử của hộp số","text":"Đai truyền này gồm 320 phần tử bằng thép được xếp cạnh nhau và đặt nằm ngang so với đường trục của sợi đai truyền. Mômen xoắn được truyền từ trục chủ động sang trục bị động là nhờ ma sát giữa các phần tử nằm ngang và các bề mặt hình côn. Khi làm việc các phần tử này sẽ chịu một áp suất rất lớn giữa bề mặt của chúng và bề mặt của các đĩa hình côn. Mặt khác các lớp thép chạy theo chiều dọc lại chịu một sức căng rất lớn (mỗi lớp sợi thép mỏng có bề dày 0,1 mm và được đặt chồng lên nhau thành nhiều lớp). Hệ số ma sát giữa bề mặt của đai truyền và bề mặt của tấm ma sát tương đối nhỏ, do đó để truyền mômen xoắn mà không bị trượt thì giữa các đai truyền và các bề mặt ma sát hình côn phải xuất hiện một lực nén rất lớn (20.000N). Theo hướng truyền mômen xoắn từ động cơ xuống, ngay sau bánh đà động cơ là bộ phận giảm chấn xoắn.","anchor":"block-1781161309826-osbdqsbw2"},{"id":"s713","kind":"html","lesson":"4.4.1","title":"Hộp số tự động · Các phần tử của hộp số","text":"Nó có tác dụng giới hạn các rung động khi chạy không tải và làm giảm các tải trọng động từ động cơ lên hệ thống truyền lực trong trường hợp tài xế tăng hoặc giảm ga đột ngột. Từ trục thứ cấp của giảm chấn xoắn, mômen xoắn được truyền đến cần của bộ bánh răng hành tinh trên cơ cấu hành tinh (Hình 4.57) các trục của bánh răng vệ tinh một đầu được nối với cần (lồng răng) và đầu kia được nối với ly hợp tiến, ly hợp này đóng hay mở là nhờ sự thay đổi áp suất của dầu thủy lực điều khiển nó (ly hợp ma sát ướt). Mặt khác bánh răng bao của bộ bánh răng hành tinh được nối với ly hợp lùi cũng là loại ma sát ướt.","anchor":"block-1781161309826-osbdqsbw2"},{"id":"s714","kind":"html","lesson":"4.4.1","title":"Hộp số tự động · Các phần tử của hộp số","text":"Nếu ly hợp tiến đóng và ly hợp lùi mở, lập tức bộ bánh răng hành tinh bị hãm (các bánh răng vệ tinh không quay) lúc này các bộ phận của bộ bánh răng hành tinh đều quay như một khối động học liền (không có sự mất năng lượng trong bộ bánh răng hành tinh) bởi vậy mômen xoắn được truyền trực tiếp từ cần của bộ bánh răng hành tinh qua cặp đĩa ma sát hình côn trên trục chủ động của hộp số. Do đó chiều quay của trục sơ cấp hộp số sẽ cùng chiều với chiều quay của trục khuỷu động cơ và lúc này xe chuyển động theo chiều tiến. Trường hợp ngược lại, nếu ly hợp tiến mở và ly hợp lùi đóng, lập tức bộ bánh răng hành tinh trở lại trạng thái làm việc tự do (không bị hãm). Nhờ vậy, trục sơ cấp của hộp số sẽ đổi chiều quay và quay ngược với chiều quay của cốt máy, lúc này chiều quay của bánh xe chủ động cũng bị đổi chiều và xe sẽ chuyển động lùi.","anchor":"block-1781161309826-osbdqsbw2"},{"id":"s715","kind":"lesson","lesson":"4.4.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích điều chỉnh bán kính làm việc của CVT."},{"id":"s716","kind":"note","lesson":"4.4.2","title":"Hai puli thay đổi phối hợp","text":"Khi hai mặt côn sơ cấp tiến gần nhau, bán kính làm việc sơ cấp tăng; phía thứ cấp phối hợp theo chiều giảm bán kính. Đây là quá trình đồng thời, không phải thao tác nối tiếp hai puli. Bỏ qua trượt: i_CVT = n_sơ_cấp / n_thứ_cấp = r_thứ_cấp / r_sơ_cấp. Giới hạn i_min, i_max tùy thiết kế."},{"id":"s717","kind":"simulation","lesson":"4.4.2","title":"Điều chỉnh bán kính làm việc của CVT","text":"1. Xác định trạng thái tỷ số truyền lớn. Bán kính sơ cấp nhỏ, bán kính thứ cấp lớn; hai trạng thái tồn tại đồng thời. 2. Ra lệnh chuyển sang tỷ số truyền nhỏ hơn. Điều khiển làm hai mặt côn sơ cấp gần nhau, phía thứ cấp phối hợp tách ra. 3. Hai bán kính làm việc thay đổi phối hợp. Đai ra xa tâm sơ cấp và vào gần tâm thứ cấp đồng thời theo ràng buộc hình học. 4. Xác lập tỷ số truyền theo bán kính mới. Bỏ qua trượt: i = n sơ cấp / n thứ cấp = r thứ cấp / r sơ cấp; tỷ số biến thiên liên tục trong giới hạn thiết kế."},{"id":"s718","kind":"figure","lesson":"4.4.2","title":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","text":"A. Puli V sơ cấp. Nhận mô men đầu vào và tạo bán kính làm việc phía chủ động. B. Puli V thứ cấp. Nhận mô men qua đai truyền và đưa tới trục đầu ra. C. Đai truyền. Truyền mô men giữa hai cặp bề mặt ma sát hình côn. D. Bánh răng mặt trời. Là phần tử của bộ bánh răng hành tinh đổi chiều quay.","figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s719","kind":"part","lesson":"4.4.2","title":"Puli V sơ cấp","text":"Nhận mô men đầu vào và tạo bán kính làm việc phía chủ động.","keywords":["Puli V sơ cấp"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s720","kind":"part","lesson":"4.4.2","title":"Puli V thứ cấp","text":"Nhận mô men qua đai truyền và đưa tới trục đầu ra.","keywords":["Puli V thứ cấp"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s721","kind":"part","lesson":"4.4.2","title":"Đai truyền","text":"Truyền mô men giữa hai cặp bề mặt ma sát hình côn.","keywords":["Đai truyền"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s722","kind":"part","lesson":"4.4.2","title":"Bánh răng mặt trời","text":"Là phần tử của bộ bánh răng hành tinh đổi chiều quay.","keywords":["Bánh răng mặt trời"],"figure":{"image":"content/resources/T1_image253.jpg","caption":"Hình 4.57 — Bộ truyền đai vô cấp trên hộp số xe Ford CTX","number":"4.57"}},{"id":"s723","kind":"html","lesson":"4.4.2","title":"Hộp số tự động · Nguyên lý hoạt động","text":"Nguyên lý làm việc của hộp số FORD CTX rất đơn giản: mômen xoắn được truyền bởi đai truyền nằm giữa các bề mặt ma sát hình côn. Sự dịch chuyển tương đối giữa chúng theo chiều trục sẽ thay đổi liên tục tỷ số truyền, điều này phụ thuộc vào vị trí tương đối giữa đai truyền và trục tương ứng. Khi các bề mặt ma sát xa nhau ra trên một trục nào đó thì tại trục đó khoảng cách giữa đai truyền và trục đó giảm dần, ngược lại nếu hai bề mặt ma sát hình côn tiến lại gần nhau thì khoảng cách giữa đai truyền và trục tương ứng sẽ tăng lên. Hai quá trình này xảy ra đồng thời ở trên hai trục và ngược chiều nhau bởi vậy tỷ số truyền từ trục chủ động sang trục bị động sẽ tăng hoặc giảm liên tục do sự chuyển động của các bề mặt ma sát di động so với bề mặt ma sát cố định là liên tục.","anchor":"block-1781161333546-4qctmizav"},{"id":"s724","kind":"lesson","lesson":"5.1.1","title":"Hộp số phân phối · Chức năng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Chức năng."},{"id":"s725","kind":"simulation","lesson":"5.1.1","title":"Nguyên lý: Chức năng","text":"1. Nhận mô men từ hộp số chính. Hộp số phân phối đặt sau hộp số chính trên xe nhiều cầu chủ động. 2. Đưa mô men vào hộp phân phối. Các phần tử truyền phân chia đường truyền theo kết cấu. 3. Phân phối tới cầu sau. Trục ra đưa mô men tới cầu chủ động phía sau. 4. Phân phối tới cầu trước khi được nối. Nhánh cầu trước nhận mô men theo trạng thái của hộp phân phối."},{"id":"s726","kind":"figure","lesson":"5.1.1","title":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","text":"A. Bánh răng chủ động. Nhận mô men từ trục vào hộp phân phối. B. Bánh răng trung gian. Truyền giữa bánh răng chủ động và bị động, bảo đảm chiều quay trong sơ đồ. C. Bánh răng bị động. Truyền mô men tới các trục ra. D. Khớp gài cầu trước. Nối hoặc tách trục ra cầu trước khỏi đường truyền mô men.","figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s727","kind":"part","lesson":"5.1.1","title":"Bánh răng chủ động","text":"Nhận mô men từ trục vào hộp phân phối.","keywords":["Bánh răng chủ động"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s728","kind":"part","lesson":"5.1.1","title":"Bánh răng trung gian","text":"Truyền giữa bánh răng chủ động và bị động, bảo đảm chiều quay trong sơ đồ.","keywords":["Bánh răng trung gian"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s729","kind":"part","lesson":"5.1.1","title":"Bánh răng bị động","text":"Truyền mô men tới các trục ra.","keywords":["Bánh răng bị động"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s730","kind":"part","lesson":"5.1.1","title":"Khớp gài cầu trước","text":"Nối hoặc tách trục ra cầu trước khỏi đường truyền mô men.","keywords":["Khớp gài cầu trước"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s731","kind":"html","lesson":"5.1.1","title":"Hộp số phân phối · Chức năng","text":"Hộp số phân phối được bố trí ở sau hộp số chính trên ô tô nhiều cầu chủ động, với chức năng phân chia mô men xoắn từ động cơ tới các cầu chủ động, dẫn động bánh xe.","anchor":"block-1781161815806-5noatwyr4"},{"id":"s732","kind":"lesson","lesson":"5.1.2","title":"Hộp số phân phối · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân loại hộp phân phối."},{"id":"s733","kind":"simulation","lesson":"5.1.2","title":"Trình tự phân loại hộp phân phối","text":"1. Đếm cấp số truyền. Một cấp hay hai cấp là đặc điểm tỷ số truyền. 2. Đếm các trục ra. Số trục ra độc lập với số cấp số truyền. 3. Xét cách phân chia mô men. Phân biệt mô men cố định hay có bộ vi sai. 4. Xét cách dẫn động các cầu. Kết luận thường xuyên hoặc gián đoạn theo sơ đồ."},{"id":"s734","kind":"figure","lesson":"5.1.2","title":"Phân loại hộp số phân phối — sơ đồ học tập biên soạn từ bài 5.1.2","text":"A. Số lượng cấp số truyền. Tiêu chí số tỷ số truyền của hộp phân phối. B. Số lượng trục ra. Tiêu chí số đầu ra truyền tới các cầu. C. Đặc điểm phân chia mô men truyền. Tiêu chí phân phối mô men tới các cầu. D. Phương pháp dẫn động. Tiêu chí tổ chức dẫn động các cầu theo tài liệu.","figure":{"image":"tuong_tac/diagrams/transferclasses.svg","caption":"Phân loại hộp số phân phối — sơ đồ học tập biên soạn từ bài 5.1.2"}},{"id":"s735","kind":"part","lesson":"5.1.2","title":"Số lượng cấp số truyền","text":"Tiêu chí số tỷ số truyền của hộp phân phối.","keywords":["Số lượng cấp số truyền"],"figure":{"image":"tuong_tac/diagrams/transferclasses.svg","caption":"Phân loại hộp số phân phối — sơ đồ học tập biên soạn từ bài 5.1.2"}},{"id":"s736","kind":"part","lesson":"5.1.2","title":"Số lượng trục ra","text":"Tiêu chí số đầu ra truyền tới các cầu.","keywords":["Số lượng trục ra"],"figure":{"image":"tuong_tac/diagrams/transferclasses.svg","caption":"Phân loại hộp số phân phối — sơ đồ học tập biên soạn từ bài 5.1.2"}},{"id":"s737","kind":"part","lesson":"5.1.2","title":"Đặc điểm phân chia mô men truyền","text":"Tiêu chí phân phối mô men tới các cầu.","keywords":["Đặc điểm phân chia mô men truyền"],"figure":{"image":"tuong_tac/diagrams/transferclasses.svg","caption":"Phân loại hộp số phân phối — sơ đồ học tập biên soạn từ bài 5.1.2"}},{"id":"s738","kind":"part","lesson":"5.1.2","title":"Phương pháp dẫn động","text":"Tiêu chí tổ chức dẫn động các cầu theo tài liệu.","keywords":["Phương pháp dẫn động"],"figure":{"image":"tuong_tac/diagrams/transferclasses.svg","caption":"Phân loại hộp số phân phối — sơ đồ học tập biên soạn từ bài 5.1.2"}},{"id":"s739","kind":"html","lesson":"5.1.2","title":"Hộp số phân phối · Phân loại","text":"Hộp số phân phối được phân loại theo: Cố định hoặc thay đổi nhờ các bộ vi sai trong hộp phân phối. Luôn luôn dẫn động (full time – AWD), chỉ dẫn các cầu 1 thời gian, hoặc bán tự động","anchor":"block-1781161837273-q0jxxuxyn"},{"id":"s740","kind":"lesson","lesson":"5.2.1","title":"Hộp số phân phối · Cấu tạo","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nối và tách cầu trước ở hộp phân phối đơn giản."},{"id":"s741","kind":"note","lesson":"5.2.1","title":"Dẫn động hai cầu gián đoạn","text":"Với hộp phân phối không có vi sai giữa các cầu, khi nối cứng hai cầu sẽ phát sinh ràng buộc tốc độ. Không dùng sơ đồ này để kết luận có thể cài hai cầu trên mọi mặt đường bám tốt mà không gây căng truyền lực."},{"id":"s742","kind":"simulation","lesson":"5.2.1","title":"Nối và tách cầu trước ở hộp phân phối đơn giản","text":"1. Chế độ một cầu chủ động. Khớp gài mở; mô men truyền tới cầu sau trong sơ đồ đơn giản. 2. Chuẩn bị nối cầu trước. Với khớp gài vấu răng của sơ đồ, tài liệu yêu cầu thực hiện khi xe đứng yên. 3. Đóng khớp gài cầu trước. Khớp gài nối bánh răng bị động với trục ra cầu trước. 4. Hai cầu cùng nhận mô men. Cầu trước và sau được nối; trên đường tốt cần tách cầu trước theo tài liệu."},{"id":"s743","kind":"figure","lesson":"5.2.1","title":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","text":"A. Bánh răng chủ động. Nhận mô men từ trục vào hộp phân phối. B. Bánh răng trung gian. Truyền giữa bánh răng chủ động và bị động, bảo đảm chiều quay trong sơ đồ. C. Bánh răng bị động. Truyền mô men tới các trục ra. D. Khớp gài cầu trước. Nối hoặc tách trục ra cầu trước khỏi đường truyền mô men.","figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s744","kind":"part","lesson":"5.2.1","title":"Bánh răng chủ động","text":"Nhận mô men từ trục vào hộp phân phối.","keywords":["Bánh răng chủ động"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s745","kind":"part","lesson":"5.2.1","title":"Bánh răng trung gian","text":"Truyền giữa bánh răng chủ động và bị động, bảo đảm chiều quay trong sơ đồ.","keywords":["Bánh răng trung gian"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s746","kind":"part","lesson":"5.2.1","title":"Bánh răng bị động","text":"Truyền mô men tới các trục ra.","keywords":["Bánh răng bị động"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s747","kind":"part","lesson":"5.2.1","title":"Khớp gài cầu trước","text":"Nối hoặc tách trục ra cầu trước khỏi đường truyền mô men.","keywords":["Khớp gài cầu trước"],"figure":{"image":"content/resources/T1_image254.jpg","caption":"Hình 5.1 — Cấu tạo hộp phân phối đơn giản","number":"5.1"}},{"id":"s748","kind":"figure","lesson":"5.2.1","title":"Hình 5.1. Cấu tạo hộp phân phối đơn giản","text":"Hình 5.1. Cấu tạo hộp phân phối đơn giản","anchor":"block-1781161888664-tk8pkgity","figure":{"number":"5.1","caption":"Hình 5.1. Cấu tạo hộp phân phối đơn giản"}},{"id":"s749","kind":"figure","lesson":"5.2.1","title":"Hình 5.2. Cấu tạo hộp phân phối hai cấp số truyền","text":"Hình 5.2. Cấu tạo hộp phân phối hai cấp số truyền","anchor":"block-1781161888664-tk8pkgity","figure":{"number":"5.2","caption":"Hình 5.2. Cấu tạo hộp phân phối hai cấp số truyền"}},{"id":"s750","kind":"html","lesson":"5.2.1","title":"Hộp số phân phối · Cấu tạo","text":"Với loại 4WD này, người lái phải chuyển đổi giữa chế độ 2WD và 4WD bằng hộp số phụ theo điều kiện của đường sá. Bình thường, xe chạy theo chế độ 2WD, còn khi đường xấu và có tuyết,..v.v.. thì sử dụng 4WD. Tuy nhiên, vì hệ thống 4WD gián đoạn có các hệ thống truyền lực phía trước và phía sau nối trực tiếp với nhau, nên xảy ra hiện tượng phanh khi quay vòng, và xe không thể quay vòng được êm. Vì vậy, cần phải chuyển từ chế độ 4WD về 2WD khi xe chạy trên đường bình thường. Đây là hệ dẫn động phổ biến nhất trên các mẫu xe địa hình, nó hoạt động sau khi tài xế nhấn nút hoặc chuyển chế độ. Khi tài xế chuyển chế độ từ 2WD sang 4WD trên hộp số phụ, trục trước và trục sau khóa lại với nhau, dẫn đến các bánh trước và bánh sau quay với cùng một tốc độ, giúp cải thiện độ bám đường trong điều kiện xe đi thẳng.","anchor":"block-1781161888664-tk8pkgity"},{"id":"s751","kind":"html","lesson":"5.2.1","title":"Hộp số phân phối · Cấu tạo","text":"Trước khi có vi sai trung tâm, hệ dẫn động này gần như không có cách nào để các bánh quay với vận tốc khác nhau tại những khúc cua. Vì vậy, rất ít khi tài xế kích hoạt chế độ 2 cầu trừ khi xe di chuyển trên những mặt đường trơn trượt (như trên tuyết) hoặc sa lầy. Nếu cố gắng lái một chiếc xe trên đường khô, khi ở chế độ 4 bánh được kích hoạt, tài xế sẽ cảm thấy khó khăn và bánh cứng lại khi chuyển hướng. Ngoài ra, điều này có thể làm hỏng các thiết bị trong bộ truyên động và khiến lốp mòn nhanh hơn. 4WD gián đoạn có những điểm đáng lưu ý cần thiết cho những ai đang sử dụng, đặc điểm đầu tiên là ở chế độ bình thường xe dẫn động thông qua một cầu (2WD), thông thường là cầu sau. Việc cài cầu hoặc cắt cầu hoàn toàn do tài xế. Khi chuyển sang chế độ 4WD, công suất từ động cơ được truyền cho cả 4 bánh xe.","anchor":"block-1781161888664-tk8pkgity"},{"id":"s752","kind":"html","lesson":"5.2.1","title":"Hộp số phân phối · Cấu tạo","text":"Trong điều kiện cần thiết, tài xê có thể chọn chế độ 2 cầu số chậm để cải thiện mô-men xoắn. 4WD gián đoạn không có vi sai trung tâm và được khuyên cáo là không sử dụng 4WD trên mặt đường khô hay quá cứng. Có cấu tạo đơn gian hơn so với các hệ dẫn động 4 bánh khác. Giá thành thấp và không quá phức tạp. điều này giải thích tại sao nó lại xuất trên những mẫu xe rẻ tiền và ở cấp thấp. Ít tổn nhiên liệu hơn so với 4WD thường xuyên. Có yêu cầu khắc khe đó là tài xế phải dừng trước khi chuyển từ chế độ 2WD sang 4WD. Nó khiến người lái phải chịu trách nhiệm hoàn toàn vào quyết định cài cầu của mình, tùy thuộc vào địa hình và thời tiết. Vì chuyện cắt cầu cũng quan trọng không hề kém. Khi quay vòng sẽ xuất hiện hiện tượng tuần hoàn công suất. Quay vòng không êm.","anchor":"block-1781161888664-tk8pkgity"},{"id":"s753","kind":"html","lesson":"5.2.1","title":"Hộp số phân phối · Cấu tạo","text":"Sơ đồ cấu tạo của hộp số phân phối đơn giản được trình bày như hình sau: 1-Bánh răng chủ động; 2-Bánh răng trung gian; 3-Bánh răng bịđộng; 4-Khớp gài cầu trước. 1-Bánh răng gài số; 2-Bánh răng ra cầu sau; 3-Bánh răng sốthấp; 4-Bánh răng gài cầu trước; 5-Bánh răng ra cầu trước","anchor":"block-1781161888664-tk8pkgity"},{"id":"s754","kind":"lesson","lesson":"5.2.2","title":"Hộp số phân phối · Nguyên lý hoạt động","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự khóa hãm ở hộp phân phối hai cấp."},{"id":"s755","kind":"simulation","lesson":"5.2.2","title":"Trình tự khóa hãm ở hộp phân phối hai cấp","text":"1. Gài cầu trước trước. Cơ cấu khóa hãm yêu cầu nối cầu trước trước khi dùng số truyền thấp. 2. Gài số truyền thấp. Bánh răng gài số ăn khớp bánh răng số thấp, mô men tăng và tốc độ giảm. 3. Nhả số truyền thấp trước. Khi trở lại số truyền thẳng, phải nhả số thấp trước khi tách cầu trước. 4. Nhả cầu trước sau. Chỉ sau khi nhả số thấp mới nhả cầu trước theo cơ cấu khóa hãm của hình 5.2."},{"id":"s756","kind":"figure","lesson":"5.2.2","title":"Hình 5.2 — Cấu tạo hộp phân phối hai cấp số truyền","text":"A. Bánh răng gài số. Dịch chuyển để chọn số truyền thẳng hoặc số truyền thấp. B. Bánh răng ra cầu sau. Truyền mô men tới trục ra cầu sau. C. Bánh răng số thấp. Tạo tỷ số truyền lớn hơn ở cấp số truyền thấp. D. Bánh răng gài cầu trước. Nối đường truyền tới cầu trước. E. Bánh răng ra cầu trước. Truyền mô men tới trục ra cầu trước.","figure":{"image":"content/resources/T1_image255.jpg","caption":"Hình 5.2 — Cấu tạo hộp phân phối hai cấp số truyền","number":"5.2"}},{"id":"s757","kind":"part","lesson":"5.2.2","title":"Bánh răng gài số","text":"Dịch chuyển để chọn số truyền thẳng hoặc số truyền thấp.","keywords":["Bánh răng gài số"],"figure":{"image":"content/resources/T1_image255.jpg","caption":"Hình 5.2 — Cấu tạo hộp phân phối hai cấp số truyền","number":"5.2"}},{"id":"s758","kind":"part","lesson":"5.2.2","title":"Bánh răng ra cầu sau","text":"Truyền mô men tới trục ra cầu sau.","keywords":["Bánh răng ra cầu sau"],"figure":{"image":"content/resources/T1_image255.jpg","caption":"Hình 5.2 — Cấu tạo hộp phân phối hai cấp số truyền","number":"5.2"}},{"id":"s759","kind":"part","lesson":"5.2.2","title":"Bánh răng số thấp","text":"Tạo tỷ số truyền lớn hơn ở cấp số truyền thấp.","keywords":["Bánh răng số thấp"],"figure":{"image":"content/resources/T1_image255.jpg","caption":"Hình 5.2 — Cấu tạo hộp phân phối hai cấp số truyền","number":"5.2"}},{"id":"s760","kind":"part","lesson":"5.2.2","title":"Bánh răng gài cầu trước","text":"Nối đường truyền tới cầu trước.","keywords":["Bánh răng gài cầu trước"],"figure":{"image":"content/resources/T1_image255.jpg","caption":"Hình 5.2 — Cấu tạo hộp phân phối hai cấp số truyền","number":"5.2"}},{"id":"s761","kind":"part","lesson":"5.2.2","title":"Bánh răng ra cầu trước","text":"Truyền mô men tới trục ra cầu trước.","keywords":["Bánh răng ra cầu trước"],"figure":{"image":"content/resources/T1_image255.jpg","caption":"Hình 5.2 — Cấu tạo hộp phân phối hai cấp số truyền","number":"5.2"}},{"id":"s762","kind":"html","lesson":"5.2.2","title":"Nguyên lý hoạt động · a. Hộp phân phối đơn giản","text":"Hộp phân phối nhận mô men truyền từ hộp số tới qua trục vào và phân phối mô men đến cầu trước, cầu sau bằng hai trục ra. Hộp phân phối bốtrí một bánh răng trung gian cho phép các trục vào và trục ra có cùng chiều quay với tốc độ bằng nhau. Các bánh răng 1, 3 có số răng như nhau, do vậy hộp phân phối chỉ có một cấp số truyền, tỉ số truyền bằng 1. Trên trục ra cầu trước bố trí một khớp gài. Khớp gài 4 đóng nối trục của bánh răng 3 với trục ra cầu trước, xe hoạt động bằng hai cầu chủ động. Khi không gài khớp 4, cầu trước được tách khỏi hệ thống truyền lực, xe hoạt động bằng cầu sau chủ động. Hộp phân phối này cho phép động cơ dẫn động tất cả các cầu khi xe hoạt động trên đường xấu. Khi chuyển động trên đường tốt cầu trước được tách khỏi hệ thống truyền lực, nhằm tránh xảy ra hiện tượng tuần hoàn công suất.","anchor":"block-1781161916808-3i03hre7s"},{"id":"s763","kind":"html","lesson":"5.2.2","title":"Nguyên lý hoạt động · a. Hộp phân phối đơn giản","text":"Như vậy hộp phân phối thuộc kết cấu dẫn động tất cả các cầu một phần thời gian. Khi đóng khớp gài 4 bằng các vấu răng thường xảy ra va chạm mạnh, do vậy việc đóng khớp cần được tiến hành khi xe đứng yên. Việc sử dụng bánh răng trung gian 2 cho phép tăng khoảng cách giữa hai trục ra và vào, phù hợp với khả năng bố trí chung trên không gian của ô tô. Một số kết cấu khác sử dụng bộ truyền xích có thể loại bỏ bánh răng trung gian khi cần khoảng cách trục lớn. Ngày nay, hộp phân phối một cấp đơn giản được bốtrí trên ô tô con 2 cầu chủ động, nhưng được kết hợp với khớp ma sát hay bộ vi sai phân phối mô men ra các cầu.","anchor":"block-1781161916808-3i03hre7s"},{"id":"s764","kind":"html","lesson":"5.2.2","title":"Nguyên lý hoạt động · b. Hộp phân phối hai cấp số truyền","text":"Cấp số truyền thẳng được gài khi bánh răng 1 dịch chuyển sang bên phải, ăn khóp với vành răng trong của bánh răng 2. Mô men xoắn từtrục chủ động truyền trực tiếp tới trục ra cầu sau. Bánh răng 4 nằm ở vị trí trung gian, mô men xoắn không truyền tới trục ra cầu trước, ô tô chuyên động bằng cầu sau chủ động. Để gài cầu trước, bánh răng 4 di chuyển sang phải, ăn khớp đồng thời với bánh răng 2 và 5 (có đường kính ăn khớp như nhau). Lúc này mô men xoắn từ trục chủ động truyền qua bánh răng 2, 4, và 5 tới trục ra cầu trước. Ô tô chuyển động bằng cả hai cầu chủ động ở số truyền thẳng. Cấp số truyền thấp được gài khi bánh răng l địch chuyển sang bên trái, ăn khớp với bánh răng 3; bánh răng 4 ăn khớp đồng thời với bánh răng 2 và 5. Mômen truyền từ trục chủ động qua cặp bánh răng 1, 3 tới trục trung gian và các bánh răng 4, 2.","anchor":"block-1781161939506-2l4q9qgha"},{"id":"s765","kind":"html","lesson":"5.2.2","title":"Nguyên lý hoạt động · b. Hộp phân phối hai cấp số truyền","text":"5 đến các trục ra cầu sau, cầu trước,ởsốtruyền thấp, nhờcặp bánh răng1, 3 cótỉsốtruyền lớn hơnởsốtruyền thẳng nên mô men truyền tới cầu xe tănglên và tốc độchuyển động giảm thấp. Đểtránh quá tảicho cầu sau khi gài sốtruyền thấp, trên cơ cấu điều khiển bốtrí cơ cấu khóa hãm để:Gài cầu trước trước khi gài số truyền thấp và nhả số truyền thấp trước khi nhả cầu trước. Dẫn động điều khiển hộp phân phối nhờhai cần điều khiển: cần chuyển số điều khiển dịch chuyển bánh răng 1, cần gài cầu trước điều khiển dịch chuyển bánh răng 4 nhờ các trục trượt. Cơ cấu khóa bố trí trên các trục trượt với các chốt tỳvà rãnh lõm có chiều sâu khác nhau thực hiện chức năng khóa hãm kể trên. Các trạng thái di chuyển trục trượt và vị trí làm việc của khóa hãm trình bày trên Hình 5.2 ứng với hai trạng thái a, b.","anchor":"block-1781161939506-2l4q9qgha"},{"id":"s766","kind":"html","lesson":"5.2.2","title":"Nguyên lý hoạt động · b. Hộp phân phối hai cấp số truyền","text":"Trạng thái a: các chi tiết của cơ cấu khóa hãm ở chế độ sử dụng số truyền thẳng khi đã gài cầu trước, khe hở A trong khóa lớn hơn chiều sâu rãnh và cho phép trục trượt gài cầu trước di chuyển. Trạng thái b: các chi tiết của cơ cấu khóa hãm ở chế độ sử dụng số truyền thấp khi đã gài cầu trước, khe hở trong khóa B nhỏ hơn chiều sâu rãnh, do vậy trục trượt gài cầu trước khóa không cho trục trượt chuyển số di chuyển. Kết cấu hộp phân phổi như vậy có hai trục ra bố trí lệch nhau cho phép tạo nên số truyền thẳng, hiệu suất truyền lực cao khi xe chuyển động ở tốc độ cao trên đường tốt.","anchor":"block-1781161939506-2l4q9qgha"},{"id":"s767","kind":"lesson","lesson":"5.3.1","title":"Hộp số phân phối · Cấu tạo","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích phân phối mô men trong dẫn động thường xuyên."},{"id":"s768","kind":"simulation","lesson":"5.3.1","title":"Phân phối mô men trong dẫn động thường xuyên","text":"1. Mô men tới bộ vi sai trung tâm. Đường truyền vào được chia thành nhánh trước và nhánh sau. 2. Hai nhánh truyền tới các cầu. Bộ vi sai trước và sau phân phối tới các bánh của từng cầu. 3. Các cầu có thể khác tốc độ khi quay vòng. Bộ vi sai trung tâm cho phép chênh lệch tốc độ giữa hai nhánh. 4. Khớp thủy lực tác động khi chênh lệch. Trong kết cấu mô tả, khớp góp phần truyền lực khi có chênh lệch trước–sau."},{"id":"s769","kind":"figure","lesson":"5.3.1","title":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1","text":"A. Bộ vi sai trung tâm. Cho phép chênh lệch tốc độ giữa đường truyền tới cầu trước và cầu sau. B. Bộ vi sai trước. Phân phối mô men tới các bánh chủ động của cầu trước. C. Bộ vi sai sau. Phân phối mô men tới các bánh chủ động của cầu sau. D. Khớp thủy lực. Tham gia truyền mô men giữa các nhánh theo kết cấu được trình bày.","figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s770","kind":"part","lesson":"5.3.1","title":"Bộ vi sai trung tâm","text":"Cho phép chênh lệch tốc độ giữa đường truyền tới cầu trước và cầu sau.","keywords":["Bộ vi sai trung tâm"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s771","kind":"part","lesson":"5.3.1","title":"Bộ vi sai trước","text":"Phân phối mô men tới các bánh chủ động của cầu trước.","keywords":["Bộ vi sai trước"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s772","kind":"part","lesson":"5.3.1","title":"Bộ vi sai sau","text":"Phân phối mô men tới các bánh chủ động của cầu sau.","keywords":["Bộ vi sai sau"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s773","kind":"part","lesson":"5.3.1","title":"Khớp thủy lực","text":"Tham gia truyền mô men giữa các nhánh theo kết cấu được trình bày.","keywords":["Khớp thủy lực"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s774","kind":"figure","lesson":"5.3.1","title":"Hình 5.3. Sơ đồ truyền lực xe AWD","text":"Hình 5.3. Sơ đồ truyền lực xe AWD","anchor":"block-1781162153502-39ztd661v","figure":{"number":"5.3","caption":"Hình 5.3. Sơ đồ truyền lực xe AWD"}},{"id":"s775","kind":"figure","lesson":"5.3.1","title":"Hình 5.4.So sánh khả năng dẫn động của xe 2WD và 4WD","text":"Hình 5.4.So sánh khả năng dẫn động của xe 2WD và 4WD","anchor":"block-1781162153502-39ztd661v","figure":{"number":"5.4","caption":"Hình 5.4.So sánh khả năng dẫn động của xe 2WD và 4WD"}},{"id":"s776","kind":"html","lesson":"5.3.1","title":"Hộp số phân phối · Cấu tạo","text":"Có thể sử dụng xe tại mọi thời điểm trong mọi điều kiện chạy xe và đường sá, từ đường sá bình thường đến đường sá gồ ghề và đường có hệ số ma sát thấp là loại 4WD thường xuyên. Ngoài ra, các xe 4WD thường được trang bị bộ vi sai trung tâm. Đối với loại 4WD thường xuyên, người ta bố trí thêm một bộ vi sai trung tâm ở giữa bộ vi sai trước và bộ vi sai sau để triệt tiêu sự chênh lệch tốc độ quay của các bánh xe trước và sau. Có 3 bộ vi sai khác nhau làm cho xe chạy được êm do đảm bảo việc truyền công suất đều nhau đến cả 4 bánh xe, kể cả khi quay vòng. Một vi sai ở câu xe phía trước, một ở câu xe phía sau và một vi sai trung tâm. Đây là ưu điểm chủ yếu của loại 4WD thường xuyên, nó có thể sử dụng trên đường xá bình thường, đường gồ ghề hay đường có độ ma sát thấp.","anchor":"block-1781162153502-39ztd661v"},{"id":"s777","kind":"html","lesson":"5.3.1","title":"Hộp số phân phối · Cấu tạo","text":"Tuy nhiên, để tránh hiện tượng bộ vi sai trung tâm phải làm việc liên tục thì các lốp trước và sau phải có đường kính giống nhau, kê cả các bánh bên trái và bên phải. Để đảm bảo tính điều khiển ổn định trong khi chạy ở các điều kiện đường xá khác nhau, ở loại 4WD thường xuyên người ta còn bộ trí thêm một khớp thủy lực làm cho xe thích hợp hơn ở chế độ 2WD khi không có sự chênh lệch về tốc độ quay giữa các bánh trước và sau. Khi xe chạy vào đường gô ghế hay đường có tuyết, xuất hiện, sự chênh lệch tốc độ quay giữa bánh trước và sau, hệ thống này lập tức truyền lực dẫn động từ bảnh trước đến các bảnh sau giúp cho xe chuyển động êm hơn. Không bắt tài xế phải lựa chọn chế độ, như vậy họ có thể tập trung điều khiển xe. Xe sẽ tự quyết định việc phân bố mô-men xoắn tới các trục. Tính ổn định tốt trên đường tuyết.","anchor":"block-1781162153502-39ztd661v"},{"id":"s778","kind":"html","lesson":"5.3.1","title":"Hộp số phân phối · Cấu tạo","text":"Do cả 4 bánh đều chủ động, lực kéo truyền tới mặt đường gấp đội xe 2WD, vì vậy nó có tính thông qua rất cao trên đường có hệ số ma sát thấp. Tính năng leo dốc tuyệt vời. Do lực kéo xấp xỉ gấp đối xe 2WD nê xe 4WD có thể leo những dốc mà xe 2WD không thể leo được. Tính ổn định khi quay vòng (không xảy ra hiện tượng tuần hoàn công suất bởi vì có vi sai trung tâm). Do 4 lốp đều truyền lực được thay vì hai lốp, tải trọng lên mỗi lốp giảm xuống và lực quay vòng của lốp có thể được sử dụng hiệu quả hơn, nên tính ôn định quay vòng tốt. Tính năng khởi hành và tăng tốc tốt.Độ bám đường của lốp xe 4WD gần gấp đôi xe 2WD nên ngay cả những xe có công suất lớn, lốp vẫn không bị trượt khi xe khởi hành hay tăng tốc Tính ổn định khi chuyển động thẳng.Trong xe 4WD, độ bám dư của từng lốp xe tăng lên, các thay đôi bên ngoài sẽ không ảnh hưởng đến xe.","anchor":"block-1781162153502-39ztd661v"},{"id":"s779","kind":"html","lesson":"5.3.1","title":"Hộp số phân phối · Cấu tạo","text":"Do vậy sẽ có được tính ổn định chuyển động thẳng. Nhược điểm của 4WD thường xuyên: Cấu tạo phức tạp.Cần một hộp số phụ, trục các đăng...để phân phối công suất đến các bánh trước và sau làm kết cầu thêm phức tạp. Trọng lượng tăng, Tăng các số lượng chi tiết như hộp số phụ, trục các đăng...làm tăng trọng lượng xe. Cho nên nó tiêu thụ nhiên liệu nhiêu hơn 4WD gián đoạn. Giá thành tăng, Cấu tạo phức tạp và số lượng chi tiết tăng làm tăng giá thành xe.Tăng tiếng ổn và rung động.Tăng số lượng các chi tiết quay (hộp số phụ, trục các đăng...) làm tăng nguồn phát ra tiếng ồn và rung động. Hệ thống truyền lực 4WD thường xuyên với khớp thủy lực Hệ thống truyền lực 4WD thường xuyên có khớp thủy lực làm cho xe có thể hoạt động thích hợp với chế độ 2WD trong thời gian chạy bình thường khi hầu như không có sự chênh lệch về tốc độ quay giữa các bánh xe trước và sau.","anchor":"block-1781162153502-39ztd661v"},{"id":"s780","kind":"html","lesson":"5.3.1","title":"Hộp số phân phối · Cấu tạo","text":"Khi có sự chênh lệch tốc độ quay giữa các bánh xe trước và sau như khi xe quay vòng hoặc chạy trên đường có tuyết trơn trượt, hệ thống này truyền lực dẫn động đến các bánh sau. Nhờ vậy mà nó đảm bảo tính điều khiển ổn định trong khi chạy ở các điều kiện đường xá và chạy xe khác nhau.","anchor":"block-1781162153502-39ztd661v"},{"id":"s781","kind":"lesson","lesson":"5.3.2","title":"Hộp số phân phối · Nguyên lý hoạt động","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích phân phối mô men trong dẫn động thường xuyên."},{"id":"s782","kind":"note","lesson":"5.3.2","title":"Phân phối mô men trong AWD","text":"Có vi sai hoặc khớp điều khiển giữa các cầu không đồng nghĩa luôn chia mô men 50:50. Tỷ lệ phụ thuộc kết cấu và trạng thái điều khiển. Cần phân biệt chênh lệch tốc độ với tỷ lệ mô men."},{"id":"s783","kind":"simulation","lesson":"5.3.2","title":"Phân phối mô men trong dẫn động thường xuyên","text":"1. Mô men tới bộ vi sai trung tâm. Đường truyền vào được chia thành nhánh trước và nhánh sau. 2. Hai nhánh truyền tới các cầu. Bộ vi sai trước và sau phân phối tới các bánh của từng cầu. 3. Các cầu có thể khác tốc độ khi quay vòng. Bộ vi sai trung tâm cho phép chênh lệch tốc độ giữa hai nhánh. 4. Khớp thủy lực tác động khi chênh lệch. Trong kết cấu mô tả, khớp góp phần truyền lực khi có chênh lệch trước–sau."},{"id":"s784","kind":"figure","lesson":"5.3.2","title":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1","text":"A. Bộ vi sai trung tâm. Cho phép chênh lệch tốc độ giữa đường truyền tới cầu trước và cầu sau. B. Bộ vi sai trước. Phân phối mô men tới các bánh chủ động của cầu trước. C. Bộ vi sai sau. Phân phối mô men tới các bánh chủ động của cầu sau. D. Khớp thủy lực. Tham gia truyền mô men giữa các nhánh theo kết cấu được trình bày.","figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s785","kind":"part","lesson":"5.3.2","title":"Bộ vi sai trung tâm","text":"Cho phép chênh lệch tốc độ giữa đường truyền tới cầu trước và cầu sau.","keywords":["Bộ vi sai trung tâm"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s786","kind":"part","lesson":"5.3.2","title":"Bộ vi sai trước","text":"Phân phối mô men tới các bánh chủ động của cầu trước.","keywords":["Bộ vi sai trước"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s787","kind":"part","lesson":"5.3.2","title":"Bộ vi sai sau","text":"Phân phối mô men tới các bánh chủ động của cầu sau.","keywords":["Bộ vi sai sau"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s788","kind":"part","lesson":"5.3.2","title":"Khớp thủy lực","text":"Tham gia truyền mô men giữa các nhánh theo kết cấu được trình bày.","keywords":["Khớp thủy lực"],"figure":{"image":"tuong_tac/diagrams/awd.svg","caption":"Các bộ vi sai trong dẫn động AWD — sơ đồ học tập biên soạn từ bài 5.3.1"}},{"id":"s789","kind":"figure","lesson":"5.3.2","title":"Hình 5.5. Hộp phân phối có bộ vi sai bánh răng côn","text":"Hình 5.5. Hộp phân phối có bộ vi sai bánh răng côn","anchor":"block-1781162172179-u85d68s8e","figure":{"number":"5.5","caption":"Hình 5.5. Hộp phân phối có bộ vi sai bánh răng côn"}},{"id":"s790","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · a. Hộp phân phối có bộ vi sai bánh răng côn","text":"Mômen xoắn từ hộp số truyền tới trục chủ động 7, trên trục bố trí hai bánh răng: bánh răng chủ động 8 và bánh răng truyền sang hộp giảm tốc tời 9. Trục trung gian đặt trên vỏ nhờ ổ bi, trên trục bố trí hai bánh răng quay trơn: bánh răng trung gian 5 và bánh răng số truyền thấp 11. Trục bị động là hai nửa trục, nối giũa hai nửa trục qua bộ vi sai. Một nửa trục dẫn động cầu trước, nửa trục còn lại dẫn động cầu sau. Bộ vi sai đặt trong vỏ vi sai 14.","anchor":"block-1781162172179-u85d68s8e"},{"id":"s791","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · a. Hộp phân phối có bộ vi sai bánh răng côn","text":"1-Mặt nối ra cầu trước; 2-Khớp gài cầu trước; 3-Bánhrăng sốcao; 4-Khớpgài sốcao; 5-Bánh răng trun.g gian; 6-Khớp gài sốthấp; 7-Trục chủđộng; 8-Bánh răng chủđộng; 9-Bánh răng gài tời; 10-Ống gài sốthấp; 11-Bánh răngsốthấp; 12-Trục trung gian; 13-Bánh răng sốthấp; 14-Vỏvi sai; 15-Trục racầu sau; 16-Bánh răng ra cầu sau; 17-Bánh răng vi sai; 18-Ống gài sốcao; 19-Vành ma sát đồng tốc; 20-Vành răng gài; 21-Trục ra cầu trước; 22-Ống gài trêncầu trước; 23-Ống gài trên vỏvi sai. Khớp gài 6 trên trục trung gian và khớp gài G1 trên trục bị động được điều khiển chung, thực hiện nhiệm vụ đổi số truyền, theo hai vịtrí (H, L).","anchor":"block-1781162172179-u85d68s8e"},{"id":"s792","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · a. Hộp phân phối có bộ vi sai bánh răng côn","text":"Khi G1 nằm ở bên trái thực hiện số truyền cao, khi G1 nằm ở bên phải-số truyền thấp. - Bánh răng 3 gài với vỏ vi sai qua khớp gài G1, thực hiện theo số truyền có tốc độ cao(số truyền cao-H) -Khớp gài 6 dịch chuyển sang phải, truyền mô men từ bánh răng 5 sang bánh răng 11 tới bánh răng 13 (vỏ bộ vi sai), thực hiện theo số truyền có tốc độ thấp (sốtruyền thấp-L). Bộ vi sai bánh răng côn đối xứng cho phép phân chia mô men ra các cầu theo tỷ lệ 50/50. Bộ truyền vi sai có hai bậc tự do, khi chuyển động trên đường xấu các cầu xe chuyển động trên nền có hệ số bám khác nhau, hai nửa trục có thể chuyển động với vận tốc khác nhau và không xuất hiện hiện tượng tuần hoàn công suất. Tuy nhiên khả năng cơ động của xe trong trường hợp này sẽ giảm. Để nâng cao khả năng cơ động, hộp phân phối bố trí khớp khóa vi sai G2.","anchor":"block-1781162172179-u85d68s8e"},{"id":"s793","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · a. Hộp phân phối có bộ vi sai bánh răng côn","text":"Khớp G2 bố trí khóa vỏ vi sai 14 với trục ra cầu trước 21 (hạn chế một bậc tự do), hai nửa trục quay cùng tốc độ. Khi khóa G2 trong hệ thống truyền lực xuất hiện hiện tượng tuần hoàn công suất. Do vậy việc thực hiện gài khớp G2 chỉ thực hiện trong một thời gian ngắn, trên đường xấu, với mô men động cơ nhỏ. Trên hộp phân phối này cơ cấu điều khiển bằng đòn bố trí với một cần điều khiển hay điều khiển bằng điện thông qua môtơ bước.","anchor":"block-1781162172179-u85d68s8e"},{"id":"s794","kind":"figure","lesson":"5.3.2","title":"Hình 5.6. Sơ đồ cấu trúc hộp phân phối có bộ vi sai bánh răng trụ","text":"Hình 5.6. Sơ đồ cấu trúc hộp phân phối có bộ vi sai bánh răng trụ","anchor":"block-1781162203987-25i227wx8","figure":{"number":"5.6","caption":"Hình 5.6. Sơ đồ cấu trúc hộp phân phối có bộ vi sai bánh răng trụ"}},{"id":"s795","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · b. Hộp phân phối có bộ vi sai bánh răng trụ","text":"1-Bánh răng chủđộng sốcao; 2-Bánh răng chủ động số thấp; 3-Bánh răng trung gian sốcao; 4-Bánh răng trung gian số thấp; 5-Bánh răng dẫn động vi sai; 6-Vỏ vi sai; 7-Bánh răng trung tâm S; 8-Bánh răng vi sai P; 9-Bánh răng bao H Khi khớp gài G1 ở vị trí bên trái, mô men truyền tới bánh răng 5 qua cặp bánh răng 1 và 3, thực hiện truyền số cao (H). Khi khớp gài G1 ở vị trí bên phải, mô men truyền tới bánh răng 5 qua cặp bánh răng 2 và 4, trục trung gian, qua cặp bánh răng 3 và 5, thực hiện số truyền thấp (L). Tỉ số mô men trên hai trục đó bằng tỉ số răng của bánh răng bao H và bánh răng trung tâm S và được chọn xấp xỉ bằng hai (tương ứng với sự phân bố tải trọng của cầu trước và hai cầu sau bằng 33/67). Cầu trước luôn luôn được truyền mô men xoắn thông qua bộ vi sai.","anchor":"block-1781162203987-25i227wx8"},{"id":"s796","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · b. Hộp phân phối có bộ vi sai bánh răng trụ","text":"Để gài cứng bộvi sai sử dụng khớp G2 nối trục của bánh răng trung tâmvới vò vi sai 6 thực hiện khoá một bậc tự do của cơ cấu Wilson. Hai trục ra quay cùng tốc độ. Tương tự như bộ vi sai bánh răng côn đối xứng, bộ vi sai bánh răng trụ cho phép phân chia mô men truyền phù hợp với xe 3 cầu chủ động có một trục dẫn xuyên thông ra hai cầu sau.","anchor":"block-1781162203987-25i227wx8"},{"id":"s797","kind":"figure","lesson":"5.3.2","title":"Hình 5.7. Sơ đồ cấu trúc hộp phân phối có bộ vi sai và ly hợp ma sát","text":"Hình 5.7. Sơ đồ cấu trúc hộp phân phối có bộ vi sai và ly hợp ma sát","anchor":"block-1781162238342-nnw3lc64j","figure":{"number":"5.7","caption":"Hình 5.7. Sơ đồ cấu trúc hộp phân phối có bộ vi sai và ly hợp ma sát"}},{"id":"s798","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · c. Hộp phân phối có bộ vi sai và ly hợp ma sát","text":"1-Trục chủ động; 2-Bộ ly hợp; 3-Vỏ vi sai côn; 4-Bộ truyền xích Trên ô tô con hai cầu chủ động sử dụng hộp phân phối có cấu trúc bộvi sai bánh răng côn đối xứng và một khớp ma sát làm việc trong dầu silicon. Sơ đồ cấu tạo được trình bày trên Hình 5.7. Hộp phân phối có một số truyền cố định. Trục chủ động 1 dẫn động bộ truyền vi sai bánh răng côn thông trục bánh răng vi sai và vỏ vi sai. Bánh răng vi sai thực hiện phân phối mô men truyền với tỷ lệ 50/50 ra cầu sau và cầu trước. Mô men truyền ra cầu trước thông qua khớp gài G2 và bộ truyền xích 4. Bộ ly hợp ma sát nhiều đĩa được đặt trong một hộp kín làm việc trong dầu silicon. Li hợp bố trí nối giữa vỏ vi sai và bánh răng nối ra trục cầu sau. Nhờ bộ li hợp ma sát cho phép khóa bớt sự sai lệch tốc độ giữa hai cầu khi xe chuyển động trên đường xấu.","anchor":"block-1781162238342-nnw3lc64j"},{"id":"s799","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · c. Hộp phân phối có bộ vi sai và ly hợp ma sát","text":"Sự sai lệch tốc độ càng lớn, ly hợp trượt nhiều, nhiệt độ phát sinh tăng cao. Dầu silicon có khả năng biến đổi độ nhớt theo nhiệt độ theo hướng tăng hệ số ma sát, do vậy tăng khá năng khóa cứng vi sai. Để ô tô hoạt động linh hoạt trên đuờng tốt, khớp G2 có thể tách cầu trước ra khỏi hệ thống truyền lực, ly hợp ma sát đóng vai trò khóa một bậc tự do và tạo điều kiện mô men truyền tới cầu sau. Ngày nay dầu silicon có khả năng tăng độ nhạy cảm giữa nhiệt độ và độ nhớt, nên trên một số ô tô con không bốtrí khớp gài G2 và hộp phân phối làm việc ở chế độ luôn luôn dẫn động tất cảcác cầu xe (full time). Khi bốtrí kết cấu luôn luôn dẫn động tất cả các cầu, hiện tượng tuần hoàn công suất phát sinh phụ thuộc vào lực ma sát sinh ra trong ly hợp và được hạn chế bởi sự trượt trong các đĩa ma sát của hộp phân phối.","anchor":"block-1781162238342-nnw3lc64j"},{"id":"s800","kind":"html","lesson":"5.3.2","title":"Nguyên lý hoạt động · c. Hộp phân phối có bộ vi sai và ly hợp ma sát","text":"Việc sử dụng bộ truyền xích cho phép tăng khoảng cách trục và trọng lượng của hộp phân phối nhỏ. Các hộp phân phối như thế thường được bố trí liền sau hộp số mà trọng lượng toàn bộ ô tô không gia tăng đáng kể. Tương tự như hộp phân phối dạng vi sai côn đối xứng còn có hộp phân phối dùng vi sai bánh răng trụ, hoặc hộp phân phối có hai cấp tốc độ bố trí trước bộ vi sai","anchor":"block-1781162238342-nnw3lc64j"},{"id":"s801","kind":"lesson","lesson":"6.1.1","title":"Truyền động các đăng · Chức năng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích thích ứng góc lệch và thay đổi chiều dài."},{"id":"s802","kind":"simulation","lesson":"6.1.1","title":"Thích ứng góc lệch và thay đổi chiều dài","text":"1. Cụm chủ động phát mô men. Truyền động các đăng nối các cụm có vị trí tương đối thay đổi. 2. Khớp các đăng truyền khi lệch góc. Khớp cho phép truyền mô men giữa các đường tâm không thẳng hàng. 3. Khớp trượt bù thay đổi chiều dài. Then hoa cho phép thân trục thay đổi chiều dài trong giới hạn làm việc. 4. Cụm bị động nhận mô men. Truyền động vừa bảo đảm truyền lực vừa thích ứng chuyển động tương đối."},{"id":"s803","kind":"figure","lesson":"6.1.1","title":"Hình 6.8 — Cấu tạo của khớp các đăng","text":"A. Trục chữ thập. Liên kết hai nạng của khớp các đăng. B. Nắp vòng bi. Chứa ổ bi kim, được giữ trong lỗ trên nạng. C. Vòng chặn. Giữ vị trí nắp ổ theo kết cấu minh họa. D. Trục rỗng (Khớp nối trượt). Bù thay đổi chiều dài trong quá trình các cụm chuyển động tương đối.","figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s804","kind":"part","lesson":"6.1.1","title":"Trục chữ thập","text":"Liên kết hai nạng của khớp các đăng.","keywords":["Trục chữ thập"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s805","kind":"part","lesson":"6.1.1","title":"Nắp vòng bi","text":"Chứa ổ bi kim, được giữ trong lỗ trên nạng.","keywords":["Nắp vòng bi"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s806","kind":"part","lesson":"6.1.1","title":"Vòng chặn","text":"Giữ vị trí nắp ổ theo kết cấu minh họa.","keywords":["Vòng chặn"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s807","kind":"part","lesson":"6.1.1","title":"Trục rỗng (Khớp nối trượt)","text":"Bù thay đổi chiều dài trong quá trình các cụm chuyển động tương đối.","keywords":["Trục rỗng (Khớp nối trượt)"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s808","kind":"figure","lesson":"6.1.1","title":"Hình 6.1. Sơ đồ bố trí truyền động các đăng trên ô tô","text":"Hình 6.1. Sơ đồ bố trí truyền động các đăng trên ô tô","anchor":"block-1781162407165-j6kauk3jp","figure":{"number":"6.1","caption":"Hình 6.1. Sơ đồ bố trí truyền động các đăng trên ô tô"}},{"id":"s809","kind":"html","lesson":"6.1.1","title":"Truyền động các đăng · Chức năng","text":"Truyền động các đăng dùng để truyền mô men xoắn giữa các trục của hai cụm (Hình 6.1) mà các đường tâm của các trục không nằm trên một đường thẳng và vị trí của các cụm này có thể bị thay đổi trong quá trình ô tô chuyển động. Truyền động các đăng dùng để làm dễ dàng cho việc tháo lắp các cụm, cơ cấu truyền lực. Ví dụ như hộp số chính và hộp số phân phối đều được lắp ráp cố định trên khung xe (hoặc vỏ xe) nhưng giữa chúng được nối bằng truyền động các đăng do vậy không yêu cầu độ chính xác lắp ráp cao giữa cụm này với cụm kia và nó cũng bù trừ được sai lệch do sự biến dạng của khung xe trong quá trình xe hoạt động.","anchor":"block-1781162407165-j6kauk3jp"},{"id":"s810","kind":"html","lesson":"6.1.1","title":"Truyền động các đăng · Chức năng","text":"Ngoài ra truyền động các đăng còn dùng để dẫn động những thiết bị chuyên dùng khác của ô tô như trích công suất ra tời, dẫn động các cơ cấu chuyên dùng khác… Vì đặc điểm trên nên truyền động các đăng không những phải bảo đảm động học giữa đầu vào và đầu ra mà còn phải có khả năng dịch chuyển dọc trục để thay đổi độ dài của trục các đăng. Mặt khác để truyền mô men xoắn với khoảng cách lớn, thân trục các đăng có thể được chế tạo thành hai phần: một phần gắn lên thân xe, phần còn lại gắn với cầu xe. Giữa các đoạn thân có thể là khớp nối (hoặc gối đỡ trung gian).","anchor":"block-1781162407165-j6kauk3jp"},{"id":"s811","kind":"lesson","lesson":"6.1.2","title":"Truyền động các đăng · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân loại các đăng."},{"id":"s812","kind":"simulation","lesson":"6.1.2","title":"Trình tự phân loại các đăng","text":"1. Xác định công dụng của bộ truyền. Xác định các cụm được nối: hộp số, hộp phân phối, cầu hoặc bánh xe. 2. Xét quan hệ tốc độ tức thời. Phân biệt khác tốc và đồng tốc, không chỉ nhìn tốc độ trung bình. 3. Đếm thân trục và khớp. Số thân, số khớp và gối đỡ là tiêu chí bố trí. 4. Xét kết cấu kín hoặc hở. Quan sát ống bọc và kết luận theo tiêu chí kết cấu."},{"id":"s813","kind":"figure","lesson":"6.1.2","title":"Phân loại truyền động các đăng — sơ đồ học tập biên soạn từ bài 6.1.2","text":"A. Các đăng khác tốc. Khớp đơn lệch góc có tốc độ đầu ra biến thiên khi đầu vào quay đều. B. Các đăng đồng tốc. Đảm bảo quan hệ đồng tốc trong phạm vi làm việc của kết cấu. C. Truyền động các đăng kín. Các bộ phận đặt trong ống bọc bảo vệ theo phân loại trong bài. D. Truyền động các đăng hở. Được phân biệt với loại kín theo kết cấu bao che.","figure":{"image":"tuong_tac/diagrams/cardanclasses.svg","caption":"Phân loại truyền động các đăng — sơ đồ học tập biên soạn từ bài 6.1.2"}},{"id":"s814","kind":"part","lesson":"6.1.2","title":"Các đăng khác tốc","text":"Khớp đơn lệch góc có tốc độ đầu ra biến thiên khi đầu vào quay đều.","keywords":["Các đăng khác tốc"],"figure":{"image":"tuong_tac/diagrams/cardanclasses.svg","caption":"Phân loại truyền động các đăng — sơ đồ học tập biên soạn từ bài 6.1.2"}},{"id":"s815","kind":"part","lesson":"6.1.2","title":"Các đăng đồng tốc","text":"Đảm bảo quan hệ đồng tốc trong phạm vi làm việc của kết cấu.","keywords":["Các đăng đồng tốc"],"figure":{"image":"tuong_tac/diagrams/cardanclasses.svg","caption":"Phân loại truyền động các đăng — sơ đồ học tập biên soạn từ bài 6.1.2"}},{"id":"s816","kind":"part","lesson":"6.1.2","title":"Truyền động các đăng kín","text":"Các bộ phận đặt trong ống bọc bảo vệ theo phân loại trong bài.","keywords":["Truyền động các đăng kín"],"figure":{"image":"tuong_tac/diagrams/cardanclasses.svg","caption":"Phân loại truyền động các đăng — sơ đồ học tập biên soạn từ bài 6.1.2"}},{"id":"s817","kind":"part","lesson":"6.1.2","title":"Truyền động các đăng hở","text":"Được phân biệt với loại kín theo kết cấu bao che.","keywords":["Truyền động các đăng hở"],"figure":{"image":"tuong_tac/diagrams/cardanclasses.svg","caption":"Phân loại truyền động các đăng — sơ đồ học tập biên soạn từ bài 6.1.2"}},{"id":"s818","kind":"html","lesson":"6.1.2","title":"Truyền động các đăng · Phân loại","text":"Các đăng có thể phân loại theo công dụng, đặc điểm động học, số lượng trục và khớp các đăng hoặc kết cấu.","anchor":"block-1781162442564-tlx5cz8xx"},{"id":"s819","kind":"figure","lesson":"6.1.2","title":"Hình 6.2. Truyền động mô men xoắn đến các bánh xe chủ động","text":"Hình 6.2. Truyền động mô men xoắn đến các bánh xe chủ động","anchor":"block-1781162462057-k0syxbhgm","figure":{"number":"6.2","caption":"Hình 6.2. Truyền động mô men xoắn đến các bánh xe chủ động"}},{"id":"s820","kind":"html","lesson":"6.1.2","title":"Phân loại · a. Theo công dụng của các đăng","text":"Theo công dụng của truyền động các đăng có thể phân thành các loại sau: - Các đăng nối giữa hộp số chính với hộp số phân phối; - Các đăng nối giữa hộp số chính (hoặc hộp số phân phối) với cầu chủ động; - Các đăng nối giữa cầu chủ động với bánh xe chủ động (Hình 6.2); - Các đăng nối giữa hộp số với các thiết bị phụ: bơm thuỷ lực, tời kéo, ....","anchor":"block-1781162462057-k0syxbhgm"},{"id":"s821","kind":"html","lesson":"6.1.2","title":"Phân loại · b. Theo đặc điểm động học","text":"Theo đặc điểm động học của các đăng có thể chia thành các loại sau: - Các đăng khác tốc: tốc độ quay của trục chủ động và bị động qua một khớp các đăng là khác nhau. Sự quay không đều giữa hai trục càng lớn khi góc lệch giữa các trục càng lớn; - Các đăng đồng tốc: tốc độ quay của trục chủ động và bị động qua một khớp các đăng là bằng nhau không phụ thuộc vào góc lệch giữa hai trục mà phụ thuộc vào nguyên tắc cấu tạo và đặc điểm kết cấu khớp các đăng đồng tốc; - Khớp nối: khớp nối khác các đăng là khả năng truyền mô men giữa trục chủ động và bị động qua khớp nối giới hạn trong khoảng 30 - 60.","anchor":"block-1781162500226-ze6o1gs4w"},{"id":"s822","kind":"html","lesson":"6.1.2","title":"Phân loại · c. Theo kết cấu:","text":"Theo kết cấu của các đăng có thể chia thành các loại sau: - Khớp nối đàn hồi, cho phép làm việc ở góc truyền giới hạn.","anchor":"block-1781162524308-v3dqnkvgi"},{"id":"s823","kind":"html","lesson":"6.1.2","title":"Phân loại · d. Theo khả năng bao kín","text":"Với đặc điểm kết cấu bao kín truyền động các đăng chia làm 2 loại: - Loại kín: là toàn bộ truyền động các đăng (trục, khớp và ổ) được đặt kín trong ống bọc. Loại này làm tăng khả năng bảo vệ, tránh hư hỏng cho truyền động các đăng. - Loại hở: truyền động các đăng không được bao kín. Loại này có cấu tạo đơn giản và được sử dụng phổ biến trên ô tô. Do đặc điểm bố trí và điều kiện làm việc nên truyền động các đăng phải đảm bảo quay đều, không bị võng và va đập và không sinh ra tải trọng động. Đối với các đăng đồng tốc phải đảm bảo chính xác về động học trong quá trình làm việc khi trục chủ động và bị động lệch với nhau một góc bất kỳ để đảm bảo hai trục quay cùng tốc độ.","anchor":"block-1781162570450-cmpgb0ysn"},{"id":"s824","kind":"lesson","lesson":"6.2.1","title":"Truyền động các đăng · Sơ đồ nguyên lý","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích khớp khác tốc và điều kiện phối hợp hai khớp."},{"id":"s825","kind":"note","lesson":"6.2.1","title":"Điều kiện bù tính khác tốc","text":"Một khớp chữ thập lệch góc không đồng tốc. Hai khớp chỉ bù được biến thiên tốc độ khi thỏa điều kiện hình học bố trí, góc làm việc bằng nhau và lắp nạng đúng pha theo sơ đồ. Có hai khớp không tự động bảo đảm đồng tốc."},{"id":"s826","kind":"simulation","lesson":"6.2.1","title":"Khớp khác tốc và điều kiện phối hợp hai khớp","text":"1. Nạng chủ động quay. Nạng 1 nhận chuyển động từ trục chủ động. 2. Trục chữ thập liên kết hai nạng. Các chốt chữ thập chuyển động trong lỗ các nạng. 3. Nạng bị động quay theo. Khi lệch góc, tốc độ tức thời của đầu ra không đều dù đầu vào quay đều. 4. Hai khớp phối hợp bù khác tốc. Hai góc làm việc bằng nhau và nạng trung gian đúng pha là điều kiện bố trí được nêu."},{"id":"s827","kind":"figure","lesson":"6.2.1","title":"Hình 6.3 — Sơ đồ nguyên lý khớp các đăng đơn","text":"A. Nạng chủ động. Nhận mô men từ trục chủ động theo ký hiệu 1. B. Nạng bị động. Đưa mô men tới trục bị động theo ký hiệu 2. C. Trục chữ thập. Liên kết hai nạng và cho phép truyền động khi hai trục lệch góc.","figure":{"image":"content/resources/T1_image263.jpg","caption":"Hình 6.3 — Sơ đồ nguyên lý khớp các đăng đơn","number":"6.3"}},{"id":"s828","kind":"part","lesson":"6.2.1","title":"Nạng chủ động","text":"Nhận mô men từ trục chủ động theo ký hiệu 1.","keywords":["Nạng chủ động"],"figure":{"image":"content/resources/T1_image263.jpg","caption":"Hình 6.3 — Sơ đồ nguyên lý khớp các đăng đơn","number":"6.3"}},{"id":"s829","kind":"part","lesson":"6.2.1","title":"Nạng bị động","text":"Đưa mô men tới trục bị động theo ký hiệu 2.","keywords":["Nạng bị động"],"figure":{"image":"content/resources/T1_image263.jpg","caption":"Hình 6.3 — Sơ đồ nguyên lý khớp các đăng đơn","number":"6.3"}},{"id":"s830","kind":"part","lesson":"6.2.1","title":"Trục chữ thập","text":"Liên kết hai nạng và cho phép truyền động khi hai trục lệch góc.","keywords":["Trục chữ thập"],"figure":{"image":"content/resources/T1_image263.jpg","caption":"Hình 6.3 — Sơ đồ nguyên lý khớp các đăng đơn","number":"6.3"}},{"id":"s831","kind":"figure","lesson":"6.2.1","title":"Hình 6.3. Sơ đồ nguyên lý khớp các đăng đơn","text":"Hình 6.3. Sơ đồ nguyên lý khớp các đăng đơn","anchor":"block-1781162644864-w9kdrt88b","figure":{"number":"6.3","caption":"Hình 6.3. Sơ đồ nguyên lý khớp các đăng đơn"}},{"id":"s832","kind":"figure","lesson":"6.2.1","title":"Hình 6.4. Đồ thị vận tốc góc của trục chủ động và trục bị động","text":"Hình 6.4. Đồ thị vận tốc góc của trục chủ động và trục bị động","anchor":"block-1781162644864-w9kdrt88b","figure":{"number":"6.4","caption":"Hình 6.4. Đồ thị vận tốc góc của trục chủ động và trục bị động"}},{"id":"s833","kind":"figure","lesson":"6.2.1","title":"Hình 6.5. Sơ đồ bố trí bộ truyền các đăng hai khớp chữ thập","text":"Hình 6.5. Sơ đồ bố trí bộ truyền các đăng hai khớp chữ thập","anchor":"block-1781162644864-w9kdrt88b","figure":{"number":"6.5","caption":"Hình 6.5. Sơ đồ bố trí bộ truyền các đăng hai khớp chữ thập"}},{"id":"s834","kind":"html","lesson":"6.2.1","title":"Truyền động các đăng · Sơ đồ nguyên lý","text":"Sơ đồ nguyên lý của khớp các đăng khác tốc được thể hiện ở Hình 6.3 1 - Nạng chủ động; 2 - Nạng bị động; 3 - Trục chữ thập Cấu tạo chính của các đăng khác tốc bao gồm nạng chủ động 1, nạng bị động 2 và trục chữ thập 3. Nạng chủ động 1 được nối với nạng bị động 2 bằng trục chữ thập 3, đường tâm của hai trục tạo thành góc α. Khi trục chủ động quay qua chốt chữ thập làm trục bị động quay theo, chốt chữ thập sẽ quay trong các lỗ của các nạng với giới hạn góc α. Theo giáo trình nguyên lý máy đã chứng minh được mối quan hệ giữa góc quay của các trục và góc α ở bất kỳ vị trí nào của các trục theo biểu thức: Trong đó: φ1, φ2 - Góc quay của trục đầu vào và trục đầu ra. Như vậy do có góc α nên khi trục chủ động quay đều thì trục bị động sẽ quay không đều. Mức độ quay không đều của trục bị động càng lớn khi góc lệch giữa hai trục α càng lớn.","anchor":"block-1781162644864-w9kdrt88b"},{"id":"s835","kind":"html","lesson":"6.2.1","title":"Truyền động các đăng · Sơ đồ nguyên lý","text":"Trên hình Hình 6.4 cho thấy khi trục chủ động quay đều tốc độ ω1 = const thì tốc độ góc của trục bị động ω2 nhỏ nhất ứng với các góc quay của trục chủ động φ1 = 0o; 180o; 360o và đạt giá trị lớn nhất khi φ1 = 90o; 270o. Vận tốc góc của trục bị động thay đổi mỗi khi quay qua góc 90°, nên nó sinh ra sự thay đổi về vận tốc góc tương đối so với trục chủ động. Do sự biến đổi vận tốc góc của trục bị động trong quá trình làm việc mà trong cơ cấu các đăng đơn xuất hiện mô men quán tính lớn, có nhiều va đập gây nên sự dao động và tải trọng động lớn nên các chi tiết nhanh bị hư hỏng, do vậy hiện nay khớp các đăng đơn rất ít được sử dụng trên ô tô.","anchor":"block-1781162644864-w9kdrt88b"},{"id":"s836","kind":"html","lesson":"6.2.1","title":"Truyền động các đăng · Sơ đồ nguyên lý","text":"Hiện nay trên ô tô sử dụng bộ truyền các đăng với hai khớp chữ thập được bố trí theo sơ đồ Hình 6.5 Theo sơ đồ này thì trục bị động của khớp các đăng phía trước lại là trục chủ động của khớp các đăng phía sau còn trục bị động của khớp các đăng phía sau cũng là trục bị động của bộ truyền các đăng. Hướng của hai nạng trên trục trung gian phải trùng nhau trong một mặt phẳng. Góc hợp bởi trục chủ động với trục trung gian là α1 và góc hợp bởi trục trung gian với trục bị động là α2. Xét thời điểm ban đầu nạng của các đăng tại khớp A của trục chủ động nằm trong mặt phẳng thẳng đứng, ta có mối quan hệ động học như sau: Trong đó: - Góc quay của trục chủ động; - Góc quay của trục trung gian. Trong đó: - Góc quay của trục bị động; - Góc quay của trục trung gian.","anchor":"block-1781162644864-w9kdrt88b"},{"id":"s837","kind":"html","lesson":"6.2.1","title":"Truyền động các đăng · Sơ đồ nguyên lý","text":"Như vậy giữa góc quay trục chủ động và góc quay trục bị động có mối quan hệ theo biểu thức: Theo biểu thức trên nếu α1 = α2 thì luôn có φ1 = φ2, nghĩa là trục chủ động và trục bị động sẽ quay cùng vận tốc góc. Để bảo đảm tốc độ góc của trục chủ động và trục bị động của bộ truyền các đăng hai khớp chữ thập thì ngoài điều kiện góc α1 = α2 thì các nạng trên trục trung gian phải có hướng trùng nhau trong một mặt phẳng. Trong thực tế bộ truyền các đăng sử dụng hai khớp chữ thập được sử dụng rộng rãi. Để thay đổi khoảng cách giữa các khớp các đăng khi làm việc, chiều dài của trục trung gian có thể thay đổi bằng cách chế tạo trục thành hai đoạn và nối với nhau bằng then hoa.","anchor":"block-1781162644864-w9kdrt88b"},{"id":"s838","kind":"lesson","lesson":"6.2.2","title":"Truyền động các đăng · Cấu tạo","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích truyền mô men và bù chiều dài."},{"id":"s839","kind":"simulation","lesson":"6.2.2","title":"Truyền mô men và bù chiều dài","text":"1. Mô men vào nạng thứ nhất. Nạng và thân trục đưa mô men tới khớp chữ thập. 2. Chốt chữ thập làm việc trong ổ bi kim. Ổ bi kim liên kết chốt chữ thập với lỗ trên nạng. 3. Nạng thứ hai nhận mô men. Nắp và vòng hãm giữ ổ bi đúng vị trí khi khớp làm việc. 4. Then hoa bù thay đổi chiều dài. Hai phần thân trục liên kết then hoa để đáp ứng chuyển động tương đối."},{"id":"s840","kind":"figure","lesson":"6.2.2","title":"Hình 6.8 — Cấu tạo của khớp các đăng","text":"A. Trục chữ thập. Liên kết hai nạng của khớp các đăng. B. Nắp vòng bi. Chứa ổ bi kim, được giữ trong lỗ trên nạng. C. Vòng chặn. Giữ vị trí nắp ổ theo kết cấu minh họa. D. Trục rỗng (Khớp nối trượt). Bù thay đổi chiều dài trong quá trình các cụm chuyển động tương đối.","figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s841","kind":"part","lesson":"6.2.2","title":"Trục chữ thập","text":"Liên kết hai nạng của khớp các đăng.","keywords":["Trục chữ thập"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s842","kind":"part","lesson":"6.2.2","title":"Nắp vòng bi","text":"Chứa ổ bi kim, được giữ trong lỗ trên nạng.","keywords":["Nắp vòng bi"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s843","kind":"part","lesson":"6.2.2","title":"Vòng chặn","text":"Giữ vị trí nắp ổ theo kết cấu minh họa.","keywords":["Vòng chặn"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s844","kind":"part","lesson":"6.2.2","title":"Trục rỗng (Khớp nối trượt)","text":"Bù thay đổi chiều dài trong quá trình các cụm chuyển động tương đối.","keywords":["Trục rỗng (Khớp nối trượt)"],"figure":{"image":"content/resources/T1_image277.jpg","caption":"Hình 6.8 — Cấu tạo của khớp các đăng","number":"6.8"}},{"id":"s845","kind":"figure","lesson":"6.2.2","title":"Hình 6.6. Cấu tạo bộ truyền các đăng khác tốc sử dụng hai khớp chữ thập","text":"Hình 6.6. Cấu tạo bộ truyền các đăng khác tốc sử dụng hai khớp chữ thập","anchor":"block-1781162713680-510vlyslf","figure":{"number":"6.6","caption":"Hình 6.6. Cấu tạo bộ truyền các đăng khác tốc sử dụng hai khớp chữ thập"}},{"id":"s846","kind":"figure","lesson":"6.2.2","title":"Hình 6.7. Cấu tạo bộ truyền các đăng khác tốc sử dụng khớp đỡ","text":"Hình 6.7. Cấu tạo bộ truyền các đăng khác tốc sử dụng khớp đỡ","anchor":"block-1781162713680-510vlyslf","figure":{"number":"6.7","caption":"Hình 6.7. Cấu tạo bộ truyền các đăng khác tốc sử dụng khớp đỡ"}},{"id":"s847","kind":"figure","lesson":"6.2.2","title":"Hình 6.8. Cấu tạo của khớp các đăng.","text":"Hình 6.8. Cấu tạo của khớp các đăng.","anchor":"block-1781162713680-510vlyslf","figure":{"number":"6.8","caption":"Hình 6.8. Cấu tạo của khớp các đăng."}},{"id":"s848","kind":"html","lesson":"6.2.2","title":"Truyền động các đăng · Cấu tạo","text":"p>Cấu tạo chung của bộ truyền các đăng khác tốc bao gồm thân trục các đăng và các khớp các đăng. Thông thường người ta sử dụng loại trục các đăng có hai khớp ( Hình 6.6). 1,4,9,12- Nạng các đăng; 2- Rãnh vát; 3,11- Nắp đậy ổ bi; 5- Vỏ trục; 6- Vấu giữ;7,18- Trục trung gian; 8- Tấm thép cân bằng động; 10,19- Vòng làm kín; 13- Vòng hãm; 14- Trục chữ thập; 15,17- Vú mỡ; 16- Tấm làm kín; 20- Vòng đệm. Trong trường hợp khoảng cách truyền tương đối xa khi tốc độ quay của trục các đăng khá lớn trục có xu hướng bị võng và rung động nhiều thì người ta sử dụng trục các đăng hai thân ba khớp và có ổ đỡ trung gian (Hình 6.7). Với cấu tạo như vậy chiều dài của mỗi đoạn các đăng sẽ ngắn hơn làm độ cứng vững tăng lên nên ít bị võng và rung động khi làm việc ở tốc độ cao.","anchor":"block-1781162713680-510vlyslf"},{"id":"s849","kind":"html","lesson":"6.2.2","title":"Truyền động các đăng · Cấu tạo","text":"1- Trục chữ thập; 2- Vấu giữ; 3,8,25- Trục trung gian; 4- Đai ốc; 5- Vòng chặn; 6- Vòng chắn bụi; 7- Bulong; 9,24- Nạng; 10-Nắp chụp ổ bi; 11- Vòng hãm; 12- Tấm thép cân bằng động; 13- Phớt làm kín; 14- Vú mỡ; 15- Ổ bi; 16- Giá đỡ ổ bi; 17- Bệ đỡ cao su; 18- Mặt bích; 19- Tấm chặn; 20- Vòng làm kín; 21- Tấm đỡ; 22- Miếng đỡ; 23- Vòng đỡ; 26- Cầu chủ động. Bộ phận chính của bộ truyền các đăng là khớp các đăng, nó được mô tả trên Hình 6.7. Khớp các đăng bao gồm một trục chữ thập và hai nạng gắn liền với trục chủ động và trục bị động của khớp các đăng. Trục chữ thập được liên kết với các lỗ trên hai nạng thông qua các ổ bi kim. Vòng bi kim được lắp vào trong nắp và nắp được ép vào lỗ trên nạng.","anchor":"block-1781162713680-510vlyslf"},{"id":"s850","kind":"html","lesson":"6.2.2","title":"Truyền động các đăng · Cấu tạo","text":"Để ngăn không cho vòng bi dịch chuyển ra ngoài khi trục các đăng làm việc ở tốc độ cao thì người ta sử dụng vòng hãm hoặc tấm hãm để cố định nắp vòng bi trong lỗ trên các nạng. Thân trục các đăng dùng để nối hai khớp các đăng với nhau (Hình 6.6). Thân trục thường được chế tạo bằng ống thép hình trụ rỗng nhằm giảm khối lượng, tăng độ cứng vững và tăng khả năng truyền mô men xoắn. Các trục các đăng được cân bằng động bằng các tấm cân bằng 8. Bôi trơn khớp then hoa bằng mỡ qua vú mỡ. Trong quá trình làm việc, khoảng cách giữa hai khớp các đăng luôn thay đổi nên thân trục các đăng thường được chế tạo hai nửa và liên kết với nhau bằng then hoa. Do khi lắp ráp có thể làm hai nạng trên thân trục không trùng trên một mặt phẳng nên trên hai nửa thân trục thường có đánh dấu mũi tên để thuận tiện khi lắp ráp.","anchor":"block-1781162713680-510vlyslf"},{"id":"s851","kind":"lesson","lesson":"6.3.1","title":"Truyền động các đăng · Khớp các đăng đồng tốc kiểu chữ thập kép","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Khớp các đăng đồng tốc kiểu chữ thập kép."},{"id":"s852","kind":"note","lesson":"6.3.1","title":"Cụm chữ thập kép","text":"Khớp chữ thập kép cần cơ cấu định tâm / điều kiện hình học giữ hai góc làm việc bằng nhau. Không giải thích tính đồng tốc chỉ bằng việc thu ngắn đoạn nối giữa hai trục chữ thập."},{"id":"s853","kind":"simulation","lesson":"6.3.1","title":"Nguyên lý: Khớp các đăng đồng tốc kiểu chữ thập kép","text":"1. Trục chủ động đưa mô men vào. Khớp chữ thập thứ nhất nhận tác động từ đầu vào. 2. Khớp thứ nhất truyền tới giá chạc kép. Giá chạc kép liên kết hai trục chữ thập liền kề. 3. Khớp thứ hai nhận tác động. Hai khớp phối hợp theo bố trí để bù sự khác tốc. 4. Trục bị động nhận mô men. Đoạn giữa được thu ngắn, vừa đủ nối hai trục chữ thập theo kết cấu bài học."},{"id":"s854","kind":"figure","lesson":"6.3.1","title":"Hình 6.9 — Cấu tạo các đăng đồng tốc kiểu chữ thập kép","text":"A. Trục chủ động. Đưa mô men vào khớp chữ thập kép. B. Khớp chữ thập. Liên kết chuyển động giữa các nạng của khớp. C. Giá chạc kép. Liên kết hai khớp chữ thập đặt liền kề. D. Trục bị động. Nhận mô men từ khớp chữ thập kép.","figure":{"image":"content/resources/T1_image278.jpg","caption":"Hình 6.9 — Cấu tạo các đăng đồng tốc kiểu chữ thập kép","number":"6.9"}},{"id":"s855","kind":"part","lesson":"6.3.1","title":"Trục chủ động","text":"Đưa mô men vào khớp chữ thập kép.","keywords":["Trục chủ động"],"figure":{"image":"content/resources/T1_image278.jpg","caption":"Hình 6.9 — Cấu tạo các đăng đồng tốc kiểu chữ thập kép","number":"6.9"}},{"id":"s856","kind":"part","lesson":"6.3.1","title":"Khớp chữ thập","text":"Liên kết chuyển động giữa các nạng của khớp.","keywords":["Khớp chữ thập"],"figure":{"image":"content/resources/T1_image278.jpg","caption":"Hình 6.9 — Cấu tạo các đăng đồng tốc kiểu chữ thập kép","number":"6.9"}},{"id":"s857","kind":"part","lesson":"6.3.1","title":"Giá chạc kép","text":"Liên kết hai khớp chữ thập đặt liền kề.","keywords":["Giá chạc kép"],"figure":{"image":"content/resources/T1_image278.jpg","caption":"Hình 6.9 — Cấu tạo các đăng đồng tốc kiểu chữ thập kép","number":"6.9"}},{"id":"s858","kind":"part","lesson":"6.3.1","title":"Trục bị động","text":"Nhận mô men từ khớp chữ thập kép.","keywords":["Trục bị động"],"figure":{"image":"content/resources/T1_image278.jpg","caption":"Hình 6.9 — Cấu tạo các đăng đồng tốc kiểu chữ thập kép","number":"6.9"}},{"id":"s859","kind":"figure","lesson":"6.3.1","title":"Hình 6.9. Cấu tạo các đăng đồng tốc kiểu chữ thập kép.","text":"Hình 6.9. Cấu tạo các đăng đồng tốc kiểu chữ thập kép.","anchor":"block-1781162766835-82fqbj4c0","figure":{"number":"6.9","caption":"Hình 6.9. Cấu tạo các đăng đồng tốc kiểu chữ thập kép."}},{"id":"s860","kind":"html","lesson":"6.3.1","title":"Truyền động các đăng · Khớp các đăng đồng tốc kiểu chữ thập kép","text":"Các đăng đồng tốc kiểu chữ thập kép thực chất là sự biến hình của các đăng khác tốc kép, khi mà chiều dài của đoạn thân trục nối giữa hai khớp các đăng giảm bằng 0. Cấu tạo của khớp các đăng đồng tốc kép được mô tả trên Hình 6.9 1- Trục chủ động; 2,3- Khớp chữ thập; 4- Trục bị động; 5- Giá chạc kép; Loại các đăng này thường thấy trên cầu dẫn hướng chủ động có dầm cầu liền của ô tô du lịch tốc độ thấp, các loại ô tô cao tốc không dùng. Trên đoạn giữa của các đăng đặt hai bộ ổ, hai trục chữ thập liền kề nhau chiều dài đoạn giữa còn vừa đủ để nối hai trục chữ thập.","anchor":"block-1781162766835-82fqbj4c0"},{"id":"s861","kind":"lesson","lesson":"6.3.2","title":"Truyền động các đăng · Khớp các đăng đồng tốc loại cam","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Khớp các đăng đồng tốc loại cam."},{"id":"s862","kind":"simulation","lesson":"6.3.2","title":"Nguyên lý: Khớp các đăng đồng tốc loại cam","text":"1. Nạng chủ động tác động cam. Cam nửa hình trụ nằm trong phần lõm của nạng. 2. Cam thứ nhất truyền qua đĩa. Đĩa nằm trong rãnh của cả hai cam. 3. Cam thứ hai tiếp nhận tác động. Liên kết cam–đĩa phối hợp khi góc giữa các trục thay đổi. 4. Nạng bị động đưa mô men ra. Khớp làm việc tương tự khớp kép theo mô tả trong bài."},{"id":"s863","kind":"figure","lesson":"6.3.2","title":"Hình 6.10a — Cấu tạo khớp các đăng đồng tốc loại cam","text":"A. Nạng chủ động. Liên kết trục chủ động với cam thứ nhất. B. Cam. Bề mặt nửa hình trụ phối hợp với nạng và đĩa truyền lực. C. Đĩa. Nằm trong rãnh hai cam để liên kết truyền động. D. Nạng bị động. Nhận tác động từ cam và truyền tới trục bị động.","figure":{"image":"content/resources/T1_image279.jpg","caption":"Hình 6.10a — Cấu tạo khớp các đăng đồng tốc loại cam","number":"6.10a"}},{"id":"s864","kind":"part","lesson":"6.3.2","title":"Nạng chủ động","text":"Liên kết trục chủ động với cam thứ nhất.","keywords":["Nạng chủ động"],"figure":{"image":"content/resources/T1_image279.jpg","caption":"Hình 6.10a — Cấu tạo khớp các đăng đồng tốc loại cam","number":"6.10a"}},{"id":"s865","kind":"part","lesson":"6.3.2","title":"Cam","text":"Bề mặt nửa hình trụ phối hợp với nạng và đĩa truyền lực.","keywords":["Cam"],"figure":{"image":"content/resources/T1_image279.jpg","caption":"Hình 6.10a — Cấu tạo khớp các đăng đồng tốc loại cam","number":"6.10a"}},{"id":"s866","kind":"part","lesson":"6.3.2","title":"Đĩa","text":"Nằm trong rãnh hai cam để liên kết truyền động.","keywords":["Đĩa"],"figure":{"image":"content/resources/T1_image279.jpg","caption":"Hình 6.10a — Cấu tạo khớp các đăng đồng tốc loại cam","number":"6.10a"}},{"id":"s867","kind":"part","lesson":"6.3.2","title":"Nạng bị động","text":"Nhận tác động từ cam và truyền tới trục bị động.","keywords":["Nạng bị động"],"figure":{"image":"content/resources/T1_image279.jpg","caption":"Hình 6.10a — Cấu tạo khớp các đăng đồng tốc loại cam","number":"6.10a"}},{"id":"s868","kind":"figure","lesson":"6.3.2","title":"Hình 6.10. Cấu tạo khớp các đăng đồng tốc loại cam","text":"Hình 6.10. Cấu tạo khớp các đăng đồng tốc loại cam","anchor":"block-1781162784676-0dzr4i6uk","figure":{"number":"6.10","caption":"Hình 6.10. Cấu tạo khớp các đăng đồng tốc loại cam"}},{"id":"s869","kind":"html","lesson":"6.3.2","title":"Truyền động các đăng · Khớp các đăng đồng tốc loại cam","text":"Khớp các đăng cam (Hình 6.10a) có hai nạng 2 và 6 được lắp liền khối với trục 2 và 7 bằng hàn hoặc mối ghép then hoa. Hai cam dạng nửa hình trụ 3 và 5 được nằm vào phần lõm của hai nạng. Đĩa 4 nằm vào rãnh của hai cam. Khớp các đăng cam làm việc twong tự như khớp các đăng kép. Trên hình Hình 6.10b là kết cấu một dạng khác của các đăng cam. Trên nạng 1 và 6 người ta đặt cam 2 và 4, chúng được lắp ghép với nhau nhờ mộng 3 và rãnh 5.","anchor":"block-1781162784676-0dzr4i6uk"},{"id":"s870","kind":"lesson","lesson":"6.3.3","title":"Truyền động các đăng · Khớp các đăng loại bi","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự giải thích điều kiện đồng tốc."},{"id":"s871","kind":"simulation","lesson":"6.3.3","title":"Trình tự giải thích điều kiện đồng tốc","text":"1. Xác định góc giữa hai đường tâm. Góc truyền mô men được tạo bởi trục chủ động và trục bị động. 2. Xác định mặt phẳng phân giác. Mặt phẳng này chia đôi góc tạo bởi hai đường tâm. 3. Định vị các viên bi trên phân giác. Rãnh hoặc vòng định vị giữ điểm truyền lực đúng vị trí. 4. Truyền mô men với điều kiện đồng tốc. Giữ các điều kiện hình học trong phạm vi làm việc của khớp."},{"id":"s872","kind":"figure","lesson":"6.3.3","title":"Điều kiện đồng tốc của khớp bi — sơ đồ học tập biên soạn từ bài 6.3.3","text":"A. Trục chủ động. Truyền mô men tới các điểm tiếp xúc bi. B. Trục bị động. Nhận mô men qua các điểm truyền lực. C. Mặt phẳng phân giác. Các điểm truyền lực phải được giữ trên mặt phẳng này để bảo đảm đồng tốc. D. Vòng định vị. Một phương pháp giữ các viên bi đúng vị trí theo sơ đồ nguyên lý.","figure":{"image":"tuong_tac/diagrams/ballplane.svg","caption":"Điều kiện đồng tốc của khớp bi — sơ đồ học tập biên soạn từ bài 6.3.3"}},{"id":"s873","kind":"part","lesson":"6.3.3","title":"Trục chủ động","text":"Truyền mô men tới các điểm tiếp xúc bi.","keywords":["Trục chủ động"],"figure":{"image":"tuong_tac/diagrams/ballplane.svg","caption":"Điều kiện đồng tốc của khớp bi — sơ đồ học tập biên soạn từ bài 6.3.3"}},{"id":"s874","kind":"part","lesson":"6.3.3","title":"Trục bị động","text":"Nhận mô men qua các điểm truyền lực.","keywords":["Trục bị động"],"figure":{"image":"tuong_tac/diagrams/ballplane.svg","caption":"Điều kiện đồng tốc của khớp bi — sơ đồ học tập biên soạn từ bài 6.3.3"}},{"id":"s875","kind":"part","lesson":"6.3.3","title":"Mặt phẳng phân giác","text":"Các điểm truyền lực phải được giữ trên mặt phẳng này để bảo đảm đồng tốc.","keywords":["Mặt phẳng phân giác"],"figure":{"image":"tuong_tac/diagrams/ballplane.svg","caption":"Điều kiện đồng tốc của khớp bi — sơ đồ học tập biên soạn từ bài 6.3.3"}},{"id":"s876","kind":"part","lesson":"6.3.3","title":"Vòng định vị","text":"Một phương pháp giữ các viên bi đúng vị trí theo sơ đồ nguyên lý.","keywords":["Vòng định vị"],"figure":{"image":"tuong_tac/diagrams/ballplane.svg","caption":"Điều kiện đồng tốc của khớp bi — sơ đồ học tập biên soạn từ bài 6.3.3"}},{"id":"s877","kind":"figure","lesson":"6.3.3","title":"Hình 6.11. Nguyên lý hình thành các đăng đồng tốc kiểu bi","text":"Hình 6.11. Nguyên lý hình thành các đăng đồng tốc kiểu bi","anchor":"block-1781162804032-gw6rm9wf8","figure":{"number":"6.11","caption":"Hình 6.11. Nguyên lý hình thành các đăng đồng tốc kiểu bi"}},{"id":"s878","kind":"html","lesson":"6.3.3","title":"Truyền động các đăng · Khớp các đăng loại bi","text":"Nguyên lý hình thành các đăng bi có thể xem xét trên cơ sở bộ truyền bánh răng côn ăn khớp có kích thước hình học giống nhau hoàn toàn như trên hình. Khi góc giữa hai đường tâm trục thay đổi, tức là khi thay đổi góc nghiêng truyền mô men giữa hai trục chủ động và bị động, điều kiện đồng tốc được thực hiện nếu: - Giữ nguyên khoảng cách từ điểm truyền lực đến điểm giao nhau của hai đường tâm trục; - Điểm truyền lực luôn luôn nằm trên mặt phẳng phân giác của góc tạo nên giữa hai đường tâm trục. Trong trường hợp bộ truyền ăn khớp bi thì các viên bi phải nằm giữa trên mặt phẳng phân giác của góc tạo bởi hai đường tâm trục (Hình 6.11b). Để giữ cho các viên bi truyền lực luôn nằm trên mặt phẳng phân giác trong kết cấu cụ thể có thể thực hiện theo các kiểu khác nhau: - Tự định vị trên các rãnh cong (Hình 6.11c); - Dùng các vòng định vị (Hình 6.11d).","anchor":"block-1781162804032-gw6rm9wf8"},{"id":"s879","kind":"html","lesson":"6.3.3","title":"Truyền động các đăng · Khớp các đăng loại bi","text":"Thông thường các đăng đồng tốc được sử dụng để truyền lực cho bánh xe chủ động ở cầu dẫn hướng chủ động, vì góc quay của bánh dẫn hướng về hai phía có thể lên tới 300 - 400.","anchor":"block-1781162804032-gw6rm9wf8"},{"id":"s880","kind":"lesson","lesson":"6.3.4","title":"Truyền động các đăng · Các đăng đồng tốc bi kiểu Veise","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích phân biệt bi truyền lực và bi định tâm."},{"id":"s881","kind":"simulation","lesson":"6.3.4","title":"Phân biệt bi truyền lực và bi định tâm","text":"1. Nạng chủ động nhận mô men. Rãnh cong của nạng tạo vị trí cho các bi truyền lực. 2. Bốn bi ngoài truyền mô men. Các bi ngoài làm việc trong rãnh của hai nạng. 3. Bi giữa giữ định tâm. Viên bi thứ năm ở tâm khớp có nhiệm vụ định tâm, không thay nhiệm vụ bốn bi ngoài. 4. Nạng bị động nhận mô men. Rãnh ôm hai mặt phối hợp các bi khi góc giữa hai trục thay đổi."},{"id":"s882","kind":"figure","lesson":"6.3.4","title":"Hình 6.12 — Cấu tạo các đăng đồng tốc bi kiểu Veise","text":"A. Nạng chủ động. Nhận mô men đầu vào; có các rãnh chứa bi truyền lực. B. Bi truyền lực. Bốn bi ngoài đảm nhận truyền mô men giữa hai nạng. C. Bi giữa định tâm. Viên bi thứ năm đặt tại tâm khớp để định tâm. D. Nạng bị động. Nhận mô men qua các viên bi trong rãnh.","figure":{"image":"content/resources/T1_image281.jpg","caption":"Hình 6.12 — Cấu tạo các đăng đồng tốc bi kiểu Veise","number":"6.12"}},{"id":"s883","kind":"part","lesson":"6.3.4","title":"Nạng chủ động","text":"Nhận mô men đầu vào; có các rãnh chứa bi truyền lực.","keywords":["Nạng chủ động"],"figure":{"image":"content/resources/T1_image281.jpg","caption":"Hình 6.12 — Cấu tạo các đăng đồng tốc bi kiểu Veise","number":"6.12"}},{"id":"s884","kind":"part","lesson":"6.3.4","title":"Bi truyền lực","text":"Bốn bi ngoài đảm nhận truyền mô men giữa hai nạng.","keywords":["Bi truyền lực"],"figure":{"image":"content/resources/T1_image281.jpg","caption":"Hình 6.12 — Cấu tạo các đăng đồng tốc bi kiểu Veise","number":"6.12"}},{"id":"s885","kind":"part","lesson":"6.3.4","title":"Bi giữa định tâm","text":"Viên bi thứ năm đặt tại tâm khớp để định tâm.","keywords":["Bi giữa định tâm"],"figure":{"image":"content/resources/T1_image281.jpg","caption":"Hình 6.12 — Cấu tạo các đăng đồng tốc bi kiểu Veise","number":"6.12"}},{"id":"s886","kind":"part","lesson":"6.3.4","title":"Nạng bị động","text":"Nhận mô men qua các viên bi trong rãnh.","keywords":["Nạng bị động"],"figure":{"image":"content/resources/T1_image281.jpg","caption":"Hình 6.12 — Cấu tạo các đăng đồng tốc bi kiểu Veise","number":"6.12"}},{"id":"s887","kind":"figure","lesson":"6.3.4","title":"Hình 6.12. Cấu tạo cácđăng đồng tốc bi kiểu Veise","text":"Hình 6.12. Cấu tạo cácđăng đồng tốc bi kiểu Veise","anchor":"block-1781162887053-lvg522vx7","figure":{"number":"6.12","caption":"Hình 6.12. Cấu tạo cácđăng đồng tốc bi kiểu Veise"}},{"id":"s888","kind":"html","lesson":"6.3.4","title":"Truyền động các đăng · Các đăng đồng tốc bi kiểu Veise","text":"Trên cầu trước dẫn hướng, cầu chủ động có dầm cầu cứng với hệ thống treo phụ thuộc thường bố trí loại các đăng đồng tốc kiểu này. Trục chủ động có nạng chữ C. Hai bên của một đầu nạng có các rãnh tròn để chứa các viên bi truyền lực. Các rãnh tròn này được tạo với rãnh cong tròn có tâm là tâm của khớp với cung cong cho phép viên bi di chuyển trên nó xấp xỉ 300. Trong khớp có bốn viên bi nằm ngoài có nhiệm vụ truyền lực. Trục bị động có cấu tạo tương tự và lắp đối diện với các viên bi và tạo nên một rãnh ôm hai mặt với các viên bi. Một viên bi thứ 5 nằm giữa tâm khớp, hai phía được tì vào hai nửa trục truyền nhờ rãnh lõm hình chỏm cầu.","anchor":"block-1781162887053-lvg522vx7"},{"id":"s889","kind":"lesson","lesson":"6.3.5","title":"Truyền động các đăng · Các đăng đồng tốc bi kiểu Rzeppa","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích truyền mô men qua khớp Rzeppa."},{"id":"s890","kind":"simulation","lesson":"6.3.5","title":"Truyền mô men qua khớp Rzeppa","text":"1. Phần chủ động đưa mô men tới rãnh. Các rãnh trên phần chủ động nhận các viên bi. 2. Bi truyền mô men giữa hai phần. Sáu viên bi nằm trong các rãnh đối ứng của khớp. 3. Vòng định vị giữ mặt phẳng phân giác. Vòng định vị giữ các bi theo điều kiện đồng tốc. 4. Phần bị động nhận mô men. Bôi trơn bằng mỡ và vỏ cao su dạng xếp bảo vệ khớp theo tài liệu."},{"id":"s891","kind":"figure","lesson":"6.3.5","title":"Hình 6.13 — Cấu tạo các đăng đồng tốc bi kiểu Rzeppa","text":"A. Nạng chủ động. Phần khớp mang rãnh ngoài để truyền mô men qua bi theo ký hiệu 1. B. Nạng bị động. Phần khớp đối ứng theo ký hiệu 2, phối hợp với các rãnh bi. C. Vòng định vị. Giữ các bi trên mặt phẳng phân giác của góc giữa hai trục. D. Bi truyền lực. Truyền mô men trong các rãnh của hai phần khớp.","figure":{"image":"content/resources/T1_image282.jpg","caption":"Hình 6.13 — Cấu tạo các đăng đồng tốc bi kiểu Rzeppa","number":"6.13"}},{"id":"s892","kind":"part","lesson":"6.3.5","title":"Nạng chủ động","text":"Phần khớp mang rãnh ngoài để truyền mô men qua bi theo ký hiệu 1.","keywords":["Nạng chủ động"],"figure":{"image":"content/resources/T1_image282.jpg","caption":"Hình 6.13 — Cấu tạo các đăng đồng tốc bi kiểu Rzeppa","number":"6.13"}},{"id":"s893","kind":"part","lesson":"6.3.5","title":"Nạng bị động","text":"Phần khớp đối ứng theo ký hiệu 2, phối hợp với các rãnh bi.","keywords":["Nạng bị động"],"figure":{"image":"content/resources/T1_image282.jpg","caption":"Hình 6.13 — Cấu tạo các đăng đồng tốc bi kiểu Rzeppa","number":"6.13"}},{"id":"s894","kind":"part","lesson":"6.3.5","title":"Vòng định vị","text":"Giữ các bi trên mặt phẳng phân giác của góc giữa hai trục.","keywords":["Vòng định vị"],"figure":{"image":"content/resources/T1_image282.jpg","caption":"Hình 6.13 — Cấu tạo các đăng đồng tốc bi kiểu Rzeppa","number":"6.13"}},{"id":"s895","kind":"part","lesson":"6.3.5","title":"Bi truyền lực","text":"Truyền mô men trong các rãnh của hai phần khớp.","keywords":["Bi truyền lực"],"figure":{"image":"content/resources/T1_image282.jpg","caption":"Hình 6.13 — Cấu tạo các đăng đồng tốc bi kiểu Rzeppa","number":"6.13"}},{"id":"s896","kind":"figure","lesson":"6.3.5","title":"Hình 6.13. Cấu tạo các đăng đồng tốc bi kiểu Rzeppa.","text":"Hình 6.13. Cấu tạo các đăng đồng tốc bi kiểu Rzeppa.","anchor":"block-1781162911585-aun1e5569","figure":{"number":"6.13","caption":"Hình 6.13. Cấu tạo các đăng đồng tốc bi kiểu Rzeppa."}},{"id":"s897","kind":"html","lesson":"6.3.5","title":"Truyền động các đăng · Các đăng đồng tốc bi kiểu Rzeppa","text":"Loại các đăng đồng tốc kiểu này được sử dụng khá phổ biến trên ô tô du lịch cả với cầu chủ động loại dầm cầu liền và với hệ thống treo độc lập. Cấu tạo của chúng được mô tả trên Hình 6.13. Trục chủ động của các đăng một đầu nối với bánh răng bán trục của bộ vi sai và đầu còn lại lắp then hoa với một phần quả cầu, trên bề mặt ngoài có sáu nửa rãnh tròn. Trục bị động là một hốc cầu có sáu nửa rãnh tròn trong, chứa các viên bi. Các viên bi nằm trong rãnh tròn giữa các nửa rãnh trong và ngoài và được định vị bằng vòng định vị dạng cầu. Vòng định vị nằm sát với vách cầu của trục chủ động, đóng vai trò tạo mặt phẳng phân giác chứa các viên bi. Góc lệch tối đa cho phép giữa hai đường tâm trục khoảng 400.","anchor":"block-1781162911585-aun1e5569"},{"id":"s898","kind":"html","lesson":"6.3.5","title":"Truyền động các đăng · Các đăng đồng tốc bi kiểu Rzeppa","text":"1 - Nạng chủ động; 2 - Nạng bị động; 3 - Vòng định vị; 4 - Bi truyền lực Để thay đổi chiều dài của các đăng trong quá trình làm việc thì trục chủ động được ghép then hoa với quả cầu trong của các đăng. Khớp được bôi trơn bằng mỡ và được bao bọc bởi vỏ cao su dạng xếp.","anchor":"block-1781162911585-aun1e5569"},{"id":"s899","kind":"lesson","lesson":"6.3.6","title":"Truyền động các đăng · Các đăng đồng tốc kiểu Tripod","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Các đăng đồng tốc kiểu Tripod."},{"id":"s900","kind":"simulation","lesson":"6.3.6","title":"Nguyên lý: Các đăng đồng tốc kiểu Tripod","text":"1. Trục đầu vào truyền tới phần khớp. Hai phần khớp liên kết với các trục bằng then hoa theo kết cấu. 2. Rãnh thân bao tác động con lăn. Ba con lăn làm việc trong ba rãnh dọc của thân bao. 3. Con lăn truyền lực qua chạc ba. Chạc ba mang các con lăn; rãnh dọc cho phép bù dịch chuyển dọc trục. 4. Mô men được đưa tới trục đầu ra. Khớp phối hợp góc truyền và bù chiều dài trong phạm vi làm việc."},{"id":"s901","kind":"figure","lesson":"6.3.6","title":"Hình 6.14 — Cấu tạo các đăng đồng tốc kiểu Tripod","text":"A. Nạng chủ động. Phần đầu vào truyền mô men tới chạc ba. B. Chạc ba. Mang ba con lăn của khớp. C. Con lăn. Truyền lực trong rãnh và cho phép dịch chuyển dọc trục. D. Nạng bị động. Thân bao có ba rãnh dọc nhận tác động của các con lăn.","figure":{"image":"content/resources/T1_image283.jpg","caption":"Hình 6.14 — Cấu tạo các đăng đồng tốc kiểu Tripod","number":"6.14"}},{"id":"s902","kind":"part","lesson":"6.3.6","title":"Nạng chủ động","text":"Phần đầu vào truyền mô men tới chạc ba.","keywords":["Nạng chủ động"],"figure":{"image":"content/resources/T1_image283.jpg","caption":"Hình 6.14 — Cấu tạo các đăng đồng tốc kiểu Tripod","number":"6.14"}},{"id":"s903","kind":"part","lesson":"6.3.6","title":"Chạc ba","text":"Mang ba con lăn của khớp.","keywords":["Chạc ba"],"figure":{"image":"content/resources/T1_image283.jpg","caption":"Hình 6.14 — Cấu tạo các đăng đồng tốc kiểu Tripod","number":"6.14"}},{"id":"s904","kind":"part","lesson":"6.3.6","title":"Con lăn","text":"Truyền lực trong rãnh và cho phép dịch chuyển dọc trục.","keywords":["Con lăn"],"figure":{"image":"content/resources/T1_image283.jpg","caption":"Hình 6.14 — Cấu tạo các đăng đồng tốc kiểu Tripod","number":"6.14"}},{"id":"s905","kind":"part","lesson":"6.3.6","title":"Nạng bị động","text":"Thân bao có ba rãnh dọc nhận tác động của các con lăn.","keywords":["Nạng bị động"],"figure":{"image":"content/resources/T1_image283.jpg","caption":"Hình 6.14 — Cấu tạo các đăng đồng tốc kiểu Tripod","number":"6.14"}},{"id":"s906","kind":"figure","lesson":"6.3.6","title":"Hình 6.14. Cấu tạo các đăng đồng tốc kiểu Tripod.","text":"Hình 6.14. Cấu tạo các đăng đồng tốc kiểu Tripod.","anchor":"block-1781162946330-luk2k6kyw","figure":{"number":"6.14","caption":"Hình 6.14. Cấu tạo các đăng đồng tốc kiểu Tripod."}},{"id":"s907","kind":"figure","lesson":"6.3.6","title":"Hình 6.15. Cấu tạo các đăng đồng tốc kết hợp (trên ô tô Toyota Crown).","text":"Hình 6.15. Cấu tạo các đăng đồng tốc kết hợp (trên ô tô Toyota Crown).","anchor":"block-1781162946330-luk2k6kyw","figure":{"number":"6.15","caption":"Hình 6.15. Cấu tạo các đăng đồng tốc kết hợp (trên ô tô Toyota Crown)."}},{"id":"s908","kind":"html","lesson":"6.3.6","title":"Truyền động các đăng · Các đăng đồng tốc kiểu Tripod","text":"Cấu tạo của các đăng Tripod (Hình 6.14) gồm một thân bao hình trụ, trên đó xẻ ba rãnh dọc theo đường sinh. Thân bao hình trụ nối với trục chủ động bằng then hoa. Trục bị động lắp then hoa với một chạc ba và được cố định trên trục bằng hai vành hãm. Trên các đầu trục của trạc ba có bố trí các con lăn với hình bao ngoài dạng mặt cầu. Con lăn vừa quay trên trục vừa có thể di chuyển dọc trên trục của nó. Các con lăn bị hạn chế không chạy ra ngoài bởi gờ cao trên rãnh của thân bao hình trụ. Toàn bộ khớp các đăng được bọc trong một vỏ bọc cao su đàn hồi. Khớp các đăng loại này có khả năng truyền lực với góc lệch giữa hai đường tâm trục tới 250 và có khả năng di chuyển dọc trục lớn.","anchor":"block-1781162946330-luk2k6kyw"},{"id":"s909","kind":"html","lesson":"6.3.6","title":"Truyền động các đăng · Các đăng đồng tốc kiểu Tripod","text":"Với các góc truyền lớn hơn 250 không có khả năng giữ điểm truyền lực trong mặt phẳng phân giác vì vậy khó đảm bảo khả năng đồng tốc. tuy vậy so với các kiểu các đăng đồng tốc khác, loại các đăng này có công nghệ chế tạo đơn giản và giá thành thấp hơn. Chúng thường được bố trí trên các ô tô mini buýt hay pick-up cùng với dạng các đăng đồng tốc bi khác để tạo nên trục truyền với hai đầu là hai loại khớp các đăng khác nhau, được dùng ở hệ thống treo độc lập. Trên Hình 6.15 là cấu tạo của các đăng loại kết hợp được sử dụng trên ô tô Toyota Crown. Một đầu là khớp các đăng kiểu Tripod và một đầu là khớp các đăng kiểu Rzeppa. Đầu có cấu tạo kiểu Tripod đặt ở phía ngoài tạo điều kiện liên kết với trụ đứng trong hệ treo độc lập đồng thời có khả năng di chuyển dọc trục lớn để bù chiều dài khi bánh xe dao động theo phương thẳng đứng.","anchor":"block-1781162946330-luk2k6kyw"},{"id":"s910","kind":"lesson","lesson":"7.1.1","title":"Cầu chủ động · Chức năng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Chức năng."},{"id":"s911","kind":"simulation","lesson":"7.1.1","title":"Nguyên lý: Chức năng","text":"1. Truyền lực chính nhận mô men. Mô men từ hộp số được tăng thêm, tốc độ quay giảm. 2. Vỏ vi sai được dẫn động. Bánh răng bị động truyền lực chính gắn với vỏ vi sai. 3. Vi sai phân phối tới các bán trục. Cho phép tốc độ hai bánh khác nhau khi quay vòng. 4. Bánh xe chủ động nhận mô men. Bán trục đưa mô men từ vi sai ra bánh xe chủ động."},{"id":"s912","kind":"figure","lesson":"7.1.1","title":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","text":"A. Vỏ vi sai. Nhận mô men từ bánh răng bị động truyền lực chính. B. Bánh răng mặt trời (bán trục). Ăn khớp bánh răng vi sai và truyền mô men tới bán trục. C. Bánh răng hành tinh (vi sai). Tự quay khi cần tạo chênh lệch tốc độ giữa các bán trục. D. Trục bánh răng vi sai. Mang và định vị các bánh răng vi sai. E. Khớp khóa vi sai. Hạn chế chuyển động quay tương đối khi khóa vi sai.","figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s913","kind":"part","lesson":"7.1.1","title":"Vỏ vi sai","text":"Nhận mô men từ bánh răng bị động truyền lực chính.","keywords":["Vỏ vi sai"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s914","kind":"part","lesson":"7.1.1","title":"Bánh răng mặt trời (bán trục)","text":"Ăn khớp bánh răng vi sai và truyền mô men tới bán trục.","keywords":["Bánh răng mặt trời (bán trục)"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s915","kind":"part","lesson":"7.1.1","title":"Bánh răng hành tinh (vi sai)","text":"Tự quay khi cần tạo chênh lệch tốc độ giữa các bán trục.","keywords":["Bánh răng hành tinh (vi sai)"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s916","kind":"part","lesson":"7.1.1","title":"Trục bánh răng vi sai","text":"Mang và định vị các bánh răng vi sai.","keywords":["Trục bánh răng vi sai"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s917","kind":"part","lesson":"7.1.1","title":"Khớp khóa vi sai","text":"Hạn chế chuyển động quay tương đối khi khóa vi sai.","keywords":["Khớp khóa vi sai"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s918","kind":"figure","lesson":"7.1.1","title":"Hình 7.1. Truyền lực chính bánh răng côn và bánh răng trụ","text":"Hình 7.1. Truyền lực chính bánh răng côn và bánh răng trụ","anchor":"block-1781163137301-wj2wcrxg2","figure":{"number":"7.1","caption":"Hình 7.1. Truyền lực chính bánh răng côn và bánh răng trụ"}},{"id":"s919","kind":"html","lesson":"7.1.1","title":"Chức năng · a. Truyền lực chính","text":"a- Truyền lực chính với động cơ đặt dọc; b- Truyền lực chính với động cơ đặt ngang; 1- Bánh răng côn bị động; 2- Bánh răng côn chủ động; 3,9- Hộp số; 4,10- Ly hợp; 5,11- Động cơ ; 6- Trục các đăng; 7- Bộ vi sai; 8- Bánh răng trụ. - Truyền và tăng momen xoắn: Momen xoắn đã được biến đổi bởi hộp số nhiều cấp phải được tăng thêm ở truyền lực chính để đáp ứng đủ momen xoắn tại bánh xe chủ động trong mọi tình huống khi chạy xe trên đường. - Giảm tổc độ quay động cơ: Tốc độ quay động cơ đã biến đổi tại hộp số nhiều cấp được giảm xuống nhờ tỷ số truyền cố định của bộ truyền lực chính. - Chuyển hướng đường truyền lực, nếu cần: Nếu động cơ lắp theo phương dọc trục xe, đường truyền lực phải được chuyển hướng 90° bằng cặp bánh răng côn của bộ truyền lực chính, vì các bán trục của xe luôn nằm ngang Hình 7.1","anchor":"block-1781163137301-wj2wcrxg2"},{"id":"s920","kind":"html","lesson":"7.1.1","title":"Chức năng · b. Bộ vi sai","text":"- Cân bằng khác biệt tốc độ quay giữa các bánh xe chủ động: Khi xe đang quay vòng, các bánh xe phía ngoài phải di chuyển một quãng đường lớn hơn các bánh xe phía trong. Bề mặt đường khác nhau cũng gây nên sự khác biệt quãng đường đi. Vì vậy các bánh xe trên cùng một cầu sẽ quay với các tốc độ quay khác nhau. - Phân phối momen xoắn đồng đều tới các bánh xe chủ động: Bộ truyền động vi sai truyền momen xoắn đồng đều tới cả hai bánh xe chủ động ngay cả khi một bánh xe chủ động quay nhanh hơn bánh xe kia tùy theo lực cản mặt đường sinh ra tại các bánh xe.","anchor":"block-1781163174649-l35ef7xcw"},{"id":"s921","kind":"html","lesson":"7.1.1","title":"Chức năng · c. Bán trục","text":"Dùng để truyền mômen xoắn từ bộ vi sai đến các bánh xe chủ động. Nếu cầu chủ động là loại cầu liền (kết hợp với hệ thống treo phụ thuộc) thì truyền động đến các bánh xe nhờ các bán trục. Nếu cầu chủ động là cầu cắt (kết hợp với hệ thống treo độc lập) hoặc truyền mômen đến các bánh dẫn hướng là bánh chủ động thì có thêm khớp các đăng đồng tốc.","anchor":"block-1781163201147-zpqknrhtx"},{"id":"s922","kind":"lesson","lesson":"7.1.2","title":"Cầu chủ động · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân loại các phần tử cầu chủ động."},{"id":"s923","kind":"simulation","lesson":"7.1.2","title":"Trình tự phân loại các phần tử cầu chủ động","text":"1. Đếm cặp bánh răng truyền lực chính. Một cặp là đơn, hai cặp là kép. 2. Xét công dụng bộ vi sai. Phân biệt giữa bánh xe, giữa cầu xe và giữa truyền lực cạnh. 3. Xét mức chịu tải của bán trục. Đối chiếu bố trí ổ đỡ phía ngoài và tải trọng uốn của bán trục. 4. Xét kết cấu dầm cầu. Cầu liền hay cầu cắt là tiêu chí kết cấu riêng."},{"id":"s924","kind":"figure","lesson":"7.1.2","title":"Phân loại cầu chủ động — sơ đồ học tập biên soạn từ bài 7.1.2","text":"A. Truyền lực chính đơn. Phân loại theo số cặp bánh răng truyền lực chính. B. Truyền lực chính kép. Hai cặp truyền giảm tốc, có thể bố trí tập trung hoặc phân tán. C. Vi sai giữa các bánh xe. Phân loại vi sai theo công dụng, khác vi sai giữa các cầu. D. Bán trục giảm tải hoàn toàn. Phân loại bán trục theo mức chịu tải nhờ bố trí ổ đỡ.","figure":{"image":"tuong_tac/diagrams/axleclasses.svg","caption":"Phân loại cầu chủ động — sơ đồ học tập biên soạn từ bài 7.1.2"}},{"id":"s925","kind":"part","lesson":"7.1.2","title":"Truyền lực chính đơn","text":"Phân loại theo số cặp bánh răng truyền lực chính.","keywords":["Truyền lực chính đơn"],"figure":{"image":"tuong_tac/diagrams/axleclasses.svg","caption":"Phân loại cầu chủ động — sơ đồ học tập biên soạn từ bài 7.1.2"}},{"id":"s926","kind":"part","lesson":"7.1.2","title":"Truyền lực chính kép","text":"Hai cặp truyền giảm tốc, có thể bố trí tập trung hoặc phân tán.","keywords":["Truyền lực chính kép"],"figure":{"image":"tuong_tac/diagrams/axleclasses.svg","caption":"Phân loại cầu chủ động — sơ đồ học tập biên soạn từ bài 7.1.2"}},{"id":"s927","kind":"part","lesson":"7.1.2","title":"Vi sai giữa các bánh xe","text":"Phân loại vi sai theo công dụng, khác vi sai giữa các cầu.","keywords":["Vi sai giữa các bánh xe"],"figure":{"image":"tuong_tac/diagrams/axleclasses.svg","caption":"Phân loại cầu chủ động — sơ đồ học tập biên soạn từ bài 7.1.2"}},{"id":"s928","kind":"part","lesson":"7.1.2","title":"Bán trục giảm tải hoàn toàn","text":"Phân loại bán trục theo mức chịu tải nhờ bố trí ổ đỡ.","keywords":["Bán trục giảm tải hoàn toàn"],"figure":{"image":"tuong_tac/diagrams/axleclasses.svg","caption":"Phân loại cầu chủ động — sơ đồ học tập biên soạn từ bài 7.1.2"}},{"id":"s929","kind":"html","lesson":"7.1.2","title":"Phân loại · a. Theo truyền lực chính","text":"- Với cấp số truyền; Có thể có 1 cấp hoặc 2 cấp độ; - Với số cặp bánh răng: Có loại đơn và loại kép. Loại đơn có một cặp bánh răng ăn khớp và loại kép có hai cặp bánh răn khớp. - Với loại bánh răng: Có bánh răng nón, bánh răng hypoit và bánh răng trục vít. Hiện nay trên ô tô thường sử dụng bánh răng nón răng cong và bánh răng hypoit.","anchor":"block-1781163332827-ftjvn1ecl"},{"id":"s930","kind":"html","lesson":"7.1.2","title":"Phân loại · b. Theo bộ vi sai","text":"- Xét theo công dụng: Vi sai giữa các bánh xe; vi sai giữa các cầu xe; vi sai giữa các truyền lực cạnh. - Xét theo mức độ tự động: Vi sai không có hãm; vi sai có hãm bằng tay; vi sai hãm tự động. - Xét theo kết cấu: Vi sai loại bánh răng nón; vi sai loại bánh răng trụ; vi sai cam; vi sai trục vít; vi sai ma sát thủy lực; vi sai có tỉ số truyền thay đổi; vi sai có hành trình tự do. - Xét theo giá trị hệ số hãm: Vi sai ma sát trong nhỏ (kh= 0 - 0.2); vi sai ma sát trong lớn (kh= 0.21 - 0.7); vi sai hãm cứng (hk > 0.7).","anchor":"block-1781163358617-g71jjkwip"},{"id":"s931","kind":"html","lesson":"7.1.2","title":"Phân loại · c. Theo bán trục","text":"- Xét theo kết cấu của dầm cầu chia ra làm hai loại: Cầu liền và cầu rời (cầu cắt) - Xét theo mức độ chịu lực hướng kính và lực chiều trục chia ra làm bốn loại như sau: Loại không giảm tải; loại giảm tải ½; loại giảm tải ¾; loại giảm tải hoàn toàn.","anchor":"block-1781163375784-twg9mqis2"},{"id":"s932","kind":"lesson","lesson":"7.2.1","title":"Cầu chủ động · Truyền lực chính","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích đường truyền qua truyền lực chính."},{"id":"s933","kind":"simulation","lesson":"7.2.1","title":"Đường truyền qua truyền lực chính","text":"1. Bánh răng chủ động nhận mô men. Đường truyền vào tác động bánh răng côn chủ động. 2. Cặp bánh răng côn ăn khớp. Mô men truyền sang bánh răng côn bị động. 3. Đổi hướng và giảm tốc. Trong sơ đồ trục giao nhau, đường truyền được đổi hướng và tốc độ giảm theo tỷ số răng. 4. Vỏ vi sai được dẫn động. Bánh răng bị động gắn với vỏ vi sai để truyền tiếp tới các bán trục."},{"id":"s934","kind":"figure","lesson":"7.2.1","title":"Hình 7.2 — Bộ truyền lực chính bánh răng côn răng thẳng","text":"A. Bánh răng côn chủ động. Nhận mô men từ đường truyền vào. B. Bánh răng côn bị động. Giảm tốc, tăng mô men và truyền tới vỏ vi sai.","figure":{"image":"content/resources/T1_image286.jpg","caption":"Hình 7.2 — Bộ truyền lực chính bánh răng côn răng thẳng","number":"7.2"}},{"id":"s935","kind":"part","lesson":"7.2.1","title":"Bánh răng côn chủ động","text":"Nhận mô men từ đường truyền vào.","keywords":["Bánh răng côn chủ động"],"figure":{"image":"content/resources/T1_image286.jpg","caption":"Hình 7.2 — Bộ truyền lực chính bánh răng côn răng thẳng","number":"7.2"}},{"id":"s936","kind":"part","lesson":"7.2.1","title":"Bánh răng côn bị động","text":"Giảm tốc, tăng mô men và truyền tới vỏ vi sai.","keywords":["Bánh răng côn bị động"],"figure":{"image":"content/resources/T1_image286.jpg","caption":"Hình 7.2 — Bộ truyền lực chính bánh răng côn răng thẳng","number":"7.2"}},{"id":"s937","kind":"figure","lesson":"7.2.1","title":"Hình 7.2. Bộ truyền lực chính bánh răng côn răng thẳng","text":"Hình 7.2. Bộ truyền lực chính bánh răng côn răng thẳng","anchor":"block-1781163461770-mcje2o4i3","figure":{"number":"7.2","caption":"Hình 7.2. Bộ truyền lực chính bánh răng côn răng thẳng"}},{"id":"s938","kind":"figure","lesson":"7.2.1","title":"Hình 7.3. Bộ truyền lực chính bánh răng côn xoắn","text":"Hình 7.3. Bộ truyền lực chính bánh răng côn xoắn","anchor":"block-1781163461770-mcje2o4i3","figure":{"number":"7.3","caption":"Hình 7.3. Bộ truyền lực chính bánh răng côn xoắn"}},{"id":"s939","kind":"figure","lesson":"7.2.1","title":"Hình 7.4. Bộ truyền lực chính Hypoit","text":"Hình 7.4. Bộ truyền lực chính Hypoit","anchor":"block-1781163461770-mcje2o4i3","figure":{"number":"7.4","caption":"Hình 7.4. Bộ truyền lực chính Hypoit"}},{"id":"s940","kind":"figure","lesson":"7.2.1","title":"Hình 7.5. Bộ truyền lực chính bánh răng trụ","text":"Hình 7.5. Bộ truyền lực chính bánh răng trụ","anchor":"block-1781163461770-mcje2o4i3","figure":{"number":"7.5","caption":"Hình 7.5. Bộ truyền lực chính bánh răng trụ"}},{"id":"s941","kind":"figure","lesson":"7.2.1","title":"Hình 7.6. Bộ truyền lực chính trục vít-bánh vít","text":"Hình 7.6. Bộ truyền lực chính trục vít-bánh vít","anchor":"block-1781163461770-mcje2o4i3","figure":{"number":"7.6","caption":"Hình 7.6. Bộ truyền lực chính trục vít-bánh vít"}},{"id":"s942","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Bộ truyền lực chính bánh răng côn thể hiện trên Hình 7.1a, bao gồm một bánh răng côn dẫn động (bánh răng quả dứa) ăn khớp với bánh răng vành khăn (bánh răng vành chậu). Trong quá trình làm việc, mô men xoắn được truyền qua cặp bánh răng côn ăn khớp của truyền lực chính làm thay đổi phương quay của mô men xoắn trong hệ thống truyền lực. Sau đó, bộ vi sai nhận mômen xoắn nhờ vỏ vi sai lắp chặt với bánh răng bị động của truyền lực chính và phân phối mô men xoắn đến các bán trục ra bánh xe chủ động. Bộ truyền lực chính bánh răng côn bao gồm ba loại: loại bánh răng côn thẳng, loại bánh răng côn xoắn và loại truyền động hypoit. Loại truyền lực chính này gồm bánh răng côn chủ động và bánh răng côn bị động Hình 7.2 Bánh răng côn chủ động được chế tạo liền trục. Bánh răng côn bị động được chế tạo rời sau đó được lắp ghép cố định với vỏ vi sai bằng các bu lông.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s943","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Thông thường cặp bánh răng côn răng thẳng được bố trí dưới một góc 900. Truyền lực chính bánh răng côn thẳng hiện nay ít được sử dụng trên ô tô nhưng nó là cơ sở để chế tạo các loại truyền lực chính bánh răng côn xoắn và loại truyền động hypoit. Truyền lực chính bánh răng côn thẳng có ưu điểm là đơn giản, dễ chế tạo, giá thành thấp và trong quá trình lắp ráp không yêu cầu quá cao về ăn khớp của các bánh răng. Tuy nhiên, khỉ muốn tỉ số truyền lớn thì kích thước bánh răng bị động lớn thông thường lớn hơn 8 đến 9 răng nếu bé hơn thì sẽ xảy ra hiện tượng cắt chân răng do đó làm tăng kích thước của cầu chủ động, làm việc ồn. Ngoài ra cặp bánh răng nón răng thẳng làm việc không được êm dịu, nhất là khi xe chạy ở tốc độ cao ồn nhiều, khả năng chịu tải kém nên hiện nay ít được sử dụng.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s944","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"1- Bánh răng côn chủ động; 2- Bánh răng côn bị động Loại truyền lực chính này dùng phổ biến trên ô tô du lịch, ô tô tải nhỏ và trung bình. Đặc điểm cấu tạo được thể hiện trên Hình 7.3 Truyền lực chính bao gồm một cặp bánh răng côn xoắn. Trục chủ động 2 chế tạo liền với bánh răng côn xoắn chủ động và được gối trên vỏ bằng hai ổ bi côn. Khoảng cách và cách bố trí hai ổ côn có ảnh hưởng đến độ cứng vững của trục chủ động. Thông thường hai ổ bi côn được bố trí theo chiều như trên hình vẽ sao cho khoảng cách giữa hai tâm chịu lực thực tế là lớn. Bánh răng bị động 8 được chế tạo rời thành vành răng rồi lắp ghép cố định với vỏ bộ vi sai 7,18 bằng các bulông. Trong vỏ bộ vi sai có lắp đặt các trục 11 và bánh răng vi sai 13, hai bánh răng bán trục 14, các đệm tựa 15, 24 cho các bánh răng vi sai và bánh răng bán trục.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s945","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Số răng bánh răng chủ động có thề giảm tới 5 mà bộ truyền vẫn ăn khớp tốt và đủ bền, tăng được tỉ số truyền khi cùng kích thước với bánh răng bị động của truyền lực chính bánh răng côn răng thẳng. Làm việc êm dịu ngay cả khi tốc độ quay lớn nhờ đó mà có thể sừ dụng được cả với động cơ cao tốc. Truyền lực chính bánh răng côn xoắn do có độ cong của các răng và số lượng răng vào ăn khớp lớn nên chúng làm việc êm, khả năng truyền lực và mô men lớn, có độ bền cao, khả nàng chống mòn tốt, đồng thời yêu cầu một tỷ số truyền xác định nó sẽ cho kích thước nhỏ gọn, trọng lượng nhỏ hơn so với loại truyền lực chính bánh răng côn thẳng.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s946","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"1- Vòng bít làm kín; 2- Trục chủ động; 3,4,19- Vòng cách ngoài; 5,23- Bán trục; 6- Vòng cách trong; 7,18- Vỏ vi sai; 8- Bánh răng bị động; 9,13- Bánh răng vi sai; 10- Lỗ thoát nhiệt; 11- Trục bánh răng vi sai; 12,22,25,39- Vỏ cầu; 14- Bánh răng bán trục; 15,24- Đệm điều chỉnh; 16- Bu long; 17- Mặt bích; 20,33- Đai ốc điều chỉnh; 21- Tấm định vị đai ốc điều chỉnh; 26- Bạc chặn; 27- Cốc; 28- Tấm thép; 29- Tấm chặn; 30- Đầu chụp; 31- Vỏ chụp; 32- Mặt bích liên kết với các đăng; 34- Chốt; 35- Bu long; 36- Đệm khóa; 37,38- Đệm; 40,41- Đai ốc. Loại bộ truyền bánh răng côn xoắn có nhược điểm như sau: Khi ăn khớp phát sinh lực dọc trục lớn, nếu hướng xoắn của răng trên trục chủ động trùng với chiều quay của trục thì lực dọc trục sẽ có chiều từ đáy lên đỉnh bánh răng côn, gây nên hiện tượng kẹt bánh răng.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s947","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Vì vậy trong trường hợp ô tô chuyển động tịnh tiến bánh răng côn chủ động có chiều quay phải thì hướng xoắn của bánh răng chủ động phải xoắn trái. Như thế khi chuyển động lùi thì hướng xoắn và chiều quay lại trùng nhau nên lực chiều trục sẽ hướng về phía có khuynh hướng làm kẹt răng nhưng vì thời gian chuyển động lùi ngắn nên loại bánh răng vẫn được dùng. Khi chế tạo bánh răng côn răng xoắn, nhà chế tạo cố tạo ra điều kiện các răng ăn khớp theo vùng nghĩa là khi ăn khớp hai bánh răng sẽ tiếp xúc theo phạm vi trên răng mà không phải toàn cả răng. Muốn như vậy bán kính cong của bánh răng chủ động được chế tạo bé hơn bán kính cong của bánh răng chủ động một ít như thế các răng tiếp xúc nhau chỉ ở phần giữa. Bán kính cong được chọn khoảng gần một nửa chiều dài răng.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s948","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Còn khi tải trọng lớn thì xẽ tiếp xúc cả chiều dài răng, nếu được như vậy khi có sự dịch chuyển tương đối một khoảng nhỏ của hai bánh răng thì vùng ăn khớp chỉ dịch chuyển từ giữa răng ra phía này hay ra phía kia một chút. 1- Đai ốc châm dầu; 2- Bán trục; 3,4,6,15- Vỏ cầu; 5,11- Trục chủ động; 7- Vòng cách ngoài; 8- Vỏ chụp; 9- Mặt bích liên kết các đăng; 10- Đai ốc điều chỉnh; 12- Vòng cách trong; 13- Bánh răng chủ động; 14- Bánh răng bị động; 16- Đai ốc xả dầu. Đặc điểm cấu tạo được thể hiện trên Hình 7.4, ở truyền lực chính đơn Hypôit bánh răng côn chủ động được đặt lệch trục so với bánh răng côn bị động. Giá trị độ lệch trục nằm trong khoảng (0,125 - 0,2 ) đường kính bánh răng bị động. Trục bánh răng chủ động có thể đặt ở trên hoặc ở dưới so với đường tâm bánh răng bị động.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s949","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Các răng của các bánh răng truyền lực chính Hypôit là răng cong có góc nghiêng đường răng khác nhau. Góc nghiêng đường răng bánh răng chủ động (450-500) lớn hơn góc nghiêng đường răng bánh răng bị động (200-300). Do góc nghiêng đường răng lớn nên độ dài răng của bánh răng truyền lực chính Hypôit lớn hơn so với truyền lực chính bánh răng côn xoắn cùng kích thước. Truyền lực chính Hypôit làm việc êm hơn và có kích thước nhỏ gọn hơn khi cùng tỷ số truyền so với truyền lực chính bánh răng côn xoắn. So với truyền lực chính bánh răng côn xoắn thì truyền lực chính đơn Hypôit có sự trượt tương đối tại vùng ăn khớp khá lớn (có cả trượt ngang lẫn trượt dọc bề mặt răng khi ăn khớp).","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s950","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Do vậy để khắc phục nhược điểm này người ta dùng dầu bôi trơn chuyên dùng cho truyền lực chính Hyppoit (gọi là dầu bôi trơn Hypôit) và đảm bảo độ chính xác lắp ráp cao, điều chỉnh đúng trong quá trình sử dụng. Loại này có một số ưu điểm như sau: - Chạy êm dịu hơn vì số răng ăn khớp nhiều hơn; - Khả năng chịu tải cao hơn vì đường kính và bề rộng răng của bánh răng côn chủ động lớn hơn. - Cần ít không gian hơn vì bánh răng côn bị động có kích thước nhỏ hơn khi chịu cùng tải. Nhờ vậy, trục các đăng có thể lắp ở vị trí thấp hơn trên xe động cơ đặt phía trước cầu sau chủ động. - Nhờ độ lệch trục mà có thể nâng hoặc hạ chiều cao trọng tâm xe, giảm góc nghiêng trục các đăng và tăng tính êm dịu của cặp truyền lực bánh răng.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s951","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Bên cạnh đó loại này có một số nhược điểm như sau: - Đòi hỏi phải lắp ráp chính xác và bánh răng côn chủ động phải có điểm tựa chắc chắn. - Làm tăng sự trượt dọc của bánh răng truyền lực chính xuất hiện tại các điểm tiếp xúc mặt hông răng lớn hơn so với trường hợp không lệch trục, gây ra hiện tượng chóng mòn răng. Do vậy cần phải bôi trơn bằng dầu hypoit chuyên dùng có độ bền nén và độ bền cắt đặc biệt. Loại này thường được sử dụng trên các ôtô du lịch động cơ đặt trước và cầu trước chủ động (thường chế tạo liền một cụm với động cơ và hộp số). Cấu tạo của bộ truyền lực chính này được mô tả trên Hình 7.5 Truyền lực chính và vi sai được bố trí kết hợp với hộp số thành một khối.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s952","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Vì động cơ đặt ngang nên tâm trục hộp số song song với tâm trục cầu trước có nghĩa là hướng truyền lực từ trục ra hộp số đến trục vào của truyền lực chính là song song với nhau nên truyền lực chính sử dụng cặp bánh răng trụ. Bánh răng chủ động truyền lực chính là loại bánh răng trụ răng nghiêng. Bánh răng này được ăn khớp với bánh răng trụ bị động răng ngiêng và lắp trên vỏ hộp số ngang qua hai vòng bi bán trục. Bán trục ăn khớp với then hoa trong của bánh răng bán trục. Thường có hai bánh răng vi sai để dẫn động, nhưng ở các bộ vi dùng cho các động cơ có công suất cao thường dùng bốn bánh răng vi sai.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s953","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"1- Trục bị động họp số; 2- Bánh răng trụ chủ động truyền lực chính; 3- Bánh răng trụ bị động truyền lực chính Đặc điểm cấu tạo bộ truyền trục vít được biểu diễn trên Hình 7.6, truyền động trục vít được sử dụng ở một số loại ô tô buýt, ô tô 3 cầu và một số loại ô tô du lịch có công suất nhỏ. Trục vít có thể được đặt trên hoặc dưới bánh vít.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s954","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · a. Truyền lực chính đơn","text":"Bộ truyền lực chính loại này có những ưu nhược điểm sau: + Có khả năng làm việc êm dịu, có kích thước và trọng lượng nhỏ nhưng tỉ số truyền lớn. + Cho phép đặt bộ vi sai ở giữa cầu, nhờ đó mà cầu có kết cấu đối xứng, đối với ô tô 3 cầu có khả năng truyền mô men xoắn đến 2 cầu chủ động bằng một trục. + Khi đặt trục vít xuống dưới có thể hạ thấp được trọng tâm ô tô. + Hiệu suất truyền động thấp, đòi hỏi lắp ráp thật chính xác, nếu lắp ráp không chính xác thì hiệu suất càng thấp và trục vít chóng mòn. + Khi đặt trục vít xuống dưới khoảng sáng gầm xe giảm và làm tăng góc nghiêng của trục các đăng, nếu đặt trục vít lên trên việc bôi trơn cho cặp trục vít, bánh vít khó khăn. + Chế tạo phức tạp, giá thành cao. 1- Trục vít; 2- Bánh vít; 3- Trục bánh răng vi sai; 4- Bánh răng vi sai; 5- Vỏ vi sai; 6- Bánh răng mặt trời; 7- Đai ốc điều chỉnh; 8- Vỏ cầu.","anchor":"block-1781163461770-mcje2o4i3"},{"id":"s955","kind":"figure","lesson":"7.2.1","title":"Hình 7.7. Truyền lực chính kép loại tập trung","text":"Hình 7.7. Truyền lực chính kép loại tập trung","anchor":"block-1781163512048-nl8vx3bw8","figure":{"number":"7.7","caption":"Hình 7.7. Truyền lực chính kép loại tập trung"}},{"id":"s956","kind":"figure","lesson":"7.2.1","title":"Hình 7.8. Truyền lực chính kép loại tập trung","text":"Hình 7.8. Truyền lực chính kép loại tập trung","anchor":"block-1781163512048-nl8vx3bw8","figure":{"number":"7.8","caption":"Hình 7.8. Truyền lực chính kép loại tập trung"}},{"id":"s957","kind":"figure","lesson":"7.2.1","title":"Hình 7.9. Truyền lực cạnh với cơ cấu hành tinh ra bánh xích","text":"Hình 7.9. Truyền lực cạnh với cơ cấu hành tinh ra bánh xích","anchor":"block-1781163512048-nl8vx3bw8","figure":{"number":"7.9","caption":"Hình 7.9. Truyền lực cạnh với cơ cấu hành tinh ra bánh xích"}},{"id":"s958","kind":"figure","lesson":"7.2.1","title":"Hình 7.10. Truyền lực cạnh với cơ cấu hành tinh ra bánh hơi","text":"Hình 7.10. Truyền lực cạnh với cơ cấu hành tinh ra bánh hơi","anchor":"block-1781163512048-nl8vx3bw8","figure":{"number":"7.10","caption":"Hình 7.10. Truyền lực cạnh với cơ cấu hành tinh ra bánh hơi"}},{"id":"s959","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"Truyền lực chính kép được sử dụng trên những xe ô tô cần có tỉ số truyền của truyền lực chính lớn mà vẫn đảm bảo được kích thước của cầu xe gọn. Truyền lực chính kép gồm hai cặp bánh răng, một cặp bánh răng côn và một cặp bánh răng trụ. Trong truyền lực chính kép các cặp bánh răng côn và trụ cùng đặt trên vỏ của dầm cầu. Bộ vi sai được đặt sau cặp bánh răng trụ. Trục trung gian và bán trục (trục bị động) có thể đặt trong mặt phẳng nằm ngang Hình 7.7, hoặc trong mặt phẳng thẳng đứng Hình 7.8 để đảm bảo truyền mô men xoắn từ cầu giữa ra cầu sau bằng một trục các đăng. Trên bộ truyền lực chính Hình 7.7. Bánh răng côn trên trục trung gian 12 được lắp ghép cố định với trục bằng mối ghép then bằng. Bánh răng trụ 23 được chế tạo liền trục với trục trung gian và luôn ăn khớp với bánh răng trụ bị động 2.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s960","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"Đầu phía trong trục trung gian được gối bằng ổ bi đỡ trụ và đầu phía ngoài được đỡ bằng hai ổ đỡ côn để gia tăng độ cứng vững cho trục. Bánh răng trụ bị động 2 là một vành răng được lắp ghép cố định với hai phần vỏ bộ vi sai bằng các bu lông. 1,6- Vỏ bộ vi sai; 2- Bánh răng trụ bị động; 3- Trục bánh răng vi sai; 4- Đệm điều chỉnh; 5- Bánh răng vi sai; 7- Bánh răng bán trục; 8,11- Ổ đỡ trụ; 9- Lỗ thoát nhiệt; 10- Trục chủ động; 12- Bánh răng côn trên trục trung gian; 13- Bánh răng côn chủ động; 14- Ổ đỡ côn; 15- Vòng bít làm kín; 16,19,20,25- Đệm điều chỉnh; 17- Nắp trục; 18- Cốc; 21- Tấm chặn; 22,24,26,28- Bi côn; 23- Bánh răng trụ răng nghiêng trên trục trung gian; 27- Đai ốc điều chỉnh; 29- Tấm định vị đai ốc điều chỉnh; 30- Mặt bích.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s961","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"Ổ đỡ trục bánh răng chủ động 13 là hai ổ thanh lăn côn và một ổ trụ, trong đó hai ổ côn được đặt trong cốc 18, được kẹp chặt với vỏ truyền lực chính bằng các bu lông, ổ trụ đặt trên vỏ cầu để gia tăng độ cứng vững. Khe hở hai ổ này được điều chỉnh bằng các đệm điều chỉnh 20 đặt giữa vòng trong ổ và vòng cách. Ổ trục trung gian cũng là hai ổ thanh lăn côn cũng được điều chỉnh bằng các đệm điều chỉnh 25. Các đệm điều chỉnh này cũng có tác dụng điều chỉnh sự ăn khớp của cặp bánh răng côn xoắn. Ổ đỡ vỏ bộ vi sai và bánh răng trụ bị động sử dụng hai ổ thanh lăn côn. Hai ổ này được điều chỉnh nhờ hai đai ốc điều chỉnh 27 tại hai đầu vỏ bộ vi sai.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s962","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"1,5,34,37,38,43- Bu lông; 2- Đai ốc điều chỉnh; 3,22,27- Tấm chặn; 4,31- Bạc chặn; 6- Nắp; 7- Tấm định vị; 8,19,29- Đệm điều chỉnh; 9,41- Ổ đỡ côn; 10- Vỏ; 11- Bánh răng trụ răng nghiêng trên trục trung gian; 12- Then bằng; 13- Bánh răng côn trên trục trung gian; 14- Bi trụ; 15- Trục chủ động; 16- Nút đổ dầu; 17- Bánh răng côn chủ động; 18,30,35- Bi côn; 20- Cốc; 21- Nắp trục; 23- Vòng bít làm kín; 24- Mặt bích nối trục các đăng; 25- Chốt giữ; 26- Đai ốc; 28- Vỏ chụp; 32- Đệm lót; 33- Mặt bích; 36,47- Bán trục; 39- Bánh răng bị động; 40- Lỗ; 42- Đai ốc điều chỉnh; 44- Bu lông xả cặn; 45- Đệm định vị; 46- tấm định vị. Điều chỉnh sự ăn khớp của cặp bánh răng côn xoắn được thực hiện bằng cách dịch chuyển theo chiều trục cả hai bánh răng côn chủ động và bị động bằng các đệm điều chỉnh 16, 19.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s963","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"Điều chỉnh sự ăn khớp của cặp bánh răng trụ thực hiện sau khi điều chỉnh sự ăn khớp của cặp bánh răng côn xoắn nhằm cố định trục trung gian và dịch chuyển dọc trục bánh răng trụ bị động bằng việc vặn các đai ốc điều chỉnh 27. Bôi trơn truyền lực chính kép bằng dầu chứa trong vỏ cầu. Dầu bôi trơn cho các ổ trục bánh răng côn chủ động được chảy từ các đường rãnh trong vỏ truyền lực chính và cốc 18. Trên một số xe tải ba cầu chủ động, kết cấu truyền lực chính kép tại cầu sau được bố trí như Hình 7.8 tương ứng với truyền lực chính tại cầu giữa. Trục trung gian và trục bị động nằm trong phương thẳng đứng để đảm bảo đường truyền mô men xoắn từ cầu giữa tới cầu sau bằng một trục các đăng. Trên một số ô tô tải có tải trọng lớn, khi cần tỉ số truyền của truyền lực chính lớn người ta có thể sử dụng truyền lực chính kép phân chia như trên Hình 7.9 và Hình 7.10.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s964","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"Thực chất của truyền lực chính kép phân chia bao gồm hai bộ truyền: bộ truyền thứ nhất hoàn toàn giống như truyền lực đơn; bộ truyền thứ hai là một cặp bánh răng trụ được bố trí cạnh bánh xe chủ động (nên còn gọi là truyền lực cạnh hoặc giảm tốc bánh xe). Bộ truyền thứ hai này có thể là bộ truyền bánh răng trụ thông thường hoặc có thể là bộ truyền bánh răng trụ dạng hành tinh. a- Sơ đồ cấu tạo; b- Sơ đồ nguyên lý; 1- Bánh răng mặt trời; 2- Bánh răng ngoại luân; 3- Dẫn động ra bánh xe; 4- Bán trục; 5- Bánh răng hành tinh; 6- Trục bánh răng hành tinh.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s965","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"1- Bán trục; 2,8- Dầm cầu; 3,33- Ống chặn; 4,46,47,49- Mâm phanh; 5- Guốc phanh; 6,40- Vòng làm kín; 7- Trống phanh; 9- Bạc gắn vành răng cảm biến tốc độ; 10- Ống chặn; 11,38- Gioăng làm kín; 12- Bulong; 13- Cốc ngoài; 14,39- Ổ đỡ côn; 15- Cốc chặn; 16- Vòng; 17- Bánh răng ngoại luân; 18,22,29,35- Vòng chặn; 19,28- Đai ốc siết; 20- Bánh răng hành tinh; 21- Bi đũa; 23,25- Mặt bích; 24- Trục bánh răng hành tinh; 26- Vỏ chụp; 27,44- Vòng định vị; 30,32- Đai ốc, 31- Bánh răng mặt trời; 34,36- Vòng hãm; 37- Cốc trong; 41- Vành răng cảm biến tốc độ; 42- Cảm biến tốc độ; 43- Giá đỡ cảm biến tốc độ; 45- Bu long; 48- Ống đỡ. Trong truyền lực chính kép kiểu phân chia thường sử dụng cơ cấu hành tinh làm truyền lực cạnh như trên Hình 7.9 và Hình 7.10 làm khâu truyền động cuối cùng. Đó là cơ cấu gọn nhẹ, đơn giản và có khả năng truyền mô men với tỉ số truyền lớn.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s966","kind":"html","lesson":"7.2.1","title":"Truyền lực chính · b. Truyền lực chính kép","text":"Truyền động bắt đầu từ cặp bánh răng côn ăn khớp đầu vào tại vỏ cầu thông qua bộ vi sai truyền qua bán trục tới bánh răng mặt trời của truyền lực cạnh, sau đó thông qua bánh răng hành tinh, trục bánh răng hành tinh và bánh răng ngoại luân tới bánh xe. Truyền lực chính loại kép bố trí theo kiểu phân chia đảm bảo tăng được khoảng sáng gầm xe đồng thời làm giảm tải trọng tác dụng lên các chi tiết của bộ vi sai. Tuy nhiên ở truyền lực cạnh tại bánh xe lại có cấu tạo phức tạp, khó khăn trong việc bảo dưỡng và sửa chữa.","anchor":"block-1781163512048-nl8vx3bw8"},{"id":"s967","kind":"lesson","lesson":"7.2.2","title":"Cầu chủ động · Bộ vi sai","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích đi thẳng và quay vòng với vi sai đối xứng."},{"id":"s968","kind":"note","lesson":"7.2.2","title":"Tốc độ và mô men của vi sai mở","text":"Với vi sai đối xứng lý tưởng: n_trái + n_phải = 2n_vỏ; mô men hai đầu ra xấp xỉ bằng nhau khi bỏ qua ma sát nội. Bánh quay nhanh hơn không nhất thiết nhận mô men lớn hơn. Khóa vi sai và vi sai hạn chế trượt có quan hệ khác."},{"id":"s969","kind":"simulation","lesson":"7.2.2","title":"Đi thẳng và quay vòng với vi sai đối xứng","text":"1. Đi thẳng với lực cản hai bên bằng nhau. Bánh răng vi sai quay theo vỏ, không tự quay tương đối quanh trục của nó. 2. Hai bánh có quãng đường khác khi quay vòng. Bánh ngoài cần tốc độ lớn hơn bánh trong. 3. Bánh răng vi sai tự quay. Chuyển động tự quay tạo tốc độ khác nhau giữa hai bánh răng bán trục. 4. Hai bán trục truyền mô men ở tốc độ khác nhau. Vi sai cho phép chênh lệch tốc độ; khóa vi sai là một trạng thái khác."},{"id":"s970","kind":"figure","lesson":"7.2.2","title":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","text":"A. Vỏ vi sai. Nhận mô men từ bánh răng bị động truyền lực chính. B. Bánh răng mặt trời (bán trục). Ăn khớp bánh răng vi sai và truyền mô men tới bán trục. C. Bánh răng hành tinh (vi sai). Tự quay khi cần tạo chênh lệch tốc độ giữa các bán trục. D. Trục bánh răng vi sai. Mang và định vị các bánh răng vi sai. E. Khớp khóa vi sai. Hạn chế chuyển động quay tương đối khi khóa vi sai.","figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s971","kind":"part","lesson":"7.2.2","title":"Vỏ vi sai","text":"Nhận mô men từ bánh răng bị động truyền lực chính.","keywords":["Vỏ vi sai"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s972","kind":"part","lesson":"7.2.2","title":"Bánh răng mặt trời (bán trục)","text":"Ăn khớp bánh răng vi sai và truyền mô men tới bán trục.","keywords":["Bánh răng mặt trời (bán trục)"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s973","kind":"part","lesson":"7.2.2","title":"Bánh răng hành tinh (vi sai)","text":"Tự quay khi cần tạo chênh lệch tốc độ giữa các bán trục.","keywords":["Bánh răng hành tinh (vi sai)"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s974","kind":"part","lesson":"7.2.2","title":"Trục bánh răng vi sai","text":"Mang và định vị các bánh răng vi sai.","keywords":["Trục bánh răng vi sai"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s975","kind":"part","lesson":"7.2.2","title":"Khớp khóa vi sai","text":"Hạn chế chuyển động quay tương đối khi khóa vi sai.","keywords":["Khớp khóa vi sai"],"figure":{"image":"content/resources/T1_image295.jpg","caption":"Hình 7.11 — Cấu tạo bộ vi sai bánh răng côn đối xứng","number":"7.11"}},{"id":"s976","kind":"figure","lesson":"7.2.2","title":"Hình 7.11. Cấu tạo bộ vi sai bánh răng côn đối xứng","text":"Hình 7.11. Cấu tạo bộ vi sai bánh răng côn đối xứng","anchor":"block-1781163602707-cyxmzuffv","figure":{"number":"7.11","caption":"Hình 7.11. Cấu tạo bộ vi sai bánh răng côn đối xứng"}},{"id":"s977","kind":"figure","lesson":"7.2.2","title":"Hình 7.12. Nguyên lý hoạt động vi sai bánh răng côn đối xứng","text":"Hình 7.12. Nguyên lý hoạt động vi sai bánh răng côn đối xứng","anchor":"block-1781163602707-cyxmzuffv","figure":{"number":"7.12","caption":"Hình 7.12. Nguyên lý hoạt động vi sai bánh răng côn đối xứng"}},{"id":"s978","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Bộ vi sai bánh răng côn đối xứng được dùng phổ biến trên ô tô làm vi sai giữa các bánh xe trên một cầu để đảm bảo cho chúng quay với tốc độ khác nhau tùy theo lực cản của mặt đường tại vị trí các bánh xe. Sơ đồ cấu tạo được biểu diễn trên Hình 7.11. 1- Vòng hãm; 2- Khớp khóa vi sai; 3,8- Vỏ vi sai; 4- Trục bánh răng vi sai; 5- Bánh răng mặt trời (bán trục); 6,11- Đệm tựa; 7- Bánh răng bị động truyền lực chính; 9- Ống lót ; 10- Bánh răng hành tinh (vi sai). Cấu tạo của bộ vi sai Hình 7.11 bao gồm các chi tiết như sau: vỏ vi sai gồm hai nửa 3 và 8, chúng được lắp ghép cố định với nhau bằng các bu lông. Ở vỏ 8 có lắp cố định bánh răng bánh răng bị động của truyền lực chính bằng bu lông hoặc các vít cấy. Tại mặt phẳng phân chia vỏ vi sai được đặt trục bánh răng vi sai mà ở mỗi đầu của trục này đều có lắp bánh răng vi sai 10.","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s979","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Thông thường mỗi bộ vi sai có bốn bánh răng vi sai. Ở một số ô tô tải trọng nhỏ chỉ dùng hai bánh răng vi sai. Các bánh răng vi sai 10 đồng thời ăn khớp với hai bánh răng bán trục 5. Mặt lưng của các bánh răng vi sai 10 có dạng chỏm cầu và khi lắp các chỏm cầu này vào vỏ vi sai. Nhờ vậy mà các bánh răng vi sai được định tâm tốt và đảm bảo được độ chính xác ăn khớp với các bánh răng bán trục. Để giảm ma sát giữa bề mặt lưng của các bánh răng vi sai 10 và bánh răng bán trục 5 với vỏ vi sai và giảm sự mài mòn các bề mặt tỳ đó người ta đặt các đệm tựa 6 và 11. Thông thường các đệm tựa này được chế tạo bằng đồng thau và ở bề mặt tiếp xúc của nó có các lỗ nhỏ để chứa dầu bôi trơn. Tại moay ơ của các bánh răng bán trục 5 có gia công lỗ then hoa để lắp ghép với then hoa của các đầu bán trục.","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s980","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Việc bôi trơn vi sai được đảm bảo bằng các biện pháp kết cấu như: ở các ngõng trục chữ thập có các mặt vát để chứa dầu bôi trơn cho bánh răng vi sai; ở chân răng của bánh răng vi sai và bánh răng bán trục có gia công các lỗ dầu bôi trơn mặt tỳ lưng bánh răng, các lỗ nhỏ trên bề mặt đệm. 1- Trục chủ động; 2- Vỏ vi sai; 3- Bánh răng bán trục; 4- Bánh răng vi sai; 5- Trục bánh răng vi sai; 6- Bánh răng bị động. Nguyên lý hoạt động của bộ vi sai bánh răng côn đối xứng như sau: Khi vỏ vi sai 2 quay cùng với bánh răng bị động 6 của truyền lực chính với số vòng quay là n0 như Hình 7.12, qua các bánh răng hành tinh 4 và các bánh răng bán trục 3 làm cho các bán trục bên trái và bên phải quay số vòng quay theo thứ tự tương ứng là n1 và n2.","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s981","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Sự truyền mô men xoắn M0 từ vỏ vi sai 2 đến trục bánh răng vi sai 5, đến các bánh răng vi sai 4 và các bánh răng bán trục 3 rồi mới tới các bán trục bên trái là M1 và bên phải là M2. Xét các trường hợp xe hoạt động: + Khi xe chuyển động thẳng hoặc lực cản mặt đường tác dụng lên hai bánh xe là như nhau: Các bánh răng bán trục có cùng số vòng quay n1 = n2 nên các bánh răng vi sai 4 không chuyển động quay quanh trục của nó (lúc đó các bánh răng này chỉ tham gia một chuyển động quay cùng với vỏ vi sai).","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s982","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Các bánh răng của bộ vi sai đóng vai trò như những chêm đảm bảo cho các bộ vi sai quay thành một khối. n1 – Số vòng quay của bán trục bên trái; n2 – Số vòng quay của bán trục bên phải; M1 – Mô men xoắn phân ra bán trục bên trái; M2 – Mô men xoắn phân ra bán trục bên phải; n0, M0 – Số vòng quay và mô men xoắn trên vỏ vi sai. + Khi xe quay vòng hoặc khi sức cản mặt đường tác dụng lên hai bánh xe là khác nhau: Hai bánh răng bán trục sẽ quay với số vòng quay khác nhau n1 ≠ n2. Lúc đó các bánh răng vi sai vừa chuyển động quay theo vỏ vi sai và chúng còn có chuyển động quay tương đối xung quanh trục.","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s983","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Do các bánh răng vi sai đồng thời ăn khớp với hai bánh răng bán trục nên chúng sẽ làm tăng số vòng quay của bánh răng bán trục này lên bao nhiêu thì cũng đồng thời làm giảm số vòng quay của bánh răng bán trục kia đi bấy nhiêu để đảm bảo được phương trình động học của bộ vi sai (7.1). Do vậy các bánh xe sẽ không xảy ra sự trượt. Giả sử bánh xe bên trái quay nhanh và bánh xe bên phải quay chậm ( n1 > n2) khi đó sẽ xuất hiện mô men ma sát Mr do chuyển động quay tương đối của các bánh răng vi sai quanh trục của nó và chuyển động tương đối giữa các bánh răng bán trục. Ta gọi Mr là mô men ma sát trong của bộ vi sai. Khi đó mô men phân chia cho hai bánh trục sẽ là: Có nghĩa là mô men trên bán trục quay chậm hơn sẽ có giá trị lớn hơn mô men trên bán trục quay nhanh hơn. + Giả sử bánh xe chủ động bên phải nằm ở chỗ đường lầy còn bánh xe bên trái nằm ở chỗ đường tốt.","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s984","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Do vi sai này có mô men ma sát trong Mr nhỏ nên mô men xoắn truyền đến bánh xe bên trái được tăng lên nhưng cũng không đủ để khắc phục lực cản nên xe bị sa lầy, (M2 nhỏ do bánh xe bên phải có khả năng bám kém). Kết quả là bánh xe bên phải nằm ở chỗ lầy sẽ quay với tốc độ góc bằng tốc độ góc của vỏ vi sai còn bánh xe bên trái đứng yên và xe không thể chuyển động được, nghĩa là: Ngược lại nếu bánh xe bên phải nằm ở chỗ đường tốt và bánh xe bên trái nằm ở chỗ đường lầy thì hiện tượng xảy ra cũng tương tự, nghĩa là: + Khi tốc độ quay của vỏ vi sai đột ngột bằng không (n0 = 0). Trường hợp này xảy ra trong thực tế khi tiến hành phanh trục truyền bằng phanh tay hoặc kê kích bánh xe sau đó lấy tay quay một bánh xe trên cùng một cầu chủ động.","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s985","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Khi đó tốc độ góc của vỏ vi sai bằng 0, ta có: Điều này có nghĩa là chiều quay của bánh xe bên phải và bên trái là ngược nhau làm cho xe đang chuyển động có xu hướng quay ngang và mất khả năng ổn định hướng chuyển động. Vì vậy đối với những xe có bố trí phanh tay ở trục truyền lực thì trong quá trình xe đang chuyển động không được sử dụng phanh tay để phanh xe. Việc phân chia đều mô men xoắn cho các bánh xe chủ động thích hợp với những trường hợp xe chạy trên đường tốt hoặc điều kiện chuyển động của hai bánh xe là như nhau. Nó giảm tải trọng động cho dẫn động các bánh xe, giảm mòn lốp xe và giảm suất tiêu hao nhiêu liệu, dễ điều khiển xe. Tuy nhiên do ma sát trong bộ vi sai nhỏ nên làm giảm khả năng thông qua của xe khi một trong hai bánh xe nằm vào chỗ đường lầy (đường có hệ số bám nhỏ).","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s986","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · a. Vi sai bánh răng côn đối xứng","text":"Muốn khắc phục nhược điểm này cần phải có cơ cấu khoá vi sai khi cần thiết. Khi vi sai được khoá cứng hai bán trục được nối thành một trục cứng, khi đó sẽ cùng quay tốc độ như nhau và tận dụng trọng lượng bám của xe để vượt qua đường có hệ số bám thấp. Vi sai thường được khoá bằng cách nối một trong hai bán trục với vỏ vi sai nhờ khớp răng hoặc nhờ cơ cấu khoá kiểu cam.","anchor":"block-1781163602707-cyxmzuffv"},{"id":"s987","kind":"figure","lesson":"7.2.2","title":"Hình 7.13. Sơ đồ nguyên lý bộ vi sai cam hướng kính","text":"Hình 7.13. Sơ đồ nguyên lý bộ vi sai cam hướng kính","anchor":"block-1781163654392-jut1h7qpl","figure":{"number":"7.13","caption":"Hình 7.13. Sơ đồ nguyên lý bộ vi sai cam hướng kính"}},{"id":"s988","kind":"figure","lesson":"7.2.2","title":"Hình 7.14. Cấu tạo bộ vi sai cam","text":"Hình 7.14. Cấu tạo bộ vi sai cam","anchor":"block-1781163654392-jut1h7qpl","figure":{"number":"7.14","caption":"Hình 7.14. Cấu tạo bộ vi sai cam"}},{"id":"s989","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · b. Vi sai tăng ma sát","text":"Trên một số ô tô có tính năng cơ động cao, cần mô men ma sát trong bộ vi sai lớn để cho phép tăng khả năng chuyển động của ô tô trên đường trơn lầy thì người ta sử dụng bộ vi sai cam hướng kính. Sơ đồ nguyên lý như trên Hình 7.13 Đặc điểm cấu tạo bộ vi sai cam hướng kính hai dãy vấu cam và các con trượt như Hình 7.14. Vi sai được tạo bởi vòng cách 1, vành cam ngoài 3, vành cam trong 4, các con trượt 2 và vỏ vi sai. Vòng cách 1 là phần chủ động của bộ vi sai này. Nó được chế tạo liền mới moay ơ của bánh răng bị động truyền lực chính và là phần bên trái của vỏ vi sai. Ở thân vòng cách có gia công hai dãy lỗ để lắp các con trượt 2. Mỗi dãy lỗ gồm 12 lỗ hướng kính và các lỗ trên hai dãy được đặt so le nhau. Vành cam trong 4 gồm hai dãy cam gồm 6 vấu cam như nhau và hai dãy cam này cũng được bố trí so le nhau nửa bước.","anchor":"block-1781163654392-jut1h7qpl"},{"id":"s990","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · b. Vi sai tăng ma sát","text":"Ở moay ơ của vành cam trong 4 có gia công lỗ then hoa để lắp ghép với bán trục phía bên trái. Vành cam ngoài 3 chỉ có một dãy cam gồm 6 cam lõm có biên dạng và kích thước như nhau. Moay ơ của vành cam ngoài 3 có gia công lỗ then hoa để lắp ghép với bán trục phía bên phải và lỗ đưa dầu vào bôi trơn các bề mặt của vi sai. Vi sai cam có 24 con trượt được lắp đặt vào hai dãy lỗ của vòng cách 1. Ở mặt trong của vòng cách 1 người ta có đặt vòng chặn để chống xoay các con trượt và giữ chúng ở trong lỗ vòng cách khi lắp ráp. Các con trượt đều có một đầu tì vào các vấu của vành cam trong 4 và đầu ngoài tì vào vấu của vành cam ngoài 3. Vỏ vi sai gồm hai phần bên trái và bên phải. Chúng được lắp cố định với nhau bằng các bu lông.","anchor":"block-1781163654392-jut1h7qpl"},{"id":"s991","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · b. Vi sai tăng ma sát","text":"Như vậy nếu so sánh với vi sai bánh răng côn đối xứng thì các vành cam trong và vành cam ngoài thực hiện chức năng các bánh răng bán trục; vòng cách đóng vai trò trục chữ thập, còn các con trượt thực hiện nhiệm vụ của các bánh răng vi sai. 1- Vòng cách; 2- Cam trượt; 3- Vòng cách ngoài; 4- Vòng cách trong Nguyên lý hoạt động của bộ vi sai cam hướng kính như sau: Mô men xoắn trên vỏ vi sai hay từ vòng cách 1 truyền qua các con trượt tới 2 vành cam trong và vành cam ngoài rồi đến các bán trục. Khi xe chuyển động thẳng hoặc khi sức cản từ mặt đường tác dụng lên hai bánh xe là như nhau: Các con trượt 2 đóng vai trò như các bánh răng vi sai. Chúng giữ cho vòng cách 1, các vành cam trong 4 và vành cam ngoài 3 quay thành một khối. Mô men xoắn được phân bố đều ra hai bên bán trục.","anchor":"block-1781163654392-jut1h7qpl"},{"id":"s992","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · b. Vi sai tăng ma sát","text":"Tuy nhiên không phải 24 con trượt cùng truyền mô men mà tại một thời điểm bất kỳ ứng với một chiều quay của vòng cách 1, chỉ những con trượt nào mà hai đầu của nó cùng tiến vào phần lồi của các vấu cam ở vành cam trong và vành cam ngoài thì con trượt đó mới truyền mô men. Vi sai cam có hay dãy và thông thường mỗi dãy có 6 con trượt cùng truyền mô men nên tổng số con trượt cùng làm việc nhiều nhất là 12 con trượt theo một chiều quay của vòng cách. Khi xe quay vòng hoặc khi lực cản từ mặt đường tác dụng lên hai bánh xe là khác nhau: Hai bán trục có tốc độ quay khác nhau, khi đó giữa vành cam trong 4 và vành cam ngoài 3 có chuyển động quay tương đối với nhau. Các con trượt khi đó ngoài chuyển động quay cùng vòng cách chúng còn dịch chuyển tịnh tiến dọc trục của chúng và trượt trên các bề mặt cam của vành cam trong và vành cam ngoài.","anchor":"block-1781163654392-jut1h7qpl"},{"id":"s993","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · b. Vi sai tăng ma sát","text":"Các chuyển động tương đối làm phát sinh lực ma sát giữa hai đầu các con trượt với vành cam trong và vành cam ngoài. Lực ma sát tác dụng lên vành cam quay chậm cùng chiều với lực vòng tác dụng lên nó còn lực ma sát tác dụng lên vành cam quay nhanh ngược chiều với lực vòng tác dụng lên nó. Kết quả là mô men xoắn truyền đến bánh xe quay chậm được tăng lên và ngược lại. Điều này giúp cho xe có thể vượt qua được những chỗ khi mà một bên bánh xe nằm ở vùng đường xấu và một bên bánh xe ở vùng đường tốt. Khi một bánh xe bị trượt quay: Thời điểm ban đầu có sự chuyển động xoay tương đối giữa vành cam trong và vành cam ngoài.","anchor":"block-1781163654392-jut1h7qpl"},{"id":"s994","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · b. Vi sai tăng ma sát","text":"Đến khi đỉnh lồi của vấu cam dãy ngoài hoặc dãy trong của vành cam trong trùng với (phương hướng kính) đỉnh lõm của vấu cam ở vành cam ngoài hoặc ngược lại, khi đó cả dãy con trượt sẽ không truyền mô men và trong trường hợp này chỉ có 6 con trượt của dãy con trượt còn lại truyên mô men tới các bán trục. Khi tốc độ quay của vỏ vi sai đột ngột bằng không. Trường hợp này xảy ra trong thực tế khi tiến hành phanh trục truyền bằng phanh tay hoặc kê kích bánh xe sau đó lấy tay quay một bánh xe trên cùng một cầu chủ động: Do sức cản từ bánh răng bị động truyền lực chính nên vòng cách 1 không nhận được mô men.Vành cam trong 4 và vành cam ngoài 3 có chuyển động quay tương đối nên xuất hiện sự trượt dọc trục của các con trượt do biên dạng cam.","anchor":"block-1781163654392-jut1h7qpl"},{"id":"s995","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · b. Vi sai tăng ma sát","text":"Trên cùng chiều quay kim đồng hồ của vành cam ngoài (hoặc vành cam trong) một dãy 6 con trượt ở trạng thái làm việc của vành cam ngoài (hoặc vành cam trong) bị cản do vòng cách đứng yên. Khi đó 6 con trượt ở trạng thái làm việc của dãy còn lại có xu hướng khắc phục sự cản đó bằng cách tác động cho vành cam trong (hoặc vành cam ngoài) quay ngược chiều kim đồng hồ. Như vậy trong mọi trường hợp vi sai cam hai dãy đều có khả năng truyền mô men xoắn ra các bán trục vì có hai dãy cam và con trượt bố trí so le với nhau. Vi sai cam cũng có khả năng phân bố mô men xoắn ra các bánh xe chủ động phù hợp với điều kiện chuyển động của bánh xe: khi bánh xe nào có điều kiện bám tốt hơn thì mô men xoắn được truyền đến bánh xe đó lớn hơn và ngược lại. Tính chất này nâng cao khả năng cơ động và tính năng thông qua cho xe.","anchor":"block-1781163654392-jut1h7qpl"},{"id":"s996","kind":"figure","lesson":"7.2.2","title":"Hình 7.15. Vi sai giữa các bánh xe","text":"Hình 7.15. Vi sai giữa các bánh xe","anchor":"block-1781163690877-vk7c69gbg","figure":{"number":"7.15","caption":"Hình 7.15. Vi sai giữa các bánh xe"}},{"id":"s997","kind":"figure","lesson":"7.2.2","title":"Hình 7.16. Vi sai giữa các cầu xe","text":"Hình 7.16. Vi sai giữa các cầu xe","anchor":"block-1781163690877-vk7c69gbg","figure":{"number":"7.16","caption":"Hình 7.16. Vi sai giữa các cầu xe"}},{"id":"s998","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Khóa vi sai gồm có cơ cấu chuyển đổi và khớp gài. Việc chuyển đổi có thể thực hiện cơ học bằng tay, thủy lực hoặc khí nén. Hiện nay có thể sử dụng cơ cấu khóa vi sai để thực hiện khóa vi sai giữa các bánh xe như trên Hình 7.15 hoặc khóa vi sai giữa các cầu xe Hình 7.16 1- Bánh răng bị động truyền lực chính; 2- Trục bánh răng vi sai; 3- Cơ cấu gài; 4- Khớp gài; 5- Khớp răng; 6- Vỏ vi sai; 7,9- Bánh răng bán trục; 8- Bánh răng vi sai. Đặc điểm cấu tạo cơ cấu khóa vi sai giữa các bánh xe sử dụng cơ cấu vi sai bánh răng côn đối xứng như Hình 7.15. Khi vi sai được khoá cứng hai bánh răng bán trục được nối thành một trục cứng, khi đó sẽ cùng quay tốc độ như nhau và tận dụng trọng lượng bám của xe để vượt qua đường có hệ số bám thấp. Vi sai thường được khoá bằng cách nối một trong hai bán trục với vỏ vi sai 6 nhờ khớp răng 5 và khớp gài 4.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s999","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Khi gài cơ cấu khóa vi sai, khớp răng 5 sẽ liên kết bán trục bên phải với vỏ vi sai 6 và bánh răng bị động truyền lực chính 1. Khi đó cả ba chi tiết này sẽ cùng quay một tốc độ như nhau. Một sự liên kết giữa bán trục bên phải và vỏ vi sai thông qua răng trong của khớp gài và răng ngoài phía bên phải của vỏ vi sai. Vì vậy, các bánh răng vi sai không thể quay lăn trên các bánh răng bán trục. Chúng chỉ có tác dụng như bánh dẫn động. Sự cân bằng bị khóa 100 %. Cơ cấu khóa vi sai phải được tách ra khi độ bám mặt đường của các bánh xe chủ động có trị số bình thường, để tránh hư hỏng cho các bánh răng và khớp răng trên vỏ vi sai với trên ống gài.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1000","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"1,6,15- Mặt bích; 2- Vỏ xi lanh; 3- Trục truyền ra cầu sau; 4- Bánh răng côn chủ động; 5,12,13,20- Đai ốc; 7- Piston; 8,9- Lò xo; 10- Ống mềm, 11- Thanh trượt; 14- Công tắc cảm biến đóng mạch; 16,19- Vỏ;17- Vỏ vi sai; 18- Bánh răng vi sai; 21- Ống gài; 22,24- Bánh răng mặt trời; 23- Trục bánh răng vi sai (Trục chữ thập); 25- Bu long. Ngoài việc dùng vi sai bánh răng còn đối xứng làm vi sai giữa các bánh xe, nó còn được dùng làm vi sai giữa các cầu xe. Trên một số ô tô tải KaMaz có bố trí vi sai giữa cầu giữa và cầu sau là vi sai bánh răng côn đối xứng có khớp khoá vi sai. Bộ vi sai này được đặt ở cụm cầu giữa của xe. Đặc điểm cấu tạo của bộ vi sai và phần dẫn động khoá vi sai được thể hiện trên Hình 7.16 Vi sai giữa các cầu xe được lắp ráp trong vỏ 16, 19 và vỏ này được lắp cố định với vỏ truyền lực chính của cầu giữa.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1001","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Vỏ vi sai 17 có hai phần được lắp ghép cố định với nhau bằng các bu lông. Phần vỏ phía trước (bên trái) có một đoạn trục được chế tạo liền với nó tì lên ổ đỡ. Đầu của đoạn trục này có gia công then hoa để lắp ráp bích 1 và nhờ bích này nối dẫn động từ hộp số chính đến bộ vi sai bởi truyền động các đăng kép. Tại mặt phẳng lắp ráp hai phần của vỏ 17 có đặt chữ thập 23 mà ở các đầu ngõng trục của nó lắp bốn bánh răng vi sai 18. Mỗi bánh răng vi sai đều có đệm tựa. Các bánh răng vi sai đồng thời ăn khớp với hai bánh răng mặt trời 22 và 24 dẫn động cầu giữa và cầu sau. Các bánh răng mặt trời có kích thước như nhau. Bánh răng 24 dẫn động cầu sau được đặt trong hốc của phần vỏ phía trước của vi sai và có đệm tựa lưng. Các lỗ dẫn đầu được gia công trên vỏ vi sai để bôi trơn cho các bề mặt ma sát này.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1002","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Moay ơ của bánh răng 24 có gia công then hoa để lắp ghép then hoa cố định với trục dẫn động ra truyền lực chính cầu sau của xe. Bánh răng 22 dẫn động cầu giữa cũng có gia công lỗ then hoa lắp ghép then hoa với phần kéo dài của moay ơ bánh răng côn chủ động của truyền lực chính. Ở đoạn đuôi moay ơ bánh răng mặt trời 22 có gia công vành răng ngoài để ăn khớp với vành răng trong của ống gài 21. Ống gài 21 này có thể di chuyển dọc trục bánh răng 22 để ăn khớp với vành răng trên vỏ vi sai 17 nhằm thực hiện việc khoá vi sai khi cần thiết. Càng gài gắn trên ống gài được lắp cố định với thanh trượt 11 và thanh này được liên kết với cơ cấu dẫn động khoá vi sai. Vỏ 2 của cơ cấu dẫn động khoá vi sai được kẹp chặt với vỏ ngoài của bộ vi sai giữa các cầu xe. Giữa vỏ 2 và nắp của cơ cấu dẫn động vi sai là màng cao su 7.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1003","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Khoang bên trái màng đặt thanh trượt 11, nối ghép với cốc mà bên trong nó có lò xo nén 8, bên ngoài cốc là lò xo hồi vị 9. Cần của van điều khiển khoá vi sai được đặt ở bảng các loại đồng hồ trong cabin. Trên bảng này cũng có đèn báo tín hiệu khoá vi sai giữa các cầu xe. Nguyên lý của cơ cấu khóa vi sai giữa các cầu như sau: Quá trình làm việc của vi sai giữa các cầu xe này xảy ra tương tự như đối với vi sai bánh răng côn đối xứng giữa các bánh xe. Việc bố trí vi sai giữa các cầu xe làm cho các bánh xe trên các cầu có thể chuyển động quay với vận tốc góc khác nhau do vậy mà tránh được hiện tượng tuần hoàn công suất. Tuy nhiên do vi sai bánh răng côn đối xứng là loại vi sai có ma sát trong nhỏ nên khi các bánh xe của một cầu chủ động hoặc cả hai cầu chủ động nằm ở chỗ đường lầy (đường có khả năng bám kém) thì xe không thể vượt qua được.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1004","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Trường hợp này phải thực hiện việc khoá vi sai giữa các cầu xe. Ở vị trí như trên Hình 7.16, vi sai giữa các cầu không được khoá. Để khoá vi sai này, cần của van điều khiển khoá vi sai phải được người lái gạt sang bên phải (khoá vi sai cưỡng bức). Khi đó khí nén từ van điều khiển theo hệ thống dẫn khí và đường ống mềm 10 vào khoang bên phải của màng 7, tạo ra áp lực thắng sức căng của lò xo hồi vị 9 đẩy cốc và thanh trượt 11 về phía trước (sang trái). Khi thanh trượt 11 dịch chuyển, thông qua càng gài đẩy ống gài vào ăn khớp với vành răng trên vỏ vi sai 17. Khi đó bánh răng 22 dẫn động cầu giữa và vỏ 17 của bộ vi sai được khoá cứng với nhau và do vậy bộ vi sai giữa hai cầu được khoá, các bánh răng 22 và 24 dẫn động hai cầu giữa và sau sẽ quay cùng một tốc độ góc.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1005","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Đồng thời khi thanh trượt 11 dịch chuyển sang trái sẽ đóng công tắc của cảm biến đóng mạch 14 và đèn tín hiệu trong cabin sáng lên báo hiệu bộ vi sai giữa các cầu đã được khoá. Để nhả khoá vi sai, cần của van điều khiển được gạt sang bên trái. Khi nén trong khoang bên phải của màng 7 theo đường ống dẫn và van điều khiển thải ra ngoài khí trời. Quá trình xảy ra trong dẫn động khoá ngược lại với quá trình khoá vi sai. Việc khoá vi sai giữa các cầu nhất là khi ô tô chuyển động trên đường có khả năng bám kém sẽ cho phép xe có thể vượt qua được đoạn đường này. Tuy nhiên khi khoá vi sai các bánh xe của một cầu xe hoặc các cầu xe được nối cứng với nhau nên chúng luôn phải quay cùng một tốc độ và sẽ phát sinh những nhược điểm như không đặt vi sai giữa các bánh xe chủ động.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1006","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · c. Vi sai có cơ cấu khóa điều khiển được","text":"Vì vậy đối với các loại xe có cơ cấu gài cưỡng bức vi sai người lái phải tuân theo đúng những quy định và hướng dẫn sử dụng xe. Nhược điểm của cơ cấu khoá vi sai là không tự động hoá được việc khoá và nhả khoá nên dễ dẫn đến tình trạng khoá và nhả khoá vi sai không đúng lúc do người lái không đánh giá đúng điều kiện hoạt động của xe. Nhưng nhược điểm này có thể khắc phục nếu sử dụng khoá vi sai một cách tự động hoàn toàn hoặc dùng vi sai tự khoá với ma sát trong cao. Trong thiết kế chế tạo người ta đã tính toán đến việc vi sai có khớp khoá cưỡng bức sẽ không bị quên nhả khoá bởi người lái. Ví dụ hệ thống dẫn động điều khiển khoá vi sai cưỡng bức buộc người lái phải giữ cần điều khiển hoặc ấn nút điều kiển trong suốt quá trình vi sai được khoá. Tuy nhiên biện pháp này sẽ không thuận tiện trong sử dụng xe và vẫn có thể sai lầm khi khoá vi sai không đúng lúc.","anchor":"block-1781163690877-vk7c69gbg"},{"id":"s1007","kind":"figure","lesson":"7.2.2","title":"Hình 7.17. Khóa vi sai với ly hợp nhiều đĩa","text":"Hình 7.17. Khóa vi sai với ly hợp nhiều đĩa","anchor":"block-1781163732749-k35fgvf1n","figure":{"number":"7.17","caption":"Hình 7.17. Khóa vi sai với ly hợp nhiều đĩa"}},{"id":"s1008","kind":"figure","lesson":"7.2.2","title":"Hình 7.18. Khóa vi sai Torsen giữa các cầu","text":"Hình 7.18. Khóa vi sai Torsen giữa các cầu","anchor":"block-1781163732749-k35fgvf1n","figure":{"number":"7.18","caption":"Hình 7.18. Khóa vi sai Torsen giữa các cầu"}},{"id":"s1009","kind":"figure","lesson":"7.2.2","title":"Hình 7.19. Khóa vi sai Torsen giữa các bánh xe","text":"Hình 7.19. Khóa vi sai Torsen giữa các bánh xe","anchor":"block-1781163732749-k35fgvf1n","figure":{"number":"7.19","caption":"Hình 7.19. Khóa vi sai Torsen giữa các bánh xe"}},{"id":"s1010","kind":"figure","lesson":"7.2.2","title":"Hình 7.20. Vi sai tự khóa điều khiển bằng điện","text":"Hình 7.20. Vi sai tự khóa điều khiển bằng điện","anchor":"block-1781163732749-k35fgvf1n","figure":{"number":"7.20","caption":"Hình 7.20. Vi sai tự khóa điều khiển bằng điện"}},{"id":"s1011","kind":"figure","lesson":"7.2.2","title":"Hình 7.21. Các bộ phận vi sai tự khóa","text":"Hình 7.21. Các bộ phận vi sai tự khóa","anchor":"block-1781163732749-k35fgvf1n","figure":{"number":"7.21","caption":"Hình 7.21. Các bộ phận vi sai tự khóa"}},{"id":"s1012","kind":"figure","lesson":"7.2.2","title":"Hình 7.22. Vi sai tự khóa chủ động","text":"Hình 7.22. Vi sai tự khóa chủ động","anchor":"block-1781163732749-k35fgvf1n","figure":{"number":"7.22","caption":"Hình 7.22. Vi sai tự khóa chủ động"}},{"id":"s1013","kind":"figure","lesson":"7.2.2","title":"Hình 7.23. Sơ đồ nguyên lý của vi sai tự khóa chủ động","text":"Hình 7.23. Sơ đồ nguyên lý của vi sai tự khóa chủ động","anchor":"block-1781163732749-k35fgvf1n","figure":{"number":"7.23","caption":"Hình 7.23. Sơ đồ nguyên lý của vi sai tự khóa chủ động"}},{"id":"s1014","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Đặc điểm cấu tạo của khóa vi sai với ly hợp nhiều đĩa được thể hiện trên Hình 7.17. Ngoài các bộ phận của bộ vi sai bánh răng côn đối xứng, khóa vi sai này còn được bồ sung thêm hai vòng ép 12 và 17 và hai ly hợp nhiều đĩa về hai phía của bánh răng bán trục. 1,10- Bán trục; 2,9- Lò xo đĩa; 3- Trục bánh răng vi sai; 4- Bề mặt hình nêm; 5- Bánh răng chủ động truyền lực chính; 6- Các đĩa ngoài (không quay được trong vỏ vi sai); 7- Bánh răng bán trục; 8- Nắp; 11- Các đĩa trong (không quay được với bánh răng bán trục); 12,17- Vòng ép; 13- Bánh răng vi sai; 14- Chêm dẫn động; 15- Vỏ vi sai;16- Bánh răng bị động truyền lực chính. Các vòng ép 12, 17 có các chêm dẫn động 14 trên bề mặt xung quanh ăn khớp với các rãnh dọc trên vỏ vi sai 15. Chúng kết nối chặt không quay được với vỏ vi sai, nhưng có thể chuyển động dọc trục trên vỏ.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1015","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Các đĩa ngoài 6 và đĩa trong 11 được bố trí giữa mặt trước phía ngoài của vòng ép và mặt trước của vỏ vi sai. Các đĩa có răng ngoài ăn khớp với rãnh dọc trên ỏ vi sai, còn các đĩa có răng trong ăn khớp với răng ngoài của bán trục. Hai đĩa ép có bốn rãnh phay ở mặt trên phía bên trong là chỗ lắp trục các bánh răng côn vi sai. Các lò xo đĩa 2 và 9 được lắp đặt tạo lực ép ban đầu lên các đĩa. Nguyên lý làm việc của khóa vi sai như sau: Momen xoắn từ hộp số nhiều cấp được gia tăng bởi tỷ số truyền của bộ truyền lực chính và truyền qua bánh răng bị động truyền lực chính 16 và vỏ vi sai 15 tới các vòng ép 12 và 17. Khi độ bám mặt đường là tốt như nhau tại cả hai bánh xe trên một cầu: 50% mô men từ vỏ vi sai được truyền tới mỗi bánh xe chủ động.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1016","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Mô men được truyền qua bánh răng bị động truyền lực chính 16 tới vỏ vi sai và qua các vòng ép 12 và 17 (các vòng này có thể di chuyển dọc trục) tới các ly hợp nhiều đĩa và tới các bán trục. Khỉ độ bám mặt đường khác nhau tại mỗi bánh xe hoặc khí xe quay vòng: Thí dụ nếu bánh xe chủ động bên phải quay trượt, các bánh răng côn vi sai 13 sẽ quay. Các trục của chúng ép các vòng ép vào hai khối các đĩa ly hợp. Lực ép tạo nên momen ma sát phụ thuộc vào tải trọng giữa các đĩa có răng trong quay nhanh hơn và các đĩa có răng ngoài của khối các đĩa ly hợp bên phải. Momen ma sát này truyền qua vỏ vi sai, khối các đĩa ly hợp bên trái và các răng của bán trục trái tới bánh xe chủ động phía bên trái. Tại đây mô men này tác động thêm vào mô men dẫn động của phía bánh răng bán trục bên phải.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1017","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Nguyên lý cơ bản của vi sai Torsen dựa trên tinh chất tự khóa giữa trục vít và bánh vít trong bộ truyền trục vít. Mức độ tự khóa phụ thuộc vào góc nghiêng răng của trục vít và bánh vít. Sự tự khóa không xảy ra khi trục vít dẫn động bánh vít. Vi sai Torsen (Torsen = Torque sensing = cảm nhận momen xoắn) phân phối tùy theo mô men xoắn được cung cấp từ hộp số nhiều cấp. Vi sai có thể được dùng như khóa dọc trong bộ vi sai trung tâm để phân phối mô men tới các cầu, thí dụ với phân phối momen đều hoặc không đều như Hình 7.18 (40 % cầu trước và 60 % cầu sau) hoặc như khóa ngang giữa các bánh xe Hình 7.19 Vi sai Torsen bao gồm hai bộ truyền trục vít (trục vít và bánh vít). Các bánh răng trụ 6 liên kết hai bộ truyền trục vít với nhau bằng ăn khớp răng. Chúng lắp quay được trong vỏ vi sai 2. Mỗi trục vít 1 và 5 được liên kết chặt không quay được với mỗi bán trục.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1018","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Trong trường hợp phân phối momen bằng nhau, các bánh vít 7 có cùng kích thước Hình 7.19; nếu phân phối momen không bằng nhau, các bánh vít có đường kính khác nhau như Hình 7.18. 1- Bánh răng đầu vào; 2- Bánh vít dẫn động lớn; 3- Vỏ vi sai trung tâm; 4- Bánh vít dẫn động nhỏ. Nguyên lý là việc của khóa vi sai Torsen như sau: Đường truyền lực trong vi sai Torsen: Mô men dẫn động từ bánh răng bị động truyền lực chính 3 và truyền tới các trục vít 1, 5 của hai bán trục 4 và 8 nhờ vỏ vi sai 2 và các bánh vít 7. Khi độ bám mặt đường tốt như nhau tại cả hai bánh xe: Khi chạy trên đường thẳng, các bánh xe chủ động quay cùng tốc độ gốc, các bánh vít không quay cùng với các bánh răng trụ phía bên cạnh, và tác dụng như chêm dẫn động. Momen xoắn dược phân phối đồng đều tới hai bán trục.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1019","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Khi độ bám mặt đường khác nhau giữa hai bánh xe, khi quay vòng: Việc cân bằng tốc độ góc được thực hiện qua các bánh răng trụ 6 quay và các bánh vít 7, khi đó hiện tượng tự khóa xảy ra. Thí dụ, nếu bánh xe chủ động trái quay nhanh hơn, thì trục vít trái dẫn động bánh vít trái. Bánh răng trụ phía trái truyền chuyển động quay tới bánh răng trụ và bánh vít phía phải. Sự tự khóa tương ứng với trị số khóa xảy ra giữa bánh vít và trục vít. Bánh xe với độ bám đường tốt hơn hoặc tốc độ quay thấp hơn, ở đây là bánh xe phải, sẽ nhận được nhiều mô men hơn. 1- Trục vít bên phải; 2- Vỏ vi sai; 3- Vỏ Bánh răng bị động truyền lực chính; 4,8- Bán trục; 5- Trục vít bên trái; 6- Bánh răng trụ; 7- Bánh vít. Đây là vi sai tự khóa tự động hoàn toàn sử dụng động cơ điện với các bánh răng truyền động để khóa hoàn toàn 100% vi sai tại cầu sau.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1020","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Đặc điểm cấu tạo được thể hiện trên Hình 7.20 và Hình 7.21 Vỏ phía cầu sau với bộ truyền lực chính bánh răng côn có thêm một số chi tiết như sau: Một ly hợp nhiều đĩa 1 trong vỏ vi sai; một thiết bị tạo áp kiểu cơ học với đế cầu với các chi tiết đối ứng với đế cầu 4, bánh răng với đế cầu 5, đĩa 8 và bi 9; một động cơ điện với bánh răng truyền động để kích hoạt khóa. Nguyên lý làm việc của vi sai tự khóa thể hiện trên Hình 7.21 như sau: Nếu một bánh xe chủ động bị trượt quay, động cơ điện 7 được kích hoạt. Nhờ bánh răng truyền động 6, phần bánh răng với đế cầu 5 có gờ với độ dốc quay, khiến cho vòng ép 2 dịch chuyển dọc trục. Vòng ép 2 ép các đĩa bên trong liên kết với bán trục vào các đĩa bên ngoài với vỏ vi sai. Vi sai bị khóa 100 %. Nếu động cơ điện ngừng kích hoạt (không có điện), lò xo 10 đẩy vòng ép trở lại và ly hợp được nhả ra lại.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1021","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"1- Ly hợp nhiều đĩa; 2- Vòng ép; 3,4- Đế cầu; 5- Động cơ điện; 6- Bánh răng truyền động. 1- Ly hợp nhiều đĩa; 2- Vòng ép; 3- Chốt ép; 4- Chi tiết đối ứng với đế cầu 5- Bánh răng với đế cầu; 6- Bánh răng truyền động; 7- Động cơ điện; 8- Đĩa; 9- bi; 10- Lò xo. Đây là vi sai tự khóa hoàn toàn tự động, tùy theo tình trạng xe chạy nó có thể phân phối lực kéo vô cấp và thay đổi được tới từng bánh xe. Đặc điểm cấu tạo được thể hiện trên Hình 7.22. Một số bộ phận sau được tích hợp vào vỏ cầu phía sau cùng với bộ truyền lực chính bánh răng côn: Một bên bán trục có một bộ bánh răng hành tinh phối hợp gồm bánh răng mặt trời 3, 8 và vành răng trong 1, 2. Bộ bánh răng có thể được nối với các ly hợp nhiều đĩa 5 và 7; sử dụng hệ thống điều khiển điện-thủy lực để kích hoạt ly hợp nhiều đĩa.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1022","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Bộ vi sai tự khóa này có đặc điểm là lực kéo được cải thiện khi lực bám mặt đường thay đổi (trị số khóa tối đa là 30% tới 40%). Xe ô tô khi di chuyển sẽ có độ ổn định hướng tốt hơn khi quay vòng do khi quay vòng sẽ xuất hiện mô men quay quanh trục thẳng đứng đi qua trọng tâm ô tô. 1- Vành răng trong số 2; 2- Vành răng trong số 1; 3- Bánh răng mặt trời số 1; 4- Vành răng trong số 1; 5,7- Ly hợp nhiều đĩa; 6- Động cơ điện; 8- Bánh răng mặt trời số 2. Nguyên lý làm việc của hệ thống vi sai tự khóa tự động được thể hiện trên Hình 7.23 như sau: Tùy vào tốc độ xe, góc đánh lái và mô men quanh trục thẳng đứng của xe đi qua trọng tâm, các bánh xe chủ động được cung cấp mô men dẫn động khác nhau bằng cách kích hoạt ly hợp nhiều đĩa. Bằng cách này hiệu ứng tự lái của xe có thể được ảnh hưởng có chủ định.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1023","kind":"html","lesson":"7.2.2","title":"Bộ vi sai · d. Vi sai có cơ cấu khóa tự động","text":"Nếu sự gia tăng mô men được mong muốn ở một bánh xe chủ động, ly hợp nhiều đĩa đóng và kết nối bánh răng mặt trời 1 với vành răng trong 1. Thông qua các tỷ số truyền có tác dụng khác nhau (S1 tới H1 sau đó kết nối từ H2 sang S2), sự gia tăng mô men được tạo ra ở bánh xe phía đối diện. Khi đi thẳng, các ly hợp được nhả và mô men dẫn động được phân phối đều tới các bánh xe. S1- Bánh răng mặt trời 1; S2- Bánh răng mặt trời 2; H1- Vành răng trong 1; H2- Vành răng trong 2.","anchor":"block-1781163732749-k35fgvf1n"},{"id":"s1024","kind":"lesson","lesson":"7.2.3","title":"Cầu chủ động · Bán trục và vỏ cầu","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích phân biệt đường mô men và đường chịu tải."},{"id":"s1025","kind":"simulation","lesson":"7.2.3","title":"Phân biệt đường mô men và đường chịu tải","text":"1. Bánh răng bán trục nhận mô men. Bộ vi sai đưa mô men tới bán trục. 2. Bán trục truyền tới moay ơ. Mô men truyền ra bánh xe chủ động. 3. Ổ đỡ tiếp nhận tải bánh xe. Mức tải uốn trên bán trục phụ thuộc cách bố trí ổ đỡ phía ngoài. 4. Vỏ cầu truyền tải về hệ thống treo. Vỏ cầu làm giá đỡ và bao che; phân biệt đường truyền tải và mô men."},{"id":"s1026","kind":"figure","lesson":"7.2.3","title":"Bán trục và vỏ cầu — sơ đồ học tập biên soạn từ bài 7.2.3","text":"A. Bán trục giảm tải một nửa. Ổ đỡ phía ngoài lắp trực tiếp trên bán trục theo sơ đồ. B. Bán trục giảm tải hoàn toàn. Moay ơ được đỡ trên vỏ bán trục nên giảm tải uốn cho bán trục. C. Vỏ cầu. Đỡ và bảo vệ các phần tử truyền lực, liên kết với hệ thống treo. D. Khớp các đăng đồng tốc. Đáp ứng truyền động ở cầu với hệ thống treo độc lập.","figure":{"image":"tuong_tac/diagrams/halfshafts.svg","caption":"Bán trục và vỏ cầu — sơ đồ học tập biên soạn từ bài 7.2.3"}},{"id":"s1027","kind":"part","lesson":"7.2.3","title":"Bán trục giảm tải một nửa","text":"Ổ đỡ phía ngoài lắp trực tiếp trên bán trục theo sơ đồ.","keywords":["Bán trục giảm tải một nửa"],"figure":{"image":"tuong_tac/diagrams/halfshafts.svg","caption":"Bán trục và vỏ cầu — sơ đồ học tập biên soạn từ bài 7.2.3"}},{"id":"s1028","kind":"part","lesson":"7.2.3","title":"Bán trục giảm tải hoàn toàn","text":"Moay ơ được đỡ trên vỏ bán trục nên giảm tải uốn cho bán trục.","keywords":["Bán trục giảm tải hoàn toàn"],"figure":{"image":"tuong_tac/diagrams/halfshafts.svg","caption":"Bán trục và vỏ cầu — sơ đồ học tập biên soạn từ bài 7.2.3"}},{"id":"s1029","kind":"part","lesson":"7.2.3","title":"Vỏ cầu","text":"Đỡ và bảo vệ các phần tử truyền lực, liên kết với hệ thống treo.","keywords":["Vỏ cầu"],"figure":{"image":"tuong_tac/diagrams/halfshafts.svg","caption":"Bán trục và vỏ cầu — sơ đồ học tập biên soạn từ bài 7.2.3"}},{"id":"s1030","kind":"part","lesson":"7.2.3","title":"Khớp các đăng đồng tốc","text":"Đáp ứng truyền động ở cầu với hệ thống treo độc lập.","keywords":["Khớp các đăng đồng tốc"],"figure":{"image":"tuong_tac/diagrams/halfshafts.svg","caption":"Bán trục và vỏ cầu — sơ đồ học tập biên soạn từ bài 7.2.3"}},{"id":"s1031","kind":"figure","lesson":"7.2.3","title":"Hình 7.24. Sơ đồ lực tác dụng lên bán trục giảm tải một nửa","text":"Hình 7.24. Sơ đồ lực tác dụng lên bán trục giảm tải một nửa","anchor":"block-1781163796594-0f8j036ky","figure":{"number":"7.24","caption":"Hình 7.24. Sơ đồ lực tác dụng lên bán trục giảm tải một nửa"}},{"id":"s1032","kind":"figure","lesson":"7.2.3","title":"Hình 7.25. Cầu chủ động sử dụng bán trục giảm tải một nửa","text":"Hình 7.25. Cầu chủ động sử dụng bán trục giảm tải một nửa","anchor":"block-1781163796594-0f8j036ky","figure":{"number":"7.25","caption":"Hình 7.25. Cầu chủ động sử dụng bán trục giảm tải một nửa"}},{"id":"s1033","kind":"figure","lesson":"7.2.3","title":"Hình 7.26. Sơ đồ lực tác dụng lên bán trục giảm tải ba phần tư","text":"Hình 7.26. Sơ đồ lực tác dụng lên bán trục giảm tải ba phần tư","anchor":"block-1781163796594-0f8j036ky","figure":{"number":"7.26","caption":"Hình 7.26. Sơ đồ lực tác dụng lên bán trục giảm tải ba phần tư"}},{"id":"s1034","kind":"figure","lesson":"7.2.3","title":"Hình 7.27. Sơ đồ lực tác dụng lên bán trục giảm tải hoàn toàn","text":"Hình 7.27. Sơ đồ lực tác dụng lên bán trục giảm tải hoàn toàn","anchor":"block-1781163796594-0f8j036ky","figure":{"number":"7.27","caption":"Hình 7.27. Sơ đồ lực tác dụng lên bán trục giảm tải hoàn toàn"}},{"id":"s1035","kind":"figure","lesson":"7.2.3","title":"Hình 7.28. Cầu chủ động sử dụng bán trục giảm tải hoàn toàn","text":"Hình 7.28. Cầu chủ động sử dụng bán trục giảm tải hoàn toàn","anchor":"block-1781163796594-0f8j036ky","figure":{"number":"7.28","caption":"Hình 7.28. Cầu chủ động sử dụng bán trục giảm tải hoàn toàn"}},{"id":"s1036","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Các bán trục được sử dụng trên ô tô hiện nay được phân loại theo đặc điểm kết cấu các ổ đỡ phía ngoài của bán trục mà các ổ này xác định mức độ chịu tải trọng uốn của bán trục. Bán trục nối từ bánh răng bán trục của bộ vi sai tới các bánh xe chủ động. Bán trục thường phải đỡ toàn bộ trọng lượng xe cũng như chịu tải trọng của xe, tải trọng ngang khi xe quay vòng do đó chúng thường được tôi cứng để có thể tăng thêm chiều dài. Trên xe hiện nay việc bố trí trên hệ thống treo phụ thuộc thường dùng bán trục giảm tải ½ . Những xe hai hoặc ba cầu chủ động và một số xe tải nặng có công suất cao dùng bán trục giảm tải ¾ và bán trục giảm tải hoàn toàn.","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1037","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Loại bán trục không giảm tải hiện nay không còn được sử dụng. - Bán trục giảm tải một nửa Hình 7.24 : Là loại bán trục mà đầu phía trong tỳ lên vỏ vi sai 32 còn đầu phía ngoài có ổ đỡ 6 mà vòng trong lắp trực tiếp lên bán trục 1 còn vòng ngoài tỳ lên cốc nối 8 với vỏ bán trục. Bán trục giảm tải một nửa truyền mô men đến bánh xe chủ động.","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1038","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"1- Bán trục; 2,3,33- Bu long; 4- Giá đỡ; 5- Tang trống phanh; 6- Ổ đỡ cầu; 7- Bạc; 8- Cốc; 9,24- Phớt làm kín; 10- Dầm cầu; 11- Gioăng làm kín; 12- Mâm phanh; 13,28- Vỏ cầu; 14- Đai ốc điều chỉnh; 15,23- Ổ đỡ côn; 16- Mặt bích; 17- Đường thoát khí; 18- Bánh răng vi sai; 19- Bánh răng bị động truyền lực chính; 20- Bánh răng bán trục; 21- Đệm chặn; 22- Vỏ đỡ trục chủ động truyền lực chính; 25- Vỏ chụp; 26- Mặt bích nối với trục các đăng; 27- Tấm chặn; 29- Bánh răng chủ động truyền lực chính; 30- Trục bánh răng vi sai; 31- Đệm tựa; 32- Vỏ vi sai; 34- Tấm định vị cơ cấu điều chỉnh. Bán trục giảm tải một nửa có ổ phía ngoài là ổ bi cầu hoặc hai ổ thanh lăn côn chịu được lực chiều trục về cả hai phía. Ta thấy điểm tựa của đầu ngoài bán trục giảm một nửa tải là một ổ bi hình côn.","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1039","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Kết cấu như vậy giá thành rẻ hơn, nhưng cần chú ý trong trường hợp này lực chiều trục tác dụng vào phía trong ổ bi phía đối diện. Vì vậy mà phải có miếng đở để truyền lực chiều trục từ bán trục này sang bán trục khác. Loại này có kết cấu tương đối đơn giản nên được sử dụng ở các ô tô con và ô tô tải cỡ nhỏ. Sơ đồ lực tác dụng lên bán trục được thể hiện trên Error! Reference source not found. Ngoài mô men xoắn từ động cơ truyền tới, nó còn chịu thêm mô men bởi các lực tác dụng trong mặt phẳng thẳng đứng ngang xe như sau: Mô men uốn do phản lực pháp tuyến Rk sinh ra với cánh tay đòn là b trong mặt phẳng thẳng đứng ngang ; mô men uốn do phản lực ngang Yk gây ra với cánh tay đòn rk trong mặt phẳng thẳng đứng ngang .","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1040","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Trong mặt phẳng thẳng đứng dọc xe bán trục chịu sự tác dụng bởi mô men do các lực sinh ra như sau: Mô men uốn do lực kéo Pk và lực phanh Pp sinh ra lần lượt là và . Với sơ đồ lực tác dụng lên loại bán trục giảm tải ¾ Hình 7.26, một ổ bi đơn phía trong được tỳ trực tiếp lên vỏ vi sai như loại bán trục giảm tải ½, còn ổ ngoài được đặt trên dầm cầu và lồng vào moay ơ bánh xe. Ứng suất uốn trong bán trục giảm tải ¾ phụ thuộc độ cứng của bán trục và ổ bi. Cũng như bán trục giảm tải 1/2 có thể dùng loại moay ơ đơn giản. Khi đầu ngoài bán trục giảm tải ¾ đặt trong ổ côn lăn thẳng (ổ này không chịu được lực chiều trục) thì bánh răng bán trục phải chế tạo liền với bán trục để bán trục có thể tỳ lên trục chữ thập của vi sai. Như vậy tùy theo hướng của lực chiều trục thì một trong hai ổ bi của bánh răng bị động truyền lực chính sẽ phải chịu lực này.","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1041","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Lực chiều trục gây ra mômen uốn làm lệch ổ bi nên làm giảm tuổi thọ của ổ bi. Cũng vì lý do này mà ngày nay người ta ít dùng loại bán trục giảm ¾ tải. Khi làm việc phần lớn tải trọng của xe được đỡ bởi vỏ cầu, mặc dù phản lực ngang của đường Yk sẽ tác dụng vào bán trục khi quay vòng. Lực và mômen (trừ mô men phanh và mô men kéo) tác dụng lên đầu ngoài của bán trục sẽ nhờ ổ bi đặt trên dầm cầu chịu tải một phần. Ngoài ra bán trục còn chịu mô men bởi các lực tác dụng trong mặt phẳng thẳng đứng ngang xe như sau: Mô men uốn do phản lực pháp tuyến Rk sinh ra với cánh tay đòn là b trong mặt phẳng thẳng đứng ngang ; mô men uốn do phản lực ngang Yk gây ra với cánh tay đòn rk trong mặt phẳng thẳng đứng ngang .","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1042","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Trong mặt phẳng thẳng đứng dọc xe bán trục chịu sự tác dụng bởi mô men do các lực sinh ra như sau: Mô men uốn do lực kéo Pk và lực phanh Pp sinh ra lần lượt là và . Với loại bán trục giảm tải hoàn toàn Hình 7.27 chỉ khác với loại ¾ là gối đỡ phía ngoài gồm hai ổ đỡ côn 21 và 24 đặt gần nhau, ổ bi đơn phía trong 6 vẫn được tỳ trực tiếp lên vỏ vi sai. Đầu phía trong của bán trục 8 có then hoa sẽ ăn khớp lỗ then hoa ở bánh răng bán trục của bộ vi sai còn đầu ngoài được kẹp chặt với moay ơ bánh xe bằng các gu dông. Trong các lỗ bích đầu trục có một lỗ gia công ren và lắp bu lông vào đó. Nó được dùng để tháo bán trục ra khỏi cầu xe khi cần thiết. Hai ổ thanh lăn côn 21, 24 có vòng trong được lắp lên vỏ 19 của bán trục 20 còn vòng ngoài lắp lên moay ơ bánh xe.","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1043","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Điều chỉnh khe hở các ổ thanh lăn côn này và cố định chúng lên vỏ 19 của bán trục bằng đai ốc điều chỉnh ở đầu trục, các tấm đệm và có chốt định vị với đai ốc hãm. 1- Vỏ bộ vi sai; 2- Bánh răng vi sai; 3- Trục bánh răng vi sai; 4- Bánh răng bị động truyền lực chính; 5- Bánh răng bán trục; 6- Ổ bi đỡ trụ; 7- Đai ốc điều chỉnh; 8,20- Bán trục; 9,23,26,34- Phớt làm kín; 10- Vỏ cầu; 11- Nắp; 12- Ổ bi đỡ côn; 13- Mâm phanh; 14- Tang trống; 15- Guốc phanh; 16- Bạc của cơ cấu bơm lốp; 17- Vòng đệm; 18- Bu long; 19- Vỏ của bán trục; 21,24- Ổ bi côn; 22- Nắp đầu trục; 25- Lò xo hồi vị; 27- Mặt bích với mâm bánh xe; 28- Vòng liên kết với mâm phanh; 29,31- Bạc lót; 30- Bát xoay; 32- Gioăng làm kín; 33- Thanh kéo ngang. Vỏ cầu xe với kiểu bố trí bán trục loại này sẽ đỡ toàn bộ tải trọng của xe nên bán trục chỉ dẫn động bánh xe. Do vậy tránh được lực tác dụng bán trục.","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1044","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · a. Bán trục trên hệ thống treo phụ thuộc","text":"Kiểu này thường dùng cho xe ô tôt chở khách, xe tải loại vừa và lớn vì nó chịu được tải trọng lớn. Về mặt lý thuyết thì bán trục chỉ chịu có mômen xoắn. Nhưng trong thực tế do biến dạng đàn hồi của dầm cầu, do sai sót trong chế tạo (sự không đồng trục của mayơ bánh xe và bánh răng bán trục của vi sai) khó giữ được bán trục vuông góc với mặt bích. Vì vậy khi siết đai ốc phát sinh các biến dạng uốn bán trục và đầu bên phải bán trục sẽ tựa lên thành ổ bánh răng bán trục. Trong quá trình làm việc bán trục chỉ chịu mô men xoắn từ động cơ truyền xuống hoặc mô men do lực kéo và lực phanh sinh ra. Các lực như lực kéo Pk, lực ngang Yk và phản lực pháp tuyến Rk sẽ không truyền đến bán trục mà chỉ truyền đến dầm cầu.","anchor":"block-1781163796594-0f8j036ky"},{"id":"s1045","kind":"figure","lesson":"7.2.3","title":"Hình 7.29. Cấu tạo bán trục trên hệ thống treo độc lập","text":"Hình 7.29. Cấu tạo bán trục trên hệ thống treo độc lập","anchor":"block-1781163835170-mnd3nwhyg","figure":{"number":"7.29","caption":"Hình 7.29. Cấu tạo bán trục trên hệ thống treo độc lập"}},{"id":"s1046","kind":"figure","lesson":"7.2.3","title":"Hình 7.30. Bán trục dùng thêm trục trung gian","text":"Hình 7.30. Bán trục dùng thêm trục trung gian","anchor":"block-1781163835170-mnd3nwhyg","figure":{"number":"7.30","caption":"Hình 7.30. Bán trục dùng thêm trục trung gian"}},{"id":"s1047","kind":"figure","lesson":"7.2.3","title":"Hình 7.31. Sơ đồ thể hiện góc lệch của hai bán trục","text":"Hình 7.31. Sơ đồ thể hiện góc lệch của hai bán trục","anchor":"block-1781163835170-mnd3nwhyg","figure":{"number":"7.31","caption":"Hình 7.31. Sơ đồ thể hiện góc lệch của hai bán trục"}},{"id":"s1048","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · b. Bán trục trên hệ thống treo độc lập","text":"1- Bánh răng bán trục; 2- Vỏ vi sai; 3- Vỏ của khớp các đăng Tripol; 4- Giá đỡ; 5- Trụ lái đứng; 6- Ngõng trục; 7- Đai ốc đầu trục; 8- Ổ đỡ; 9- Khớp các đăng Rzeppa; 10- Bán trục; 11- Khớp các đăng Tripol. Những ô tô có cầu chủ động với hệ thống treo độc lập thường chế tạo theo kiểu bán trục rời. Bán trục rời thường được dùng khi bộ vi sai gắn chắc chắn trên khung xe. Sử dụng khớp các đăng đồng tốc trên bán trục là cần thiết để cho phép hệ thống treo dịch chuyển lên xuống trong quá trình xe chuyển động. Kết cấu như vậy đảm bảo độ êm dịu chuyển động, vì bánh xe có thể dịch chuyển lên xuống trong mặt phẳng thẳng đứng khi đi trên đường có biên dạng mấp mô.","anchor":"block-1781163835170-mnd3nwhyg"},{"id":"s1049","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · b. Bán trục trên hệ thống treo độc lập","text":"Bán trục khi truyền mômen từ bộ vi sai đến các bánh xe chủ động phải thỏa mãn hai yêu cầu sau: - Nó phải có cơ cấu thay đổi chiều dài bán trục khi các bánh xe dịch chuyển lên xuống. - Do các bánh trước vừa là bánh dẫn hướng, vừa là bánh chủ động nên các bán trục phải có khả năng đảm bảo thay đổi về góc khi đang lái và đảm bảo điều kiện đồng tốc khi truyền mô men. Với truyền động loại này bán trục trên dầm cầu cắt sẽ dùng các khớp các đăng đồng tốc khác nhau. Khớp các đăng phía bánh xe được sử dụng rộng rãi nhất là khớp đồng tốc Rzeppa, khớp phía bộ vi sai sử dụng khớp Tripol vì có góc lệch trục lớn hơn. 1- Ổ đỡ; 2,8- Khớp Rzeppa; 3,7- Khớp Tripol; 4- Vỏ vi sai; 5- Nạng; 6-Khớp các đăng chữ thập; 9,11- Trục bánh xe; 10- Trục trung gian. Trên Hình 7.30 thể hiện sơ đồ cấu tạo bán trục sử dụng thêm một trục trung gian 10 được gắn ở phía bán trục dài hơn.","anchor":"block-1781163835170-mnd3nwhyg"},{"id":"s1050","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · b. Bán trục trên hệ thống treo độc lập","text":"Vì vậy hai bán trục bên trái và bên phải có thể làm cùng chiều dài. Kiểu bán trục này được sử dụng ở nhiều xe mà có sự chênh lệch lớn về chiều dài giữa hai bán trục lớn và nó thường được dùng ở xe có động cơ và hộp số đều đặt nằm ngang. 1- Bán trục phía bên trái; 2- Bán trục phía bên phải; 3- Vỏ cầu; - Góc lệch của bán trục trái so với tâm trục bánh xe; - Góc lệch của bán trục bên phải so với tâm trục bánh xe. Trên Hình 7.31 thể hiện sự chệnh lệch chiều dài giữa hai bán trục làm xuất hiện hiện tượng tự lái. Khi ô tô khởi hành sau đó tăng ga đột ngột, đầu xe bị nâng lên và góc nghiêng , (so với tâm trục bánh xe) của bán trục lớn nên có xu hướng sinh ra một mômen làm các bánh xe xoay quanh trục thẳng đứng của khớp ngoài vào phía trong. Mô men này càng lớn khi góc nghiêng của bán trục càng lớn.","anchor":"block-1781163835170-mnd3nwhyg"},{"id":"s1051","kind":"html","lesson":"7.2.3","title":"Bán trục và vỏ cầu · b. Bán trục trên hệ thống treo độc lập","text":"Vì vậy, như Hình 7.31 mômen sinh ra ở phía bán trục ngắn hơn trong hai bán trục (bán trục có góc nghiêng θ1 lớn hơn) có xu hướng làm bánh xe quay vào trong sẽ lớn hơn, trong khi mô men của trục dài hơn (trục có góc nghiêng θ2) sẽ nhỏ hơn, nên xe có xu hướng quay về phía bán trục dài. Do đó một phương pháp để ngăn cản sự tự lái như trên là lắp thêm một trục trung gian 10 như Hình 7.30, thì khi đó có thể làm hai bán trục có chiều dài bằng nhau. Nếu dùng phương pháp này, góc nghiêng θ1 và θ2 của hai bán trục sẽ bằng nhau nên mô men làm các bánh xe phía trước xoay vào trong sẽ khử lẫn nhau và đảm bảo được tính ổn định chuyển động thẳng của xe.","anchor":"block-1781163835170-mnd3nwhyg"},{"id":"s1052","kind":"lesson","lesson":"8.1.1","title":"Cụm bánh xe · Lốp xe","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quan hệ chịu tải và tiếp xúc mặt đường."},{"id":"s1053","kind":"simulation","lesson":"8.1.1","title":"Quan hệ chịu tải và tiếp xúc mặt đường","text":"1. Tải trọng xe tác dụng lên lốp. Lốp được bơm khí có áp và đỡ tải trọng xe. 2. Kết cấu lốp truyền tới vết tiếp xúc. Lớp bố và các lớp lốp phối hợp chịu tải. 3. Hoa lốp tiếp xúc mặt đường. Lực dẫn động và lực phanh được truyền giữa xe và đường tại vùng tiếp xúc. 4. Lốp biến dạng qua mấp mô. Biến dạng lốp góp phần giảm chấn động; áp suất không phù hợp gây mòn bất thường."},{"id":"s1054","kind":"figure","lesson":"8.1.1","title":"Hình 8.1 — Cấu tạo của lốp","text":"A. Hoa lốp. Tiếp xúc với mặt đường, truyền lực kéo và lực phanh. B. Lớp sợi bố. Tạo kết cấu chịu tải của lốp. C. Lớp lót trong. Lớp phía trong của lốp, giữ kín khí ở lốp không săm. D. Dây mép lốp. Giữ mép lốp chắc trên vành bánh xe.","figure":{"image":"content/resources/T1_image329.jpg","caption":"Hình 8.1 — Cấu tạo của lốp","number":"8.1"}},{"id":"s1055","kind":"part","lesson":"8.1.1","title":"Hoa lốp","text":"Tiếp xúc với mặt đường, truyền lực kéo và lực phanh.","keywords":["Hoa lốp"],"figure":{"image":"content/resources/T1_image329.jpg","caption":"Hình 8.1 — Cấu tạo của lốp","number":"8.1"}},{"id":"s1056","kind":"part","lesson":"8.1.1","title":"Lớp sợi bố","text":"Tạo kết cấu chịu tải của lốp.","keywords":["Lớp sợi bố"],"figure":{"image":"content/resources/T1_image329.jpg","caption":"Hình 8.1 — Cấu tạo của lốp","number":"8.1"}},{"id":"s1057","kind":"part","lesson":"8.1.1","title":"Lớp lót trong","text":"Lớp phía trong của lốp, giữ kín khí ở lốp không săm.","keywords":["Lớp lót trong"],"figure":{"image":"content/resources/T1_image329.jpg","caption":"Hình 8.1 — Cấu tạo của lốp","number":"8.1"}},{"id":"s1058","kind":"part","lesson":"8.1.1","title":"Dây mép lốp","text":"Giữ mép lốp chắc trên vành bánh xe.","keywords":["Dây mép lốp"],"figure":{"image":"content/resources/T1_image329.jpg","caption":"Hình 8.1 — Cấu tạo của lốp","number":"8.1"}},{"id":"s1059","kind":"figure","lesson":"8.1.1","title":"Hình 8.1. Cấu tạo của lốp","text":"Hình 8.1. Cấu tạo của lốp","anchor":"block-1781164047048-hgjz2k8uc","figure":{"number":"8.1","caption":"Hình 8.1. Cấu tạo của lốp"}},{"id":"s1060","kind":"figure","lesson":"8.1.1","title":"Hình 8.2. Thông số của lốp","text":"Hình 8.2. Thông số của lốp","anchor":"block-1781164047048-hgjz2k8uc","figure":{"number":"8.2","caption":"Hình 8.2. Thông số của lốp"}},{"id":"s1061","kind":"html","lesson":"8.1.1","title":"Cụm bánh xe · Lốp xe","text":"Các xe chạy bằng lốp hơi đượcbơm không khí có áp suất. Lốp là bộphậnduy nhất của xe tiếp xúc trực tiếp với mặt đường. Nếu áp suất không khí tronglốp không chính xác có thể gây ra độ mòn bất thường và giảm tính năng dẫn động. Lốp thực hiện các chức năng sau đây: -Lốp đỡ toàn bộ trọng lượng của xe -Lốp trực tiếp tiếp xúc với mặt đường và do đó truyền lực dẫn động và lực phanh vào đường, do đó chi phối việc chuyển bánh, tăng tốc, giảm tốc, đỗ xe và quay vòng. -Lốp làm giảm chấn động do các mấp môởmặt đường gây ra. Lốp có các loại lốp có săm và lốp không có săm. Ngoài ra, còn có loại lốp bố tròn và lốp bố chéo, cả hai loại cùng có các bộ phận được chỉ ra trên Hình 8.1. Hoa lốp: Lớp bên ngoài của lốp dùng để bảo vệ lớp sợi bố và chống mòn cũng như rách. Là lớp cao su, được trình bày ở hình trên.","anchor":"block-1781164047048-hgjz2k8uc"},{"id":"s1062","kind":"html","lesson":"8.1.1","title":"Cụm bánh xe · Lốp xe","text":"Nó có tác dụng bảo vệ cho lớp bố không bị mòn và các hư hỏng bên ngoài do quá trình tiếp xúc với mặt đường. Bề mặt gai lốp được xẻ nhiều rãnh để tăng hiệu quả truyền lực kéo và lực phanh tới mặt đường. Lớp đai (lớp lót tăng cứng): Những dây tăng cường được bố trí dọc theo chu vi giữa lớp hoa lốp và lớp sợi bố. Lớp bố: Tạo nên kết cấu lớp cho lốp tạo thành lốp. Bố lốp gồm nhiều lớp dây lốp (các tấm lưới đặt song song) được ghép xen kẽ với với cao su. Ở các loại xe buýt, xe tải các dây lốp này thường được chế tạo bằng thép. Ở xe du lịch thì các dây lốp thường được chế tạo bằng nylông hoặc polyeste. Lốp bố phải có độ cứng cao để chịu được áp suất cao, nhưng nó cũng có độ mềm Lớp lót trong: Một lớp cao su tương tự như săm, nó được gắn vào vách trong của lốp.","anchor":"block-1781164047048-hgjz2k8uc"},{"id":"s1063","kind":"html","lesson":"8.1.1","title":"Cụm bánh xe · Lốp xe","text":"Dây mép lốp: Giữ chặt lốp vào vành.Thông số của lốp xe: Ký hiệu lốp xe theo Nga: D X B hoặc D X H (inch) Ký hiệu theo Châu Á và Châu Âu: 195/55 R16 87V Ký hiệu theo kiểu Mỹ: P195/55 R16 87V P: passenger (xe khách); LT: Tải nhẹ; C : Thương mại nhẹ; T: Tạm thời 195= B : Chiều rộng của lốp (mm); H/B = 55%: Tỷ lệ chiều cao/ Chiều rộng 15 = d (inch): Đường kính lắp vành bánh xe (larang) 87: chỉ số tại trọng tối đa (545kg) V: chỉ số tốc độ tối đa (240km/h) Code | J | K | L | M | N | O | P | Q | R | S | T | U | V | W | Y Tốc độ (Km/h) | 100 | 110 | 120 | 130 | 140 | 150 | 160 | 170 | 180 | 190 | 200 | 210 | 240 | 270 | 300 Code | 80 | 81 | 82 | 83 | 84 | 85 | 86 | 87 | 88 | 89 | 90 | 91 | 92 | 93 | 94 Tải (kg) | 450 | 462 | 475 | 487 | 500 | 515 | 530 | 545 | 560 | 580 | 600 | 615 | 630 | 650 | 670 Code | 95 | 96 | 97 | 98 | 99 | 100 | 101 | 102 | 103 | 104 | 105 |","anchor":"block-1781164047048-hgjz2k8uc"},{"id":"s1064","kind":"html","lesson":"8.1.1","title":"Cụm bánh xe · Lốp xe","text":"106 | 107 | 108 | Tải (kg) | 690 | 710 | 730 | 750 | 775 | 800 | 825 | 850 | 875 | 900 | 925 | 950 | 975 | 1000 | 2C: Mã nhà máy BT: Mã kích thước lốp xe 3AV: Mã lựa chọn 44: Tuần sản xuất 01: Năm sản xuất | Trước năm 2000, chỉ sử dụng 1 chữ số ( ví dụ: xx xx xxx 399, tuần 39 năm 1999) Trên gai lốp có vạch chỉ thị độ mòn mặt lốp. Nằm tại rãnh gai của mặt cạnh lốp với chiều cao vạch chỉ thị 1.6mm hoặc trên.","anchor":"block-1781164047048-hgjz2k8uc"},{"id":"s1065","kind":"lesson","lesson":"8.1.2","title":"Cụm bánh xe · Các kiểu hoa lốp","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự nhận diện hoa lốp."},{"id":"s1066","kind":"simulation","lesson":"8.1.2","title":"Trình tự nhận diện hoa lốp","text":"1. Quan sát hướng rãnh chính. Rãnh theo chu vi gợi ý kiểu sọc. 2. Quan sát vấu và rãnh ngang. Đối chiếu kiểu vấu và đặc điểm dùng trên đường không lát. 3. Kiểm tra dạng kết hợp. Xác định sọc kết hợp vấu nếu có hai dạng đặc trưng. 4. Kiểm tra chiều quay quy định. Hoa lốp định hướng phải được lắp theo chiều quy định."},{"id":"s1067","kind":"figure","lesson":"8.1.2","title":"Các kiểu hoa lốp — sơ đồ học tập biên soạn từ bài 8.1.2","text":"A. Kiểu sọc. Thường dùng trên đường lát phẳng và xe cao tốc theo bài. B. Kiểu vấu. Ưu tiên lực kéo trên đường không lát. C. Sọc kết hợp vấu. Kết hợp đặc điểm của hai dạng hoa lốp. D. Kiểu định hướng. Cần được lắp đúng chiều quay của lốp.","figure":{"image":"tuong_tac/diagrams/tread.svg","caption":"Các kiểu hoa lốp — sơ đồ học tập biên soạn từ bài 8.1.2"}},{"id":"s1068","kind":"part","lesson":"8.1.2","title":"Kiểu sọc","text":"Thường dùng trên đường lát phẳng và xe cao tốc theo bài.","keywords":["Kiểu sọc"],"figure":{"image":"tuong_tac/diagrams/tread.svg","caption":"Các kiểu hoa lốp — sơ đồ học tập biên soạn từ bài 8.1.2"}},{"id":"s1069","kind":"part","lesson":"8.1.2","title":"Kiểu vấu","text":"Ưu tiên lực kéo trên đường không lát.","keywords":["Kiểu vấu"],"figure":{"image":"tuong_tac/diagrams/tread.svg","caption":"Các kiểu hoa lốp — sơ đồ học tập biên soạn từ bài 8.1.2"}},{"id":"s1070","kind":"part","lesson":"8.1.2","title":"Sọc kết hợp vấu","text":"Kết hợp đặc điểm của hai dạng hoa lốp.","keywords":["Sọc kết hợp vấu"],"figure":{"image":"tuong_tac/diagrams/tread.svg","caption":"Các kiểu hoa lốp — sơ đồ học tập biên soạn từ bài 8.1.2"}},{"id":"s1071","kind":"part","lesson":"8.1.2","title":"Kiểu định hướng","text":"Cần được lắp đúng chiều quay của lốp.","keywords":["Kiểu định hướng"],"figure":{"image":"tuong_tac/diagrams/tread.svg","caption":"Các kiểu hoa lốp — sơ đồ học tập biên soạn từ bài 8.1.2"}},{"id":"s1072","kind":"figure","lesson":"8.1.2","title":"Hình 8.3. Hoa lốp (gai lốp)","text":"Hình 8.3. Hoa lốp (gai lốp)","anchor":"block-1781164177285-297atmy1t","figure":{"number":"8.3","caption":"Hình 8.3. Hoa lốp (gai lốp)"}},{"id":"s1073","kind":"html","lesson":"8.1.2","title":"Cụm bánh xe · Các kiểu hoa lốp","text":"Đa số, các xe ngày nay sử dụng lốp xe có hình dạng hoa văn đặc biệt, hình dạng này phụ thuộc vào kết cấu xe, điều kiện chuyển động của xe…Việc thiết kế gai đem đến những ưu điểm như thoát nhiệt tốt, bánh xe bám tốt mặt đường…","anchor":"block-1781164177285-297atmy1t"},{"id":"s1074","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · a. Kiểu sọc","text":"Gồm nhiều rãnh bố trí chạy song song với chu vi lốp xe.Kiểu rãnh này thường được sử dụng ở các loại xe cao tốc trên đường lát phẳng. Việc bố trí gai lốp kiểu sọc đem lại các ưu điểm: - Giảm lực cản lăn tác dụng lên lốp. - Giảm lực ngang tác dụng, đảm bảo ổn định ngang khi chuyển động.","anchor":"block-1781164198029-h58dxdyxw"},{"id":"s1075","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · b. Kiểu vấu","text":"Các rãnh được bố trí trí như hình vẽ, loại gai lốp này thường sử dụng khi xe chạy trên đường không lát phẳng. Loại gai lốp này có các đặc điểm sau: - Gai lốp dễ bị mòn và gây tiếng ồn.","anchor":"block-1781164237385-s34rew0ni"},{"id":"s1076","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · c. Kiểu vấu – sọc","text":"Loại này được kết hợp giữa kiểu sọc và kiểu vấu. Nó có thể giúp xe chuyển động trên cả 2 loại đường lát phẳng và không lát phẳng. - Các sọc chạy dọc đường tâm lốp làm giảm lực ngang tác dụng, nên giảm tối thiểu sự trượt ngang. - Các vấu làm tăng tính năng dẫn động và phanh. - Lực cản lăn lớn làm vấu dễ bị mòn.","anchor":"block-1781164261886-2btetbfcp"},{"id":"s1077","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · d. Kiểu khối","text":"Gai lốp được chia thành nhiều khối, giúp xe chuyển động tốt trên loại đường tuyết và được sử dụng ở loại bố tròn. - Tạo ra tính năng dẫn động và tính năng phanh tốt. - Giảm trượt ngang và trượt quay khi chạy trên đường tuyết và đường lầy lội. - Lốp nhanh mòn, có thể mòn không đều.","anchor":"block-1781164298496-aql262b6k"},{"id":"s1078","kind":"figure","lesson":"8.1.2","title":"Hình 8.4. Kiểu lốp định hướng theo chiều quay","text":"Hình 8.4. Kiểu lốp định hướng theo chiều quay","anchor":"block-1781164329550-krjasvr67","figure":{"number":"8.4","caption":"Hình 8.4. Kiểu lốp định hướng theo chiều quay"}},{"id":"s1079","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · e. Kiểu định hướng theo chiều quay","text":"Ở kiểu này, gai lốp được định hướng treo chiều quay của xe. Việc sử dụng kiểu gai theo chiều quay có các đặc điểm sau: - Cải thiện tính năng chuyển động trên mặt đường ẩm ướt. - Nếu như bố trí ngược chiều sẽ gây ra mòn lốp nhanh, gây ra tính hút nước của lốp.","anchor":"block-1781164329550-krjasvr67"},{"id":"s1080","kind":"figure","lesson":"8.1.2","title":"Hình 8.5. Sơ đồ biểu thị độ bền của lốp phụ thuộc vào áp suất, tải trọng và tốc độ","text":"Hình 8.5. Sơ đồ biểu thị độ bền của lốp phụ thuộc vào áp suất, tải trọng và tốc độ","anchor":"block-1781164370882-ee2h77p3l","figure":{"number":"8.5","caption":"Hình 8.5. Sơ đồ biểu thị độ bền của lốp phụ thuộc vào áp suất, tải trọng và tốc độ"}},{"id":"s1081","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · f. Độ mòn của lốp","text":"Độ mòn của lốp là sự tổn thất hoặc hư hỏng của gai lốp, bề mặt cao su của lốp do xuất hiện lực ma sát giữa lốp xe và mặt đường. Độ mòn lốp phụ thuộc vào các yếu tố. Qua đồ thị, có thể thấy áp suất lốp càng nhỏ thì độ mòn lốp càng tăng và ngược lại.(Hình 8.5a) - Tải tác dụng Qua đồ thị, có thể thấy tải càng lớn thì độ mòn lốp càng tăng.(Hình 8.5b) Khi tăng tốc độ, lực kéo, lực ly tâm và các lực tác dụng lên lốp tăng lên. Lực ly tâm có giá trị tỉ lệ thuận với tốc độ của xe, vì vậy khi tăng tốc các lực này tăng lên, đồng thời sự trượt sinh ra giữa lốp xe và mặt đường càng lớn. Kết quả, lốp xe nhanh bị mòn.","anchor":"block-1781164370882-ee2h77p3l"},{"id":"s1082","kind":"figure","lesson":"8.1.2","title":"Hình 8.6. Lốp đinh","text":"Hình 8.6. Lốp đinh","anchor":"block-1781164411209-srel5nmwq","figure":{"number":"8.6","caption":"Hình 8.6. Lốp đinh"}},{"id":"s1083","kind":"figure","lesson":"8.1.2","title":"Hình 8.7. Lốp đi đường tuyết","text":"Hình 8.7. Lốp đi đường tuyết","anchor":"block-1781164411209-srel5nmwq","figure":{"number":"8.7","caption":"Hình 8.7. Lốp đi đường tuyết"}},{"id":"s1084","kind":"figure","lesson":"8.1.2","title":"Hình 8.8. Lốp đi đường cát","text":"Hình 8.8. Lốp đi đường cát","anchor":"block-1781164411209-srel5nmwq","figure":{"number":"8.8","caption":"Hình 8.8. Lốp đi đường cát"}},{"id":"s1085","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · g. Kết cấu, đặc điểm, nguyên lý hoạt động một số loại lốp điển hình","text":"- Khả năng bám tốt trên đường tuyết vì các đinh có khả năng truyền lực bám tốt, trên gai lốp còn bố trí các đinh kim loại để đảm bảo chuyển động tốt trên đường băng cũng như đường tuyết. - Khả năng bám trên đường băng nhỏ. - Đa số các xe hiện nay không sử dụng lốp đinh, lí do khi sử dụng thì các đinh mau bị mòn, dễ làm hỏng mặt đường và gây ô nhiễm. - Để đảm bảo chuyển động trên đường tuyết, người ta thiết kế ở bề mặt lốp có nhiều các khối. - Các khối này cao và khoảng cách rộng hơn so với các lốp bình thường, bề rộng lớn hơn lốp bình thường 10% - 20%, rãnh của chúng cũng sâu hơn. - Nếu kiểu vấu được kết hợp với kiểu khối, kết quả sẽ tăng hiệu quả truyền lực. Nếu kết hợp với kiểu sọc sẽ giảm lực ngang tác dụng. - Tỉ lệ diện tích giữa bề mặt các vấu và diện tích tất cả các rãnh gọi là tỉ lệ diện tích tiếp xúc của lốp.","anchor":"block-1781164411209-srel5nmwq"},{"id":"s1086","kind":"html","lesson":"8.1.2","title":"Các kiểu hoa lốp · g. Kết cấu, đặc điểm, nguyên lý hoạt động một số loại lốp điển hình","text":"Lốp đi tuyết có tỉ lệ này nhỏ hơn lốp thường nên nó cải thiện được tính năng chuyển động trên đường tuyết. Lốp đi trên đường tuyết có các đặc điểm sau: - Tính kéo tốt, độ trượt bên nhỏ, ổn định lái tốt khi phanh. - Giảm sự rung động và tiếng ồn. - Do gai lốp có độ cứng không bằng lốp thường nên khi xe chạy trên đường với tốc độ cao, kết quả tính ổn định kém đi. Khi chạy trên đường tuyết, các vấu sẽ cám sâu xuống tuyết và nén chặt tuyết thành những lớp có hình dạng khối. Nhờ lực kéo, lốp sẽ chuyển động về phía trước nhờ vào việc tỳ lên các khối của tuyết. - Gai lốp thiết kế kiểu sọc, có rãnh tác dụng ngăn cản không cho phá vỡ lớp cát khi bánh xe chuyển động trên cát. - Làm tăng diện tích tiếp xúc giữa lốp và mặt đường khi áp suất lốp cao.","anchor":"block-1781164411209-srel5nmwq"},{"id":"s1087","kind":"lesson","lesson":"8.2.1","title":"Cụm bánh xe · Cấu tạo vành bánh xe","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự đọc thông số vành."},{"id":"s1088","kind":"simulation","lesson":"8.2.1","title":"Trình tự đọc thông số vành","text":"1. Đọc chiều rộng vành. Đối chiếu ký hiệu kích thước vành. 2. Đọc dạng mép của vành. Nhận diện dạng mép để ghép đúng loại lốp. 3. Đọc đường kính lắp lốp. So sánh đường kính vành với kích thước lắp của lốp. 4. Đối chiếu toàn bộ dạng vành. Vành cần cứng vững, phù hợp lốp và có tính cân bằng động tốt."},{"id":"s1089","kind":"figure","lesson":"8.2.1","title":"Thông số vành bánh xe — sơ đồ học tập biên soạn từ bài 8.2.1","text":"A. Chiều rộng vành. Một thông số kích thước lắp của vành trong hình ký hiệu. B. Dạng mép của vành. Đặc trưng hình dạng mép cần phù hợp với lốp. C. Đường kính lắp với lốp. Phải phù hợp với đường kính lắp của lốp. D. Kiểu vành đối xứng. Được chỉ ra trong hình ký hiệu vành của bài.","figure":{"image":"tuong_tac/diagrams/rim.svg","caption":"Thông số vành bánh xe — sơ đồ học tập biên soạn từ bài 8.2.1"}},{"id":"s1090","kind":"part","lesson":"8.2.1","title":"Chiều rộng vành","text":"Một thông số kích thước lắp của vành trong hình ký hiệu.","keywords":["Chiều rộng vành"],"figure":{"image":"tuong_tac/diagrams/rim.svg","caption":"Thông số vành bánh xe — sơ đồ học tập biên soạn từ bài 8.2.1"}},{"id":"s1091","kind":"part","lesson":"8.2.1","title":"Dạng mép của vành","text":"Đặc trưng hình dạng mép cần phù hợp với lốp.","keywords":["Dạng mép của vành"],"figure":{"image":"tuong_tac/diagrams/rim.svg","caption":"Thông số vành bánh xe — sơ đồ học tập biên soạn từ bài 8.2.1"}},{"id":"s1092","kind":"part","lesson":"8.2.1","title":"Đường kính lắp với lốp","text":"Phải phù hợp với đường kính lắp của lốp.","keywords":["Đường kính lắp với lốp"],"figure":{"image":"tuong_tac/diagrams/rim.svg","caption":"Thông số vành bánh xe — sơ đồ học tập biên soạn từ bài 8.2.1"}},{"id":"s1093","kind":"part","lesson":"8.2.1","title":"Kiểu vành đối xứng","text":"Được chỉ ra trong hình ký hiệu vành của bài.","keywords":["Kiểu vành đối xứng"],"figure":{"image":"tuong_tac/diagrams/rim.svg","caption":"Thông số vành bánh xe — sơ đồ học tập biên soạn từ bài 8.2.1"}},{"id":"s1094","kind":"html","lesson":"8.2.1","title":"Cụm bánh xe · Cấu tạo vành bánh xe","text":"Là bộ phận có chức năng giữ cho lốp có dạng profin theo yêu cầu, cố định bánh xe với moayơ đầu trục. Nó quyết định đến sự an toàn khi chuyển động, vì vậy nó phải đảm bảo các yếu tố sau: - Có độ cứng vững cao để chống đỡ lại tải trọng thẳng đứng và tải trọng ngang. - Chịu được lực kéo, lực phanh và các lực khác tác dụng lên nó. - Có khối lượng không lớn để đảm bảo chuyển động. - Chế tạo phù hợp với lốp và có tính cân bằng động tốt khi xe chạy ở tốt độ cao. Người ta ký hiệu vành bánh xe theo: - Ký hiệu theo hình dạng vánh: Vành đối xứng, không đối xứng, theo cấu trúc profin. Hiện nay, có 3 kiểu ký hiệu vành xe: + Theo tiêu chuẩn ISO hiện nay thì d1 được ghi lên đầu tiên. Thí dụ: 13 x 5 J – S: Vành đối xứng. + Kiểu vành đối xứng không có chữ S hoặc thay chữ S bằng chữ A.","anchor":"block-1781164522875-oo488p6ij"},{"id":"s1095","kind":"lesson","lesson":"8.2.2","title":"Cụm bánh xe · Liên kết giữa vành và moay ơ, vành bánh xe và lốp xe","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quan hệ định tâm và giữ chặt mối ghép."},{"id":"s1096","kind":"simulation","lesson":"8.2.2","title":"Quan hệ định tâm và giữ chặt mối ghép","text":"1. Định tâm mâm vành trên moay ơ. Mối ghép phải giữ đúng tâm cụm bánh. 2. Bu lông và ê cu tạo lực kẹp. Các bề mặt lắp được ép chặt nhờ mối ghép ren. 3. Mối ghép giữ chắc bằng ma sát. Mô men siết đúng quy định tạo lực kẹp phù hợp. 4. Vành giữ lốp khi cụm bánh làm việc. Liên kết phải chịu các tải tác dụng trong quá trình bánh xe làm việc."},{"id":"s1097","kind":"figure","lesson":"8.2.2","title":"Liên kết vành – moay ơ – lốp — sơ đồ học tập biên soạn từ bài 8.2.2","text":"A. Bu lông. Cùng ê cu tạo lực kẹp giữ bánh xe trên moay ơ. B. Ê cu định tâm. Mối ghép phải được siết đúng mô men quy định. C. Moay ơ. Tiếp nhận và định tâm mâm vành bánh xe. D. Vành bánh xe. Liên kết với moay ơ và lắp lốp tạo cụm bánh xe.","figure":{"image":"tuong_tac/diagrams/wheeljoint.svg","caption":"Liên kết vành – moay ơ – lốp — sơ đồ học tập biên soạn từ bài 8.2.2"}},{"id":"s1098","kind":"part","lesson":"8.2.2","title":"Bu lông","text":"Cùng ê cu tạo lực kẹp giữ bánh xe trên moay ơ.","keywords":["Bu lông"],"figure":{"image":"tuong_tac/diagrams/wheeljoint.svg","caption":"Liên kết vành – moay ơ – lốp — sơ đồ học tập biên soạn từ bài 8.2.2"}},{"id":"s1099","kind":"part","lesson":"8.2.2","title":"Ê cu định tâm","text":"Mối ghép phải được siết đúng mô men quy định.","keywords":["Ê cu định tâm"],"figure":{"image":"tuong_tac/diagrams/wheeljoint.svg","caption":"Liên kết vành – moay ơ – lốp — sơ đồ học tập biên soạn từ bài 8.2.2"}},{"id":"s1100","kind":"part","lesson":"8.2.2","title":"Moay ơ","text":"Tiếp nhận và định tâm mâm vành bánh xe.","keywords":["Moay ơ"],"figure":{"image":"tuong_tac/diagrams/wheeljoint.svg","caption":"Liên kết vành – moay ơ – lốp — sơ đồ học tập biên soạn từ bài 8.2.2"}},{"id":"s1101","kind":"part","lesson":"8.2.2","title":"Vành bánh xe","text":"Liên kết với moay ơ và lắp lốp tạo cụm bánh xe.","keywords":["Vành bánh xe"],"figure":{"image":"tuong_tac/diagrams/wheeljoint.svg","caption":"Liên kết vành – moay ơ – lốp — sơ đồ học tập biên soạn từ bài 8.2.2"}},{"id":"s1102","kind":"figure","lesson":"8.2.2","title":"Hình 8.10. Mối ghép giữa mâm và moay ơ nhờ mối ghép ren","text":"Hình 8.10. Mối ghép giữa mâm và moay ơ nhờ mối ghép ren","anchor":"block-1781164546340-d7vuvgror","figure":{"number":"8.10","caption":"Hình 8.10. Mối ghép giữa mâm và moay ơ nhờ mối ghép ren"}},{"id":"s1103","kind":"figure","lesson":"8.2.2","title":"Hình 8.11. Kết cấu vành dập dàn từ thép lá","text":"Hình 8.11. Kết cấu vành dập dàn từ thép lá","anchor":"block-1781164546340-d7vuvgror","figure":{"number":"8.11","caption":"Hình 8.11. Kết cấu vành dập dàn từ thép lá"}},{"id":"s1104","kind":"figure","lesson":"8.2.2","title":"Hình 8.12. Kết cấu vành đúc hợp kim nhôm","text":"Hình 8.12. Kết cấu vành đúc hợp kim nhôm","anchor":"block-1781164546340-d7vuvgror","figure":{"number":"8.12","caption":"Hình 8.12. Kết cấu vành đúc hợp kim nhôm"}},{"id":"s1105","kind":"html","lesson":"8.2.2","title":"Cụm bánh xe · Liên kết giữa vành và moay ơ, vành bánh xe và lốp xe","text":"Liên kết giữa vành và moay ơ bằng bu lông, ê cu định tâm, liên kết này đảm bảo cho giữ chặt và định tâm toàn bộ bánh xe trên moay ơ trong quá trình bánh xe làm việc. Các định vị và bắt chặt liên kết kiểu ren, đòi hỏi mô men siết chặt đúng quy định nhằn tạo nên ma sát giữ mâm vành và moay ơ. Các dạng mâm vành được chế tạo với hình dáng khác nhau, giúp cho mối ghép đảm bảo tốt chức năng.","anchor":"block-1781164546340-d7vuvgror"},{"id":"s1106","kind":"lesson","lesson":"8.2.3","title":"Cụm bánh xe · Cân bằng bánh xe","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích tác động của mất cân bằng bánh xe."},{"id":"s1107","kind":"note","lesson":"8.2.3","title":"Cân bằng và góc đặt bánh xe","text":"Cân bằng khối lượng bánh xe xử lý lực / mô men mất cân bằng khi quay; cân chỉnh camber, caster và độ chụm xử lý hình học dẫn hướng. Hai thao tác không thay thế nhau."},{"id":"s1108","kind":"simulation","lesson":"8.2.3","title":"Tác động của mất cân bằng bánh xe","text":"1. Cụm vành lắp lốp có điểm nặng. Khối lượng không đồng đều tạo mất cân bằng. 2. Bánh quay sinh tác động ly tâm. Điểm nặng gây rung khi cụm bánh quay. 3. Xác định cân bằng tĩnh và động. Cân bằng tĩnh xét đứng yên; cân bằng động xét khi quay. 4. Hiệu chỉnh phân bố khối lượng. Cân bằng cả cụm vành đã lắp lốp, không nhầm với hiệu chỉnh độ đảo hình học."},{"id":"s1109","kind":"figure","lesson":"8.2.3","title":"Hình 8.13 — Cân bằng bánh xe","text":"A. Điểm nặng. Khối lượng tập trung không đều gây lực ly tâm khi quay. B. Cân bằng tĩnh. Xét sự cân bằng khối lượng khi cụm bánh đứng yên. C. Cân bằng động. Xét sự cân bằng của cụm bánh khi quay, gồm tác động gây mô men rung.","figure":{"image":"content/resources/T1_image349.jpg","caption":"Hình 8.13 — Cân bằng bánh xe","number":"8.13"}},{"id":"s1110","kind":"part","lesson":"8.2.3","title":"Điểm nặng","text":"Khối lượng tập trung không đều gây lực ly tâm khi quay.","keywords":["Điểm nặng"],"figure":{"image":"content/resources/T1_image349.jpg","caption":"Hình 8.13 — Cân bằng bánh xe","number":"8.13"}},{"id":"s1111","kind":"part","lesson":"8.2.3","title":"Cân bằng tĩnh","text":"Xét sự cân bằng khối lượng khi cụm bánh đứng yên.","keywords":["Cân bằng tĩnh"],"figure":{"image":"content/resources/T1_image349.jpg","caption":"Hình 8.13 — Cân bằng bánh xe","number":"8.13"}},{"id":"s1112","kind":"part","lesson":"8.2.3","title":"Cân bằng động","text":"Xét sự cân bằng của cụm bánh khi quay, gồm tác động gây mô men rung.","keywords":["Cân bằng động"],"figure":{"image":"content/resources/T1_image349.jpg","caption":"Hình 8.13 — Cân bằng bánh xe","number":"8.13"}},{"id":"s1113","kind":"figure","lesson":"8.2.3","title":"Hình 8.13. cân bằng bánh xe","text":"Hình 8.13. cân bằng bánh xe","anchor":"block-1781164743360-royx024ce","figure":{"number":"8.13","caption":"Hình 8.13. cân bằng bánh xe"}},{"id":"s1114","kind":"html","lesson":"8.2.3","title":"Cụm bánh xe · Cân bằng bánh xe","text":"Độ đồng đều của lốp là sự đồng đều về trọng lượng, kích thước và độ cứngvững. Tuy nhiên, vì sự đồng đều về trọng lượng thường được gọi là sự cân bằng của bánh xe, và sự đồng đều về kích thước thường được gọi là độ đảo, nên độ đồng đều thường chỉ để nói độ đồng đều về sư cứng vững. Những điều này có ảnh hưởng đến tính năng dẫn động. Cần phải cân bằng các cụm bánh xe một cách chính xác để loại bỏ các rung động và thao tác này được gọi là cân bằng bánh xe. Việc cân bằng bánh xe liên quan đến việc cân bằng trọng lượng của cả cụm bánh xe, tức là vành xe có lắp lốp. Việc cân bằng bánh xe được chia thành “cân bằng tĩnh” (cân bằng khi cụm bánh xe đứng yên) và “cân bằng động” (cân bằng khi bánh xe quay).","anchor":"block-1781164743360-royx024ce"},{"id":"s1115","kind":"lesson","lesson":"8.2.4","title":"Cụm bánh xe · Đảo lốp","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự lựa chọn sơ đồ đảo lốp."},{"id":"s1116","kind":"note","lesson":"8.2.4","title":"Đảo lốp theo điều kiện lắp","text":"Không dùng một sơ đồ đảo lốp cho mọi xe. Phải xét lốp có chiều quay, lốp khác kích thước trước / sau, kiểu dẫn động và hướng dẫn của xe; kiểm tra áp suất và mô men siết theo tài liệu nhà sản xuất."},{"id":"s1117","kind":"simulation","lesson":"8.2.4","title":"Trình tự lựa chọn sơ đồ đảo lốp","text":"1. Kiểm tra kích thước lốp trước và sau. Nếu khác cỡ, không tự ý thay giữa trước và sau. 2. Kiểm tra chiều quay của lốp. Lốp có chiều quay xác định không đổi phải–trái theo tài liệu. 3. Chọn sơ đồ phù hợp kiểu xe. Đối chiếu sơ đồ đảo lốp và dạng dẫn động trong hình 8.14. 4. Luân chuyển theo sơ đồ đã chọn. Mục đích là giúp mức mòn lốp đồng đều hơn."},{"id":"s1118","kind":"figure","lesson":"8.2.4","title":"Điều kiện luân chuyển lốp — sơ đồ học tập biên soạn từ bài 8.2.4","text":"A. Tải trọng đặt lên lốp. Tải trọng khác nhau làm mức mòn lốp khác nhau. B. Lốp có chiều quay xác định. Không đổi giữa bên phải và bên trái theo lưu ý trong tài liệu. C. Lốp trước và sau khác cỡ. Không đổi trước–sau nếu cỡ lốp không phù hợp. D. Sơ đồ đảo lốp. Chọn sơ đồ trong bài phù hợp dạng dẫn động và loại lốp.","figure":{"image":"tuong_tac/diagrams/rotation.svg","caption":"Điều kiện luân chuyển lốp — sơ đồ học tập biên soạn từ bài 8.2.4"}},{"id":"s1119","kind":"part","lesson":"8.2.4","title":"Tải trọng đặt lên lốp","text":"Tải trọng khác nhau làm mức mòn lốp khác nhau.","keywords":["Tải trọng đặt lên lốp"],"figure":{"image":"tuong_tac/diagrams/rotation.svg","caption":"Điều kiện luân chuyển lốp — sơ đồ học tập biên soạn từ bài 8.2.4"}},{"id":"s1120","kind":"part","lesson":"8.2.4","title":"Lốp có chiều quay xác định","text":"Không đổi giữa bên phải và bên trái theo lưu ý trong tài liệu.","keywords":["Lốp có chiều quay xác định"],"figure":{"image":"tuong_tac/diagrams/rotation.svg","caption":"Điều kiện luân chuyển lốp — sơ đồ học tập biên soạn từ bài 8.2.4"}},{"id":"s1121","kind":"part","lesson":"8.2.4","title":"Lốp trước và sau khác cỡ","text":"Không đổi trước–sau nếu cỡ lốp không phù hợp.","keywords":["Lốp trước và sau khác cỡ"],"figure":{"image":"tuong_tac/diagrams/rotation.svg","caption":"Điều kiện luân chuyển lốp — sơ đồ học tập biên soạn từ bài 8.2.4"}},{"id":"s1122","kind":"part","lesson":"8.2.4","title":"Sơ đồ đảo lốp","text":"Chọn sơ đồ trong bài phù hợp dạng dẫn động và loại lốp.","keywords":["Sơ đồ đảo lốp"],"figure":{"image":"tuong_tac/diagrams/rotation.svg","caption":"Điều kiện luân chuyển lốp — sơ đồ học tập biên soạn từ bài 8.2.4"}},{"id":"s1123","kind":"figure","lesson":"8.2.4","title":"Hình 8.14. Sơ đồ đảo lốp xe","text":"Hình 8.14. Sơ đồ đảo lốp xe","anchor":"block-1781164778393-rwd515dpk","figure":{"number":"8.14","caption":"Hình 8.14. Sơ đồ đảo lốp xe"}},{"id":"s1124","kind":"html","lesson":"8.2.4","title":"Cụm bánh xe · Đảo lốp","text":"Vì tải trọng đặt lên các lốp trước và sau khác nhau, nên mức mòn cũng khác nhau. Do đó cần thường xuyên luân chuyển lốp để chúng mòn đều. Các lốp có chiều quay được xác định không được thay giữa bên phải và bên trái. Lốp xe loại cỡ trước và sau khác nhau thì không được thay thế giữa vịtrí trước và vị trí sau. Phương pháp luân chuyển lốp thay đổi theo kiểu xe và khu vực như Hình 8.14","anchor":"block-1781164778393-rwd515dpk"},{"id":"s1125","kind":"lesson","lesson":"9.1.1","title":"Hệ thống lái · Công dụng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Công dụng."},{"id":"s1126","kind":"simulation","lesson":"9.1.1","title":"Nguyên lý: Công dụng","text":"1. Người lái tạo yêu cầu đổi hướng. Vành tay lái nhận thao tác trực tiếp. 2. Truyền tới cơ cấu lái. Trục lái đưa chuyển động vào cơ cấu lái. 3. Dẫn động đổi góc bánh dẫn hướng. Các đòn dẫn động truyền tác động tới bánh. 4. Xe đi theo hướng được điều khiển. Hệ thống cần duy trì hướng ổn định và phản hồi phù hợp."},{"id":"s1127","kind":"figure","lesson":"9.1.1","title":"Hình 9.9 — Bố trí chung của hệ thống lái","text":"A. Vành tay lái. Nhận lực và chuyển động điều khiển của người lái. B. Trục lái. Nối vành tay lái với cơ cấu lái. C. Dẫn động lái. Truyền tác động của cơ cấu lái tới bánh xe dẫn hướng. D. Cơ cấu lái. Biến đổi lực và chuyển động từ trục lái.","figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1128","kind":"part","lesson":"9.1.1","title":"Vành tay lái","text":"Nhận lực và chuyển động điều khiển của người lái.","keywords":["Vành tay lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1129","kind":"part","lesson":"9.1.1","title":"Trục lái","text":"Nối vành tay lái với cơ cấu lái.","keywords":["Trục lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1130","kind":"part","lesson":"9.1.1","title":"Dẫn động lái","text":"Truyền tác động của cơ cấu lái tới bánh xe dẫn hướng.","keywords":["Dẫn động lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1131","kind":"part","lesson":"9.1.1","title":"Cơ cấu lái","text":"Biến đổi lực và chuyển động từ trục lái.","keywords":["Cơ cấu lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1132","kind":"lesson","lesson":"9.1.2","title":"Hệ thống lái · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân loại hệ thống lái."},{"id":"s1133","kind":"simulation","lesson":"9.1.2","title":"Trình tự phân loại hệ thống lái","text":"1. Xét vị trí vành tay lái. Phân biệt bố trí bên trái và bên phải. 2. Xét bộ truyền của cơ cấu lái. Xác định trục vít, con lăn, thanh răng hoặc dạng kết hợp. 3. Xét nguồn tạo trợ lực. Phân biệt dầu có áp với mô-tơ điện. 4. Kết luận theo từng tiêu chí. Không dùng tên loại trợ lực thay tên cơ cấu truyền."},{"id":"s1134","kind":"figure","lesson":"9.1.2","title":"Phân loại hệ thống lái — sơ đồ học tập biên soạn từ bài 9.1.2","text":"A. Bố trí vành tay lái. Tiêu chí vị trí người điều khiển và vành tay lái. B. Kết cấu cơ cấu lái. Tiêu chí kiểu bộ truyền của cơ cấu lái. C. Trợ lực thủy lực. Tiêu chí nguồn tạo lực trợ lái. D. Trợ lực điện. EPS sử dụng động cơ điện theo bài học.","figure":{"image":"tuong_tac/diagrams/steerclasses.svg","caption":"Phân loại hệ thống lái — sơ đồ học tập biên soạn từ bài 9.1.2"}},{"id":"s1135","kind":"part","lesson":"9.1.2","title":"Bố trí vành tay lái","text":"Tiêu chí vị trí người điều khiển và vành tay lái.","keywords":["Bố trí vành tay lái"],"figure":{"image":"tuong_tac/diagrams/steerclasses.svg","caption":"Phân loại hệ thống lái — sơ đồ học tập biên soạn từ bài 9.1.2"}},{"id":"s1136","kind":"part","lesson":"9.1.2","title":"Kết cấu cơ cấu lái","text":"Tiêu chí kiểu bộ truyền của cơ cấu lái.","keywords":["Kết cấu cơ cấu lái"],"figure":{"image":"tuong_tac/diagrams/steerclasses.svg","caption":"Phân loại hệ thống lái — sơ đồ học tập biên soạn từ bài 9.1.2"}},{"id":"s1137","kind":"part","lesson":"9.1.2","title":"Trợ lực thủy lực","text":"Tiêu chí nguồn tạo lực trợ lái.","keywords":["Trợ lực thủy lực"],"figure":{"image":"tuong_tac/diagrams/steerclasses.svg","caption":"Phân loại hệ thống lái — sơ đồ học tập biên soạn từ bài 9.1.2"}},{"id":"s1138","kind":"part","lesson":"9.1.2","title":"Trợ lực điện","text":"EPS sử dụng động cơ điện theo bài học.","keywords":["Trợ lực điện"],"figure":{"image":"tuong_tac/diagrams/steerclasses.svg","caption":"Phân loại hệ thống lái — sơ đồ học tập biên soạn từ bài 9.1.2"}},{"id":"s1139","kind":"lesson","lesson":"9.2.1","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít – bánh vít","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Cơ cấu lái kiểu trục vít - bánh ví."},{"id":"s1140","kind":"simulation","lesson":"9.2.1","title":"Nguyên lý: Cơ cấu lái kiểu trục vít - bánh ví","text":"1. Vành tay lái làm trục vít quay. Trục vít nhận chuyển động từ trục tay lái. 2. Trục vít ăn khớp bánh vít. Bộ truyền đổi tác động quay với tỷ số truyền của cơ cấu. 3. Trục đòn quay đứng chuyển động. Trục ra đưa tác động từ bánh vít tới đòn quay đứng. 4. Dẫn động tác động bánh dẫn hướng. Ma sát trượt lớn là nhược điểm của kiểu truyền được trình bày."},{"id":"s1141","kind":"figure","lesson":"9.2.1","title":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","text":"A. Trục vít. Nhận chuyển động quay từ trục tay lái. B. Bánh vít. Nhận chuyển động qua ăn khớp với trục vít. C. Trục đòn quay đứng. Đưa tác động từ bánh vít tới dẫn động lái.","figure":{"image":"nt/figures/t2-9-3.jpg","caption":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","number":"9.3"}},{"id":"s1142","kind":"part","lesson":"9.2.1","title":"Trục vít","text":"Nhận chuyển động quay từ trục tay lái.","keywords":["Trục vít"],"figure":{"image":"nt/figures/t2-9-3.jpg","caption":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","number":"9.3"}},{"id":"s1143","kind":"part","lesson":"9.2.1","title":"Bánh vít","text":"Nhận chuyển động qua ăn khớp với trục vít.","keywords":["Bánh vít"],"figure":{"image":"nt/figures/t2-9-3.jpg","caption":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","number":"9.3"}},{"id":"s1144","kind":"part","lesson":"9.2.1","title":"Trục đòn quay đứng","text":"Đưa tác động từ bánh vít tới dẫn động lái.","keywords":["Trục đòn quay đứng"],"figure":{"image":"nt/figures/t2-9-3.jpg","caption":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","number":"9.3"}},{"id":"s1145","kind":"lesson","lesson":"9.2.2","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít lõm - con lăn","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Cơ cấu lái kiểu trục vít lõm - con lăn."},{"id":"s1146","kind":"simulation","lesson":"9.2.2","title":"Nguyên lý: Cơ cấu lái kiểu trục vít lõm - con lăn","text":"1. Trục vít lõm quay. Trục vít dạng glô-bô-it nhận tác động từ người lái. 2. Con lăn ăn khớp và lăn theo ren. Tiếp xúc lăn giảm ma sát so với kiểu trục vít–bánh vít. 3. Giá con lăn tác động trục ra. Con lăn phối hợp với giá gắn trên trục đòn quay đứng. 4. Trục đòn quay đứng truyền ra dẫn động. Dẫn động tiếp nhận tác động để đổi góc bánh dẫn hướng."},{"id":"s1147","kind":"figure","lesson":"9.2.2","title":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","text":"A. Trục vít. Trục vít dạng glô-bô-it nhận chuyển động quay đầu vào. B. Con lăn. Ăn khớp với ren trục vít, thay tiếp xúc trượt bằng tiếp xúc lăn. C. Trục đòn quay đứng. Nhận tác động từ giá con lăn và truyền ra dẫn động lái.","figure":{"image":"nt/figures/t2-9-4.jpg","caption":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","number":"9.4"}},{"id":"s1148","kind":"part","lesson":"9.2.2","title":"Trục vít","text":"Trục vít dạng glô-bô-it nhận chuyển động quay đầu vào.","keywords":["Trục vít"],"figure":{"image":"nt/figures/t2-9-4.jpg","caption":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","number":"9.4"}},{"id":"s1149","kind":"part","lesson":"9.2.2","title":"Con lăn","text":"Ăn khớp với ren trục vít, thay tiếp xúc trượt bằng tiếp xúc lăn.","keywords":["Con lăn"],"figure":{"image":"nt/figures/t2-9-4.jpg","caption":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","number":"9.4"}},{"id":"s1150","kind":"part","lesson":"9.2.2","title":"Trục đòn quay đứng","text":"Nhận tác động từ giá con lăn và truyền ra dẫn động lái.","keywords":["Trục đòn quay đứng"],"figure":{"image":"nt/figures/t2-9-4.jpg","caption":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","number":"9.4"}},{"id":"s1151","kind":"lesson","lesson":"9.2.3","title":"Hệ thống lái · Cơ cấu lái kiểu bánh răng - thanh răng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Cơ cấu lái kiểu bánh răng - thanh răng."},{"id":"s1152","kind":"simulation","lesson":"9.2.3","title":"Nguyên lý: Cơ cấu lái kiểu bánh răng - thanh răng","text":"1. Bánh răng nhận chuyển động quay. Trục lái đưa chuyển động quay vào bánh răng. 2. Thanh răng dịch chuyển tịnh tiến. Ăn khớp biến chuyển động quay thành chuyển động tịnh tiến. 3. Đòn kéo truyền tác động. Đòn kéo và khớp nối đưa lực tới cam quay. 4. Bánh dẫn hướng đổi góc. Quan hệ hình học dẫn động cho phép bánh xe quay theo tác động lái."},{"id":"s1153","kind":"figure","lesson":"9.2.3","title":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","text":"A. Bánh răng. Nhận chuyển động quay từ trục lái. B. Thanh răng. Dịch chuyển tịnh tiến khi bánh răng quay. C. Đòn kéo. Truyền tác động từ thanh răng tới bánh xe dẫn hướng. D. Trụ đứng. Tạo trục quay cho bánh xe dẫn hướng theo sơ đồ.","figure":{"image":"nt/figures/t2-9-6.jpg","caption":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","number":"9.6"}},{"id":"s1154","kind":"part","lesson":"9.2.3","title":"Bánh răng","text":"Nhận chuyển động quay từ trục lái.","keywords":["Bánh răng"],"figure":{"image":"nt/figures/t2-9-6.jpg","caption":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","number":"9.6"}},{"id":"s1155","kind":"part","lesson":"9.2.3","title":"Thanh răng","text":"Dịch chuyển tịnh tiến khi bánh răng quay.","keywords":["Thanh răng"],"figure":{"image":"nt/figures/t2-9-6.jpg","caption":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","number":"9.6"}},{"id":"s1156","kind":"part","lesson":"9.2.3","title":"Đòn kéo","text":"Truyền tác động từ thanh răng tới bánh xe dẫn hướng.","keywords":["Đòn kéo"],"figure":{"image":"nt/figures/t2-9-6.jpg","caption":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","number":"9.6"}},{"id":"s1157","kind":"part","lesson":"9.2.3","title":"Trụ đứng","text":"Tạo trục quay cho bánh xe dẫn hướng theo sơ đồ.","keywords":["Trụ đứng"],"figure":{"image":"nt/figures/t2-9-6.jpg","caption":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","number":"9.6"}},{"id":"s1158","kind":"lesson","lesson":"9.2.4","title":"Hệ thống lái · Cơ cấu vít - đai ốc bi tuần hoàn","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Cơ cấu vít - đai ốc bi tuần hoàn."},{"id":"s1159","kind":"simulation","lesson":"9.2.4","title":"Nguyên lý: Cơ cấu vít - đai ốc bi tuần hoàn","text":"1. Trục vít quay. Chuyển động vào tác động hệ rãnh xoắn và các viên bi. 2. Bi lăn trong rãnh. Bi tuần hoàn thay ma sát trượt bằng ma sát lăn. 3. Đai ốc bi dịch chuyển. Đai ốc thực hiện chuyển động tịnh tiến theo trục vít. 4. Cung răng quay trục đòn quay đứng. Tác động từ đai ốc truyền tới cung răng và đầu ra."},{"id":"s1160","kind":"figure","lesson":"9.2.4","title":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","text":"A. Trục vít. Nhận chuyển động quay từ trục lái. B. Đai ốc bi. Dịch chuyển dọc trục nhờ các bi lăn trong rãnh. C. Viên bi. Thay ma sát trượt bằng ma sát lăn trong bộ truyền. D. Bánh răng (hình rẽ quạt). Nhận tác động từ đai ốc để quay trục đòn quay đứng.","figure":{"image":"nt/figures/t2-9-8.jpg","caption":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","number":"9.8"}},{"id":"s1161","kind":"part","lesson":"9.2.4","title":"Trục vít","text":"Nhận chuyển động quay từ trục lái.","keywords":["Trục vít"],"figure":{"image":"nt/figures/t2-9-8.jpg","caption":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","number":"9.8"}},{"id":"s1162","kind":"part","lesson":"9.2.4","title":"Đai ốc bi","text":"Dịch chuyển dọc trục nhờ các bi lăn trong rãnh.","keywords":["Đai ốc bi"],"figure":{"image":"nt/figures/t2-9-8.jpg","caption":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","number":"9.8"}},{"id":"s1163","kind":"part","lesson":"9.2.4","title":"Viên bi","text":"Thay ma sát trượt bằng ma sát lăn trong bộ truyền.","keywords":["Viên bi"],"figure":{"image":"nt/figures/t2-9-8.jpg","caption":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","number":"9.8"}},{"id":"s1164","kind":"part","lesson":"9.2.4","title":"Bánh răng (hình rẽ quạt)","text":"Nhận tác động từ đai ốc để quay trục đòn quay đứng.","keywords":["Bánh răng (hình rẽ quạt)"],"figure":{"image":"nt/figures/t2-9-8.jpg","caption":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","number":"9.8"}},{"id":"s1165","kind":"lesson","lesson":"9.3.1","title":"Hệ thống lái · Sơ đồ dẫn động lái","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Sơ đồ dẫn động lái."},{"id":"s1166","kind":"simulation","lesson":"9.3.1","title":"Nguyên lý: Sơ đồ dẫn động lái","text":"1. Vành tay lái nhận thao tác. Người lái tạo lực và chuyển động điều khiển. 2. Trục lái nối đến cơ cấu lái. Trục có thể liền hoặc gồm nhiều đoạn ghép nối. 3. Cơ cấu lái biến đổi tác động. Hộp giảm tốc làm việc theo tỷ số truyền thiết kế. 4. Dẫn động tới bánh xe dẫn hướng. Các đòn và khớp truyền tác động ra bánh."},{"id":"s1167","kind":"figure","lesson":"9.3.1","title":"Hình 9.9 — Bố trí chung của hệ thống lái","text":"A. Vành tay lái. Nhận lực và chuyển động điều khiển của người lái. B. Trục lái. Nối vành tay lái với cơ cấu lái. C. Dẫn động lái. Truyền tác động của cơ cấu lái tới bánh xe dẫn hướng. D. Cơ cấu lái. Biến đổi lực và chuyển động từ trục lái.","figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1168","kind":"part","lesson":"9.3.1","title":"Vành tay lái","text":"Nhận lực và chuyển động điều khiển của người lái.","keywords":["Vành tay lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1169","kind":"part","lesson":"9.3.1","title":"Trục lái","text":"Nối vành tay lái với cơ cấu lái.","keywords":["Trục lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1170","kind":"part","lesson":"9.3.1","title":"Dẫn động lái","text":"Truyền tác động của cơ cấu lái tới bánh xe dẫn hướng.","keywords":["Dẫn động lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1171","kind":"part","lesson":"9.3.1","title":"Cơ cấu lái","text":"Biến đổi lực và chuyển động từ trục lái.","keywords":["Cơ cấu lái"],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s1172","kind":"lesson","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Cấu tạo các chi tiết dẫn động lái."},{"id":"s1173","kind":"simulation","lesson":"9.3.2","title":"Nguyên lý: Cấu tạo các chi tiết dẫn động lái","text":"1. Vành tay lái đưa mô men vào trục. Liên kết vành tay lái và trục lái bằng then hoa hoặc bu lông theo bài. 2. Khớp chữ thập truyền giữa các đoạn. Các đoạn trục có thể lệch góc mà vẫn truyền được mô men. 3. Cơ cấu lái đưa tác động ra thanh kéo. Đầu ra của hộp lái liên kết với dẫn động. 4. Rô-tuyn thích ứng góc liên kết. Khớp cầu cho phép các đòn quay ở những mặt phẳng khác nhau."},{"id":"s1174","kind":"figure","lesson":"9.3.2","title":"Các chi tiết dẫn động lái — sơ đồ học tập biên soạn từ bài 9.3.2","text":"A. Vành tay lái. Nhận lực điều khiển trực tiếp từ người lái. B. Trục lái. Truyền mô men và có thể có nhiều đoạn nối khớp. C. Khớp chữ thập. Cho phép truyền mô men khi các đoạn trục không thẳng hàng. D. Rô-tuyn. Truyền lực trong khi góc giữa đòn và thanh kéo thay đổi.","figure":{"image":"tuong_tac/diagrams/steerparts.svg","caption":"Các chi tiết dẫn động lái — sơ đồ học tập biên soạn từ bài 9.3.2"}},{"id":"s1175","kind":"part","lesson":"9.3.2","title":"Vành tay lái","text":"Nhận lực điều khiển trực tiếp từ người lái.","keywords":["Vành tay lái"],"figure":{"image":"tuong_tac/diagrams/steerparts.svg","caption":"Các chi tiết dẫn động lái — sơ đồ học tập biên soạn từ bài 9.3.2"}},{"id":"s1176","kind":"part","lesson":"9.3.2","title":"Trục lái","text":"Truyền mô men và có thể có nhiều đoạn nối khớp.","keywords":["Trục lái"],"figure":{"image":"tuong_tac/diagrams/steerparts.svg","caption":"Các chi tiết dẫn động lái — sơ đồ học tập biên soạn từ bài 9.3.2"}},{"id":"s1177","kind":"part","lesson":"9.3.2","title":"Khớp chữ thập","text":"Cho phép truyền mô men khi các đoạn trục không thẳng hàng.","keywords":["Khớp chữ thập"],"figure":{"image":"tuong_tac/diagrams/steerparts.svg","caption":"Các chi tiết dẫn động lái — sơ đồ học tập biên soạn từ bài 9.3.2"}},{"id":"s1178","kind":"part","lesson":"9.3.2","title":"Rô-tuyn","text":"Truyền lực trong khi góc giữa đòn và thanh kéo thay đổi.","keywords":["Rô-tuyn"],"figure":{"image":"tuong_tac/diagrams/steerparts.svg","caption":"Các chi tiết dẫn động lái — sơ đồ học tập biên soạn từ bài 9.3.2"}},{"id":"s1179","kind":"lesson","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích các hướng quan sát góc đặt bánh xe."},{"id":"s1180","kind":"note","lesson":"9.3.3","title":"Chuẩn quan sát góc đặt bánh xe","text":"Camber: mặt phẳng bánh với phương thẳng đứng khi nhìn trước. Caster: trục quay lái với phương thẳng đứng khi nhìn bên. Góc nghiêng ngang trụ đứng xét khi nhìn trước. Độ chụm dương theo quy ước khoảng cách: khoảng cách phía trước nhỏ hơn phía sau, đo cùng độ cao; thông số mục tiêu phụ thuộc xe."},{"id":"s1181","kind":"simulation","lesson":"9.3.3","title":"Các hướng quan sát góc đặt bánh xe","text":"1. Nhìn từ trước để xét camber. Góc nghiêng ngang bánh xe là góc của mặt phẳng bánh với phương thẳng đứng. 2. Vẫn nhìn từ trước để xét trục đứng. Xét góc nghiêng ngang trục quay lái, khác với mặt phẳng bánh. 3. Nhìn từ bên để xét caster. Góc nghiêng dọc trục quay lái có vai trò ổn định hướng và hồi vị theo bài. 4. Nhìn từ trên để xét độ chụm. So sánh khoảng cách trước và sau của hai bánh dẫn hướng."},{"id":"s1182","kind":"figure","lesson":"9.3.3","title":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","text":"A. Góc camber. Góc nghiêng ngang của mặt phẳng bánh xe khi nhìn từ trước. B. Góc nghiêng ngang trục lái đứng. Góc nghiêng của trục quay lái khi nhìn từ trước. C. Góc caster. Góc nghiêng dọc của trục quay lái khi nhìn từ bên. D. Độ chụm. Quan hệ khoảng cách hai bánh ở phía trước và phía sau khi nhìn từ trên.","figure":{"image":"nt/figures/t2-9-23.jpg","caption":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","number":"9.23"}},{"id":"s1183","kind":"part","lesson":"9.3.3","title":"Góc camber","text":"Góc nghiêng ngang của mặt phẳng bánh xe khi nhìn từ trước.","keywords":["Góc camber"],"figure":{"image":"nt/figures/t2-9-23.jpg","caption":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","number":"9.23"}},{"id":"s1184","kind":"part","lesson":"9.3.3","title":"Góc nghiêng ngang trục lái đứng","text":"Góc nghiêng của trục quay lái khi nhìn từ trước.","keywords":["Góc nghiêng ngang trục lái đứng"],"figure":{"image":"nt/figures/t2-9-23.jpg","caption":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","number":"9.23"}},{"id":"s1185","kind":"part","lesson":"9.3.3","title":"Góc caster","text":"Góc nghiêng dọc của trục quay lái khi nhìn từ bên.","keywords":["Góc caster"],"figure":{"image":"nt/figures/t2-9-23.jpg","caption":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","number":"9.23"}},{"id":"s1186","kind":"part","lesson":"9.3.3","title":"Độ chụm","text":"Quan hệ khoảng cách hai bánh ở phía trước và phía sau khi nhìn từ trên.","keywords":["Độ chụm"],"figure":{"image":"nt/figures/t2-9-23.jpg","caption":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","number":"9.23"}},{"id":"s1187","kind":"lesson","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích dòng dầu và lực trợ lái."},{"id":"s1188","kind":"simulation","lesson":"9.4.1","title":"Dòng dầu và lực trợ lái","text":"1. Bơm dầu cung cấp nguồn có áp. Nguồn dầu trợ lực được đưa tới van phân phối. 2. Người lái tác động van phân phối. Van đổi đường dầu theo yêu cầu quay vòng. 3. Dầu tác động xi-lanh lực. Áp suất trên các khoang tạo lực hỗ trợ lái. 4. Lực trợ lực phối hợp dẫn động. Cơ cấu lái và xi-lanh lực phối hợp đưa tác động tới bánh xe."},{"id":"s1189","kind":"figure","lesson":"9.4.1","title":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","text":"A. Van phân phối. Điều khiển đường dầu tới các khoang xi-lanh lực. B. Cơ cấu lái. Biến đổi chuyển động cơ khí của người lái. C. Xi-lanh lực. Biến áp suất dầu thành lực trợ lái. D. Bơm dầu. Cung cấp dầu có áp cho mạch trợ lực.","figure":{"image":"nt/figures/t2-9-30.jpg","caption":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","number":"9.30"}},{"id":"s1190","kind":"part","lesson":"9.4.1","title":"Van phân phối","text":"Điều khiển đường dầu tới các khoang xi-lanh lực.","keywords":["Van phân phối"],"figure":{"image":"nt/figures/t2-9-30.jpg","caption":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","number":"9.30"}},{"id":"s1191","kind":"part","lesson":"9.4.1","title":"Cơ cấu lái","text":"Biến đổi chuyển động cơ khí của người lái.","keywords":["Cơ cấu lái"],"figure":{"image":"nt/figures/t2-9-30.jpg","caption":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","number":"9.30"}},{"id":"s1192","kind":"part","lesson":"9.4.1","title":"Xi-lanh lực","text":"Biến áp suất dầu thành lực trợ lái.","keywords":["Xi-lanh lực","xy lanh lực"],"figure":{"image":"nt/figures/t2-9-30.jpg","caption":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","number":"9.30"}},{"id":"s1193","kind":"part","lesson":"9.4.1","title":"Bơm dầu","text":"Cung cấp dầu có áp cho mạch trợ lực.","keywords":["Bơm dầu"],"figure":{"image":"nt/figures/t2-9-30.jpg","caption":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","number":"9.30"}},{"id":"s1194","kind":"lesson","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích thu nhận tín hiệu và tạo trợ lực EPS."},{"id":"s1195","kind":"simulation","lesson":"9.4.2","title":"Thu nhận tín hiệu và tạo trợ lực EPS","text":"1. Cảm biến nhận tác động người lái. Mô-men trên trục lái được nhận biết bởi cảm biến. 2. ECU nhận thêm tốc độ xe. ECU tính mức trợ lực phù hợp mô-men và tốc độ. 3. ECU điều khiển mô-tơ điện. Dòng điện được điều khiển để tạo mô men hỗ trợ. 4. Mô men trợ lực tác động cơ cấu lái. Khi chạy nhanh, mức hỗ trợ giảm theo nguyên lý trong bài."},{"id":"s1196","kind":"figure","lesson":"9.4.2","title":"Hình 9.37 — Sơ đồ trợ lực lái điện","text":"A. Cảm biến mô-men. Nhận biết tác động điều khiển của người lái trên trục lái. B. ECU. Nhận tín hiệu và tính toán lệnh trợ lực điện. C. Mô-tơ điện. Sinh mô men hỗ trợ thông qua bộ truyền. D. Cơ cấu lái. Đưa tác động tổng hợp tới bánh xe dẫn hướng.","figure":{"image":"nt/figures/t2-9-37.jpg","caption":"Hình 9.37 — Sơ đồ trợ lực lái điện","number":"9.37"}},{"id":"s1197","kind":"part","lesson":"9.4.2","title":"Cảm biến mô-men","text":"Nhận biết tác động điều khiển của người lái trên trục lái.","keywords":["Cảm biến mô-men"],"figure":{"image":"nt/figures/t2-9-37.jpg","caption":"Hình 9.37 — Sơ đồ trợ lực lái điện","number":"9.37"}},{"id":"s1198","kind":"part","lesson":"9.4.2","title":"ECU","text":"Nhận tín hiệu và tính toán lệnh trợ lực điện.","keywords":["ECU"],"figure":{"image":"nt/figures/t2-9-37.jpg","caption":"Hình 9.37 — Sơ đồ trợ lực lái điện","number":"9.37"}},{"id":"s1199","kind":"part","lesson":"9.4.2","title":"Mô-tơ điện","text":"Sinh mô men hỗ trợ thông qua bộ truyền.","keywords":["Mô-tơ điện"],"figure":{"image":"nt/figures/t2-9-37.jpg","caption":"Hình 9.37 — Sơ đồ trợ lực lái điện","number":"9.37"}},{"id":"s1200","kind":"part","lesson":"9.4.2","title":"Cơ cấu lái","text":"Đưa tác động tổng hợp tới bánh xe dẫn hướng.","keywords":["Cơ cấu lái"],"figure":{"image":"nt/figures/t2-9-37.jpg","caption":"Hình 9.37 — Sơ đồ trợ lực lái điện","number":"9.37"}},{"id":"s1201","kind":"lesson","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích điều khiển điện tử nguồn trợ lực thủy lực."},{"id":"s1202","kind":"note","lesson":"9.4.3","title":"Bổ sung: hệ thống lái không trục lái","text":"Tài liệu 2026 đã có mục riêng về Steer-by-Wire tại trang PDF 50–53. Lệnh lái và phản hồi cảm giác lái được tổ chức thành hai vòng điều khiển; đây là cấu trúc khác EPS còn giữ đường truyền cơ khí. Phương án dự phòng phụ thuộc thiết kế, không phải mọi SbW đều có ly hợp nối cơ khí."},{"id":"s1203","kind":"simulation","lesson":"9.4.3","title":"Điều khiển điện tử nguồn trợ lực thủy lực","text":"1. Cảm biến cung cấp trạng thái xe. Tốc độ và tác động lái đưa thông tin tới điều khiển. 2. ECU tính mức hỗ trợ. Yêu cầu trợ lực thay đổi theo điều kiện vận hành. 3. Điều khiển van hoặc bơm. Tùy kết cấu, lệnh tác động van điện từ hoặc bơm trợ lực. 4. Xi-lanh lực tạo trợ lái. Áp suất dầu tạo lực hỗ trợ, phân biệt với EPS tạo mô men bằng mô-tơ."},{"id":"s1204","kind":"simulation","lesson":"9.4.3","title":"Bổ sung 2026: hai vòng điều khiển của SbW","text":"1. Đo yêu cầu của người lái. Góc và mô men tại vành tay lái được đo; không suy thành đường truyền cơ khí tới bánh xe. 2. Điều khiển góc bánh xe. ECU điều khiển chấp hành theo góc yêu cầu và nhận phản hồi góc thực. 3. Tạo mô men phản hồi lái. Vòng tạo cảm giác lái được điều khiển đồng thời, sử dụng thông tin trạng thái xe. 4. Giám sát và dự phòng. Phương án dự phòng theo thiết kế cụ thể: nguồn, cảm biến, điều khiển và chấp hành; một số thiết kế có liên kết cơ khí dự phòng."},{"id":"s1205","kind":"figure","lesson":"9.4.3","title":"Trợ lực thủy lực điều khiển điện tử — sơ đồ học tập biên soạn từ bài 9.4.3","text":"A. Bộ điều khiển điện tử trợ lực lái (ECU). Tính lệnh điều chỉnh trợ lực dựa vào tín hiệu đầu vào. B. Van điện từ. Điều chỉnh mạch thủy lực theo lệnh điện tử. C. Bơm trợ lực. Có thể được điều khiển điện để thay đổi cấp nguồn theo kết cấu. D. Xi-lanh lực. Thủy lực vẫn tạo lực hỗ trợ tại cơ cấu chấp hành.","figure":{"image":"tuong_tac/diagrams/ehps.svg","caption":"Trợ lực thủy lực điều khiển điện tử — sơ đồ học tập biên soạn từ bài 9.4.3"}},{"id":"s1206","kind":"part","lesson":"9.4.3","title":"Bộ điều khiển điện tử trợ lực lái (ECU)","text":"Tính lệnh điều chỉnh trợ lực dựa vào tín hiệu đầu vào.","keywords":["Bộ điều khiển điện tử trợ lực lái (ECU)"],"figure":{"image":"tuong_tac/diagrams/ehps.svg","caption":"Trợ lực thủy lực điều khiển điện tử — sơ đồ học tập biên soạn từ bài 9.4.3"}},{"id":"s1207","kind":"part","lesson":"9.4.3","title":"Van điện từ","text":"Điều chỉnh mạch thủy lực theo lệnh điện tử.","keywords":["Van điện từ"],"figure":{"image":"tuong_tac/diagrams/ehps.svg","caption":"Trợ lực thủy lực điều khiển điện tử — sơ đồ học tập biên soạn từ bài 9.4.3"}},{"id":"s1208","kind":"part","lesson":"9.4.3","title":"Bơm trợ lực","text":"Có thể được điều khiển điện để thay đổi cấp nguồn theo kết cấu.","keywords":["Bơm trợ lực"],"figure":{"image":"tuong_tac/diagrams/ehps.svg","caption":"Trợ lực thủy lực điều khiển điện tử — sơ đồ học tập biên soạn từ bài 9.4.3"}},{"id":"s1209","kind":"part","lesson":"9.4.3","title":"Xi-lanh lực","text":"Thủy lực vẫn tạo lực hỗ trợ tại cơ cấu chấp hành.","keywords":["Xi-lanh lực","xy lanh lực"],"figure":{"image":"tuong_tac/diagrams/ehps.svg","caption":"Trợ lực thủy lực điều khiển điện tử — sơ đồ học tập biên soạn từ bài 9.4.3"}},{"id":"s1210","kind":"lesson","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích giảm tốc và giữ xe khi đỗ."},{"id":"s1211","kind":"simulation","lesson":"10.1.1","title":"Giảm tốc và giữ xe khi đỗ","text":"1. Người lái yêu cầu giảm tốc. Tác động phanh chính được đưa tới dẫn động. 2. Cơ cấu phanh tạo mô men cản. Mô men phanh chống lại sự quay của bánh xe. 3. Lốp truyền tác động với mặt đường. Tác động tại vết tiếp xúc làm xe giảm tốc. 4. Giữ xe khi đỗ bằng phanh đỗ. Chức năng giữ đứng yên khác với điều khiển giảm tốc khi đang chạy."},{"id":"s1212","kind":"figure","lesson":"10.1.1","title":"Công dụng hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.1","text":"A. Phanh chính. Đáp ứng yêu cầu điều khiển giảm tốc và dừng xe. B. Phanh đỗ. Giữ xe khi đỗ trên đường bằng hoặc trên dốc. C. Phanh chậm dần. Phối hợp giảm tải cho cơ cấu phanh khi xuống dốc dài. D. ABS. Hệ thống điều khiển hỗ trợ duy trì khả năng điều khiển khi phanh.","figure":{"image":"tuong_tac/diagrams/brakepurpose.svg","caption":"Công dụng hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.1"}},{"id":"s1213","kind":"part","lesson":"10.1.1","title":"Phanh chính","text":"Đáp ứng yêu cầu điều khiển giảm tốc và dừng xe.","keywords":["Phanh chính"],"figure":{"image":"tuong_tac/diagrams/brakepurpose.svg","caption":"Công dụng hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.1"}},{"id":"s1214","kind":"part","lesson":"10.1.1","title":"Phanh đỗ","text":"Giữ xe khi đỗ trên đường bằng hoặc trên dốc.","keywords":["Phanh đỗ"],"figure":{"image":"tuong_tac/diagrams/brakepurpose.svg","caption":"Công dụng hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.1"}},{"id":"s1215","kind":"part","lesson":"10.1.1","title":"Phanh chậm dần","text":"Phối hợp giảm tải cho cơ cấu phanh khi xuống dốc dài.","keywords":["Phanh chậm dần"],"figure":{"image":"tuong_tac/diagrams/brakepurpose.svg","caption":"Công dụng hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.1"}},{"id":"s1216","kind":"part","lesson":"10.1.1","title":"ABS","text":"Hệ thống điều khiển hỗ trợ duy trì khả năng điều khiển khi phanh.","keywords":["ABS"],"figure":{"image":"tuong_tac/diagrams/brakepurpose.svg","caption":"Công dụng hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.1"}},{"id":"s1217","kind":"lesson","lesson":"10.1.2","title":"Hệ thống phanh · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân loại hệ thống phanh."},{"id":"s1218","kind":"simulation","lesson":"10.1.2","title":"Trình tự phân loại hệ thống phanh","text":"1. Xét nhiệm vụ phanh. Phân biệt chính, đỗ và dự phòng. 2. Xét bề mặt tạo ma sát. Phân biệt tang trống với đĩa. 3. Xét phương pháp dẫn động. Nhận diện cơ khí, chất lỏng, khí nén hoặc liên hợp. 4. Xét phần điều khiển điện tử. Xác định các chức năng hỗ trợ như ABS theo tài liệu."},{"id":"s1219","kind":"figure","lesson":"10.1.2","title":"Phân loại hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.2","text":"A. Theo công dụng. Tiêu chí nhiệm vụ làm việc của hệ thống phanh. B. Theo cơ cấu phanh. Tiêu chí kết cấu tạo mô men phanh. C. Theo dẫn động. Tiêu chí phương pháp truyền tác động điều khiển. D. Theo mức điều khiển. Tiêu chí sự tham gia của các hệ thống điều khiển.","figure":{"image":"tuong_tac/diagrams/brakeclasses.svg","caption":"Phân loại hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.2"}},{"id":"s1220","kind":"part","lesson":"10.1.2","title":"Theo công dụng","text":"Tiêu chí nhiệm vụ làm việc của hệ thống phanh.","keywords":["Theo công dụng"],"figure":{"image":"tuong_tac/diagrams/brakeclasses.svg","caption":"Phân loại hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.2"}},{"id":"s1221","kind":"part","lesson":"10.1.2","title":"Theo cơ cấu phanh","text":"Tiêu chí kết cấu tạo mô men phanh.","keywords":["Theo cơ cấu phanh"],"figure":{"image":"tuong_tac/diagrams/brakeclasses.svg","caption":"Phân loại hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.2"}},{"id":"s1222","kind":"part","lesson":"10.1.2","title":"Theo dẫn động","text":"Tiêu chí phương pháp truyền tác động điều khiển.","keywords":["Theo dẫn động"],"figure":{"image":"tuong_tac/diagrams/brakeclasses.svg","caption":"Phân loại hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.2"}},{"id":"s1223","kind":"part","lesson":"10.1.2","title":"Theo mức điều khiển","text":"Tiêu chí sự tham gia của các hệ thống điều khiển.","keywords":["Theo mức điều khiển"],"figure":{"image":"tuong_tac/diagrams/brakeclasses.svg","caption":"Phân loại hệ thống phanh — sơ đồ học tập biên soạn từ bài 10.1.2"}},{"id":"s1224","kind":"lesson","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích phanh và nhả ở cơ cấu tang trống."},{"id":"s1225","kind":"simulation","lesson":"10.2.1","title":"Phanh và nhả ở cơ cấu tang trống","text":"1. Cam phanh nhận tác động. Trong hình 10.2, dẫn động làm cam phanh quay. 2. Guốc phanh dịch ra ngoài. Cam đẩy guốc và má phanh về phía mặt trong trống. 3. Ma sát tạo mô men phanh. Má phanh ép trống đang quay, chống lại chuyển động bánh xe. 4. Lò xo hồi vị kéo guốc về. Khi thôi phanh, lò xo kéo guốc về và khôi phục khe hở."},{"id":"s1226","kind":"figure","lesson":"10.2.1","title":"Hình 10.2 — Cơ cấu phanh tang trống","text":"A. Mâm phanh. Giá cố định để lắp các chi tiết của cơ cấu phanh. B. Guốc phanh. Mang má phanh áp sát mặt trong trống phanh khi phanh. C. Trống phanh. Phần quay cùng bánh xe, tiếp xúc với má phanh. D. Cam phanh. Đẩy guốc phanh ra theo sơ đồ dẫn động bằng cam. E. Lò xo hồi vị. Kéo guốc phanh về sau khi thôi tác động phanh.","figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s1227","kind":"part","lesson":"10.2.1","title":"Mâm phanh","text":"Giá cố định để lắp các chi tiết của cơ cấu phanh.","keywords":["Mâm phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s1228","kind":"part","lesson":"10.2.1","title":"Guốc phanh","text":"Mang má phanh áp sát mặt trong trống phanh khi phanh.","keywords":["Guốc phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s1229","kind":"part","lesson":"10.2.1","title":"Trống phanh","text":"Phần quay cùng bánh xe, tiếp xúc với má phanh.","keywords":["Trống phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s1230","kind":"part","lesson":"10.2.1","title":"Cam phanh","text":"Đẩy guốc phanh ra theo sơ đồ dẫn động bằng cam.","keywords":["Cam phanh"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s1231","kind":"part","lesson":"10.2.1","title":"Lò xo hồi vị","text":"Kéo guốc phanh về sau khi thôi tác động phanh.","keywords":["Lò xo hồi vị"],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s1232","kind":"lesson","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích tạo lực ép và hồi vị của phanh đĩa."},{"id":"s1233","kind":"note","lesson":"10.2.2","title":"Hồi vị ở phanh đĩa","text":"Khe hở làm việc rất nhỏ được khôi phục chủ yếu nhờ biến dạng hồi phục của phớt tiết diện vuông và đặc điểm cụm phanh. Không mô tả phanh đĩa có lò xo kéo guốc như phanh tang trống."},{"id":"s1234","kind":"simulation","lesson":"10.2.2","title":"Tạo lực ép và hồi vị của phanh đĩa","text":"1. Dầu có áp tác động pít-tông. Pít-tông trong cụm xi-lanh tạo lực ép lên má phanh. 2. Hai má ép hai mặt đĩa. Ở càng di động, phản lực làm càng trượt để ép má phía đối diện. 3. Ma sát cản đĩa đang quay. Đĩa gắn với moay-ơ và quay cùng bánh xe. 4. Phớt đàn hồi góp phần hồi vị. Khi áp suất giảm, biến dạng đàn hồi giúp pít-tông hồi một phần để tạo khe hở."},{"id":"s1235","kind":"figure","lesson":"10.2.2","title":"Hình 10.18 — Cấu tạo phanh đĩa","text":"A. Má phanh. Tạo bề mặt ma sát với hai mặt đĩa phanh. B. Giá đỡ xi-lanh. Chứa pít-tông và đỡ cụm tác động phanh. C. Vít xả. Dùng để xả khí khỏi cụm xi-lanh khi bảo dưỡng. D. Đĩa phanh. Quay cùng bánh xe và tạo mặt ma sát với má phanh.","figure":{"image":"nt/figures/t2-10-18.jpg","caption":"Hình 10.18 — Cấu tạo phanh đĩa","number":"10.18"}},{"id":"s1236","kind":"part","lesson":"10.2.2","title":"Má phanh","text":"Tạo bề mặt ma sát với hai mặt đĩa phanh.","keywords":["Má phanh"],"figure":{"image":"nt/figures/t2-10-18.jpg","caption":"Hình 10.18 — Cấu tạo phanh đĩa","number":"10.18"}},{"id":"s1237","kind":"part","lesson":"10.2.2","title":"Giá đỡ xi-lanh","text":"Chứa pít-tông và đỡ cụm tác động phanh.","keywords":["Giá đỡ xi-lanh","Giá đỡ xy lanh"],"figure":{"image":"nt/figures/t2-10-18.jpg","caption":"Hình 10.18 — Cấu tạo phanh đĩa","number":"10.18"}},{"id":"s1238","kind":"part","lesson":"10.2.2","title":"Vít xả","text":"Dùng để xả khí khỏi cụm xi-lanh khi bảo dưỡng.","keywords":["Vít xả"],"figure":{"image":"nt/figures/t2-10-18.jpg","caption":"Hình 10.18 — Cấu tạo phanh đĩa","number":"10.18"}},{"id":"s1239","kind":"part","lesson":"10.2.2","title":"Đĩa phanh","text":"Quay cùng bánh xe và tạo mặt ma sát với má phanh.","keywords":["Đĩa phanh"],"figure":{"image":"nt/figures/t2-10-18.jpg","caption":"Hình 10.18 — Cấu tạo phanh đĩa","number":"10.18"}},{"id":"s1240","kind":"lesson","lesson":"10.3.1","title":"Hệ thống phanh · Dẫn động bằng cơ khí","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nguyên lý: Dẫn động bằng cơ khí."},{"id":"s1241","kind":"simulation","lesson":"10.3.1","title":"Nguyên lý: Dẫn động bằng cơ khí","text":"1. Người lái tác động bàn đạp. Bàn đạp làm quay trục và đòn quay. 2. Đòn dẫn động truyền lực. Các đòn và thanh kéo đưa lực tới trục cam. 3. Cam phanh quay và mở guốc. Cam biến tác động dẫn động thành dịch chuyển của guốc. 4. Guốc áp sát trống phanh. Ma sát tạo mô men phanh; phanh đỗ dùng cơ cấu giữ theo kết cấu."},{"id":"s1242","kind":"figure","lesson":"10.3.1","title":"Hình 10.28 — Dẫn động phanh cơ khí","text":"A. Bàn đạp phanh. Nhận lực điều khiển từ người lái. B. Đòn dẫn động. Truyền lực giữa các đòn quay. C. Cam phanh. Đẩy các guốc phanh áp sát trống phanh. D. Guốc phanh. Tạo lực ma sát với mặt trong trống phanh.","figure":{"image":"nt/figures/t2-10-28.jpg","caption":"Hình 10.28 — Dẫn động phanh cơ khí","number":"10.28"}},{"id":"s1243","kind":"part","lesson":"10.3.1","title":"Bàn đạp phanh","text":"Nhận lực điều khiển từ người lái.","keywords":["Bàn đạp phanh"],"figure":{"image":"nt/figures/t2-10-28.jpg","caption":"Hình 10.28 — Dẫn động phanh cơ khí","number":"10.28"}},{"id":"s1244","kind":"part","lesson":"10.3.1","title":"Đòn dẫn động","text":"Truyền lực giữa các đòn quay.","keywords":["Đòn dẫn động"],"figure":{"image":"nt/figures/t2-10-28.jpg","caption":"Hình 10.28 — Dẫn động phanh cơ khí","number":"10.28"}},{"id":"s1245","kind":"part","lesson":"10.3.1","title":"Cam phanh","text":"Đẩy các guốc phanh áp sát trống phanh.","keywords":["Cam phanh"],"figure":{"image":"nt/figures/t2-10-28.jpg","caption":"Hình 10.28 — Dẫn động phanh cơ khí","number":"10.28"}},{"id":"s1246","kind":"part","lesson":"10.3.1","title":"Guốc phanh","text":"Tạo lực ma sát với mặt trong trống phanh.","keywords":["Guốc phanh"],"figure":{"image":"nt/figures/t2-10-28.jpg","caption":"Hình 10.28 — Dẫn động phanh cơ khí","number":"10.28"}},{"id":"s1247","kind":"lesson","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích truyền tác động bằng áp suất chất lỏng."},{"id":"s1248","kind":"note","lesson":"10.3.2","title":"Áp suất, lực và hành trình","text":"Quan hệ gần đúng F = pA giúp phân tích khuếch đại lực theo diện tích pít-tông. Lực tăng kèm thay đổi hành trình / thể tích dịch chuyển; không tạo thêm năng lượng. Trợ lực chân không và cơ cấu điều hòa lực phanh phải được phân biệt với xi-lanh chính."},{"id":"s1249","kind":"simulation","lesson":"10.3.2","title":"Truyền tác động bằng áp suất chất lỏng","text":"1. Bàn đạp tác động xi-lanh chính. Lực người lái đẩy pít-tông trong xi-lanh chính. 2. Áp suất truyền qua đường ống. Chất lỏng có áp truyền tác động tới các xi-lanh công tác. 3. Xi-lanh công tác tác động guốc. Áp suất biến thành lực ép tại cơ cấu phanh bánh xe. 4. Nhả bàn đạp, hệ thống hồi vị. Áp suất giảm, cơ cấu phanh hồi về; khí lẫn trong đường dầu làm tăng tính nén."},{"id":"s1250","kind":"figure","lesson":"10.3.2","title":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","text":"A. Bàn đạp. Truyền lực người lái tới cần đẩy pít-tông. B. Xi-lanh chính. Biến lực bàn đạp thành áp suất chất lỏng. C. Đường ống dẫn. Truyền áp suất chất lỏng tới cơ cấu phanh. D. Xi-lanh công tác. Biến áp suất chất lỏng thành lực tác động guốc phanh.","figure":{"image":"nt/figures/t2-10-34.jpg","caption":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","number":"10.34"}},{"id":"s1251","kind":"part","lesson":"10.3.2","title":"Bàn đạp","text":"Truyền lực người lái tới cần đẩy pít-tông.","keywords":["Bàn đạp"],"figure":{"image":"nt/figures/t2-10-34.jpg","caption":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","number":"10.34"}},{"id":"s1252","kind":"part","lesson":"10.3.2","title":"Xi-lanh chính","text":"Biến lực bàn đạp thành áp suất chất lỏng.","keywords":["Xi-lanh chính","xy lanh chính"],"figure":{"image":"nt/figures/t2-10-34.jpg","caption":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","number":"10.34"}},{"id":"s1253","kind":"part","lesson":"10.3.2","title":"Đường ống dẫn","text":"Truyền áp suất chất lỏng tới cơ cấu phanh.","keywords":["Đường ống dẫn"],"figure":{"image":"nt/figures/t2-10-34.jpg","caption":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","number":"10.34"}},{"id":"s1254","kind":"part","lesson":"10.3.2","title":"Xi-lanh công tác","text":"Biến áp suất chất lỏng thành lực tác động guốc phanh.","keywords":["Xi-lanh công tác","xy lanh công tác"],"figure":{"image":"nt/figures/t2-10-34.jpg","caption":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","number":"10.34"}},{"id":"s1255","kind":"lesson","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nạp khí, tác động phanh và xả khí."},{"id":"s1256","kind":"note","lesson":"10.3.3","title":"Phanh công tác và bầu tích năng","text":"Bầu phanh công tác nhận khí để tạo lực phanh. Với phần lò xo tích năng dùng cho phanh dừng trong ví dụ, khí nén giải phóng lực lò xo để nhả phanh; mất áp có thể làm phanh tác dụng. Không áp dụng chiều tác động của bầu công tác cho mọi phần tử khí nén."},{"id":"s1257","kind":"simulation","lesson":"10.3.3","title":"Nạp khí, tác động phanh và xả khí","text":"1. Máy nén nạp các bình khí. Khí có áp được tích trữ để cung cấp năng lượng phanh. 2. Bàn đạp điều khiển van phanh tổng. Van điều khiển lượng khí cấp tới bầu phanh. 3. Bầu phanh tạo lực cơ khí. Màng hoặc pít-tông nhận áp suất khí để tác động cơ cấu phanh. 4. Thôi phanh, khí từ bầu được xả. Van mở đường xả, lò xo hồi vị đưa cơ cấu về."},{"id":"s1258","kind":"figure","lesson":"10.3.3","title":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","text":"A. Máy nén khí. Tạo nguồn không khí nén cho hệ thống. B. Bình khí. Tích trữ năng lượng khí nén. C. Van phanh tổng. Điều khiển cấp và xả khí theo thao tác bàn đạp. D. Bầu phanh. Biến áp suất khí thành lực cơ khí tác động phanh.","figure":{"image":"nt/figures/t2-10-46.jpg","caption":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","number":"10.46"}},{"id":"s1259","kind":"part","lesson":"10.3.3","title":"Máy nén khí","text":"Tạo nguồn không khí nén cho hệ thống.","keywords":["Máy nén khí"],"figure":{"image":"nt/figures/t2-10-46.jpg","caption":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","number":"10.46"}},{"id":"s1260","kind":"part","lesson":"10.3.3","title":"Bình khí","text":"Tích trữ năng lượng khí nén.","keywords":["Bình khí"],"figure":{"image":"nt/figures/t2-10-46.jpg","caption":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","number":"10.46"}},{"id":"s1261","kind":"part","lesson":"10.3.3","title":"Van phanh tổng","text":"Điều khiển cấp và xả khí theo thao tác bàn đạp.","keywords":["Van phanh tổng"],"figure":{"image":"nt/figures/t2-10-46.jpg","caption":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","number":"10.46"}},{"id":"s1262","kind":"part","lesson":"10.3.3","title":"Bầu phanh","text":"Biến áp suất khí thành lực cơ khí tác động phanh.","keywords":["Bầu phanh"],"figure":{"image":"nt/figures/t2-10-46.jpg","caption":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","number":"10.46"}},{"id":"s1263","kind":"lesson","lesson":"10.3.4","title":"Hệ thống phanh · Dẫn động kết hợp thuỷ lực - khí nén","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích chuyển tác động khí nén sang thủy lực."},{"id":"s1264","kind":"simulation","lesson":"10.3.4","title":"Chuyển tác động khí nén sang thủy lực","text":"1. Van phân phối cấp khí. Khí từ bình được đưa tới phần xi-lanh khí nén. 2. Pít-tông khí tạo lực đẩy. Pít-tông khí nén qua thanh đẩy tác động phần chất lỏng. 3. Pít-tông chất lỏng tạo áp suất. Xi-lanh chất lỏng tạo áp suất đưa tới mạch phanh bánh xe. 4. Chất lỏng tác động cơ cấu phanh. Dạng truyền cuối cùng tới cơ cấu phanh trong sơ đồ là thủy lực."},{"id":"s1265","kind":"figure","lesson":"10.3.4","title":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","text":"A. Máy nén khí. Cấp nguồn khí nén cho hệ thống. B. Bình khí. Tích trữ khí nén. C. Van phân phối. Điều khiển khí nén tới cụm xi-lanh kép. D. Cụm xi-lanh kép. Biến tác động khí nén thành áp suất chất lỏng. E. Đường ống dẫn chất lỏng. Truyền áp suất thủy lực tới cơ cấu phanh.","figure":{"image":"nt/figures/t2-10-55.jpg","caption":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","number":"10.55"}},{"id":"s1266","kind":"part","lesson":"10.3.4","title":"Máy nén khí","text":"Cấp nguồn khí nén cho hệ thống.","keywords":["Máy nén khí"],"figure":{"image":"nt/figures/t2-10-55.jpg","caption":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","number":"10.55"}},{"id":"s1267","kind":"part","lesson":"10.3.4","title":"Bình khí","text":"Tích trữ khí nén.","keywords":["Bình khí"],"figure":{"image":"nt/figures/t2-10-55.jpg","caption":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","number":"10.55"}},{"id":"s1268","kind":"part","lesson":"10.3.4","title":"Van phân phối","text":"Điều khiển khí nén tới cụm xi-lanh kép.","keywords":["Van phân phối"],"figure":{"image":"nt/figures/t2-10-55.jpg","caption":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","number":"10.55"}},{"id":"s1269","kind":"part","lesson":"10.3.4","title":"Cụm xi-lanh kép","text":"Biến tác động khí nén thành áp suất chất lỏng.","keywords":["Cụm xi-lanh kép","Cụm xy lanh kép"],"figure":{"image":"nt/figures/t2-10-55.jpg","caption":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","number":"10.55"}},{"id":"s1270","kind":"part","lesson":"10.3.4","title":"Đường ống dẫn chất lỏng","text":"Truyền áp suất thủy lực tới cơ cấu phanh.","keywords":["Đường ống dẫn chất lỏng"],"figure":{"image":"nt/figures/t2-10-55.jpg","caption":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","number":"10.55"}},{"id":"s1271","kind":"lesson","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích phát hiện trạng thái và điều chỉnh ABS."},{"id":"s1272","kind":"note","lesson":"10.3.5","title":"ABS, FCW, AEB và các chức năng liên quan","text":"ABS điều chỉnh áp suất dựa trên xu hướng bó cứng; ba trạng thái tăng / giữ / giảm được lựa chọn theo tín hiệu, không phải chu trình cố định bắt buộc. Với mạch thủy lực hai van thường gặp: tăng = van nạp mở, van xả đóng; giữ = cả hai đóng; giảm = van nạp đóng, van xả mở. Sơ đồ khí nén có đường khí và cơ cấu khác, xem chế độ riêng. FCW cảnh báo nguy cơ va chạm; AEB có thể tự tạo yêu cầu phanh. EBD, BA, EPB có mục tiêu riêng, không phải tên khác của ABS."},{"id":"s1273","kind":"simulation","lesson":"10.3.5","title":"ABS thủy lực: nhận tín hiệu và điều chỉnh áp suất","text":"1. Cảm biến cung cấp tốc độ bánh xe. ECU nhận trạng thái quay bánh để phát hiện xu hướng bó cứng. 2. Giữ áp khi cần hạn chế tăng phanh. Bộ chấp hành đóng các đường cần thiết để giữ áp suất ở cơ cấu phanh. 3. Giảm áp khi bánh có xu hướng bó cứng. Đường giảm áp được mở theo lệnh để bánh phục hồi tốc độ quay. 4. Tăng áp trở lại khi điều kiện cho phép. Chu trình tăng, giữ, giảm được điều khiển lặp lại theo trạng thái bánh xe."},{"id":"s1274","kind":"simulation","lesson":"10.3.5","title":"ABS khí nén: tăng – giữ – giảm áp","text":"1. Tăng áp tại bầu phanh. Bộ điều biến mở đường khí từ nguồn điều khiển tới bầu; đường xả đóng. Áp suất bầu tăng theo yêu cầu phanh. 2. Giữ áp tại bầu phanh. Đường cấp và đường xả đều đóng, cô lập thể tích khí trong bầu. 3. Giảm áp tại bầu phanh. Đường cấp đóng, đường xả từ bầu ra khí trời mở để giảm lực phanh. Lệnh tiếp theo phụ thuộc trạng thái bánh xe."},{"id":"s1275","kind":"figure","lesson":"10.3.5","title":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","text":"A. Cảm biến tốc độ. Cung cấp thông tin tốc độ quay bánh xe. B. Xi-lanh chính. Tạo áp suất phanh do người lái tác động. C. ECU điều khiển. Xử lý trạng thái bánh xe và phát lệnh điều chỉnh. D. Bộ chấp hành thủy lực. Thực hiện tăng, giữ hoặc giảm áp suất phanh theo lệnh.","figure":{"image":"nt/figures/t2-10-58.jpg","caption":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","number":"10.58"}},{"id":"s1276","kind":"part","lesson":"10.3.5","title":"Cảm biến tốc độ","text":"Cung cấp thông tin tốc độ quay bánh xe.","keywords":["Cảm biến tốc độ"],"figure":{"image":"nt/figures/t2-10-58.jpg","caption":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","number":"10.58"}},{"id":"s1277","kind":"part","lesson":"10.3.5","title":"Xi-lanh chính","text":"Tạo áp suất phanh do người lái tác động.","keywords":["Xi-lanh chính","xy lanh chính"],"figure":{"image":"nt/figures/t2-10-58.jpg","caption":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","number":"10.58"}},{"id":"s1278","kind":"part","lesson":"10.3.5","title":"ECU điều khiển","text":"Xử lý trạng thái bánh xe và phát lệnh điều chỉnh.","keywords":["ECU điều khiển"],"figure":{"image":"nt/figures/t2-10-58.jpg","caption":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","number":"10.58"}},{"id":"s1279","kind":"part","lesson":"10.3.5","title":"Bộ chấp hành thủy lực","text":"Thực hiện tăng, giữ hoặc giảm áp suất phanh theo lệnh.","keywords":["Bộ chấp hành thủy lực"],"figure":{"image":"nt/figures/t2-10-58.jpg","caption":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","number":"10.58"}},{"id":"s1280","kind":"lesson","lesson":"11.1.1","title":"Hệ thống treo · Công dụng","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích phối hợp đàn hồi, dẫn hướng và giảm chấn."},{"id":"s1281","kind":"simulation","lesson":"11.1.1","title":"Phối hợp đàn hồi, dẫn hướng và giảm chấn","text":"1. Bánh xe gặp kích động mặt đường. Dao động bắt đầu ở phần bánh và cầu xe. 2. Bộ phận đàn hồi biến dạng. Lò xo thu nhận năng lượng biến dạng và đỡ tải. 3. Bộ phận dẫn hướng truyền lực. Dẫn hướng truyền lực dọc, ngang và mô men, xác định quỹ đạo bánh. 4. Giảm chấn tiêu tán năng lượng. Giảm chấn biến năng lượng dao động thành nhiệt để dao động giảm nhanh."},{"id":"s1282","kind":"figure","lesson":"11.1.1","title":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","text":"A. Lò xo xoắn. Đàn hồi theo hành trình biến dạng, đỡ tải trọng thẳng đứng. B. Giảm chấn. Tiêu tán năng lượng dao động thành nhiệt. C. Đòn trên. Tham gia cơ cấu dẫn hướng bánh xe. D. Đòn dưới. Tham gia truyền lực và xác định quỹ đạo bánh xe.","figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1283","kind":"part","lesson":"11.1.1","title":"Lò xo xoắn","text":"Đàn hồi theo hành trình biến dạng, đỡ tải trọng thẳng đứng.","keywords":["Lò xo xoắn"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1284","kind":"part","lesson":"11.1.1","title":"Giảm chấn","text":"Tiêu tán năng lượng dao động thành nhiệt.","keywords":["Giảm chấn"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1285","kind":"part","lesson":"11.1.1","title":"Đòn trên","text":"Tham gia cơ cấu dẫn hướng bánh xe.","keywords":["Đòn trên"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1286","kind":"part","lesson":"11.1.1","title":"Đòn dưới","text":"Tham gia truyền lực và xác định quỹ đạo bánh xe.","keywords":["Đòn dưới"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1287","kind":"lesson","lesson":"11.1.2","title":"Hệ thống treo · Phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự phân biệt hệ thống treo."},{"id":"s1288","kind":"simulation","lesson":"11.1.2","title":"Trình tự phân biệt hệ thống treo","text":"1. Quan sát liên kết hai bánh cùng cầu. Tìm dầm cầu cứng chung hoặc cơ cấu treo riêng. 2. Xét quan hệ dao động hai bánh. Liên kết bằng dầm cứng làm một bánh ảnh hưởng bánh kia. 3. Xác định dạng dẫn hướng. Đối chiếu MacPherson và các dạng đòn độc lập trong tài liệu. 4. Xét phần điều khiển đặc tính. Điều khiển điện tử là tiêu chí bổ sung về phương pháp làm việc."},{"id":"s1289","kind":"figure","lesson":"11.1.2","title":"Phân loại hệ thống treo — sơ đồ học tập biên soạn từ bài 11.1.2","text":"A. Hệ thống treo phụ thuộc. Dao động một bánh ảnh hưởng bánh kia do liên kết bằng dầm cầu. B. Hệ thống treo độc lập. Không có dầm cầu cứng nối hai bánh như dạng phụ thuộc. C. Hệ thống treo điều khiển điện tử. Điều khiển điện tử tham gia thay đổi đặc tính làm việc. D. MacPherson. Giảm chấn làm đòn đứng, phối hợp đòn dưới và lò xo.","figure":{"image":"tuong_tac/diagrams/suspclasses.svg","caption":"Phân loại hệ thống treo — sơ đồ học tập biên soạn từ bài 11.1.2"}},{"id":"s1290","kind":"part","lesson":"11.1.2","title":"Hệ thống treo phụ thuộc","text":"Dao động một bánh ảnh hưởng bánh kia do liên kết bằng dầm cầu.","keywords":["Hệ thống treo phụ thuộc"],"figure":{"image":"tuong_tac/diagrams/suspclasses.svg","caption":"Phân loại hệ thống treo — sơ đồ học tập biên soạn từ bài 11.1.2"}},{"id":"s1291","kind":"part","lesson":"11.1.2","title":"Hệ thống treo độc lập","text":"Không có dầm cầu cứng nối hai bánh như dạng phụ thuộc.","keywords":["Hệ thống treo độc lập"],"figure":{"image":"tuong_tac/diagrams/suspclasses.svg","caption":"Phân loại hệ thống treo — sơ đồ học tập biên soạn từ bài 11.1.2"}},{"id":"s1292","kind":"part","lesson":"11.1.2","title":"Hệ thống treo điều khiển điện tử","text":"Điều khiển điện tử tham gia thay đổi đặc tính làm việc.","keywords":["Hệ thống treo điều khiển điện tử"],"figure":{"image":"tuong_tac/diagrams/suspclasses.svg","caption":"Phân loại hệ thống treo — sơ đồ học tập biên soạn từ bài 11.1.2"}},{"id":"s1293","kind":"part","lesson":"11.1.2","title":"MacPherson","text":"Giảm chấn làm đòn đứng, phối hợp đòn dưới và lò xo.","keywords":["MacPherson"],"figure":{"image":"tuong_tac/diagrams/suspclasses.svg","caption":"Phân loại hệ thống treo — sơ đồ học tập biên soạn từ bài 11.1.2"}},{"id":"s1294","kind":"lesson","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích dẫn hướng và đàn hồi bằng bó nhíp."},{"id":"s1295","kind":"simulation","lesson":"11.2.1","title":"Dẫn hướng và đàn hồi bằng bó nhíp","text":"1. Cầu xe tiếp nhận tác động bánh xe. Dầm cầu cứng liên kết các bánh ở treo phụ thuộc. 2. Quang nhíp truyền tới bó nhíp. Bu lông quang nhíp giữ chặt bó nhíp với cầu. 3. Bó nhíp biến dạng và dẫn hướng. Trong kết cấu này nhíp vừa đàn hồi vừa truyền các lực và mô men. 4. Hai đầu nhíp truyền tới khung. Liên kết bản lề hoặc gối đỡ cho phép biến dạng phù hợp hành trình."},{"id":"s1296","kind":"figure","lesson":"11.2.1","title":"Hình 11.1 — Lắp nhíp trên xe","text":"A. Khung xe. Tiếp nhận tải trọng và liên kết với hai đầu nhíp. B. Bó nhíp. Vừa đàn hồi vừa dẫn hướng trong kết cấu minh họa. C. Bu lông quang nhíp. Bắt chặt bó nhíp với cầu xe. D. Cầu xe. Liên kết hai bánh xe trong hệ thống treo phụ thuộc.","figure":{"image":"nt/figures/t2-11-1.jpg","caption":"Hình 11.1 — Lắp nhíp trên xe","number":"11.1"}},{"id":"s1297","kind":"part","lesson":"11.2.1","title":"Khung xe","text":"Tiếp nhận tải trọng và liên kết với hai đầu nhíp.","keywords":["Khung xe"],"figure":{"image":"nt/figures/t2-11-1.jpg","caption":"Hình 11.1 — Lắp nhíp trên xe","number":"11.1"}},{"id":"s1298","kind":"part","lesson":"11.2.1","title":"Bó nhíp","text":"Vừa đàn hồi vừa dẫn hướng trong kết cấu minh họa.","keywords":["Bó nhíp"],"figure":{"image":"nt/figures/t2-11-1.jpg","caption":"Hình 11.1 — Lắp nhíp trên xe","number":"11.1"}},{"id":"s1299","kind":"part","lesson":"11.2.1","title":"Bu lông quang nhíp","text":"Bắt chặt bó nhíp với cầu xe.","keywords":["Bu lông quang nhíp"],"figure":{"image":"nt/figures/t2-11-1.jpg","caption":"Hình 11.1 — Lắp nhíp trên xe","number":"11.1"}},{"id":"s1300","kind":"part","lesson":"11.2.1","title":"Cầu xe","text":"Liên kết hai bánh xe trong hệ thống treo phụ thuộc.","keywords":["Cầu xe"],"figure":{"image":"nt/figures/t2-11-1.jpg","caption":"Hình 11.1 — Lắp nhíp trên xe","number":"11.1"}},{"id":"s1301","kind":"lesson","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích quan hệ dẫn hướng của treo MacPherson."},{"id":"s1302","kind":"simulation","lesson":"11.2.2","title":"Quan hệ dẫn hướng của treo MacPherson","text":"1. Bánh xe dịch chuyển theo mặt đường. Bánh và cam quay chuyển động theo cơ cấu dẫn hướng. 2. Đòn dưới xác định quỹ đạo. Đòn dưới liên kết cam quay với khung qua khớp. 3. Giảm chấn làm đòn đứng. Trong MacPherson, đầu dưới giảm chấn gắn với cam quay, đầu trên liên kết khung. 4. Lò xo đỡ tải theo hành trình. Lò xo đảm nhận đàn hồi, phối hợp giảm chấn và dẫn hướng."},{"id":"s1303","kind":"figure","lesson":"11.2.2","title":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","text":"A. Lò xo. Đảm nhận chức năng đàn hồi. B. Giảm chấn. Đồng thời là đòn đứng trong kết cấu MacPherson. C. Cam quay bánh xe. Liên kết bánh xe với bộ phận dẫn hướng. D. Đòn dưới. Dẫn hướng và truyền lực giữa bánh xe với khung.","figure":{"image":"nt/figures/t2-11-16.jpg","caption":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","number":"11.16"}},{"id":"s1304","kind":"part","lesson":"11.2.2","title":"Lò xo","text":"Đảm nhận chức năng đàn hồi.","keywords":["Lò xo"],"figure":{"image":"nt/figures/t2-11-16.jpg","caption":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","number":"11.16"}},{"id":"s1305","kind":"part","lesson":"11.2.2","title":"Giảm chấn","text":"Đồng thời là đòn đứng trong kết cấu MacPherson.","keywords":["Giảm chấn"],"figure":{"image":"nt/figures/t2-11-16.jpg","caption":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","number":"11.16"}},{"id":"s1306","kind":"part","lesson":"11.2.2","title":"Cam quay bánh xe","text":"Liên kết bánh xe với bộ phận dẫn hướng.","keywords":["Cam quay bánh xe"],"figure":{"image":"nt/figures/t2-11-16.jpg","caption":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","number":"11.16"}},{"id":"s1307","kind":"part","lesson":"11.2.2","title":"Đòn dưới","text":"Dẫn hướng và truyền lực giữa bánh xe với khung.","keywords":["Đòn dưới"],"figure":{"image":"nt/figures/t2-11-16.jpg","caption":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","number":"11.16"}},{"id":"s1308","kind":"lesson","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích thu nhận và giải phóng năng lượng đàn hồi."},{"id":"s1309","kind":"simulation","lesson":"11.3.1","title":"Thu nhận và giải phóng năng lượng đàn hồi","text":"1. Lò xo tiếp nhận tải thẳng đứng. Lò xo xoắn biến dạng để đỡ tải theo hành trình. 2. Năng lượng tích trong biến dạng. Nhíp uốn, thanh xoắn chịu xoắn, lò xo xoắn nén hoặc giãn theo dạng phần tử. 3. Phần tử phục hồi khi tải thay đổi. Năng lượng đàn hồi được giải phóng khi phần tử phục hồi. 4. Giảm chấn phối hợp dập dao động. Phần tử đàn hồi không tự thay thế nhiệm vụ của giảm chấn và dẫn hướng."},{"id":"s1310","kind":"figure","lesson":"11.3.1","title":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","text":"A. Lò xo xoắn. Đàn hồi theo hành trình biến dạng, đỡ tải trọng thẳng đứng. B. Giảm chấn. Tiêu tán năng lượng dao động thành nhiệt. C. Đòn trên. Tham gia cơ cấu dẫn hướng bánh xe. D. Đòn dưới. Tham gia truyền lực và xác định quỹ đạo bánh xe.","figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1311","kind":"part","lesson":"11.3.1","title":"Lò xo xoắn","text":"Đàn hồi theo hành trình biến dạng, đỡ tải trọng thẳng đứng.","keywords":["Lò xo xoắn"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1312","kind":"part","lesson":"11.3.1","title":"Giảm chấn","text":"Tiêu tán năng lượng dao động thành nhiệt.","keywords":["Giảm chấn"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1313","kind":"part","lesson":"11.3.1","title":"Đòn trên","text":"Tham gia cơ cấu dẫn hướng bánh xe.","keywords":["Đòn trên"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1314","kind":"part","lesson":"11.3.1","title":"Đòn dưới","text":"Tham gia truyền lực và xác định quỹ đạo bánh xe.","keywords":["Đòn dưới"],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s1315","kind":"lesson","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích đàn hồi nhờ nén và giãn khí."},{"id":"s1316","kind":"note","lesson":"11.3.2","title":"Bộ phận đàn hồi khí nén","text":"Độ cứng thay đổi theo áp suất, thể tích khí và diện tích làm việc; không chỉ do chiều cao bầu khí. Mô hình lý tưởng có thể dùng pV^κ ≈ hằng số với giả thiết trao đổi nhiệt đã nêu. Không lấy một κ cố định cho mọi chế độ thực tế."},{"id":"s1317","kind":"simulation","lesson":"11.3.2","title":"Đàn hồi nhờ nén và giãn khí","text":"1. Tải làm buồng khí giảm thể tích. Bộ phận đàn hồi khí nén sử dụng khả năng nén của chất khí. 2. Áp suất khí tăng. Khí bị nén tạo tác động đàn hồi chống lại biến dạng. 3. Lực đàn hồi đỡ khung xe. Vỏ cao su hoặc màng biến dạng theo hành trình. 4. Giảm tải, khí giãn và phục hồi. Đặc tính khí nén là phi tuyến theo tài liệu; cao su còn dùng hạn chế hành trình."},{"id":"s1318","kind":"figure","lesson":"11.3.2","title":"Hình 11.32 — Bộ phận đàn hồi khí nén","text":"A. Vỏ cao su. Bao kín thể tích khí và biến dạng theo hành trình. B. Vành kim loại. Giữ phần mép của vỏ cao su theo kết cấu. C. Màng cao su. Biến dạng để thay đổi thể tích khí trong phần tử đàn hồi. D. Vỏ kim loại. Giới hạn buồng khí trong kết cấu dùng màng cao su.","figure":{"image":"nt/figures/t2-11-32.jpg","caption":"Hình 11.32 — Bộ phận đàn hồi khí nén","number":"11.32"}},{"id":"s1319","kind":"part","lesson":"11.3.2","title":"Vỏ cao su","text":"Bao kín thể tích khí và biến dạng theo hành trình.","keywords":["Vỏ cao su"],"figure":{"image":"nt/figures/t2-11-32.jpg","caption":"Hình 11.32 — Bộ phận đàn hồi khí nén","number":"11.32"}},{"id":"s1320","kind":"part","lesson":"11.3.2","title":"Vành kim loại","text":"Giữ phần mép của vỏ cao su theo kết cấu.","keywords":["Vành kim loại"],"figure":{"image":"nt/figures/t2-11-32.jpg","caption":"Hình 11.32 — Bộ phận đàn hồi khí nén","number":"11.32"}},{"id":"s1321","kind":"part","lesson":"11.3.2","title":"Màng cao su","text":"Biến dạng để thay đổi thể tích khí trong phần tử đàn hồi.","keywords":["Màng cao su"],"figure":{"image":"nt/figures/t2-11-32.jpg","caption":"Hình 11.32 — Bộ phận đàn hồi khí nén","number":"11.32"}},{"id":"s1322","kind":"part","lesson":"11.3.2","title":"Vỏ kim loại","text":"Giới hạn buồng khí trong kết cấu dùng màng cao su.","keywords":["Vỏ kim loại"],"figure":{"image":"nt/figures/t2-11-32.jpg","caption":"Hình 11.32 — Bộ phận đàn hồi khí nén","number":"11.32"}},{"id":"s1323","kind":"lesson","lesson":"11.4.1","title":"Hệ thống treo · Giảm chấn kiểu ống đơn","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nén, bù thể tích và trả ở giảm chấn ống đơn."},{"id":"s1324","kind":"note","lesson":"11.4.1","title":"Chiều dòng dầu theo khoang trên hình","text":"Ở Hình 11.39: nén, dầu từ II sang I; trả, dầu từ I sang II. Pít-tông khí / khoang khí bù thể tích do cần chiếm chỗ. Chiều “lên / xuống” chỉ đúng với tư thế lắp đang vẽ. Mốc vận tốc 0,3 m/s trong tài liệu là ví dụ kết cấu, không phải ngưỡng chung cho mọi giảm chấn."},{"id":"s1325","kind":"simulation","lesson":"11.4.1","title":"Nén, bù thể tích và trả ở giảm chấn ống đơn","text":"1. Hành trình nén: pit tông đi xuống. Bánh xe tiến gần khung làm pit tông thủy lực dịch xuống. 2. Dầu qua van nén từ II sang I. Chênh áp mở đường van nén; nén mạnh mở thêm các nắp van. 3. Pit tông khí bù thể tích. Khoang III chứa khí; pit tông khí dịch chuyển để bù phần thể tích cần chiếm chỗ. 4. Hành trình trả: dầu từ I sang II. Bánh xe rời xa khung, pit tông đi lên; dầu qua đường van trả."},{"id":"s1326","kind":"figure","lesson":"11.4.1","title":"Hình 11.39 — Giảm chấn kiểu ống đơn","text":"A. Cần pit tông. Dẫn chuyển động dao động tới pit tông thủy lực. B. Pit tông thủy lực. Chia khoang dầu và mang các đường van nén, trả. C. Pit tông khí. Dịch chuyển để bù thay đổi thể tích do cần pit tông chiếm chỗ. D. Khoang III. Chứa chất khí có thể nén để bù thể tích.","figure":{"image":"nt/figures/t2-11-39.jpg","caption":"Hình 11.39 — Giảm chấn kiểu ống đơn","number":"11.39"}},{"id":"s1327","kind":"part","lesson":"11.4.1","title":"Cần pit tông","text":"Dẫn chuyển động dao động tới pit tông thủy lực.","keywords":["Cần pit tông","Cần pít-tông","Cần piston"],"figure":{"image":"nt/figures/t2-11-39.jpg","caption":"Hình 11.39 — Giảm chấn kiểu ống đơn","number":"11.39"}},{"id":"s1328","kind":"part","lesson":"11.4.1","title":"Pit tông thủy lực","text":"Chia khoang dầu và mang các đường van nén, trả.","keywords":["Pit tông thủy lực","pít-tông thủy lực","piston thủy lực"],"figure":{"image":"nt/figures/t2-11-39.jpg","caption":"Hình 11.39 — Giảm chấn kiểu ống đơn","number":"11.39"}},{"id":"s1329","kind":"part","lesson":"11.4.1","title":"Pit tông khí","text":"Dịch chuyển để bù thay đổi thể tích do cần pit tông chiếm chỗ.","keywords":["Pit tông khí","pít-tông khí","piston khí"],"figure":{"image":"nt/figures/t2-11-39.jpg","caption":"Hình 11.39 — Giảm chấn kiểu ống đơn","number":"11.39"}},{"id":"s1330","kind":"part","lesson":"11.4.1","title":"Khoang III","text":"Chứa chất khí có thể nén để bù thể tích.","keywords":["Khoang III"],"figure":{"image":"nt/figures/t2-11-39.jpg","caption":"Hình 11.39 — Giảm chấn kiểu ống đơn","number":"11.39"}},{"id":"s1331","kind":"lesson","lesson":"11.4.2","title":"Hệ thống treo · Giảm chấn kiểu ống kép","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trao đổi dầu và bù thể tích ở ống kép."},{"id":"s1332","kind":"note","lesson":"11.4.2","title":"Khoang bù của giảm chấn ống kép","text":"Theo Hình 11.40–11.41, khoang III nằm giữa hai vỏ và dưới đế van. Dầu qua van pít-tông và đế van theo từng hành trình; lượng bù liên quan thể tích cần đi vào / đi ra. Giảm chấn tiêu tán năng lượng; bộ phận đàn hồi đảm nhiệm tích trữ và hoàn trả năng lượng chủ yếu."},{"id":"s1333","kind":"simulation","lesson":"11.4.2","title":"Trao đổi dầu và bù thể tích ở ống kép","text":"1. Pit tông dịch chuyển ở hành trình nén. Cần và pit tông làm thay đổi thể tích khoang I, II. 2. Dầu trao đổi qua van nén. Dầu đi từ khoang II tới khoang I; phần chênh lệch thể tích trao đổi với khoang bù qua đế van. 3. Khoang bù tiếp nhận thể tích chênh lệch. Khoang III nằm giữa vỏ trong và ngoài bù phần thể tích do cần chiếm chỗ. 4. Hành trình trả mở đường van trả. Dầu từ I sang II qua van trả, dầu bù được bổ sung theo hành trình."},{"id":"s1334","kind":"figure","lesson":"11.4.2","title":"Hình 11.40 — Giảm chấn kiểu ống kép","text":"A. Cần pit tông. Truyền chuyển động dao động tới pit tông. B. Pit tông. Chia khoang I và II trong vỏ trong. C. Vỏ trong. Tạo xi-lanh làm việc của giảm chấn. D. Vỏ ngoài. Bao ngoài và tạo khoảng không cho khoang bù. E. Đế van. Mang đường van trao đổi dầu với khoang bù.","figure":{"image":"nt/figures/t2-11-40.jpg","caption":"Hình 11.40 — Giảm chấn kiểu ống kép","number":"11.40"}},{"id":"s1335","kind":"part","lesson":"11.4.2","title":"Cần pit tông","text":"Truyền chuyển động dao động tới pit tông.","keywords":["Cần pit tông","Cần pít-tông","Cần piston"],"figure":{"image":"nt/figures/t2-11-40.jpg","caption":"Hình 11.40 — Giảm chấn kiểu ống kép","number":"11.40"}},{"id":"s1336","kind":"part","lesson":"11.4.2","title":"Pit tông","text":"Chia khoang I và II trong vỏ trong.","keywords":["Pit tông","pít-tông","piston"],"figure":{"image":"nt/figures/t2-11-40.jpg","caption":"Hình 11.40 — Giảm chấn kiểu ống kép","number":"11.40"}},{"id":"s1337","kind":"part","lesson":"11.4.2","title":"Vỏ trong","text":"Tạo xi-lanh làm việc của giảm chấn.","keywords":["Vỏ trong"],"figure":{"image":"nt/figures/t2-11-40.jpg","caption":"Hình 11.40 — Giảm chấn kiểu ống kép","number":"11.40"}},{"id":"s1338","kind":"part","lesson":"11.4.2","title":"Vỏ ngoài","text":"Bao ngoài và tạo khoảng không cho khoang bù.","keywords":["Vỏ ngoài"],"figure":{"image":"nt/figures/t2-11-40.jpg","caption":"Hình 11.40 — Giảm chấn kiểu ống kép","number":"11.40"}},{"id":"s1339","kind":"part","lesson":"11.4.2","title":"Đế van","text":"Mang đường van trao đổi dầu với khoang bù.","keywords":["Đế van"],"figure":{"image":"nt/figures/t2-11-40.jpg","caption":"Hình 11.40 — Giảm chấn kiểu ống kép","number":"11.40"}},{"id":"s1340","kind":"lesson","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích chuyển đặc tính mềm và cứng của Hydractive."},{"id":"s1341","kind":"note","lesson":"11.5.1","title":"Phạm vi minh họa Hydractive","text":"Minh họa trong bài tập trung vào nối / tách quả cầu trung tâm để thay đổi đặc tính đàn hồi. Tách cầu khí phụ làm giảm thể tích khí tham gia và tăng độ cứng trong cùng điều kiện. Cơ chế này chưa đủ để đại diện mọi chức năng của hệ thống treo chủ động."},{"id":"s1342","kind":"simulation","lesson":"11.5.1","title":"Chuyển đặc tính mềm và cứng của Hydractive","text":"1. Chế độ êm dịu nối ba quả cầu. Có thêm đệm khí phụ của quả cầu ở giữa nên đàn hồi mềm hơn. 2. Điều khiển nhận trạng thái xe. Độ cao, góc lái và bàn đạp cung cấp thông tin để lựa chọn trạng thái. 3. Van cắt liên kết quả cầu ở giữa. Lệnh điều khiển tác động bộ điều chỉnh độ cứng, cắt đường nối quả cầu trung tâm. 4. Chế độ thể thao có độ cứng lớn hơn. Thể tích khí tham gia giảm; bộ đàn hồi cứng hơn, hạn chế nghiêng thân."},{"id":"s1343","kind":"figure","lesson":"11.5.1","title":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","text":"A. Cảm biến đo độ cao. Cung cấp độ cao tương đối của khung gầm. B. Cụm thủy lực. Cấp và điều khiển dòng dầu tới các phần tử đàn hồi. C. Quả cầu lò xo ở giữa. Bổ sung thể tích khí khi được nối vào mạch để tạo chế độ mềm. D. Bộ điều khiển. Nhận tín hiệu để quyết định trạng thái của hệ thống.","figure":{"image":"nt/figures/t2-11-45.jpg","caption":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","number":"11.45"}},{"id":"s1344","kind":"part","lesson":"11.5.1","title":"Cảm biến đo độ cao","text":"Cung cấp độ cao tương đối của khung gầm.","keywords":["Cảm biến đo độ cao"],"figure":{"image":"nt/figures/t2-11-45.jpg","caption":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","number":"11.45"}},{"id":"s1345","kind":"part","lesson":"11.5.1","title":"Cụm thủy lực","text":"Cấp và điều khiển dòng dầu tới các phần tử đàn hồi.","keywords":["Cụm thủy lực"],"figure":{"image":"nt/figures/t2-11-45.jpg","caption":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","number":"11.45"}},{"id":"s1346","kind":"part","lesson":"11.5.1","title":"Quả cầu lò xo ở giữa","text":"Bổ sung thể tích khí khi được nối vào mạch để tạo chế độ mềm.","keywords":["Quả cầu lò xo ở giữa"],"figure":{"image":"nt/figures/t2-11-45.jpg","caption":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","number":"11.45"}},{"id":"s1347","kind":"part","lesson":"11.5.1","title":"Bộ điều khiển","text":"Nhận tín hiệu để quyết định trạng thái của hệ thống.","keywords":["Bộ điều khiển"],"figure":{"image":"nt/figures/t2-11-45.jpg","caption":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","number":"11.45"}},{"id":"s1348","kind":"lesson","lesson":"11.5.2","title":"Hệ thống treo · Bộ phận điều chỉnh lực giảm chấn điện tử – Continuous Damping Control (CDC)","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích điều chỉnh lực giảm chấn bằng van tỷ lệ."},{"id":"s1349","kind":"note","lesson":"11.5.2","title":"CDC, chủ động và lưu biến","text":"Tên đúng: Continuous Damping Control. CDC điển hình là điều khiển giảm chấn bán chủ động: thay đổi đặc tính cản, không phải cơ cấu chủ động tạo mọi lực nâng thân xe. Giảm chấn từ lưu biến dùng từ trường; lưu biến điện dùng điện trường. Không đồng nhất hai nguyên lý."},{"id":"s1350","kind":"simulation","lesson":"11.5.2","title":"Điều chỉnh lực giảm chấn bằng van tỷ lệ","text":"1. Cảm biến đo trạng thái dao động. Dữ liệu độ cao và chuyển động được đưa tới điều khiển. 2. Bộ điều khiển chọn lực giảm chấn. Phối hợp trạng thái xe và lựa chọn êm dịu hoặc thể thao. 3. Dòng điện điều khiển van tỷ lệ. Van làm thay đổi tiết diện lưu thông dầu theo yêu cầu. 4. Lực cản giảm chấn thay đổi. Mức lực giảm chấn được điều chỉnh liên tục theo điều khiển."},{"id":"s1351","kind":"figure","lesson":"11.5.2","title":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","text":"A. Nút chọn. Nhận lựa chọn chế độ chuyển động của người lái. B. Bộ điều khiển. Tính toán và phát lệnh điều chỉnh lực giảm chấn. C. Các cảm biến đo độ cao của xe. Cung cấp thông tin trạng thái dao động của xe. D. Các van thay đổi lực giảm chấn. Điều chỉnh đường dầu để thay đổi lực cản giảm chấn.","figure":{"image":"nt/figures/t2-11-48.jpg","caption":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","number":"11.48"}},{"id":"s1352","kind":"part","lesson":"11.5.2","title":"Nút chọn","text":"Nhận lựa chọn chế độ chuyển động của người lái.","keywords":["Nút chọn"],"figure":{"image":"nt/figures/t2-11-48.jpg","caption":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","number":"11.48"}},{"id":"s1353","kind":"part","lesson":"11.5.2","title":"Bộ điều khiển","text":"Tính toán và phát lệnh điều chỉnh lực giảm chấn.","keywords":["Bộ điều khiển"],"figure":{"image":"nt/figures/t2-11-48.jpg","caption":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","number":"11.48"}},{"id":"s1354","kind":"part","lesson":"11.5.2","title":"Các cảm biến đo độ cao của xe","text":"Cung cấp thông tin trạng thái dao động của xe.","keywords":["Các cảm biến đo độ cao của xe"],"figure":{"image":"nt/figures/t2-11-48.jpg","caption":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","number":"11.48"}},{"id":"s1355","kind":"part","lesson":"11.5.2","title":"Các van thay đổi lực giảm chấn","text":"Điều chỉnh đường dầu để thay đổi lực cản giảm chấn.","keywords":["Các van thay đổi lực giảm chấn"],"figure":{"image":"nt/figures/t2-11-48.jpg","caption":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","number":"11.48"}},{"id":"s1356","kind":"lesson","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích chịu tải và bao che của khung – vỏ."},{"id":"s1357","kind":"note","lesson":"12.1.1","title":"Cập nhật khung vỏ xe điện","text":"Tập 2/2026 có thêm vùng bảo vệ khối pin và phương án bố trí pin ở xe con, xe tải, xe buýt và hybrid. Đây là phần bổ sung so với gói cũ; khi đọc các hình khung vỏ cần xét đường truyền tải và nhiệm vụ bảo vệ khối pin."},{"id":"s1358","kind":"simulation","lesson":"12.1.1","title":"Chịu tải và bao che của khung – vỏ","text":"1. Xác định các cụm tạo tải trọng. Động cơ, truyền lực, buồng lái và thùng xe đặt tải lên kết cấu. 2. Xác định bộ phận chịu lực chính. Khung dầm hoặc thân vỏ chịu lực tiếp nhận tải theo kết cấu. 3. Theo dõi tải xuống hệ thống treo. Kết cấu chịu lực truyền tải qua các điểm liên kết hệ thống treo. 4. Phân biệt chức năng bao che của vỏ. Vỏ còn tạo không gian và bảo vệ khỏi môi trường, khác chức năng chịu lực."},{"id":"s1359","kind":"figure","lesson":"12.1.1","title":"Cơ chế chịu lực của khung – vỏ — sơ đồ học tập biên soạn từ bài 12.1.1","text":"A. Khung dầm rời chịu lực toàn bộ. Khung dầm đỡ các tổng thành, thân vỏ tạo không gian bao ngoài. B. Thân vỏ liền khối. Kết cấu thân vỏ là bộ phận của hệ chịu lực. C. Khung liền vỏ. Kết cấu khung, vỏ liên kết theo dạng được trình bày trong tài liệu. D. Vỏ ô tô. Bao bên ngoài, tạo không gian chứa người, hàng hóa và bảo vệ trước môi trường.","figure":{"image":"tuong_tac/diagrams/bodyclasses.svg","caption":"Cơ chế chịu lực của khung – vỏ — sơ đồ học tập biên soạn từ bài 12.1.1"}},{"id":"s1360","kind":"part","lesson":"12.1.1","title":"Khung dầm rời chịu lực toàn bộ","text":"Khung dầm đỡ các tổng thành, thân vỏ tạo không gian bao ngoài.","keywords":["Khung dầm rời chịu lực toàn bộ"],"figure":{"image":"tuong_tac/diagrams/bodyclasses.svg","caption":"Cơ chế chịu lực của khung – vỏ — sơ đồ học tập biên soạn từ bài 12.1.1"}},{"id":"s1361","kind":"part","lesson":"12.1.1","title":"Thân vỏ liền khối","text":"Kết cấu thân vỏ là bộ phận của hệ chịu lực.","keywords":["Thân vỏ liền khối"],"figure":{"image":"tuong_tac/diagrams/bodyclasses.svg","caption":"Cơ chế chịu lực của khung – vỏ — sơ đồ học tập biên soạn từ bài 12.1.1"}},{"id":"s1362","kind":"part","lesson":"12.1.1","title":"Khung liền vỏ","text":"Kết cấu khung, vỏ liên kết theo dạng được trình bày trong tài liệu.","keywords":["Khung liền vỏ"],"figure":{"image":"tuong_tac/diagrams/bodyclasses.svg","caption":"Cơ chế chịu lực của khung – vỏ — sơ đồ học tập biên soạn từ bài 12.1.1"}},{"id":"s1363","kind":"part","lesson":"12.1.1","title":"Vỏ ô tô","text":"Bao bên ngoài, tạo không gian chứa người, hàng hóa và bảo vệ trước môi trường.","keywords":["Vỏ ô tô"],"figure":{"image":"tuong_tac/diagrams/bodyclasses.svg","caption":"Cơ chế chịu lực của khung – vỏ — sơ đồ học tập biên soạn từ bài 12.1.1"}},{"id":"s1364","kind":"lesson","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích đường chịu tải trên khung xe tải."},{"id":"s1365","kind":"simulation","lesson":"12.1.2","title":"Đường chịu tải trên khung xe tải","text":"1. Giá đỡ tiếp nhận tải tổng thành. Các vị trí lắp định vị động cơ, buồng lái và các cụm. 2. Dầm dọc chịu tải chính. Hai dầm dọc chạy theo chiều dài khung tải. 3. Dầm ngang liên kết và gia cường. Dầm ngang nối hai dầm dọc, góp phần cứng vững kết cấu. 4. Tải truyền qua hệ thống treo xuống cầu. Khung phải đủ bền, cứng và thuận tiện lắp các tổng thành."},{"id":"s1366","kind":"figure","lesson":"12.1.2","title":"Hình 12.6 — Cấu tạo một số khung xe tải","text":"A. Dầm dọc. Thành phần chịu lực chính chạy theo chiều dài khung. B. Dầm ngang. Liên kết hai dầm dọc và gia cường độ cứng vững. C. Giá đỡ. Tạo vị trí lắp và định vị các cụm tổng thành.","figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s1367","kind":"part","lesson":"12.1.2","title":"Dầm dọc","text":"Thành phần chịu lực chính chạy theo chiều dài khung.","keywords":["Dầm dọc"],"figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s1368","kind":"part","lesson":"12.1.2","title":"Dầm ngang","text":"Liên kết hai dầm dọc và gia cường độ cứng vững.","keywords":["Dầm ngang"],"figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s1369","kind":"part","lesson":"12.1.2","title":"Giá đỡ","text":"Tạo vị trí lắp và định vị các cụm tổng thành.","keywords":["Giá đỡ"],"figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s1370","kind":"lesson","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích trình tự nhận biết dạng khung – vỏ xe con."},{"id":"s1371","kind":"simulation","lesson":"12.1.3","title":"Trình tự nhận biết dạng khung – vỏ xe con","text":"1. Xác định dạng liên kết thân và khung. Thân vỏ rời chế tạo tách biệt rồi lắp với khung. 2. Đối chiếu mức tham gia chịu tải. Thân chịu tải một phần khác với chịu tải hoàn toàn. 3. Theo dõi các điểm lắp tổng thành. Khung phụ đỡ các cụm tại vùng bố trí. 4. Kết luận cơ chế chịu lực. Dựa vào đường truyền tải thay vì chỉ hình dáng bao ngoài."},{"id":"s1372","kind":"figure","lesson":"12.1.3","title":"Các dạng khung và vỏ xe con — sơ đồ học tập biên soạn từ bài 12.1.3","text":"A. Thân vỏ rời. Thân lắp với khung dầm bằng mối ghép theo kết cấu. B. Thân vỏ chịu tải một phần. Cả khung và phần thân tham gia tiếp nhận tải theo dạng được mô tả. C. Thân vỏ chịu tải hoàn toàn. Hệ sàn và các phần thân tạo kết cấu chịu lực. D. Khung phụ. Dùng để lắp các tổng thành như động cơ, truyền lực hoặc treo theo bố trí.","figure":{"image":"tuong_tac/diagrams/carbody.svg","caption":"Các dạng khung và vỏ xe con — sơ đồ học tập biên soạn từ bài 12.1.3"}},{"id":"s1373","kind":"part","lesson":"12.1.3","title":"Thân vỏ rời","text":"Thân lắp với khung dầm bằng mối ghép theo kết cấu.","keywords":["Thân vỏ rời"],"figure":{"image":"tuong_tac/diagrams/carbody.svg","caption":"Các dạng khung và vỏ xe con — sơ đồ học tập biên soạn từ bài 12.1.3"}},{"id":"s1374","kind":"part","lesson":"12.1.3","title":"Thân vỏ chịu tải một phần","text":"Cả khung và phần thân tham gia tiếp nhận tải theo dạng được mô tả.","keywords":["Thân vỏ chịu tải một phần"],"figure":{"image":"tuong_tac/diagrams/carbody.svg","caption":"Các dạng khung và vỏ xe con — sơ đồ học tập biên soạn từ bài 12.1.3"}},{"id":"s1375","kind":"part","lesson":"12.1.3","title":"Thân vỏ chịu tải hoàn toàn","text":"Hệ sàn và các phần thân tạo kết cấu chịu lực.","keywords":["Thân vỏ chịu tải hoàn toàn"],"figure":{"image":"tuong_tac/diagrams/carbody.svg","caption":"Các dạng khung và vỏ xe con — sơ đồ học tập biên soạn từ bài 12.1.3"}},{"id":"s1376","kind":"part","lesson":"12.1.3","title":"Khung phụ","text":"Dùng để lắp các tổng thành như động cơ, truyền lực hoặc treo theo bố trí.","keywords":["Khung phụ"],"figure":{"image":"tuong_tac/diagrams/carbody.svg","caption":"Các dạng khung và vỏ xe con — sơ đồ học tập biên soạn từ bài 12.1.3"}},{"id":"s1377","kind":"lesson","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích ba chế độ bơm, giữ và xả khí."},{"id":"s1378","kind":"note","lesson":"12.2.1","title":"Ưu tiên nguồn khí và giới hạn sử dụng","text":"Hệ thống điều chỉnh áp suất lốp trung tâm và phanh có thể dùng chung nguồn khí qua van bảo vệ. Các ngưỡng áp suất trong ví dụ chỉ áp dụng cho kết cấu được mô tả. Bơm / giữ / xả là chế độ được lựa chọn, không phải chu trình tự động bắt buộc."},{"id":"s1379","kind":"simulation","lesson":"12.2.1","title":"Ba chế độ bơm, giữ và xả khí","text":"1. Nguồn khí được cấp và bảo vệ. Nguồn khí của phanh được ưu tiên khi áp suất thấp theo van hạn chế. 2. Chế độ bơm: nối nguồn với lốp. Van điều khiển cho khí từ nguồn qua bộ phận dẫn tới lốp. 3. Chế độ giữ: đóng đường khí. Đường cấp và xả được đóng để giữ áp suất lốp. 4. Chế độ xả: nối lốp với khí trời. Van điều khiển mở đường khí từ lốp ra ngoài."},{"id":"s1380","kind":"figure","lesson":"12.2.1","title":"Điều chỉnh áp suất hơi lốp — sơ đồ học tập biên soạn từ bài 12.2.1","text":"A. Cụm cung cấp và điều hòa khí nén. Bao gồm máy nén, bình chứa và phần điều hòa nguồn khí. B. Van điều khiển. Đổi đường khí theo chế độ điều chỉnh áp suất lốp. C. Bộ phận dẫn khí nén vào bánh xe. Truyền khí tới lốp và làm kín khi bánh xe quay. D. Van giữ hơi. Tham gia giữ kín khí của lốp theo kết cấu trong tài liệu.","figure":{"image":"tuong_tac/diagrams/tirepressure.svg","caption":"Điều chỉnh áp suất hơi lốp — sơ đồ học tập biên soạn từ bài 12.2.1"}},{"id":"s1381","kind":"part","lesson":"12.2.1","title":"Cụm cung cấp và điều hòa khí nén","text":"Bao gồm máy nén, bình chứa và phần điều hòa nguồn khí.","keywords":["Cụm cung cấp và điều hòa khí nén"],"figure":{"image":"tuong_tac/diagrams/tirepressure.svg","caption":"Điều chỉnh áp suất hơi lốp — sơ đồ học tập biên soạn từ bài 12.2.1"}},{"id":"s1382","kind":"part","lesson":"12.2.1","title":"Van điều khiển","text":"Đổi đường khí theo chế độ điều chỉnh áp suất lốp.","keywords":["Van điều khiển"],"figure":{"image":"tuong_tac/diagrams/tirepressure.svg","caption":"Điều chỉnh áp suất hơi lốp — sơ đồ học tập biên soạn từ bài 12.2.1"}},{"id":"s1383","kind":"part","lesson":"12.2.1","title":"Bộ phận dẫn khí nén vào bánh xe","text":"Truyền khí tới lốp và làm kín khi bánh xe quay.","keywords":["Bộ phận dẫn khí nén vào bánh xe"],"figure":{"image":"tuong_tac/diagrams/tirepressure.svg","caption":"Điều chỉnh áp suất hơi lốp — sơ đồ học tập biên soạn từ bài 12.2.1"}},{"id":"s1384","kind":"part","lesson":"12.2.1","title":"Van giữ hơi","text":"Tham gia giữ kín khí của lốp theo kết cấu trong tài liệu.","keywords":["Van giữ hơi"],"figure":{"image":"tuong_tac/diagrams/tirepressure.svg","caption":"Điều chỉnh áp suất hơi lốp — sơ đồ học tập biên soạn từ bài 12.2.1"}},{"id":"s1385","kind":"lesson","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Nhận diện và gọi đúng các chi tiết hoặc khái niệm trọng tâm trong bài. Giải thích nâng, giữ và hạ thùng theo điều khiển."},{"id":"s1386","kind":"note","lesson":"12.2.2","title":"Nâng hạ thùng và giữ tải","text":"Bơm chủ yếu cấp lưu lượng; áp suất hình thành theo tải và sức cản mạch. Giữ thùng bằng khóa đường dầu là mô tả chức năng, không phải bảo đảm cơ khí tuyệt đối khi rò rỉ. Không suy từ trạng thái minh họa sang quy trình bảo dưỡng dưới thùng. Nâng / giữ / hạ và vận hành tời là hai cơ cấu riêng trong bài."},{"id":"s1387","kind":"simulation","lesson":"12.2.2","title":"Nâng, giữ và hạ thùng theo điều khiển","text":"1. Hộp trích công suất dẫn động bơm. Bơm hút dầu từ thùng và cấp nguồn áp suất cho mạch. 2. Nâng: dầu tới xy lanh thủy lực. Van điều khiển đưa dầu có áp tới xy lanh để nâng thùng. 3. Giữ: khóa dầu trong xy lanh. Ở vị trí trung gian, dầu trong xy lanh được giữ; dầu từ bơm hồi về thùng. 4. Hạ: mở đường dầu hồi về thùng. Van cho dầu từ xy lanh về thùng để thùng hạ theo chế độ điều khiển."},{"id":"s1388","kind":"simulation","lesson":"12.2.2","title":"Đường truyền của tời cơ khí","text":"1. Hộp trích công suất nhận dẫn động. Công suất động cơ được lấy qua hộp số chính tới hộp trích công suất. 2. Các đăng truyền tới hộp giảm tốc. Trục các đăng nối hộp trích công suất với hộp giảm tốc tời. 3. Hộp giảm tốc làm quay trống tời. Giảm tốc làm tăng mô men tại trống tời. 4. Cáp tời truyền lực kéo. Trống quấn hoặc nhả cáp tạo tác động kéo theo chế độ điều khiển."},{"id":"s1389","kind":"figure","lesson":"12.2.2","title":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","text":"A. Thùng dầu thủy lực. Chứa dầu cho hệ thống nâng hạ. B. Hộp trích công suất từ hộp số chính. Truyền công suất để dẫn động bơm dầu thủy lực. C. Van điều khiển. Chọn đường dầu ứng với nâng, giữ hoặc hạ thùng. D. Xy lanh thủy lực. Biến áp suất dầu thành lực nâng thùng. E. Van giới hạn nâng sàn. Giới hạn nâng theo cơ cấu của hệ thống minh họa.","figure":{"image":"nt/figures/t2-12-41.jpg","caption":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.41"}},{"id":"s1390","kind":"part","lesson":"12.2.2","title":"Thùng dầu thủy lực","text":"Chứa dầu cho hệ thống nâng hạ.","keywords":["Thùng dầu thủy lực"],"figure":{"image":"nt/figures/t2-12-41.jpg","caption":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.41"}},{"id":"s1391","kind":"part","lesson":"12.2.2","title":"Hộp trích công suất từ hộp số chính","text":"Truyền công suất để dẫn động bơm dầu thủy lực.","keywords":["Hộp trích công suất từ hộp số chính"],"figure":{"image":"nt/figures/t2-12-41.jpg","caption":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.41"}},{"id":"s1392","kind":"part","lesson":"12.2.2","title":"Van điều khiển","text":"Chọn đường dầu ứng với nâng, giữ hoặc hạ thùng.","keywords":["Van điều khiển"],"figure":{"image":"nt/figures/t2-12-41.jpg","caption":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.41"}},{"id":"s1393","kind":"part","lesson":"12.2.2","title":"Xy lanh thủy lực","text":"Biến áp suất dầu thành lực nâng thùng.","keywords":["Xy lanh thủy lực","xi-lanh thủy lực"],"figure":{"image":"nt/figures/t2-12-41.jpg","caption":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.41"}},{"id":"s1394","kind":"part","lesson":"12.2.2","title":"Van giới hạn nâng sàn","text":"Giới hạn nâng theo cơ cấu của hệ thống minh họa.","keywords":["Van giới hạn nâng sàn"],"figure":{"image":"nt/figures/t2-12-41.jpg","caption":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.41"}},{"id":"s1395","kind":"figure","lesson":"12.2.2","title":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","text":"A. Hộp trích công suất. Nhận công suất từ hộp số chính để dẫn động thiết bị phụ. B. Trục các đăng. Truyền mô men giữa hộp trích công suất và hộp giảm tốc. C. Hộp giảm tốc. Giảm tốc và tăng mô men tới trống tời. D. Trống tời. Quấn hoặc nhả dây cáp để tạo tác động kéo. E. Dây cáp. Truyền lực kéo từ trống tời tới điểm kéo.","figure":{"image":"nt/figures/t2-12-35.jpg","caption":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","number":"12.35"}},{"id":"s1396","kind":"part","lesson":"12.2.2","title":"Hộp trích công suất","text":"Nhận công suất từ hộp số chính để dẫn động thiết bị phụ.","keywords":["Hộp trích công suất"],"figure":{"image":"nt/figures/t2-12-35.jpg","caption":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","number":"12.35"}},{"id":"s1397","kind":"part","lesson":"12.2.2","title":"Trục các đăng","text":"Truyền mô men giữa hộp trích công suất và hộp giảm tốc.","keywords":["Trục các đăng"],"figure":{"image":"nt/figures/t2-12-35.jpg","caption":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","number":"12.35"}},{"id":"s1398","kind":"part","lesson":"12.2.2","title":"Hộp giảm tốc","text":"Giảm tốc và tăng mô men tới trống tời.","keywords":["Hộp giảm tốc"],"figure":{"image":"nt/figures/t2-12-35.jpg","caption":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","number":"12.35"}},{"id":"s1399","kind":"part","lesson":"12.2.2","title":"Trống tời","text":"Quấn hoặc nhả dây cáp để tạo tác động kéo.","keywords":["Trống tời"],"figure":{"image":"nt/figures/t2-12-35.jpg","caption":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","number":"12.35"}},{"id":"s1400","kind":"part","lesson":"12.2.2","title":"Dây cáp","text":"Truyền lực kéo từ trống tời tới điểm kéo.","keywords":["Dây cáp"],"figure":{"image":"nt/figures/t2-12-35.jpg","caption":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","number":"12.35"}},{"id":"s1401","kind":"figure","lesson":"9.1.1","title":"Hình 9.1. Các kiểu quay vòng của ô tô a) Ô tô 2 cầu, 2 bánh trước dẫn hướng; b) Ô tô 3 cầu, 2 bánh trước dẫn hướng; c) Ô tô 4 cầu, bốn bánh trước dẫn hướng; d) Ô tô 2 cầu, 4 bánh dẫn hướng; e) Ô tô 2 cầu kéo theo","text":"Hình 9.1. Các kiểu quay vòng của ô tô a) Ô tô 2 cầu, 2 bánh trước dẫn hướng; b) Ô tô 3 cầu, 2 bánh trước dẫn hướng; c) Ô tô 4 cầu, bốn bánh trước dẫn hướng; d) Ô tô 2 cầu, 4 bánh dẫn hướng; e) Ô tô 2 cầu kéo theo","pages":[13],"figure":{"number":"9.1","caption":"Hình 9.1. Các kiểu quay vòng của ô tô a) Ô tô 2 cầu, 2 bánh trước dẫn hướng; b) Ô tô 3 cầu, 2 bánh trước dẫn hướng; c) Ô tô 4 cầu, bốn bánh trước dẫn hướng; d) Ô tô 2 cầu, 4 bánh dẫn hướng; e) Ô tô 2 cầu kéo theo"}},{"id":"s1402","kind":"pdf","lesson":"9.1.1","title":"Hệ thống lái · Công dụng","text":"Hệ thống lái có nhiệm vụ thay đổi hướng chuyển động của ô tô thông qua việc điều khiển góc quay của bánh xe dẫn hướng, đồng thời góp phần duy trì tính ổn định và khả năng điều khiển xe trong quá trình vận hành. Chương này trình bày công dụng, phân loại và cấu tạo chung của hệ thống lái; các cơ cấu lái, dẫn động lái và những đặc điểm kết cấu tương ứng. Nội dung tiếp theo tập trung vào các hệ thống lái có trợ lực thủy lực, trợ lực điện, trợ lực thủy lực điều khiển điện tử và hệ thống lái không trục lái. 1. Công dụng Hệ thống lái dùng để thay đổi hướng chuyển động của ô tô bằng cách thay đổi góc quay của bánh xe dẫn hướng (thường là bánh trước).","pages":[13]},{"id":"s1403","kind":"pdf","lesson":"9.1.1","title":"Hệ thống lái · Công dụng","text":"Ngoài ra, hệ thống lái còn có các công dụng sau: - Duy trì hướng chuyển động ổn định: giữ cho xe đi đúng hướng đã chọn trong quá trình di chuyển thẳng hoặc khi quay vòng. - Tạo cảm giác lái tin cậy: cung cấp phản hồi phù hợp về điều kiện mặt đường và trạng thái vận hành xe qua vành tay lái. - Hạn chế ảnh hưởng từ mặt đường: giảm thiểu các dao động, rung động truyền ngược từ bánh xe đến tay lái. - Hỗ trợ an toàn khi vận hành: giúp người lái xử lý chính xác và kịp thời trong các tình huống đặc biệt (phanh gấp, đánh lái khẩn cấp). Các hệ thống lái hiện đại có thể tích hợp trợ lực, cảm biến, bộ điều khiển điện tử (ECU) và các thiết bị điện tử liên quan nhằm nâng cao hiệu quả điều khiển và giảm sức điều khiển cho người lái. rơ mooc, với kiểu \"quay nửa thân xe\" Các phương pháp quay vòng thường được sử dụng trên ô tô (Hình 9.1) gồm:","pages":[13]},{"id":"s1404","kind":"figure","lesson":"9.1.1","title":"Hình 9.2. Cầu xe dẫn hướng 1. Bánh xe dẫn hướng; 2. Moay-ơ bánh xe; 3. Trụ đứng; 4. Dầm cầu; 5. Ổ bi moay-ơ.","text":"Hình 9.2. Cầu xe dẫn hướng 1. Bánh xe dẫn hướng; 2. Moay-ơ bánh xe; 3. Trụ đứng; 4. Dầm cầu; 5. Ổ bi moay-ơ.","pages":[14],"figure":{"number":"9.2","caption":"Hình 9.2. Cầu xe dẫn hướng 1. Bánh xe dẫn hướng; 2. Moay-ơ bánh xe; 3. Trụ đứng; 4. Dầm cầu; 5. Ổ bi moay-ơ."}},{"id":"s1405","kind":"pdf","lesson":"9.1.1","title":"Hệ thống lái · Công dụng","text":"- Quay bánh xe dẫn hướng (Hình 9.1a, b, c, d); - Thay đổi hướng của một phần trục dọc thân xe (Hình 9.1e). Phương pháp thay đổi hướng chuyển động của ô tô phổ biến nhất hiện nay là quay các bánh xe dẫn hướng quanh trục trụ đứng. Để thực hiện chuyển động này, cụm bánh xe dẫn hướng (thông qua cam quay) được liên kết bản lề với dầm cầu (Hình 9.2) hoặc liên kết qua các khớp cầu với bộ phận dẫn hướng của hệ thống treo. Chi tiết chốt tạo liên kết bản lề này (hoặc đường tâm quay tương ứng) được gọi là trụ đứng. 2.","pages":[14]},{"id":"s1406","kind":"pdf","lesson":"9.1.2","title":"Hệ thống lái · Phân loại","text":"Phân loại a) Theo cách bố trí vành tay lái - Vành tay lái bố trí bên trái: dùng ở các quốc gia áp dụng luật giao thông đi bên phải như Việt Nam, Pháp, Nga, Đức, Hoa Kỳ; khi đó người lái ngồi bên trái khoang lái; - Vành tay lái bố trí bên phải: phổ biến ở các quốc gia có luật giao thông đi bên trái như Vương quốc Anh, Nhật Bản, Thái Lan, Úc, Ấn Độ. b) Theo cơ cấu lái - Loại trục vít – bánh vít: dạng cơ cấu cổ điển, có độ bền cao, thường dùng trên xe tải hoặc xe buýt đời cũ; cơ cấu này có hiệu suất truyền lực thấp và ma sát lớn; - Loại trục vít – cung răng: sử dụng cung răng thay cho bánh răng tròn, giúp giảm kích thước và cải thiện hiệu suất; - Loại trục vít – con lăn: có hiệu suất cao hơn, giảm ma sát tiếp xúc, thường dùng trên các mẫu xe cũ; - Loại kết hợp (trục vít – đai ốc – thanh răng – cung răng): kết hợp nhiều dạng cơ cấu trên nhằm tăng độ chính xác,","pages":[14]},{"id":"s1407","kind":"pdf","lesson":"9.1.1","title":"Hệ thống lái · Công dụng","text":"giảm ma sát và tăng độ bền. c) Theo số lượng bánh xe được điều khiển - Hệ thống lái bánh trước (phổ biến nhất); - Hệ thống lái bốn bánh (4WS – Four Wheel Steering). d) Theo nguyên lý làm việc của bộ trợ lực Bộ trợ lực giúp người lái giảm lực tác động lên vành tay lái, đặc biệt khi xe chạy ở tốc độ thấp hoặc quay đầu. Căn cứ vào nguyên lý làm việc, hệ thống trợ lực được chia thành:","pages":[14]},{"id":"s1408","kind":"figure","lesson":"9.2.1","title":"Hình 9.3. Cơ cấu lái trục vít – bánh vít","text":"Hình 9.3. Cơ cấu lái trục vít – bánh vít","pages":[15],"figure":{"number":"9.3","caption":"Hình 9.3. Cơ cấu lái trục vít – bánh vít"}},{"id":"s1409","kind":"pdf","lesson":"9.2.1","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít – bánh vít","text":"- Loại trợ lực thủy lực (Hydraulic Power Steering - HPS): sử dụng một bơm dầu tạo ra áp suất thủy lực cần thiết cung cấp cho cơ cấu lái, giảm lực tác động của người lái lên vành tay lái; - Loại trợ lực điện (Electric Power Steering - EPS): sử dụng mô-tơ điện và cảm biến mô-men để tạo ra lực hỗ trợ tác động lên trục lái, giảm lực điều khiển của người lái; mô-tơ được ECU điều khiển dựa trên tín hiệu từ cảm biến góc lái và tốc độ xe; - Hệ thống lái thủy lực điều khiển điện tử (Electro-Hydraulic Power Steering - EHPS): kết hợp ưu điểm của HPS và EPS, sử dụng bơm thủy lực được dẫn động bằng mô-tơ điện và điều khiển bởi ECU; - Hệ thống lái không trục (Steer-by-Wire): là hệ thống sử dụng tín hiệu điện và các cơ cấu chấp hành điện để điều khiển hướng của bánh xe dẫn hướng, không sử dụng liên kết cơ khí truyền lực lái trực tiếp giữa vành tay lái và cơ cấu lái trong","pages":[15]},{"id":"s1410","kind":"pdf","lesson":"9.2.1","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít – bánh vít","text":"chế độ vận hành bình thường. II. CƠ CẤU LÁI Trong hệ thống lái, cơ cấu lái đóng vai trò biến đổi chuyển động quay của trục lái thành chuyển động góc hoặc chuyển động tịnh tiến của dẫn động lái, đồng thời khuếch đại mô-men nhằm giảm nhẹ lực điều khiển và đảm bảo độ chính xác khi thay đổi hướng chuyển động của ô tô. Tùy thuộc vào yêu cầu thiết kế và tải trọng của từng loại xe, các dạng cơ cấu lái phổ biến dưới đây được lựa chọn ứng dụng. 1.","pages":[15]},{"id":"s1411","kind":"pdf","lesson":"9.2.1","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít – bánh vít","text":"Cơ cấu lái kiểu trục vít - bánh vít Đây là dạng cơ cấu sử dụng bộ truyền trục vít ăn khớp với bánh vít để truyền chuyển động quay từ vành tay lái đến đòn quay đứng (Hình 9.3). a) Cấu tạo Cơ cấu lái kiểu trục vít - bánh vít là dạng truyền động cơ khí cổ điển, gồm các bộ phận chính: - Trục vít: gắn liền với trục vành tay lái, có ren ngoài ăn khớp với bánh vít. - Bánh vít: có dạng cung răng hoặc bánh răng, thường được lắp lệch tâm với trục đứng. - Trục đòn quay đứng: nhận chuyển động quay từ bánh vít để truyền tới các đòn kéo.","pages":[15]},{"id":"s1412","kind":"figure","lesson":"9.2.2","title":"Hình 9.4. Cơ cấu lái trục vít lõm – con lăn 1. Trục vít; 2. Con lăn; 3. Trục đòn quay đứng","text":"Hình 9.4. Cơ cấu lái trục vít lõm – con lăn 1. Trục vít; 2. Con lăn; 3. Trục đòn quay đứng","pages":[16],"figure":{"number":"9.4","caption":"Hình 9.4. Cơ cấu lái trục vít lõm – con lăn 1. Trục vít; 2. Con lăn; 3. Trục đòn quay đứng"}},{"id":"s1413","kind":"pdf","lesson":"9.2.1","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít – bánh vít","text":"- Vỏ cơ cấu lái: chứa cơ cấu lái và có cơ cấu điều chỉnh khe hở răng. - Ổ đỡ và bạc lót: giúp trục quay dễ dàng, đồng thời định vị các chi tiết. b) Nguyên lý làm việc Khi người lái quay vành tay lái, trục vít quay. Nhờ ăn khớp với trục vít, bánh vít quay và làm trục đòn quay đứng quay theo; trục đòn quay đứng truyền lực đến thanh dẫn động để đổi hướng bánh xe. Đặc điểm: - Hiệu suất thấp do ma sát trượt cao; - Tỷ số truyền lớn, phù hợp cho xe tải; - Có khả năng tự hãm (hạn chế truyền phản lực về vành tay lái); - Ưu điểm: kết cấu đơn giản, độ bền cao; - Nhược điểm: hiệu suất truyền lực thấp, ma sát lớn, gây tiêu hao công suất; tay lái nặng nếu không có trợ lực. Cơ cấu này thường được dùng trên xe tải và xe buýt thế hệ cũ. Hiện nay ít được sử dụng, chủ yếu kết hợp với trợ lực thủy lực. 2.","pages":[16]},{"id":"s1414","kind":"pdf","lesson":"9.2.2","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít lõm - con lăn","text":"Cơ cấu lái kiểu trục vít lõm - con lăn Cơ cấu lái kiểu trục vít lõm – con lăn (Hình 9.4) gồm trục vít dạng glô-bô-it (ren lõm) ăn khớp với một hoặc nhiều con lăn; các con lăn được lắp trên giá con lăn cố định trên trục đòn quay đứng. a) Cấu tạo - Trục vít (1) được gắn trực tiếp với trục vành tay lái. Trục vít này có biên dạng ren dạng glô-bô-it, được chế tạo phù hợp với biên dạng của con lăn để đảm bảo khả năng truyền lực. - Con lăn (2) được lắp trên một trục phụ gọi là giá con lăn và luôn ở trạng thái ăn khớp với ren của trục vít. Tùy thuộc vào tải trọng và thiết kế của từng loại xe, cơ cấu này có thể được trang bị 1 hoặc 2 con lăn. - Trục đòn quay đứng (3) được thiết kế gắn liền với giá con lăn, là trục truyền động đưa lực ra thanh dẫn động để làm quay bánh xe dẫn hướng.","pages":[16]},{"id":"s1415","kind":"pdf","lesson":"9.2.1","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít – bánh vít","text":"Đầu ra của trục đòn quay đứng thường được chế tạo rãnh then hoa để lắp ghép với đòn quay đứng.","pages":[16]},{"id":"s1416","kind":"figure","lesson":"9.2.2","title":"Hình 9.5. Cơ cấu lái trục vít – con lăn xe GAZ-66 1. Trục vít; 2. Trục lái; 3. Giá con lăn; 4. Con lăn; 5. Đòn quay đứng; 6. Vỏ cơ cấu lái; 7.","text":"Hình 9.5. Cơ cấu lái trục vít – con lăn xe GAZ-66 1. Trục vít; 2. Trục lái; 3. Giá con lăn; 4. Con lăn; 5. Đòn quay đứng; 6. Vỏ cơ cấu lái; 7.","pages":[17],"figure":{"number":"9.5","caption":"Hình 9.5. Cơ cấu lái trục vít – con lăn xe GAZ-66 1. Trục vít; 2. Trục lái; 3. Giá con lăn; 4. Con lăn; 5. Đòn quay đứng; 6. Vỏ cơ cấu lái; 7."}},{"id":"s1417","kind":"pdf","lesson":"9.2.2","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít lõm - con lăn","text":"- Ổ lăn, ổ bi được bố trí bên trong cơ cấu nhằm giảm thiểu tối đa ma sát cho quá trình quay của trục vít và con lăn. - Vỏ cơ cấu lái bao bọc bên ngoài với nhiệm vụ chính là giữ dầu bôi trơn cho các chi tiết bên trong. Trên vỏ còn có bố trí một vít điều chỉnh khe hở ăn khớp. Vít này có chức năng ép giá con lăn tiến lại gần trục vít, giúp người thợ dễ dàng căn chỉnh và bù đắp các khe hở phát sinh do hao mòn sau thời gian dài sử dụng. b) Nguyên lý làm việc Khi người lái quay vành tay lái, trục vít quay. Con lăn (2) ăn khớp với ren lõm vừa quay quanh trục của nó, vừa dịch chuyển dọc trục vít. Chuyển động này truyền sang trục đòn quay đứng để đổi hướng bánh xe dẫn hướng. So với kiểu bánh vít, cơ cấu trục vít – con lăn có hiệu suất cao hơn nhờ thay ma sát trượt bằng ma sát lăn. Kết cấu gọn nhẹ và dễ điều chỉnh khe hở ăn khớp.","pages":[17]},{"id":"s1418","kind":"pdf","lesson":"9.2.2","title":"Hệ thống lái · Cơ cấu lái kiểu trục vít lõm - con lăn","text":"Biên dạng glô-bô-it ôm sát con lăn giúp phân bố tải trọng đồng đều lên nhiều diện tích tiếp xúc hơn trong quá trình đánh lái nhằm hạn chế hiện tượng mài mòn cụ. Trước đây, cơ cấu này phổ biến trên một số xe như Rolls-Royce Silver Shadow, Fiat 500 Topolino, Toyota Land Cruiser FJ40, GAZ-53, GAZ-66 (Hình 9.5). 3.","pages":[17]},{"id":"s1419","kind":"pdf","lesson":"9.2.3","title":"Hệ thống lái · Cơ cấu lái kiểu bánh răng - thanh răng","text":"Cơ cấu lái kiểu bánh răng - thanh răng a) Cấu tạo - Bánh răng trụ: Được lắp ở đầu dưới của trục lái, nhận chuyển động quay từ vành lái. - Thanh răng: Là thanh kim loại có gia công răng ở một phía để ăn khớp với bánh răng chủ động, được lắp trượt dọc trục bên trong vỏ cơ cấu lái. - Vỏ thanh răng: Che chắn, bảo vệ cặp bánh răng – thanh răng, lưu giữ mỡ bôi trơn và bố trí bạc dẫn hướng cho thanh răng. - Chụp bụi và bạc cao su: Bao kín hai đầu vỏ cơ cấu lái, có tác dụng ngăn bụi bẩn, nước xâm nhập và giữ mỡ bôi trơn. - Thanh nối: Liên kết hai đầu thanh răng với đòn quay ngang của cam quay thông qua các khớp cầu (rô-tuyn lái).","pages":[17]},{"id":"s1420","kind":"figure","lesson":"9.2.3","title":"Hình 9.6. Cơ cấu lái bánh răng - thanh răng trên các mẫu xe thế hệ cũ","text":"Hình 9.6. Cơ cấu lái bánh răng - thanh răng trên các mẫu xe thế hệ cũ","pages":[18],"figure":{"number":"9.6","caption":"Hình 9.6. Cơ cấu lái bánh răng - thanh răng trên các mẫu xe thế hệ cũ"}},{"id":"s1421","kind":"figure","lesson":"9.2.3","title":"Hình 9.7. Cơ cấu lái bánh răng - thanh răng trên xe du lịch 1. Vít điều chỉnh; 2. Lò xo nén; 3. Vít điều chỉnh; 4. Vòng bi đỡ trên; 5. Bánh răng; 6. Vòng bi đỡ dưới; 7. Thanh răng; 8. Dẫn hướng thanh răng; 9. Vỏ thanh răng; 10. Bạc lót;","text":"Hình 9.7. Cơ cấu lái bánh răng - thanh răng trên xe du lịch 1. Vít điều chỉnh; 2. Lò xo nén; 3. Vít điều chỉnh; 4. Vòng bi đỡ trên; 5. Bánh răng; 6. Vòng bi đỡ dưới; 7. Thanh răng; 8. Dẫn hướng thanh răng; 9. Vỏ thanh răng; 10. Bạc lót;","pages":[18],"figure":{"number":"9.7","caption":"Hình 9.7. Cơ cấu lái bánh răng - thanh răng trên xe du lịch 1. Vít điều chỉnh; 2. Lò xo nén; 3. Vít điều chỉnh; 4. Vòng bi đỡ trên; 5. Bánh răng; 6. Vòng bi đỡ dưới; 7. Thanh răng; 8. Dẫn hướng thanh răng; 9. Vỏ thanh răng; 10. Bạc lót;"}},{"id":"s1422","kind":"pdf","lesson":"9.2.3","title":"Hệ thống lái · Cơ cấu lái kiểu bánh răng - thanh răng","text":"Cơ cấu lái kiểu bánh răng – thanh răng là một trong những kiểu cơ cấu lái phổ biến hiện nay. Cơ cấu có kết cấu đơn giản, nhỏ gọn, hiệu suất cao do ma sát thấp nên được dùng rộng rãi trên xe du lịch hiện đại (Hình 9.6 và Hình 9.7). 1. Vỏ cơ cấu lái; 2. Trục lái; 3. Thanh răng; 4. Bánh răng; 5. Đòn kéo; 6. Trụ 11. Đầu thanh răng; 12. Thanh nối đến cam quay b) Nguyên lý làm việc Khi người lái quay vành tay lái, bánh răng trụ quay theo. Nhờ ăn khớp với thanh răng, chuyển động quay này được biến đổi thành chuyển động tịnh tiến của thanh răng sang trái hoặc phải.","pages":[18]},{"id":"s1423","kind":"figure","lesson":"9.2.4","title":"Hình 9.8. Cơ cấu lái trục vít - đai ốc - thanh răng - cung răng 1, 4. Ổ bi đỡ; 2. Trục vít; 3. Đai ốc bi; 5. Đai ốc; 6. Cung răng; 7. Vỏ cơ cấu lái; 8. Viên bi.","text":"Hình 9.8. Cơ cấu lái trục vít - đai ốc - thanh răng - cung răng 1, 4. Ổ bi đỡ; 2. Trục vít; 3. Đai ốc bi; 5. Đai ốc; 6. Cung răng; 7. Vỏ cơ cấu lái; 8. Viên bi.","pages":[19],"figure":{"number":"9.8","caption":"Hình 9.8. Cơ cấu lái trục vít - đai ốc - thanh răng - cung răng 1, 4. Ổ bi đỡ; 2. Trục vít; 3. Đai ốc bi; 5. Đai ốc; 6. Cung răng; 7. Vỏ cơ cấu lái; 8. Viên bi."}},{"id":"s1424","kind":"pdf","lesson":"9.2.4","title":"Hệ thống lái · Cơ cấu vít - đai ốc bi tuần hoàn","text":"Thanh răng di chuyển sẽ đẩy các thanh nối lái hai bên, khiến moay-ơ bánh xe và bánh dẫn hướng quay theo, từ đó thay đổi hướng chuyển động của xe. Cơ cấu này được dùng phổ biến trên xe du lịch, SUV, crossover và xe thể thao nhờ hiệu quả cao và kết cấu nhỏ gọn; đây cũng là loại cơ cấu lái thường được kết hợp với hệ thống trợ lực lái điện (EPS). 4. Cơ cấu lái kiểu vít - đai ốc bi tuần hoàn Cơ cấu này sử dụng trục vít và đai ốc bi, trong đó các viên bi thép tuần hoàn lăn giữa rãnh của trục vít và rãnh của đai ốc. Khi trục vít quay, thông qua các viên bi tuần hoàn, đai ốc bi dịch chuyển theo phương trục, làm quay cung răng và đòn quay đứng (Hình 9.8). a) Cấu tạo Cơ cấu gồm các bộ phận chính sau: - Trục vít (2) được kết nối trực tiếp với trục vành tay lái để tiếp nhận chuyển động quay từ người điều khiển. Trên thân trục vít có gia công các rãnh xoắn chạy dọc.","pages":[19]},{"id":"s1425","kind":"pdf","lesson":"9.2.4","title":"Hệ thống lái · Cơ cấu vít - đai ốc bi tuần hoàn","text":"Trục vít được định vị và xoay nhờ các ổ bi đỡ (1) và (4) ở hai đầu. - Đai ốc bi (3) và viên bi thép (8) bố trí giữa rãnh của trục vít và đai ốc. Các viên bi này thay thế ma sát trượt thông thường bằng ma sát lăn, giúp đai ốc dịch chuyển tịnh tiến dọc theo trục vít. - Ống dẫn nhỏ có biên dạng cong, được hàn hoặc lắp cố định ngay trên mặt ngoài của đai ốc bi để dẫn hướng các viên bi thép (8) quay trở lại điểm xuất phát, tạo thành một chu trình lăn khép kín, tuần hoàn liên tục khi trục vít quay. - Mặt ngoài của đai ốc bi (3) thường được phay dạng thanh răng thẳng. Cung răng (6) sẽ ăn khớp trực tiếp với phần thanh răng này.","pages":[19]},{"id":"s1426","kind":"pdf","lesson":"9.2.3","title":"Hệ thống lái · Cơ cấu lái kiểu bánh răng - thanh răng","text":"Cung răng được liên kết cơ khí then hoa chặt chẽ với trục đòn quay đứng, làm nhiệm vụ biến đổi chuyển động tịnh tiến của đai ốc thành chuyển động xoay của đòn quay đứng, từ đó truyền lực ra hệ thống đòn kéo bánh lái. - Vỏ cơ cấu (7) bằng kim loại, làm nhiệm vụ bao bọc, nâng đỡ toàn bộ cụm chi tiết chuyển động bên trong và giữ kín dầu bôi trơn. Bên cạnh đó cơ cấu còn trang bị đai ốc (5) để hỗ trợ quá trình lắp ráp và điều chỉnh khe hở.","pages":[19]},{"id":"s1427","kind":"figure","lesson":"9.3.1","title":"Hình 9.9. Bố trí chung của hệ thống lái 1. Vành tay lái; 2. Trục tay lái; 3. Dẫn động lái; 4. Cơ cấu lái","text":"Hình 9.9. Bố trí chung của hệ thống lái 1. Vành tay lái; 2. Trục tay lái; 3. Dẫn động lái; 4. Cơ cấu lái","pages":[20],"figure":{"number":"9.9","caption":"Hình 9.9. Bố trí chung của hệ thống lái 1. Vành tay lái; 2. Trục tay lái; 3. Dẫn động lái; 4. Cơ cấu lái"}},{"id":"s1428","kind":"pdf","lesson":"9.2.4","title":"Hệ thống lái · Cơ cấu vít - đai ốc bi tuần hoàn","text":"b) Nguyên lý làm việc Khi người lái xoay vành tay lái, trục vít quay tạo lực kéo xoắn lên các viên bi thép nằm giữa vít và đai ốc. - Các viên bi lăn theo rãnh ren, đẩy đai ốc tịnh tiến theo chiều dọc trục. - Đến cuối rãnh, bi được dẫn về đầu rãnh qua ống dẫn và tạo chuyển động tuần hoàn. - Đai ốc tịnh tiến làm cung răng quay, kéo theo đòn quay đứng quay và truyền chuyển động tới dẫn động lái. Ma sát trượt được thay bằng ma sát lăn gần như hoàn toàn, cho hiệu suất cao, lực điều khiển nhẹ, độ bền cao. Cơ cấu này phù hợp với các xe tải nặng, xe buýt hoặc các xe du lịch thế hệ mới có tích hợp trợ lực.","pages":[20]},{"id":"s1429","kind":"pdf","lesson":"9.2.4","title":"Hệ thống lái · Cơ cấu vít - đai ốc bi tuần hoàn","text":"Cơ cấu lái bi tuần hoàn được sử dụng phổ biến trên xe tải hạng nặng, xe buýt, SUV cỡ lớn và một số xe sang cao cấp như: Toyota Hilux, Isuzu NPR, BMW 5 Series (E39); Hyundai Mighty/HD series (HD65, HD72, HD99, HD120, Mighty EX); Isuzu N-Series (NQR, NPR, NKR), F- Series; Hino 300, 500, 700 series; Thaco Ollin, Frontier, Auman, Forland; Fuso Fighter, Canter; Xe khách Samco, Thaco Town, Thaco Mobihome; Hyundai County, Universe, Aero Town. 1. Sơ đồ dẫn động lái Sơ đồ bố trí chung của hệ thống lái được thể hiện trên Hình 9.9, bao gồm bốn bộ phận chính: vành lái, trục lái, cơ cấu lái và dẫn động lái.","pages":[20]},{"id":"s1430","kind":"pdf","lesson":"9.3.1","title":"Hệ thống lái · Sơ đồ dẫn động lái","text":"Trong đó, dẫn động lái là hệ thống các đòn kéo, đòn quay và khớp cầu tiếp nhận lực từ cơ cấu lái (trực tiếp từ thanh răng hoặc qua đòn quay đứng) để làm quay các bánh xe dẫn hướng, đồng thời thiết lập mối liên kết hình học nhằm đảm bảo động học quay vòng chuẩn xác cho ô tô. a) Cầu dẫn hướng bị động Cầu dẫn hướng bị động (Hình 9.10) có ba chi tiết chính là dầm cầu, cam quay và trụ đứng; trên cầu còn lắp các chi tiết liên quan của hệ thống lái:","pages":[20]},{"id":"s1431","kind":"figure","lesson":"9.3.2","title":"Hình 9.10. Cầu dẫn hướng bị động 1. Cơ cấu lái; 2. Khung xe; 3. Dầm cầu dẫn hướng; 4, 10. Trụ đứng; 5,9. Cam quay; 6,8. Đòn bên hình thang lái; 7. Đòn ngang hình thang lái; 11. Đòn quay ngang; 12. Đòn kéo","text":"Hình 9.10. Cầu dẫn hướng bị động 1. Cơ cấu lái; 2. Khung xe; 3. Dầm cầu dẫn hướng; 4, 10. Trụ đứng; 5,9. Cam quay; 6,8. Đòn bên hình thang lái; 7. Đòn ngang hình thang lái; 11. Đòn quay ngang; 12. Đòn kéo","pages":[21],"figure":{"number":"9.10","caption":"Hình 9.10. Cầu dẫn hướng bị động 1. Cơ cấu lái; 2. Khung xe; 3. Dầm cầu dẫn hướng; 4, 10. Trụ đứng; 5,9. Cam quay; 6,8. Đòn bên hình thang lái; 7. Đòn ngang hình thang lái; 11. Đòn quay ngang; 12. Đòn kéo"}},{"id":"s1432","kind":"figure","lesson":"9.3.2","title":"Hình 9.11. Bánh xe chủ động cầu dẫn hướng 1. Vỏ cầu; 2. Khớp các-đăng đồng tốc; 3. Trụ đứng; 4. Trống phanh; 5. Moay-ơ bánh xe; 6. Bích truyền động; 7. Bán trục phía ngoài; 8. Ống dẫn khí bơm lốp; 9, 12. Cam quay; 10. Bu-lông bánh xe; 11. Vành bánh xe; 13. Ổ bi trụ đứng; 14. Đòn quay ngang dẫn động","text":"Hình 9.11. Bánh xe chủ động cầu dẫn hướng 1. Vỏ cầu; 2. Khớp các-đăng đồng tốc; 3. Trụ đứng; 4. Trống phanh; 5. Moay-ơ bánh xe; 6. Bích truyền động; 7. Bán trục phía ngoài; 8. Ống dẫn khí bơm lốp; 9, 12. Cam quay; 10. Bu-lông bánh xe; 11. Vành bánh xe; 13. Ổ bi trụ đứng; 14. Đòn quay ngang dẫn động","pages":[21],"figure":{"number":"9.11","caption":"Hình 9.11. Bánh xe chủ động cầu dẫn hướng 1. Vỏ cầu; 2. Khớp các-đăng đồng tốc; 3. Trụ đứng; 4. Trống phanh; 5. Moay-ơ bánh xe; 6. Bích truyền động; 7. Bán trục phía ngoài; 8. Ống dẫn khí bơm lốp; 9, 12. Cam quay; 10. Bu-lông bánh xe; 11. Vành bánh xe; 13. Ổ bi trụ đứng; 14. Đòn quay ngang dẫn động"}},{"id":"s1433","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"- Dầm cầu: Chịu tải trọng của thân xe phân bố xuống cầu dẫn hướng, đồng thời làm giá đỡ cho toàn bộ cụm bánh xe và hệ thống treo. - Cam quay: Đóng vai trò là giá đỡ ngõng trục của moay-ơ bánh xe, tiếp nhận lực từ hệ thống dẫn động lái để làm quay cụm bánh xe dẫn hướng. - Trụ đứng: Là chi tiết chốt tạo liên kết bản lề giữa cam quay và dầm cầu, thiết lập trục quay hình học cho cụm bánh xe dẫn hướng khi ô tô quay vòng. b) Cầu dẫn hướng chủ động Cầu dẫn hướng chủ động (Hình 9.11) thường được sử dụng trên các xe dẫn động cầu trước (FWD), xe dẫn động 4 bánh toàn thời gian (AWD/4WD) hoặc xe nhiều cầu, trong đó cầu dẫn hướng đồng thời là cầu chủ động. lái; 15. Bán trục phía trong.","pages":[21]},{"id":"s1434","kind":"figure","lesson":"9.3.2","title":"Hình 9.12. Trục và vành tay lái 1. Vành tay lái; 2. Giá đỡ dễ vỡ; 3. Ống trục lái; 4. Trục lái; 5. Cần nghiêng; 6. Tấm giữ;","text":"Hình 9.12. Trục và vành tay lái 1. Vành tay lái; 2. Giá đỡ dễ vỡ; 3. Ống trục lái; 4. Trục lái; 5. Cần nghiêng; 6. Tấm giữ;","pages":[22],"figure":{"number":"9.12","caption":"Hình 9.12. Trục và vành tay lái 1. Vành tay lái; 2. Giá đỡ dễ vỡ; 3. Ống trục lái; 4. Trục lái; 5. Cần nghiêng; 6. Tấm giữ;"}},{"id":"s1435","kind":"figure","lesson":"9.3.2","title":"Hình 9.13. Kết cấu trục lái 1. Giá đỡ cong; 2. Thân xe; 3. Giá đỡ dễ vỡ; 4. Trục lái chính (phía trên); 5. Chốt nhựa;","text":"Hình 9.13. Kết cấu trục lái 1. Giá đỡ cong; 2. Thân xe; 3. Giá đỡ dễ vỡ; 4. Trục lái chính (phía trên); 5. Chốt nhựa;","pages":[22],"figure":{"number":"9.13","caption":"Hình 9.13. Kết cấu trục lái 1. Giá đỡ cong; 2. Thân xe; 3. Giá đỡ dễ vỡ; 4. Trục lái chính (phía trên); 5. Chốt nhựa;"}},{"id":"s1436","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Mô-men xoắn từ bán trục phía trong (15), truyền qua khớp các-đăng đồng tốc (2) để ra bán trục phía ngoài (7), sau đó qua bích truyền động (6) làm quay moay-ơ bánh xe (5). Song song đó, quá trình dẫn hướng được thực hiện thông qua sự điều khiển của đòn quay ngang dẫn động lái (14). Lực đánh lái làm toàn bộ cụm moay-ơ và bánh xe xoay quanh trục của trụ đứng (3) nhờ sự hỗ trợ của ổ bi trụ đứng (13) và cam quay (9, 12). Tất cả các chi tiết này được lắp đặt trên vỏ cầu (1) và liên kết với cụm bánh xe thông qua bu-lông (10), vành bánh xe (11) cùng cơ cấu phanh như trống phanh (4). 2.","pages":[22]},{"id":"s1437","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Cấu tạo các chi tiết dẫn động lái Hệ thống dẫn động lái gồm nhiều chi tiết phối hợp để truyền lực từ vành tay lái đến cơ cấu lái và đến bánh xe dẫn hướng. a) Vành tay lái Vành tay lái là bộ phận điều khiển chính bố trí trong khoang lái, được gắn với trục lái bằng then hoa hoặc bu-lông (Hình 9.12). 7. Tấm giữ; 8. Chốt; 9. Ống trục lái. 6. Trục lái chính phía dưới","pages":[22]},{"id":"s1438","kind":"figure","lesson":"9.3.2","title":"Hình 9.14. Lắp ghép cầu dẫn hướng không chủ động 1. Moay-ơ bánh xe; 2. Trống phanh; 3. Cam phanh; 4. Bạc lót trụ đứng; 5. Đòn quay ngang; 6. Đòn kéo dọc; 7. Dầm cầu; 8. Đòn ngang hình thang lái; 9. Trụ đứng; 10. Guốc","text":"Hình 9.14. Lắp ghép cầu dẫn hướng không chủ động 1. Moay-ơ bánh xe; 2. Trống phanh; 3. Cam phanh; 4. Bạc lót trụ đứng; 5. Đòn quay ngang; 6. Đòn kéo dọc; 7. Dầm cầu; 8. Đòn ngang hình thang lái; 9. Trụ đứng; 10. Guốc","pages":[23],"figure":{"number":"9.14","caption":"Hình 9.14. Lắp ghép cầu dẫn hướng không chủ động 1. Moay-ơ bánh xe; 2. Trống phanh; 3. Cam phanh; 4. Bạc lót trụ đứng; 5. Đòn quay ngang; 6. Đòn kéo dọc; 7. Dầm cầu; 8. Đòn ngang hình thang lái; 9. Trụ đứng; 10. Guốc"}},{"id":"s1439","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Trục lái (Hình 9.13) là cơ cấu đóng vai trò truyền lực (mô-men xoắn) trực tiếp từ vành tay lái xuống cơ cấu lái. Nhằm đáp ứng các yêu cầu về không gian bố trí trên xe cũng như tiêu chuẩn an toàn, trục lái không được chế tạo thành một thanh cứng liền khối mà bao gồm nhiều đoạn ghép nối với nhau: - Trục lái chính phía trên được gắn kết trực tiếp với vành tay lái để tiếp nhận thao tác điều khiển được trang bị khớp lồng (ống trượt lồng vào nhau), cho phép trục lái có khả năng tự động co rút lại khi xảy ra va chạm trực diện, qua đó hấp thụ xung lực và giảm thiểu chấn thương cho vùng ngực của người điều khiển. - Khớp trượt có nhiệm vụ bảo đảm chiều dài tổng thể của trục lái có thể thay đổi.","pages":[23]},{"id":"s1440","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Sự co giãn này không chỉ phục vụ người lái điều chỉnh vị trí vành tay lái cho phù hợp, mà còn giúp hấp thụ những dao động của khung gầm truyền ngược lên hệ thống lái trong quá trình xe vận hành. - Khớp chữ thập (khớp các-đăng): Trong thực tế bố trí cụm lái, trục của vành tay lái và trục đầu vào của cơ cấu lái thường không nằm trên cùng một đường thẳng. Do đó, khớp chữ thập được sử dụng để duy trì khả năng truyền mô-men lái liên tục ngay cả khi trục lái bị bẻ góc hoặc lệch trục so với cơ cấu lái. c) Trụ đứng (trụ quay đứng) Trụ đứng (9) Hình 9.14 là trục chính để cụm bánh xe dẫn hướng có thể xoay quanh đó mỗi khi xe thực hiện việc chuyển hướng. Chi tiết này có biên dạng hình trụ, thường được bố trí ở hai đầu của dầm cầu trước. Trong quá trình vận hành, trụ đứng phải chịu tải trọng đứng từ trọng lượng xe dội xuống cũng như các mô-men quay sinh ra khi bẻ lái.","pages":[23]},{"id":"s1441","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Về cấu trúc liên kết, chi tiết này được lắp chặt cố định với cam quay và kết nối với dầm cầu thông qua hệ thống bạc lót (4) hoặc ổ bi đũa.","pages":[23]},{"id":"s1442","kind":"figure","lesson":"9.3.2","title":"Hình 9.15. Hệ thống treo độc lập của bánh xe chủ động dẫn hướng 1. Đĩa phanh; 2. Moay-ơ bánh xe; 3. Bánh xe; 4. Đòn đứng; 5, 13. Khớp cầu; 6. Đòn trên;","text":"Hình 9.15. Hệ thống treo độc lập của bánh xe chủ động dẫn hướng 1. Đĩa phanh; 2. Moay-ơ bánh xe; 3. Bánh xe; 4. Đòn đứng; 5, 13. Khớp cầu; 6. Đòn trên;","pages":[24],"figure":{"number":"9.15","caption":"Hình 9.15. Hệ thống treo độc lập của bánh xe chủ động dẫn hướng 1. Đĩa phanh; 2. Moay-ơ bánh xe; 3. Bánh xe; 4. Đòn đứng; 5, 13. Khớp cầu; 6. Đòn trên;"}},{"id":"s1443","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Cấu tạo chi tiết của cụm trụ đứng bao gồm các phần chính sau: Thân trụ: Thường được chế tạo dưới dạng thanh thép đặc hoặc rỗng, có kích thước đường kính và chiều dài phù hợp với kết cấu của cầu xe. Bề mặt thân trụ được gia công cơ khí chính xác và tôi cứng nhằm tăng cường khả năng chịu tải cũng như chống mài mòn. Đầu trụ (trên và dưới): Các phần đầu của trụ đứng được thiết kế dạng lỗ hoặc ngàm chuyên dụng. Khu vực này đóng vai trò là điểm định vị để lắp đặt hệ thống bạc lót, ổ bi và khớp quay. Cổ trụ quay: Là bộ phận đảm nhận việc liên kết trực tiếp với cam quay (11), giữ nhiệm vụ truyền chuyển động từ hệ thống đòn dẫn động lái ra cụm bánh xe. Phớt chắn dầu - mỡ: Được bố trí xung quanh các khu vực khớp nối chuyển động.","pages":[24]},{"id":"s1444","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Bộ phận này có nhiệm vụ ngăn chặn chất bôi trơn bị rò rỉ ra ngoài, đồng thời tạo lớp màng bảo vệ ngăn không cho nước, bụi bẩn và tạp chất xâm nhập vào các bề mặt đang ma sát. Trụ đứng trên hệ thống treo độc lập (Hình 9.15 và Hình 9.16): - Trên các dòng xe hiện đại sử dụng hệ thống treo độc lập (Hình 9.15): Đối với hệ thống treo hai tay đòn (tay đòn kép): Hình 9.15, đòn đứng (4) được thiết kế với hai điểm neo giữ ở phía trên và phía dưới. Các vị trí này được dùng để bắt khớp cầu (5 và 13) hoặc các bạc cao su, qua đó liên kết với đòn trên (6) và đòn dưới (11). Cơ cấu này giúp bánh xe di chuyển ổn định theo phương thẳng đứng khi vấp phải mấp mô mặt đường, đồng thời cho phép bánh xe xoay quanh trục nối hai khớp cầu khi người lái điều khiển vành tay lái. 7, 9. Khớp trụ; 8. Khung xe; 10. Lò xo; 11. Đòn dưới; 12. Ụ hạn chế; 14. Bán trục; 15.","pages":[24]},{"id":"s1445","kind":"figure","lesson":"9.3.2","title":"Hình 9.16. Hệ thống treo độc lập của bánh xe dẫn hướng không chủ động 1. Khung xe; 2. Lò xo; 3. Giảm chấn; 4, 15. Khớp trụ; 5. Đòn đứng; 6. Đòn trên; 7, 13.","text":"Hình 9.16. Hệ thống treo độc lập của bánh xe dẫn hướng không chủ động 1. Khung xe; 2. Lò xo; 3. Giảm chấn; 4, 15. Khớp trụ; 5. Đòn đứng; 6. Đòn trên; 7, 13.","pages":[25],"figure":{"number":"9.16","caption":"Hình 9.16. Hệ thống treo độc lập của bánh xe dẫn hướng không chủ động 1. Khung xe; 2. Lò xo; 3. Giảm chấn; 4, 15. Khớp trụ; 5. Đòn đứng; 6. Đòn trên; 7, 13."}},{"id":"s1446","kind":"figure","lesson":"9.3.2","title":"Hình 9.17. Cam quay 1. Khớp cầu; 2. Cam quay; 3. Gối đỡ trên; 4. Gối đỡ dưới; 5. Moay-ơ","text":"Hình 9.17. Cam quay 1. Khớp cầu; 2. Cam quay; 3. Gối đỡ trên; 4. Gối đỡ dưới; 5. Moay-ơ","pages":[25],"figure":{"number":"9.17","caption":"Hình 9.17. Cam quay 1. Khớp cầu; 2. Cam quay; 3. Gối đỡ trên; 4. Gối đỡ dưới; 5. Moay-ơ"}},{"id":"s1447","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Đối với hệ thống treo McPherson: Cụm trụ đứng (giá đỡ moay-ơ) phía trên được liên kết trực tiếp với cụm giảm chấn, trong khi phần phía dưới liên kết với tay đòn dưới thông qua một khớp cầu duy nhất. Ở kết cấu này, trục quay lái (trục tưởng tượng mà bánh xe sẽ quay quanh nó khi bẻ lái) được xác định là đường thẳng nối trực tiếp từ tâm ổ đỡ phía trên của cụm giảm chấn đi qua tâm của khớp cầu nằm ở phía dưới. Khớp cầu; 8. Bánh xe; 9. Trống phanh; 10. Bu-lông bánh xe; 11. Moay-ơ bánh xe; 12. d) Cam quay Cam quay (Hình 9.17) là bộ phận trung gian giữa trụ đứng và moay-ơ bánh xe, truyền chuyển động từ đòn quay sang bánh xe. Trên cam quay thường có tai để gắn khớp cầu hoặc đòn quay ngang.","pages":[25]},{"id":"s1448","kind":"figure","lesson":"9.3.2","title":"Hình 9.18 thể hiện lắp ghép giữa dầm cầu (4), trụ đứng (2) và cam quay (1). Trụ đứng được lắp chặt với dầm cầu và cố định bằng chốt định vị. Cam quay được lắp với trụ đứng thông qua bạc lót (chi tiết (3) trên Hình 9.18a, b, c) hoặc ổ bi đũa (chi tiết (6) và (7) trên Hình 9.18d). Trên cam quay (1) có bố trí các vị trí để lắp các chi tiết của hệ thống dẫn động lái.","text":"Hình 9.18 thể hiện lắp ghép giữa dầm cầu (4), trụ đứng (2) và cam quay (1). Trụ đứng được lắp chặt với dầm cầu và cố định bằng chốt định vị. Cam quay được lắp với trụ đứng thông qua bạc lót (chi tiết (3) trên Hình 9.18a, b, c) hoặc ổ bi đũa (chi tiết (6) và (7) trên Hình 9.18d). Trên cam quay (1) có bố trí các vị trí để lắp các chi tiết của hệ thống dẫn động lái.","pages":[26],"figure":{"number":"9.18","caption":"Hình 9.18 thể hiện lắp ghép giữa dầm cầu (4), trụ đứng (2) và cam quay (1). Trụ đứng được lắp chặt với dầm cầu và cố định bằng chốt định vị. Cam quay được lắp với trụ đứng thông qua bạc lót (chi tiết (3) trên Hình 9.18a, b, c) hoặc ổ bi đũa (chi tiết (6) và (7) trên Hình 9.18d). Trên cam quay (1) có bố trí các vị trí để lắp các chi tiết của hệ thống dẫn động lái."}},{"id":"s1449","kind":"figure","lesson":"9.3.2","title":"Hình 9.18. Các kiểu lắp ghép dầm cầu, trụ đứng và cam quay 1. Cam quay; 2. Trụ đứng; 3. Bạc; 4. Dầm cầu; 5. Ổ bi đỡ; 6, 7. Ổ bi đũa.","text":"Hình 9.18. Các kiểu lắp ghép dầm cầu, trụ đứng và cam quay 1. Cam quay; 2. Trụ đứng; 3. Bạc; 4. Dầm cầu; 5. Ổ bi đỡ; 6, 7. Ổ bi đũa.","pages":[26],"figure":{"number":"9.18","caption":"Hình 9.18. Các kiểu lắp ghép dầm cầu, trụ đứng và cam quay 1. Cam quay; 2. Trụ đứng; 3. Bạc; 4. Dầm cầu; 5. Ổ bi đỡ; 6, 7. Ổ bi đũa."}},{"id":"s1450","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Trường hợp người lái ngồi bên trái (theo luật đi đường bên phải), vị trí A lắp với đòn quay ngang của dẫn động lái, đòn quay ngang nhận lực người lái từ vành tay lái truyền đến. Vị trí B để lắp với đòn bên của hình thang lái, dẫn động sang bánh xe phải. Trường hợp người lái ngồi bên phải (theo luật đi đường bên trái), điểm A nằm ở cam quay bên phải. e) Moay-ơ bánh xe Moay-ơ bánh xe là bộ phận liên kết trực tiếp và quay đồng tốc cùng với bánh xe. Đối với cầu chủ động, moay-ơ được kết nối với bán trục nhận mô-men xoắn, trong khi ở cầu bị động, chi tiết này sẽ quay tự do. Để đảm bảo khả năng chịu tải và quay êm, moay-ơ thường được trang bị hệ thống ổ bi đôi.","pages":[26]},{"id":"s1451","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Mặc dù cấu tạo chi tiết của moay-ơ có thể khác tùy thuộc vào từng dòng xe và thiết kế của hệ thống treo, nhưng nhìn chung đều bao gồm các phần cấu thành chính sau: Thân moay-ơ: Thường có thiết kế dạng hình trụ rỗng, được chế tạo từ vật liệu thép đúc hoặc các loại hợp kim đặc biệt đảm bảo độ cứng và chịu lực. Kết cấu thân moay-ơ bao gồm một lỗ trung tâm để lắp ghép ổ bi, cùng với phần gờ mặt bích có gia công các vị trí để bắt chặt vành bánh xe thông qua bu-lông.","pages":[26]},{"id":"s1452","kind":"figure","lesson":"9.3.2","title":"Hình 9.19. Lắp ghép đòn quay và đòn kéo dẫn động từ cơ cấu lái đến bánh xe dẫn hướng 1, 9. Đòn quay; 2. Đòn kéo; 3, 5, 13, 15. Đế rô-tuyn; 4, 14. Rô-tuyn; 6, 12. Lò xo; 7, 17.","text":"Hình 9.19. Lắp ghép đòn quay và đòn kéo dẫn động từ cơ cấu lái đến bánh xe dẫn hướng 1, 9. Đòn quay; 2. Đòn kéo; 3, 5, 13, 15. Đế rô-tuyn; 4, 14. Rô-tuyn; 6, 12. Lò xo; 7, 17.","pages":[27],"figure":{"number":"9.19","caption":"Hình 9.19. Lắp ghép đòn quay và đòn kéo dẫn động từ cơ cấu lái đến bánh xe dẫn hướng 1, 9. Đòn quay; 2. Đòn kéo; 3, 5, 13, 15. Đế rô-tuyn; 4, 14. Rô-tuyn; 6, 12. Lò xo; 7, 17."}},{"id":"s1453","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Ổ bi bánh xe: Thường sử dụng loại ổ bi đôi hoặc ổ bi côn, được ép chặt vào bên trong lỗ trung tâm của moay-ơ hoặc được lắp trực tiếp trên ngõng trục của cam quay. Trên nhiều dòng xe hiện đại, ổ bi được chế tạo gắn liền với moay-ơ thành một cụm chi tiết thống nhất (bạc moay-ơ tích hợp), giúp tăng độ bền bỉ, độ chính xác và phù hợp hơn trong quá trình bảo dưỡng. Ngoài ra, trên các dòng xe ô tô hiện đại được trang bị hệ thống chống bó cứng phanh (ABS) hoặc hệ thống cân bằng ổn định điện tử, trên cụm moay-ơ thường được tích hợp thêm vòng từ tính hoặc vành răng.","pages":[27]},{"id":"s1454","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Các chi tiết này kết hợp với cảm biến để liên tục đo đạc và gửi tín hiệu tốc độ quay của bánh xe về bộ điều khiển trung tâm. f) Đòn quay đứng, đòn quay ngang, thanh kéo dọc và khớp cầu Các chi tiết này thuộc cụm dẫn động lái, làm nhiệm vụ truyền lực từ cơ cấu lái đến các bánh xe dẫn hướng: - Đòn quay đứng: Thường được lắp ghép trực tiếp với trục ra của cơ cấu lái để tiếp nhận mô-men. - Đòn quay ngang: Làm nhiệm vụ tiếp nhận chuyển động và truyền lực quay sang cam quay thông qua cơ cấu khớp cầu. - Thanh kéo dọc (đòn kéo): Là đòn liên kết trung gian từ đòn quay đứng đến đòn quay ngang, có đặc điểm di chuyển chủ yếu theo phương dọc của xe. Hai đầu của thanh kéo được trang bị các rô-tuyn (khớp cầu) để bảo đảm biên độ hoạt động khi xe đánh lái. Chốt hãm; 8, 16. Đai ốc; 10, 11. Vú mỡ.","pages":[27]},{"id":"s1455","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Đặc điểm cấu tạo và lắp ghép (Hình 9.19): Hình 9.19 thể hiện sơ đồ lắp ghép hai đòn quay và đòn kéo dẫn động từ cơ cấu lái đến bánh xe dẫn hướng, thường được ứng dụng trên các dòng xe tải trung bình. Về mặt động học, do hai đòn quay (chi tiết 1 và chi tiết 9) hoạt động xoay trong hai mặt phẳng vuông góc với nhau, nên các liên kết giữa đòn quay và đòn kéo bắt buộc phải sử dụng khớp cầu. Cấu tạo chi tiết của một khớp cầu bao gồm: rô-tuyn","pages":[27]},{"id":"s1456","kind":"figure","lesson":"9.3.2","title":"Hình 9.20. Lắp ghép đòn quay và đòn kéo dẫn động từ cơ cấu lái đến bánh xe dẫn hướng","text":"Hình 9.20. Lắp ghép đòn quay và đòn kéo dẫn động từ cơ cấu lái đến bánh xe dẫn hướng","pages":[28],"figure":{"number":"9.20","caption":"Hình 9.20. Lắp ghép đòn quay và đòn kéo dẫn động từ cơ cấu lái đến bánh xe dẫn hướng"}},{"id":"s1457","kind":"figure","lesson":"9.3.2","title":"Hình 9.21. Sơ đồ bố trí chung hệ thống lái cơ khí 1. Vành tay lái; 2. Trục lái; 3. Trục các-đăng; 4. Cơ cấu lái; 5, 10. Đòn kéo bên; 6. Cam quay; 7. Đòn quay ngang; 8. Dầm cầu; 9. Cam quay; 11. Thanh lái ngang; 12. Đòn kéo","text":"Hình 9.21. Sơ đồ bố trí chung hệ thống lái cơ khí 1. Vành tay lái; 2. Trục lái; 3. Trục các-đăng; 4. Cơ cấu lái; 5, 10. Đòn kéo bên; 6. Cam quay; 7. Đòn quay ngang; 8. Dầm cầu; 9. Cam quay; 11. Thanh lái ngang; 12. Đòn kéo","pages":[28],"figure":{"number":"9.21","caption":"Hình 9.21. Sơ đồ bố trí chung hệ thống lái cơ khí 1. Vành tay lái; 2. Trục lái; 3. Trục các-đăng; 4. Cơ cấu lái; 5, 10. Đòn kéo bên; 6. Cam quay; 7. Đòn quay ngang; 8. Dầm cầu; 9. Cam quay; 11. Thanh lái ngang; 12. Đòn kéo"}},{"id":"s1458","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"hình cầu (4) và (14); cụm đế giữ rô-tuyn (3), (5), (13), (15) (mỗi rô-tuyn được kẹp chặt bởi 2 đế); lò xo ép (6), (12) và đai ốc giữ (8), (16). Toàn bộ cụm chi tiết rô-tuyn, đế giữ và lò xo được bố trí lắp đặt gọn vào bên trong phần thân rỗng của thanh kéo. Lò xo có tác dụng tạo ra lực ép vĩnh cửu, luôn giữ cho các đế áp sát vào bề mặt cầu của rô-tuyn, giúp triệt tiêu độ rơ lỏng phát sinh. Các đai ốc (8), (16) dùng để cố định cụm đế và được khóa hãm an toàn bằng chốt (7) và (17). Để liên kết với đòn quay, một phía của rô-tuyn được gia công theo dạng trụ côn, qua đó các đòn quay (1), (9) sẽ được định vị và lắp ghép chặt vào bề mặt này. Đáng chú ý, xét theo chiều không gian trên Hình 9.20, trục của rô-tuyn (9) được bố trí vuông góc với trục của rô-tuyn (6). 1, 5. Đòn quay; 2, 6. Rô-tuyn; 3, 4, 11, 18. Đế rô-tuyn; 7, 12. Đai ốc; 8, 13.","pages":[28]},{"id":"s1459","kind":"pdf","lesson":"9.3.2","title":"Hệ thống lái · Cấu tạo các chi tiết dẫn động lái","text":"Lò xo. g) Hình thang lái Hình thang lái là thuật ngữ cơ bản trong hệ thống dẫn động lái, chỉ hình học bố trí các thanh liên kết giữa cơ cấu lái và hai bánh xe dẫn hướng, tạo thành một hình thang. dọc; 13, 14. Đòn quay đứng.","pages":[28]},{"id":"s1460","kind":"figure","lesson":"9.3.2","title":"Hình 9.22. Dẫn động lái 1. Đòn cam lái; 2. Cơ cấu lái; 3. Đòn lắc; 4. Đòn đỡ; 5. Cam lái; 6, 8. Thanh lái; 7. Thanh","text":"Hình 9.22. Dẫn động lái 1. Đòn cam lái; 2. Cơ cấu lái; 3. Đòn lắc; 4. Đòn đỡ; 5. Cam lái; 6, 8. Thanh lái; 7. Thanh","pages":[29],"figure":{"number":"9.22","caption":"Hình 9.22. Dẫn động lái 1. Đòn cam lái; 2. Cơ cấu lái; 3. Đòn lắc; 4. Đòn đỡ; 5. Cam lái; 6, 8. Thanh lái; 7. Thanh"}},{"id":"s1461","kind":"figure","lesson":"9.3.3","title":"Hình 9.23. Các góc đặt bánh xe dẫn hướng","text":"Hình 9.23. Các góc đặt bánh xe dẫn hướng","pages":[29],"figure":{"number":"9.23","caption":"Hình 9.23. Các góc đặt bánh xe dẫn hướng"}},{"id":"s1462","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Cấu trúc hình thang lái gồm 4 điểm nối tạo thành 4 cạnh chính (Hình 9.21 và Hình 9.22). Tại mỗi điểm nối giữa các thanh có rô-tuyn (khớp cầu), cho phép các thanh chuyển động tương đối khi đánh lái và dao động theo hệ thống treo. 3. Các góc đặt bánh xe dẫn hướng Ngoài chức năng đỡ toàn bộ tải trọng của ô tô và tạo nên chuyển động của xe, bánh xe dẫn hướng còn đảm nhận nhiệm vụ dẫn hướng. Vì vậy, bánh xe dẫn hướng được bố trí với các góc đặt (Hình 9.23) nhằm: - Bảo đảm điều kiện truyền lực tốt nhất giữa bánh xe với mặt đường; - Bảo đảm ổn định chuyển động của ô tô khi đi thẳng cũng như khi quay vòng. Các giá trị góc đặt bánh xe không có một giá trị “tốt” cố định cho mọi ô tô. Chúng được xác định theo thiết kế của hệ thống treo, hệ thống lái, lốp, tải trọng và đặc tính động lực học mong muốn của từng loại xe.","pages":[29]},{"id":"s1463","kind":"figure","lesson":"9.3.3","title":"Hình 9.24. Góc camber () d: Mặt phẳng dọc trục; c: Khoảng camber","text":"Hình 9.24. Góc camber () d: Mặt phẳng dọc trục; c: Khoảng camber","pages":[30],"figure":{"number":"9.24","caption":"Hình 9.24. Góc camber () d: Mặt phẳng dọc trục; c: Khoảng camber"}},{"id":"s1464","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":": Góc nghiêng ngang bánh xe – góc camber;  Góc nghiêng ngang trụ lái đứng – góc kingpin;  Góc nghiêng dọc trụ lái đứng – góc caster; a: Khoảng cách phía trước của 2 bánh xe; b: Khoảng cách phía sau của 2 bánh xe. a) Góc nghiêng ngang của bánh xe dẫn hướng (góc camber – góc ) Góc camber là góc tạo bởi mặt phẳng trung tuyến của bánh xe và mặt phẳng thẳng đứng (nhìn từ phía trước/sau xe). Góc nghiêng này được thể hiện trên Hình 9.24. Giá trị và dấu của góc camber được xác định theo thiết kế của từng loại xe và hệ thống treo. Tùy kết cấu, xe có thể sử dụng camber dương, camber gần bằng không hoặc camber âm.","pages":[30]},{"id":"s1465","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Bố trí bánh xe dẫn hướng với góc nghiêng dương có tác dụng: - Khi bánh xe chịu tải, khắc phục các khe hở trong kết cấu, góc nghiêng ngang giảm nhỏ, đảm bảo đa số thời gian bánh xe lăn trong mặt phẳng lăn giúp bánh xe có khả năng tiếp nhận phản lực tốt hơn và tạo sự mài mòn đều bề mặt lăn của lốp; - Phản lực từ mặt đường tác dụng lên bánh xe có xu hướng đẩy bánh xe vào trong, khắc phục độ rơ ổ bi moay-ơ bánh xe; - Giảm cánh tay đòn \"c\", tức là giảm nhỏ mô-men cản quay vòng, đồng thời giảm lực trên vành tay lái. Bố trí bánh xe dẫn hướng với góc nghiêng vào trong (góc camber âm) làm giảm khả năng trượt ngang của bánh xe ngoài dưới tác dụng của lực ly tâm khi chuyển động với vận tốc cao. Camber dương (Hình 9.25b): bánh xe nghiêng ra phía ngoài so với phương thẳng đứng. Giá trị camber được lựa chọn theo yêu cầu thiết kế hệ thống treo và động học bánh xe.","pages":[30]},{"id":"s1466","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Trong một số kết cấu, camber dương tĩnh được sử dụng nhằm bù trừ sự thay đổi camber trong quá trình làm việc của hệ thống treo và các biến dạng đàn hồi của các chi tiết.","pages":[30]},{"id":"s1467","kind":"figure","lesson":"9.3.3","title":"Hình 9.25. Các dạng góc camber a) Camber bằng không; b) Camber dương – bánh xe nghiêng ra phía ngoài; c) Camber","text":"Hình 9.25. Các dạng góc camber a) Camber bằng không; b) Camber dương – bánh xe nghiêng ra phía ngoài; c) Camber","pages":[31],"figure":{"number":"9.25","caption":"Hình 9.25. Các dạng góc camber a) Camber bằng không; b) Camber dương – bánh xe nghiêng ra phía ngoài; c) Camber"}},{"id":"s1468","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"âm – bánh xe nghiêng vào phía trong. Camber âm (Hình 9.25c): bánh xe nghiêng vào phía trong so với phương thẳng đứng. Camber âm thường được sử dụng nhằm cải thiện đặc tính tiếp xúc của lốp với mặt đường khi xe chuyển động và đặc biệt có ý nghĩa đối với khả năng tạo lực ngang khi xe quay vòng. Giá trị camber tối ưu phụ thuộc vào loại xe, kết cấu hệ thống treo, lốp và điều kiện vận hành. b) Góc nghiêng dọc trụ lái đứng (góc caster – góc ) Góc nghiêng dọc trụ đứng (thường gọi là góc caster) là góc hợp bởi đường tâm trụ đứng và phương thẳng đứng trong mặt phẳng dọc xe. Góc caster quy ước là dương khi đường tâm trụ đứng có phần trên nghiêng về phía sau, và là âm khi nghiêng về phía trước. Đa số ô tô hiện đại ứng dụng góc caster dương nhằm tạo mô-men tự trả lái và tăng tính ổn định chuyển động thẳng.","pages":[31]},{"id":"s1469","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Khi kéo dài đường tâm trụ đứng, đường này cắt mặt đường tại một điểm nằm trước tâm vết tiếp xúc của bánh xe một khoảng a. Nhờ có vết caster này, dưới tác dụng của lực bên từ mặt đường, hệ thống sẽ sinh ra mô-men hồi vị giúp bánh xe tự động quay về vị trí chạy thẳng sau khi thực hiện xong quá trình quay vòng.","pages":[31]},{"id":"s1470","kind":"figure","lesson":"9.3.3","title":"Hình 9.27. Độ ổn định chạy trên đường thẳng nhờ có góc caster a) Khi không có góc caster; b) Khi có góc caster; c) Bánh xe hồi vị nhờ có khoảng caster.","text":"Hình 9.27. Độ ổn định chạy trên đường thẳng nhờ có góc caster a) Khi không có góc caster; b) Khi có góc caster; c) Bánh xe hồi vị nhờ có khoảng caster.","pages":[32],"figure":{"number":"9.27","caption":"Hình 9.27. Độ ổn định chạy trên đường thẳng nhờ có góc caster a) Khi không có góc caster; b) Khi có góc caster; c) Bánh xe hồi vị nhờ có khoảng caster."}},{"id":"s1471","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"O, O’: Tâm điểm giữa tiếp xúc lốp với mặt đường F’1, F’2: Lực thành phần F’ Khi ô tô quay vòng, việc quay các bánh xe dẫn hướng quanh trục trụ đứng có góc caster sẽ làm thay đổi độ nghiêng của bánh xe và tạo ra mô-men kích, làm nâng nhẹ thân xe ở phía tương ứng (Hình 9.27). Dưới tác dụng của trọng lực xe, mô-men kích này sinh ra thành phần lực hồi vị tác động lên hệ thống lái, có xu hướng đưa bánh xe trở về vị trí trung tâm, từ đó duy trì tính ổn định động học khi xe chạy thẳng.","pages":[32]},{"id":"s1472","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Hồi vị bánh xe nhờ có khoảng caster: - Nếu bánh xe có góc caster, giao điểm giữa đường tâm trụ đứng với mặt đường sẽ nằm phía trước tâm điểm tiếp xúc giữa lốp xe với mặt đường. - Vì lốp xe được kéo về phía trước nên lực kéo này sẽ lấn át các lực có xu hướng làm cho bánh xe mất ổn định, giữ cho bánh xe chạy ổn định theo đường thẳng. - Khi bánh xe được chuyển hướng sang một bên (do lái hoặc do trở ngại khi chạy trên đường thẳng) thì sẽ phát sinh các lực bên F2 và F'2. - Các lực bên này có tác dụng làm quay trụ đứng (nhờ có khoảng caster) và có xu hướng hồi vị bánh xe về vị trí ban đầu của nó (lực hồi vị).","pages":[32]},{"id":"s1473","kind":"figure","lesson":"9.3.3","title":"Hình 9.28. Góc nghiêng ngang trụ lái đứng Trục quay này được tạo thành bởi đường nối từ bản lề trụ đứng (kingpin hoặc rô-tuyn trụ đứng) phía trên và phía dưới. Trục quay đứng là đường tưởng tượng nối các tâm khớp quay của cơ cấu dẫn hướng. Đối với hệ thống treo McPherson, trục quay lái được xác định bởi đường nối giữa tâm ổ đỡ phía trên của cụm giảm chấn và tâm khớp cầu phía dưới. Trên thực tế, ở xe hiện đại, góc kingpin thường được tích hợp sẵn vào thiết kế trụ đứng và không điều chỉnh được.","text":"Hình 9.28. Góc nghiêng ngang trụ lái đứng Trục quay này được tạo thành bởi đường nối từ bản lề trụ đứng (kingpin hoặc rô-tuyn trụ đứng) phía trên và phía dưới. Trục quay đứng là đường tưởng tượng nối các tâm khớp quay của cơ cấu dẫn hướng. Đối với hệ thống treo McPherson, trục quay lái được xác định bởi đường nối giữa tâm ổ đỡ phía trên của cụm giảm chấn và tâm khớp cầu phía dưới. Trên thực tế, ở xe hiện đại, góc kingpin thường được tích hợp sẵn vào thiết kế trụ đứng và không điều chỉnh được.","pages":[33],"figure":{"number":"9.28","caption":"Hình 9.28. Góc nghiêng ngang trụ lái đứng Trục quay này được tạo thành bởi đường nối từ bản lề trụ đứng (kingpin hoặc rô-tuyn trụ đứng) phía trên và phía dưới. Trục quay đứng là đường tưởng tượng nối các tâm khớp quay của cơ cấu dẫn hướng. Đối với hệ thống treo McPherson, trục quay lái được xác định bởi đường nối giữa tâm ổ đỡ phía trên của cụm giảm chấn và tâm khớp cầu phía dưới. Trên thực tế, ở xe hiện đại, góc kingpin thường được tích hợp sẵn vào thiết kế trụ đứng và không điều chỉnh được."}},{"id":"s1474","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Với cùng một lực bên, nếu khoảng caster lớn, lực hồi vị bánh xe cũng lớn. Vì vậy, khoảng caster càng lớn thì độ ổn định trên đường thẳng và lực hồi vị càng lớn. c) Góc nghiêng ngang trụ lái đứng (góc kingpin – góc) Góc nghiêng ngang trụ lái đứng là góc nghiêng được đo theo phương ngang của xe (nhìn từ phía đầu ô tô) của trụ lái đứng với mặt phẳng thẳng đứng song song với mặt phẳng đối xứng dọc của xe (Hình 9.28). Kéo dài đường tâm trụ đứng đến mặt đường, điểm cắt của đường kéo dài này với mặt đường cách tâm bánh xe một khoảng c. Khi quay vòng, bánh xe dẫn hướng quay xung quanh trụ đứng. Tại mặt đường, các phản lực dọc của bánh xe với cánh tay đòn c gây nên mô-men quay với trụ đứng. Mô-men do phản lực mặt đường tác dụng với cánh tay đòn đối với trục quay lái tạo ra mô-men có xu hướng đưa bánh xe trở về vị trí cân bằng.","pages":[33]},{"id":"s1475","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Giá trị và chiều của mô-men phụ thuộc vào hình học hệ thống lái, đặc biệt là góc nghiêng ngang trụ lái. d) Độ chụm (hoặc độ doãng) của bánh xe dẫn hướng Độ chụm là độ lệch của phần trước và phần sau bánh xe khi nhìn từ trên xuống. Góc lệch của bánh xe được gọi là góc chụm (Hình 9.29). Giá trị độ chụm của bánh xe dẫn hướng được xác định theo yêu cầu thiết kế, đặc tính động học của hệ thống treo, dẫn động lái và đặc tính bám của lốp. Tùy thuộc vào kết cấu xe, độ chụm có thể mang giá trị dương (chụm), bằng không hoặc âm (doãng). Khi thiết lập độ chụm dương, lực cản lăn từ mặt đường tác dụng ngược chiều chuyển động sẽ tạo ra mô-men quay bánh xe quanh trục trụ đứng thông qua tay đòn c (Hình 9.28).","pages":[33]},{"id":"s1476","kind":"pdf","lesson":"9.3.3","title":"Hệ thống lái · Các góc đặt bánh xe dẫn hướng","text":"Mô-men này có tác dụng triệt tiêu lực lệch hướng, giữ cho các bánh xe lăn song song ở trạng thái động học tối ưu và giảm thiểu mài mòn lốp. - Độ chụm: hai bánh xe hướng vào nhau ở đầu trước. - Độ doãng: hai bánh xe mở rộng đầu trước so với đuôi.","pages":[33]},{"id":"s1477","kind":"figure","lesson":"9.3.3","title":"Hình 9.29. Độ chụm bánh xe dẫn hướng","text":"Hình 9.29. Độ chụm bánh xe dẫn hướng","pages":[34],"figure":{"number":"9.29","caption":"Hình 9.29. Độ chụm bánh xe dẫn hướng"}},{"id":"s1478","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Độ chụm giúp bảo đảm ổn định chuyển động thẳng của xe, hạn chế hiện tượng mòn không đều của lốp và bù trừ độ rơ ổ trục, gối đỡ cũng như ảnh hưởng của hệ thống treo trong điều kiện chuyển động thực tế. IV. HỆ THỐNG LÁI CÓ TRỢ LỰC 1. Hệ thống lái trợ lực thủy lực a) Khái niệm Hệ thống lái trợ lực thủy lực sử dụng áp suất dầu để hỗ trợ người lái khi xoay vành tay lái.","pages":[34]},{"id":"s1479","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Khi hệ thống hoạt động, áp suất thủy lực được tạo ra bởi bơm dầu giúp giảm lực cần thiết tác động lên vành tay lái, đặc biệt khi xe đang đứng yên hoặc chạy chậm. b) Cấu tạo Hệ thống lái trợ lực thủy lực thông thường bao gồm các bộ phận chính sau: - Bơm dầu trợ lực: thường là loại bơm cánh gạt, dẫn động từ trục động cơ qua dây đai. - Van phân phối (van trượt): điều khiển hướng dòng chất lỏng thủy lực đến xi-lanh trợ lực theo hướng quay vành tay lái. - Xi-lanh trợ lực: tích hợp với cơ cấu bánh răng – thanh răng, tác động trực tiếp lên thanh răng để quay bánh lái. - Bình chứa dầu: chứa chất lỏng thủy lực, nối với bơm thông qua ống dẫn hồi. - Đường ống cao áp và hồi: dẫn dầu từ bơm đến van trượt và từ xi-lanh trở về bình chứa. Tùy theo vị trí tương đối giữa van phân phối, xi-lanh lực và cơ cấu lái, trợ lực lái có các kiểu bố trí như Hình 9.30:","pages":[34]},{"id":"s1480","kind":"figure","lesson":"9.4.1","title":"Hình 9.30. Các kiểu bố trí trợ lực lái trên ô tô 1. Van phân phối; 2. Cơ cấu lái; 3. Xi-lanh lực; 4. Bơm dầu","text":"Hình 9.30. Các kiểu bố trí trợ lực lái trên ô tô 1. Van phân phối; 2. Cơ cấu lái; 3. Xi-lanh lực; 4. Bơm dầu","pages":[35],"figure":{"number":"9.30","caption":"Hình 9.30. Các kiểu bố trí trợ lực lái trên ô tô 1. Van phân phối; 2. Cơ cấu lái; 3. Xi-lanh lực; 4. Bơm dầu"}},{"id":"s1481","kind":"figure","lesson":"9.4.1","title":"Hình 9.30a: Van phân phối, xi-lanh lực và cơ cấu lái được bố trí chung một khối. Ở loại này, hệ thống lái có kích thước nhỏ gọn, ít đường ống dẫn và có độ nhạy cao. Tuy nhiên kết cấu hệ thống phức tạp, các chi tiết của dẫn động lái chịu tải lớn. Sử dụng trên xe Zil 130, Zil 131, KAMAZ, và trên các loại xe du lịch, xe tải mới hiện nay như Hyundai Universal, Hino.","text":"Hình 9.30a: Van phân phối, xi-lanh lực và cơ cấu lái được bố trí chung một khối. Ở loại này, hệ thống lái có kích thước nhỏ gọn, ít đường ống dẫn và có độ nhạy cao. Tuy nhiên kết cấu hệ thống phức tạp, các chi tiết của dẫn động lái chịu tải lớn. Sử dụng trên xe Zil 130, Zil 131, KAMAZ, và trên các loại xe du lịch, xe tải mới hiện nay như Hyundai Universal, Hino.","pages":[35],"figure":{"number":"9.30a","caption":"Hình 9.30a: Van phân phối, xi-lanh lực và cơ cấu lái được bố trí chung một khối. Ở loại này, hệ thống lái có kích thước nhỏ gọn, ít đường ống dẫn và có độ nhạy cao. Tuy nhiên kết cấu hệ thống phức tạp, các chi tiết của dẫn động lái chịu tải lớn. Sử dụng trên xe Zil 130, Zil 131, KAMAZ, và trên các loại xe du lịch, xe tải mới hiện nay như Hyundai Universal, Hino."}},{"id":"s1482","kind":"figure","lesson":"9.4.1","title":"Hình 9.30b: Van phân phối, xi-lanh lực và cơ cấu lái bố trí riêng rẽ. Loại này đảm bảo giảm được tải trọng cho đa số các chi tiết của hệ thống lái. Tuy nhiên số lượng các khâu liên kết tăng lên, chiều dài các đường ống tăng và giảm độ nhạy của hệ thống lái. Dùng trên xe GAZ-66.","text":"Hình 9.30b: Van phân phối, xi-lanh lực và cơ cấu lái bố trí riêng rẽ. Loại này đảm bảo giảm được tải trọng cho đa số các chi tiết của hệ thống lái. Tuy nhiên số lượng các khâu liên kết tăng lên, chiều dài các đường ống tăng và giảm độ nhạy của hệ thống lái. Dùng trên xe GAZ-66.","pages":[35],"figure":{"number":"9.30b","caption":"Hình 9.30b: Van phân phối, xi-lanh lực và cơ cấu lái bố trí riêng rẽ. Loại này đảm bảo giảm được tải trọng cho đa số các chi tiết của hệ thống lái. Tuy nhiên số lượng các khâu liên kết tăng lên, chiều dài các đường ống tăng và giảm độ nhạy của hệ thống lái. Dùng trên xe GAZ-66."}},{"id":"s1483","kind":"figure","lesson":"9.4.1","title":"Hình 9.30c: Van phân phối và xi-lanh lực bố trí liền nhau và tách biệt với cơ cấu lái. Loại này giảm được chiều dài các đường ống, đảm bảo an toàn cho hệ thống lái khi xe chạy trên đường xấu. Dùng trên xe Maz-500, KRAZ-255B.","text":"Hình 9.30c: Van phân phối và xi-lanh lực bố trí liền nhau và tách biệt với cơ cấu lái. Loại này giảm được chiều dài các đường ống, đảm bảo an toàn cho hệ thống lái khi xe chạy trên đường xấu. Dùng trên xe Maz-500, KRAZ-255B.","pages":[35],"figure":{"number":"9.30c","caption":"Hình 9.30c: Van phân phối và xi-lanh lực bố trí liền nhau và tách biệt với cơ cấu lái. Loại này giảm được chiều dài các đường ống, đảm bảo an toàn cho hệ thống lái khi xe chạy trên đường xấu. Dùng trên xe Maz-500, KRAZ-255B."}},{"id":"s1484","kind":"figure","lesson":"9.4.1","title":"Hình 9.30d: Van phân phối, cơ cấu lái bố trí liền nhau và tách biệt với xi-lanh lực. Loại này đảm bảo độ nhạy của hệ thống lái cao. Dùng trên xe Ural-375D.","text":"Hình 9.30d: Van phân phối, cơ cấu lái bố trí liền nhau và tách biệt với xi-lanh lực. Loại này đảm bảo độ nhạy của hệ thống lái cao. Dùng trên xe Ural-375D.","pages":[35],"figure":{"number":"9.30d","caption":"Hình 9.30d: Van phân phối, cơ cấu lái bố trí liền nhau và tách biệt với xi-lanh lực. Loại này đảm bảo độ nhạy của hệ thống lái cao. Dùng trên xe Ural-375D."}},{"id":"s1485","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"c) Nguyên lý làm việc Khi vành tay lái ở vị trí trung gian, van phân phối đóng các đường dầu vào xi- lanh, dầu từ bơm hồi thẳng về bình chứa dầu. Khi người lái xoay vành tay lái, van xoay mở thông đường dầu áp lực vào một bên xi-lanh, đồng thời cho dầu ở phía bên kia xi-lanh hồi về bình chứa dầu. Chênh lệch áp suất hai bên pít-tông tạo lực đẩy pít- tông di chuyển, kéo theo thanh răng (hoặc trục vít) giúp quay bánh xe theo hướng người lái mong muốn.","pages":[35]},{"id":"s1486","kind":"figure","lesson":"9.4.1","title":"Hình 9.31. Cấu tạo bơm thủy lực loại cánh gạt 1. Khoang chứa dầu; 2. Van cánh gạt; 3. Rô-to; 4. Van giảm áp; 5. Vỏ bơm","text":"Hình 9.31. Cấu tạo bơm thủy lực loại cánh gạt 1. Khoang chứa dầu; 2. Van cánh gạt; 3. Rô-to; 4. Van giảm áp; 5. Vỏ bơm","pages":[36],"figure":{"number":"9.31","caption":"Hình 9.31. Cấu tạo bơm thủy lực loại cánh gạt 1. Khoang chứa dầu; 2. Van cánh gạt; 3. Rô-to; 4. Van giảm áp; 5. Vỏ bơm"}},{"id":"s1487","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Mức trợ lực phụ thuộc vào độ vặn của thanh xoắn trong van – tức là phụ thuộc lực mà người lái tác dụng. Khi người lái ngừng xoay, lực vặn biến mất, van trở về trung gian, và pít-tông giữ vị trí mới. Nếu trợ lực mất (do chết máy hoặc bơm hỏng), người lái vẫn có thể điều khiển xe nhưng sẽ rất nặng do phải thắng cả lực cản của dầu trong xi-lanh. Ưu điểm: Hệ thống trợ lực thủy lực cho cảm giác lái tự nhiên, phản hồi tương đối tốt về mặt đường. Kết cấu đã được tiêu chuẩn hóa và độ tin cậy cao; lực trợ giúp mạnh mẽ phù hợp cả cho xe nặng. Nhược điểm: Luôn tiêu tốn công suất động cơ (bơm chạy liên tục), tốn nhiên liệu. Cấu tạo nhiều chi tiết (bơm, đường ống, dầu) cần bảo dưỡng; nguy cơ rò rỉ dầu. Đặc biệt, mức trợ lực cố định, thiếu linh hoạt theo tốc độ – dẫn đến việc tay lái có thể quá nhẹ ở tốc độ cao hoặc còn nặng khi tốc độ rất thấp.","pages":[36]},{"id":"s1488","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Các bộ phận chính của hệ thống lái trợ lực thủy lực gồm bơm trợ lực, van điều khiển và xi-lanh trợ lực. d) Bơm trợ lực thủy lực Bơm thường dùng loại bơm cánh gạt do có kết cấu đơn giản, gọn, tạo áp suất ổn định, phù hợp yêu cầu của hệ thống trợ lực (Hình 9.31). Các chi tiết chính gồm: - Vỏ bơm có mặt trong dạng cam lệch tâm. - Rô-to có các rãnh lắp cánh gạt. - Cánh gạt trượt trong rãnh rô-to, tỳ sát vào mặt trong vỏ bơm nhờ lực ly tâm và áp suất dầu. - Cửa hút và cửa đẩy bố trí lệch nhau theo biên dạng cam để tạo khoang hút và khoang nén. - Van điều chỉnh lưu lượng (giữ lưu lượng ổn định) và van an toàn (xả bớt áp khi quá tải) tích hợp trong cụm bơm. Nguyên lý làm việc: Khi rô-to quay (được dẫn động từ puly trục khuỷu qua dây đai), cánh gạt tỳ vào mặt trong stato, tạo các khoang dầu thay đổi thể tích.","pages":[36]},{"id":"s1489","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Ở vùng cửa hút I và III, thể tích khoang tăng nên dầu từ bình chứa bị hút vào cửa A. Ở vùng cửa đẩy II và IV, thể tích khoang giảm khiến cho dầu bị nén và đẩy ra cửa áp suất cao ở cửa B,","pages":[36]},{"id":"s1490","kind":"figure","lesson":"9.4.1","title":"Hình 9.32. Sơ đồ hệ thống lái có trợ lực dùng van trượt và có cơ cấu lái, van điều","text":"Hình 9.32. Sơ đồ hệ thống lái có trợ lực dùng van trượt và có cơ cấu lái, van điều","pages":[37],"figure":{"number":"9.32","caption":"Hình 9.32. Sơ đồ hệ thống lái có trợ lực dùng van trượt và có cơ cấu lái, van điều"}},{"id":"s1491","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"đưa tới van điều khiển. Van điều chỉnh lưu lượng đưa lượng dầu thừa trở lại cửa hút để lưu lượng ra ổn định, trong khi van an toàn xả dầu về bình nếu áp suất vượt giới hạn thiết kế. e) Van điều khiển (van phân phối) Van điều khiển có nhiệm vụ phân phối dầu có áp suất đến một trong hai khoang của xi-lanh trợ lực tùy theo hướng đánh lái, đồng thời xả dầu từ khoang đối diện về bình. Khi vành tay lái ở vị trí trung gian, van ở trạng thái trung gian, dầu từ bơm hồi về bình mà không tạo trợ lực. * Van trượt điều khiển bằng cơ khí Cấu tạo (Hình 9.32): Ống trượt được dịch chuyển dọc trục nhờ cần liên kết cơ khí với trục lái hoặc cơ cấu lái. Cơ cấu lái truyền chuyển động quay đến đòn quay (12). Đòn quay (12) được nối với lõi van điều khiển là con trượt (2).","pages":[37]},{"id":"s1492","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Con trượt (2) tác dụng vào vỏ van (4) thông qua các lò xo (3) và (9); vỏ van (4) và pít-tông sinh lực (7) nối với đòn quay (8) của bánh xe. Con trượt (2), các lò xo (3), (9) và vỏ van (4) đóng vai trò như đòn kéo trong sơ đồ hệ thống lái không có trợ lực. Khi người lái quay vành tay lái, đòn quay (12) đẩy vào con trượt (2), thông qua các lò xo (3), (9) và vỏ van (4) đẩy vào đòn quay (8) làm quay bánh xe. Van điều khiển có 5 cửa: Cửa I và III nối với bơm (13), nhận chất lỏng áp suất cao; cửa II nối với thùng dầu (1); cửa IV nối với khoang A và cửa V nối với khoang B của xi-lanh (6).","pages":[37]},{"id":"s1493","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Khi vành tay lái ở vị trí trung gian, xe đi thẳng, cửa I, III mở, cửa II đóng, chất lỏng áp suất cao từ bơm dầu (13) đi qua các cửa I và III qua cửa V và IV đến cả 2 phía của pít-tông (7), giữ cho bánh xe song song với phương chuyển động của xe và tránh cho bánh xe bị lệch hướng khi chịu chấn động nào đó từ mặt đường. Áp suất chất lỏng trong cả hai khoang A và B cũng có tác dụng ngăn cản các chấn động từ mặt đường lên vành tay lái. khiển, bộ phận sinh lực bố trí độc lập 1. Thùng dầu; 2. Lõi van (con trượt); 3, 9. Lò xo; 4. Vỏ van; 5. Bánh xe; 6, 7. Xi-lanh, pít- tông lực; 8. Đòn quay bánh xe; 10. Cơ cấu lái; 11. Vành tay lái; 12. Đòn quay cơ cấu lái; 13. Khi người lái đánh vành tay lái sang trái, đòn quay (12) đẩy con trượt (2) sang phải. Con trượt (2) thông qua lò xo (3) đẩy vào vỏ (4) và vỏ (4) đẩy vào đòn quay (8) để làm quay bánh xe (5).","pages":[37]},{"id":"s1494","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Thoạt đầu lực từ vành tay lái chưa đủ thắng lực cản bánh xe, bánh xe sẽ không quay do đó vỏ van (4) chưa di chuyển. Vì thế con trượt (2) sẽ dịch","pages":[37]},{"id":"s1495","kind":"figure","lesson":"9.4.1","title":"Hình 9.33. Hệ thống lái trục vít - đai ốc - bi - thanh răng - cung răng có trợ lực thủy lực","text":"Hình 9.33. Hệ thống lái trục vít - đai ốc - bi - thanh răng - cung răng có trợ lực thủy lực","pages":[38],"figure":{"number":"9.33","caption":"Hình 9.33. Hệ thống lái trục vít - đai ốc - bi - thanh răng - cung răng có trợ lực thủy lực"}},{"id":"s1496","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"chuyển sang phải so với vỏ (4) và lò xo (3) bị nén lại. Do vỏ (4) đứng yên, con trượt (2) di chuyển sang phải nên cửa I bị đóng lại và cửa II được mở ra. Thời điểm đóng cửa I và mở cửa II tương ứng với lực trên vành tay lái đạt giá trị Fo. Chất lỏng từ khoang B thoát qua cửa V, rồi qua cửa II về thùng dầu (1). Áp suất chất lỏng ở khoang A đẩy pít- tông sang phải, kéo theo đòn quay (8) và làm quay bánh xe (5) sang trái. Khi người lái đánh vành tay lái sang phải, đòn quay (12) kéo con trượt (2) sang trái, thông qua lò xo (9) đẩy vỏ van (4) sang trái, vỏ van (4) kéo đòn (8) sang trái và làm quay bánh xe (5) sang phải. Tương tự như trường hợp quay vành tay lái sang trái, khi lực người lái chưa thắng được lực cản của bánh xe (5) thì bánh xe không quay, do đó vỏ van (4) chưa di chuyển sang trái.","pages":[38]},{"id":"s1497","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Con trượt (2) sẽ nén lò xo (9) và dịch chuyển sang trái so với vỏ van (4). Khi lực trên vành tay lái đạt giá trị Fo cửa III đóng lại và cửa II mở ra. Chất lỏng từ khoang A thoát qua cửa IV và II về thùng (1). Áp suất chất lỏng khoang B đẩy pít-tông sang trái, đẩy đòn (8) sang trái và làm quay bánh xe (5) sang phải. (Zil 130) 1. Xi-lanh lực; 2. Đai ốc – thanh răng – pít-tông lực; 3. Các viên bi; 4. Trục vít; 5, 7. Ổ bi chặn; 6. Con trượt; 8. Cung răng; 9. Ốc điều chỉnh; 10. Trục của cung răng; 11. Đòn quay. Khi người lái đang đánh vành tay lái (ví dụ sang phải) rồi dừng lại, cửa I và II đang mở, chất lỏng áp suất cao đang sang khoang B và chất lỏng khoang A đang về thùng, bánh xe tiếp tục bị đẩy sang phải.","pages":[38]},{"id":"s1498","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Do người lái dừng lại nên con trượt (2) đã dừng lại nhưng vỏ van (4) nối với bánh xe tiếp tục bị đẩy sang trái nên làm đóng cửa II lại và duy trì áp suất bên phải pít-tông tương ứng với vị trí của vành tay lái. Cơ cấu lái trục vít – thanh răng – cung răng có trợ lực thủy lực (Hình 9.33) Cơ cấu lái loại này có đặc điểm thiết kế tích hợp hệ thống trợ lực thủy lực thành một cụm thống nhất (Hình 9.33). Cụ thể, vỏ cơ cấu lái (1) đồng thời đóng vai trò là thân xi-lanh lực, trong khi đó cụm đai ốc – thanh răng (2) đảm nhận luôn chức năng của pít-tông sinh lực trợ lực.","pages":[38]},{"id":"s1499","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Trục vít (4) tiếp nhận chuyển động quay từ vành tay lái thông qua trục lái. Ở phần đầu phía bên phải của trục vít (4) được bố trí một van điều khiển thủy lực dạng trượt. Con trượt (6) của cụm van này được định vị trên trục vít bằng hai ổ bi chặn (5) và (7). Đai ốc – thanh răng (2) luôn ăn khớp với cung răng (8). Khi cung răng (8) dịch chuyển, nó sẽ làm quay trục cung răng (10) và kéo theo đòn quay (11) để điều khiển cơ cấu lái bánh xe. Khối pít-tông (2) phân chia không gian bên trong xi-lanh (1) thành hai khoang kín biệt lập là khoang A và khoang B. Chất lỏng có áp suất cao từ bơm thủy lực được nạp vào hệ thống qua cửa C. Con trượt (6) sẽ đóng vai trò như một công tắc điều hướng, phân phối dòng chất lỏng áp suất cao này vào khoang A hoặc B tùy theo điều kiện vận hành.","pages":[39]},{"id":"s1500","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Nguyên lý hoạt động Khi xe đi thẳng: Vành tay lái được giữ ở vị trí trung gian, dẫn đến con trượt (6) của van điều khiển cũng nằm ở trạng thái cân bằng ở giữa. Lúc này, các cửa van mở đều, cho phép chất lỏng áp suất cao từ cửa C đi vào cả hai khoang A và B. Áp lực cân bằng ở cả hai phía giúp giữ cụm đai ốc – thanh răng – pít-tông (2) ổn định ở vị trí trung gian. Khi quay vòng: Thao tác quay vành tay lái của người điều khiển sẽ làm trục vít (4) quay. Về lý thuyết cơ cấu, đai ốc – thanh răng (2) sẽ trượt dọc trên trục vít (4), làm quay cung răng (8), dẫn đến trục (10) quay và đẩy đòn quay (11) làm chuyển hướng bánh xe. Trên sơ đồ ở Hình 9.34 chia tách và trực quan hướng đi của đường dầu áp suất cao (A) và đường dầu hồi về (B) theo ba trạng thái vận hành độc lập: khi xe đi thẳng (I), quay vòng phải (II) và quay vòng trái (III).","pages":[39]},{"id":"s1501","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Quá trình sinh lực trợ lực: Khi lực cản quay vòng từ mặt đường tác dụng lên bánh xe lớn, lực xoay trên vành tay lái chưa đủ để thắng mô-men cản này thì cụm đai ốc – thanh răng (2) sẽ bị giữ lại, chưa thể chuyển động. Lúc này, sự quay của trục vít (4) sẽ khiến nó tự trượt dọc trên cụm đai ốc (2), kéo theo con trượt (6) di chuyển. Khi sự dịch chuyển này đạt đến giá trị thiết kế, con trượt (6) sẽ thực hiện đóng/mở các cửa van, cho phép chất lỏng áp suất cao từ một khoang (A hoặc B, tùy hướng đánh lái) xả ngược về thùng chứa. Sự chênh lệch áp suất sinh ra giữa khoang A và B sẽ tạo lực đẩy thủy lực lên mặt pít-tông (2), trợ giúp người lái dịch chuyển thanh răng một cách nhẹ nhàng. Để tăng tuổi thọ cho cặp thanh răng – cung răng, mặt răng của các răng kề nhau không được chế tạo song song tuyệt đối (thường có độ côn hoặc góc nghiêng nhất định).","pages":[39]},{"id":"s1502","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Khi bị mòn, vành tay lái có độ rơ; khi đó, cung răng (8) được dịch chuyển sang trái bằng bu-lông điều chỉnh (9). Sơ đồ nguyên lý làm việc của hệ thống lái có trợ lực thủy lực trên xe Kamaz 5320 thể hiện trên Hình 9.34. Van quay kiểu thanh xoắn Hình 9.35 thể hiện sơ đồ hệ thống lái có cơ cấu lái bánh răng - thanh răng với trợ lực thủy lực sử dụng van điều khiển dạng xoay.","pages":[39]},{"id":"s1503","kind":"figure","lesson":"9.4.1","title":"Hình 9.34. Sơ đồ nguyên lý làm việc của hệ thống lái xe Kamaz 5320 I – Trạng thái đi thẳng; II – Trạng thái quay vòng phải; III – Trạng thái quay vòng trái.","text":"Hình 9.34. Sơ đồ nguyên lý làm việc của hệ thống lái xe Kamaz 5320 I – Trạng thái đi thẳng; II – Trạng thái quay vòng phải; III – Trạng thái quay vòng trái.","pages":[40],"figure":{"number":"9.34","caption":"Hình 9.34. Sơ đồ nguyên lý làm việc của hệ thống lái xe Kamaz 5320 I – Trạng thái đi thẳng; II – Trạng thái quay vòng phải; III – Trạng thái quay vòng trái."}},{"id":"s1504","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Lõi van (5) được lắp với trục lái (6) và bánh răng của cơ cấu lái. Vỏ van (4) có bốn cửa: cửa dầu đến (từ bơm thủy lực), cửa dẫn chất lỏng về thùng và hai cửa dẫn chất lỏng đến khoang trái và phải của pít-tông lực (2). Lõi van có các lỗ có thể thông hoặc ngắt với các cửa của vỏ van, tùy thuộc vào vị trí tương đối giữa lõi và vỏ. 1. Van xả; 2. Trục đòn quay đứng; 3. Pít-tông liền thanh răng; 4. Đai ốc bi; 5. Trục vít; 6. Vỏ cơ cấu lái; 7. Van an toàn của cơ cấu lái; 8. Vỏ van phân phối; 9. Con trượt van phân phối; 10. Két làm mát dầu; 11. Bình chứa dầu của bơm trợ lực; 12. Bơm trợ lực thủy lực. A. Đường dầu áp suất cao; Khi ô tô chuyển động thẳng: Lực cản đánh lái từ mặt đường không đáng kể, thanh xoắn ở trạng thái tự do không bị biến dạng. Lõi van (5) và vỏ van (4) duy trì ở vị trí trung gian.","pages":[40]},{"id":"s1505","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Dầu cao áp cấp từ bơm đi qua các khe hở (đang mở đều nhau) và xả thẳng về bình chứa. Do đó, áp suất tại khoang trái và khoang phải của pít-tông lực (2) cân bằng và ở mức thấp, không sinh ra lực trợ lực đẩy thanh răng (3). Khi ô tô quay vòng (ví dụ đánh lái sang trái): Người lái tác dụng mô-men làm quay trục lái (6) cùng lõi van (5). Tuy nhiên, lực cản quay vòng từ mặt đường truyền ngược qua bánh xe lên thanh răng (3) làm bánh răng chủ động và vỏ van (4) có xu hướng xoay chậm hơn. Sự chênh lệch tốc độ này làm biến dạng thanh xoắn, tạo ra một góc lệch tương đối giữa lõi van (5) và vỏ van (4). Góc lệch này làm thay đổi tiết diện các rãnh dẫn dầu: dầu cao áp từ bơm bị chặn đường về bình chứa và bị ép đi vào khoang bên phải của xi-lanh lực (1); đồng thời khoang bên trái được mở thông với đường hồi dầu.","pages":[40]},{"id":"s1506","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Sự chênh lệch áp suất cực lớn này tạo ra lực đẩy pít-tông (2) và thanh răng (3) dịch chuyển mạnh sang trái, trực tiếp hỗ trợ người lái bẻ lái một cách nhẹ nhàng.","pages":[40]},{"id":"s1507","kind":"figure","lesson":"9.4.1","title":"Hình 9.35. Hệ thống lái bánh răng - thanh răng, trợ lực thủy lực dùng van xoay","text":"Hình 9.35. Hệ thống lái bánh răng - thanh răng, trợ lực thủy lực dùng van xoay","pages":[41],"figure":{"number":"9.35","caption":"Hình 9.35. Hệ thống lái bánh răng - thanh răng, trợ lực thủy lực dùng van xoay"}},{"id":"s1508","kind":"figure","lesson":"9.4.1","title":"Hình 9.36. Kết cấu van xoay 1, 2, 7. Chốt; 3. Lõi van trong; 4. Thanh xoắn; 5. Vỏ van; 6. Lõi van ngoài; 8. Trục chủ","text":"Hình 9.36. Kết cấu van xoay 1, 2, 7. Chốt; 3. Lõi van trong; 4. Thanh xoắn; 5. Vỏ van; 6. Lõi van ngoài; 8. Trục chủ","pages":[41],"figure":{"number":"9.36","caption":"Hình 9.36. Kết cấu van xoay 1, 2, 7. Chốt; 3. Lõi van trong; 4. Thanh xoắn; 5. Vỏ van; 6. Lõi van ngoài; 8. Trục chủ"}},{"id":"s1509","kind":"figure","lesson":"9.4.1","title":"Hình 9.36 thể hiện kết cấu một van điều khiển dạng xoay dùng trên hệ thống lái có trợ lực thủy lực. Lõi van trong (3) được nối với trục lái và nhận lực điều khiển của người lái từ vành tay lái. Lõi van (3) dẫn động thanh xoắn (4) bằng chốt (2). Thanh xoắn (4) nối với trục bị động (8) của cơ cấu lái bằng chốt (7). Trục (8) có thể là trục bánh răng trong cơ cấu lái bánh răng - thanh răng, có thể là trục vít trong cơ cấu lái trục vít - đai ốc - thanh răng - cung răng. Phía ngoài lõi van trong (3) lắp lõi van ngoài (6) và lõi van (6) nối với trục (8) bằng chốt (1).","text":"Hình 9.36 thể hiện kết cấu một van điều khiển dạng xoay dùng trên hệ thống lái có trợ lực thủy lực. Lõi van trong (3) được nối với trục lái và nhận lực điều khiển của người lái từ vành tay lái. Lõi van (3) dẫn động thanh xoắn (4) bằng chốt (2). Thanh xoắn (4) nối với trục bị động (8) của cơ cấu lái bằng chốt (7). Trục (8) có thể là trục bánh răng trong cơ cấu lái bánh răng - thanh răng, có thể là trục vít trong cơ cấu lái trục vít - đai ốc - thanh răng - cung răng. Phía ngoài lõi van trong (3) lắp lõi van ngoài (6) và lõi van (6) nối với trục (8) bằng chốt (1).","pages":[41],"figure":{"number":"9.36","caption":"Hình 9.36 thể hiện kết cấu một van điều khiển dạng xoay dùng trên hệ thống lái có trợ lực thủy lực. Lõi van trong (3) được nối với trục lái và nhận lực điều khiển của người lái từ vành tay lái. Lõi van (3) dẫn động thanh xoắn (4) bằng chốt (2). Thanh xoắn (4) nối với trục bị động (8) của cơ cấu lái bằng chốt (7). Trục (8) có thể là trục bánh răng trong cơ cấu lái bánh răng - thanh răng, có thể là trục vít trong cơ cấu lái trục vít - đai ốc - thanh răng - cung răng. Phía ngoài lõi van trong (3) lắp lõi van ngoài (6) và lõi van (6) nối với trục (8) bằng chốt (1)."}},{"id":"s1510","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"1. Xi-lanh lực; 2. Pít-tông lực; 3. Thanh răng; 4. Vỏ van; 5. Lõi van; 6. Trục lái. Kết cấu của van xoay khá phức tạp và được trình bày chi tiết ở Hình 9.36. động của cơ cấu lái (trục bánh răng của cơ cấu lái bánh răng - thanh răng). Vỏ van (5) có bốn cửa: Cửa I nối với bơm thủy lực, cửa II nối với thùng dầu, cửa III và IV nối với hai khoang của xi-lanh lực (ví dụ theo sơ đồ, cửa III và IV nối với khoang trái và phải pít-tông (2)). Các cửa này không nằm cùng trên một mặt phẳng (trên Hình 9.36, các cửa được vẽ trong cùng mặt phẳng bản vẽ). Lõi van ngoài (6) có 4 lỗ khoan thẳng và ứng với các lỗ thẳng này có 2 lỗ khoan chéo, do vậy trên mặt van","pages":[41]},{"id":"s1511","kind":"figure","lesson":"9.4.2","title":"Hình 9.37. Sơ đồ trợ lực lái điện 1. Vành tay lái; 2. Cảm biến góc đánh lái; 3. Trục lái; 4. Cơ cấu trục vít bánh vít; 5. Cơ","text":"Hình 9.37. Sơ đồ trợ lực lái điện 1. Vành tay lái; 2. Cảm biến góc đánh lái; 3. Trục lái; 4. Cơ cấu trục vít bánh vít; 5. Cơ","pages":[42],"figure":{"number":"9.37","caption":"Hình 9.37. Sơ đồ trợ lực lái điện 1. Vành tay lái; 2. Cảm biến góc đánh lái; 3. Trục lái; 4. Cơ cấu trục vít bánh vít; 5. Cơ"}},{"id":"s1512","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"có tổng cộng 12 lỗ. Lõi van trong (3) có lỗ nhận dầu đến và lỗ thoát dầu về. Thanh xoắn được tính toán độ cứng để lõi van trong (3) xoay so với lõi van ngoài (6) một góc (khoảng 3°), khi đó van mở để dầu áp suất cao từ bơm đi đến xi-lanh lực. Khi quay vòng, người lái quay vành tay lái, qua trục lái làm quay lõi van trong (3), lõi van (3) thông qua chốt (2) làm quay thanh xoắn (4). Do có lực cản quay vòng của bánh xe, nên trục (8) chưa quay, do vậy lõi van ngoài (6) cũng chưa quay, thanh xoắn (4) bị xoắn lại. Khi lực trên vành tay lái đạt Fo (điểm A) thanh xoắn bị xoắn một góc khoảng 3°, tức là lõi van trong (3) xoay đi so với lõi van ngoài (6) khoảng 3°, đủ để nối thông đường dầu từ bơm đến một khoang của xi-lanh lực và nối khoang còn lại với đường dầu về thùng.","pages":[42]},{"id":"s1513","kind":"pdf","lesson":"9.4.1","title":"Hệ thống lái · Hệ thống lái trợ lực thủy lực","text":"Khi đang quay vòng, người lái ngừng quay vành tay lái, khi đó lõi van trong (3) dừng lại, khi đó van đang ở trạng thái như khi quay vành tay lái nên pít-tông lực vẫn tiếp tục đẩy bánh xe quay, kéo theo trục (8) và lõi van ngoài (6) quay theo, thanh xoắn trở về trạng thái không bị xoắn, đường dầu đến hai khoang của xi-lanh lực bị đóng lại, duy trì áp suất trong hai khoang tương ứng với vị trí của vành tay lái. Ở mặt cắt B-B, lõi van trong (3) và trục (8) có một khoảng hở; khi lõi van (3) xoay đi 3° thì chưa chạm vào trục (8). Khi thanh xoắn bị gãy, lõi van (3) xoay quá 3° và chạm vào trục (8); khi đó lõi van (3) trực tiếp dẫn động trục (8), bộ phận trợ lực không làm việc. f) Xi-lanh trợ lực (cơ cấu chấp hành) Xi-lanh trợ lực (cơ cấu chấp hành) tạo lực đẩy hỗ trợ người lái.","pages":[42]},{"id":"s1514","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"Tùy theo kết cấu, xi-lanh trợ lực có thể được bố trí chung một khối với van phân phối và cơ cấu lái hoặc bố trí riêng; các kiểu bố trí và phạm vi sử dụng đã trình bày ở mục b) (Hình 9.30). 2. Hệ thống lái trợ lực điện a) Khái quát cấu lái; 6. Trục nối; 7. Mô-tơ trợ lực lái; 8. ECU hệ thống trợ lực lái điện. Nguyên lý tổng quát của EPS là gắn một mô-tơ điện vào cơ cấu lái hoặc trục lái, mô-tơ này sinh mô-men trợ lực lên trục lái khi người lái xoay vành tay lái. Bộ","pages":[42]},{"id":"s1515","kind":"figure","lesson":"9.4.2","title":"Hình 9.38. Vị trí bố trí mô-tơ trợ lực trên hệ thống lái a) Mô-tơ trên trục lái; b) Mô-tơ trên thước lái ngang; c) Mô-tơ trên cơ cấu lái.","text":"Hình 9.38. Vị trí bố trí mô-tơ trợ lực trên hệ thống lái a) Mô-tơ trên trục lái; b) Mô-tơ trên thước lái ngang; c) Mô-tơ trên cơ cấu lái.","pages":[43],"figure":{"number":"9.38","caption":"Hình 9.38. Vị trí bố trí mô-tơ trợ lực trên hệ thống lái a) Mô-tơ trên trục lái; b) Mô-tơ trên thước lái ngang; c) Mô-tơ trên cơ cấu lái."}},{"id":"s1516","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"điều khiển điện tử (ECU) sẽ nhận tín hiệu từ cảm biến mô-men trên trục lái (đo lực hay độ xoắn do tay lái tác động) và từ cảm biến tốc độ xe, sau đó tính toán mức độ trợ lực phù hợp. ECU điều khiển dòng điện cung cấp cho mô-tơ điện: khi xe chạy chậm hoặc xoay vành tay lái nhanh đột ngột, ECU cho mô-tơ tạo lực hỗ trợ lớn; khi xe chạy tốc độ cao, ECU giảm dòng điện để mô-tơ chỉ tạo hỗ trợ nhỏ, nhằm giữ cảm giác lái thật. Kết quả là hệ thống EPS có thể cung cấp trợ lực biến thiên theo điều kiện lái một cách mềm mại, tối ưu cả ở tốc độ thấp lẫn cao. Sơ đồ hệ thống lái trợ lực điện thể hiện trên Hình 9.37. Theo vị trí bố trí mô-tơ trợ lực, EPS có thể được phân thành các dạng chính (Hình 9.38): trợ lực trên trục lái (column assist), trợ lực trên bánh răng dẫn động (pinion assist) và trợ lực trực tiếp trên thanh răng (rack assist).","pages":[43]},{"id":"s1517","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"Việc lựa chọn vị trí mô-tơ phụ thuộc vào kết cấu hệ thống lái, tải trọng cần trợ lực, không gian bố trí và yêu cầu điều khiển của xe. Ở kiểu gắn trục lái (còn gọi là EPS kiểu gắn trên trục lái - column assist EPS), mô-tơ đặt gần trục vành tay lái trong ca-bin, truyền lực qua cơ cấu bánh răng tới trục lái. Ở kiểu gắn trên thanh răng (EPS kiểu gắn trên thanh răng - rack assist EPS), mô-tơ tích hợp trong hộp cơ cấu lái, đẩy trực tiếp thanh răng qua một cơ cấu bánh răng – thanh răng phụ. Dù theo cấu hình nào, hệ thống EPS cũng gồm: Mô-tơ điện, thường là mô-tơ đồng bộ nam châm vĩnh cửu (PMSM) hoặc mô-tơ một chiều không chổi than (BLDC), tùy theo thiết kế của hệ thống; ECU điều khiển; cảm biến mô-men xoắn; cảm biến vị trí và tốc độ; cùng các dây dẫn điện. Không có bơm dầu, ống dẫn hay van thủy lực trong hệ thống EPS, giảm bảo trì và tiết kiệm nhiên liệu.","pages":[43]},{"id":"s1518","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"Ưu điểm: Cấu tạo gọn gàng, loại bỏ hoàn toàn dầu và bơm nên giảm bảo trì và tránh tổn hao công suất khi không cần trợ lực (Do mô-tơ điện chỉ tiêu thụ năng lượng khi hệ thống cần trợ lực, EPS có thể giảm tổn hao công suất so với hệ thống trợ lực thủy lực truyền thống, qua đó góp phần cải thiện mức tiêu thụ nhiên liệu). Dễ dàng tùy biến đặc tính trợ lực bằng phần mềm (có thể điều chỉnh độ nặng nhẹ của tay lái theo ý đồ thiết kế hoặc chế độ lái khác nhau). Tích hợp thuận lợi với các hệ thống hỗ trợ người lái hiện đại (như giữ làn đường, đỗ xe tự động) vì mô-tơ điện có thể điều khiển độc lập để đánh lái mà không cần người lái.","pages":[43]},{"id":"s1519","kind":"figure","lesson":"9.4.2","title":"Hình 9.39. Cấu tạo cảm biến mô-men xoắn 1. Cảm biến mô-men; 2. Trục lái chính; 3. Vành tay lái; 4. Bộ giảm tốc; 5. Vòng phát hiện 1; 6. Trục sơ cấp; 7. Cuộn dây bù; 8. Vòng phát hiện 2; 9. Cuộn dây phát hiện; 10.","text":"Hình 9.39. Cấu tạo cảm biến mô-men xoắn 1. Cảm biến mô-men; 2. Trục lái chính; 3. Vành tay lái; 4. Bộ giảm tốc; 5. Vòng phát hiện 1; 6. Trục sơ cấp; 7. Cuộn dây bù; 8. Vòng phát hiện 2; 9. Cuộn dây phát hiện; 10.","pages":[44],"figure":{"number":"9.39","caption":"Hình 9.39. Cấu tạo cảm biến mô-men xoắn 1. Cảm biến mô-men; 2. Trục lái chính; 3. Vành tay lái; 4. Bộ giảm tốc; 5. Vòng phát hiện 1; 6. Trục sơ cấp; 7. Cuộn dây bù; 8. Vòng phát hiện 2; 9. Cuộn dây phát hiện; 10."}},{"id":"s1520","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"Nhược điểm: Khả năng tạo lực của EPS bị giới hạn bởi công suất mô-tơ và nguồn điện, do đó trên các xe cỡ lớn hoặc xe tải nặng, EPS thuần túy có thể không đáp ứng đủ (mặc dù công nghệ đang cải thiện điều này). Một số người lái nhận xét cảm giác lái của EPS “không thật” bằng hệ thống thủy lực thuần túy, do sự can thiệp của mô-tơ và bộ điều khiển làm mất phần nào phản hồi từ mặt đường. Ngoài ra, nếu hệ thống điện gặp trục trặc (ví dụ hỏng mô-tơ hoặc ECU), trợ lực sẽ mất hoàn toàn – lúc này vành tay lái sẽ rất nặng giống như khi tắt máy ở hệ thống thủy lực. Vì vậy, yêu cầu an toàn điện cho EPS rất cao, thường phải có nguồn điện dự phòng hoặc cơ chế cảnh báo sớm khi có lỗi. Vòng phát hiện 3; 11. Trục thứ cấp. Cảm biến mô-men (1) (Hình 9.39) là một thành phần cơ điện tử cốt lõi trong hệ thống lái trợ lực điện (EPS).","pages":[44]},{"id":"s1521","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"Nhiệm vụ chính của cảm biến là ghi nhận lực xoắn (mô-men) do người lái tác dụng lên vành tay lái (3) cũng như chiều quay của vành tay lái, sau đó chuyển đổi thành tín hiệu điện áp gửi về hộp điều khiển trung tâm (ECU) để tính toán dòng điện cấp cho mô-tơ trợ lực. Về mặt cơ khí, cụm cảm biến thường được bố trí tích hợp ngay trên trục lái chính (2), nằm ở vị trí phía trên bộ giảm tốc (4). Bên trong của cảm biến mô-men điện từ bao gồm hai phần trục được liên kết đàn hồi với nhau thông qua một thanh xoắn đặt ở tâm: Trục sơ cấp (6): Liên kết phần trên với trục lái, tiếp nhận trực tiếp chuyển động quay và lực tác dụng từ vành tay lái. Trục thứ cấp (11): Liên kết phần dưới với cơ cấu lái (bánh răng - thanh răng).","pages":[44]},{"id":"s1522","kind":"figure","lesson":"9.4.2","title":"Hình 9.40. Cấu tạo mô-tơ điện trợ lực 1. Vòng bi; 2. Trục vít; 3. Vỏ trục lái; 4. Khớp nối; 5. Rô-to; 6. Stato; 7. Trục mô-tơ; 8.","text":"Hình 9.40. Cấu tạo mô-tơ điện trợ lực 1. Vòng bi; 2. Trục vít; 3. Vỏ trục lái; 4. Khớp nối; 5. Rô-to; 6. Stato; 7. Trục mô-tơ; 8.","pages":[45],"figure":{"number":"9.40","caption":"Hình 9.40. Cấu tạo mô-tơ điện trợ lực 1. Vòng bi; 2. Trục vít; 3. Vỏ trục lái; 4. Khớp nối; 5. Rô-to; 6. Stato; 7. Trục mô-tơ; 8."}},{"id":"s1523","kind":"figure","lesson":"9.4.2","title":"Hình 9.41. Hệ thống lái trợ lực điện - Có nhiệm vụ tạo mô-men trợ lực trực tiếp vào trục lái hoặc thanh răng. - Mô-tơ có tích hợp cảm biến vị trí rô-to để ECU điều khiển chính xác. ECU – bộ điều khiển điện tử (Hình 9.41) - Nhận tín hiệu từ cảm biến mô-men, cảm biến tốc độ xe, cảm biến góc quay vành tay lái.","text":"Hình 9.41. Hệ thống lái trợ lực điện - Có nhiệm vụ tạo mô-men trợ lực trực tiếp vào trục lái hoặc thanh răng. - Mô-tơ có tích hợp cảm biến vị trí rô-to để ECU điều khiển chính xác. ECU – bộ điều khiển điện tử (Hình 9.41) - Nhận tín hiệu từ cảm biến mô-men, cảm biến tốc độ xe, cảm biến góc quay vành tay lái.","pages":[45],"figure":{"number":"9.41","caption":"Hình 9.41. Hệ thống lái trợ lực điện - Có nhiệm vụ tạo mô-men trợ lực trực tiếp vào trục lái hoặc thanh răng. - Mô-tơ có tích hợp cảm biến vị trí rô-to để ECU điều khiển chính xác. ECU – bộ điều khiển điện tử (Hình 9.41) - Nhận tín hiệu từ cảm biến mô-men, cảm biến tốc độ xe, cảm biến góc quay vành tay lái."}},{"id":"s1524","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"Cụm cảm biến từ tính: Bao gồm các cuộn dây phát hiện (9), cuộn dây bù (7) và các vòng phát hiện tương ứng (5, 8, 10) được gia công có vấu rãnh và lắp cố định trên các trục. Sự dịch chuyển góc tương đối giữa các vòng phát hiện này sẽ làm thay đổi khe hở từ, qua đó làm thay đổi từ thông đi qua các cuộn dây. EPS gồm các bộ phận chính: Mô-tơ điện trợ lực Mô-tơ trợ lực điện thường sử dụng mô-tơ BLDC hoặc PMSM, có khả năng tạo mô-men lớn trong phạm vi tốc độ và kích thước phù hợp với yêu cầu của hệ thống EPS (Hình 9.40). Trục lái chính; 9. Bánh vít.","pages":[45]},{"id":"s1525","kind":"figure","lesson":"9.4.2","title":"Hình 9.42. Cảm biến mô-men Cảm biến góc quay và tốc độ vành tay lái - Giúp ECU biết được tốc độ đánh lái (quay nhanh hay chậm). - Đảm bảo hệ thống đáp ứng kịp thời, tránh trợ lực quá đà. Cơ cấu truyền lực - Tùy bố trí, lực từ mô-tơ truyền qua bánh răng trục vít, hoặc truyền trực tiếp lên thanh răng.","text":"Hình 9.42. Cảm biến mô-men Cảm biến góc quay và tốc độ vành tay lái - Giúp ECU biết được tốc độ đánh lái (quay nhanh hay chậm). - Đảm bảo hệ thống đáp ứng kịp thời, tránh trợ lực quá đà. Cơ cấu truyền lực - Tùy bố trí, lực từ mô-tơ truyền qua bánh răng trục vít, hoặc truyền trực tiếp lên thanh răng.","pages":[46],"figure":{"number":"9.42","caption":"Hình 9.42. Cảm biến mô-men Cảm biến góc quay và tốc độ vành tay lái - Giúp ECU biết được tốc độ đánh lái (quay nhanh hay chậm). - Đảm bảo hệ thống đáp ứng kịp thời, tránh trợ lực quá đà. Cơ cấu truyền lực - Tùy bố trí, lực từ mô-tơ truyền qua bánh răng trục vít, hoặc truyền trực tiếp lên thanh răng."}},{"id":"s1526","kind":"figure","lesson":"9.4.2","title":"Hình 9.43. Nguyên lý làm việc","text":"Hình 9.43. Nguyên lý làm việc","pages":[46],"figure":{"number":"9.43","caption":"Hình 9.43. Nguyên lý làm việc"}},{"id":"s1527","kind":"pdf","lesson":"9.4.2","title":"Hệ thống lái · Hệ thống lái trợ lực điện","text":"- Xử lý thông tin để quyết định mức dòng điện cấp cho mô-tơ. - Có khả năng tự chẩn đoán, lưu lỗi, và chế độ an toàn (fail-safe). Cảm biến mô-men xoắn (Torque Sensor) (Hình 9.42) - Lắp trên trục lái, đo độ xoắn của thanh xoắn khi người lái tác động lực. - Tín hiệu điện áp tỉ lệ với mô-men được gửi về ECU. - Có cơ cấu giảm tốc để khuếch đại mô-men từ mô-tơ. Nguyên lý hoạt động (Hình 9.43): Nguyên lý hoạt động của hệ thống trợ lực lái điện diễn ra theo một chu trình điều khiển khép kín: Khi người lái tác động lên vành tay lái, cảm biến mô-men xác định độ xoắn và truyền tín hiệu về bộ điều khiển điện tử trung tâm. Dựa trên tốc độ","pages":[46]},{"id":"s1528","kind":"figure","lesson":"9.4.3","title":"Hình 9.44. Sơ đồ hệ thống lái trợ lực thủy lực điều khiển điện tử 1. Vành tay lái; 2. Trục lái; 3. Cảm biến mô-men và góc lái; 4. Bộ điều khiển điện tử trợ lực lái (ECU); 5. Động cơ đồng bộ nam châm vĩnh cửu (PMSM); 6. Cung răng; 7. Cơ cấu lái bi tuần hoàn; 8. Van phân phối quay; 9. Động cơ điện; 10. Cầu xe; 11. Thanh kéo; 12.","text":"Hình 9.44. Sơ đồ hệ thống lái trợ lực thủy lực điều khiển điện tử 1. Vành tay lái; 2. Trục lái; 3. Cảm biến mô-men và góc lái; 4. Bộ điều khiển điện tử trợ lực lái (ECU); 5. Động cơ đồng bộ nam châm vĩnh cửu (PMSM); 6. Cung răng; 7. Cơ cấu lái bi tuần hoàn; 8. Van phân phối quay; 9. Động cơ điện; 10. Cầu xe; 11. Thanh kéo; 12.","pages":[47],"figure":{"number":"9.44","caption":"Hình 9.44. Sơ đồ hệ thống lái trợ lực thủy lực điều khiển điện tử 1. Vành tay lái; 2. Trục lái; 3. Cảm biến mô-men và góc lái; 4. Bộ điều khiển điện tử trợ lực lái (ECU); 5. Động cơ đồng bộ nam châm vĩnh cửu (PMSM); 6. Cung răng; 7. Cơ cấu lái bi tuần hoàn; 8. Van phân phối quay; 9. Động cơ điện; 10. Cầu xe; 11. Thanh kéo; 12."}},{"id":"s1529","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"xe, mô-men tác động của người lái, góc lái, tốc độ đánh lái và chế độ vận hành, bộ điều khiển sẽ tính toán mức độ trợ lực tối ưu. Nhờ đó, hệ thống giảm nhẹ lực đánh lái khi xe đỗ hoặc di chuyển ở tốc độ thấp, đồng thời hạ thấp mức trợ lực khi xe chạy ở tốc độ cao để cải thiện cảm giác lái và duy trì ổn định hướng chuyển động. Cuối cùng, mô-tơ điện thông qua cơ cấu truyền lực sẽ tạo ra mô-men hỗ trợ, tác động trực tiếp vào trục lái hoặc thanh răng để giảm tải cho người lái. Ở tốc độ thấp, ECU thường điều khiển mô-tơ tạo mức trợ lực lớn hơn nhằm giảm lực điều khiển khi đỗ xe và quay vòng ở tốc độ thấp. Khi tốc độ xe tăng, mức trợ lực thường được giảm để tăng cảm giác lái và ổn định hướng chuyển động. Mức trợ lực thực tế còn phụ thuộc vào mô-men người lái, góc lái, tốc độ đánh lái, chế độ vận hành và các tín hiệu điều khiển khác.","pages":[47]},{"id":"s1530","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Mô-tơ quay, thông qua bộ truyền, tạo mô-men bổ sung vào trục lái hoặc thanh răng của dẫn động lái. Cảm biến góc và tốc độ lái giúp ECU điều chỉnh kịp thời, đảm bảo trợ lực chính xác. 3. Hệ thống lái trợ lực thủy lực điều khiển điện tử Lốp xe; 13. Bánh răng trục vít. Để khắc phục nhược điểm của trợ lực thủy lực truyền thống là mức trợ lực khó điều chỉnh linh hoạt theo điều kiện vận hành, các hãng xe đã bổ sung điều khiển điện tử vào hệ thống lái thủy lực (Hình 9.44). Hệ thống vẫn sử dụng dầu và xi-lanh thủy lực để tạo lực, nhưng có thêm bộ điều khiển điện tử và các cơ cấu chấp hành (van điện từ, bơm điện) để thay đổi áp lực dầu theo tín hiệu từ xe. Kết quả là tay lái","pages":[47]},{"id":"s1531","kind":"figure","lesson":"9.4.3","title":"Hình 9.45. Nguyên lý làm việc b) Kiểu bơm trợ lực thủy lực điều khiển điện (Electro-Hydraulic Power Steering – EHPS)","text":"Hình 9.45. Nguyên lý làm việc b) Kiểu bơm trợ lực thủy lực điều khiển điện (Electro-Hydraulic Power Steering – EHPS)","pages":[48],"figure":{"number":"9.45","caption":"Hình 9.45. Nguyên lý làm việc b) Kiểu bơm trợ lực thủy lực điều khiển điện (Electro-Hydraulic Power Steering – EHPS)"}},{"id":"s1532","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"nhẹ khi cần thiết và nặng hơn (cảm giác thật) khi xe chạy nhanh, kết hợp ưu điểm của cả hai loại trợ lực. Khi người lái thao tác trên vành tay lái, các cảm biến sẽ liên tục ghi nhận dữ liệu về góc đánh lái và mô-men xoắn, sau đó truyền tín hiệu về bộ điều khiển điện tử trung tâm (ECU). Dựa trên các dữ liệu đầu vào này (kết hợp cùng tín hiệu tốc độ xe trong thực tế), ECU sẽ tính toán mức độ hỗ trợ cần thiết và xuất lệnh điều khiển hệ thống động cơ điện cùng cụm van phân phối quay. Có hai kiểu hệ thống trợ lực thủy lực điều khiển điện tử phổ biến: a) Kiểu van điện từ điều tiết dầu Đây là giải pháp thường thấy trên các xe thập niên 1990–2000 (ví dụ hệ thống Servotronic của BMW, Speed-sensitive Steering của Mercedes).","pages":[48]},{"id":"s1533","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Hệ thống sử dụng một van điện từ gắn trên đường dầu (hoặc ngay trên thân cơ cấu lái) để điều chỉnh lưu lượng dầu trợ lực tùy thuộc vào tốc độ xe (Hình 9.45). Ở tốc độ thấp, van điện từ đóng bớt đường hồi dầu, dồn dầu vào xi-lanh trợ lực tạo áp lực cao – kết quả là trợ lực tối đa, đánh lái nhẹ nhàng khi đỗ xe hoặc quay vòng nhỏ. Khi tốc độ tăng, ECU sẽ giảm dòng điện kích thích van điện từ, khiến van mở thông hơn, một phần dầu trợ lực thoát về bình chứa, giảm bớt áp lực tác động lên xi-lanh. Lực trợ lực vì thế giảm xuống, giúp tay lái nặng hơn ở tốc độ cao, tăng cảm giác mặt đường và độ ổn định khi lái. Hệ thống cảm biến tốc độ xe, cảm biến góc/ tốc độ quay vành tay lái sẽ cung cấp dữ liệu đầu vào cho ECU điều khiển van.","pages":[48]},{"id":"s1534","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Trong trường hợp điện tử gặp lỗi hoặc mất điện, van điện từ thường trở về trạng thái an toàn (thường là mở hoàn toàn) để hệ thống chuyển thành trợ lực tối đa như loại thủy lực thông thường, đảm bảo vẫn có trợ lực cho người lái. Ở hệ thống này, bơm dầu không lấy chuyển động từ động cơ qua dây đai nữa, mà được dẫn động bởi mô-tơ điện công suất cao (Hình 9.46). Về cơ bản, hệ thống kết hợp cơ cấu lái trợ lực thủy lực (van, xi-lanh, dầu) với một mô-tơ điện tương tự EPS để quay bơm dầu. ECU sẽ điều khiển tốc độ và công suất của mô-tơ bơm dựa trên tín hiệu tốc độ xe và lực lái.","pages":[48]},{"id":"s1535","kind":"figure","lesson":"9.4.3","title":"Hình 9.46. Sơ đồ hệ thống lái trợ lực thủy lực có điều khiển bơm trợ lực","text":"Hình 9.46. Sơ đồ hệ thống lái trợ lực thủy lực có điều khiển bơm trợ lực","pages":[49],"figure":{"number":"9.46","caption":"Hình 9.46. Sơ đồ hệ thống lái trợ lực thủy lực có điều khiển bơm trợ lực"}},{"id":"s1536","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Khi xe chạy chậm hoặc đánh lái gấp, mô-tơ bơm quay nhanh để tạo áp lực dầu lớn (trợ lực nhiều); khi chạy trên cao tốc thẳng, mô-tơ có thể quay chậm lại hoặc ngừng, nhằm tiết kiệm năng lượng và giảm trợ lực (tay lái nặng hơn tương ứng). Ưu điểm của EHPS là loại bỏ được tổn hao liên tục như bơm thủy lực truyền thống, tiết kiệm nhiên liệu gần bằng EPS, trong khi lực trợ lực tạo ra vẫn rất lớn, phù hợp cho xe hạng nặng. Hệ EHPS còn cho phép điều khiển linh hoạt bằng phần mềm giống như EPS. Nhiều mẫu xe giai đoạn chuyển giao (cuối 2000s) đã dùng giải pháp này trước khi EPS đủ sức thay thế hoàn toàn (ví dụ một số mẫu của Toyota, Peugeot sử dụng bơm trợ lực điện).","pages":[49]},{"id":"s1537","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Ưu điểm của EHPS: - Vì vẫn dùng cơ cấu dầu thủy lực để tạo lực, nên vành tay lái mang lại cảm giác nặng – thật, quen thuộc với người lái, đặc biệt phù hợp xe off-road (ví dụ Jeep Wrangler). - Bơm thủy lực chạy bằng mô-tơ điện thay vì dây curoa từ động cơ, nên chỉ hoạt động khi cần, do đó giảm tổn hao công suất động cơ, cải thiện mức tiêu thụ nhiên liệu. Nhược điểm của EHPS: - Có ống dẫn, dầu, phớt nên dễ rò rỉ, tốn chi phí bảo dưỡng; Phức tạp hơn EPS hoàn toàn điện; Khó tích hợp tính năng hiện đại. Xu hướng: xe du lịch (sedan, SUV đô thị, hatchback…) ngày nay đều hướng tới giảm khối lượng, tiết kiệm nhiên liệu và tích hợp hệ thống lái tự động; vì vậy, EPS là lựa chọn tối ưu.","pages":[49]},{"id":"s1538","kind":"figure","lesson":"9.4.3","title":"Hình 9.47. Hệ thống lái không trục lái a) Cấu tạo Hệ thống lái không trục lái gồm ba khối chính: phân hệ vành tay lái, bộ điều khiển điện tử và phân hệ dẫn động lái (Hình 9.47). Ngoài ra, hệ thống còn được trang bị các thành phần dự phòng.","text":"Hình 9.47. Hệ thống lái không trục lái a) Cấu tạo Hệ thống lái không trục lái gồm ba khối chính: phân hệ vành tay lái, bộ điều khiển điện tử và phân hệ dẫn động lái (Hình 9.47). Ngoài ra, hệ thống còn được trang bị các thành phần dự phòng.","pages":[50],"figure":{"number":"9.47","caption":"Hình 9.47. Hệ thống lái không trục lái a) Cấu tạo Hệ thống lái không trục lái gồm ba khối chính: phân hệ vành tay lái, bộ điều khiển điện tử và phân hệ dẫn động lái (Hình 9.47). Ngoài ra, hệ thống còn được trang bị các thành phần dự phòng."}},{"id":"s1539","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Tóm lại, hệ thống lái trợ lực thủy lực điều khiển điện tử là bước cải tiến trung gian, tận dụng sức mạnh cơ cấu thủy lực nhưng bổ sung sự tinh chỉnh của điện tử. Nhờ đó, người lái có tay lái nhẹ nhàng khi cần, nhưng vẫn giữ độ chắc chắn khi chạy ở tốc độ cao. Hiện nay, hầu hết các xe du lịch đều có ít nhiều tính năng điều chỉnh trợ lực theo tốc độ, dù hệ thống nền tảng là thủy lực hay điện. 4. Hệ thống lái không trục lái Hệ thống lái không trục (Steer-by-Wire – SbW) là một hướng phát triển của công nghệ điều khiển lái, trong đó lệnh điều khiển từ người lái được truyền tới cơ cấu chấp hành thông qua tín hiệu điện.","pages":[50]},{"id":"s1540","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Nói cách khác, toàn bộ việc truyền tín hiệu lái là bằng điện/điện tử: vành tay lái chỉ đóng vai trò như một bộ cảm biến góc lái và mô-men; còn tại cầu trước, các mô-tơ điện sẽ nhận lệnh từ máy tính trung tâm để xoay bánh xe sang trái hoặc sang phải (Hình 9.47). - Phân hệ vành tay lái: Tiếp nhận ý định lái của người lái và tạo cảm giác lái. Phân hệ gồm vành tay lái, cảm biến góc lái, cảm biến mô-men xoắn và mô-tơ phản hồi lái, lắp trên một trục vành tay lái ngắn không nối với cơ cấu lái.","pages":[50]},{"id":"s1541","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Cảm biến góc lái đo góc quay và tốc độ quay vành tay lái. Cảm biến thường hoạt động theo hiệu ứng Hall hoặc từ trở và có hai kênh tín hiệu độc lập. Cảm biến mô-men xoắn đo mô-men người lái tác dụng lên vành tay lái, dựa trên độ xoắn của thanh xoắn. Mô-tơ phản hồi lái thường là mô-tơ một chiều không chổi than, dẫn động trục vành tay lái qua bộ truyền giảm tốc. Mô-tơ tạo mô-men cản để tái tạo cảm giác mặt đường và giúp vành tay lái tự trả về vị trí trung gian. - Bộ điều khiển điện tử: ECU tiếp nhận tín hiệu từ các cảm biến của hệ thống lái và từ các hệ thống khác trên xe (tốc độ xe, gia tốc ngang, tốc độ quay thân xe). Từ các tín hiệu này, ECU tính toán góc quay bánh xe yêu cầu và mô-men phản hồi, rồi điều khiển hai mô-tơ chấp hành tương ứng.","pages":[51]},{"id":"s1542","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"ECU đồng thời giám sát, chẩn đoán lỗi và kích hoạt chế độ dự phòng khi cần. - Phân hệ dẫn động lái: Phân hệ dẫn động lái quay các bánh xe dẫn hướng theo lệnh của ECU. Phân hệ gồm mô-tơ truyền động lái, cơ cấu lái, thanh nối lái và cảm biến góc bánh xe. Mô-tơ truyền động lái thường là mô-tơ đồng bộ nam châm vĩnh cửu (PMSM), có công suất đủ lớn để thắng toàn bộ lực cản quay bánh xe. Cơ cấu lái thường là kiểu bánh răng – thanh răng. Mô-tơ dẫn động thanh răng qua bánh răng, hoặc qua bộ truyền đai kết hợp vít me - bi. Chuyển động được truyền tới cam quay bánh xe qua thanh nối lái và khớp cầu. Cảm biến góc bánh xe đo vị trí thực tế của thanh răng để ECU điều khiển theo vòng kín. - Thành phần dự phòng: Do không có liên kết cơ khí, SbW được thiết kế theo nguyên tắc vẫn hoạt động khi có lỗi.","pages":[51]},{"id":"s1543","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Các thành phần dự phòng thường gồm: Nguồn điện kép; hai hoặc ba ECU giám sát chéo; mô-tơ có cuộn dây kép; cảm biến và đường truyền tín hiệu nhiều kênh. Một số thiết kế còn giữ trục lái cơ khí kèm ly hợp điện từ. Ly hợp nhả khi hệ thống hoạt động bình thường và đóng lại để nối cơ khí khi có sự cố. b) Nguyên lý hoạt động Hệ thống lái không trục lái hoạt động ở hai chế độ: chế độ vận hành bình thường và chế độ sự cố. Chế độ vận hành bình thường Ở chế độ này, ECU thực hiện đồng thời hai vòng điều khiển. Vòng điều khiển góc quay bánh xe: Khi người lái quay vành tay lái, cảm biến góc lái gửi tín hiệu góc quay và tốc độ quay vành tay lái về ECU. ECU xác định góc quay bánh xe yêu cầu theo tỷ số truyền lái: Trong đó: θv là góc quay vành tay lái; δb là góc quay bánh xe dẫn hướng.","pages":[51]},{"id":"s1544","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Sau khi xác định góc yêu cầu, ECU điều khiển mô-tơ truyền động lái dịch chuyển thanh răng để quay bánh xe. Cảm biến góc bánh xe liên tục gửi vị trí thực tế","pages":[51]},{"id":"s1545","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"về ECU. ECU so sánh vị trí này với giá trị yêu cầu và hiệu chỉnh để triệt tiêu sai lệch (điều khiển vòng kín). Vòng điều khiển cảm giác lái: ECU ước tính lực cản từ mặt đường tác dụng lên bánh xe dựa trên dòng điện của mô-tơ truyền động lái. Từ lực cản này, kết hợp với tốc độ xe và góc quay vành tay lái, ECU điều khiển mô-tơ phản hồi lái tạo mô- men cản tương ứng trên vành tay lái. Tín hiệu từ cảm biến mô-men xoắn được dùng để hiệu chỉnh mô-men phản hồi theo lực lái thực tế của người lái. Nhờ đó, người lái cảm nhận được trạng thái bám đường, và vành tay lái tự trả về vị trí trung gian khi buông tay. Ngoài hai vòng điều khiển trên, ECU còn có thể chủ động hiệu chỉnh góc quay bánh xe để ổn định xe, ví dụ khi phanh trên mặt đường có hệ số bám không đều hoặc khi có gió ngang. Việc hiệu chỉnh này không làm quay vành tay lái.","pages":[52]},{"id":"s1546","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Chế độ sự cố Khi phát hiện lỗi ở một kênh (cảm biến, mô-tơ, ECU hoặc nguồn điện), ECU thực hiện các bước sau: - Cô lập kênh lỗi và chuyển sang kênh dự phòng để duy trì khả năng lái; - Bật đèn cảnh báo cho người lái; - Có thể giới hạn tốc độ xe hoặc giảm hiệu năng lái để người lái đưa xe về nơi an toàn. Đối với thiết kế có liên kết cơ khí dự phòng, ly hợp điện từ đóng lại khi có sự cố. Khi đó, vành tay lái được nối cơ khí với cơ cấu lái và hệ thống làm việc như hệ thống lái thông thường. Một số thiết kế còn giữ trục lái cơ khí kèm ly hợp điện từ. Ly hợp nhả khi hệ thống hoạt động bình thường và đóng lại để nối cơ khí khi có sự cố. c) Ưu điểm và nhược điểm Ưu điểm: Bố trí linh hoạt: loại bỏ cột lái, trục trung gian và các khớp các-đăng giúp mở rộng không gian khoang lái và dễ bố trí khoang động cơ.","pages":[52]},{"id":"s1547","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Việc chuyển đổi giữa xe tay lái thuận và tay lái nghịch cũng đơn giản hơn. Ngoài ra, nguy cơ chấn thương do cột lái khi va chạm trực diện giảm, và rung động từ mặt đường không truyền trực tiếp lên vành tay lái. Tùy biến đặc tính lái bằng phần mềm: Tỷ số truyền lái thay đổi được trong phạm vi rộng. Ở tốc độ thấp, tỷ số truyền nhỏ giúp giảm số vòng quay vành tay lái khi đỗ xe hoặc quay đầu. Ở tốc độ cao, tỷ số truyền lớn giúp xe ổn định. Cảm giác lái cũng điều chỉnh được theo chế độ lái như tiết kiệm, tiêu chuẩn hay thể thao. Dễ tích hợp với hệ thống hỗ trợ người lái và lái tự động: Ví dụ hỗ trợ đỗ xe tự động, giữ làn đường hoặc tránh vật cản. ECU điều khiển trực tiếp góc quay bánh xe mà không cần cơ cấu chấp hành bổ sung. Ở chế độ lái tự động, vành tay lái có thể đứng yên hoặc thu gọn.","pages":[52]},{"id":"s1548","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Giảm chi tiết cơ khí: so với HPS, SbW không cần bơm, dầu và đường ống trợ lực, nên khối lượng và nhu cầu bảo dưỡng giảm.","pages":[52]},{"id":"s1549","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Nhược điểm: Yêu cầu độ tin cậy rất cao: khi hệ thống điều khiển hoặc nguồn điện gặp sự cố mà hệ thống dự phòng không hoạt động, khả năng lái bị suy giảm hoặc mất hoàn toàn. Hệ thống phải đáp ứng mức toàn vẹn an toàn cao nhất theo tiêu chuẩn an toàn chức năng ISO 26262. Chi phí và độ phức tạp điện tử cao: Do cấu trúc dự phòng nhiều lớp, mô-tơ công suất lớn và phần mềm điều khiển phức tạp. Hệ thống cũng cần được bảo vệ trước nhiễu điện từ và tấn công an ninh mạng. Tiêu thụ điện năng lớn: mô-tơ truyền động lái phải tạo toàn bộ lực quay bánh xe, nên công suất yêu cầu cao. Hệ thống phù hợp hơn với xe dùng mạng điện áp cao hoặc mạng 48 V. Cảm giác lái phụ thuộc thuật toán: người lái không nhận phản hồi trực tiếp từ mặt đường.","pages":[53]},{"id":"s1550","kind":"pdf","lesson":"9.4.3","title":"Hệ thống lái · Hệ thống lái trợ lực thuỷ lực điều khiển điện tử","text":"Nếu thuật toán điều khiển mô-tơ phản hồi chưa tối ưu, cảm giác lái sẽ thiếu chân thực, và người lái cần thời gian làm quen với tỷ số truyền thay đổi.","pages":[53]},{"id":"s1551","kind":"pdf","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"Hệ thống phanh có nhiệm vụ giảm tốc độ chuyển động, dừng ô tô theo yêu cầu và giữ xe đứng yên khi cần thiết. Chương này giới thiệu công dụng, phân loại và cấu tạo chung của hệ thống phanh, trong đó tập trung vào cơ cấu phanh tang trống, cơ cấu phanh đĩa và các phương án dẫn động phanh. Các nội dung được triển khai từ đặc điểm cấu tạo, nguyên lý làm việc của từng bộ phận đến sự phối hợp giữa cơ cấu phanh và dẫn động phanh trong quá trình tạo lực phanh. Bên cạnh các hệ thống phanh sử dụng dẫn động cơ khí, thủy lực hoặc khí nén, chương còn đề cập đến những kết cấu và hệ thống điều khiển phanh được sử dụng trên ô tô hiện đại. 1. Công dụng Hệ thống phanh trên ô tô giữ vai trò quyết định đối với tính năng an toàn và vận hành của xe trong mọi điều kiện giao thông.","pages":[54]},{"id":"s1552","kind":"pdf","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"Hệ thống phanh có các công dụng sau: - Giảm tốc độ hoặc dừng hẳn xe theo ý muốn của người lái, đảm bảo hiệu quả phanh tin cậy trong cả điều kiện vận hành thông thường lẫn các tình huống khẩn cấp; - Cố định xe ở trạng thái đứng yên trên mặt đường bằng hoặc các mặt dốc theo thiết kế thông qua hệ thống phanh đỗ (phanh tay); - Duy trì vận tốc ổn định khi xe di chuyển trên các đoạn đường đèo dốc dài bằng phương thức kết hợp phanh phụ (phanh động cơ, phanh chậm dần); - Nâng cao độ ổn định hướng chuyển động và khả năng điều khiển thông qua việc tích hợp sâu các hệ thống hỗ trợ điện tử: ABS, EBD, BA, TRC và VSC/ESP. 2.","pages":[54]},{"id":"s1553","kind":"pdf","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"Phân loại a) Theo công dụng - Phanh chính: Đây là hệ thống phanh chủ đạo và được sử dụng với tần suất liên tục giúp người điều khiển chủ động giảm tốc độ hoặc dừng hẳn xe một cách an toàn trong suốt quá trình xe đang vận hành trên đường. - Phanh dừng: Hãm cứng các bánh xe giữ cho ô tô đứng yên tại chỗ, đảm bảo xe không bị trôi khi đang ở trạng thái không hoạt động hoặc đỗ trên đường dốc. - Phanh dự phòng: Chỉ được kích hoạt và sử dụng trong những tình huống khẩn cấp, cụ thể là khi hệ thống phanh chính gặp sự cố hỏng hóc hoặc hoàn toàn mất tác dụng. b) Theo kết cấu cơ cấu phanh - Cơ cấu phanh tang trống (Hình 10.1a): Sử dụng guốc phanh ép chặt vào mặt trong của tang trống để sinh lực cản ma sát. Toàn bộ cụm phanh được lắp đặt trên một mâm phanh (3) cố định.","pages":[54]},{"id":"s1554","kind":"pdf","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"Khi đạp phanh, áp lực truyền đến xi-lanh công tác (2) sẽ đẩy các má phanh (4) doãng ra ngoài và tì sát vào tang trống. - Cơ cấu phanh đĩa (Hình 10.1b): Cơ cấu này hoạt động theo nguyên lý dùng má phanh ép chặt vào hai bên bề mặt của đĩa phanh để giảm tốc độ. Gồm một đĩa","pages":[54]},{"id":"s1555","kind":"figure","lesson":"10.1.1","title":"Hình 10.1 Sơ đồ chung của hệ thống phanh 1. Bàn đạp phanh; 2. Cam phanh; 3. Tang trống; 4. Guốc phanh; 5. Chốt; 6. Má phanh;","text":"Hình 10.1 Sơ đồ chung của hệ thống phanh 1. Bàn đạp phanh; 2. Cam phanh; 3. Tang trống; 4. Guốc phanh; 5. Chốt; 6. Má phanh;","pages":[55],"figure":{"number":"10.1","caption":"Hình 10.1 Sơ đồ chung của hệ thống phanh 1. Bàn đạp phanh; 2. Cam phanh; 3. Tang trống; 4. Guốc phanh; 5. Chốt; 6. Má phanh;"}},{"id":"s1556","kind":"pdf","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"phanh (11) dạng hở, được liên kết quay đồng tốc với bánh xe thông qua vòng bi (8) và bu-lông bánh xe (12). Bao khép ngoài đĩa phanh là cụm càng phanh (9), bên trong chứa các má phanh (10) làm nhiệm vụ tì kẹp. c) Theo dẫn động phanh - Dẫn động cơ khí (cáp, đòn bẩy); - Dẫn động thủy lực; - Dẫn động khí nén; - Dẫn động kết hợp thủy lực - khí nén. d) Theo mức độ tự động hóa - Hệ thống phanh thường (không có điều khiển điện tử); - Hệ thống phanh có trang bị điều khiển điện tử: ABS, EBD, BA, và các hệ thống hỗ trợ khác như TRC, VSC. e) Sơ đồ nguyên lý làm việc chung của hệ thống phanh Sơ đồ nguyên lý làm việc cơ bản của hệ thống phanh sử dụng cơ cấu phanh tang trống và dẫn động cơ khí được thể hiện trên Hình 10.1.","pages":[55]},{"id":"s1557","kind":"pdf","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"Quá trình làm việc của hệ thống diễn ra theo hai trạng thái động lực học cơ bản: Trạng thái phanh: Khi người lái tác dụng lực lên bàn đạp phanh (1), lực này được truyền qua hệ thống các đòn kéo của cơ cấu dẫn động, làm xoay cam phanh (2). Chuyển động quay của cam phanh tạo ra lực đẩy thắng được lực đàn hồi của lò xo hồi vị (7), ép hai guốc phanh (4) bung rộng ra xung quanh tâm quay là chốt tựa (5). Khi đó, má phanh (6) bị ép chặt vào mặt trong của tang trống (3) (chi tiết đang quay đồng bộ cùng bánh xe), sinh ra mô-men ma sát. Mô-men ma sát này cản trở chuyển động quay của tang trống và bánh xe, tạo ra lực phanh ở vùng tiếp xúc giữa lốp và mặt đường, giúp ô tô giảm tốc độ hoặc dừng hẳn lại. Trạng thái nhả phanh: Khi người lái nhả chân khỏi bàn đạp phanh (1), lực tác dụng bị triệt tiêu.","pages":[55]},{"id":"s1558","kind":"pdf","lesson":"10.1.1","title":"Hệ thống phanh · Công dụng","text":"Dưới tác dụng của lò xo hồi vị tại bàn đạp và lò xo hồi vị guốc phanh (7), cam phanh (2) và toàn bộ hệ thống dẫn động nhanh chóng lùi về vị trí","pages":[55]},{"id":"s1559","kind":"figure","lesson":"10.2.1","title":"Hình 10.2. Cơ cấu phanh tang trống 1. Mâm phanh; 2, 3. Guốc phanh; 4, 5. Chốt định vị; 6. Trống phanh; 7. Cam phanh; 8.","text":"Hình 10.2. Cơ cấu phanh tang trống 1. Mâm phanh; 2, 3. Guốc phanh; 4, 5. Chốt định vị; 6. Trống phanh; 7. Cam phanh; 8.","pages":[56],"figure":{"number":"10.2","caption":"Hình 10.2. Cơ cấu phanh tang trống 1. Mâm phanh; 2, 3. Guốc phanh; 4, 5. Chốt định vị; 6. Trống phanh; 7. Cam phanh; 8."}},{"id":"s1560","kind":"figure","lesson":"10.2.1","title":"Hình 10.3. Trống phanh 1. Moay-ơ bánh xe; 2. Trống phanh; 3. Tấm phụ.","text":"Hình 10.3. Trống phanh 1. Moay-ơ bánh xe; 2. Trống phanh; 3. Tấm phụ.","pages":[56],"figure":{"number":"10.3","caption":"Hình 10.3. Trống phanh 1. Moay-ơ bánh xe; 2. Trống phanh; 3. Tấm phụ."}},{"id":"s1561","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"không làm việc ban đầu. Các guốc phanh (4) co lại, tách bề mặt má phanh (6) ra khỏi tang trống (3). Mô-men ma sát bị triệt tiêu hoàn toàn, bánh xe được giải phóng để ô tô tiếp tục chuyển động tự do. II. CƠ CẤU PHANH Cơ cấu phanh là bộ phận trực tiếp tạo ra mô men phanh cản trở chuyển động quay của bánh xe. Trên ô tô hiện đại có hai loại cơ cấu phanh cơ bản là cơ cấu phanh tang trống và cơ cấu phanh đĩa. 1. Cơ cấu phanh tang trống a) Cơ cấu phanh tang trống dẫn động thủy lực Lò xo hồi vị; 9. Bánh xe. Cơ cấu phanh tang trống (Hình 10.2) gồm các bộ phận chính: mâm phanh, tang trống, guốc phanh, xi-lanh bánh xe và lò xo hồi vị. Mâm phanh (Hình 10.2) thường là một tấm thép dập có dạng như một chiếc “mâm”.","pages":[56]},{"id":"s1562","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Trên xe có hệ thống treo phụ thuộc, mâm phanh được bắt cố định với cầu xe; trên xe có hệ thống treo độc lập, mâm phanh được bắt cố định với phần tử hướng của hệ thống treo. Các chi tiết và bộ phận khác của cơ cấu phanh như guốc phanh, bộ phận điều khiển và bộ phận điều chỉnh khe hở được lắp trên mâm phanh. Tang trống (trống phanh) được gắn chặt với moay-ơ bánh xe và quay cùng bánh xe khi xe chuyển động.","pages":[56]},{"id":"s1563","kind":"figure","lesson":"10.2.1","title":"Hình 10.4. Guốc phanh 1. Má phanh; 2, 3. Xương guốc phanh; 4. Đinh tán.","text":"Hình 10.4. Guốc phanh 1. Má phanh; 2, 3. Xương guốc phanh; 4. Đinh tán.","pages":[57],"figure":{"number":"10.4","caption":"Hình 10.4. Guốc phanh 1. Má phanh; 2, 3. Xương guốc phanh; 4. Đinh tán."}},{"id":"s1564","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Trống phanh thường được chế tạo bằng gang đúc hoặc thép đúc; mặt tiếp xúc với má phanh là một mặt trụ tròn được gia công có độ nhẵn và độ chính xác tương đối cao (bề mặt A trên Hình 10.3). Trống phanh nhận lực cản (ma sát) từ má phanh, đồng thời tiếp nhận nhiệt sinh ra do ma sát giữa trống phanh và má phanh rồi tỏa ra ngoài không khí. Khi lắp lên xe, trống phanh (Hình 10.3a và b) được cố định với moay-ơ bánh xe (chi tiết 1). Trong nhiều trường hợp (Hình 10.3b), để dễ chế tạo trống phanh (2), có thể dùng tấm phụ (3) để cố định trống phanh (2) với moay-ơ (1). Trống phanh trên Hình 10.3c được chế tạo bằng phương pháp dập và dùng cho xe nhỏ. Phía ngoài trống phanh có thể bố trí gân để tăng độ cứng và tản nhiệt tốt hơn. Trên trống phanh thường có một rãnh để kiểm tra khe hở má phanh (rãnh B trên Hình 10.3a).","pages":[57]},{"id":"s1565","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Guốc phanh: có lót má phanh, khi phanh, guốc phanh được ép vào mặt trong tang trống để sinh ra lực ma sát. Một guốc phanh có 2 chi tiết chính: xương guốc và má phanh. Trường hợp má phanh được cố định vào xương guốc bằng đinh tán thì có thêm chi tiết đinh tán. Xương guốc bằng kim loại, được chế tạo bằng phương pháp hàn (thép carbon) hoặc đúc (hợp kim nhôm hoặc gang). Nếu chế tạo bằng phương pháp hàn, xương guốc gồm 2 tấm thép (2 và 3 trên Hình 10.4) hàn với nhau. Nếu má phanh được tán vào xương guốc thì trên guốc phanh phải khoan các lỗ. Trên những xe nhỏ, má phanh có thể được gắn vào xương guốc bằng keo dán. Má phanh (Hình 10.4) được chế tạo từ vật liệu ma sát. Trước đây có thể sử dụng vật liệu ferôđô (Ferodo); hiện nay có nhiều loại vật liệu ma sát composite và vật liệu gốm có hệ số ma sát và độ bền phù hợp.","pages":[57]},{"id":"s1566","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Có nhiều cách lắp guốc phanh vào mâm phanh; cách thường gặp là lắp kiểu bản lề thông qua các chốt (Hình 10.2). Chốt (4) và (5) lắp vào mâm phanh; guốc phanh (2) và (3) lắp vào các chốt (4) và (5) và quay được quanh các chốt. Giữa chốt bản lề và guốc phanh có thể có bạc lệch tâm để điều chỉnh khe hở má phanh. Điểm tựa này của guốc phanh được gọi là điểm tựa dưới. Ở phía ngược lại, guốc phanh tựa vào bộ phận điều khiển và nhận lực từ bộ phận điều khiển; điểm tựa này được gọi là điểm tựa trên. Xi-lanh bánh xe (xi-lanh công tác): nhận áp suất dầu đẩy pít-tông tác động vào guốc phanh.","pages":[57]},{"id":"s1567","kind":"figure","lesson":"10.2.1","title":"Hình 10.5. Xi-lanh công tác 1, 6. Pít-tông; 2. Phớt; 3. Xi-lanh; 4. Nắp che bụi; 5. Chốt tựa guốc phanh; 7. Lò xo.","text":"Hình 10.5. Xi-lanh công tác 1, 6. Pít-tông; 2. Phớt; 3. Xi-lanh; 4. Nắp che bụi; 5. Chốt tựa guốc phanh; 7. Lò xo.","pages":[58],"figure":{"number":"10.5","caption":"Hình 10.5. Xi-lanh công tác 1, 6. Pít-tông; 2. Phớt; 3. Xi-lanh; 4. Nắp che bụi; 5. Chốt tựa guốc phanh; 7. Lò xo."}},{"id":"s1568","kind":"figure","lesson":"10.2.1","title":"Hình 10.6. Bố trí xi-lanh công tác trên cơ cấu phanh tang trống a) Cơ cấu phanh có 2 điểm tựa riêng rẽ về một phía, lực dẫn động lên các guốc phanh","text":"Hình 10.6. Bố trí xi-lanh công tác trên cơ cấu phanh tang trống a) Cơ cấu phanh có 2 điểm tựa riêng rẽ về một phía, lực dẫn động lên các guốc phanh","pages":[58],"figure":{"number":"10.6","caption":"Hình 10.6. Bố trí xi-lanh công tác trên cơ cấu phanh tang trống a) Cơ cấu phanh có 2 điểm tựa riêng rẽ về một phía, lực dẫn động lên các guốc phanh"}},{"id":"s1569","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Bộ phận tạo ra lực đẩy vào guốc phanh của loại dẫn động chất lỏng có nhiệm vụ biến áp suất chất lỏng thành lực đẩy vào guốc phanh. Kết cấu của bộ phận này thể hiện trên Hình 10.5, gồm xi-lanh công tác (3), hai pít-tông công tác (1) và (6) có các phớt làm kín (2). Đầu mỗi pít-tông có chốt tựa (5) để guốc phanh tựa vào. Hai đầu xi-lanh có các nắp (4) bằng cao su để chắn bụi. Lỗ B dẫn chất lỏng vào xi-lanh, lỗ A dùng để xả khí. Khi phanh, chất lỏng có áp suất cao được dẫn qua lỗ B vào xi-lanh. Áp suất chất lỏng đẩy các pít-tông (1) và (6) ra hai phía và thông qua các chốt tựa (5) đẩy các guốc phanh áp sát vào trống phanh. Lò xo hồi vị: kéo guốc phanh về vị trí ban đầu khi nhả phanh. Tấm đỡ: gắn cố định trên cầu xe, giữ các chi tiết cơ cấu phanh.","pages":[58]},{"id":"s1570","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Bố trí các xi-lanh công tác trên cơ cấu phanh tang trống (Hình 10.6): b) Cơ cấu phanh có 2 điểm tựa riêng rẽ về hai phía, lực dẫn động lên các guốc phanh c) Cơ cấu phanh có 1 điểm tựa cố định chung cho 2 guốc phanh, lực dẫn động tác dụng lên các guốc phanh bằng nhau. Nguyên lý làm việc Khi phanh, áp suất dầu trong xi-lanh công tác tăng. Áp suất dầu tác dụng lên các pít-tông, làm pít-tông và guốc phanh dịch chuyển, ép má phanh vào mặt trong","pages":[58]},{"id":"s1571","kind":"figure","lesson":"10.2.1","title":"Hình 10.7. Kết cấu cơ cấu phanh 1 xi-lanh 1. Chốt bản lề; 2. Mâm phanh; 3. Vòng lệch tâm; 4. Cam lệch tâm; 5. Bu lông điều chỉnh;","text":"Hình 10.7. Kết cấu cơ cấu phanh 1 xi-lanh 1. Chốt bản lề; 2. Mâm phanh; 3. Vòng lệch tâm; 4. Cam lệch tâm; 5. Bu lông điều chỉnh;","pages":[59],"figure":{"number":"10.7","caption":"Hình 10.7. Kết cấu cơ cấu phanh 1 xi-lanh 1. Chốt bản lề; 2. Mâm phanh; 3. Vòng lệch tâm; 4. Cam lệch tâm; 5. Bu lông điều chỉnh;"}},{"id":"s1572","kind":"figure","lesson":"10.2.1","title":"Hình 10.8. Kết cấu cơ cấu phanh 2 xi-lanh 1, 8. Xi-lanh; 2. Vít xả khí; 3. Ống dẫn dầu; 4. Mâm phanh; 5, 9. Chốt bản lề;","text":"Hình 10.8. Kết cấu cơ cấu phanh 2 xi-lanh 1, 8. Xi-lanh; 2. Vít xả khí; 3. Ống dẫn dầu; 4. Mâm phanh; 5, 9. Chốt bản lề;","pages":[59],"figure":{"number":"10.8","caption":"Hình 10.8. Kết cấu cơ cấu phanh 2 xi-lanh 1, 8. Xi-lanh; 2. Vít xả khí; 3. Ống dẫn dầu; 4. Mâm phanh; 5, 9. Chốt bản lề;"}},{"id":"s1573","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"tang trống. Khi nhả phanh, áp suất dầu trong xi-lanh công tác giảm, lò xo kéo các guốc phanh trở về vị trí ban đầu, má phanh được tách khỏi tang trống. Ứng dụng, ưu nhược điểm - Cơ cấu phanh tang trống được dùng rộng rãi trên ô tô tải, xe khách, nhiều loại xe du lịch đời cũ; hiện nay vẫn phổ biến ở bánh sau của nhiều xe du lịch cỡ nhỏ và ở cả bốn bánh của xe tải hoặc xe khách do chi phí hợp lý và lực phanh cao. - Ưu điểm: kết cấu kín, dễ bảo vệ khỏi bụi bẩn, giá thành rẻ, lực hãm lớn. - Nhược điểm: khả năng tản nhiệt kém, dễ mất hiệu quả phanh khi làm việc liên tục ở tốc độ cao. Kết cấu cơ cấu phanh tang trống dùng một xi-lanh và hai xi-lanh công tác thể hiện trên Hình 10.7 và Hình 10.8. 6, 9. Guốc phanh; 7, 10. Má phanh; 8. Xi-lanh; 11. Ốc hãm. 6, 10. Guốc phanh; 7, 12. Cam lệch tâm; 11. Chốt giữ guốc phanh.","pages":[59]},{"id":"s1574","kind":"figure","lesson":"10.2.1","title":"Hình 10.9. Điều khiển guốc phanh bằng cam phanh a) Sơ đồ bố trí; b) Kết cấu cam phanh. 1. Cam phanh; 2, 3. Các thanh dẫn động.","text":"Hình 10.9. Điều khiển guốc phanh bằng cam phanh a) Sơ đồ bố trí; b) Kết cấu cam phanh. 1. Cam phanh; 2, 3. Các thanh dẫn động.","pages":[60],"figure":{"number":"10.9","caption":"Hình 10.9. Điều khiển guốc phanh bằng cam phanh a) Sơ đồ bố trí; b) Kết cấu cam phanh. 1. Cam phanh; 2, 3. Các thanh dẫn động."}},{"id":"s1575","kind":"figure","lesson":"10.2.1","title":"Hình 10.10. Điều khiển guốc phanh bằng cơ cấu nêm 1, 6. Guốc phanh; 2. Thân cơ cấu điều khiển; 3, 5. Thanh trượt; 4a. Miếng vát; 4b. Con","text":"Hình 10.10. Điều khiển guốc phanh bằng cơ cấu nêm 1, 6. Guốc phanh; 2. Thân cơ cấu điều khiển; 3, 5. Thanh trượt; 4a. Miếng vát; 4b. Con","pages":[60],"figure":{"number":"10.10","caption":"Hình 10.10. Điều khiển guốc phanh bằng cơ cấu nêm 1, 6. Guốc phanh; 2. Thân cơ cấu điều khiển; 3, 5. Thanh trượt; 4a. Miếng vát; 4b. Con"}},{"id":"s1576","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"b) Cơ cấu phanh tang trống dẫn động cơ khí Cơ cấu phanh tang trống dẫn động cơ khí có cấu tạo cụm ma sát hoàn toàn tương tự loại thủy lực. Điểm khác biệt là thay vì dùng áp suất dầu đẩy pít-tông, hệ thống sử dụng lực cơ học thông qua cam phanh (Hình 10.9) hoặc cơ cấu nêm (Hình 10.10) để doãng guốc phanh. Điều khiển bằng cam phanh (Hình 10.9): Cam phanh (thường có biên dạng chữ S hoặc lệch tâm) được làm quay bởi hệ thống đòn dẫn động (2, 3). Khi xoay, biên dạng cam cưỡng bức hai đầu guốc phanh mở rộng, ép sát má phanh vào tang trống. Thiết kế này chịu tải lớn rất tốt, do đó trở thành giải pháp tiêu chuẩn trên hệ thống phanh khí nén của ô tô tải và xe khách. Điều khiển bằng cơ cấu nêm (Hình 10.10): Lực đẩy dọc trục (Fc) tác dụng lên thanh đẩy (7) làm dịch chuyển khối nêm (4a).","pages":[60]},{"id":"s1577","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Thông qua ma sát trượt hoặc các con lăn (4b), khối nêm ép hai chốt đẩy (3, 5) dịch chuyển ngang, bung guốc phanh (1, 6) thực hiện quá trình hãm. Ngoài ra, cơ cấu phanh dẫn động hoàn toàn bằng hệ thống cơ khí (cáp kéo, thanh đòn) hiện nay chủ yếu được tích hợp làm hệ thống phanh dừng (phanh đỗ xe). Loại dẫn động cơ cấu phanh bằng cơ khí thường áp dụng cho hệ thống phanh tay (phanh dừng) như trên Hình 10.11 và Hình 10.12.","pages":[60]},{"id":"s1578","kind":"figure","lesson":"10.2.1","title":"Hình 10.11. Cơ cấu phanh tay trên xe Zil 131","text":"Hình 10.11. Cơ cấu phanh tay trên xe Zil 131","pages":[61],"figure":{"number":"10.11","caption":"Hình 10.11. Cơ cấu phanh tay trên xe Zil 131"}},{"id":"s1579","kind":"figure","lesson":"10.2.1","title":"Hình 10.12. Cơ cấu phanh tay xe Ural 4320 c) Cơ cấu phanh tang trống dẫn động khí nén Tương tự như ở dẫn động chất lỏng, bộ phận tạo ra lực đẩy vào guốc phanh của loại dẫn động khí nén có nhiệm vụ biến áp suất khí nén thành lực đẩy vào guốc phanh (Hình 10.13 và 10.14). Vì bầu phanh phải bố trí ngoài trống phanh nên khí nén không tác động trực tiếp vào guốc phanh như dẫn động chất lỏng mà phải thông qua một cơ cấu dẫn động.","text":"Hình 10.12. Cơ cấu phanh tay xe Ural 4320 c) Cơ cấu phanh tang trống dẫn động khí nén Tương tự như ở dẫn động chất lỏng, bộ phận tạo ra lực đẩy vào guốc phanh của loại dẫn động khí nén có nhiệm vụ biến áp suất khí nén thành lực đẩy vào guốc phanh (Hình 10.13 và 10.14). Vì bầu phanh phải bố trí ngoài trống phanh nên khí nén không tác động trực tiếp vào guốc phanh như dẫn động chất lỏng mà phải thông qua một cơ cấu dẫn động.","pages":[61],"figure":{"number":"10.12","caption":"Hình 10.12. Cơ cấu phanh tay xe Ural 4320 c) Cơ cấu phanh tang trống dẫn động khí nén Tương tự như ở dẫn động chất lỏng, bộ phận tạo ra lực đẩy vào guốc phanh của loại dẫn động khí nén có nhiệm vụ biến áp suất khí nén thành lực đẩy vào guốc phanh (Hình 10.13 và 10.14). Vì bầu phanh phải bố trí ngoài trống phanh nên khí nén không tác động trực tiếp vào guốc phanh như dẫn động chất lỏng mà phải thông qua một cơ cấu dẫn động."}},{"id":"s1580","kind":"figure","lesson":"10.2.1","title":"Hình 10.13. Điều khiển guốc phanh ở dẫn động phanh khí nén 1. Bầu phanh; 2. Thanh đẩy; 3. Đòn quay; 4. Cam phanh; 5. Màng sinh lực.","text":"Hình 10.13. Điều khiển guốc phanh ở dẫn động phanh khí nén 1. Bầu phanh; 2. Thanh đẩy; 3. Đòn quay; 4. Cam phanh; 5. Màng sinh lực.","pages":[61],"figure":{"number":"10.13","caption":"Hình 10.13. Điều khiển guốc phanh ở dẫn động phanh khí nén 1. Bầu phanh; 2. Thanh đẩy; 3. Đòn quay; 4. Cam phanh; 5. Màng sinh lực."}},{"id":"s1581","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Nguyên lý làm việc: Khi người lái tác động lên bàn đạp phanh, van phanh tổng điều khiển dòng khí nén từ bình chứa đến bầu phanh. Khí nén tác dụng lên màng bầu phanh, làm thanh đẩy dịch chuyển và quay cam phanh. Cam phanh ép guốc phanh vào tang trống, tạo ra ma sát làm chậm bánh xe. Khi nhả phanh, lò xo hồi vị kéo guốc phanh về vị trí ban đầu, bánh xe quay tự do.","pages":[61]},{"id":"s1582","kind":"figure","lesson":"10.2.1","title":"Hình 10.14. Kết cấu cơ cấu phanh dẫn động khí nén 1. Giá đỡ; 2. Guốc phanh; 3. Trống phanh; 4. Cam phanh; 5. Chốt tựa má phanh; 6. Má phanh;","text":"Hình 10.14. Kết cấu cơ cấu phanh dẫn động khí nén 1. Giá đỡ; 2. Guốc phanh; 3. Trống phanh; 4. Cam phanh; 5. Chốt tựa má phanh; 6. Má phanh;","pages":[62],"figure":{"number":"10.14","caption":"Hình 10.14. Kết cấu cơ cấu phanh dẫn động khí nén 1. Giá đỡ; 2. Guốc phanh; 3. Trống phanh; 4. Cam phanh; 5. Chốt tựa má phanh; 6. Má phanh;"}},{"id":"s1583","kind":"figure","lesson":"10.2.1","title":"Hình 10.15. Cơ cấu điều chỉnh khe hở 1, 4. Thanh đẩy; 2. Bu lông; 3. Bánh răng; 5. Cam lệch tâm; 6, 7. Bu lông điều chỉnh; 8.","text":"Hình 10.15. Cơ cấu điều chỉnh khe hở 1, 4. Thanh đẩy; 2. Bu lông; 3. Bánh răng; 5. Cam lệch tâm; 6, 7. Bu lông điều chỉnh; 8.","pages":[62],"figure":{"number":"10.15","caption":"Hình 10.15. Cơ cấu điều chỉnh khe hở 1, 4. Thanh đẩy; 2. Bu lông; 3. Bánh răng; 5. Cam lệch tâm; 6, 7. Bu lông điều chỉnh; 8."}},{"id":"s1584","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"7. Mâm phanh; 8, 9. Trục vít, bánh vít; 10. Đòn quay; 11. Thanh đẩy; 12. Bầu phanh. d) Cơ cấu điều chỉnh khe hở giữa má phanh và tang trống Trong quá trình làm việc, bề mặt má phanh bị mài mòn làm tăng khe hở giữa má phanh và tang trống. Khe hở vượt quá giới hạn chuẩn không chỉ kéo dài thời gian chậm tác dụng của hệ thống phanh mà còn làm giảm mô-men phanh, do diện tích tiếp xúc thực tế giữa má phanh và tang trống bị suy giảm. Vì vậy, khe hở này cần được khắc phục kịp thời để duy trì hiệu quả phanh. Việc điều chỉnh có thể được thực hiện bằng tay hoặc thông qua cơ cấu điều chỉnh tự động. * Loại điều chỉnh bằng tay Vòng lệch tâm; 9. Guốc phanh.","pages":[62]},{"id":"s1585","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Điều chỉnh khe hở giữa má phanh và trống phanh ở trên các xe du lịch: Phương pháp điều chỉnh khe hở bằng tay thường sử dụng cơ cấu trục ren kết hợp bánh răng điều chỉnh (Hình 10.15b) hoặc chốt cam lệch tâm (Hình 10.15c, d). Để thực hiện, người thợ dùng tua-vít gạt bánh răng điều chỉnh nhằm đẩy hai guốc phanh doãng rộng ra cho đến khi má phanh chạm sát vào mặt trong của tang trống (Hình 10.15). Sau đó, gạt ngược bánh răng lại một số nấc nhất định theo đúng tiêu chuẩn kỹ thuật của nhà sản xuất để thiết lập khe hở theo đúng khuyến nghị của nhà sản xuất.","pages":[62]},{"id":"s1586","kind":"figure","lesson":"10.2.1","title":"Hình 10.16. Điều chỉnh khe hở má phanh của phanh dẫn động khí nén 1. Bầu phanh; 2. Thanh đẩy; 3. Đòn quay; 4, 5. Bộ truyền trục vít bánh vít; 6. Trục cam quay.","text":"Hình 10.16. Điều chỉnh khe hở má phanh của phanh dẫn động khí nén 1. Bầu phanh; 2. Thanh đẩy; 3. Đòn quay; 4, 5. Bộ truyền trục vít bánh vít; 6. Trục cam quay.","pages":[63],"figure":{"number":"10.16","caption":"Hình 10.16. Điều chỉnh khe hở má phanh của phanh dẫn động khí nén 1. Bầu phanh; 2. Thanh đẩy; 3. Đòn quay; 4, 5. Bộ truyền trục vít bánh vít; 6. Trục cam quay."}},{"id":"s1587","kind":"figure","lesson":"10.2.1","title":"Hình 10.17. Phương pháp điều chỉnh phanh tay tự động 1. Tang trống; 2. Má phanh; 3. Khe hở giữa má phanh với tang trống; 4. Cần điều chỉnh;","text":"Hình 10.17. Phương pháp điều chỉnh phanh tay tự động 1. Tang trống; 2. Má phanh; 3. Khe hở giữa má phanh với tang trống; 4. Cần điều chỉnh;","pages":[63],"figure":{"number":"10.17","caption":"Hình 10.17. Phương pháp điều chỉnh phanh tay tự động 1. Tang trống; 2. Má phanh; 3. Khe hở giữa má phanh với tang trống; 4. Cần điều chỉnh;"}},{"id":"s1588","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Điều chỉnh khe hở giữa má phanh và trống phanh ở trên các xe tải: Trên các xe tải, cơ cấu điều chỉnh thường được bố trí ở hai vị trí: - Vị trí thứ nhất trên chốt quay cố định của guốc phanh (chi tiết 5 trên Hình 10.14); - Vị trí thứ hai nằm sát phần trên của guốc phanh bằng cam lệch tâm (chi tiết 7, 12 trên Hình 10.8) hoặc ở ngay trục cam phanh (chi tiết 4 trên Hình 10.16). * Loại tự động điều chỉnh Việc điều chỉnh bằng tay đôi khi thiếu chính xác vì phụ thuộc vào trình độ của người thợ; hơn nữa, việc điều chỉnh nhiều khi không kịp thời nên khe hở tăng quá tiêu chuẩn, làm giảm hiệu quả phanh. Để khắc phục nhược điểm trên, hiện nay trên một số ô tô sử dụng cơ cấu tự động điều chỉnh khe hở giữa má phanh và trống phanh (Hình 10.17). 5. Cơ cấu điều chỉnh; 6. Cần kéo; 7,10. Cần điều chỉnh; 8,9. Cơ cấu điều chỉnh.","pages":[63]},{"id":"s1589","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"Cơ cấu này tận dụng càng phanh tay và thanh nối giữa càng phanh tay với guốc phanh còn lại làm cơ cấu điều chỉnh. Trên thanh nối bố trí một bánh xe điều chỉnh liền với bu lông điều chỉnh; trên càng phanh tay lắp thêm một cần điều chỉnh. Mỗi lần kéo phanh tay, càng phanh tay và cần điều chỉnh xoay một góc nào đó. Khi khe hở giữa má phanh và trống phanh còn nằm trong giá trị cho phép, góc quay của cần điều chỉnh","pages":[63]},{"id":"s1590","kind":"figure","lesson":"10.2.2","title":"Hình 10.18. Cấu tạo phanh đĩa 1. Má phanh; 2. Giá đỡ xi-lanh; 3. Bu lông; 4. Vít xả; 5. Giá đỡ má phanh; 6. Lò xo.","text":"Hình 10.18. Cấu tạo phanh đĩa 1. Má phanh; 2. Giá đỡ xi-lanh; 3. Bu lông; 4. Vít xả; 5. Giá đỡ má phanh; 6. Lò xo.","pages":[64],"figure":{"number":"10.18","caption":"Hình 10.18. Cấu tạo phanh đĩa 1. Má phanh; 2. Giá đỡ xi-lanh; 3. Bu lông; 4. Vít xả; 5. Giá đỡ má phanh; 6. Lò xo."}},{"id":"s1591","kind":"pdf","lesson":"10.2.1","title":"Hệ thống phanh · Cơ cấu phanh tang trống.","text":"nhỏ hơn bước răng của bánh xe điều chỉnh; do đó, sau khi nhả phanh tay, cần điều chỉnh không gạt lên răng và bánh xe điều chỉnh không xoay. Khi khe hở giữa má phanh và trống phanh lớn hơn giá trị cho phép, góc quay của cần điều chỉnh lớn hơn bước răng của bánh xe điều chỉnh. Do đó, khi kéo phanh tay, cần điều chỉnh ăn khớp với răng kế tiếp của bánh xe điều chỉnh; khi nhả phanh tay, cần điều chỉnh gạt lên răng làm bánh xe điều chỉnh xoay một góc tương ứng. Kết quả là bu lông điều chỉnh của thanh nối cũng quay một góc tương ứng, đẩy hai guốc phanh ra một khoảng, bù lại khe hở đã tăng lên giữa má phanh và trống phanh. 2. Cơ cấu phanh đĩa a) Đặc điểm cấu tạo Cơ cấu phanh đĩa (Hình 10.18) gồm các bộ phận chính sau: Đĩa phanh (Hình 10.19): gắn với moay-ơ bánh xe, quay cùng bánh xe. Đĩa phanh tạo ra bề mặt ma sát với má phanh và được làm bằng thép đúc.","pages":[64]},{"id":"s1592","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"Tùy theo điều kiện sử dụng của từng xe, đĩa phanh có nhiều loại khác nhau. Cụm giá đỡ (caliper) hay càng phanh (Hình 10.20): nằm cùng moay-ơ, chứa pít-tông và má phanh. Càng phanh có 2 kiểu kết cấu: càng phanh cố định và càng phanh di động.","pages":[64]},{"id":"s1593","kind":"figure","lesson":"10.2.2","title":"Hình 10.20. Càng phanh cố định 1. Đĩa phanh; 2. Má phanh; 3. Càng phanh cố định; 4. Pít-tông phanh.","text":"Hình 10.20. Càng phanh cố định 1. Đĩa phanh; 2. Má phanh; 3. Càng phanh cố định; 4. Pít-tông phanh.","pages":[65],"figure":{"number":"10.20","caption":"Hình 10.20. Càng phanh cố định 1. Đĩa phanh; 2. Má phanh; 3. Càng phanh cố định; 4. Pít-tông phanh."}},{"id":"s1594","kind":"figure","lesson":"10.2.2","title":"Hình 10.21. Càng phanh di động 1. Moay-ơ bánh xe; 2. Vành bánh xe; 3, 5. Má phanh; 4. Đĩa phanh; 6. Xi-lanh; 7. Phớt;","text":"Hình 10.21. Càng phanh di động 1. Moay-ơ bánh xe; 2. Vành bánh xe; 3, 5. Má phanh; 4. Đĩa phanh; 6. Xi-lanh; 7. Phớt;","pages":[65],"figure":{"number":"10.21","caption":"Hình 10.21. Càng phanh di động 1. Moay-ơ bánh xe; 2. Vành bánh xe; 3, 5. Má phanh; 4. Đĩa phanh; 6. Xi-lanh; 7. Phớt;"}},{"id":"s1595","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"- Loại càng phanh cố định: gồm hai xi-lanh công tác đặt hai bên, số xi-lanh có thể là bốn đặt đối xứng nhau hoặc ba xi-lanh trong đó hai xi-lanh bé một bên và một xi-lanh lớn một bên. - Loại càng phanh di động (Hình 10.21): sử dụng một xi-lanh, giá đỡ xi-lanh được di động trên trục dẫn hướng. Khi phanh, má phanh bị đẩy vào đĩa phanh, đồng thời càng phanh trượt theo chiều ngược lại, nhờ đó đĩa phanh bị ép từ cả hai bên. Điều chỉnh khe hở má phanh trên cơ cấu phanh đĩa (Hình 10.21): khe hở giữa má phanh và đĩa phanh rất nhỏ. Khi nhả phanh, cơ cấu hồi vị giúp má phanh tách nhẹ khỏi đĩa phanh và duy trì khe hở làm việc cần thiết. Khe hở má phanh trên cơ cấu phanh đĩa được tạo ra nhờ sự đàn hồi của phớt làm kín (7).","pages":[65]},{"id":"s1596","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"Phớt làm kín (7) bằng cao su lắp trên pít-tông (8) (thể hiện ở mặt cắt I) vừa có tác dụng làm kín, vừa có tác dụng tạo ra khe hở giữa má phanh và đĩa phanh. Khi phanh, pít-tông (8) dịch chuyển sang trái và làm lệch phớt; khi nhả phanh, phớt trở về vị trí ban đầu làm pít- tông di chuyển sang phải và tạo ra khe hở giữa má phanh và đĩa phanh. 8. Pít-tông; 9. Vít xả không khí; 10. Đường ống dẫn dầu phanh; 11. Giá đỡ xi-lanh Pít-tông thủy lực (Hình 10.22): đặt trong xi-lanh của cụm caliper, nhận áp suất dầu và tạo lực ép má phanh vào đĩa phanh.","pages":[65]},{"id":"s1597","kind":"figure","lesson":"10.2.2","title":"Hình 10.22. Pít-tông phanh đĩa Má phanh (Hình 10.23): Đóng vai trò là chi tiết trực tiếp sinh ra mô-men ma sát khi bị pít-tông ép chặt vào hai bên mặt đĩa phanh. Cấu tạo chi tiết của má phanh bao gồm:","text":"Hình 10.22. Pít-tông phanh đĩa Má phanh (Hình 10.23): Đóng vai trò là chi tiết trực tiếp sinh ra mô-men ma sát khi bị pít-tông ép chặt vào hai bên mặt đĩa phanh. Cấu tạo chi tiết của má phanh bao gồm:","pages":[66],"figure":{"number":"10.22","caption":"Hình 10.22. Pít-tông phanh đĩa Má phanh (Hình 10.23): Đóng vai trò là chi tiết trực tiếp sinh ra mô-men ma sát khi bị pít-tông ép chặt vào hai bên mặt đĩa phanh. Cấu tạo chi tiết của má phanh bao gồm:"}},{"id":"s1598","kind":"figure","lesson":"10.2.2","title":"Hình 10.23. Má phanh 1. Xương thép; 2. Má phanh; 3. Tấm lót; 4. Rãnh","text":"Hình 10.23. Má phanh 1. Xương thép; 2. Má phanh; 3. Tấm lót; 4. Rãnh","pages":[66],"figure":{"number":"10.23","caption":"Hình 10.23. Má phanh 1. Xương thép; 2. Má phanh; 3. Tấm lót; 4. Rãnh"}},{"id":"s1599","kind":"figure","lesson":"10.2.2","title":"Hình 10.24. Nguyên lý hồi vị của pít-tông","text":"Hình 10.24. Nguyên lý hồi vị của pít-tông","pages":[66],"figure":{"number":"10.24","caption":"Hình 10.24. Nguyên lý hồi vị của pít-tông"}},{"id":"s1600","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"- Đế thép làm bệ đỡ và khung truyền lực chính; - Lớp vật liệu ma sát được dán ép cố định lên mặt trước của đế thép, trực tiếp cọ xát với đĩa phanh; - Tấm đệm chống ồn ở mặt sau đế thép, có tác dụng triệt tiêu rung động gây ồn và cách nhiệt, ngăn nhiệt lượng truyền ngược vào buồng chứa dầu phanh. - Rãnh cắt được xẻ dọc trên bề mặt lớp ma sát nhằm tăng cường khả năng tản nhiệt, thoát mùn cặn/nước và đóng vai trò làm chuẩn chỉ thị độ mòn tối thiểu. Cơ cấu hồi vị và chốt trượt (Hình 10.24): Đảm nhận nhiệm vụ tách má phanh khỏi đĩa phanh khi kết thúc quá trình phanh. Cụ thể, nguyên lý hồi vị của pít-tông (Hình 10.24) được thực hiện dựa vào tính đàn hồi của vòng đệm cao su làm kín. Khi đạp phanh, pít-tông dịch chuyển làm vòng đệm bị biến dạng.","pages":[66]},{"id":"s1601","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"Khi nhả phanh, vòng đệm phục hồi hình dáng ban đầu, kéo pít-tông lùi lại một khoảng nhỏ để tạo khe hở giữa má phanh và đĩa phanh.","pages":[66]},{"id":"s1602","kind":"figure","lesson":"10.2.2","title":"Hình 10.25. Cơ cấu chỉ báo mòn má phanh b) Nguyên lý làm việc Khi người lái đạp bàn đạp phanh, áp suất dầu từ xi-lanh chính truyền qua ống dẫn, tác động vào pít-tông nằm bên trong ngàm phanh (Hình 10.26). Dưới tác dụng của áp suất thủy lực, pít-tông dịch chuyển và ép các má phanh tỳ chặt vào hai mặt của đĩa phanh. Lực ma sát sinh ra giữa má phanh và đĩa phanh tạo thành mô-men hãm chuyển động quay của bánh xe, giúp ô tô giảm tốc hoặc dừng hẳn. Khi nhả bàn đạp phanh, áp suất dầu giảm, pít-tông lùi về vị trí ban đầu nhờ lực hồi vị đàn hồi, tách má phanh ra khỏi mặt đĩa.","text":"Hình 10.25. Cơ cấu chỉ báo mòn má phanh b) Nguyên lý làm việc Khi người lái đạp bàn đạp phanh, áp suất dầu từ xi-lanh chính truyền qua ống dẫn, tác động vào pít-tông nằm bên trong ngàm phanh (Hình 10.26). Dưới tác dụng của áp suất thủy lực, pít-tông dịch chuyển và ép các má phanh tỳ chặt vào hai mặt của đĩa phanh. Lực ma sát sinh ra giữa má phanh và đĩa phanh tạo thành mô-men hãm chuyển động quay của bánh xe, giúp ô tô giảm tốc hoặc dừng hẳn. Khi nhả bàn đạp phanh, áp suất dầu giảm, pít-tông lùi về vị trí ban đầu nhờ lực hồi vị đàn hồi, tách má phanh ra khỏi mặt đĩa.","pages":[67],"figure":{"number":"10.25","caption":"Hình 10.25. Cơ cấu chỉ báo mòn má phanh b) Nguyên lý làm việc Khi người lái đạp bàn đạp phanh, áp suất dầu từ xi-lanh chính truyền qua ống dẫn, tác động vào pít-tông nằm bên trong ngàm phanh (Hình 10.26). Dưới tác dụng của áp suất thủy lực, pít-tông dịch chuyển và ép các má phanh tỳ chặt vào hai mặt của đĩa phanh. Lực ma sát sinh ra giữa má phanh và đĩa phanh tạo thành mô-men hãm chuyển động quay của bánh xe, giúp ô tô giảm tốc hoặc dừng hẳn. Khi nhả bàn đạp phanh, áp suất dầu giảm, pít-tông lùi về vị trí ban đầu nhờ lực hồi vị đàn hồi, tách má phanh ra khỏi mặt đĩa."}},{"id":"s1603","kind":"figure","lesson":"10.2.2","title":"Hình 10.26. Nguyên lý làm việc cơ cấu phanh đĩa c) Ứng dụng So với phanh tang trống, phanh đĩa có cấu trúc hở giúp tản nhiệt tốt, duy trì hiệu quả phanh ổn định ở tốc độ cao và có khả năng tự làm sạch bụi bẩn, nước thông qua lực ly tâm. Được ứng dụng:","text":"Hình 10.26. Nguyên lý làm việc cơ cấu phanh đĩa c) Ứng dụng So với phanh tang trống, phanh đĩa có cấu trúc hở giúp tản nhiệt tốt, duy trì hiệu quả phanh ổn định ở tốc độ cao và có khả năng tự làm sạch bụi bẩn, nước thông qua lực ly tâm. Được ứng dụng:","pages":[67],"figure":{"number":"10.26","caption":"Hình 10.26. Nguyên lý làm việc cơ cấu phanh đĩa c) Ứng dụng So với phanh tang trống, phanh đĩa có cấu trúc hở giúp tản nhiệt tốt, duy trì hiệu quả phanh ổn định ở tốc độ cao và có khả năng tự làm sạch bụi bẩn, nước thông qua lực ly tâm. Được ứng dụng:"}},{"id":"s1604","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"Cơ cấu báo mòn má phanh (Hình 10.25): Có chức năng phát tín hiệu cảnh báo cho người lái khi chiều dày của vật liệu ma sát đã giảm đến giới hạn mòn cho phép. Cơ cấu này được chia thành hai loại là loại cơ khí và loại điện tử. Loại cơ khí sử dụng một lá thép đàn hồi; khi má phanh mòn đến giới hạn, lá thép sẽ cọ xát trực tiếp vào đĩa phanh sinh ra tiếng rít cảnh báo. Loại điện tử tích hợp một tiếp điểm đặt chìm trong má phanh; khi bề mặt ma sát mòn tới tiếp điểm, sự tiếp xúc với đĩa phanh sẽ làm đóng hoặc ngắt mạch điện, kích hoạt đèn cảnh báo trên bảng điều khiển.","pages":[67]},{"id":"s1605","kind":"figure","lesson":"10.2.2","title":"Hình 10.27. Cơ cấu phanh đĩa, dẫn động khí nén","text":"Hình 10.27. Cơ cấu phanh đĩa, dẫn động khí nén","pages":[68],"figure":{"number":"10.27","caption":"Hình 10.27. Cơ cấu phanh đĩa, dẫn động khí nén"}},{"id":"s1606","kind":"figure","lesson":"10.2.2","title":"Hình 10.27 thể hiện một cơ cấu phanh đĩa dẫn động khí nén. Bầu phanh (10) được lắp chặt với giá (8); giá (8) có thể di chuyển theo phương của trục bánh xe. Trên giá (8) lắp má phanh (1). Má phanh (3) lắp với thanh đẩy (5). Thanh đẩy (5) tựa vào đòn quay (7) thông qua khớp (6). Thanh đẩy (9) nhận lực từ màng phanh (11) và đẩy vào đầu trên của đòn quay (7). Đĩa phanh (2) lắp với moay-ơ bánh xe.","text":"Hình 10.27 thể hiện một cơ cấu phanh đĩa dẫn động khí nén. Bầu phanh (10) được lắp chặt với giá (8); giá (8) có thể di chuyển theo phương của trục bánh xe. Trên giá (8) lắp má phanh (1). Má phanh (3) lắp với thanh đẩy (5). Thanh đẩy (5) tựa vào đòn quay (7) thông qua khớp (6). Thanh đẩy (9) nhận lực từ màng phanh (11) và đẩy vào đầu trên của đòn quay (7). Đĩa phanh (2) lắp với moay-ơ bánh xe.","pages":[68],"figure":{"number":"10.27","caption":"Hình 10.27 thể hiện một cơ cấu phanh đĩa dẫn động khí nén. Bầu phanh (10) được lắp chặt với giá (8); giá (8) có thể di chuyển theo phương của trục bánh xe. Trên giá (8) lắp má phanh (1). Má phanh (3) lắp với thanh đẩy (5). Thanh đẩy (5) tựa vào đòn quay (7) thông qua khớp (6). Thanh đẩy (9) nhận lực từ màng phanh (11) và đẩy vào đầu trên của đòn quay (7). Đĩa phanh (2) lắp với moay-ơ bánh xe."}},{"id":"s1607","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"- Các dòng xe ô tô con hiện đại và xe hiệu suất cao thường trang bị phanh đĩa trên tất cả các bánh xe. - Trên các dòng xe thương mại cỡ nhỏ hoặc xe tải nhẹ, phanh đĩa thường được ưu tiên bố trí ở cầu trước (nơi chịu phần lớn tải trọng động khi phanh) nhằm tối ưu hóa khả năng dừng xe an toàn. d) Cơ cấu phanh đĩa dẫn động khí nén a) Khi chưa phanh; b) Khi phanh. 1, 3. Má phanh; 2. Đĩa phanh; 4. Lò xo; 5, 9. Thanh đẩy; 6. Khớp cầu; 7. Đòn quay; 8. Giá đỡ; 10. Bầu phanh; 11. Màng cao su. Tương tự như ở cơ cấu phanh tang trống, do áp suất khí nén của dẫn động phanh khí nén nhỏ (0,4 ÷ 0,6 MPa) nên kích thước bộ phận sinh lực lớn và rất khó bố trí bầu phanh hoặc xi-lanh phanh tác dụng trực tiếp vào tấm ma sát mà phải thông qua một cơ cấu dẫn động. Khi phanh, khí nén đi vào bầu phanh ở phía bên phải của màng phanh (11).","pages":[68]},{"id":"s1608","kind":"pdf","lesson":"10.2.2","title":"Hệ thống phanh · Cơ cấu phanh đĩa","text":"Lực khí nén đẩy màng phanh sang trái, thông qua thanh đẩy (9) làm quay đòn quay (7). Đòn quay (7) đẩy vào thanh đẩy (5) và thanh đẩy (5) đẩy má phanh (3) sang phải. Khi má phanh (3) chạm vào đĩa phanh (4), phản lực từ đĩa phanh tác dụng lên thanh đẩy (5); thông qua đòn quay (7), thanh đẩy (5) đẩy giá (8) sang trái, đồng thời kéo theo má phanh (1) sang trái. Hai má phanh (1) và (3) ép chặt vào đĩa phanh (2), tạo ra lực ma sát và sinh ra mô men phanh.","pages":[68]},{"id":"s1609","kind":"figure","lesson":"10.3.1","title":"Hình 10.28. Dẫn động phanh cơ khí 1. Bàn đạp phanh; 2. Trục quay; 3, 5. Đòn quay; 4. Đòn dẫn động; 6. Trục cam; 7. Cam","text":"Hình 10.28. Dẫn động phanh cơ khí 1. Bàn đạp phanh; 2. Trục quay; 3, 5. Đòn quay; 4. Đòn dẫn động; 6. Trục cam; 7. Cam","pages":[69],"figure":{"number":"10.28","caption":"Hình 10.28. Dẫn động phanh cơ khí 1. Bàn đạp phanh; 2. Trục quay; 3, 5. Đòn quay; 4. Đòn dẫn động; 6. Trục cam; 7. Cam"}},{"id":"s1610","kind":"figure","lesson":"10.3.1","title":"Hình 10.28 thể hiện một hệ thống phanh dẫn động cơ khí. Bàn đạp (1) lắp chặt với trục quay (2), trục quay (2) lắp chặt với các đòn quay (3). Các đòn quay (3) nối với các đòn quay (5) bằng các thanh kéo (4). Cam phanh (7) và đòn quay (5) lắp chặt với trục (6). Khi người lái đạp bàn đạp phanh (1), trục (2) và các đòn quay (3) quay theo. Các đòn quay (3) thông qua thanh kéo (4) làm quay đòn quay (5), trục (6) và cam phanh (7). Các cam phanh (7) đẩy các guốc phanh (8) áp sát vào trống phanh.","text":"Hình 10.28 thể hiện một hệ thống phanh dẫn động cơ khí. Bàn đạp (1) lắp chặt với trục quay (2), trục quay (2) lắp chặt với các đòn quay (3). Các đòn quay (3) nối với các đòn quay (5) bằng các thanh kéo (4). Cam phanh (7) và đòn quay (5) lắp chặt với trục (6). Khi người lái đạp bàn đạp phanh (1), trục (2) và các đòn quay (3) quay theo. Các đòn quay (3) thông qua thanh kéo (4) làm quay đòn quay (5), trục (6) và cam phanh (7). Các cam phanh (7) đẩy các guốc phanh (8) áp sát vào trống phanh.","pages":[69],"figure":{"number":"10.28","caption":"Hình 10.28 thể hiện một hệ thống phanh dẫn động cơ khí. Bàn đạp (1) lắp chặt với trục quay (2), trục quay (2) lắp chặt với các đòn quay (3). Các đòn quay (3) nối với các đòn quay (5) bằng các thanh kéo (4). Cam phanh (7) và đòn quay (5) lắp chặt với trục (6). Khi người lái đạp bàn đạp phanh (1), trục (2) và các đòn quay (3) quay theo. Các đòn quay (3) thông qua thanh kéo (4) làm quay đòn quay (5), trục (6) và cam phanh (7). Các cam phanh (7) đẩy các guốc phanh (8) áp sát vào trống phanh."}},{"id":"s1611","kind":"pdf","lesson":"10.3.1","title":"Hệ thống phanh · Dẫn động bằng cơ khí","text":"III. DẪN ĐỘNG HỆ THỐNG PHANH Dẫn động phanh có nhiệm vụ truyền lực điều khiển từ người lái hoặc từ một nguồn năng lượng nào đó đến cơ cấu phanh để cơ cấu phanh sinh ra mô men phanh. Như đã trình bày ở mục II, để sinh ra mô men phanh cần có lực tác động vào guốc phanh hoặc má phanh; lực này có nguồn gốc từ người lái hoặc từ một nguồn năng lượng nào đó. Khi phanh, người lái đạp bàn đạp phanh (hoặc kéo cần điều khiển); khi đó, dẫn động phanh truyền lực của người lái đến cơ cấu phanh hoặc dẫn dòng khí nén, chất lỏng đến cơ cấu phanh. Có các loại dẫn động phanh sau đây: - Dẫn động cơ khí; - Dẫn động thủy lực; - Dẫn động khí nén; - Dẫn động hỗn hợp (thủy lực - khí nén); - Dẫn động có trợ lực (chân không, khí nén). 1. Dẫn động bằng cơ khí Dẫn động cơ khí gồm các thanh, đòn, dây cáp; lực do người lái sinh ra được truyền qua các thanh, đòn, dây cáp đến cơ cấu phanh.","pages":[69]},{"id":"s1612","kind":"pdf","lesson":"10.3.1","title":"Hệ thống phanh · Dẫn động bằng cơ khí","text":"Loại dẫn động phanh này có kết cấu đơn giản nhưng có nhược điểm lớn là khó điều khiển nhiều cơ cấu phanh cùng một lúc, đồng thời các cơ cấu phanh có mô men phanh không bằng nhau. Vì thế, trên ô tô, loại dẫn động này không dùng cho","pages":[69]},{"id":"s1613","kind":"figure","lesson":"10.3.1","title":"Hình 10.29. Dẫn động phanh dừng (phanh tay) bằng cơ khí 1,6. Cần phanh tay; 2. Guốc phanh; 3. Cáp phanh; 4. Đai ốc hãm; 5. Đai ốc điều chỉnh; 7.","text":"Hình 10.29. Dẫn động phanh dừng (phanh tay) bằng cơ khí 1,6. Cần phanh tay; 2. Guốc phanh; 3. Cáp phanh; 4. Đai ốc hãm; 5. Đai ốc điều chỉnh; 7.","pages":[70],"figure":{"number":"10.29","caption":"Hình 10.29. Dẫn động phanh dừng (phanh tay) bằng cơ khí 1,6. Cần phanh tay; 2. Guốc phanh; 3. Cáp phanh; 4. Đai ốc hãm; 5. Đai ốc điều chỉnh; 7."}},{"id":"s1614","kind":"figure","lesson":"10.3.1","title":"Hình 10.30. Các loại cần kéo phanh tay Các dạng cơ cấu phanh tay (Hình 10.31): Loại phanh tang trống (1) trên Hình 10.31: cơ cấu này tận dụng trực tiếp kết cấu của cụm phanh tang trống (phanh chân) ở cầu sau để làm phanh dừng. Khi người lái kéo phanh tay, lực truyền qua hệ thống dây cáp tác động lên một cơ cấu đòn bẩy cơ khí bên trong cụm phanh, đẩy hai guốc phanh ép chặt vào mặt trong của trống phanh.","text":"Hình 10.30. Các loại cần kéo phanh tay Các dạng cơ cấu phanh tay (Hình 10.31): Loại phanh tang trống (1) trên Hình 10.31: cơ cấu này tận dụng trực tiếp kết cấu của cụm phanh tang trống (phanh chân) ở cầu sau để làm phanh dừng. Khi người lái kéo phanh tay, lực truyền qua hệ thống dây cáp tác động lên một cơ cấu đòn bẩy cơ khí bên trong cụm phanh, đẩy hai guốc phanh ép chặt vào mặt trong của trống phanh.","pages":[70],"figure":{"number":"10.30","caption":"Hình 10.30. Các loại cần kéo phanh tay Các dạng cơ cấu phanh tay (Hình 10.31): Loại phanh tang trống (1) trên Hình 10.31: cơ cấu này tận dụng trực tiếp kết cấu của cụm phanh tang trống (phanh chân) ở cầu sau để làm phanh dừng. Khi người lái kéo phanh tay, lực truyền qua hệ thống dây cáp tác động lên một cơ cấu đòn bẩy cơ khí bên trong cụm phanh, đẩy hai guốc phanh ép chặt vào mặt trong của trống phanh."}},{"id":"s1615","kind":"pdf","lesson":"10.3.1","title":"Hệ thống phanh · Dẫn động bằng cơ khí","text":"phanh chính mà chủ yếu dùng cho phanh dừng (phanh tay) – loại phanh có ít cơ cấu phanh (chỉ 1 hoặc 2 cơ cấu phanh) và không đòi hỏi khắt khe về sự đồng đều mô men phanh giữa các cơ cấu phanh cũng như thời gian tác dụng. Trên một số máy kéo, có bố trí dẫn động cơ khí cho phanh chính do vận tốc thấp và chỉ có hai bánh sau là có cơ cấu phanh. Sơ đồ dẫn động phanh dừng (phanh tay) bằng cơ khí thể hiện trên Hình 10.29. Cần điều chỉnh; 8. Cam phanh; 9. Trống phanh; 10. Chốt tựa; 11. Má phanh; 12. Càng kéo; 13. Bánh răng rẻ quạt. Phanh tay được sử dụng khi đỗ xe: cơ cấu phanh khóa cơ khí các bánh sau, bảo đảm cho ô tô đứng yên khi đỗ trên mặt đường dốc hoặc ở những nơi có độ ma sát giữa lốp xe và mặt đường kém. Các loại cần phanh tay (Hình 10.30):","pages":[70]},{"id":"s1616","kind":"figure","lesson":"10.3.1","title":"Hình 10.31. Các kiểu cơ cấu phanh dừng (phanh tay) 1. Phanh tang trống; 2. Phanh đĩa; 3. Phanh dừng tách rời; 4. Phanh dừng trung tâm","text":"Hình 10.31. Các kiểu cơ cấu phanh dừng (phanh tay) 1. Phanh tang trống; 2. Phanh đĩa; 3. Phanh dừng tách rời; 4. Phanh dừng trung tâm","pages":[71],"figure":{"number":"10.31","caption":"Hình 10.31. Các kiểu cơ cấu phanh dừng (phanh tay) 1. Phanh tang trống; 2. Phanh đĩa; 3. Phanh dừng tách rời; 4. Phanh dừng trung tâm"}},{"id":"s1617","kind":"figure","lesson":"10.3.1","title":"Hình 10.32. Cơ cấu phanh tay xe tải Loại phanh trung tâm (4) trên Hình 10.31: khác với 3 loại trên (tác động trực tiếp tại bánh xe), phanh trung tâm được bố trí hoàn toàn tách biệt, thường lắp ngay phía sau đuôi hộp số (hộp số dọc) và tác động trực tiếp lên trục các-đăng. Khi hoạt động, một cụm phanh tang trống nhỏ (hoặc phanh đĩa) sẽ khóa cứng trục truyền động.","text":"Hình 10.32. Cơ cấu phanh tay xe tải Loại phanh trung tâm (4) trên Hình 10.31: khác với 3 loại trên (tác động trực tiếp tại bánh xe), phanh trung tâm được bố trí hoàn toàn tách biệt, thường lắp ngay phía sau đuôi hộp số (hộp số dọc) và tác động trực tiếp lên trục các-đăng. Khi hoạt động, một cụm phanh tang trống nhỏ (hoặc phanh đĩa) sẽ khóa cứng trục truyền động.","pages":[71],"figure":{"number":"10.32","caption":"Hình 10.32. Cơ cấu phanh tay xe tải Loại phanh trung tâm (4) trên Hình 10.31: khác với 3 loại trên (tác động trực tiếp tại bánh xe), phanh trung tâm được bố trí hoàn toàn tách biệt, thường lắp ngay phía sau đuôi hộp số (hộp số dọc) và tác động trực tiếp lên trục các-đăng. Khi hoạt động, một cụm phanh tang trống nhỏ (hoặc phanh đĩa) sẽ khóa cứng trục truyền động."}},{"id":"s1618","kind":"pdf","lesson":"10.3.1","title":"Hệ thống phanh · Dẫn động bằng cơ khí","text":"Loại phanh đĩa (2) trên Hình 10.31: đối với các xe trang bị phanh đĩa ở cả bốn bánh, cơ cấu phanh dừng được thiết kế tích hợp ngay trong ngàm phanh cầu sau. Hệ thống cáp kéo sẽ tác động lên một trục cam xoay hoặc cơ cấu vít me - đai ốc nằm ở đuôi xi-lanh phanh. Chuyển động quay này được chuyển đổi thành chuyển động tịnh tiến, đẩy trực tiếp pít-tông và má phanh ép chặt vào đĩa phanh mà không cần sử dụng áp suất thủy lực. Loại phanh dừng tách rời (3) trên Hình 10.31: đây là hệ thống phanh dừng độc lập, kết hợp giữa phanh đĩa và phanh tang trống. Phanh chân vẫn sử dụng ngàm và đĩa phanh bình thường, nhưng phần lõi trung tâm (moay-ơ) của đĩa phanh được thiết kế nhô ra và rỗng bên trong, đóng vai trò như một trống phanh thu nhỏ. Một hệ thống guốc phanh phụ (chỉ dành riêng cho việc đỗ xe) được bố trí gọn gàng bên trong không gian này và điều khiển bằng cáp kéo.","pages":[71]},{"id":"s1619","kind":"figure","lesson":"10.3.1","title":"Hình 10.33. Cơ cấu phanh tay trên xe MG6 1. Tấm đỡ phía sau; 2. Lò xo hồi má phanh; 3. Cần điều chỉnh má phanh; 4. Chốt giữ má phanh; 5. Má phanh trước; 6. Đĩa phanh tích hợp với tang trống; 7. Cần đẩy má phanh; 8. Kẹp","text":"Hình 10.33. Cơ cấu phanh tay trên xe MG6 1. Tấm đỡ phía sau; 2. Lò xo hồi má phanh; 3. Cần điều chỉnh má phanh; 4. Chốt giữ má phanh; 5. Má phanh trước; 6. Đĩa phanh tích hợp với tang trống; 7. Cần đẩy má phanh; 8. Kẹp","pages":[72],"figure":{"number":"10.33","caption":"Hình 10.33. Cơ cấu phanh tay trên xe MG6 1. Tấm đỡ phía sau; 2. Lò xo hồi má phanh; 3. Cần điều chỉnh má phanh; 4. Chốt giữ má phanh; 5. Má phanh trước; 6. Đĩa phanh tích hợp với tang trống; 7. Cần đẩy má phanh; 8. Kẹp"}},{"id":"s1620","kind":"figure","lesson":"10.3.2","title":"Hình 10.34. Sơ đồ dẫn động điều khiển phanh bằng thủy lực 1. Bàn đạp; 2. Thanh đẩy; 3, 4. Pít-tông - xi-lanh chính; 5. Đường ống; 6, 7. Pít-tông - xi-","text":"Hình 10.34. Sơ đồ dẫn động điều khiển phanh bằng thủy lực 1. Bàn đạp; 2. Thanh đẩy; 3, 4. Pít-tông - xi-lanh chính; 5. Đường ống; 6, 7. Pít-tông - xi-","pages":[72],"figure":{"number":"10.34","caption":"Hình 10.34. Sơ đồ dẫn động điều khiển phanh bằng thủy lực 1. Bàn đạp; 2. Thanh đẩy; 3, 4. Pít-tông - xi-lanh chính; 5. Đường ống; 6, 7. Pít-tông - xi-"}},{"id":"s1621","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"giữ; 9. Lò xo hồi má phanh; 10. Má phanh sau; 11. Chốt giữ má phanh; 12. Tấm dẫn hướng Loại phanh trung tâm kết hợp phanh dừng kiểu trống ở giữa hộp số dọc và trục các-đăng, được sử dụng chủ yếu trên xe buýt và xe tải. Hình 10.32 và Hình 10.33 mô tả cơ cấu phanh tay trên một số xe. 2. Dẫn động bằng thủy lực a) Dẫn động thủy lực không có trợ lực Ở hệ thống dẫn động thủy lực, lực của người lái được truyền đến cơ cấu phanh bằng dòng chất lỏng (Hình 10.34). Người lái tác động vào pít-tông xi-lanh chính để tạo ra chất lỏng có áp suất cao. Chất lỏng áp suất cao được truyền đến xi-lanh công tác; pít-tông công tác biến áp suất chất lỏng thành lực tác động vào guốc phanh.","pages":[72]},{"id":"s1622","kind":"figure","lesson":"10.3.2","title":"Hình 10.35. Dẫn động điều khiển hệ thống phanh thủy lực một dòng trên ô tô 1. Bàn đạp phanh; 2. Xi-lanh chính; 3. Đường ống dẫn cứng; 4, 5, 6, 7. Cơ cấu phanh; 8.","text":"Hình 10.35. Dẫn động điều khiển hệ thống phanh thủy lực một dòng trên ô tô 1. Bàn đạp phanh; 2. Xi-lanh chính; 3. Đường ống dẫn cứng; 4, 5, 6, 7. Cơ cấu phanh; 8.","pages":[73],"figure":{"number":"10.35","caption":"Hình 10.35. Dẫn động điều khiển hệ thống phanh thủy lực một dòng trên ô tô 1. Bàn đạp phanh; 2. Xi-lanh chính; 3. Đường ống dẫn cứng; 4, 5, 6, 7. Cơ cấu phanh; 8."}},{"id":"s1623","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Trên sơ đồ dẫn động (Hình 10.35), khi người lái đạp bàn đạp (1), chất lỏng trong xi-lanh chính (2) được gia tăng áp suất và theo các đường ống dẫn (3) đi đến xi-lanh công tác (9) của các cơ cấu phanh (4, 5, 6, 7) bố trí ở các bánh xe. Đường ống dẫn chất lỏng được chế tạo bằng kim loại (đồng). Riêng đoạn ống dẫn (8) đến các xi-lanh công tác ở các bánh xe được làm bằng cao su vì bánh xe có chuyển động tương đối với thân xe. Đường ống dẫn mềm; 9. Xi-lanh công tác. Ưu điểm: - Có thể truyền đến nhiều cơ cấu phanh với mô men phanh và thời gian tác dụng đồng đều nhau. - Độ nhạy cao do áp suất chất lỏng tăng đồng thời tại mọi vị trí trong hệ thống. Nhược điểm: - Lực điều khiển do người lái sinh ra nên độ lớn bị hạn chế.","pages":[73]},{"id":"s1624","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Hệ thống phanh sẽ bị mất tác dụng nếu có một chỗ nào đó của hệ thống bị rò rỉ. - Khi có sự cố (lọt khí, rò dầu…), áp suất không đều sẽ gây mất cân bằng lực phanh giữa các bánh và lệch hướng chuyển động khi phanh, khó giữ ổn định cho thân xe. - Hệ thống 1 dòng dễ bị lọt khí, rò rỉ tại các phớt, ống mềm làm giảm hiệu quả phanh theo thời gian. Tùy theo sơ đồ mạch dẫn động, dẫn động phanh thủy lực được chia thành dẫn động một dòng và dẫn động hai dòng. Ở dẫn động một dòng, từ đầu ra của xi-lanh chính chỉ có một đường dầu duy nhất dẫn đến các xi-lanh bánh xe. Loại này có kết cấu đơn giản nhưng độ an toàn không cao nên ít được sử dụng trong thực tế. Ở dẫn động hai dòng (Hình 10.36), từ đầu ra của xi-lanh chính có hai đường dầu độc lập đến các xi-lanh bánh xe.","pages":[73]},{"id":"s1625","kind":"figure","lesson":"10.3.2","title":"Hình 10.36. Sơ đồ nguyên lý hệ thống phanh thủy lực dẫn động hai dòng 1. Bàn đạp phanh; 2. Bình dầu phanh; 3. Xi-lanh phanh chính; 4. Ống dẫn dầu; 5. Cơ cấu","text":"Hình 10.36. Sơ đồ nguyên lý hệ thống phanh thủy lực dẫn động hai dòng 1. Bàn đạp phanh; 2. Bình dầu phanh; 3. Xi-lanh phanh chính; 4. Ống dẫn dầu; 5. Cơ cấu","pages":[74],"figure":{"number":"10.36","caption":"Hình 10.36. Sơ đồ nguyên lý hệ thống phanh thủy lực dẫn động hai dòng 1. Bàn đạp phanh; 2. Bình dầu phanh; 3. Xi-lanh phanh chính; 4. Ống dẫn dầu; 5. Cơ cấu"}},{"id":"s1626","kind":"figure","lesson":"10.3.2","title":"Hình 10.37. Sơ đồ bố trí các dòng thủy lực b) Dẫn động thủy lực có trợ lực Để giảm nhẹ lực tác động của người lái trong quá trình sử dụng phanh, đồng thời tăng hiệu quả sử dụng phanh trong trường hợp phanh gấp, hệ thống phanh thường được trang bị thêm bộ trợ lực phanh.","text":"Hình 10.37. Sơ đồ bố trí các dòng thủy lực b) Dẫn động thủy lực có trợ lực Để giảm nhẹ lực tác động của người lái trong quá trình sử dụng phanh, đồng thời tăng hiệu quả sử dụng phanh trong trường hợp phanh gấp, hệ thống phanh thường được trang bị thêm bộ trợ lực phanh.","pages":[74],"figure":{"number":"10.37","caption":"Hình 10.37. Sơ đồ bố trí các dòng thủy lực b) Dẫn động thủy lực có trợ lực Để giảm nhẹ lực tác động của người lái trong quá trình sử dụng phanh, đồng thời tăng hiệu quả sử dụng phanh trong trường hợp phanh gấp, hệ thống phanh thường được trang bị thêm bộ trợ lực phanh."}},{"id":"s1627","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"phanh bánh sau; 6. Cơ cấu phanh bánh trước. Do hai dòng hoạt động độc lập nên xi-lanh chính phải có hai ngăn độc lập. Khi một dòng bị rò rỉ, dòng còn lại vẫn có tác dụng; vì vậy, phanh hai dòng có độ an toàn cao và được sử dụng nhiều trong thực tế. Các sơ đồ dẫn động thủy lực hai dòng thường gặp (Hình 10.37) gồm: - Một dòng dẫn động cho hai bánh xe cầu trước, dòng còn lại dẫn động cho các bánh xe cầu sau (Hình 10.37a); - Một dòng dẫn động cho bánh xe trước ở một phía và bánh xe sau ở phía khác, dòng còn lại dẫn động cho các bánh xe chéo còn lại (Hình 10.37b); - Hai mạch thủy lực hoạt động độc lập, mỗi mạch dẫn động một bánh trước và một bánh sau ở hai phía tương ứng của xe (Hình 10.37c).","pages":[74]},{"id":"s1628","kind":"figure","lesson":"10.3.2","title":"Hình 10.38. Xi-lanh chính kép 1, 5. Lò xo hồi vị; 2. Nắp; 3, 6. Pít-tông; 4. Xi-lanh; 7, 8. Vít hạn chế; 9. Phớt làm kín","text":"Hình 10.38. Xi-lanh chính kép 1, 5. Lò xo hồi vị; 2. Nắp; 3, 6. Pít-tông; 4. Xi-lanh; 7, 8. Vít hạn chế; 9. Phớt làm kín","pages":[75],"figure":{"number":"10.38","caption":"Hình 10.38. Xi-lanh chính kép 1, 5. Lò xo hồi vị; 2. Nắp; 3, 6. Pít-tông; 4. Xi-lanh; 7, 8. Vít hạn chế; 9. Phớt làm kín"}},{"id":"s1629","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Trợ lực phanh có hai dạng cơ bản là trợ lực bằng chân không và trợ lực bằng thủy lực (trợ lực dầu). Bộ trợ lực thủy lực: Dùng một bơm có mô-tơ để tạo ra một áp suất thủy lực đủ lớn, nhằm giảm lực đạp phanh cần thiết (loại này ít phổ biến). Bộ trợ lực chân không: hoạt động dựa vào độ chênh lệch giữa độ chân không của động cơ và áp suất khí quyển để tạo ra một lực mạnh tỉ lệ thuận với lực ấn của bàn đạp phanh. Nguồn chân không có thể lấy ở đường nạp động cơ hoặc dùng bơm chân không riêng làm việc nhờ động cơ (loại này dùng phổ biến trên hầu hết các loại xe du lịch, xe tải nhỏ).","pages":[75]},{"id":"s1630","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Các cụm chi tiết chính của hệ thống phanh dẫn động thủy lực gồm: xi-lanh chính, đường ống dẫn và bàn đạp phanh; bộ trợ lực chân không; van điều hòa lực phanh. c) Xi-lanh chính, đường ống dẫn và bàn đạp phanh Cụm xi-lanh chính có nhiệm vụ tạo ra áp suất chất lỏng (dầu phanh) trong hệ thống phanh khi có lực tác động của người lái. Áp suất chất lỏng trong hệ thống phanh khi phanh cực đại có thể đạt 5 ÷ 8 MPa hoặc hơn nữa. Cụm này bao gồm bầu chứa dầu phanh, xi-lanh, pít-tông, các van và còn được gọi là “tổng phanh”. Hiện nay, xi-lanh chính dùng cho hệ thống phanh có từ 2 dòng thường là loại 2 pít-tông, gọi là xi-lanh chính kép. Hình 10.38 là bản vẽ mặt cắt cụm xi-lanh chính kép của dẫn động chất lỏng hai dòng dùng trên xe lắp cơ cấu phanh đĩa. Xi-lanh (4) được lắp hai pít-tông (3 và 6). Xi-lanh có hai đường cung cấp dầu phanh qua cửa III và cửa V.","pages":[75]},{"id":"s1631","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Hai bầu chứa dầu phanh được lắp trực tiếp vào hai cửa III và V hoặc qua đường ống dẫn. Đồng thời, xi-lanh cũng có hai cửa ra để chất lỏng đi đến các xi-lanh công tác là cửa II và IV. Thường mỗi cửa ra cung cấp dầu phanh cho hai bánh xe cùng một cầu. Pít-tông (6) được gọi là pít-tông sơ cấp, pít-tông (3) là pít-tông thứ cấp.","pages":[75]},{"id":"s1632","kind":"figure","lesson":"10.3.2","title":"Hình 10.39. Ống nối cứng, ống nối mềm và bàn đạp phanh Vì cơ cấu phanh đĩa không được phép có áp suất dư trong xi-lanh công tác (vì nếu có, pít-tông của xi-lanh công tác sẽ không trở về vị trí không phanh được) nên từ xi-lanh chính đến xi-lanh công tác không bố trí các van (van đi và van hồi) như trường hợp lắp cơ cấu phanh tang trống.","text":"Hình 10.39. Ống nối cứng, ống nối mềm và bàn đạp phanh Vì cơ cấu phanh đĩa không được phép có áp suất dư trong xi-lanh công tác (vì nếu có, pít-tông của xi-lanh công tác sẽ không trở về vị trí không phanh được) nên từ xi-lanh chính đến xi-lanh công tác không bố trí các van (van đi và van hồi) như trường hợp lắp cơ cấu phanh tang trống.","pages":[76],"figure":{"number":"10.39","caption":"Hình 10.39. Ống nối cứng, ống nối mềm và bàn đạp phanh Vì cơ cấu phanh đĩa không được phép có áp suất dư trong xi-lanh công tác (vì nếu có, pít-tông của xi-lanh công tác sẽ không trở về vị trí không phanh được) nên từ xi-lanh chính đến xi-lanh công tác không bố trí các van (van đi và van hồi) như trường hợp lắp cơ cấu phanh tang trống."}},{"id":"s1633","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Khi lắp vào xi-lanh, hai pít-tông nối với nhau bằng lò xo (5), đồng thời chia xi-lanh thành hai khoang lớn là (A + B) và (D + C). Trên mỗi pít-tông có các phớt (9) chia các khoang lớn thành các khoang nhỏ. Pít-tông sơ cấp (6) nhận lực đẩy từ người lái thông qua bàn đạp phanh và hệ thống dẫn động. Khu vực có phớt (9) thể hiện ở mặt cắt trích I. Khi không phanh, khoang A thông với khoang B và khoang C thông với khoang D. Khi phanh, pít-tông (6) di chuyển sang trái, thông qua lò xo (lò xo giữa pít- tông sơ cấp và thứ cấp) làm pít-tông (3) cũng di chuyển sang trái, lúc này phớt (9) chưa di chuyển. Khi pít-tông chạm vào phớt (9), khoang B bị ngăn cách với khoang A và khoang D bị ngăn cách với khoang C. Các pít-tông tiếp tục di chuyển, áp suất trong các khoang A và C tăng lên và chất lỏng sẽ qua các cửa II và IV đến các cơ cấu phanh.","pages":[76]},{"id":"s1634","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Các đường ống dẫn chất lỏng (Hình 10.39) thường được chế tạo bằng đồng chịu được áp lực cao (10 MPa hoặc hơn nữa) và được bố trí sao cho khi vận hành không cản trở hoạt động của các bộ phận khác và phải đảm bảo an toàn, tức là ít có khả năng bị gãy, vỡ, bẹp. Đoạn đường ống dẫn từ khung xe đến bánh xe (hoặc cầu xe) là bộ phận có sự dịch chuyển tương đối với khung xe, do đó phải dùng ống cao su chịu áp lực cao. Bàn đạp phanh được bố trí trong ca-bin xe, nơi người lái ngồi. Hành trình bàn đạp thường không quá 150 mm. Thông thường, bàn đạp tác dụng trực tiếp vào thanh đẩy và thanh đẩy tác dụng trực tiếp vào pít-tông của cụm xi-lanh chính, nên cụm xi- lanh chính cũng được bố trí gần ca-bin xe. d) Bộ trợ lực chân không Bầu trợ lực chân không (Hình 10.40) thường gồm các bộ phận chính sau: - Vỏ bầu trợ lực gồm hai khoang, ngăn cách bởi màng đàn hồi (cao su);","pages":[76]},{"id":"s1635","kind":"figure","lesson":"10.3.2","title":"Hình 10.40. Sơ đồ cấu tạo bộ trợ lực chân không 1. Thanh đẩy xi-lanh; 2. Van chân không; 3. Màng ngăn; 4. Pít-tông trợ lực; 5. Van điều","text":"Hình 10.40. Sơ đồ cấu tạo bộ trợ lực chân không 1. Thanh đẩy xi-lanh; 2. Van chân không; 3. Màng ngăn; 4. Pít-tông trợ lực; 5. Van điều","pages":[77],"figure":{"number":"10.40","caption":"Hình 10.40. Sơ đồ cấu tạo bộ trợ lực chân không 1. Thanh đẩy xi-lanh; 2. Van chân không; 3. Màng ngăn; 4. Pít-tông trợ lực; 5. Van điều"}},{"id":"s1636","kind":"figure","lesson":"10.3.2","title":"Hình 10.41. Hoạt động của bộ trợ lực chân không ở trạng thái không phanh","text":"Hình 10.41. Hoạt động của bộ trợ lực chân không ở trạng thái không phanh","pages":[77],"figure":{"number":"10.41","caption":"Hình 10.41. Hoạt động của bộ trợ lực chân không ở trạng thái không phanh"}},{"id":"s1637","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"- Màng cao su ngăn cách khoang chân không và khoang khí quyển, truyền lực sang thanh đẩy; - Van một chiều nối bầu trợ lực với ống nguồn cung cấp chân không (bơm chân không), bảo đảm dòng khí chỉ đi ra từ bầu trợ lực; - Cần đẩy nối bàn đạp phanh với pít-tông xi-lanh chính; - Lò xo hồi vị đưa màng về vị trí ban đầu khi nhả phanh. khiển; 6. Lọc khí nạp; 7. Thanh đẩy bàn đạp; 8. Chân không. Nguyên lý làm việc: Hầu hết các bộ trợ lực chân không có ba trạng thái hoạt động là: nhả phanh, đạp phanh và duy trì phanh. Những trạng thái này được xác định bởi độ lớn của áp suất tác dụng lên thanh đẩy. Khi không phanh (chưa đạp bàn đạp phanh) (Hình 10.41): Khi không đạp phanh, cửa chân không mở và cửa không khí đóng. Áp suất giữa hai buồng A và B cân bằng nhau, lò xo hồi vị đẩy pít-tông về bên phải, không có lực tác dụng lên thanh đẩy. 1. Cửa chân không (mở); 2.","pages":[77]},{"id":"s1638","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Cửa khí quyển (đóng); 3. Buồng B; 4. Buồng A.","pages":[77]},{"id":"s1639","kind":"figure","lesson":"10.3.2","title":"Hình 10.42. Hoạt động của bộ trợ lực chân không ở trạng thái đạp phanh","text":"Hình 10.42. Hoạt động của bộ trợ lực chân không ở trạng thái đạp phanh","pages":[78],"figure":{"number":"10.42","caption":"Hình 10.42. Hoạt động của bộ trợ lực chân không ở trạng thái đạp phanh"}},{"id":"s1640","kind":"figure","lesson":"10.3.2","title":"Hình 10.43. Hoạt động của bộ trợ lực chân không ở trạng thái giữ phanh","text":"Hình 10.43. Hoạt động của bộ trợ lực chân không ở trạng thái giữ phanh","pages":[78],"figure":{"number":"10.43","caption":"Hình 10.43. Hoạt động của bộ trợ lực chân không ở trạng thái giữ phanh"}},{"id":"s1641","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Khi đạp phanh (Hình 10.42): 1. Cửa chân không (đóng); 2. Cửa khí quyển (mở); 3. Buồng B; 4. Buồng A. Khi phanh, cần đẩy dịch chuyển sang trái làm cửa chân không đóng, cửa khí quyển mở. Buồng A thông với buồng khí nạp động cơ, buồng B có áp suất bằng áp suất khí quyển. Sự chênh lệch áp suất này tạo ra lực cường hóa đẩy pít-tông và màng cao su dịch chuyển về bên trái, tạo ra khả năng tăng lực đẩy cho pít-tông xi-lanh chính. Khi giữ phanh (Hình 10.43): Ở trạng thái giữ phanh, cả hai cửa đều đóng, do đó áp suất ở phía phải của màng không đổi, áp suất trong hệ thống được duy trì. 1. Cửa chân không (đóng); 2. Cửa khí quyển (đóng). Khi nhả phanh, lò xo hồi vị đẩy pít-tông và màng ngăn về vị trí ban đầu. Trường hợp bộ trợ lực bị hỏng, cần đẩy sẽ làm việc như một trục liền.","pages":[78]},{"id":"s1642","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Do đó, khi phanh, người lái cần phải tác động một lực lớn hơn để thắng lực đẩy của lò xo và lực ma sát của cơ cấu. Ứng dụng: Hầu hết xe con, xe du lịch tại Việt Nam hiện nay đều dùng bộ trợ lực chân không để tăng hiệu quả phanh. Một số xe phổ biến: Toyota Vios, Honda City, Hyundai Accent, Mazda 3, Kia Cerato, VinFast Lux A2.0, Ford Ranger… Ưu điểm: Tăng lực phanh mà không cần tăng lực bàn đạp (lực đạp phanh của người lái). Kết cấu đơn giản, độ tin cậy cao.","pages":[78]},{"id":"s1643","kind":"figure","lesson":"10.3.2","title":"Hình 10.44. Van điều hòa theo áp suất phanh 1. Xi-lanh chính; 2. Pít-tông; 3. Phớt làm kín; 4. Thân van; 5. Nắp chặn","text":"Hình 10.44. Van điều hòa theo áp suất phanh 1. Xi-lanh chính; 2. Pít-tông; 3. Phớt làm kín; 4. Thân van; 5. Nắp chặn","pages":[79],"figure":{"number":"10.44","caption":"Hình 10.44. Van điều hòa theo áp suất phanh 1. Xi-lanh chính; 2. Pít-tông; 3. Phớt làm kín; 4. Thân van; 5. Nắp chặn"}},{"id":"s1644","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Nhược điểm: Phụ thuộc vào áp suất chân không của động cơ. Giảm hiệu quả nếu động cơ chết máy (nên có thêm bầu tích trữ chân không). e) Van điều hòa lực phanh theo áp suất Van điều hòa áp suất phanh có nhiệm vụ phân phối hợp lý áp suất dầu phanh giữa bánh trước và bánh sau, đảm bảo hiệu quả phanh tối ưu, hạn chế hiện tượng bánh sau bị bó cứng khi phanh gấp, đặc biệt khi xe giảm tải hoặc phanh trên đường trơn. Loại van điều hòa này sử dụng thông số áp suất sau xi-lanh chính (hoặc sau van phân phối) để điều chỉnh áp suất đi đến cơ cấu phanh sau, cho nên còn được gọi là van điều hòa một thông số. Khi phanh mạnh, tải trọng dồn về cầu trước làm giảm lực bám của bánh sau. Nếu không điều chỉnh, bánh sau dễ bị khóa. Van điều hòa sẽ giảm áp suất dầu tới bánh sau khi áp suất này vượt qua ngưỡng nhất định, giúp các bánh phanh đều, duy trì sự ổn định của xe.","pages":[79]},{"id":"s1645","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Cấu tạo của van điều hòa lực phanh một thông số kiểu pít-tông được thể hiện trên Hình 10.44. Van điều hòa được lắp trên đường chất lỏng (dầu phanh) đi đến các cơ cấu phanh sau, như vậy dầu phanh đi qua van điều hòa rồi đến cơ cấu phanh sau. Vỏ của van điều hòa được cố định lên thân xe. Pít-tông có diện tích chịu áp lực chất lỏng phía phải lớn hơn phía trái do phía trái bị phần có đường kính d chiếm chỗ. Đồng thời, phía trái của pít-tông luôn chịu lực tĩnh (lực Ft) của lò xo. Cụm van điều hòa áp suất thường gồm: Thân van đúc bằng hợp kim nhôm hoặc gang, chứa các buồng dầu và lò xo đàn hồi; pít-tông chịu tác dụng của áp suất dầu từ xi-lanh chính và điều chỉnh dòng dầu đi tới cầu sau; van bi và lò xo duy trì trạng thái mở của dòng dầu cho tới khi áp suất vượt ngưỡng thiết kế; đường dầu vào - ra nối từ xi-lanh chính đến các mạch phanh cầu sau.","pages":[79]},{"id":"s1646","kind":"figure","lesson":"10.3.2","title":"Hình 10.45. Van điều hòa theo áp suất phanh và tải trọng xe Khi tải trọng thay đổi, biến dạng của hệ thống treo thay đổi và do đó, khoảng cách giữa cầu xe và thân xe thay đổi theo. Tải trọng tăng, khoảng cách giữa cầu xe và thân xe giảm đi và ngược lại, tải trọng giảm, khoảng cách giữa cầu xe và thân xe tăng lên. Sự tăng giảm khoảng cách giữa cầu xe và thân xe được sử dụng để làm thông số điều chỉnh van điều hòa (cùng với thông số áp suất phanh hay còn gọi là cường độ phanh).","text":"Hình 10.45. Van điều hòa theo áp suất phanh và tải trọng xe Khi tải trọng thay đổi, biến dạng của hệ thống treo thay đổi và do đó, khoảng cách giữa cầu xe và thân xe thay đổi theo. Tải trọng tăng, khoảng cách giữa cầu xe và thân xe giảm đi và ngược lại, tải trọng giảm, khoảng cách giữa cầu xe và thân xe tăng lên. Sự tăng giảm khoảng cách giữa cầu xe và thân xe được sử dụng để làm thông số điều chỉnh van điều hòa (cùng với thông số áp suất phanh hay còn gọi là cường độ phanh).","pages":[80],"figure":{"number":"10.45","caption":"Hình 10.45. Van điều hòa theo áp suất phanh và tải trọng xe Khi tải trọng thay đổi, biến dạng của hệ thống treo thay đổi và do đó, khoảng cách giữa cầu xe và thân xe thay đổi theo. Tải trọng tăng, khoảng cách giữa cầu xe và thân xe giảm đi và ngược lại, tải trọng giảm, khoảng cách giữa cầu xe và thân xe tăng lên. Sự tăng giảm khoảng cách giữa cầu xe và thân xe được sử dụng để làm thông số điều chỉnh van điều hòa (cùng với thông số áp suất phanh hay còn gọi là cường độ phanh)."}},{"id":"s1647","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Nguyên lý làm việc Khi phanh nhẹ (áp suất thấp): Áp suất dầu từ xi-lanh chính sinh ra lực đẩy chưa đủ để thắng được lực đàn hồi tĩnh của lò xo. Do đó, lò xo vẫn đẩy và giữ pít- tông ở vị trí van mở hoàn toàn → áp suất dầu truyền đến cơ cấu phanh bánh trước và bánh sau gần như bằng nhau. Ở giai đoạn này, sự phân bố lực phanh được duy trì theo đúng tỷ lệ thiết kế cơ bản của hệ thống. Khi phanh mạnh (áp suất cao): Áp suất dầu tăng cao → pít-tông trong van dịch chuyển, nén lò xo → van bi đóng dần đường dầu ra cầu sau → làm giảm áp suất dầu phanh bánh sau so với bánh trước. Khi nhả phanh: Áp suất giảm, lò xo đẩy pít-tông và van bi trở lại vị trí ban đầu, khôi phục thông mạch dầu.","pages":[80]},{"id":"s1648","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Ứng dụng Trên xe du lịch: van điều hòa được tích hợp trong bộ chia dầu, điều chỉnh tự động theo áp suất. f) Van điều hòa lực phanh theo áp suất phanh và tải trọng Ở loại van điều hòa này, ngoài thông số áp suất phanh (cường độ phanh) còn có thêm một thông số điều chỉnh là tải trọng của xe, cụ thể là khoảng cách giữa cầu sau và thân xe (Hình 10.45). Vì thế, van còn được gọi là van điều hòa hai thông số. Van điều hòa loại này ngoài những chi tiết cơ bản của van điều hòa áp suất phanh, còn có thêm một lò xo cảm biến tải trọng được nối với cầu sau của xe. Khi tải trọng cầu sau thay đổi, lực do lò xo cảm biến tải tác dụng lên pít-tông trong van cũng thay đổi.","pages":[80]},{"id":"s1649","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Van điều hòa hai thông số thường gồm hai phần chính: - Phần điều chỉnh áp suất phanh: Nhận dầu từ xi-lanh chính và phân phối đến bánh sau. - Phần cảm biến tải trọng: Gồm cần nối và lò xo liên kết với cầu xe, tác dụng lên pít-tông van. Nguyên lý làm việc Khi tải trọng cầu sau thay đổi, độ biến dạng của hệ thống treo và cầu xe cũng thay đổi, kéo theo độ căng của lò xo cảm biến tải. Khi xe đầy tải (tải trọng lớn): Trọng lượng xe ép hệ thống treo biến dạng, khiến lò xo cảm biến tải bị nén nhiều và sinh ra một lực đẩy cơ học lớn tác dụng lên pít-tông. Lực ép này có tác dụng kháng lại áp suất thủy lực, giữ cho van điều tiết mở rộng và giữ lâu hơn. Nhờ vậy, dòng dầu từ xi-lanh chính ít bị tiết lưu, cho phép áp suất dầu truyền tới cơ cấu phanh bánh sau đạt mức cao, sinh ra lực phanh lớn tương ứng để giảm tốc của chiếc xe đang chở nặng.","pages":[81]},{"id":"s1650","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Khi xe không tải hoặc tải nhẹ: Khoảng cách giữa thân xe và cầu xe tăng lên khiến lò xo cảm biến tải giãn ra, dẫn đến lực cơ học ép lên pít-tông bị suy giảm đáng kể. Do lực giữ tĩnh rất nhỏ, chỉ cần một áp suất dầu phanh tương đối thấp đã đủ để đẩy pít-tông dịch chuyển, khiến van điều tiết làm việc (đóng/tiết lưu đường dầu) từ rất sớm. Kết quả là sự gia tăng áp suất dầu cấp đến phanh sau bị cắt giảm kịp thời, ngăn chặn hiện tượng dư thừa lực phanh gây khóa cứng (bó cứng) bánh sau – vốn là nguyên nhân chính gây trượt lết và mất kiểm soát quỹ đạo khi xe chạy vắng tải. Ứng dụng Van điều hòa loại này thích hợp cho xe có sự thay đổi tải trọng lớn giữa có tải và không tải, như xe tải nhẹ và xe du lịch. Khi xe phanh, van tự động điều chỉnh áp suất dầu đến bánh sau tương ứng với tải trọng thực tế, giúp cải thiện hiệu quả phanh và tránh trượt bánh sau. 3.","pages":[81]},{"id":"s1651","kind":"pdf","lesson":"10.3.2","title":"Hệ thống phanh · Dẫn động bằng thủy lực","text":"Dẫn động khí nén Phanh khí nén được sử dụng trên xe vận tải có tải trọng lớn. Hệ thống sử dụng năng lượng của không khí nén để thực hiện quá trình phanh. Hệ thống phanh khí nén có ưu điểm là tạo ra lực phanh lớn, điều khiển nhẹ nhàng, có thể dùng không khí nén vào các mục đích khác như bơm hơi bánh xe, truyền động cho bộ phận gạt nước trên kính. Tuy nhiên, hệ thống phanh khí nén có những nhược điểm sau: -Khi có sự rò rỉ khí nén do các mối ghép không kín thì thời gian phục hồi khả năng phanh khá lâu. - Do tính nén của không khí, hệ thống có đặc tính đáp ứng khác so với dẫn động thủy lực và yêu cầu các thiết bị điều khiển, tích trữ và bảo vệ khí nén phù hợp. - Kết cấu phức tạp thể hiện ở số lượng chi tiết nhiều, kích cỡ lớn. - Hệ thống sử dụng máy nén khí nên tiêu hao một phần công suất của động cơ để dẫn động máy nén khí.","pages":[81]},{"id":"s1652","kind":"figure","lesson":"10.3.3","title":"Hình 10.46. Sơ đồ nguyên lý hệ thống phanh khí nén 1. Máy nén khí; 2. Bộ điều áp; 3. Van bảo vệ; 4. Bình khí; 5. Van xả nước; 6. Van phanh tay; 7. Tổng van phanh; 8. Van theo tải trọng; 9. Bầu phanh; 10. Xi-lanh phanh; 11. Cụm","text":"Hình 10.46. Sơ đồ nguyên lý hệ thống phanh khí nén 1. Máy nén khí; 2. Bộ điều áp; 3. Van bảo vệ; 4. Bình khí; 5. Van xả nước; 6. Van phanh tay; 7. Tổng van phanh; 8. Van theo tải trọng; 9. Bầu phanh; 10. Xi-lanh phanh; 11. Cụm","pages":[82],"figure":{"number":"10.46","caption":"Hình 10.46. Sơ đồ nguyên lý hệ thống phanh khí nén 1. Máy nén khí; 2. Bộ điều áp; 3. Van bảo vệ; 4. Bình khí; 5. Van xả nước; 6. Van phanh tay; 7. Tổng van phanh; 8. Van theo tải trọng; 9. Bầu phanh; 10. Xi-lanh phanh; 11. Cụm"}},{"id":"s1653","kind":"figure","lesson":"10.3.3","title":"Hình 10.47. Sơ đồ cấu tạo hệ thống phanh khí nén Cấu tạo và nguyên lý làm việc của các cụm chi tiết chính trong hệ thống phanh khí nén được trình bày dưới đây.","text":"Hình 10.47. Sơ đồ cấu tạo hệ thống phanh khí nén Cấu tạo và nguyên lý làm việc của các cụm chi tiết chính trong hệ thống phanh khí nén được trình bày dưới đây.","pages":[82],"figure":{"number":"10.47","caption":"Hình 10.47. Sơ đồ cấu tạo hệ thống phanh khí nén Cấu tạo và nguyên lý làm việc của các cụm chi tiết chính trong hệ thống phanh khí nén được trình bày dưới đây."}},{"id":"s1654","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"a) Sơ đồ nguyên lý hệ thống phanh khí nén Hệ thống phanh khí nén gồm cơ cấu phanh và bộ phận dẫn động phanh (Hình 10.46). Cơ cấu phanh là bộ phận trực tiếp tạo ra sức cản chuyển động của ô tô. Bộ phận dẫn động phanh làm nhiệm vụ truyền năng lượng cho cơ cấu phanh và điều khiển cơ cấu phanh trong quá trình phanh.","pages":[82]},{"id":"s1655","kind":"figure","lesson":"10.3.3","title":"Hình 10.48. Sơ đồ và cấu tạo van phanh tổng 1. Thân van; 2, 5, 11. Pít-tông; 3. Tấm cao su; 4. Giá; 6. Cốc; 7, 12. Nắp van; 8, 9, 10, 13.","text":"Hình 10.48. Sơ đồ và cấu tạo van phanh tổng 1. Thân van; 2, 5, 11. Pít-tông; 3. Tấm cao su; 4. Giá; 6. Cốc; 7, 12. Nắp van; 8, 9, 10, 13.","pages":[83],"figure":{"number":"10.48","caption":"Hình 10.48. Sơ đồ và cấu tạo van phanh tổng 1. Thân van; 2, 5, 11. Pít-tông; 3. Tấm cao su; 4. Giá; 6. Cốc; 7, 12. Nắp van; 8, 9, 10, 13."}},{"id":"s1656","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"b) Van phanh tổng (tổng phanh, khóa phanh, van phân phối) Hiện nay, các xe sử dụng hệ thống phanh khí nén thường được trang bị từ 2 dòng trở lên. Van phanh tổng (7) trên Hình 10.47 của hệ thống dẫn động hai dòng là van phân phối có hai \"tầng\". \"Tầng trên\" có một đường dẫn khí vào từ bình khí và một đường ra cung cấp khí nén cho các bầu phanh sau (10). \"Tầng dưới\" cũng có một đường dẫn khí vào từ bình khí và một đường ra cung cấp khí nén cho các bầu phanh trước (9). Van phanh tổng (Hình 10.48) có vỏ 1 (gồm 2 phần 1a và 1b) lắp vào thân xe tại giá (4); các pít-tông (5), (2) và (11) lắp trong vỏ (1). Van có hai tầng: tầng trên và tầng dưới. Nắp van (7) là nắp chung của hai van: van nạp tầng trên V1 (nắp (7) với vỏ 1a), van xả tầng trên V2 (nắp (7) với pít-tông (5)).","pages":[83]},{"id":"s1657","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Nắp van (12) là nắp chung của hai van: Van nạp tầng dưới V3 (nắp (12) với vỏ 1b), van xả tầng dưới V4 (nắp (12) với pít-tông (11)). Lò xo (8) đẩy vào pít-tông (5) làm cho V2 mở khi không phanh (không có tác dụng của người lái). Tương tự lò xo (10) đẩy vào pít-tông (11) làm cho V4 mở khi không có tác dụng của người lái. Lò xo (9) đẩy vào nắp van (7) làm cho V1 đóng khi không phanh (không có tác dụng của người lái). Tương tự lò xo (13) đẩy vào nắp van (12) làm cho V3 đóng khi không có tác dụng của người lái. Pít-tông (2) ngăn chia phía trong vỏ 1 thành 2 tầng: tầng trên bao gồm khoang A và C, tầng dưới bao gồm khoang B và D. Các van V3 và V4 chia tầng dưới thành khoang B và khoang D. Cửa I và II nối với các bình khí, cửa III nối với bầu phanh sau, cửa IV nối với bầu phanh trước. Khoang E thông với khí trời qua cửa VI.","pages":[83]},{"id":"s1658","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Trên thân 1b, gần cửa ra III có lỗ V thông với khoang phía trên pít-tông (2).","pages":[83]},{"id":"s1659","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Khi không phanh (người lái không tác dụng vào bàn đạp), các van V1 và V3 đóng, V2 và V4 mở, khí nén đi vào buồng A và B và dừng lại ở đó, buồng C và D thông qua V2 và V4 qua khe hở của ty đẩy (14) thông với khoang E và qua cửa V thông với khí trời. Như vậy, các bầu phanh thông với khí trời, hệ thống không làm việc. Khi phanh, thông qua dẫn động, người lái tác dụng vào cốc (6), cốc (6) thông qua khối cao su (3) đẩy vào pít-tông (5). Pít-tông (5) đi xuống đóng V2, ngăn cách buồng C với khí trời, nếu tiếp tục đẩy sẽ mở V1 và khí nén sẽ qua V1 vào khoang C và đến các bầu phanh sau. Một lượng khí nén sẽ đi qua lỗ V trên vỏ 1b xuống và đẩy vào pít-tông (2), pít-tông (2) đi xuống, đẩy vào pít-tông (11), pít-tông (11) đi xuống đóng V4, ngăn cách buồng D với khí trời, sau đó mở V3, khí nén từ khoang B qua V3 sang khoang D và đi đến các bầu phanh trước.","pages":[84]},{"id":"s1660","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Khi nhả phanh, van trở về vị trí ban đầu, V1 và V3 đóng, V2 và V4 mở, khí nén từ các bầu phanh qua khoang C và D qua V2 và V4 đi ra khí trời. Khi đường dẫn khí đến cầu trước bị hỏng (đường khí nén đi qua cửa II, V3, V4, cửa IV), đường khí nén đến cầu sau (đi qua cửa I, V1, V2, cửa III) vẫn làm việc bình thường. Ngược lại, nếu đường khí nén ra cầu sau bị hỏng, trong buồng C không có áp suất; khi người lái đạp phanh, pít-tông (5) đẩy ty đẩy (14) đi xuống, ty đẩy (14) đẩy vào pít-tông (11) và khi đó người lái trực tiếp điều khiển các van dẫn khí nén ra cầu trước. Người lái đạp phanh đến một vị trí nhất định rồi dừng lại, cốc (6) dừng lại. Ở thời điểm đó, các van V1 và V3 mở, V2 và V4 đóng, khí nén vẫn tiếp tục đi vào khoang C và D.","pages":[84]},{"id":"s1661","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Áp suất trong khoang C tăng đẩy pít-tông (5) đi lên nén khối cao su (3) lại, lò xo (9) sẽ đẩy nắp (7) đi lên cùng với pít-tông (5) và đóng V1 lại, duy trì áp suất trong khoang C tương ứng với lực (hoặc vị trí) bàn đạp. Tương tự áp suất trong khoang D tăng đẩy pít-tông (11) và (2) đi lên, lò xo (13) sẽ đẩy nắp (12) đi lên và đóng V3 lại, duy trì áp suất trong khoang D tương ứng với lực (hoặc vị trí) bàn đạp. c) Van điều chỉnh áp suất (Hình 10.49) Khi áp suất khí nén trong hệ thống (tại cửa B) vượt quá giới hạn trên, áp lực này thắng lực đàn hồi của lò xo (10), đẩy pít-tông cân bằng (7) dịch chuyển lên trên. Chuyển động này làm đóng van (11) và mở van (13), cho phép khí nén đi qua rãnh I vào buồng phía trên pít-tông (14). Khí nén đẩy pít-tông (14) đi xuống, ép mở van giảm tải (3).","pages":[84]},{"id":"s1662","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Lúc này, luồng khí từ máy nén cấp vào sẽ xả thẳng ra ngoài qua cửa D (máy nén chạy không tải), đồng thời nước ngưng tụ trên đế van (4) cũng được đẩy ra môi trường. Khi áp suất hệ thống giảm xuống dưới giới hạn cho phép, lò xo (10) đẩy pít-tông cân bằng (7) lùi xuống, làm mở van (11) và đóng van (13). Áp suất phía trên pít-tông (14) bị xả bỏ, lò xo (2) đẩy van giảm tải (3) đóng lại, cho phép máy nén tiếp tục nạp khí vào hệ thống. Ngoài ra, lực đàn hồi của lò xo (2) được thiết kế kiêm chức năng an toàn: nếu cụm van điều khiển gặp sự cố kẹt, áp suất dòng khí nén tăng vượt","pages":[84]},{"id":"s1663","kind":"figure","lesson":"10.3.3","title":"Hình 10.49. Van điều chỉnh áp suất 1. Nắp dưới; 2, 10. Lò xo; 3. Van giảm tải; 4. Đế van; 5. Thân van; 6. Lưới lọc; 7. Pít-","text":"Hình 10.49. Van điều chỉnh áp suất 1. Nắp dưới; 2, 10. Lò xo; 3. Van giảm tải; 4. Đế van; 5. Thân van; 6. Lưới lọc; 7. Pít-","pages":[85],"figure":{"number":"10.49","caption":"Hình 10.49. Van điều chỉnh áp suất 1. Nắp dưới; 2, 10. Lò xo; 3. Van giảm tải; 4. Đế van; 5. Thân van; 6. Lưới lọc; 7. Pít-"}},{"id":"s1664","kind":"figure","lesson":"10.3.3","title":"Hình 10.50. Máy nén khí 1. Bánh đai dẫn động; 2. Khối xi-lanh; 3, 7. Pít-tông; 4. Nắp; 5, 6. Van nạp; 8. Thanh","text":"Hình 10.50. Máy nén khí 1. Bánh đai dẫn động; 2. Khối xi-lanh; 3, 7. Pít-tông; 4. Nắp; 5, 6. Van nạp; 8. Thanh","pages":[85],"figure":{"number":"10.50","caption":"Hình 10.50. Máy nén khí 1. Bánh đai dẫn động; 2. Khối xi-lanh; 3, 7. Pít-tông; 4. Nắp; 5, 6. Van nạp; 8. Thanh"}},{"id":"s1665","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"tông cân bằng; 8. Nắp trên; 9. Bu lông điều chỉnh; 11, 13. Nắp van kép; 12. Van một chiều; 14. Pít-tông van xả d) Máy nén khí (Hình 10.50) truyền; 9. Hộp trục khuỷu; 10. Trục khuỷu. Máy nén khí cung cấp cho hệ thống phanh khí nén có áp suất khoảng 0,4 ÷ 0,7 MPa. Máy nén khí của hệ thống phanh là loại máy nén pít-tông, dẫn động từ động cơ của xe bằng dây đai thang. Tùy theo tải trọng xe mà máy nén có một hoặc hai pít-tông.","pages":[85]},{"id":"s1666","kind":"figure","lesson":"10.3.3","title":"Hình 10.51. Cấu tạo bầu phanh đơn kiểu màng (a) và kiểu pít-tông (b)","text":"Hình 10.51. Cấu tạo bầu phanh đơn kiểu màng (a) và kiểu pít-tông (b)","pages":[86],"figure":{"number":"10.51","caption":"Hình 10.51. Cấu tạo bầu phanh đơn kiểu màng (a) và kiểu pít-tông (b)"}},{"id":"s1667","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Bánh đai (1) lắp với trục khuỷu (10), nhận truyền động từ động cơ của xe. Thân máy nén có 3 khối chính: khối xi-lanh (2), nắp (4) và hộp trục khuỷu (9). Trục khuỷu quay, thông qua các thanh truyền (8) làm các pít-tông (3) và (7) chuyển động tịnh tiến lên xuống đẩy khí qua van nạp (6) đến đường ống và đến các bình khí nén. Trên ô tô, máy nén không làm việc hết 100% thời gian. Khi khí nén trong bình đã đủ áp suất theo quy định, một hệ thống van sẽ mở để áp suất trong xi-lanh bằng áp suất khí quyển và máy nén chỉ quay nhưng không nén khí. Ví dụ, máy nén có hai xi- lanh như trên Hình 10.50 có thể bố trí van nối thông hai xi-lanh. e) Bầu phanh Bầu phanh bánh xe dùng để biến đổi năng lượng của khí nén thành cơ năng thực hiện việc phanh xe ở cơ cấu phanh bánh xe. Bầu phanh có nhiệm vụ tạo lực khí nén đẩy cần đẩy dịch chuyển, làm xoay cam quay ở cơ cấu phanh.","pages":[86]},{"id":"s1668","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Bầu phanh bánh xe có cấu trúc như xi-lanh lực tác động một chiều. Vỏ của bầu phanh được cố định trên vỏ cầu, đồng thời tựa chặt trên pít-tông đẩy và dịch chuyển để điều khiển cam quay. Bầu phanh có thể chia làm hai loại chính: - Bầu phanh đơn: là loại có tác dụng một chiều. - Bầu phanh kép: có tác dụng hai chiều (bầu phanh tích năng). Bầu phanh đơn (Hình 10.51) Khi phanh, không khí nén từ tổng van phanh qua ống dẫn tạo áp lực tác động lên màng ngăn và thắng sức căng lò xo; pít-tông dịch chuyển làm thanh đẩy cùng dịch chuyển, tác động lên cơ cấu phanh đẩy hai guốc phanh bung ra và quá trình phanh được thực hiện. Khi nhả phanh, không khí nén không được cấp tới bầu phanh nữa nên lò xo đẩy pít-tông dịch chuyển, ép không khí thoát ra ngoài qua tổng van phanh; cùng với lò xo hồi vị guốc phanh, quá trình phanh kết thúc. a) 1. Thanh đẩy; 2. Lò xo nén; 3.","pages":[86]},{"id":"s1669","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Màng ngăn; 4. Pít-tông. b) 1. Vòng hãm giữa cần bầu phanh với ống dẫn hướng; 2. Xi-lanh; 3. Pít-tông; 4. Phớt làm kín; 5. Vòng làm kín; 6. Lò xo hồi vị; 7. Ống dẫn hướng; 8. Nắp; 9. Chụp bao kín; 10. Cần bầu phanh; 11. Đầu nối; 12. Vòng chắn mỡ; 13. Phin lọc.","pages":[86]},{"id":"s1670","kind":"figure","lesson":"10.3.3","title":"Hình 10.52. Bầu tích năng 1. Lò xo tích năng; 2. Bầu tích năng; 3. Pít-tông; 4. Bu lông; 5. Ống đẩy; 6, 9. Bầu phanh","text":"Hình 10.52. Bầu tích năng 1. Lò xo tích năng; 2. Bầu tích năng; 3. Pít-tông; 4. Bu lông; 5. Ống đẩy; 6, 9. Bầu phanh","pages":[87],"figure":{"number":"10.52","caption":"Hình 10.52. Bầu tích năng 1. Lò xo tích năng; 2. Bầu tích năng; 3. Pít-tông; 4. Bu lông; 5. Ống đẩy; 6, 9. Bầu phanh"}},{"id":"s1671","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Bầu phanh kép (bầu tích năng) (Hình 10.52) Phía phải là bầu phanh của phanh chính với màng phanh (7), vỏ bầu phanh gồm hai nửa (6 và 9). Khi phanh (phanh chính), khí nén được dẫn vào bầu phanh từ cửa I, khí nén đẩy vào màng và màng (7) đẩy thanh đẩy (12) sang phải, thực hiện sự phanh. Phía trái của vỏ (6) được lắp thêm vỏ (2) của bầu tích năng. Trong vỏ (2) lắp pít-tông (3) và lò xo tích năng (1). Cửa II dẫn khí nén từ van điều khiển phanh dừng đến khoang A. Khi không phanh (phanh dừng), khí nén được dẫn vào khoang A, áp suất khí nén tác dụng vào pít-tông (3) và nén lò xo tích năng (1) lại (như trên Hình 10.52). Khi phanh (phanh dừng), khí nén từ khoang A sẽ thoát qua cửa II, qua van điều khiển ra ngoài, lò xo tích năng (1) giãn ra, đẩy vào pít-tông (3), thông qua ống đẩy (5) tác dụng vào màng (7) và thực hiện sự phanh.","pages":[87]},{"id":"s1672","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Trên xe có hệ thống phanh khí nén, bầu tích năng dạng lò xo được sử dụng để dẫn động phanh dừng, thông qua van phanh tay. chính; 7. Màng phanh; 8. Đai hãm; 10. Lò xo hồi vị; 11. Bu lông; 12. Thanh đẩy. f) Van phanh tay và van gia tốc Mặt cắt của van điều khiển phanh dừng (van phanh tay) thể hiện trên Hình 10.53a. Van gồm có thân (14) và nắp (12). Trong nắp (12) lắp nắp dẫn hướng (11). Nắp (11) quay cùng nắp (12) và dịch chuyển tương đối được với nhau theo chiều thẳng đứng. Giữa nắp (12) và nắp (11) đặt lò xo (10). Mặt dưới của nắp dẫn hướng (11) tựa lên mặt trên của ống (13); mặt trên của ống (13) được gia công có mặt nghiêng xoáy trôn ốc. Trong thân (14) lắp pít-tông (3). Phía trên pít-tông (3) lắp ống (6). Giữa ống (6) và pít-tông (3) đặt lò xo (4). Phía trên ống (6) lắp ống (7). Cần (9) nối nắp dẫn hướng (11) và ống (7) thông qua lò xo (5).","pages":[87]},{"id":"s1673","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Trong pít-tông (3) lắp nắp van (2). Nắp van (2) cùng với đế là pít-tông (3) tạo thành van xả; nắp van (2) cùng với đế là cần (9) tạo thành van nạp. Cửa I nối với bình khí, cửa II thông với khí trời và cửa III nối với van gia tốc.","pages":[87]},{"id":"s1674","kind":"figure","lesson":"10.3.3","title":"Hình 10.53. Kết cấu van phanh tay và van gia tốc a) Van phanh tay: 1, 4, 5, 10. Lò xo; 2. Nắp van; 3. Pít-tông; 6. Ống dưới; 7. Ống trên; 8. Cần điều khiển; 9. Cần đẩy; 11. Nắp dẫn hướng; 12. Nắp van; 13. Ống có mặt nghiêng;","text":"Hình 10.53. Kết cấu van phanh tay và van gia tốc a) Van phanh tay: 1, 4, 5, 10. Lò xo; 2. Nắp van; 3. Pít-tông; 6. Ống dưới; 7. Ống trên; 8. Cần điều khiển; 9. Cần đẩy; 11. Nắp dẫn hướng; 12. Nắp van; 13. Ống có mặt nghiêng;","pages":[88],"figure":{"number":"10.53","caption":"Hình 10.53. Kết cấu van phanh tay và van gia tốc a) Van phanh tay: 1, 4, 5, 10. Lò xo; 2. Nắp van; 3. Pít-tông; 6. Ống dưới; 7. Ống trên; 8. Cần điều khiển; 9. Cần đẩy; 11. Nắp dẫn hướng; 12. Nắp van; 13. Ống có mặt nghiêng;"}},{"id":"s1675","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Van được người lái điều khiển bằng cách xoay cần (8) làm nắp ngoài (12) và nắp dẫn hướng (11) quay theo. Van có ba vị trí đáng chú ý như sau: vị trí không phanh, vị trí phanh hoàn toàn và vị trí trung gian. Vị trí phanh hoàn toàn: trên Hình 10.53a, van đang ở vị trí phanh hoàn toàn; cần (8) ở vị trí tương ứng với nắp (11) ở vị trí cao nhất, nắp van (2) không chạm được vào đế van trên cần (9), do đó van xả luôn mở. Khí nén từ van gia tốc qua cửa III đến khoang A, qua van xả đến khoang B và theo cửa II thoát ra khí trời. Phanh dừng ở trạng thái phanh hoàn toàn. Vị trí không phanh: Người lái kéo cần (8) đi hết hành trình, nắp dẫn hướng (11) quay theo. Mặt dưới của nắp (11) trượt trên rãnh nghiêng của ống (13) và bị lò xo (10) đẩy xuống, kéo theo cần (9) bị đẩy xuống.","pages":[88]},{"id":"s1676","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Mặt dưới của cần (9) (đế van xả) chạm vào nắp (2), đóng van xả lại và tiếp tục đẩy nắp (2) và pít-tông (3) xuống vị trí thấp nhất. Ở vị trí này, nắp (2) thấp hơn pít-tông (3) nên van nạp luôn mở. Khí nén từ bình khí vào khoang C qua van nạp vào khoang A, ra cửa III và đi sang van gia tốc. Phanh dừng sẽ ở trạng thái không phanh. b) Van gia tốc: 1.Van xả; 2.Pít-tông điều khiển; 3.Đế van xả; 4. Nắp van nạp; 5. Ống dẫn hướng; 6. Lò xo van nạp; 7. Thân van; 8. Lò xo pít-tông. Cửa I: Cửa khí nén điều khiển từ van phanh tay; Cửa II: Cửa khí nén cấp từ bình chứa; Cửa III: Cửa khí nén nối với bầu phanh tích năng; Khoang A: Khoang nhận áp suất điều khiển; Khoang B: Khoang cấp và xả khí nén đến bầu phanh tích năng; Khoang C: Khoang làm việc bên trong cụm pít-tông và van.","pages":[88]},{"id":"s1677","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Vị trí trung gian: Cần (8) ở vị trí trung gian (giữa hai vị trí nói trên), pít-tông (3) trở thành pít-tông tùy động. Pít-tông cân bằng với phía trên là lực của lò xo cân","pages":[88]},{"id":"s1678","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"bằng (5) và áp suất khoang A (tức áp suất ở van gia tốc), và phía dưới là áp suất ở khoang C (tức áp suất bình khí). Lúc này cả hai van nạp, xả đều đóng. Mặt cắt của van gia tốc thể hiện trên Hình 10.53b. Vỏ van gồm nắp (1) và thân (7). Trong thân van lắp ống dẫn hướng (5) và trong nắp van (1) lắp pít-tông (2). Trên ống (5) lắp đế (3) của van xả và nắp (4) của van nạp. Nắp của van xả là pít-tông (2) còn đế của van nạp là thân (7). Cửa I nhận khí nén từ van điều khiển hệ thống phanh dừng, cửa II nhận khí nén từ bình khí, cửa III đi đến bầu tích năng. Khi không có khí nén từ van điều khiển đến, lò xo (6) đẩy ống (5) và nắp van (4) đi lên. Nắp van (4) chạm vào thân (7) và van nạp đóng lại. Khí nén từ bình khí đi đến cửa I và dừng ở đó. Lò xo (8) đẩy pít-tông (2) đi lên và van xả mở. Khoang B qua van xả thông sang khoang C và thông với khí trời.","pages":[89]},{"id":"s1679","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Bầu tích năng không có khí nén, lò xo tích năng (lò xo (1) trên Hình 10.52) giãn ra, thực hiện sự phanh. Khi người lái kéo cần (8) của van điều khiển (Hình 10.53a), khí nén từ van điều khiển đi đến cửa I vào khoang A và đẩy pít-tông (3) đi xuống. Pít-tông (3) chạm vào đế (2) của van xả làm van xả đóng lại, ngăn cách buồng B với khí trời. Khí nén từ khoang A tiếp tục đẩy pít-tông (3) đi xuống, thông qua đế van (2) đẩy ống (5) đi xuống làm mở van nạp. Khí nén từ cửa II qua van nạp vào khoang B và đi đến bầu tích năng. Khí nén đẩy vào pít-tông (3) (Hình 10.53) làm nén lò xo lại và phanh dừng nhả ra. Cấu tạo và nguyên lý hoạt động của van gia tốc (Hình 10.53b) Van gia tốc đóng vai trò như một rơ-le khí nén, giúp cấp hoặc xả khí nhanh cho bầu phanh tích năng.","pages":[89]},{"id":"s1680","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Về mặt kết nối, cửa I nhận tín hiệu khí nén từ van điều khiển (van phanh tay), cửa II nhận khí nén trực tiếp từ bình chứa, và cửa III dẫn khí nén đi đến bầu phanh tích năng. Nguyên lý làm việc: Trạng thái phanh dừng (Không có khí nén điều khiển): (Không có khí nén điều khiển): Khi van phanh tay ở vị trí phanh, không có dòng khí nén đi đến cửa I, khoang A không có áp suất. Lúc này, lò xo (8) đẩy pít-tông (2) đi lên, làm hở khoảng cách giữa pít-tông (2) và đế van xả (3) đẩy van xả mở. Đồng thời, lò xo (6) đẩy ống dẫn hướng (5) và nắp van nạp (4) đi lên chạm chặt vào thân van (7) khiến van nạp đóng lại. Khí nén từ bình chứa đến cửa II bị chặn lại hoàn toàn. Khí nén tồn dư trong bầu tích năng sẽ đi ngược về cửa III (vào khoang B), xuyên qua van xả đang mở để thoát ra môi trường.","pages":[89]},{"id":"s1681","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"Bầu tích năng mất áp suất, lò xo tích năng bung ra thực hiện việc hãm cứng bánh xe (phanh dừng). Trạng thái không phanh (Có khí nén điều khiển): Khi người lái thao tác nhả phanh tay, khí nén từ van điều khiển đi vào cửa I, nạp vào khoang A và tạo áp lực đẩy pít-tông (2) đi xuống. Pít-tông (2) trước tiên sẽ chạm vào đế (3) trên ống dẫn hướng (5), làm đóng kín van xả (ngăn cách khoang B với khí trời). Áp lực khí nén ở khoang A tiếp tục ép pít-tông (2) đẩy cụm ống (5) và nắp van (4) dịch chuyển xuống dưới, tách rời nắp van (4) khỏi thân (7) khiến van nạp mở. Khí nén áp suất cao từ bình chứa (cửa II) lập tức đi qua van nạp, vào khoang B và thoát ra cửa III để nạp nhanh vào bầu phanh tích năng. Khí nén sẽ thắng lực ép của lò xo tích năng, đẩy cơ cấu phanh nhả ra, đưa xe về trạng thái sẵn sàng di chuyển.","pages":[89]},{"id":"s1682","kind":"figure","lesson":"10.3.3","title":"Hình 10.54. Cấu tạo van bảo vệ 4 ngả 1. Vỏ bọc; 2. Lò xo nén; 3. Phớt làm kín; 4. Đế van; 5. Cửa tiết lưu; 6. Van tràn; 7. Van","text":"Hình 10.54. Cấu tạo van bảo vệ 4 ngả 1. Vỏ bọc; 2. Lò xo nén; 3. Phớt làm kín; 4. Đế van; 5. Cửa tiết lưu; 6. Van tràn; 7. Van","pages":[90],"figure":{"number":"10.54","caption":"Hình 10.54. Cấu tạo van bảo vệ 4 ngả 1. Vỏ bọc; 2. Lò xo nén; 3. Phớt làm kín; 4. Đế van; 5. Cửa tiết lưu; 6. Van tràn; 7. Van"}},{"id":"s1683","kind":"figure","lesson":"10.3.4","title":"Hình 10.55. Sơ đồ hệ thống phanh thủy lực - khí nén 1. Máy nén khí; 2. Bình khí; 3. Van phân phối; 4. Đường ống dẫn khí; 5, 6. Cụm xi-lanh","text":"Hình 10.55. Sơ đồ hệ thống phanh thủy lực - khí nén 1. Máy nén khí; 2. Bình khí; 3. Van phân phối; 4. Đường ống dẫn khí; 5, 6. Cụm xi-lanh","pages":[90],"figure":{"number":"10.55","caption":"Hình 10.55. Sơ đồ hệ thống phanh thủy lực - khí nén 1. Máy nén khí; 2. Bình khí; 3. Van phân phối; 4. Đường ống dẫn khí; 5, 6. Cụm xi-lanh"}},{"id":"s1684","kind":"pdf","lesson":"10.3.3","title":"Hệ thống phanh · Dẫn động khí nén","text":"g) Van bảo vệ 4 ngả Van bảo vệ 4 ngả (Hình 10.54) dùng để chia khí nén từ máy nén khí đến hai đường khí chính cho bầu tích khí và một đường cho van phanh tay. Van bảo vệ sẽ tự động ngắt một đường khí nào đó khi đường khí đó bị hở và đảm bảo hoạt động của các đường còn lại. Khí nén từ máy nén khí đi vào qua cửa số 1, ngay sau khi áp suất khí nén đạt áp suất mở quy định, các van I và II mở, khí nén đi qua cửa 21 và 22 vào các mạch phanh để thực hiện quá trình phanh. Khi một trong các ống dẫn khí bị hở, áp suất trong thân van giảm xuống, khi đó van của đường dây còn lại và van phanh tay sẽ đóng lại để ngăn ngừa áp suất trong các đường này cũng giảm theo. Giả sử đường phanh I bị hỏng và áp suất giảm xuống lúc này van của đường I đóng lại và khí nén chỉ vào đường còn lại và van phanh tay qua van một chiều. một chiều; 8. Cửa cố định 4.","pages":[90]},{"id":"s1685","kind":"pdf","lesson":"10.3.4","title":"Hệ thống phanh · Dẫn động kết hợp thuỷ lực - khí nén","text":"Dẫn động kết hợp thủy lực - khí nén kép; 7. Đường ống dẫn chất lỏng; 8, 9. Cơ cấu phanh.","pages":[90]},{"id":"s1686","kind":"figure","lesson":"10.3.4","title":"Hình 10.56 thể hiện cụm xi-lanh kép của hệ thống phanh dẫn động liên hợp có sơ đồ ở Hình 10.55. Có hai pít-tông - xi-lanh khí lắp nối tiếp với nhau với mục đích làm tăng lực đẩy vào pít-tông chất lỏng mà không phải tăng đường kính xi-lanh khí.","text":"Hình 10.56 thể hiện cụm xi-lanh kép của hệ thống phanh dẫn động liên hợp có sơ đồ ở Hình 10.55. Có hai pít-tông - xi-lanh khí lắp nối tiếp với nhau với mục đích làm tăng lực đẩy vào pít-tông chất lỏng mà không phải tăng đường kính xi-lanh khí.","pages":[91],"figure":{"number":"10.56","caption":"Hình 10.56 thể hiện cụm xi-lanh kép của hệ thống phanh dẫn động liên hợp có sơ đồ ở Hình 10.55. Có hai pít-tông - xi-lanh khí lắp nối tiếp với nhau với mục đích làm tăng lực đẩy vào pít-tông chất lỏng mà không phải tăng đường kính xi-lanh khí."}},{"id":"s1687","kind":"figure","lesson":"10.3.4","title":"Hình 10.56. Kết cấu xi-lanh kép 1, 4. Pít-tông khí; 2. Ống nối; 3, 5. Xi-lanh khí; 6. Thanh đẩy; 7. Bình dầu phanh; 8. Xi-","text":"Hình 10.56. Kết cấu xi-lanh kép 1, 4. Pít-tông khí; 2. Ống nối; 3, 5. Xi-lanh khí; 6. Thanh đẩy; 7. Bình dầu phanh; 8. Xi-","pages":[91],"figure":{"number":"10.56","caption":"Hình 10.56. Kết cấu xi-lanh kép 1, 4. Pít-tông khí; 2. Ống nối; 3, 5. Xi-lanh khí; 6. Thanh đẩy; 7. Bình dầu phanh; 8. Xi-"}},{"id":"s1688","kind":"pdf","lesson":"10.3.4","title":"Hệ thống phanh · Dẫn động kết hợp thuỷ lực - khí nén","text":"Hệ thống phanh dẫn động liên hợp (Hình 10.55): Kết hợp dẫn động khí nén và chất lỏng. Hệ thống có máy nén khí (1), bình khí (2), van phân phối khí nén (3), các đường ống dẫn khí nén (4), xi-lanh kép (5, 6), các đường ống dẫn chất lỏng (7) và các cơ cấu phanh (8, 9). Máy nén, bình khí và van phân phối có cấu tạo như ở hệ thống dẫn động khí nén. Xi-lanh kép có xi-lanh khí nén và xi-lanh chất lỏng (Hình 10.56). Khi phanh, người lái đạp phanh, khí nén qua van phân phối đến xi-lanh khí nén của xi-lanh kép tác dụng vào pít-tông. Pít-tông khí nén qua thanh đẩy tác dụng vào pít-tông chất lỏng, đẩy chất lỏng từ xi-lanh chất lỏng trong xi-lanh kép đi đến các cơ cấu phanh tại các bánh xe. Để giảm thiểu nhược điểm của dẫn động khí nén, các bộ phận phải bố trí sao cho các đường ống dẫn khí nén phải ngắn.","pages":[91]},{"id":"s1689","kind":"pdf","lesson":"10.3.4","title":"Hệ thống phanh · Dẫn động kết hợp thuỷ lực - khí nén","text":"Muốn như vậy, phải bố trí bình khí và các xi-lanh kép gần van phân phối. lanh chất lỏng; 9. Pít-tông thủy lực. Khí nén đi qua van phân phối và đường ống được dẫn vào cửa I đi vào khoang A bên phải pít-tông khí (1) và qua ống dẫn nằm trong pít-tông (1) và ống nối (2) đến khoang B bên trái pít-tông (4). Pít-tông (1) và (4) bị đẩy sang trái, thông qua thanh đẩy (6) tác dụng vào pít-tông chất lỏng (9), ép chất lỏng từ khoang C của xi-lanh chất lỏng (8) qua cửa II đến các cơ cấu phanh. 5. Hệ thống phanh có điều khiển điện tử a) Hệ thống phanh thuỷ lực chống bó cứng bánh xe (Anti-lock Brake System – ABS) Khi phanh khẩn cấp, để các bánh xe không bị bó cứng và không mất khả năng điều khiển vành tay lái, người lái cần lặp lại nhiều lần động tác đạp và nhả bàn đạp phanh. Tuy nhiên, trong tình huống phanh khẩn cấp không có đủ thời gian để thực hiện việc này.","pages":[91]},{"id":"s1690","kind":"pdf","lesson":"10.3.4","title":"Hệ thống phanh · Dẫn động kết hợp thuỷ lực - khí nén","text":"Hệ thống ABS (Hình 10.58) dùng một máy tính để xác định tình trạng quay của 4 bánh xe trong khi phanh và có thể tự động đạp và nhả phanh.","pages":[91]},{"id":"s1691","kind":"figure","lesson":"10.3.5","title":"Hình 10.57. Đặc tính trượt","text":"Hình 10.57. Đặc tính trượt","pages":[92],"figure":{"number":"10.57","caption":"Hình 10.57. Đặc tính trượt"}},{"id":"s1692","kind":"figure","lesson":"10.3.5","title":"Hình 10.58. Sơ đồ các cụm chức năng cơ cấu ABS thủy lực 1. Cảm biến tốc độ bánh trước; 2. Công tắc báo mức dầu phanh; 3. Công tắc đèn phanh;","text":"Hình 10.58. Sơ đồ các cụm chức năng cơ cấu ABS thủy lực 1. Cảm biến tốc độ bánh trước; 2. Công tắc báo mức dầu phanh; 3. Công tắc đèn phanh;","pages":[92],"figure":{"number":"10.58","caption":"Hình 10.58. Sơ đồ các cụm chức năng cơ cấu ABS thủy lực 1. Cảm biến tốc độ bánh trước; 2. Công tắc báo mức dầu phanh; 3. Công tắc đèn phanh;"}},{"id":"s1693","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Mối quan hệ giữa lực phanh và hệ số trượt của bánh xe có thể được biểu diễn bằng đường đặc tính μ–λ (Hình 10.57). Khi hệ số trượt tăng, lực bám dọc của lốp tăng đến một giá trị cực đại, sau đó có xu hướng giảm khi bánh xe tiến gần trạng thái bó cứng. Giá trị hệ số trượt tương ứng với lực bám cực đại phụ thuộc vào loại lốp, tải trọng, tốc độ và đặc biệt là điều kiện mặt đường. 4. Cảm biến tốc độ bánh sau; 5. ECU điều khiển; 6. Bộ chấp hành ABS","pages":[92]},{"id":"s1694","kind":"figure","lesson":"10.3.5","title":"Hình 10.59. ECU điều khiển","text":"Hình 10.59. ECU điều khiển","pages":[93],"figure":{"number":"10.59","caption":"Hình 10.59. ECU điều khiển"}},{"id":"s1695","kind":"figure","lesson":"10.3.5","title":"Hình 10.60. Bộ chấp hành thủy lực 1. Bộ chấp hành của phanh; 2. ECU điều khiển trượt; 3. Bơm; 4. Bình chứa; 5. Van điện","text":"Hình 10.60. Bộ chấp hành thủy lực 1. Bộ chấp hành của phanh; 2. ECU điều khiển trượt; 3. Bơm; 4. Bình chứa; 5. Van điện","pages":[93],"figure":{"number":"10.60","caption":"Hình 10.60. Bộ chấp hành thủy lực 1. Bộ chấp hành của phanh; 2. ECU điều khiển trượt; 3. Bơm; 4. Bình chứa; 5. Van điện"}},{"id":"s1696","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Hệ thống ABS liên tục xác định trạng thái quay của từng bánh xe và điều chỉnh áp suất phanh thông qua bộ chấp hành để hạn chế hiện tượng bó cứng, duy trì bánh xe trong vùng trượt thích hợp. Nhờ đó, ABS vừa tận dụng khả năng bám dọc của lốp để tạo lực phanh lớn, vừa duy trì khả năng truyền lực ngang cần thiết cho ổn định hướng của xe. Trên mặt đường có hệ số bám thấp như đường ướt, tuyết hoặc băng, lực bám tổng thể giảm nên quãng đường phanh vẫn có thể tăng dù ABS đang hoạt động. Trên một số bề mặt đặc biệt như đường sỏi hoặc tuyết mới, đặc tính làm việc của ABS có thể khác so với mặt đường nhựa thông thường. Sơ đồ bố trí các cụm chức năng của hệ thống ABS thủy lực thể hiện trên Hình 10.58. Các bộ phận chính của hệ thống được trình bày dưới đây.","pages":[93]},{"id":"s1697","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"ECU (Bộ điều khiển điện tử) (Hình 10.59): Bộ phận này xác định mức trượt giữa bánh xe và mặt đường dựa vào các tín hiệu từ các cảm biến và điều khiển bộ chấp hành phanh. từ giảm áp suất; 6. Van điện từ giữ áp suất; 7. Van điện từ chuyển mạch hỗ trợ phanh.","pages":[93]},{"id":"s1698","kind":"figure","lesson":"10.3.5","title":"Hình 10.61. Van điện từ 2-vị trí có van điều khiển lưu lượng","text":"Hình 10.61. Van điện từ 2-vị trí có van điều khiển lưu lượng","pages":[94],"figure":{"number":"10.61","caption":"Hình 10.61. Van điện từ 2-vị trí có van điều khiển lưu lượng"}},{"id":"s1699","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Bộ chấp hành ABS: Bộ chấp hành phanh (Hình 10.60) gồm có van điện từ giữ áp suất, van điện từ giảm áp suất, bơm, mô-tơ và bình chứa.Trong quá trình vận hành, dựa trên tín hiệu phân tích từ bộ điều khiển điện tử chống trượt, hệ thống các van điện từ sẽ liên tục đóng/mở để thực hiện ba chế độ kiểm soát áp suất tại cơ cấu phanh bánh xe: Chế độ giữ áp suất: Van điện từ chuyển trạng thái để cô lập đường ống, ngắt mạch dầu từ xi-lanh chính đến bánh xe. Áp suất tại cơ cấu phanh được giữ cố định, ngăn chặn nguy cơ bánh xe bị hãm cứng hoàn toàn. Chế độ giảm áp suất: Nếu bánh xe vẫn có xu hướng trượt lết, van điện từ giảm áp (5) sẽ mở để xả bớt một phần áp lực dầu phanh đưa về bình tích áp (4). Ngay lập tức, mô-tơ sẽ dẫn động bơm (3) hút lượng dầu này trả ngược về mạch dẫn phía trên.","pages":[94]},{"id":"s1700","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Quá trình này giúp nới lỏng lực ép má phanh, cho phép bánh xe lấy lại tốc độ quay và khôi phục lực bám với mặt đường. Chế độ tăng áp suất: Khi bánh xe đã thoát khỏi trạng thái trượt và bám đường trở lại, hệ thống van mở thông mạch, cho phép áp suất dầu tiếp tục truyền đến cơ cấu phanh để duy trì lực hãm tối ưu. Bộ chấp hành của phanh có các loại sau đây: Van điện từ hai vị trí có van điều khiển lưu lượng (Hình 10.61): Bộ chấp hành thủy lực của hệ thống phanh bao gồm nhiều loại, trong đó phổ biến là loại sử dụng van điện từ hai vị trí kết hợp van điều khiển lưu lượng (Hình 10.61). Đối với kết cấu này, van điều khiển lưu lượng hoạt động theo nguyên lý cơ - thủy lực (không nhận tín hiệu điều khiển trực tiếp từ bộ điều khiển điện tử) nhằm tự động điều tiết áp suất dầu phanh cấp đến từng cơ cấu phanh ở các bánh xe.","pages":[94]},{"id":"s1701","kind":"figure","lesson":"10.3.5","title":"Hình 10.62. Van điện từ 2-vị trí có van tăng áp suất Van điện từ 3-vị trí có van cơ học (Hình 10.63): Van cơ học hoạt động để điều chỉnh áp suất thủy lực của phanh các bánh sau bên phải và bên trái. Van cơ học được sử dụng khi có đường ống chéo.","text":"Hình 10.62. Van điện từ 2-vị trí có van tăng áp suất Van điện từ 3-vị trí có van cơ học (Hình 10.63): Van cơ học hoạt động để điều chỉnh áp suất thủy lực của phanh các bánh sau bên phải và bên trái. Van cơ học được sử dụng khi có đường ống chéo.","pages":[95],"figure":{"number":"10.62","caption":"Hình 10.62. Van điện từ 2-vị trí có van tăng áp suất Van điện từ 3-vị trí có van cơ học (Hình 10.63): Van cơ học hoạt động để điều chỉnh áp suất thủy lực của phanh các bánh sau bên phải và bên trái. Van cơ học được sử dụng khi có đường ống chéo."}},{"id":"s1702","kind":"figure","lesson":"10.3.5","title":"Hình 10.63. Van điện từ 3-vị trí có van cơ học","text":"Hình 10.63. Van điện từ 3-vị trí có van cơ học","pages":[95],"figure":{"number":"10.63","caption":"Hình 10.63. Van điện từ 3-vị trí có van cơ học"}},{"id":"s1703","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Van điện từ 2-vị trí có van tăng áp suất (Hình 10.62): Van tăng áp suất được bố trí trên mạch thủy lực dẫn đến các bánh sau. Trong kết cấu này, van tăng áp suất vận hành theo nguyên lý cơ - thủy lực, hoạt động cùng van điện từ của bánh sau nhằm điều tiết áp suất dòng dầu cấp đến các cơ cấu phanh ở cầu sau.","pages":[95]},{"id":"s1704","kind":"figure","lesson":"10.3.5","title":"Hình 10.64. Cảm biến tốc độ bánh xe","text":"Hình 10.64. Cảm biến tốc độ bánh xe","pages":[96],"figure":{"number":"10.64","caption":"Hình 10.64. Cảm biến tốc độ bánh xe"}},{"id":"s1705","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Đồng hồ táp lô: Đèn báo của ABS bật sáng khi ECU phát hiện thấy trục trặc ở ABS hoặc của hệ thống phanh, đèn này bật sáng để báo cho người lái biết. Đèn báo hệ thống phanh bật sáng đồng thời với đèn báo của ABS để báo cho người lái biết rằng có trục trặc ở hệ thống. Bình thường, đèn báo này không sáng lên do tín hiệu của ECU truyền đến đồng hồ táp lô hoặc rơ le điều khiển ABS. Nếu ECU bị hỏng và không có tín hiệu, đèn báo của ABS, đèn báo hệ thống phanh, đèn báo ngắt TRC (ở các xe có trang bị TRC), và đèn báo VSC (ở các xe có trang bị VSC) luôn bật sáng. Công tắc đèn phanh: Công tắc này phát hiện bàn đạp phanh đã được đạp xuống và truyền tín hiệu đến ECU. Cảm biến tốc độ: Cảm biến tốc độ phát hiện tốc độ của từng bánh xe và truyền tín hiệu đến ECU điều khiển trượt. Cảm biến tốc độ bánh xe có hai loại là cảm biến điện từ và cảm biến Hall.","pages":[96]},{"id":"s1706","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Trong đó, cảm biến điện từ được sử dụng phổ biến hơn. Tùy theo cách điều khiển khác nhau, các cảm biến tốc độ bánh xe thường được gắn ở mỗi bánh xe để đo riêng rẽ từng bánh hoặc được gắn ở vỏ bọc của cầu chủ động, đo tốc độ trung bình của hai bánh xe dựa vào tốc độ của bánh răng vành chậu. Nguyên lý hoạt động của ABS: Các cảm biến tốc độ bánh xe (Hình 10.64) nhận biết tốc độ góc của các bánh xe và gửi tín hiệu về ECU. Tùy loại cảm biến, tín hiệu có thể là tín hiệu điện áp xoay chiều hoặc tín hiệu số. ECU theo dõi tình trạng các bánh xe bằng cách tính tốc độ xe và sự thay đổi tốc độ bánh xe, xác định mức trượt dựa trên tốc độ các bánh xe.","pages":[96]},{"id":"s1707","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Khi phanh gấp hay phanh trên đường ướt, trơn trượt có hệ số bám thấp, ECU điều khiển bộ chấp hành thủy lực cung cấp áp suất dầu tối ưu cho mỗi xi-lanh phanh bánh xe theo các chế độ tăng áp, giữ áp hay giảm áp để duy trì độ trượt nằm trong giới hạn tốt nhất, tránh bị hãm cứng bánh xe khi phanh. 1. Rô to cảm biến; 2. Cuộn dây * Tạo áp lực phanh - tăng áp Ứng với lúc người lái tác dụng lực lên bàn đạp phanh, lúc này bánh xe đang quay nên tín hiệu điện áp do cảm biến tạo ra gửi về thiết bị điều khiển điện tử là lớn nhất (Hình 10.65). Tương ứng với nó, thông tin từ thiết bị điều khiển điện tử gửi tới thiết bị thủy lực bằng không, cho nên van điện từ không làm việc, lò xo của van đẩy","pages":[96]},{"id":"s1708","kind":"figure","lesson":"10.3.5","title":"Hình 10.65. Sơ đồ tạo áp lực phanh 1. Van an toàn; 2. Bơm khứ hồi; 3. Van giảm áp; 4. Thiết bị điều khiển điện tử; 5. Thiết","text":"Hình 10.65. Sơ đồ tạo áp lực phanh 1. Van an toàn; 2. Bơm khứ hồi; 3. Van giảm áp; 4. Thiết bị điều khiển điện tử; 5. Thiết","pages":[97],"figure":{"number":"10.65","caption":"Hình 10.65. Sơ đồ tạo áp lực phanh 1. Van an toàn; 2. Bơm khứ hồi; 3. Van giảm áp; 4. Thiết bị điều khiển điện tử; 5. Thiết"}},{"id":"s1709","kind":"figure","lesson":"10.3.5","title":"Hình 10.66. Sơ đồ giữ áp lực phanh 1. Cảm biến số vòng; 2. Pít-tông; 3. Thiết bị điều khiển điện tử","text":"Hình 10.66. Sơ đồ giữ áp lực phanh 1. Cảm biến số vòng; 2. Pít-tông; 3. Thiết bị điều khiển điện tử","pages":[97],"figure":{"number":"10.66","caption":"Hình 10.66. Sơ đồ giữ áp lực phanh 1. Cảm biến số vòng; 2. Pít-tông; 3. Thiết bị điều khiển điện tử"}},{"id":"s1710","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"cho pít-tông xuống điểm thấp nhất. Khi người lái đạp phanh, xi-lanh chính làm việc tạo ra áp lực phanh theo đường ống dẫn qua pít-tông tới xi-lanh bánh xe để thực hiện quá trình phanh. * Giữ áp lực phanh – giữ áp Trường hợp này tương tự như khi rà phanh (quá trình phanh bánh xe xảy ra để giảm tốc độ cho xe nhưng bánh xe chưa bị bó cứng) (Hình 10.66). Lúc đó, số vòng quay của bánh xe giảm nên tín hiệu điện áp từ cảm biến gửi tới thiết bị điều khiển điện tử giảm. Tương ứng, thông tin từ thiết bị điều khiển điện tử gửi tới thiết bị điều khiển thủy lực ở mức dòng điện khác không. Van điện từ làm việc tạo ra sức hút pít-tông đi lên, lò xo hồi vị bị nén lại. (tùy thuộc vào giá trị dòng điện nhỏ hay lớn mà sự dịch chuyển của pít-tông lên ít hay nhiều).","pages":[97]},{"id":"s1711","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Đường dẫn dầu phanh đến xi-lanh bánh xe bị ngắt cho nên áp suất dầu trong dẫn động phanh tới xi-lanh bánh xe không còn tăng nữa mà giữ nguyên ở một trị số nào đó. * Trả áp lực phanh - Giảm áp","pages":[97]},{"id":"s1712","kind":"figure","lesson":"10.3.5","title":"Hình 10.67. Sơ đồ trả áp lực phanh 1. Pít-tông; 2. Bơm khứ hồi; 3. Van giảm áp; 4. Đường dầu về; 5. Thiết bị điều khiển điện tử","text":"Hình 10.67. Sơ đồ trả áp lực phanh 1. Pít-tông; 2. Bơm khứ hồi; 3. Van giảm áp; 4. Đường dầu về; 5. Thiết bị điều khiển điện tử","pages":[98],"figure":{"number":"10.67","caption":"Hình 10.67. Sơ đồ trả áp lực phanh 1. Pít-tông; 2. Bơm khứ hồi; 3. Van giảm áp; 4. Đường dầu về; 5. Thiết bị điều khiển điện tử"}},{"id":"s1713","kind":"figure","lesson":"10.3.5","title":"Hình 10.68. Sơ đồ ABS có bốn kênh điều khiển Loại này thường được sử dụng cho xe FF (Động cơ đặt trước, dẫn động cầu trước) có đường phanh kiểu chữ X (đường chéo). Các bánh xe trước được điều khiển độc lập và điều khiển bánh xe sau thường tuân theo nguyên tắc chọn giá trị thấp nhất (select-low logic) để ổn định xe trong khi hệ thống ABS hoạt động.","text":"Hình 10.68. Sơ đồ ABS có bốn kênh điều khiển Loại này thường được sử dụng cho xe FF (Động cơ đặt trước, dẫn động cầu trước) có đường phanh kiểu chữ X (đường chéo). Các bánh xe trước được điều khiển độc lập và điều khiển bánh xe sau thường tuân theo nguyên tắc chọn giá trị thấp nhất (select-low logic) để ổn định xe trong khi hệ thống ABS hoạt động.","pages":[98],"figure":{"number":"10.68","caption":"Hình 10.68. Sơ đồ ABS có bốn kênh điều khiển Loại này thường được sử dụng cho xe FF (Động cơ đặt trước, dẫn động cầu trước) có đường phanh kiểu chữ X (đường chéo). Các bánh xe trước được điều khiển độc lập và điều khiển bánh xe sau thường tuân theo nguyên tắc chọn giá trị thấp nhất (select-low logic) để ổn định xe trong khi hệ thống ABS hoạt động."}},{"id":"s1714","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Ứng với lúc bánh xe khi phanh bị bó cứng (Hình 10.67), tín hiệu điện áp từ cảm biến gửi về thiết bị điều khiển điện tử bằng không. Tương ứng, thông tin từ thiết bị điều khiển điện tử gửi tới thiết bị điều khiển thủy lực ở mức dòng điện cực đại. Van điện từ làm việc tạo ra sức hút lớn nhất, hút cho pít-tông lên tới điểm cao nhất. Đường dẫn dầu phanh từ xi-lanh chính tới bị ngắt nhưng lại được nối thông với van giảm áp và bơm khứ hồi của thiết bị điều khiển thủy lực. Lúc này, bơm khứ hồi làm việc cùng với áp suất của dầu phanh để mở van một chiều ở bơm khứ hồi, giúp cho áp suất giảm nhanh chóng. Vì thế, bánh xe không còn bó cứng nữa mặc dù người lái vẫn thực hiện quá trình phanh.","pages":[98]},{"id":"s1715","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Một số dạng sơ đồ bố trí hệ thống ABS trên xe hiện nay: - Bốn kênh điều khiển (Hình 10.68): Loại bốn kênh điều khiển này bao gồm bốn van điều chỉnh làm việc độc lập do vậy các bánh xe được tự động chống hãm cứng riêng rẽ, nên hiệu quả phanh cao, đảm bảo tính dẫn hướng, điều khiển xe khi đi vào đường xấu và quay vòng. - Ba kênh điều khiển (Hình 10.69): Hệ thống sử dụng ba cảm biến và ba van điều chỉnh. Trong cấu hình phổ biến nhất, hai bánh xe trước được giám sát và điều khiển hoàn toàn độc lập (sử dụng 2 van và 2 cảm biến), trong khi các bánh xe sau được điều khiển chung thông qua một kênh (sử dụng 1 van và 1 cảm biến tốc độ duy","pages":[98]},{"id":"s1716","kind":"figure","lesson":"10.3.5","title":"Hình 10.69. Sơ đồ ABS ba kênh điều khiển - Hai kênh điều khiển (Hình 10.70): Ở loại sơ đồ này, hệ thống sử dụng hai hoặc ba cảm biến nhưng chỉ có hai van điều chỉnh (chia thành hai mạch điều khiển độc lập, thường là chéo nhau hoặc chia theo cầu trước/sau). Tín hiệu tốc độ được truyền về bộ xử lý trung tâm và hệ thống sẽ tự động điều tiết áp suất dựa trên việc nhận diện bánh xe nào có nguy cơ bó cứng trước. So với hệ thống phanh cơ sở, cấu hình ABS hai kênh giúp cải thiện đáng kể khả năng kiểm soát trượt, tuy nhiên hiệu quả phanh tối ưu vẫn phụ thuộc nhiều vào cách bố trí mạch điều khiển và điều kiện thực tế của mặt đường.","text":"Hình 10.69. Sơ đồ ABS ba kênh điều khiển - Hai kênh điều khiển (Hình 10.70): Ở loại sơ đồ này, hệ thống sử dụng hai hoặc ba cảm biến nhưng chỉ có hai van điều chỉnh (chia thành hai mạch điều khiển độc lập, thường là chéo nhau hoặc chia theo cầu trước/sau). Tín hiệu tốc độ được truyền về bộ xử lý trung tâm và hệ thống sẽ tự động điều tiết áp suất dựa trên việc nhận diện bánh xe nào có nguy cơ bó cứng trước. So với hệ thống phanh cơ sở, cấu hình ABS hai kênh giúp cải thiện đáng kể khả năng kiểm soát trượt, tuy nhiên hiệu quả phanh tối ưu vẫn phụ thuộc nhiều vào cách bố trí mạch điều khiển và điều kiện thực tế của mặt đường.","pages":[99],"figure":{"number":"10.69","caption":"Hình 10.69. Sơ đồ ABS ba kênh điều khiển - Hai kênh điều khiển (Hình 10.70): Ở loại sơ đồ này, hệ thống sử dụng hai hoặc ba cảm biến nhưng chỉ có hai van điều chỉnh (chia thành hai mạch điều khiển độc lập, thường là chéo nhau hoặc chia theo cầu trước/sau). Tín hiệu tốc độ được truyền về bộ xử lý trung tâm và hệ thống sẽ tự động điều tiết áp suất dựa trên việc nhận diện bánh xe nào có nguy cơ bó cứng trước. So với hệ thống phanh cơ sở, cấu hình ABS hai kênh giúp cải thiện đáng kể khả năng kiểm soát trượt, tuy nhiên hiệu quả phanh tối ưu vẫn phụ thuộc nhiều vào cách bố trí mạch điều khiển và điều kiện thực tế của mặt đường."}},{"id":"s1717","kind":"figure","lesson":"10.3.5","title":"Hình 10.70. Sơ đồ ABS hai kênh điều khiển - Một kênh điều khiển (Hình 10.71): loại này dùng trên xe có hệ thống đường phanh kiểu chữ H, chỉ điều khiển áp suất phanh các bánh xe sau bằng một cảm biến tốc độ lắp trên bộ vi sai sau. Khi phanh gấp, các bánh xe trước vẫn bị khóa cứng, xe mất ổn định lái và quãng đường dừng trên bề mặt đường có hệ số bám thấp tăng lên. Hệ thống này giúp xe dừng thẳng.","text":"Hình 10.70. Sơ đồ ABS hai kênh điều khiển - Một kênh điều khiển (Hình 10.71): loại này dùng trên xe có hệ thống đường phanh kiểu chữ H, chỉ điều khiển áp suất phanh các bánh xe sau bằng một cảm biến tốc độ lắp trên bộ vi sai sau. Khi phanh gấp, các bánh xe trước vẫn bị khóa cứng, xe mất ổn định lái và quãng đường dừng trên bề mặt đường có hệ số bám thấp tăng lên. Hệ thống này giúp xe dừng thẳng.","pages":[99],"figure":{"number":"10.70","caption":"Hình 10.70. Sơ đồ ABS hai kênh điều khiển - Một kênh điều khiển (Hình 10.71): loại này dùng trên xe có hệ thống đường phanh kiểu chữ H, chỉ điều khiển áp suất phanh các bánh xe sau bằng một cảm biến tốc độ lắp trên bộ vi sai sau. Khi phanh gấp, các bánh xe trước vẫn bị khóa cứng, xe mất ổn định lái và quãng đường dừng trên bề mặt đường có hệ số bám thấp tăng lên. Hệ thống này giúp xe dừng thẳng."}},{"id":"s1718","kind":"figure","lesson":"10.3.5","title":"Hình 10.71. Sơ đồ ABS một kênh điều khiển ABS trên hệ thống phanh dẫn động khí nén Hình 10.72 và Hình 10.73 thể hiện sơ đồ một cơ cấu chấp hành của hệ thống phanh dẫn động khí nén có trang bị hệ thống chống hãm cứng bánh xe (ABS). Cơ cấu chấp hành có ba cửa: A, B, C và sáu van: I, II, III, IV, V, VI.","text":"Hình 10.71. Sơ đồ ABS một kênh điều khiển ABS trên hệ thống phanh dẫn động khí nén Hình 10.72 và Hình 10.73 thể hiện sơ đồ một cơ cấu chấp hành của hệ thống phanh dẫn động khí nén có trang bị hệ thống chống hãm cứng bánh xe (ABS). Cơ cấu chấp hành có ba cửa: A, B, C và sáu van: I, II, III, IV, V, VI.","pages":[99],"figure":{"number":"10.71","caption":"Hình 10.71. Sơ đồ ABS một kênh điều khiển ABS trên hệ thống phanh dẫn động khí nén Hình 10.72 và Hình 10.73 thể hiện sơ đồ một cơ cấu chấp hành của hệ thống phanh dẫn động khí nén có trang bị hệ thống chống hãm cứng bánh xe (ABS). Cơ cấu chấp hành có ba cửa: A, B, C và sáu van: I, II, III, IV, V, VI."}},{"id":"s1719","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"nhất, ví dụ: cảm biến có thể được bố trí trên vành răng vi sai). Nhược điểm của sơ đồ này là có thể xảy ra hiện tượng trượt lết ở một trong hai bánh xe phía trước khi xe phanh trên bề mặt đường có hệ số bám khác nhau giữa hai bên.","pages":[99]},{"id":"s1720","kind":"figure","lesson":"10.3.5","title":"Hình 10.72. ABS ở dẫn động phanh khí nén (chế độ tăng áp) 1. Van phân phối; 2. Bình khí; 3. Bầu phanh; 4, 7. Cuộn dây điện từ; 5, 8. Lõi van; 6. ECU.","text":"Hình 10.72. ABS ở dẫn động phanh khí nén (chế độ tăng áp) 1. Van phân phối; 2. Bình khí; 3. Bầu phanh; 4, 7. Cuộn dây điện từ; 5, 8. Lõi van; 6. ECU.","pages":[100],"figure":{"number":"10.72","caption":"Hình 10.72. ABS ở dẫn động phanh khí nén (chế độ tăng áp) 1. Van phân phối; 2. Bình khí; 3. Bầu phanh; 4, 7. Cuộn dây điện từ; 5, 8. Lõi van; 6. ECU."}},{"id":"s1721","kind":"figure","lesson":"10.3.5","title":"Hình 10.73. Chế độ giữ áp và giảm áp","text":"Hình 10.73. Chế độ giữ áp và giảm áp","pages":[100],"figure":{"number":"10.73","caption":"Hình 10.73. Chế độ giữ áp và giảm áp"}},{"id":"s1722","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Cửa A nối với van phân phối (1). Cửa B nối với bầu phanh (3). Cửa C thông với khí trời. Các van I và II đóng mở do áp suất phanh. Các van III, IV đóng mở nhờ lò xo và cuộn dây điện từ (7). Các van V, VI đóng mở nhờ lò xo và cuộn dây điện từ (4). Các cuộn dây điện từ (7) và (4) được cung cấp dòng điện từ ECU (6). Cơ cấu chấp hành của hệ thống này cũng có ba chế độ: tăng áp, giữ áp và giảm áp. Ở chế độ tăng áp (Hình 10.72): Cuộn dây (7) không được ECU cấp dòng, lò xo đẩy lõi (8) đi lên, đóng van III và mở van IV. Cuộn dây (4) cũng không được ECU cấp dòng, lò xo đẩy lõi (5) đi xuống, mở van V và đóng van VI. a) Chế độ giữ áp; b) Chế độ giảm áp 1. Van phân phối; 2. Bình khí; 3. Bầu phanh; 4, 7. Cuộn dây điện từ; 5, 8. Lõi van; 6. ECU.","pages":[100]},{"id":"s1723","kind":"figure","lesson":"10.3.5","title":"Hình 10.74. Hệ thống phanh EBD EBD là sự mở rộng chức năng của ABS, hoạt động song song với hệ thống chống bó cứng bánh xe để điều khiển độc lập áp suất dầu phanh cho từng bánh trước - sau.","text":"Hình 10.74. Hệ thống phanh EBD EBD là sự mở rộng chức năng của ABS, hoạt động song song với hệ thống chống bó cứng bánh xe để điều khiển độc lập áp suất dầu phanh cho từng bánh trước - sau.","pages":[101],"figure":{"number":"10.74","caption":"Hình 10.74. Hệ thống phanh EBD EBD là sự mở rộng chức năng của ABS, hoạt động song song với hệ thống chống bó cứng bánh xe để điều khiển độc lập áp suất dầu phanh cho từng bánh trước - sau."}},{"id":"s1724","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Khí nén từ bình khí (2) qua van phân phối (1) đi vào cửa A, đẩy vào phía dưới nắp van I. Còn phía trên nắp van I qua van IV thông với khoang C và thông với khí trời nên van I mở. Khí nén qua van I đến cửa B và đi đến bầu phanh (3). Đồng thời, khí nén đi qua van V đi đến phía dưới của nắp van II. Phía trên nắp van II thông với buồng C và thông với khí trời nên van II đóng. Như vậy, khí nén từ van phân phối (1) qua cơ cấu chấp hành đi đến bầu phanh. Ở chế độ giữ áp (Hình 10.73a). Cuộn dây (7) được ECU cấp dòng tạo từ trường hút lõi (8) đi xuống, mở van III, đóng van IV. Cuộn dây (4) không được ECU cấp dòng, lò xo đẩy lõi (5) đi xuống, mở van V và đóng van VI. Lúc này, khí nén qua van III đi lên phía trên nắp van I làm đóng van I do diện tích tiếp xúc với khí nén phía trên van I lớn hơn phía dưới. Lúc này, van II vẫn tiếp tục đóng.","pages":[101]},{"id":"s1725","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Do van I và II đều đóng nên khí nén ở cửa B giữ nguyên áp suất không đổi. Ở chế độ giảm áp (Hình 10.73b): Cuộn dây (7) được ECU cấp dòng tạo từ trường hút lõi (8) đi xuống, mở van III, đóng van IV. Cuộn dây (4) cũng được ECU cấp dòng, từ trường hút lõi (5) đi lên, mở van VI và đóng van V. Vì van III mở nên tương tự chế độ giữ áp, van I đóng. Do van VI mở nên phía dưới nắp van II thông với khoang C và thông với khí trời, van II mở ra. Khí nén từ cửa B thoát qua van II ra khí trời nên áp suất khí ở cửa B (tức của bầu phanh) giảm. b) Hệ thống phân phối lực phanh điện tử (Electronic Brake-force Distribution – EBD)","pages":[101]},{"id":"s1726","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Hệ thống EBD (Hình 10.74) có nhiệm vụ phân phối lực phanh tối ưu đến từng bánh xe dựa trên tải trọng, điều kiện mặt đường và tốc độ bánh xe, nhằm: - Giữ ổn định hướng chuyển động của ô tô khi phanh; - Rút ngắn quãng đường phanh; - Hạn chế hiện tượng bánh sau bị bó cứng khi tải trọng thay đổi hoặc khi phanh gấp; - Tăng hiệu quả sử dụng của hệ thống ABS. Hệ thống EBD gồm các bộ phận chính: - Cảm biến tốc độ bánh xe: thu tín hiệu tốc độ quay của từng bánh. - Bộ điều khiển điện tử (ECU): xử lý tín hiệu, so sánh tốc độ giữa các bánh, xác định tải trọng phân bố. - Cụm van điều khiển thủy lực (modulator): gồm các van điện từ điều khiển áp suất dầu đến từng bánh xe. - Đường ống thủy lực và cảm biến áp suất phanh: giúp điều chỉnh chính xác lực phanh.","pages":[102]},{"id":"s1727","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Nguyên lý làm việc: Phân phối lực phanh giữa các bánh trước và bánh sau Khi phanh trong lúc xe đang chạy tiến thẳng, sự chuyển tải trọng sẽ giảm tải trọng tác động lên các bánh sau. ECU điều khiển trượt xác định điều kiện này bằng các tín hiệu từ các cảm biến tốc độ, và điều khiển bộ chấp hành ABS để điều chỉnh tối ưu sự phân phối lực phanh đến các bánh sau. Chẳng hạn, mức tải trọng tác động lên các bánh sau trong khi phanh sẽ thay đổi tùy theo xe có mang tải hay không. Mức tải trọng tác động lên các bánh sau cũng thay đổi theo mức giảm tốc. Như vậy, sự phân phối lực phanh đến bánh sau được điều chỉnh tối ưu để sử dụng có hiệu quả lực phanh của các bánh sau theo những điều kiện này.","pages":[102]},{"id":"s1728","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Phân phối lực phanh giữa các bánh bên phải và bên trái khi xe quay vòng Khi xe phanh trong lúc quay vòng, tải trọng có xu hướng chuyển từ phía trong sang phía ngoài của quỹ đạo quay vòng. Do đó, tải trọng và khả năng tạo lực phanh của các bánh xe bên ngoài và bên trong vòng quay không giống nhau. ECU sử dụng tín hiệu từ các cảm biến tốc độ bánh xe và các tín hiệu liên quan đến trạng thái chuyển động của xe để điều khiển bộ chấp hành, điều chỉnh áp suất phanh phù hợp giữa các bánh xe.","pages":[102]},{"id":"s1729","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Việc phân phối lực phanh hợp lý giúp hạn chế hiện tượng bánh xe có tải trọng nhỏ bị trượt và góp phần duy trì ổn định hướng chuyển động khi phanh trong lúc quay vòng. c) Hệ thống hỗ trợ phanh khẩn cấp (Brake Assist – BA) Khi phanh khẩn cấp, những người chưa quen lái xe hoặc những người dễ hoảng loạn (dù đã quen lái xe) đôi khi không đạp bàn đạp phanh đủ mạnh để tận dụng tính năng của hệ thống phanh. Hệ thống hỗ trợ phanh khẩn cấp BA (Hình 10.75) sử dụng tín hiệu áp suất phanh hoặc tốc độ thay đổi của áp suất, kết hợp với các tín hiệu vận hành khác, để nhận biết tình huống phanh khẩn cấp và tăng cường","pages":[102]},{"id":"s1730","kind":"figure","lesson":"10.3.5","title":"Hình 10.75. Sơ đồ hệ thống BA Khi phanh khẩn cấp, những người chưa quen lái xe hoặc những người dễ hoảng loạn (dù đã quen lái xe) đôi khi không đạp bàn đạp phanh đủ mạnh để tận dụng tính năng của hệ thống phanh.","text":"Hình 10.75. Sơ đồ hệ thống BA Khi phanh khẩn cấp, những người chưa quen lái xe hoặc những người dễ hoảng loạn (dù đã quen lái xe) đôi khi không đạp bàn đạp phanh đủ mạnh để tận dụng tính năng của hệ thống phanh.","pages":[103],"figure":{"number":"10.75","caption":"Hình 10.75. Sơ đồ hệ thống BA Khi phanh khẩn cấp, những người chưa quen lái xe hoặc những người dễ hoảng loạn (dù đã quen lái xe) đôi khi không đạp bàn đạp phanh đủ mạnh để tận dụng tính năng của hệ thống phanh."}},{"id":"s1731","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"lực phanh theo thiết kế của hệ thống. Nhờ đó, máy vi tính dự kiến được ý muốn phanh khẩn cấp của người lái để tăng lực phanh, nhằm đạt được tính năng tối đa của hệ thống phanh. Hệ thống hỗ trợ phanh khẩn cấp BA (Hình 10.75) sử dụng tín hiệu áp suất phanh hoặc tốc độ thay đổi của áp suất, kết hợp với các tín hiệu vận hành khác, để nhận biết tình huống phanh khẩn cấp và tăng cường lực phanh theo thiết kế của hệ thống. Nhờ đó, máy vi tính dự kiến được ý muốn phanh khẩn cấp của người lái để tăng lực phanh, nhằm đạt được tính năng tối đa của hệ thống phanh. BA cũng đặt thời gian hỗ trợ và mức hỗ trợ để làm cho cảm giác về phanh càng tự nhiên càng tốt bằng cách điều chỉnh hỗ trợ theo yêu cầu như thể hiện trên đồ thị (Hình 10.75).","pages":[103]},{"id":"s1732","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Hoạt động: Khi ECU điều khiển trượt xác định rằng người lái đang phanh khẩn cấp, van điện từ chuyển mạch hỗ trợ phanh được đóng mạch, tạo thành một đường thông giữa xi-lanh chính và bình chứa, và chuyển dầu đến bơm (Hình 10.76). Sự kích hoạt này tạo ra một đường thông thủy lực, dẫn dầu từ xi-lanh chính qua bình chứa và đi thẳng vào cửa hút của bơm. Bơm lập tức hoạt động, gia áp dòng dầu và đẩy đến các cơ cấu phanh bánh xe để gia tăng lực hãm. Nhằm bảo vệ hệ thống, một van an toàn được thiết kế để tự động mở xả áp khi độ chênh lệch áp suất giữa xi-lanh bánh xe và xi-lanh chính vượt quá giới hạn thiết lập, giúp duy trì áp suất phanh ở mức an toàn. Bơm hút dầu và đẩy đến xi-lanh ở bánh xe. Van an toàn mở ra để bảo đảm rằng áp suất của xi-lanh ở bánh xe không vượt áp suất của xi-lanh chính quá một mức đã đặt trước để duy trì độ chênh áp suất này.","pages":[103]},{"id":"s1733","kind":"figure","lesson":"10.3.5","title":"Hình 10.76. Mạch thủy lực hệ thống phanh có BA d) Cảnh báo va chạm phía trước và phanh khẩn cấp tự động (Forward Collision Warning – FCW, Automatic Emergency Braking – AEB)","text":"Hình 10.76. Mạch thủy lực hệ thống phanh có BA d) Cảnh báo va chạm phía trước và phanh khẩn cấp tự động (Forward Collision Warning – FCW, Automatic Emergency Braking – AEB)","pages":[104],"figure":{"number":"10.76","caption":"Hình 10.76. Mạch thủy lực hệ thống phanh có BA d) Cảnh báo va chạm phía trước và phanh khẩn cấp tự động (Forward Collision Warning – FCW, Automatic Emergency Braking – AEB)"}},{"id":"s1734","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Các hệ thống phanh tự động có nhiệm vụ phát hiện nguy cơ va chạm và tự động kích hoạt phanh để giảm tốc hoặc dừng xe hoàn toàn, nhằm tránh hoặc giảm thiểu va chạm khi người lái không phản ứng kịp. FCW là chức năng sử dụng các cảm biến phía trước như radar, camera hoặc lidar để phát hiện nguy cơ va chạm và cảnh báo người lái. FCW không trực tiếp thực hiện phanh tự động. AEB là chức năng có khả năng tự động tác động lên hệ thống phanh khi phát hiện nguy cơ va chạm phía trước và người lái không phản ứng hoặc phản ứng không đủ. Tùy thiết kế, AEB có thể giảm tốc độ xe hoặc phanh mạnh để tránh hoặc giảm mức độ nghiêm trọng của va chạm. Hệ thống sử dụng cảm biến radar hoặc camera phía trước xe để đo khoảng cách và tốc độ tiếp cận vật cản. ECU phân tích dữ liệu và cảnh báo người lái bằng âm thanh hoặc hình ảnh (FCW).","pages":[104]},{"id":"s1735","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Nếu người lái không phản ứng, hệ thống tự động điều khiển van thủy lực hoặc mô-tơ điện để tạo áp suất phanh (AEB). Một số hệ thống có thể giảm tốc từng bánh để hỗ trợ ổn định hướng lái khi phanh gấp. Quá trình làm việc của hệ thống FCW – AEB gồm ba giai đoạn chính: - Phát hiện nguy cơ va chạm (FCW): + Radar và camera trước quét không gian phía trước xe.","pages":[104]},{"id":"s1736","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"+ ECU ADAS tính toán khoảng cách an toàn và thời gian va chạm dự kiến (TTC). + Khi TTC nhỏ hơn giá trị giới hạn, hệ thống phát cảnh báo âm thanh hoặc hình ảnh cho người lái. - Chuẩn bị phanh tự động (AEB – giai đoạn cảnh báo tăng cường): + Nếu người lái không phản ứng (không đạp phanh), ECU sẽ tăng áp suất sơ bộ trong hệ thống phanh, giúp phanh phản ứng nhanh hơn khi cần. - Phanh tự động khẩn cấp (AEB – giai đoạn can thiệp): + Khi xác định va chạm là không thể tránh khỏi, ECU ra lệnh cho ABS/ESP điều khiển van điện từ để tạo áp suất phanh tự động. + Nếu người lái bắt đầu đạp phanh, hệ thống sẽ tăng lực phanh hỗ trợ (Brake Assist) để dừng xe nhanh nhất.","pages":[105]},{"id":"s1737","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Mối liên hệ với các hệ thống khác - ABS / EBD / BA: AEB sử dụng trực tiếp cụm điều khiển phanh ABS để tạo áp suất phanh tự động. - TRC / VSC (ESP): Dữ liệu từ cảm biến gia tốc và cảm biến 3 phương được dùng để xác định hướng chuyển động và ổn định khi phanh tự động. - ACC (Adaptive Cruise Control): AEB có thể sử dụng chung hoặc khai thác dữ liệu từ radar, camera và các cảm biến được sử dụng cho ACC tùy kiến trúc hệ thống. - CCS (Cruise Control System): CCS chỉ điều khiển bướm ga; AEB mở rộng chức năng này để tự điều khiển phanh khi phát hiện nguy cơ va chạm. Ứng dụng thực tế Hiện nay, các hệ thống AEB và FCW được trang bị phổ biến trên các dòng xe có gói ADAS (Advanced Driver Assistance System) (Bảng 10.1): Bảng 10.1.","pages":[105]},{"id":"s1738","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Tên gọi hệ thống ADAS trên một số dòng xe Hãng xe Gói công nghệ Hệ thống AEB/FCW tương ứng Toyota Toyota Safety Sense Pre-Collision System (PCS) Honda Honda Sensing Collision Mitigation Braking System (CMBS) Mazda i-Activsense Smart City Brake Support (SCBS) Hyundai Kia SmartSense Forward Collision-Avoidance Assist (FCA) VinFast VinFast ADAS AEB + FCW tích hợp radar – camera e) Phanh tay điện tử Hệ thống phanh tay điện tử (EPB) là hệ thống điều khiển phanh dừng bằng điện. Hệ thống thay thế cơ cấu điều khiển phanh dừng bằng cần kéo và cáp cơ khí bằng công tắc điện, ECU và cơ cấu chấp hành điện. Tùy kết cấu xe, cơ cấu chấp hành có thể tác động trực tiếp lên cụm phanh đĩa phía sau hoặc sử dụng một cơ cấu phanh dừng riêng.","pages":[105]},{"id":"s1739","kind":"figure","lesson":"10.3.5","title":"Hình 10.77. Sơ đồ của phanh tay điện tử Về cơ bản, EPB vẫn đảm nhận các chức năng như phanh tay truyền thống: giữ cố định xe tại chỗ khi đỗ, ngăn xe lăn trôi trên dốc hoặc khi đậu xe.","text":"Hình 10.77. Sơ đồ của phanh tay điện tử Về cơ bản, EPB vẫn đảm nhận các chức năng như phanh tay truyền thống: giữ cố định xe tại chỗ khi đỗ, ngăn xe lăn trôi trên dốc hoặc khi đậu xe.","pages":[106],"figure":{"number":"10.77","caption":"Hình 10.77. Sơ đồ của phanh tay điện tử Về cơ bản, EPB vẫn đảm nhận các chức năng như phanh tay truyền thống: giữ cố định xe tại chỗ khi đỗ, ngăn xe lăn trôi trên dốc hoặc khi đậu xe."}},{"id":"s1740","kind":"figure","lesson":"10.3.5","title":"Hình 10.78. Cơ cấu chấp hành phanh tay điện tử 1. Pít-tông phanh; 2. Gờ định vị má phanh; 3,7. Càng phanh; 4. Đường ống dẫn dầu","text":"Hình 10.78. Cơ cấu chấp hành phanh tay điện tử 1. Pít-tông phanh; 2. Gờ định vị má phanh; 3,7. Càng phanh; 4. Đường ống dẫn dầu","pages":[106],"figure":{"number":"10.78","caption":"Hình 10.78. Cơ cấu chấp hành phanh tay điện tử 1. Pít-tông phanh; 2. Gờ định vị má phanh; 3,7. Càng phanh; 4. Đường ống dẫn dầu"}},{"id":"s1741","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Hệ thống EPB hoạt động nhờ sự can thiệp của bộ điều khiển điện tử phanh (ECU), cho phép cơ cấu chấp hành thực hiện nhiều chức năng như: giữ xe khi đỗ, hỗ trợ khởi hành ngang dốc và hỗ trợ chế độ Start–Stop. Hệ thống EPB (Hình 10.77) gồm các bộ phận chính: - Bộ điều khiển hệ thống phanh tay điện tử. - Cơ cấu chấp hành phanh tay điện tử. - Công tắc phanh tay. - Đèn hiển thị trên bảng đồng hồ. Các bộ phận hỗ trợ: bộ điều khiển phanh ABS, cảm biến bàn đạp chân phanh, cảm biến vị trí bàn đạp ly hợp, công tắc AUTOHOLD. phanh; 5. Má phanh; 6. Vít xả khí.","pages":[106]},{"id":"s1742","kind":"figure","lesson":"10.3.5","title":"Hình 10.79. Mô-tơ chấp hành 1. Pít-tông phanh; 2. Mô-tơ phanh; 3. Đai dẫn động; 4. Hệ thống bánh răng.","text":"Hình 10.79. Mô-tơ chấp hành 1. Pít-tông phanh; 2. Mô-tơ phanh; 3. Đai dẫn động; 4. Hệ thống bánh răng.","pages":[107],"figure":{"number":"10.79","caption":"Hình 10.79. Mô-tơ chấp hành 1. Pít-tông phanh; 2. Mô-tơ phanh; 3. Đai dẫn động; 4. Hệ thống bánh răng."}},{"id":"s1743","kind":"figure","lesson":"10.3.5","title":"Hình 10.80. Mặt cắt mô-tơ chấp hành Trục vít – đai ốc đẩy là chi tiết chính để chuyển đổi chuyển động quay thành chuyển động tịnh tiến. Trục vít sẽ được dẫn động trực tiếp từ trục đầu ra của hệ thống bánh răng đĩa cuốn. Tùy thuộc vào chiều quay của trục vít, đai ốc đẩy di chuyển tiến tới hay lùi lại; chuyển động này được hộp điều khiển phanh tay điện tử theo dõi và điều khiển.","text":"Hình 10.80. Mặt cắt mô-tơ chấp hành Trục vít – đai ốc đẩy là chi tiết chính để chuyển đổi chuyển động quay thành chuyển động tịnh tiến. Trục vít sẽ được dẫn động trực tiếp từ trục đầu ra của hệ thống bánh răng đĩa cuốn. Tùy thuộc vào chiều quay của trục vít, đai ốc đẩy di chuyển tiến tới hay lùi lại; chuyển động này được hộp điều khiển phanh tay điện tử theo dõi và điều khiển.","pages":[107],"figure":{"number":"10.80","caption":"Hình 10.80. Mặt cắt mô-tơ chấp hành Trục vít – đai ốc đẩy là chi tiết chính để chuyển đổi chuyển động quay thành chuyển động tịnh tiến. Trục vít sẽ được dẫn động trực tiếp từ trục đầu ra của hệ thống bánh răng đĩa cuốn. Tùy thuộc vào chiều quay của trục vít, đai ốc đẩy di chuyển tiến tới hay lùi lại; chuyển động này được hộp điều khiển phanh tay điện tử theo dõi và điều khiển."}},{"id":"s1744","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Cơ cấu chấp hành phanh (Hình 10.78) là bộ phận dẫn động giúp ép má phanh vào đĩa phanh. Cơ cấu gồm các chi tiết như càng phanh, đĩa phanh, má phanh và mô-tơ phanh dừng. Khi xe đang di chuyển, cơ cấu phanh đĩa hoạt động nhờ áp suất dầu phanh để ép pít-tông phanh vào má phanh, giúp xe giảm tốc hoặc dừng lại. Khi xe được dừng đỗ, mô-tơ phanh dừng sẽ hoạt động, giữ má phanh ép vào đĩa phanh, giúp xe đứng yên an toàn trên đường. Mô-tơ phanh dừng (Hình 10.79 và Hình 10.80) được cấu tạo là một cơ cấu trục vít - đai ốc chuyển động tịnh tiến được điều khiển thông qua hệ thống bánh răng giảm tốc biến đổi chuyển động quay của mô-tơ điện thành chuyển động tịnh tiến của pít-tông.","pages":[107]},{"id":"s1745","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Đai ốc đẩy bị hạn chế chuyển động dọc trục khi được lắp dọc theo pít-tông phanh và nhờ cấu tạo đặc biệt của đai ốc và thành pít-tông phanh giúp hạn chế chuyển động xoắn của đai ốc khi trục vít quay. * Phương thức điều khiển phanh tay điện tử - Tín hiệu vị trí bàn đạp ly hợp hoặc công tắc tay số P/N Tín hiệu từ vị trí bàn đạp ly hợp (Hình 10.81) hoặc công tắc tay số P/N được hộp điều khiển nhận dạng nhằm mục đích xác định điều kiện xe đang vận hành hay","pages":[107]},{"id":"s1746","kind":"figure","lesson":"10.3.5","title":"Hình 10.81. Vị trí cảm biến ly hợp + Cảm biến Hall 2 cung cấp tín hiệu tương tự phản ánh vị trí bàn đạp ly hợp. ECU sử dụng tín hiệu này để xác định chính xác vị trí bàn đạp và tính toán thời điểm nhả phanh dừng phù hợp.","text":"Hình 10.81. Vị trí cảm biến ly hợp + Cảm biến Hall 2 cung cấp tín hiệu tương tự phản ánh vị trí bàn đạp ly hợp. ECU sử dụng tín hiệu này để xác định chính xác vị trí bàn đạp và tính toán thời điểm nhả phanh dừng phù hợp.","pages":[108],"figure":{"number":"10.81","caption":"Hình 10.81. Vị trí cảm biến ly hợp + Cảm biến Hall 2 cung cấp tín hiệu tương tự phản ánh vị trí bàn đạp ly hợp. ECU sử dụng tín hiệu này để xác định chính xác vị trí bàn đạp và tính toán thời điểm nhả phanh dừng phù hợp."}},{"id":"s1747","kind":"figure","lesson":"10.3.5","title":"Hình 10.82. Công tắc và đèn báo - Hộp điều khiển phanh tay điện tử","text":"Hình 10.82. Công tắc và đèn báo - Hộp điều khiển phanh tay điện tử","pages":[108],"figure":{"number":"10.82","caption":"Hình 10.82. Công tắc và đèn báo - Hộp điều khiển phanh tay điện tử"}},{"id":"s1748","kind":"figure","lesson":"10.3.5","title":"Hình 10.83. ECU điều khiển phanh tay","text":"Hình 10.83. ECU điều khiển phanh tay","pages":[108],"figure":{"number":"10.83","caption":"Hình 10.83. ECU điều khiển phanh tay"}},{"id":"s1749","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"đứng yên từ đó đưa ra tín hiệu điều khiển cho phù hợp. Khi người lái về số P/N hay nhấn bàn đạp ly hợp, tín hiệu số (mức 0 hoặc mức 1) sẽ được gửi về hộp điều khiển. Để đáp ứng nhiều yêu cầu khác nhau, cảm biến vị trí bàn đạp ly hợp có một thanh đẩy tích hợp nam châm vĩnh cửu di chuyển trong xi-lanh chính ly hợp. Cảm biến vị trí bàn đạp ly hợp gồm ba cảm biến Hall được tích hợp để cảm nhận sự di chuyển của nam châm vĩnh cửu, nhờ đó xác định được từng vị trí bàn đạp ly hợp. + Cảm biến Hall 1 gửi tín hiệu digital (mức 0 hoặc mức 1) về hộp điều khiển động cơ. Nhờ đó, hộp điều khiển động cơ xác định được người lái muốn nhấn bàn đạp ly hợp.","pages":[108]},{"id":"s1750","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Tín hiệu này được sử dụng để điều khiển tắt hệ thống Cruise control. + Cảm biến Hall 3 sẽ gửi tín hiệu digital đến mạch nguồn của xe để xác định bàn đạp ly hợp đã được nhấn và chỉ khi đó động cơ được khởi động. - Tín hiệu công tắc điều khiển và đèn báo","pages":[108]},{"id":"s1751","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Nút nhấn điều khiển phanh tay điện tử và nút nhấn Auto Hold thể hiện trên Hình 10.82. Tín hiệu từ công tắc EPB và các cảm biến liên quan được ECU xử lý để điều khiển mô-tơ chấp hành, tạo lực hãm và duy trì trạng thái phanh dừng theo yêu cầu. Nút nhấn phanh tay điện tử vẫn có thể được nhấn khi chìa khóa xe tắt. Khi đó, đèn báo sáng ở cả nút nhấn và trên bảng đồng hồ của xe; tín hiệu từ nút nhấn được đưa đến hộp điều khiển phanh tay điện tử, hộp điều khiển kiểm tra chìa khóa xe đã được bật chưa và đưa ra chế độ hoạt động tối ưu nhất. Điều này nhằm ngăn trẻ em nhả phanh khi không có người lái; khi đó, các đèn báo chỉ sáng trong 30 giây rồi tắt. Phanh tay điện tử có thể được nhả tự động khi người lái thắt dây an toàn, đóng cửa, khởi động động cơ và đạp bàn đạp ga.","pages":[109]},{"id":"s1752","kind":"pdf","lesson":"10.3.5","title":"Hệ thống phanh · Hệ thống phanh có điều khiển điện tử","text":"Thời điểm nhả sẽ được hộp điều khiển phanh tính toán dựa vào hai điều kiện: độ dốc mặt đường và mô men xoắn của động cơ. Khi đó đèn báo sẽ tắt. Bộ điều khiển điện tử EPB (ECU): Tiếp nhận tín hiệu điều khiển từ người lái và các cảm biến, tính toán và điều khiển mô-tơ phanh tay. ECU EPB có thể là một hộp điều khiển độc lập hoặc tích hợp chung với hộp điều khiển phanh ABS/ESC trên xe. Hộp điều khiển (Hình 10.83) được đặt dưới bảng điều khiển trung tâm. Tất cả việc điều khiển hoạt động và chẩn đoán các lỗi xảy ra đều được thực hiện tại hộp điều khiển phanh tay điện tử. Hệ thống phanh tay điện tử có hai bộ xử lý là bộ điều khiển phanh tay điện tử và bộ điều khiển phanh ABS được giao tiếp với nhau thông qua mạng CAN. Tùy kiến trúc hệ thống, một số cảm biến có thể được tích hợp trong cụm điều khiển; các cảm biến khác có thể được bố trí riêng trên xe.","pages":[109]},{"id":"s1753","kind":"pdf","lesson":"11.1.1","title":"Hệ thống treo · Công dụng","text":"Hệ thống treo là bộ phận liên kết đàn hồi giữa bánh xe với khung hoặc thân xe, có nhiệm vụ tiếp nhận và truyền tải trọng, đồng thời hạn chế ảnh hưởng của các kích động từ mặt đường đến thân xe. Chương này trình bày công dụng, phân loại và cấu tạo của hệ thống treo; đặc điểm kết cấu của các bộ phận đàn hồi, bộ phận dẫn hướng và giảm chấn. Nội dung phân tích các dạng hệ thống treo phụ thuộc, hệ thống treo độc lập và các phương án kết cấu được sử dụng trên ô tô. 1.","pages":[110]},{"id":"s1754","kind":"pdf","lesson":"11.1.1","title":"Hệ thống treo · Công dụng","text":"Công dụng Hệ thống treo thực hiện liên kết đàn hồi giữa bánh xe và thân xe, đảm nhận các công dụng chính sau: - Giảm tải trọng động và tăng độ êm dịu: Tiếp nhận và hấp thụ các dao động thẳng đứng từ mặt đường truyền lên khung xe (thông qua bộ phận đàn hồi). - Dập tắt nhanh dao động: Biến đổi năng lượng dao động của thân xe thành nhiệt năng để triệt tiêu dao động kéo dài, giúp xe chuyển động êm dịu (thông qua bộ phận giảm chấn). - Truyền lực và duy trì quan hệ động học: Truyền toàn bộ lực dọc, lực ngang và mô-men giữa bánh xe với thân xe; đồng thời kiểm soát sự dịch chuyển tương đối hợp lý giữa bánh xe và khung vỏ (thông qua bộ phận dẫn hướng). - Tăng cường độ ổn định: Hạn chế sự nghiêng lệch giữa hai bánh trên cùng một trục, nâng cao tính an toàn và ổn định khi chuyển động; chức năng này do thanh ổn định ngang (thanh cân bằng) đảm nhiệm.","pages":[110]},{"id":"s1755","kind":"pdf","lesson":"11.1.2","title":"Hệ thống treo · Phân loại","text":"Như vậy, hệ thống treo có các bộ phận sau đây: - Bộ phận dẫn hướng; - Bộ phận đàn hồi; - Bộ phận giảm chấn; - Thanh cân bằng. 2. Phân loại a) Hệ thống treo phụ thuộc Hệ thống treo phụ thuộc là loại kết cấu trong đó hai bánh xe nằm trên cùng một cầu được nối cứng với nhau thông qua một dầm cầu (hay còn gọi là cầu cứng). Khi một bánh xe dao động lên hoặc xuống theo phương thẳng đứng (do tác động của mặt đường), chuyển động này sẽ truyền sang bánh xe bên kia. Vì vậy, dao động của hai bánh xe không độc lập mà luôn ảnh hưởng lẫn nhau. Kết cấu loại này đơn giản, chịu tải tốt, dễ chế tạo và bảo dưỡng. Tuy nhiên, khả năng êm dịu và ổn định động học thấp hơn các hệ thống treo hiện đại vì khi một bánh chịu dao động, bánh còn lại cũng bị ảnh hưởng. Hệ thống treo phụ thuộc thường được sử dụng ở cầu sau của xe tải, xe khách cỡ lớn, một số","pages":[110]},{"id":"s1756","kind":"pdf","lesson":"11.1.1","title":"Hệ thống treo · Công dụng","text":"xe bán tải và xe địa hình, là những loại xe đòi hỏi độ bền và khả năng chịu tải lớn. Một số xe sử dụng kết cấu này như KamAZ 5320, Ural-4320 (cầu sau), Hyundai Mighty (tải nhẹ) hoặc xe khách cỡ trung như Hyundai County. b) Hệ thống treo độc lập Ở hệ thống treo độc lập, mỗi bánh xe có bộ phận treo riêng biệt, được nối với khung xe hoặc thân xe bằng các cơ cấu đòn ngang, đòn dọc hoặc cơ cấu treo kiểu MacPherson, đòn kép (wishbone), v.v. Nhờ đó, mỗi bánh xe có thể dao động độc lập theo điều kiện mặt đường mà không ảnh hưởng đến bánh còn lại, qua đó nâng cao độ êm dịu, tăng khả năng bám đường và kiểm soát tốt động học bánh xe. Tuy nhiên, kết cấu phức tạp hơn, chi phí sản xuất và bảo dưỡng cao hơn so với treo phụ thuộc.","pages":[111]},{"id":"s1757","kind":"pdf","lesson":"11.1.1","title":"Hệ thống treo · Công dụng","text":"Hệ thống treo độc lập được sử dụng rộng rãi ở cầu trước xe con, xe khách hiện đại, các dòng xe cao cấp và thể thao, giúp nâng cao sự thoải mái và an toàn khi vận hành ở tốc độ cao. Ví dụ: MacPherson thường thấy trên Toyota Camry, Hyundai Elantra, VinFast VF5; trong khi hệ thống treo đòn kép hình thang áp dụng trên Honda Civic, Hyundai Santa Fe. c) Hệ thống treo điều khiển điện tử Đây là dạng hệ thống treo hiện đại nhất hiện nay, ứng dụng các cảm biến, bộ điều khiển trung tâm điện tử (ECU) để tự động điều chỉnh đặc tính đàn hồi (độ cứng/mềm của lò xo, khí nén, v.v.) và lực giảm chấn phù hợp với điều kiện vận hành thực tế, hành vi của người lái và trạng thái mặt đường, qua đó nâng cao rõ rệt độ êm dịu và khả năng kiểm soát thân xe, đồng thời đáp ứng linh hoạt yêu cầu của người lái và điều kiện mặt đường.","pages":[111]},{"id":"s1758","kind":"pdf","lesson":"11.1.1","title":"Hệ thống treo · Công dụng","text":"Hệ thống có thể tự động hoặc chủ động thay đổi chế độ (êm dịu – thể thao), luôn giữ xe ổn định, an toàn trong mọi tình huống (phanh gấp, quay vòng, tải nặng…). Hệ thống treo CDC (Continuous Damping Control) và Hydractive là các ví dụ điển hình, thường được trang bị trên xe sang, xe thể thao và SUV hiện đại. Các xe điển hình sử dụng hệ thống treo điều khiển điện tử gồm Mercedes-Benz S-Class (AIRMATIC), Audi A6 (CDC), Hyundai Genesis G80 (ECS). II. BỘ PHẬN DẪN HƯỚNG Bộ phận dẫn hướng có nhiệm vụ: - Truyền các lực dọc, ngang, mô-men giữa bánh xe (cầu xe) và khung xe; - Bảo đảm quan hệ động học giữa bánh xe và khung xe. Mỗi nhiệm vụ đặt ra các yêu cầu tương ứng đối với bộ phận dẫn hướng.","pages":[111]},{"id":"s1759","kind":"pdf","lesson":"11.1.1","title":"Hệ thống treo · Công dụng","text":"Nhiệm vụ truyền các lực dọc, ngang, mô-men giữa bánh xe (cầu xe) và khung xe được bảo đảm bằng kết cấu và kích thước của bộ phận dẫn hướng sao cho khi chịu các lực nói trên, bộ phận dẫn hướng phải đủ bền và đủ độ cứng vững. Nhiệm vụ bảo đảm quan hệ động học giữa bánh xe và khung xe đòi hỏi khi bánh xe dịch chuyển thẳng đứng không phát sinh dịch chuyển ngang, thay đổi góc nghiêng của mặt phẳng bánh xe hoặc góc lệch của trục bánh xe so với vị trí ban đầu. Nếu dịch chuyển ngang vượt quá biến dạng đàn hồi của lốp thì bánh xe sẽ bị trượt và lốp sẽ bị mòn. Góc lệch của trục bánh xe so với vị trí ban đầu sẽ tạo ra hiệu","pages":[111]},{"id":"s1760","kind":"figure","lesson":"11.2.1","title":"Hình 11.1. Lắp nhíp trên xe 1. Khung xe; 2. Giá đỡ sau; 3. Miếng trượt; 4. Cầu xe; 5. Bu lông quang nhíp; 6. Bó nhíp;","text":"Hình 11.1. Lắp nhíp trên xe 1. Khung xe; 2. Giá đỡ sau; 3. Miếng trượt; 4. Cầu xe; 5. Bu lông quang nhíp; 6. Bó nhíp;","pages":[112],"figure":{"number":"11.1","caption":"Hình 11.1. Lắp nhíp trên xe 1. Khung xe; 2. Giá đỡ sau; 3. Miếng trượt; 4. Cầu xe; 5. Bu lông quang nhíp; 6. Bó nhíp;"}},{"id":"s1761","kind":"figure","lesson":"11.2.1","title":"Hình 11.2. Bộ phận dẫn hướng dùng đòn dọc 1, 4. Đòn dọc bên; 2. Ống chống xoắn; 3. Đòn dọc trung tâm.","text":"Hình 11.2. Bộ phận dẫn hướng dùng đòn dọc 1, 4. Đòn dọc bên; 2. Ống chống xoắn; 3. Đòn dọc trung tâm.","pages":[112],"figure":{"number":"11.2","caption":"Hình 11.2. Bộ phận dẫn hướng dùng đòn dọc 1, 4. Đòn dọc bên; 2. Ống chống xoắn; 3. Đòn dọc trung tâm."}},{"id":"s1762","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"ứng con quay của bánh xe. Bánh xe có khối lượng lớn và quay với vận tốc lớn thì hiệu ứng con quay sẽ tạo nên tải trọng phụ lên các ổ bi, trục và các chi tiết của bộ phận dẫn hướng. 1. Bộ phận dẫn hướng hệ thống treo phụ thuộc Hệ thống treo phụ thuộc được lắp trên cầu cứng, trong đó hai bánh xe hai bên cùng lắp trên một dầm cầu (đối với bánh xe bị động) hoặc vỏ cầu (đối với bánh xe chủ động). Bộ phận dẫn hướng phải bảo đảm truyền lực dọc, lực ngang, mô-men và giữ dịch chuyển ngang của bánh xe trong phạm vi cho phép. a) Loại có bộ phận đàn hồi là nhíp lá Ở hệ thống treo phụ thuộc dùng nhíp lá, bó nhíp thường đồng thời đóng vai trò bộ phận đàn hồi và bộ phận dẫn hướng, như minh họa ở Hình 11.1. Bó nhíp được bắt chặt với cầu bằng quang nhíp; hai đầu nhíp liên kết với khung xe qua bản lề trụ hoặc gối đỡ cao su.","pages":[112]},{"id":"s1763","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Kết cấu này bảo đảm truyền lực dọc, lực ngang và mô-men, đồng thời cho phép bánh xe dao động trong mặt phẳng thẳng đứng. Ví dụ thực tế: KamAZ 6520, Hyundai HD72. 7. Chốt nhíp; 8. Gối đỡ; 9. Giá đỡ trước. b) Loại có bộ phận đàn hồi là lò xo xoắn","pages":[112]},{"id":"s1764","kind":"figure","lesson":"11.2.1","title":"Hình 11.2 thể hiện sơ đồ bộ phận dẫn hướng có hai đòn dọc bên (1) và (4), đòn dọc trung tâm (3). Đòn (1) và (4) nối với nhau bằng ống chống xoắn (2). Mỗi đòn có một đầu bắt bản lề với cầu xe, đầu kia bắt bản lề với khung (hoặc vỏ) xe. Nếu chỉ có đòn bên, khả năng chịu lực ngang kém và đòn trung tâm (3) có tác dụng hỗ trợ cho các đòn bên khi chịu lực ngang.","text":"Hình 11.2 thể hiện sơ đồ bộ phận dẫn hướng có hai đòn dọc bên (1) và (4), đòn dọc trung tâm (3). Đòn (1) và (4) nối với nhau bằng ống chống xoắn (2). Mỗi đòn có một đầu bắt bản lề với cầu xe, đầu kia bắt bản lề với khung (hoặc vỏ) xe. Nếu chỉ có đòn bên, khả năng chịu lực ngang kém và đòn trung tâm (3) có tác dụng hỗ trợ cho các đòn bên khi chịu lực ngang.","pages":[113],"figure":{"number":"11.2","caption":"Hình 11.2 thể hiện sơ đồ bộ phận dẫn hướng có hai đòn dọc bên (1) và (4), đòn dọc trung tâm (3). Đòn (1) và (4) nối với nhau bằng ống chống xoắn (2). Mỗi đòn có một đầu bắt bản lề với cầu xe, đầu kia bắt bản lề với khung (hoặc vỏ) xe. Nếu chỉ có đòn bên, khả năng chịu lực ngang kém và đòn trung tâm (3) có tác dụng hỗ trợ cho các đòn bên khi chịu lực ngang."}},{"id":"s1765","kind":"figure","lesson":"11.2.1","title":"Hình 11.3. Bộ phận dẫn hướng dùng đòn dọc và đòn ngang","text":"Hình 11.3. Bộ phận dẫn hướng dùng đòn dọc và đòn ngang","pages":[113],"figure":{"number":"11.3","caption":"Hình 11.3. Bộ phận dẫn hướng dùng đòn dọc và đòn ngang"}},{"id":"s1766","kind":"figure","lesson":"11.2.1","title":"Hình 11.4. Bộ phận dẫn hướng dùng đòn dọc và đòn chéo","text":"Hình 11.4. Bộ phận dẫn hướng dùng đòn dọc và đòn chéo","pages":[113],"figure":{"number":"11.4","caption":"Hình 11.4. Bộ phận dẫn hướng dùng đòn dọc và đòn chéo"}},{"id":"s1767","kind":"figure","lesson":"11.2.1","title":"Hình 11.3 thể hiện sơ đồ bộ phận dẫn hướng gồm các đòn dọc (1), (2) và các đòn ngang (3), (4). Đòn ngang (4) có một đầu bắt bản lề với khung xe, đầu còn lại bắt bản lề với thanh trung gian (5); thanh trung gian (5) quay quanh trục gắn với cầu xe. Đòn ngang (3) có một đầu bắt với thanh trung gian (5), đầu còn lại bắt với cầu xe. Mỗi đòn dọc có một đầu bắt bản lề với cầu xe, đầu còn lại bắt bản lề với khung (hoặc vỏ) xe. Các đòn ngang hỗ trợ các đòn dọc truyền lực ngang.","text":"Hình 11.3 thể hiện sơ đồ bộ phận dẫn hướng gồm các đòn dọc (1), (2) và các đòn ngang (3), (4). Đòn ngang (4) có một đầu bắt bản lề với khung xe, đầu còn lại bắt bản lề với thanh trung gian (5); thanh trung gian (5) quay quanh trục gắn với cầu xe. Đòn ngang (3) có một đầu bắt với thanh trung gian (5), đầu còn lại bắt với cầu xe. Mỗi đòn dọc có một đầu bắt bản lề với cầu xe, đầu còn lại bắt bản lề với khung (hoặc vỏ) xe. Các đòn ngang hỗ trợ các đòn dọc truyền lực ngang.","pages":[113],"figure":{"number":"11.3","caption":"Hình 11.3 thể hiện sơ đồ bộ phận dẫn hướng gồm các đòn dọc (1), (2) và các đòn ngang (3), (4). Đòn ngang (4) có một đầu bắt bản lề với khung xe, đầu còn lại bắt bản lề với thanh trung gian (5); thanh trung gian (5) quay quanh trục gắn với cầu xe. Đòn ngang (3) có một đầu bắt với thanh trung gian (5), đầu còn lại bắt với cầu xe. Mỗi đòn dọc có một đầu bắt bản lề với cầu xe, đầu còn lại bắt bản lề với khung (hoặc vỏ) xe. Các đòn ngang hỗ trợ các đòn dọc truyền lực ngang."}},{"id":"s1768","kind":"figure","lesson":"11.2.1","title":"Hình 11.4 thể hiện bộ phận dẫn hướng gồm các đòn dọc (1), (4) và các đòn chéo (2), (3). Mỗi đòn chéo có một đầu bắt với cầu xe, đầu còn lại bắt với khung","text":"Hình 11.4 thể hiện bộ phận dẫn hướng gồm các đòn dọc (1), (4) và các đòn chéo (2), (3). Mỗi đòn chéo có một đầu bắt với cầu xe, đầu còn lại bắt với khung","pages":[113],"figure":{"number":"11.4","caption":"Hình 11.4 thể hiện bộ phận dẫn hướng gồm các đòn dọc (1), (4) và các đòn chéo (2), (3). Mỗi đòn chéo có một đầu bắt với cầu xe, đầu còn lại bắt với khung"}},{"id":"s1769","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Lò xo xoắn không có khả năng truyền lực ngang và mô-men nên phải có bộ phận dẫn hướng riêng biệt. Đối với hệ thống treo phụ thuộc, bộ phận dẫn hướng có thể sử dụng đòn dọc, đòn ngang, đòn chéo hoặc phối hợp các loại đòn này. Các đòn dọc có tác dụng truyền lực dọc tốt và về mặt động học không có dịch chuyển ngang của bánh xe khi dao động. Tuy nhiên về kết cấu, đòn dọc chịu lực ngang kém. Kết cấu đòn ngang thì ngược lại, vì thế bộ phận dẫn hướng thường kết hợp đòn dọc với đòn ngang hoặc đòn chéo. Khi sử dụng đòn dọc, thường phải bố trí nhiều đòn. Một số xe điển hình: Land Rover Defender, Jeep Wrangler (cầu cứng trước và sau). 1, 2. Đòn dọc; 3, 4. Đòn ngang; 5. Thanh trung gian. 1, 4. Đòn dọc; 2, 3. Đòn chéo; 5. Bộ phận đàn hồi.","pages":[113]},{"id":"s1770","kind":"figure","lesson":"11.2.1","title":"Hình 11.5 thể hiện bộ phận dẫn hướng dùng bốn đòn dọc và một đòn ngang. Các đòn dọc (1), (2), (4), (5), gồm hai đòn ở mỗi bên, có một đầu bắt với cầu xe và đầu còn lại bắt với khung xe để truyền lực dọc. Các đòn (1) và (2) thường được gọi là “giằng cầu”. Đòn ngang (8) có một đầu bắt với khung xe qua giá (6) ở bên phải Hình 11.5, đầu còn lại bắt với cầu xe để truyền lực ngang. Các đòn dọc cùng khung và cầu xe tạo thành cơ cấu bốn khâu hình bình hành. Động học của các đòn dọc và đòn ngang bảo đảm bánh xe chỉ dao động trong mặt phẳng dọc.","text":"Hình 11.5 thể hiện bộ phận dẫn hướng dùng bốn đòn dọc và một đòn ngang. Các đòn dọc (1), (2), (4), (5), gồm hai đòn ở mỗi bên, có một đầu bắt với cầu xe và đầu còn lại bắt với khung xe để truyền lực dọc. Các đòn (1) và (2) thường được gọi là “giằng cầu”. Đòn ngang (8) có một đầu bắt với khung xe qua giá (6) ở bên phải Hình 11.5, đầu còn lại bắt với cầu xe để truyền lực ngang. Các đòn dọc cùng khung và cầu xe tạo thành cơ cấu bốn khâu hình bình hành. Động học của các đòn dọc và đòn ngang bảo đảm bánh xe chỉ dao động trong mặt phẳng dọc.","pages":[114],"figure":{"number":"11.5","caption":"Hình 11.5 thể hiện bộ phận dẫn hướng dùng bốn đòn dọc và một đòn ngang. Các đòn dọc (1), (2), (4), (5), gồm hai đòn ở mỗi bên, có một đầu bắt với cầu xe và đầu còn lại bắt với khung xe để truyền lực dọc. Các đòn (1) và (2) thường được gọi là “giằng cầu”. Đòn ngang (8) có một đầu bắt với khung xe qua giá (6) ở bên phải Hình 11.5, đầu còn lại bắt với cầu xe để truyền lực ngang. Các đòn dọc cùng khung và cầu xe tạo thành cơ cấu bốn khâu hình bình hành. Động học của các đòn dọc và đòn ngang bảo đảm bánh xe chỉ dao động trong mặt phẳng dọc."}},{"id":"s1771","kind":"figure","lesson":"11.2.1","title":"Hình 11.5. Bộ phận dẫn hướng dùng bốn đòn dọc và một đòn ngang 1, 2, 4, 5. Đòn dọc; 3. Cầu xe; 6. Giá bắt đòn ngang; 7. Giảm chấn; 8. Đòn ngang.","text":"Hình 11.5. Bộ phận dẫn hướng dùng bốn đòn dọc và một đòn ngang 1, 2, 4, 5. Đòn dọc; 3. Cầu xe; 6. Giá bắt đòn ngang; 7. Giảm chấn; 8. Đòn ngang.","pages":[114],"figure":{"number":"11.5","caption":"Hình 11.5. Bộ phận dẫn hướng dùng bốn đòn dọc và một đòn ngang 1, 2, 4, 5. Đòn dọc; 3. Cầu xe; 6. Giá bắt đòn ngang; 7. Giảm chấn; 8. Đòn ngang."}},{"id":"s1772","kind":"figure","lesson":"11.2.1","title":"Hình 11.6. Hai cầu gần nhau Trong trường hợp này, hệ thống treo được bố trí chung sao cho khi cầu (2) đứng trên một mô đất thì cả hai bánh xe của hai cầu vẫn tiếp xúc với mặt đất, phản","text":"Hình 11.6. Hai cầu gần nhau Trong trường hợp này, hệ thống treo được bố trí chung sao cho khi cầu (2) đứng trên một mô đất thì cả hai bánh xe của hai cầu vẫn tiếp xúc với mặt đất, phản","pages":[114],"figure":{"number":"11.6","caption":"Hình 11.6. Hai cầu gần nhau Trong trường hợp này, hệ thống treo được bố trí chung sao cho khi cầu (2) đứng trên một mô đất thì cả hai bánh xe của hai cầu vẫn tiếp xúc với mặt đất, phản"}},{"id":"s1773","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"(hoặc vỏ) xe. Mỗi đòn dọc có một đầu bắt bản lề với cầu xe, đầu còn lại bắt bản lề với khung (hoặc vỏ) xe. Các đòn chéo cũng hỗ trợ các đòn dọc truyền lực ngang. c) Hệ thống treo cân bằng Hệ thống treo cân bằng được áp dụng trên ô tô nhiều cầu. Ví dụ, xe ba cầu thường có hai cầu sau bố trí gần nhau; ở sơ mi rơ moóc còn có trường hợp ba cầu bố trí gần nhau. Hình 11.6 minh họa hai cầu sau, ký hiệu (2) và (3), của xe ba cầu khi mỗi cầu được bố trí một hệ thống treo riêng. Với cách bố trí này, khi cầu (2) đi lên một mô đất, cầu (3) có thể bị nhấc lên. Khi đó, cầu (2) bị quá tải, còn cầu (3) không truyền được lực dọc. Vì thế, khi hai hoặc ba cầu xe bố trí gần nhau, người ta không bố trí hệ thống treo riêng biệt cho từng cầu. Ví dụ: KamAZ 43118 (6x6), Ural-375, ZIL-131.","pages":[114]},{"id":"s1774","kind":"figure","lesson":"11.2.1","title":"Hình 11.7a bố trí một nhíp cho hai bánh xe. Nhíp (2) có hai đầu tựa lên hai bánh xe (1) và (5), đồng thời có thể quay quanh trục (4) cố định trên thân xe. Khi bánh xe (1) ở vị trí cao hơn bánh xe (5), bánh xe (1) nâng một đầu nhíp (2), làm nhíp quay quanh trục (4); nhờ đó, tải trọng vẫn được phân bố đều lên hai bánh xe. Ở Hình 11.7b, mỗi bánh xe được bố trí một nhíp; một đầu mỗi nhíp bắt với khung xe, hai đầu còn lại nối với nhau qua thanh cân bằng (6). Cách bố trí này cũng giúp tải trọng luôn phân bố đều lên hai bánh xe.","text":"Hình 11.7a bố trí một nhíp cho hai bánh xe. Nhíp (2) có hai đầu tựa lên hai bánh xe (1) và (5), đồng thời có thể quay quanh trục (4) cố định trên thân xe. Khi bánh xe (1) ở vị trí cao hơn bánh xe (5), bánh xe (1) nâng một đầu nhíp (2), làm nhíp quay quanh trục (4); nhờ đó, tải trọng vẫn được phân bố đều lên hai bánh xe. Ở Hình 11.7b, mỗi bánh xe được bố trí một nhíp; một đầu mỗi nhíp bắt với khung xe, hai đầu còn lại nối với nhau qua thanh cân bằng (6). Cách bố trí này cũng giúp tải trọng luôn phân bố đều lên hai bánh xe.","pages":[115],"figure":{"number":"11.7a","caption":"Hình 11.7a bố trí một nhíp cho hai bánh xe. Nhíp (2) có hai đầu tựa lên hai bánh xe (1) và (5), đồng thời có thể quay quanh trục (4) cố định trên thân xe. Khi bánh xe (1) ở vị trí cao hơn bánh xe (5), bánh xe (1) nâng một đầu nhíp (2), làm nhíp quay quanh trục (4); nhờ đó, tải trọng vẫn được phân bố đều lên hai bánh xe. Ở Hình 11.7b, mỗi bánh xe được bố trí một nhíp; một đầu mỗi nhíp bắt với khung xe, hai đầu còn lại nối với nhau qua thanh cân bằng (6). Cách bố trí này cũng giúp tải trọng luôn phân bố đều lên hai bánh xe."}},{"id":"s1775","kind":"figure","lesson":"11.2.1","title":"Hình 11.7. Sơ đồ hệ thống treo cân bằng","text":"Hình 11.7. Sơ đồ hệ thống treo cân bằng","pages":[115],"figure":{"number":"11.7","caption":"Hình 11.7. Sơ đồ hệ thống treo cân bằng"}},{"id":"s1776","kind":"figure","lesson":"11.2.1","title":"Hình 11.8. Kết cấu hệ thống treo cân bằng 1. Trục quay; 2. Giá đỡ; 3, 9. Thanh giằng cầu; 4, 7. Cầu xe; 5. Ống đỡ; 6. Quang nhíp; 8. Nhíp.","text":"Hình 11.8. Kết cấu hệ thống treo cân bằng 1. Trục quay; 2. Giá đỡ; 3, 9. Thanh giằng cầu; 4, 7. Cầu xe; 5. Ống đỡ; 6. Quang nhíp; 8. Nhíp.","pages":[115],"figure":{"number":"11.8","caption":"Hình 11.8. Kết cấu hệ thống treo cân bằng 1. Trục quay; 2. Giá đỡ; 3, 9. Thanh giằng cầu; 4, 7. Cầu xe; 5. Ống đỡ; 6. Quang nhíp; 8. Nhíp."}},{"id":"s1777","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"lực từ mặt đường lên các bánh xe của hai cầu không thay đổi nhiều (so với khi xe đứng trên mặt đường phẳng). Có nhiều cách bố trí hệ thống treo trong trường hợp này. Hình 11.7 thể hiện hai sơ đồ bố trí hệ thống treo cho hai cầu sau của xe ba cầu. a) Loại một nhíp; b) Loại hai nhíp. 1, 5. Bánh xe; 2, 3. Nhíp; 4. Trục quay; 6. Thanh treo cân bằng; 7. Khung xe. Trong trường hợp nhíp chỉ tựa lên bánh xe (như Hình 11.7a) thì nhíp không thể truyền được lực dọc và ngang. Khi đó, cần phải có bộ phận dẫn hướng (Hình 11.8). Hình 11.8 thể hiện kết cấu hệ thống treo cân bằng theo sơ đồ Hình 11.7a. Các cầu (4) và (7) lần lượt là cầu giữa và cầu sau. Bó nhíp (8) được bắt chặt vào ống (5) bằng các quang nhíp (6). Ống (5) lắp trên trục (1) và có thể quay quanh trục này, nhờ đó bó nhíp cũng quay quanh trục (1).","pages":[115]},{"id":"s1778","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Trục (1) được lắp trên giá (2), còn giá (2) bắt chặt vào khung xe. Hai đầu bó nhíp tựa lên các cầu (4) và (7).","pages":[115]},{"id":"s1779","kind":"figure","lesson":"11.2.1","title":"Hình 11.9. Bố trí hệ thống treo cân bằng 1, 10. Bó nhíp trái và phải; 2, 7. Cầu xe; 3. Quang nhíp; 4. Trục quay; 5. Ống đỡ; 6, 9, 11.","text":"Hình 11.9. Bố trí hệ thống treo cân bằng 1, 10. Bó nhíp trái và phải; 2, 7. Cầu xe; 3. Quang nhíp; 4. Trục quay; 5. Ống đỡ; 6, 9, 11.","pages":[116],"figure":{"number":"11.9","caption":"Hình 11.9. Bố trí hệ thống treo cân bằng 1, 10. Bó nhíp trái và phải; 2, 7. Cầu xe; 3. Quang nhíp; 4. Trục quay; 5. Ống đỡ; 6, 9, 11."}},{"id":"s1780","kind":"figure","lesson":"11.2.1","title":"Hình 11.9 thể hiện hai hệ thống treo cân bằng bố trí ở hai bên của hai cầu sau trên xe ba cầu. Hai cầu sau, ký hiệu (2) và (7), được bố trí gần nhau để cùng sử dụng hệ thống treo cân bằng.","text":"Hình 11.9 thể hiện hai hệ thống treo cân bằng bố trí ở hai bên của hai cầu sau trên xe ba cầu. Hai cầu sau, ký hiệu (2) và (7), được bố trí gần nhau để cùng sử dụng hệ thống treo cân bằng.","pages":[116],"figure":{"number":"11.9","caption":"Hình 11.9 thể hiện hai hệ thống treo cân bằng bố trí ở hai bên của hai cầu sau trên xe ba cầu. Hai cầu sau, ký hiệu (2) và (7), được bố trí gần nhau để cùng sử dụng hệ thống treo cân bằng."}},{"id":"s1781","kind":"figure","lesson":"11.2.1","title":"Hình 11.10. Treo cân bằng cho ba cầu xe 1, 5. Các chốt tựa; 2. Chốt quay; 3, 4. Thanh cân bằng; 6, 8, 10. Nhíp; 7, 9, 11. Thanh","text":"Hình 11.10. Treo cân bằng cho ba cầu xe 1, 5. Các chốt tựa; 2. Chốt quay; 3, 4. Thanh cân bằng; 6, 8, 10. Nhíp; 7, 9, 11. Thanh","pages":[116],"figure":{"number":"11.10","caption":"Hình 11.10. Treo cân bằng cho ba cầu xe 1, 5. Các chốt tựa; 2. Chốt quay; 3, 4. Thanh cân bằng; 6, 8, 10. Nhíp; 7, 9, 11. Thanh"}},{"id":"s1782","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Vì nhíp chỉ tựa lên cầu nên không thể truyền lực. Trong hệ thống này, nhíp chỉ làm nhiệm vụ của bộ phận đàn hồi. Các giằng cầu (3) và (9) (Hình 11.8) có nhiệm vụ truyền lực dọc, lực ngang, mô-men và bảo đảm quan hệ động học giữa bánh xe với cầu xe. Mỗi giằng cầu có một đầu bắt với khung xe, đầu còn lại bắt với cầu xe. Các giằng cầu này chính là bộ phận dẫn hướng của hệ thống treo. Các giằng cầu; 8. Giá đỡ. Các bó nhíp (1) và (10) được bắt vào các ống (5) bằng quang nhíp (3). Mỗi ống (5) quay quanh trục (4); trục (4) được lắp trên giá (8), còn giá (8) bắt vào khung xe. Khi bánh xe dao động, các bó nhíp (1) và (10) quay quanh trục (4). Các thanh giằng cầu (6), (9) và (11) đóng vai trò là bộ phận dẫn hướng. Liên kết giữa thanh giằng cầu với khung xe hoặc cầu xe thường là khớp cầu.","pages":[116]},{"id":"s1783","kind":"figure","lesson":"11.2.1","title":"Hình 11.11a thể hiện trạng thái xe đầy tải, khi xi-lanh lực (1) không làm việc. Nhíp (7), quang treo (3) và đòn nâng (4) tạo thành hệ thống treo cân bằng cho các bánh xe (5) và (6), nhờ đó tải trọng tác dụng lên hai bánh xe bằng nhau. Khi xe chạy non tải, bánh xe (5) được “treo” lên (Hình 11.11b). Xi-lanh lực (1) được cấp dầu; pít-tông dịch chuyển sang phải, tác động lên đòn quay (2). Đầu còn lại của đòn quay (2) đẩy đòn nâng (4) và nâng bánh xe (5) lên.","text":"Hình 11.11a thể hiện trạng thái xe đầy tải, khi xi-lanh lực (1) không làm việc. Nhíp (7), quang treo (3) và đòn nâng (4) tạo thành hệ thống treo cân bằng cho các bánh xe (5) và (6), nhờ đó tải trọng tác dụng lên hai bánh xe bằng nhau. Khi xe chạy non tải, bánh xe (5) được “treo” lên (Hình 11.11b). Xi-lanh lực (1) được cấp dầu; pít-tông dịch chuyển sang phải, tác động lên đòn quay (2). Đầu còn lại của đòn quay (2) đẩy đòn nâng (4) và nâng bánh xe (5) lên.","pages":[117],"figure":{"number":"11.11a","caption":"Hình 11.11a thể hiện trạng thái xe đầy tải, khi xi-lanh lực (1) không làm việc. Nhíp (7), quang treo (3) và đòn nâng (4) tạo thành hệ thống treo cân bằng cho các bánh xe (5) và (6), nhờ đó tải trọng tác dụng lên hai bánh xe bằng nhau. Khi xe chạy non tải, bánh xe (5) được “treo” lên (Hình 11.11b). Xi-lanh lực (1) được cấp dầu; pít-tông dịch chuyển sang phải, tác động lên đòn quay (2). Đầu còn lại của đòn quay (2) đẩy đòn nâng (4) và nâng bánh xe (5) lên."}},{"id":"s1784","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Khi có ba cầu xe bố trí gần nhau, hệ thống treo được bố trí theo sơ đồ Hình 11.10. Mỗi bánh xe có một nhíp. Nhíp (10) của bánh xe trước có một đầu tựa vào chốt (1) trên khung xe, đầu còn lại tựa vào chốt trên thanh cân bằng (3). Nhíp (8) của bánh xe giữa có hai đầu lần lượt tựa vào các chốt trên thanh cân bằng (3) và (4). Nhíp (6) của bánh xe sau có một đầu tựa vào chốt trên thanh cân bằng (4), đầu còn lại tựa vào chốt trên khung xe. Các thanh giằng (7), (9) và (11) đóng vai trò là bộ phận dẫn hướng. Cách bố trí này giúp tải trọng luôn phân bố đều lên các bánh xe. Một số ô tô nhiều cầu làm việc ở các mức tải khác nhau, chẳng hạn xe vận tải một chiều có tải ở chiều đi và không tải ở chiều về. Khi xe đầy tải, các cầu đều chịu tải; khi xe non tải, một cầu có thể được nâng lên và không chịu tải.","pages":[117]},{"id":"s1785","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Hệ thống treo cân bằng không thường trực được áp dụng trong những trường hợp này (Hình 11.11). a) b) Hình 11.11. Hệ thống treo cân bằng không thường trực a) Hai cầu cùng chịu tải trọng; b) Một cầu được treo lên. 1. Xi-lanh lực; 2. Đòn quay; 3. Quang treo; 4. Đòn nâng; 5, 6. Bánh xe; 7. Nhíp. Các bánh xe (5) và (6) dùng chung bộ phận đàn hồi là nhíp (7). Nhíp (7) được bắt chặt với bánh xe (6); một đầu bắt bản lề với khung xe, đầu còn lại bắt bản lề với quang treo (3). Đầu kia của quang treo (3) bắt bản lề với đòn nâng (4). Đòn nâng (4) bắt bản lề với khung xe; một đầu liên kết với bánh xe (5), đầu còn lại tựa vào đòn quay (2). Đòn quay (2) bắt bản lề với khung xe; một đầu tựa vào đòn nâng (4), đầu còn lại nối với cần pít-tông của xi-lanh lực (1). 2.","pages":[117]},{"id":"s1786","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Bộ phận dẫn hướng hệ thống treo độc lập a) Loại đòn ngang Ở bộ phận dẫn hướng sử dụng đòn ngang, khi bánh xe dao động (tức là có dịch chuyển thẳng đứng) sẽ có dịch chuyển ngang của bánh xe và góc lệch trục bánh xe (Hình 11.12). Hình 11.12 cho thấy khi có dịch chuyển thẳng đứng h sẽ gây ra: - Dịch chuyển theo chiều ngang của bánh xe ∆B; - Góc  : góc nghiêng của mặt phẳng bánh xe hay góc lệch của trục bánh xe so với vị trí ban đầu.","pages":[117]},{"id":"s1787","kind":"figure","lesson":"11.2.1","title":"Hình 11.12. Sơ đồ bộ phận dẫn hướng loại đòn ngang a) Loại một đòn; b) Loại hai đòn hình bình hành; c) Loại hai đòn hình thang; d) Hệ thống","text":"Hình 11.12. Sơ đồ bộ phận dẫn hướng loại đòn ngang a) Loại một đòn; b) Loại hai đòn hình bình hành; c) Loại hai đòn hình thang; d) Hệ thống","pages":[118],"figure":{"number":"11.12","caption":"Hình 11.12. Sơ đồ bộ phận dẫn hướng loại đòn ngang a) Loại một đòn; b) Loại hai đòn hình bình hành; c) Loại hai đòn hình thang; d) Hệ thống"}},{"id":"s1788","kind":"figure","lesson":"11.2.1","title":"Hình 11.13. Bộ phận dẫn hướng cơ cấu bốn khâu hình bình hành Loại hai đòn hình bình hành (Hình 11.12b và 11.13) có kết cấu bao gồm hai đòn ngang bằng nhau và một đòn đứng, kết hợp với khung xe tạo thành một cơ cấu","text":"Hình 11.13. Bộ phận dẫn hướng cơ cấu bốn khâu hình bình hành Loại hai đòn hình bình hành (Hình 11.12b và 11.13) có kết cấu bao gồm hai đòn ngang bằng nhau và một đòn đứng, kết hợp với khung xe tạo thành một cơ cấu","pages":[118],"figure":{"number":"11.13","caption":"Hình 11.13. Bộ phận dẫn hướng cơ cấu bốn khâu hình bình hành Loại hai đòn hình bình hành (Hình 11.12b và 11.13) có kết cấu bao gồm hai đòn ngang bằng nhau và một đòn đứng, kết hợp với khung xe tạo thành một cơ cấu"}},{"id":"s1789","kind":"pdf","lesson":"11.2.1","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo phụ thuộc","text":"Như đã nói ở trên, nếu dịch chuyển ngang ∆B vượt quá biến dạng đàn hồi của lốp thì bánh xe sẽ bị trượt và lốp sẽ bị mòn. Góc  sẽ tạo ra hiệu ứng con quay của bánh xe. Bánh xe có khối lượng lớn và quay với vận tốc lớn thì hiệu ứng con quay sẽ tạo nên tải trọng phụ lên các ổ bi, trục và các chi tiết của bộ phận dẫn hướng. Mặt khác, đòn ngang chịu lực ngang tốt nhưng chịu lực dọc kém. Vì vậy, kết cấu của bộ phận dẫn hướng đòn ngang phải bảo đảm truyền được lực thẳng đứng, đồng thời giữ ∆B và  (Hình 11.12) nằm trong phạm vi cho phép. Bộ phận dẫn hướng loại đòn ngang có thể có một số loại sau đây (Hình 11.12): - Loại một đòn (Hình 11.12a), loại này ít được sử dụng; - Loại hai đòn hình bình hành (Hình 11.12b); - Loại hai đòn hình thang (Hình 11.12c); - Loại MacPherson (Hình 11.12d). * Loại hai đòn hình bình hành","pages":[118]},{"id":"s1790","kind":"figure","lesson":"11.2.2","title":"Hình 11.14. Hệ thống treo sau độc lập đòn ngang hình thang 1. Khung xe; 2. Đòn trên; 3. Đòn đứng; 4, 9. Cam quay; 5. Bộ phận đàn hồi; 6, 7. Đòn","text":"Hình 11.14. Hệ thống treo sau độc lập đòn ngang hình thang 1. Khung xe; 2. Đòn trên; 3. Đòn đứng; 4, 9. Cam quay; 5. Bộ phận đàn hồi; 6, 7. Đòn","pages":[119],"figure":{"number":"11.14","caption":"Hình 11.14. Hệ thống treo sau độc lập đòn ngang hình thang 1. Khung xe; 2. Đòn trên; 3. Đòn đứng; 4, 9. Cam quay; 5. Bộ phận đàn hồi; 6, 7. Đòn"}},{"id":"s1791","kind":"figure","lesson":"11.2.2","title":"Hình 11.15. Hệ thống treo trước độc lập đòn ngang hình thang 1. Moay-ơ bánh xe; 2. Cam quay; 3. Bu lông bánh xe; 4. Bánh xe; 5. Đòn trên; 6, 9. Ụ","text":"Hình 11.15. Hệ thống treo trước độc lập đòn ngang hình thang 1. Moay-ơ bánh xe; 2. Cam quay; 3. Bu lông bánh xe; 4. Bánh xe; 5. Đòn trên; 6, 9. Ụ","pages":[119],"figure":{"number":"11.15","caption":"Hình 11.15. Hệ thống treo trước độc lập đòn ngang hình thang 1. Moay-ơ bánh xe; 2. Cam quay; 3. Bu lông bánh xe; 4. Bánh xe; 5. Đòn trên; 6, 9. Ụ"}},{"id":"s1792","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"bốn khâu hình bình hành. Loại này không có góc lệch trục bánh xe (  = 0); tuy nhiên, có dịch chuyển ngang của bánh xe ∆B lớn. Để truyền được lực dọc, các đòn ngang có kết cấu như Hình 11.13, đòn dưới có kết cấu hình chữ A còn đòn trên có kết cấu hình chữ A hoặc chữ V. Loại bộ phận dẫn hướng này cũng ít được dùng. * Loại hai đòn hình thang cao su; 7. Đòn đứng; 8. Trụ đứng; 10. Giảm chấn; 11. Trống phanh; 12. Đòn dưới; 13. Giá đỡ lò xo và giảm chấn; 14. Lò xo (bộ phận đàn hồi). Loại hai đòn hình thang được dùng khá phổ biến trên xe con. Loại này có kết cấu bao gồm hai đòn ngang không bằng nhau và một đòn đứng, kết hợp với khung xe tạo thành một cơ cấu bốn khâu hình thang. Đòn ngang trên có chiều dài nhỏ hơn đòn ngang dưới. Các đòn trên và dưới của bộ phận dẫn hướng đều có kết cấu chữ A","pages":[119]},{"id":"s1793","kind":"figure","lesson":"11.2.2","title":"Hình 11.14 thể hiện hệ thống treo có bộ phận dẫn hướng đòn ngang hình thang, lắp cho bánh xe không dẫn hướng (bánh xe sau). Bộ phận dẫn hướng có đòn trên (2) ngắn hơn các đòn dưới (6) và (7); cam quay bánh xe (4) được bắt với đòn đứng (3). Đòn trên (2), đòn dưới (6), đòn đứng (3) và khung xe (1) tạo thành cơ cấu bốn khâu hình thang.","text":"Hình 11.14 thể hiện hệ thống treo có bộ phận dẫn hướng đòn ngang hình thang, lắp cho bánh xe không dẫn hướng (bánh xe sau). Bộ phận dẫn hướng có đòn trên (2) ngắn hơn các đòn dưới (6) và (7); cam quay bánh xe (4) được bắt với đòn đứng (3). Đòn trên (2), đòn dưới (6), đòn đứng (3) và khung xe (1) tạo thành cơ cấu bốn khâu hình thang.","pages":[120],"figure":{"number":"11.14","caption":"Hình 11.14 thể hiện hệ thống treo có bộ phận dẫn hướng đòn ngang hình thang, lắp cho bánh xe không dẫn hướng (bánh xe sau). Bộ phận dẫn hướng có đòn trên (2) ngắn hơn các đòn dưới (6) và (7); cam quay bánh xe (4) được bắt với đòn đứng (3). Đòn trên (2), đòn dưới (6), đòn đứng (3) và khung xe (1) tạo thành cơ cấu bốn khâu hình thang."}},{"id":"s1794","kind":"figure","lesson":"11.2.2","title":"Hình 11.15 thể hiện hệ thống treo có bộ phận dẫn hướng đòn ngang hình thang, lắp cho bánh xe dẫn hướng (bánh xe trước). Bộ phận dẫn hướng gồm đòn trên (5), đòn dưới (12) và đòn đứng (7). Trụ đứng (8) lắp với đòn đứng (7), còn cam quay bánh xe (2) lắp với trụ đứng (8). Khi quay vòng, bánh xe quay quanh trụ đứng (8). Giá đỡ lò xo và giảm chấn (13) được lắp vào đòn dưới (12).","text":"Hình 11.15 thể hiện hệ thống treo có bộ phận dẫn hướng đòn ngang hình thang, lắp cho bánh xe dẫn hướng (bánh xe trước). Bộ phận dẫn hướng gồm đòn trên (5), đòn dưới (12) và đòn đứng (7). Trụ đứng (8) lắp với đòn đứng (7), còn cam quay bánh xe (2) lắp với trụ đứng (8). Khi quay vòng, bánh xe quay quanh trụ đứng (8). Giá đỡ lò xo và giảm chấn (13) được lắp vào đòn dưới (12).","pages":[120],"figure":{"number":"11.15","caption":"Hình 11.15 thể hiện hệ thống treo có bộ phận dẫn hướng đòn ngang hình thang, lắp cho bánh xe dẫn hướng (bánh xe trước). Bộ phận dẫn hướng gồm đòn trên (5), đòn dưới (12) và đòn đứng (7). Trụ đứng (8) lắp với đòn đứng (7), còn cam quay bánh xe (2) lắp với trụ đứng (8). Khi quay vòng, bánh xe quay quanh trụ đứng (8). Giá đỡ lò xo và giảm chấn (13) được lắp vào đòn dưới (12)."}},{"id":"s1795","kind":"figure","lesson":"11.2.2","title":"Hình 11.16. Sơ đồ hệ thống treo MacPherson 1. Giá đỡ trên; 2, 7. Ụ cao su; 3. Lò xo; 4. Giảm chấn; 5. Cam quay bánh xe; 6. Đòn dưới.","text":"Hình 11.16. Sơ đồ hệ thống treo MacPherson 1. Giá đỡ trên; 2, 7. Ụ cao su; 3. Lò xo; 4. Giảm chấn; 5. Cam quay bánh xe; 6. Đòn dưới.","pages":[120],"figure":{"number":"11.16","caption":"Hình 11.16. Sơ đồ hệ thống treo MacPherson 1. Giá đỡ trên; 2, 7. Ụ cao su; 3. Lò xo; 4. Giảm chấn; 5. Cam quay bánh xe; 6. Đòn dưới."}},{"id":"s1796","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"và có hai điểm bắt vào khung xe bằng khớp bản lề. Kết cấu này bảo đảm cho bộ phận dẫn hướng có thể truyền được lực dọc. Ví dụ: Hyundai Tucson, Kia Sorento (cầu trước độc lập). Bộ phận dẫn hướng loại hai đòn hình thang này có dịch chuyển ngang của bánh xe ∆B và góc lệch của trục bánh xe  nhỏ nếu chọn tỷ lệ chiều dài giữa đòn ngang trên và dưới hợp lý. Hiện nay, tỷ lệ này thường được chọn như sau: trong đó: la – chiều dài đòn ngang trên; lb – chiều dài đòn ngang dưới. * Hệ thống treo MacPherson Hệ thống treo MacPherson là biến thể của hệ thống treo hai đòn hình thang, trong đó đòn ngang trên được thay bằng cụm lò xo - giảm chấn, nhờ đó kết cấu trở nên gọn hơn. Về mặt động học, có thể xem đòn ngang trên của hệ thống treo MacPherson có chiều dài quy ước bằng 0 (Hình 11.12d).","pages":[120]},{"id":"s1797","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"Do không còn đòn ngang trên, khi bánh xe dao động thì chiều dài đòn đứng phải thay đổi theo chuyển vị thẳng đứng của bánh xe; vì vậy, đòn đứng có kết cấu như trên Hình 11.12d. Có thể bố trí bộ phận đàn hồi (lò xo xoắn) và giảm chấn ống tại vị trí đòn đứng (Hình 11.16 và 11.17), nhờ đó hệ thống treo MacPherson có kết cấu rất gọn. Hình 11.16 thể hiện hệ thống treo MacPherson lắp cho bánh xe bị động. Đòn ngang (6) của bộ phận dẫn hướng bắt với khung bằng bản lề trụ và bắt với cam","pages":[120]},{"id":"s1798","kind":"figure","lesson":"11.2.2","title":"Hình 11.17. Hệ thống treo xe VAZ-2108 1. Gối cao su; 2. Ổ đỡ; 3. Bánh xe; 4. Moay-ơ bánh xe; 5. Đòn ngang dưới; 6. Rô-tuyn; 7.","text":"Hình 11.17. Hệ thống treo xe VAZ-2108 1. Gối cao su; 2. Ổ đỡ; 3. Bánh xe; 4. Moay-ơ bánh xe; 5. Đòn ngang dưới; 6. Rô-tuyn; 7.","pages":[121],"figure":{"number":"11.17","caption":"Hình 11.17. Hệ thống treo xe VAZ-2108 1. Gối cao su; 2. Ổ đỡ; 3. Bánh xe; 4. Moay-ơ bánh xe; 5. Đòn ngang dưới; 6. Rô-tuyn; 7."}},{"id":"s1799","kind":"figure","lesson":"11.2.2","title":"Hình 11.17 thể hiện kết cấu hệ thống treo MacPherson của bánh xe trước chủ động, dẫn hướng trên xe VAZ-2108. Đòn dưới (5) bắt với cam quay (7) bằng rô- tuyn (6), đầu còn lại bắt với khung xe. Đòn đứng là giảm chấn (10), có đầu dưới lắp chặt với cam quay (7) và đầu trên bắt với khung xe qua ổ đỡ (2) và gối cao su (1). Ổ đỡ (2) cho phép đòn đứng quay khi ô tô đổi hướng. Bộ phận đàn hồi là lò xo (11), có đầu dưới tựa vào đòn đứng và giảm chấn (10), đầu trên tựa vào khung xe. Bán trục (8) truyền mô-men chủ động đến bánh xe qua khớp các-đăng đồng tốc (9).","text":"Hình 11.17 thể hiện kết cấu hệ thống treo MacPherson của bánh xe trước chủ động, dẫn hướng trên xe VAZ-2108. Đòn dưới (5) bắt với cam quay (7) bằng rô- tuyn (6), đầu còn lại bắt với khung xe. Đòn đứng là giảm chấn (10), có đầu dưới lắp chặt với cam quay (7) và đầu trên bắt với khung xe qua ổ đỡ (2) và gối cao su (1). Ổ đỡ (2) cho phép đòn đứng quay khi ô tô đổi hướng. Bộ phận đàn hồi là lò xo (11), có đầu dưới tựa vào đòn đứng và giảm chấn (10), đầu trên tựa vào khung xe. Bán trục (8) truyền mô-men chủ động đến bánh xe qua khớp các-đăng đồng tốc (9).","pages":[121],"figure":{"number":"11.17","caption":"Hình 11.17 thể hiện kết cấu hệ thống treo MacPherson của bánh xe trước chủ động, dẫn hướng trên xe VAZ-2108. Đòn dưới (5) bắt với cam quay (7) bằng rô- tuyn (6), đầu còn lại bắt với khung xe. Đòn đứng là giảm chấn (10), có đầu dưới lắp chặt với cam quay (7) và đầu trên bắt với khung xe qua ổ đỡ (2) và gối cao su (1). Ổ đỡ (2) cho phép đòn đứng quay khi ô tô đổi hướng. Bộ phận đàn hồi là lò xo (11), có đầu dưới tựa vào đòn đứng và giảm chấn (10), đầu trên tựa vào khung xe. Bán trục (8) truyền mô-men chủ động đến bánh xe qua khớp các-đăng đồng tốc (9)."}},{"id":"s1800","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"quay qua ụ cao su (7). Để bảo đảm truyền lực ngang, đòn ngang (6) có kết cấu như hình vẽ; trong nhiều trường hợp, đòn có dạng chữ A với hai điểm bắt bản lề vào thân xe, tương tự đòn ngang dưới của hệ thống treo hình bình hành hoặc hình thang. Đòn đứng là giảm chấn ống (4), có đầu dưới bắt chặt với cam quay (5). Đầu trên của giảm chấn (4) bắt vào giá (1) qua ụ cao su (2), còn giá (1) bắt chặt với khung xe. Bộ phận đàn hồi là lò xo xoắn (3), có đầu dưới tựa vào giảm chấn (4) và đầu trên tựa vào ụ cao su (2). Cam quay; 8. Bán trục; 9. Khớp các-đăng; 10. Giảm chấn; 11. Lò xo. Ở hệ thống treo kiểu MacPherson, khi bánh xe dao động (dịch chuyển thẳng đứng), các dịch chuyển ngang ∆B và góc lệch trục bánh xe  đều nhỏ.","pages":[121]},{"id":"s1801","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"Loại hệ thống treo này ngày càng được sử dụng nhiều trên xe con. b) Loại đòn dọc Hình 11.18 thể hiện sơ đồ bộ phận dẫn hướng loại đòn dọc, gồm đòn (1) của bánh xe trái và đòn (2) của bánh xe phải. Mỗi đòn dọc có một đầu bắt với bánh xe, đầu còn lại bắt bản lề với khung xe; trục quay của bản lề nằm ngang như hình vẽ. Với kết cấu này, khi bánh xe dịch chuyển thẳng đứng sẽ không phát sinh dịch chuyển ngang hoặc góc lệch trục bánh xe. Tuy nhiên, nếu mỗi bánh xe chỉ có một đòn như Hình 11.18 thì chiều dài cơ sở xe (khoảng cách giữa hai trục bánh xe) sẽ thay đổi khi bánh xe dịch chuyển thẳng đứng. Đòn dọc truyền lực dọc rất tốt nhưng truyền lực ngang kém. Để tăng khả năng truyền lực ngang, trục quay của bản lề được kéo dài (xem hình vẽ). Bộ phận đàn hồi (lò xo) được đặt trên đòn của bộ phận dẫn hướng.","pages":[121]},{"id":"s1802","kind":"figure","lesson":"11.2.2","title":"Hình 11.18. Bộ phận dẫn hướng loại đòn dọc","text":"Hình 11.18. Bộ phận dẫn hướng loại đòn dọc","pages":[122],"figure":{"number":"11.18","caption":"Hình 11.18. Bộ phận dẫn hướng loại đòn dọc"}},{"id":"s1803","kind":"figure","lesson":"11.2.2","title":"Hình 11.19 thể hiện sơ đồ bộ phận dẫn hướng loại đòn dọc có ống De Dion. Bộ phận dẫn hướng gồm hai đòn dưới (4), (5), hai đòn trên (1), (3) và ống De Dion (2) nối hai bên bánh xe. Hai đòn dưới (4), (5) bố trí phía trước, còn hai đòn trên (1), (3) bố trí phía sau bánh xe. Với kết cấu này, khi bánh xe dịch chuyển thẳng đứng, chiều dài cơ sở xe không thay đổi như ở trường hợp chỉ có một đòn đã trình bày ở trên. Mặt khác, việc bố trí hai cặp đòn kết hợp với ống De Dion như hình vẽ làm tăng khả năng truyền lực ngang của bộ phận dẫn hướng. Bộ phận đàn hồi (lò xo) được đặt trên các đòn dưới.","text":"Hình 11.19 thể hiện sơ đồ bộ phận dẫn hướng loại đòn dọc có ống De Dion. Bộ phận dẫn hướng gồm hai đòn dưới (4), (5), hai đòn trên (1), (3) và ống De Dion (2) nối hai bên bánh xe. Hai đòn dưới (4), (5) bố trí phía trước, còn hai đòn trên (1), (3) bố trí phía sau bánh xe. Với kết cấu này, khi bánh xe dịch chuyển thẳng đứng, chiều dài cơ sở xe không thay đổi như ở trường hợp chỉ có một đòn đã trình bày ở trên. Mặt khác, việc bố trí hai cặp đòn kết hợp với ống De Dion như hình vẽ làm tăng khả năng truyền lực ngang của bộ phận dẫn hướng. Bộ phận đàn hồi (lò xo) được đặt trên các đòn dưới.","pages":[122],"figure":{"number":"11.19","caption":"Hình 11.19 thể hiện sơ đồ bộ phận dẫn hướng loại đòn dọc có ống De Dion. Bộ phận dẫn hướng gồm hai đòn dưới (4), (5), hai đòn trên (1), (3) và ống De Dion (2) nối hai bên bánh xe. Hai đòn dưới (4), (5) bố trí phía trước, còn hai đòn trên (1), (3) bố trí phía sau bánh xe. Với kết cấu này, khi bánh xe dịch chuyển thẳng đứng, chiều dài cơ sở xe không thay đổi như ở trường hợp chỉ có một đòn đã trình bày ở trên. Mặt khác, việc bố trí hai cặp đòn kết hợp với ống De Dion như hình vẽ làm tăng khả năng truyền lực ngang của bộ phận dẫn hướng. Bộ phận đàn hồi (lò xo) được đặt trên các đòn dưới."}},{"id":"s1804","kind":"figure","lesson":"11.2.2","title":"Hình 11.19. Bộ phận dẫn hướng đòn dọc và ống De Dion","text":"Hình 11.19. Bộ phận dẫn hướng đòn dọc và ống De Dion","pages":[122],"figure":{"number":"11.19","caption":"Hình 11.19. Bộ phận dẫn hướng đòn dọc và ống De Dion"}},{"id":"s1805","kind":"figure","lesson":"11.2.2","title":"Hình 11.20 thể hiện sơ đồ bộ phận dẫn hướng loại đòn chéo. Hai đòn chéo (1) và (2) có kết cấu như hình vẽ. So với đòn dọc, đòn chéo cải thiện khả năng truyền lực ngang. Khi bánh xe dao động, bộ phận dẫn hướng loại này vẫn gây dịch chuyển ngang nhưng có giá trị nhỏ.","text":"Hình 11.20 thể hiện sơ đồ bộ phận dẫn hướng loại đòn chéo. Hai đòn chéo (1) và (2) có kết cấu như hình vẽ. So với đòn dọc, đòn chéo cải thiện khả năng truyền lực ngang. Khi bánh xe dao động, bộ phận dẫn hướng loại này vẫn gây dịch chuyển ngang nhưng có giá trị nhỏ.","pages":[122],"figure":{"number":"11.20","caption":"Hình 11.20 thể hiện sơ đồ bộ phận dẫn hướng loại đòn chéo. Hai đòn chéo (1) và (2) có kết cấu như hình vẽ. So với đòn dọc, đòn chéo cải thiện khả năng truyền lực ngang. Khi bánh xe dao động, bộ phận dẫn hướng loại này vẫn gây dịch chuyển ngang nhưng có giá trị nhỏ."}},{"id":"s1806","kind":"figure","lesson":"11.2.2","title":"Hình 11.20. Bộ phận dẫn hướng loại đòn chéo","text":"Hình 11.20. Bộ phận dẫn hướng loại đòn chéo","pages":[122],"figure":{"number":"11.20","caption":"Hình 11.20. Bộ phận dẫn hướng loại đòn chéo"}},{"id":"s1807","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"1. Đòn dọc trái; 2. Đòn dọc phải. Để khắc phục nhược điểm của loại một đòn dọc, có thể bố trí thêm các đòn khác; Hình 11.19 là một ví dụ. 1, 3. Đòn dọc trên; 2. Ống De Dion; 4, 5. Đòn dọc dưới. c) Loại đòn chéo Loại đòn chéo cũng thường được sử dụng trên các bộ phận dẫn hướng của hệ thống treo. 1. Đòn trái; 2. Đòn phải.","pages":[122]},{"id":"s1808","kind":"figure","lesson":"11.3.1","title":"Hình 11.21. Hệ thống treo có bộ phận đàn hồi là lò xo xoắn 1. Lò xo xoắn; 2. Giảm chấn; 3. Ụ hạn chế; 4. Đòn trên; 5. Đòn đứng; 6. Trụ đứng; 7.","text":"Hình 11.21. Hệ thống treo có bộ phận đàn hồi là lò xo xoắn 1. Lò xo xoắn; 2. Giảm chấn; 3. Ụ hạn chế; 4. Đòn trên; 5. Đòn đứng; 6. Trụ đứng; 7.","pages":[123],"figure":{"number":"11.21","caption":"Hình 11.21. Hệ thống treo có bộ phận đàn hồi là lò xo xoắn 1. Lò xo xoắn; 2. Giảm chấn; 3. Ụ hạn chế; 4. Đòn trên; 5. Đòn đứng; 6. Trụ đứng; 7."}},{"id":"s1809","kind":"figure","lesson":"11.3.1","title":"Hình 11.21 thể hiện hệ thống treo sử dụng lò xo xoắn làm bộ phận đàn hồi. Đây là hệ thống treo độc lập lắp cho bánh xe dẫn hướng (bánh xe trước). Lò xo (1) làm nhiệm vụ của bộ phận đàn hồi. Giảm chấn (2) được lắp trong lòng lò xo. Các thanh (4), (5) và (8) là các đòn của bộ phận dẫn hướng.","text":"Hình 11.21 thể hiện hệ thống treo sử dụng lò xo xoắn làm bộ phận đàn hồi. Đây là hệ thống treo độc lập lắp cho bánh xe dẫn hướng (bánh xe trước). Lò xo (1) làm nhiệm vụ của bộ phận đàn hồi. Giảm chấn (2) được lắp trong lòng lò xo. Các thanh (4), (5) và (8) là các đòn của bộ phận dẫn hướng.","pages":[123],"figure":{"number":"11.21","caption":"Hình 11.21 thể hiện hệ thống treo sử dụng lò xo xoắn làm bộ phận đàn hồi. Đây là hệ thống treo độc lập lắp cho bánh xe dẫn hướng (bánh xe trước). Lò xo (1) làm nhiệm vụ của bộ phận đàn hồi. Giảm chấn (2) được lắp trong lòng lò xo. Các thanh (4), (5) và (8) là các đòn của bộ phận dẫn hướng."}},{"id":"s1810","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"III. BỘ PHẬN ĐÀN HỒI Bộ phận đàn hồi tạo liên kết đàn hồi giữa khung hoặc vỏ xe với bánh xe, tiếp nhận lực thẳng đứng truyền từ khung hoặc vỏ xe xuống bánh xe và ngược lại. Bộ phận này chủ yếu gồm một chi tiết hoặc một cụm chi tiết đàn hồi, về bản chất là lò xo. Trên ô tô sử dụng các loại lò xo sau: - Lò xo kim loại, gồm các loại: + Lò xo xoắn; + Lò xo lá (nhíp lá); + Thanh xoắn. - Lò xo khí nén: chất khí có khả năng nén nên có thể được sử dụng làm phần tử đàn hồi trong hệ thống treo ô tô. 1. Bộ phận đàn hồi kim loại a) Loại lò xo Lò xo xoắn có cấu tạo đơn giản, dễ chế tạo, có trọng lượng nhỏ hơn nhiều so với lá nhíp. Nhược điểm của lò xo xoắn là chỉ chịu được lực thẳng đứng, không truyền được lực ngang hoặc lực dọc. Vì vậy, lò xo xoắn dùng trên hệ thống treo ô tô chỉ làm nhiệm vụ của bộ phận đàn hồi và hệ thống treo phải có bộ phận dẫn hướng riêng biệt.","pages":[123]},{"id":"s1811","kind":"pdf","lesson":"11.2.2","title":"Hệ thống treo · Bộ phận dẫn hướng hệ thống treo độc lập","text":"Cam quay; 8. Đòn dưới; 9. Thanh cân bằng. Bộ phận đàn hồi kim loại ở các hệ thống treo độc lập nói chung đều là lò xo xoắn (Hình 11.14, 11.15, 11.16, 11.17, 11.18, 11.19).","pages":[123]},{"id":"s1812","kind":"figure","lesson":"11.3.1","title":"Hình 11.22. Bộ phận đàn hồi dạng thanh xoắn a) Các dạng thanh xoắn: đơn và ghép; b) Bố trí thanh xoắn.","text":"Hình 11.22. Bộ phận đàn hồi dạng thanh xoắn a) Các dạng thanh xoắn: đơn và ghép; b) Bố trí thanh xoắn.","pages":[124],"figure":{"number":"11.22","caption":"Hình 11.22. Bộ phận đàn hồi dạng thanh xoắn a) Các dạng thanh xoắn: đơn và ghép; b) Bố trí thanh xoắn."}},{"id":"s1813","kind":"figure","lesson":"11.3.1","title":"Hình 11.23 thể hiện một bó nhíp lá dùng trên hệ thống treo ô tô. Hình 11.23b là bó nhíp đã lắp ghép hoàn chỉnh, còn Hình 11.23a thể hiện các chi tiết của bó nhíp. Bó nhíp trong hình có tám lá là những thanh kim loại cong, đàn hồi, tiết diện chữ nhật và chiều dài khác nhau, gồm lá nhíp cái (7) và bảy lá còn lại.","text":"Hình 11.23 thể hiện một bó nhíp lá dùng trên hệ thống treo ô tô. Hình 11.23b là bó nhíp đã lắp ghép hoàn chỉnh, còn Hình 11.23a thể hiện các chi tiết của bó nhíp. Bó nhíp trong hình có tám lá là những thanh kim loại cong, đàn hồi, tiết diện chữ nhật và chiều dài khác nhau, gồm lá nhíp cái (7) và bảy lá còn lại.","pages":[124],"figure":{"number":"11.23","caption":"Hình 11.23 thể hiện một bó nhíp lá dùng trên hệ thống treo ô tô. Hình 11.23b là bó nhíp đã lắp ghép hoàn chỉnh, còn Hình 11.23a thể hiện các chi tiết của bó nhíp. Bó nhíp trong hình có tám lá là những thanh kim loại cong, đàn hồi, tiết diện chữ nhật và chiều dài khác nhau, gồm lá nhíp cái (7) và bảy lá còn lại."}},{"id":"s1814","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Lò xo xoắn còn được sử dụng làm bộ phận đàn hồi trên hệ thống treo phụ thuộc (Hình 11.2, 11.3, 11.4, 11.5). Bộ phận đàn hồi là lò xo xoắn cũng có đường đặc tính tuyến tính như nhíp lá; do đó, nếu giảm độ cứng để tăng độ êm dịu thì biến dạng sẽ tăng và ảnh hưởng đến không gian treo của xe. b) Loại thanh xoắn Thanh xoắn có tiết diện tròn đặc hoặc tiết diện ghép hình lục lăng (Hình 11.22). Hai đầu thanh xoắn có tiết diện lục giác hoặc được gia công then để liên kết với các bộ phận của hệ thống treo. Thanh xoắn được chế tạo từ thép silic (thép hợp kim có độ đàn hồi cao), có kích thước và khối lượng nhỏ, dễ bố trí trong không gian dưới sàn xe. Để tăng khả năng chịu tải hoặc giảm kích thước, thanh xoắn được tạo ứng suất dư khi nhiệt luyện; ứng suất này có chiều ngược với ứng suất do tải trọng làm việc gây ra.","pages":[124]},{"id":"s1815","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Đầu thanh xoắn lắp ở bên phải ô tô thường có ký hiệu “R”, còn đầu lắp ở bên trái có ký hiệu “L” để tránh nhầm lẫn khi lắp ráp. 1. Khung xe; 2. Đòn ngang hệ thống treo; 3. Ốc điều chỉnh chiều cao thân xe; 4. Thanh xoắn; 5. Cơ cấu phanh bánh xe. Các bộ phận đàn hồi bằng kim loại trong hệ thống treo có đặc tính biến dạng được coi là tuyến tính. c) Loại nhíp Nhíp lá được sử dụng phổ biến trên hệ thống treo xe tải cỡ nhỏ và trung bình. Loại này có cấu tạo đơn giản, dễ chế tạo, dễ lắp ráp, giá thành thấp và phù hợp với xe không đòi hỏi độ êm dịu cao. Ví dụ: KamAZ 55111, Hyundai Mighty EX8, xe buýt Hyundai Aero Town.","pages":[124]},{"id":"s1816","kind":"figure","lesson":"11.3.1","title":"Hình 11.23. Cấu tạo nhíp lá a) Các chi tiết; b) Bó nhíp đã lắp ghép.","text":"Hình 11.23. Cấu tạo nhíp lá a) Các chi tiết; b) Bó nhíp đã lắp ghép.","pages":[125],"figure":{"number":"11.23","caption":"Hình 11.23. Cấu tạo nhíp lá a) Các chi tiết; b) Bó nhíp đã lắp ghép."}},{"id":"s1817","kind":"figure","lesson":"11.3.1","title":"Hình 11.24. Bán kính các lá nhíp Thông thường, khi chưa lắp ghép, bán kính cong của các lá nhíp không bằng nhau: các lá nhíp cái có bán kính cong lớn nhất, các lá còn lại có bán kính nhỏ dần (Hình 11.24).","text":"Hình 11.24. Bán kính các lá nhíp Thông thường, khi chưa lắp ghép, bán kính cong của các lá nhíp không bằng nhau: các lá nhíp cái có bán kính cong lớn nhất, các lá còn lại có bán kính nhỏ dần (Hình 11.24).","pages":[125],"figure":{"number":"11.24","caption":"Hình 11.24. Bán kính các lá nhíp Thông thường, khi chưa lắp ghép, bán kính cong của các lá nhíp không bằng nhau: các lá nhíp cái có bán kính cong lớn nhất, các lá còn lại có bán kính nhỏ dần (Hình 11.24)."}},{"id":"s1818","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"1. Lá nhíp; 2. Chốt nhíp; 3. Nẹp giữ; 4. Bu lông nẹp giữ; 5. Bu lông trung tâm; 6. Bạc của bu lông nẹp giữ; 7. Lá nhíp cái. Lá nhíp cái có chiều dài lớn nhất, các lá còn lại (1) có chiều dài nhỏ dần, lá cuối cùng có chiều dài nhỏ nhất. Các lá nhíp có chiều rộng giống nhau. Về chiều dày có thể có từ một đến ba nhóm (thường gặp là một hoặc hai nhóm) . Nếu chỉ có một nhóm thì chiều dày tất cả các lá giống nhau. Nếu có hai nhóm thì sẽ là nhóm lá nhíp cái (có chiều dài lớn nhất, còn gọi là nhíp chính) và nhóm lá còn lại. Nhóm nhíp cái có thể có một, hai hoặc ba lá. Nếu có một lá thì chiều dày lá nhíp cái lớn hơn chiều dày các lá còn lại. Ví dụ lá nhíp cái có chiều dày 9 mm, các lá còn lại 8 mm. Nếu nhóm nhíp cái có từ hai lá trở lên thì chiều dày của các lá nhíp cái giống nhau và nhỏ hơn chiều dày các lá còn lại.","pages":[125]},{"id":"s1819","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Ví dụ hai lá nhíp cái mỗi lá dày 8 mm, các lá nhóm còn lại 9 mm. Với cách bố trí như vậy, khi ghép lại với nhau các lá nhíp ôm khít vào nhau. Mặt khác, các lá nhíp phía trên chịu ứng suất lắp ghép ngược với ứng suất khi chịu tải (trọng lượng xe) nên ứng suất tổng giảm; tuy vậy, tác dụng này không nhiều. Nhóm lá nhíp cái đảm nhận nhiệm vụ lắp ghép với khung xe. Trên Hình 11.23, hai đầu lá nhíp cái (7) được cuốn lại thành một bản lề trụ và sẽ được lắp vào khung xe qua chốt nhíp (2).","pages":[125]},{"id":"s1820","kind":"figure","lesson":"11.3.1","title":"Hình 11.25. Lắp nhíp trên xe 1. Giá phía cố định; 2. Khung xe; 3. Giá phía di động; 4. Ụ cao su; 5. Giảm chấn; 6. Cầu","text":"Hình 11.25. Lắp nhíp trên xe 1. Giá phía cố định; 2. Khung xe; 3. Giá phía di động; 4. Ụ cao su; 5. Giảm chấn; 6. Cầu","pages":[126],"figure":{"number":"11.25","caption":"Hình 11.25. Lắp nhíp trên xe 1. Giá phía cố định; 2. Khung xe; 3. Giá phía di động; 4. Ụ cao su; 5. Giảm chấn; 6. Cầu"}},{"id":"s1821","kind":"figure","lesson":"11.3.1","title":"Hình 11.26. Lắp nhíp vào khung xe a) Dùng gối đỡ cao su: 1. Miếng đỡ trên và dưới; 2. Miếng chặn; 3. Giá đỡ trước; 4. Giá","text":"Hình 11.26. Lắp nhíp vào khung xe a) Dùng gối đỡ cao su: 1. Miếng đỡ trên và dưới; 2. Miếng chặn; 3. Giá đỡ trước; 4. Giá","pages":[126],"figure":{"number":"11.26","caption":"Hình 11.26. Lắp nhíp vào khung xe a) Dùng gối đỡ cao su: 1. Miếng đỡ trên và dưới; 2. Miếng chặn; 3. Giá đỡ trước; 4. Giá"}},{"id":"s1822","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"xe; 7. Bu lông quang nhíp; 8. Bó nhíp; 9. Chốt nhíp. Bu lông trung tâm (5) trên Hình 11.23 có nhiệm vụ ghép chặt các lá nhíp vào nhau. Để các lá nhíp không bị xô lệch, chúng được nẹp lại bằng nẹp (3), bu lông (4) và bạc (6). Nhíp là phần tử liên kết khung xe với cầu xe (hoặc bánh xe). Trong đa số trường hợp, nhíp vừa làm nhiệm vụ đàn hồi, vừa làm nhiệm vụ dẫn hướng. Bộ phận dẫn hướng truyền lực dọc, lực ngang và mô-men giữa bánh xe với thân xe, đồng thời bảo đảm quan hệ động học giữa bánh xe và khung xe. Các nhiệm vụ này quyết định cách lắp nhíp vào khung. Nhíp phải được lắp sao cho có thể truyền lực dọc, lực ngang và mô-men từ bánh xe lên thân xe và ngược lại, đồng thời bảo đảm bánh xe chỉ dao động trong mặt phẳng thẳng đứng của thân xe. b) Gối đỡ di động dùng quang treo: 1. Giá đỡ; 2. Quang treo; 3. Chốt quang treo; 4. Chốt nhíp; 5.","pages":[126]},{"id":"s1823","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Phần đầu lá nhíp cái (được cuộn tròn để lắp chốt nhíp).","pages":[126]},{"id":"s1824","kind":"figure","lesson":"11.3.1","title":"Hình 11.25 thể hiện cách lắp nhíp vào khung xe và cầu xe. Bó nhíp (8) liên kết đàn hồi khung xe (2) với cầu xe (6). Đồng thời, lực dọc, lực ngang và mô-men phải được truyền giữa cầu xe (6) với khung xe (2), còn cầu xe (6) chỉ được dịch chuyển tương đối với khung xe (2) trong mặt phẳng thẳng đứng.","text":"Hình 11.25 thể hiện cách lắp nhíp vào khung xe và cầu xe. Bó nhíp (8) liên kết đàn hồi khung xe (2) với cầu xe (6). Đồng thời, lực dọc, lực ngang và mô-men phải được truyền giữa cầu xe (6) với khung xe (2), còn cầu xe (6) chỉ được dịch chuyển tương đối với khung xe (2) trong mặt phẳng thẳng đứng.","pages":[127],"figure":{"number":"11.25","caption":"Hình 11.25 thể hiện cách lắp nhíp vào khung xe và cầu xe. Bó nhíp (8) liên kết đàn hồi khung xe (2) với cầu xe (6). Đồng thời, lực dọc, lực ngang và mô-men phải được truyền giữa cầu xe (6) với khung xe (2), còn cầu xe (6) chỉ được dịch chuyển tương đối với khung xe (2) trong mặt phẳng thẳng đứng."}},{"id":"s1825","kind":"figure","lesson":"11.3.1","title":"Hình 11.26 thể hiện một số cách lắp nhíp vào khung xe. Trên Hình 11.26a, nhíp được lắp bằng các miếng đỡ cao su (1) và miếng chặn (2). Các miếng đỡ cao su cho phép nhíp thay đổi chiều dài khi bán kính cong thay đổi.","text":"Hình 11.26 thể hiện một số cách lắp nhíp vào khung xe. Trên Hình 11.26a, nhíp được lắp bằng các miếng đỡ cao su (1) và miếng chặn (2). Các miếng đỡ cao su cho phép nhíp thay đổi chiều dài khi bán kính cong thay đổi.","pages":[127],"figure":{"number":"11.26","caption":"Hình 11.26 thể hiện một số cách lắp nhíp vào khung xe. Trên Hình 11.26a, nhíp được lắp bằng các miếng đỡ cao su (1) và miếng chặn (2). Các miếng đỡ cao su cho phép nhíp thay đổi chiều dài khi bán kính cong thay đổi."}},{"id":"s1826","kind":"figure","lesson":"11.3.1","title":"Hình 11.26b mô tả gối đỡ di động của nhíp. Đầu trái của nhíp được lắp qua bản lề trụ, tương tự đầu trái của nhíp ở Hình 11.25. Đầu phải của nhíp liên kết với khung xe qua quang treo (2). Giá treo (1) được tán chặt vào khung. Một đầu quang treo (2) lắp với giá (1) bằng chốt (3), đầu còn lại lắp với đầu phải của nhíp bằng chốt (4). Khi nhíp thay đổi chiều dài, quang treo (2) sẽ quay.","text":"Hình 11.26b mô tả gối đỡ di động của nhíp. Đầu trái của nhíp được lắp qua bản lề trụ, tương tự đầu trái của nhíp ở Hình 11.25. Đầu phải của nhíp liên kết với khung xe qua quang treo (2). Giá treo (1) được tán chặt vào khung. Một đầu quang treo (2) lắp với giá (1) bằng chốt (3), đầu còn lại lắp với đầu phải của nhíp bằng chốt (4). Khi nhíp thay đổi chiều dài, quang treo (2) sẽ quay.","pages":[127],"figure":{"number":"11.26b","caption":"Hình 11.26b mô tả gối đỡ di động của nhíp. Đầu trái của nhíp được lắp qua bản lề trụ, tương tự đầu trái của nhíp ở Hình 11.25. Đầu phải của nhíp liên kết với khung xe qua quang treo (2). Giá treo (1) được tán chặt vào khung. Một đầu quang treo (2) lắp với giá (1) bằng chốt (3), đầu còn lại lắp với đầu phải của nhíp bằng chốt (4). Khi nhíp thay đổi chiều dài, quang treo (2) sẽ quay."}},{"id":"s1827","kind":"figure","lesson":"11.3.1","title":"Hình 11.27. Lắp nhíp vào khung xe 1. Khung xe; 2. Giá đỡ phía di động; 3. Giá đỡ phía cố định; 4. Chốt quang treo; 5.","text":"Hình 11.27. Lắp nhíp vào khung xe 1. Khung xe; 2. Giá đỡ phía di động; 3. Giá đỡ phía cố định; 4. Chốt quang treo; 5.","pages":[127],"figure":{"number":"11.27","caption":"Hình 11.27. Lắp nhíp vào khung xe 1. Khung xe; 2. Giá đỡ phía di động; 3. Giá đỡ phía cố định; 4. Chốt quang treo; 5."}},{"id":"s1828","kind":"figure","lesson":"11.3.1","title":"Hình 11.27 thể hiện mặt cắt vị trí lắp ghép hai đầu nhíp: một đầu cố định và một đầu di động. Hình 11.27a là đầu cố định, còn Hình 11.27b là đầu di động. Các lá nhíp cái (9) được cuốn thành hình trụ và lắp bạc kim loại (8). Để bôi trơn, các vú mỡ (7) được lắp vào chốt nhíp (6). Khi bơm, mỡ theo đường dẫn khoan trong chốt nhíp đến bôi trơn bề mặt tiếp xúc giữa bạc (8) và chốt nhíp (6). Tương tự các trường hợp trên, các giá đỡ (2) và (3) được tán vào khung xe (1). Ở đầu di động, quang treo (5) có một đầu lắp với giá (2) bằng chốt (4), đầu còn lại lắp với nhíp bằng chốt nhíp (6).","text":"Hình 11.27 thể hiện mặt cắt vị trí lắp ghép hai đầu nhíp: một đầu cố định và một đầu di động. Hình 11.27a là đầu cố định, còn Hình 11.27b là đầu di động. Các lá nhíp cái (9) được cuốn thành hình trụ và lắp bạc kim loại (8). Để bôi trơn, các vú mỡ (7) được lắp vào chốt nhíp (6). Khi bơm, mỡ theo đường dẫn khoan trong chốt nhíp đến bôi trơn bề mặt tiếp xúc giữa bạc (8) và chốt nhíp (6). Tương tự các trường hợp trên, các giá đỡ (2) và (3) được tán vào khung xe (1). Ở đầu di động, quang treo (5) có một đầu lắp với giá (2) bằng chốt (4), đầu còn lại lắp với nhíp bằng chốt nhíp (6).","pages":[127],"figure":{"number":"11.27","caption":"Hình 11.27 thể hiện mặt cắt vị trí lắp ghép hai đầu nhíp: một đầu cố định và một đầu di động. Hình 11.27a là đầu cố định, còn Hình 11.27b là đầu di động. Các lá nhíp cái (9) được cuốn thành hình trụ và lắp bạc kim loại (8). Để bôi trơn, các vú mỡ (7) được lắp vào chốt nhíp (6). Khi bơm, mỡ theo đường dẫn khoan trong chốt nhíp đến bôi trơn bề mặt tiếp xúc giữa bạc (8) và chốt nhíp (6). Tương tự các trường hợp trên, các giá đỡ (2) và (3) được tán vào khung xe (1). Ở đầu di động, quang treo (5) có một đầu lắp với giá (2) bằng chốt (4), đầu còn lại lắp với nhíp bằng chốt nhíp (6)."}},{"id":"s1829","kind":"figure","lesson":"11.3.1","title":"Hình 11.28 thể hiện cách tạo ra kết cấu để bắt chốt nhíp ở đầu mút lá nhíp. Hình 11.28a chỉ có một lá nhíp được cuốn lại và được lắp bạc chốt nhíp vào. Hình 11.28b có thêm một lá được cuốn vào nhưng chỉ cuốn một phần, còn ở Hình 11.28c thì lá thứ hai được cuốn hết nhưng không cuốn sát vào mà có khoảng trống như hình vẽ.","text":"Hình 11.28 thể hiện cách tạo ra kết cấu để bắt chốt nhíp ở đầu mút lá nhíp. Hình 11.28a chỉ có một lá nhíp được cuốn lại và được lắp bạc chốt nhíp vào. Hình 11.28b có thêm một lá được cuốn vào nhưng chỉ cuốn một phần, còn ở Hình 11.28c thì lá thứ hai được cuốn hết nhưng không cuốn sát vào mà có khoảng trống như hình vẽ.","pages":[127],"figure":{"number":"11.28","caption":"Hình 11.28 thể hiện cách tạo ra kết cấu để bắt chốt nhíp ở đầu mút lá nhíp. Hình 11.28a chỉ có một lá nhíp được cuốn lại và được lắp bạc chốt nhíp vào. Hình 11.28b có thêm một lá được cuốn vào nhưng chỉ cuốn một phần, còn ở Hình 11.28c thì lá thứ hai được cuốn hết nhưng không cuốn sát vào mà có khoảng trống như hình vẽ."}},{"id":"s1830","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Cầu xe (6) được bắt chặt với bó nhíp (8) bằng hai bu lông quang nhíp (7). Ở phía trái (phía cố định), bó nhíp bắt với khung xe bằng khớp bản lề trụ, qua chốt nhíp (9) tại giá (1) và có thể quay quanh chốt nhíp (9) trong mặt phẳng thẳng đứng. Ở phía phải (phía di động), bó nhíp tựa lên giá (3). Các giá (1) và (3) được tán vào khung xe (2). Quang treo; 6. Chốt nhíp; 7. Vú mỡ; 8. Bạc chốt nhíp; 9. Các lá nhíp cái.","pages":[127]},{"id":"s1831","kind":"figure","lesson":"11.3.1","title":"Hình 11.29. Đường đặc tính đàn hồi","text":"Hình 11.29. Đường đặc tính đàn hồi","pages":[128],"figure":{"number":"11.29","caption":"Hình 11.29. Đường đặc tính đàn hồi"}},{"id":"s1832","kind":"figure","lesson":"11.3.1","title":"Hình 11.30. Nhíp kép Loại thường dùng ở cầu sau xe tải là nhíp kép, như minh họa ở Hình 11.30. Hệ thống treo có hai bó nhíp: nhíp chính và nhíp phụ. Nhíp chính được lắp vào khung xe như nhíp đơn; nhíp phụ và nhíp chính cùng được bắt chặt vào cầu xe bằng quang nhíp. Khi xe không tải hoặc non tải, chỉ nhíp chính làm việc. Khi tải trọng lên cầu đạt giá trị nhất định, nhíp phụ tựa vào giá trên khung xe và bắt đầu làm việc. Khi cả hai nhíp cùng làm việc, độ cứng của bộ phận đàn hồi tăng lên (đường (2) trên Hình 11.29).","text":"Hình 11.30. Nhíp kép Loại thường dùng ở cầu sau xe tải là nhíp kép, như minh họa ở Hình 11.30. Hệ thống treo có hai bó nhíp: nhíp chính và nhíp phụ. Nhíp chính được lắp vào khung xe như nhíp đơn; nhíp phụ và nhíp chính cùng được bắt chặt vào cầu xe bằng quang nhíp. Khi xe không tải hoặc non tải, chỉ nhíp chính làm việc. Khi tải trọng lên cầu đạt giá trị nhất định, nhíp phụ tựa vào giá trên khung xe và bắt đầu làm việc. Khi cả hai nhíp cùng làm việc, độ cứng của bộ phận đàn hồi tăng lên (đường (2) trên Hình 11.29).","pages":[128],"figure":{"number":"11.30","caption":"Hình 11.30. Nhíp kép Loại thường dùng ở cầu sau xe tải là nhíp kép, như minh họa ở Hình 11.30. Hệ thống treo có hai bó nhíp: nhíp chính và nhíp phụ. Nhíp chính được lắp vào khung xe như nhíp đơn; nhíp phụ và nhíp chính cùng được bắt chặt vào cầu xe bằng quang nhíp. Khi xe không tải hoặc non tải, chỉ nhíp chính làm việc. Khi tải trọng lên cầu đạt giá trị nhất định, nhíp phụ tựa vào giá trên khung xe và bắt đầu làm việc. Khi cả hai nhíp cùng làm việc, độ cứng của bộ phận đàn hồi tăng lên (đường (2) trên Hình 11.29)."}},{"id":"s1833","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"a) b) c) Hình 11.28. Các kết cấu đầu mút lá nhíp * Nhíp có độ cứng thay đổi Nhíp cũng như các chi tiết đàn hồi kim loại có một đặc điểm chung là có đường đặc tính đàn hồi tuyến tính (đường (1) trên Hình 11.29). Trong đó, F là lực tác dụng lên bộ phận đàn hồi,  là biến dạng của bộ phận đàn hồi. Độ cứng C của bộ phận đàn hồi được tính theo biểu thức: Như vậy, nhíp và các chi tiết đàn hồi kim loại có độ cứng không đổi. Đối với xe có tải trọng thay đổi, bộ nhíp được thiết kế để bảo đảm độ bền khi đầy tải thường quá cứng ở trạng thái tải nhỏ; ngược lại, bộ nhíp đáp ứng độ êm dịu khi tải nhỏ có thể không đủ bền khi đầy tải. Ở cầu sau xe tải, tải trọng phân bố lên cầu khi đầy tải có thể lớn gấp khoảng 2,5 lần khi không tải; vì vậy, nhíp có độ cứng không đổi như ở Hình 11.25 khó đồng thời đáp ứng yêu cầu về độ êm dịu và độ bền.","pages":[128]},{"id":"s1834","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Để khắc phục, ô tô sử dụng nhíp có độ cứng thay đổi.","pages":[128]},{"id":"s1835","kind":"figure","lesson":"11.3.1","title":"Hình 11.31. Nhíp thay đổi độ cứng a) Thay đổi chiều dài hiệu dụng của nhíp: 1. Giá đỡ phía cố định; 2, 3. Giá đỡ phía di động;","text":"Hình 11.31. Nhíp thay đổi độ cứng a) Thay đổi chiều dài hiệu dụng của nhíp: 1. Giá đỡ phía cố định; 2, 3. Giá đỡ phía di động;","pages":[129],"figure":{"number":"11.31","caption":"Hình 11.31. Nhíp thay đổi độ cứng a) Thay đổi chiều dài hiệu dụng của nhíp: 1. Giá đỡ phía cố định; 2, 3. Giá đỡ phía di động;"}},{"id":"s1836","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Ngoài ra, còn có nhiều kết cấu nhíp thay đổi độ cứng. Hình 11.31 thể hiện hai sơ đồ điển hình. Ở Hình 11.31a, một đầu nhíp bắt bản lề với khung xe tại gối (1), đầu còn lại tựa vào hai gối (2) và (3). Khi xe non tải, nhíp tựa vào gối (3); khi tải trọng đạt giá trị tính toán, nhíp sẽ tựa thêm vào gối (2). Do chiều dài hiệu dụng thay đổi theo điểm tựa nên độ cứng của nhíp cũng thay đổi. Ở Hình 11.31b, nhíp được chia thành hai nhóm: nhóm thứ nhất gồm các lá (1), (2), còn nhóm thứ hai gồm các lá (3), (4). Do bán kính cong của hai nhóm khác nhau, khi tải trọng nhỏ chỉ nhóm thứ nhất làm việc; khi tải trọng đạt giá trị tính toán, cả hai nhóm cùng làm việc, làm tăng độ cứng của nhíp. b) Thay đổi số lá làm việc: 1, 2. Nhóm lá thứ nhất; 3, 4. Nhóm lá thứ hai. 2.","pages":[129]},{"id":"s1837","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Bộ phận đàn hồi phi kim loại a) Loại cao su Bộ phận đàn hồi bằng cao su được dùng làm vấu hạn chế biến dạng và tăng cứng. Khi tải trọng tăng, hệ thống treo biến dạng lớn, cầu xe tỳ vào khung xe qua vấu cao su. Do có độ cứng lớn, vấu cao su làm tăng độ cứng tổng thể của bộ phận đàn hồi và giảm va đập tác dụng lên thân xe. Như vậy, vấu cao su vừa tham gia đàn hồi, vừa hạn chế hành trình của bánh xe. Trên một số ô tô, cao su có thể được dùng làm bộ phận đàn hồi chính; tuy nhiên, trên phần lớn ô tô, các chi tiết cao su được bố trí tại điểm tỳ của nhíp lá hoặc lò xo xoắn để hạn chế hành trình, giảm va đập cứng và tăng độ êm dịu cho hệ thống treo. b) Loại khí nén Chất khí có khả năng nén nên có thể được dùng làm phần tử đàn hồi. Lò xo khí nén thực hiện chức năng của bộ phận đàn hồi; hệ thống sử dụng loại lò xo này được gọi là hệ thống treo khí nén.","pages":[129]},{"id":"s1838","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Hệ thống treo khí nén đã được ứng dụng trên ô tô từ đầu thế kỷ XX. Ví dụ: Xe khách Hyundai Universe, Mercedes-Benz Sprinter, xe buýt BRT. Bộ phận đàn hồi khí nén có ưu điểm: - Đường đặc tính đàn hồi có dạng phi tuyến; đặc tính này có thể làm giảm không gian treo của xe. - Độ cứng của bộ phận đàn hồi phụ thuộc vào áp suất khí nén; vì vậy, có thể thay đổi độ cứng bằng cách điều chỉnh áp suất. Đây là ưu điểm nổi bật, cho phép điều chỉnh độ cứng theo điều kiện vận hành, chẳng hạn khi tải trọng thay đổi.","pages":[129]},{"id":"s1839","kind":"figure","lesson":"11.3.1","title":"Hình 11.33. Bộ phận đàn hồi khí nén 1. Giá đỡ bắt với khung xe; 2. Vỏ cao su; 3. Vành kim loại; 4. Giá đỡ bắt với cầu xe; 5. Ụ","text":"Hình 11.33. Bộ phận đàn hồi khí nén 1. Giá đỡ bắt với khung xe; 2. Vỏ cao su; 3. Vành kim loại; 4. Giá đỡ bắt với cầu xe; 5. Ụ","pages":[130],"figure":{"number":"11.33","caption":"Hình 11.33. Bộ phận đàn hồi khí nén 1. Giá đỡ bắt với khung xe; 2. Vỏ cao su; 3. Vành kim loại; 4. Giá đỡ bắt với cầu xe; 5. Ụ"}},{"id":"s1840","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"a) b) Hình 11.32. Bộ phận đàn hồi khí nén a) Bầu khí có vỏ cao su; b) Bầu khí có vỏ kim loại và cao su; 1. Vỏ cao su; 2. Vành kim loại; 3. Giá đỡ; 4. Bu lông; 5. Đế; 6. Màng cao su; 7. Vỏ kim loại. Cấu tạo của bộ phận đàn hồi khí nén: Lò xo khí nén ứng dụng tính chất chịu nén của chất khí để làm bộ phận đàn hồi, thay thế hoặc hỗ trợ cho nhíp lá hay lò xo xoắn kim loại truyền thống. Về mặt kết cấu cơ khí, bộ phận này thường được chia thành hai dạng chính như sau: Dạng bầu xếp: Như minh họa ở Hình 11.32a và Hình 11.33, bộ phận chính là bầu chứa khí có vỏ cao su đặc biệt, được gia cường bằng nhiều lớp mành sợi tổng hợp hoặc sợi ni-lông để chịu áp suất cao và chống mỏi. Ở Hình 11.32a, vỏ cao su (1) được định hình bằng các vành kim loại (2), (3) để hạn chế phình ngang khi chịu tải; toàn bộ cụm được làm kín và cố định bằng bu lông (4).","pages":[130]},{"id":"s1841","kind":"pdf","lesson":"11.3.1","title":"Hệ thống treo · Bộ phận đàn hồi kim loại","text":"Ở Hình 11.33, giá đỡ phía trên (1) bắt chặt vào khung xe, còn giá đỡ phía dưới (4) liên kết trực tiếp với dầm cầu hoặc trục bánh xe; vỏ cao su (2) và vành kim loại (3) tạo thành bầu khí kín. Bên trong cụm lò xo khí thường tích hợp ụ hạn chế hành trình (5), đóng vai trò đệm va đập và bảo vệ bầu khí khỏi bị xẹp hoàn toàn hoặc hư hỏng khi xe quá tải hay sập gầm. Bộ phận đàn hồi khí nén còn cho phép thay đổi độ cao thân xe. Tính năng này đặc biệt hữu ích đối với xe buýt: khi đến bến, lái xe có thể hạ thấp thân xe để bậc lên xuống gần ngang với vỉa hè, giúp hành khách lên xuống dễ dàng.","pages":[130]},{"id":"s1842","kind":"figure","lesson":"11.3.2","title":"Hình 11.34. Hệ thống treo có bộ phận đàn hồi khí nén điều chỉnh được độ cứng 1. Máy nén khí; 2. Bình khí; 3, 4. Van điều chỉnh; 5. Bình tích áp; 6. Bộ phận đàn hồi; 7.","text":"Hình 11.34. Hệ thống treo có bộ phận đàn hồi khí nén điều chỉnh được độ cứng 1. Máy nén khí; 2. Bình khí; 3, 4. Van điều chỉnh; 5. Bình tích áp; 6. Bộ phận đàn hồi; 7.","pages":[131],"figure":{"number":"11.34","caption":"Hình 11.34. Hệ thống treo có bộ phận đàn hồi khí nén điều chỉnh được độ cứng 1. Máy nén khí; 2. Bình khí; 3, 4. Van điều chỉnh; 5. Bình tích áp; 6. Bộ phận đàn hồi; 7."}},{"id":"s1843","kind":"figure","lesson":"11.3.2","title":"Hình 11.34 thể hiện sơ đồ hệ thống treo có bộ phận đàn hồi khí nén, trong đó độ cứng được điều chỉnh theo độ võng tĩnh. Các bầu lò xo khí (6) được đặt giữa khung xe (7) và cầu xe (8). Máy nén khí (1) cung cấp khí nén cho bình khí (2). Khí nén từ bình (2) đi qua van điều chỉnh (3), (4), đến bình tích áp (5) rồi vào các bầu lò xo khí (6). Vỏ van điều chỉnh (3) bắt với khung xe, còn con trượt (4) nối với cầu xe (8) qua các đòn (9), (10).","text":"Hình 11.34 thể hiện sơ đồ hệ thống treo có bộ phận đàn hồi khí nén, trong đó độ cứng được điều chỉnh theo độ võng tĩnh. Các bầu lò xo khí (6) được đặt giữa khung xe (7) và cầu xe (8). Máy nén khí (1) cung cấp khí nén cho bình khí (2). Khí nén từ bình (2) đi qua van điều chỉnh (3), (4), đến bình tích áp (5) rồi vào các bầu lò xo khí (6). Vỏ van điều chỉnh (3) bắt với khung xe, còn con trượt (4) nối với cầu xe (8) qua các đòn (9), (10).","pages":[131],"figure":{"number":"11.34","caption":"Hình 11.34 thể hiện sơ đồ hệ thống treo có bộ phận đàn hồi khí nén, trong đó độ cứng được điều chỉnh theo độ võng tĩnh. Các bầu lò xo khí (6) được đặt giữa khung xe (7) và cầu xe (8). Máy nén khí (1) cung cấp khí nén cho bình khí (2). Khí nén từ bình (2) đi qua van điều chỉnh (3), (4), đến bình tích áp (5) rồi vào các bầu lò xo khí (6). Vỏ van điều chỉnh (3) bắt với khung xe, còn con trượt (4) nối với cầu xe (8) qua các đòn (9), (10)."}},{"id":"s1844","kind":"pdf","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"Điều chỉnh độ cứng của bộ phận đàn hồi khí nén Như đã đề cập, trọng lượng tác dụng lên hệ thống treo thay đổi theo tải trọng của xe. Đặc biệt, đối với cầu sau xe tải, chênh lệch tải trọng giữa trạng thái không tải và đầy tải rất lớn. Phần trước đã giới thiệu một số kết cấu nhíp thay đổi độ cứng cho phù hợp với tải trọng, tuy nhiên các kết cấu này chỉ đáp ứng được một số trường hợp nhất định. Đối với bộ phận đàn hồi khí nén, việc thay đổi độ cứng dễ dàng và hiệu quả hơn nhiều. Độ cứng của bộ phận đàn hồi khí nén phụ thuộc vào áp suất khí bên trong; vì vậy, có thể thay đổi độ cứng bằng cách điều chỉnh áp suất. Áp suất được điều chỉnh theo tải trọng tác dụng lên bộ phận đàn hồi: tải trọng tăng thì độ cứng tăng và ngược lại.","pages":[131]},{"id":"s1845","kind":"pdf","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"Khi tải trọng thay đổi, khoảng cách giữa khung xe với bánh xe (hoặc cầu xe) cũng thay đổi; vì vậy, có thể điều khiển độ cứng theo khoảng cách này. Biến dạng của hệ thống treo dưới tải trọng tĩnh được gọi là độ võng tĩnh. Đại lượng này được dùng để điều chỉnh áp suất trong bộ phận đàn hồi khí nén, tức là điều chỉnh độ cứng. Vỏ van điều chỉnh (3) có ba cửa: một cửa nối với bình khí (2), một cửa nối với bình tích áp (5) và một cửa thông ra khí trời. Khi tải trọng xe thay đổi, khoảng cách giữa cầu xe (8) và khung xe (7) thay đổi, làm con trượt (4) dịch chuyển trong vỏ van (3). Khi tải trọng tăng, khoảng cách giữa cầu xe và khung xe giảm, con trượt (4) dịch chuyển xuống dưới, mở đường dẫn khí nén từ bình khí (2) vào bình tích áp (5)","pages":[131]},{"id":"s1846","kind":"figure","lesson":"11.3.2","title":"Hình 11.35. Bộ phận đàn hồi thủy lực - khí nén dùng pít-tông - xi-lanh 1. Tai bộ phận đàn hồi; 2. Van thủy lực; 3. Bầu thủy lực - khí nén; 4. Màng đàn hồi; 5.","text":"Hình 11.35. Bộ phận đàn hồi thủy lực - khí nén dùng pít-tông - xi-lanh 1. Tai bộ phận đàn hồi; 2. Van thủy lực; 3. Bầu thủy lực - khí nén; 4. Màng đàn hồi; 5.","pages":[132],"figure":{"number":"11.35","caption":"Hình 11.35. Bộ phận đàn hồi thủy lực - khí nén dùng pít-tông - xi-lanh 1. Tai bộ phận đàn hồi; 2. Van thủy lực; 3. Bầu thủy lực - khí nén; 4. Màng đàn hồi; 5."}},{"id":"s1847","kind":"figure","lesson":"11.3.2","title":"Hình 11.35 thể hiện kết cấu bộ phận đàn hồi thủy lực - khí nén dùng pít-tông - xi-lanh. Vỏ bộ phận gồm bầu thủy lực - khí nén (3) và xi-lanh kim loại (5). Màng cao su đàn hồi (4) chia bầu (3) thành hai khoang B và C. Khoang C được nạp khí trơ hoặc nitơ một lần. Pít-tông (6) cùng xi-lanh (5) tạo thành khoang A chứa chất lỏng. Khoang A và B nối với nhau qua cụm van thủy lực (2), hoạt động tương tự các van của giảm chấn; vì vậy, bộ phận này đồng thời thực hiện chức năng giảm chấn. Chất lỏng được dẫn vào khoang A qua đường I. Tai (1) gắn với xi-lanh là vị trí lắp bộ phận vào khung xe; phía dưới, cần pít-tông (7) bắt với bánh xe (hoặc cầu xe). Áp suất khí trong khoang C bằng áp suất chất lỏng trong khoang B. Bộ phận có thể đặt thẳng đứng, đặt nghiêng hoặc nằm ngang. Khi xe đi qua mấp mô, bánh xe dao động làm pít-tông (6) trượt trong xi-lanh (5), đẩy chất lỏng từ khoang A sang khoang B và tạo áp lực lên màng (4). Khí","text":"Hình 11.35 thể hiện kết cấu bộ phận đàn hồi thủy lực - khí nén dùng pít-tông - xi-lanh. Vỏ bộ phận gồm bầu thủy lực - khí nén (3) và xi-lanh kim loại (5). Màng cao su đàn hồi (4) chia bầu (3) thành hai khoang B và C. Khoang C được nạp khí trơ hoặc nitơ một lần. Pít-tông (6) cùng xi-lanh (5) tạo thành khoang A chứa chất lỏng. Khoang A và B nối với nhau qua cụm van thủy lực (2), hoạt động tương tự các van của giảm chấn; vì vậy, bộ phận này đồng thời thực hiện chức năng giảm chấn. Chất lỏng được dẫn vào khoang A qua đường I. Tai (1) gắn với xi-lanh là vị trí lắp bộ phận vào khung xe; phía dưới, cần pít-tông (7) bắt với bánh xe (hoặc cầu xe). Áp suất khí trong khoang C bằng áp suất chất lỏng trong khoang B. Bộ phận có thể đặt thẳng đứng, đặt nghiêng hoặc nằm ngang. Khi xe đi qua mấp mô, bánh xe dao động làm pít-tông (6) trượt trong xi-lanh (5), đẩy chất lỏng từ khoang A sang khoang B và tạo áp lực lên màng (4). Khí","pages":[132],"figure":{"number":"11.35","caption":"Hình 11.35 thể hiện kết cấu bộ phận đàn hồi thủy lực - khí nén dùng pít-tông - xi-lanh. Vỏ bộ phận gồm bầu thủy lực - khí nén (3) và xi-lanh kim loại (5). Màng cao su đàn hồi (4) chia bầu (3) thành hai khoang B và C. Khoang C được nạp khí trơ hoặc nitơ một lần. Pít-tông (6) cùng xi-lanh (5) tạo thành khoang A chứa chất lỏng. Khoang A và B nối với nhau qua cụm van thủy lực (2), hoạt động tương tự các van của giảm chấn; vì vậy, bộ phận này đồng thời thực hiện chức năng giảm chấn. Chất lỏng được dẫn vào khoang A qua đường I. Tai (1) gắn với xi-lanh là vị trí lắp bộ phận vào khung xe; phía dưới, cần pít-tông (7) bắt với bánh xe (hoặc cầu xe). Áp suất khí trong khoang C bằng áp suất chất lỏng trong khoang B. Bộ phận có thể đặt thẳng đứng, đặt nghiêng hoặc nằm ngang. Khi xe đi qua mấp mô, bánh xe dao động làm pít-tông (6) trượt trong xi-lanh (5), đẩy chất lỏng từ khoang A sang khoang B và tạo áp lực lên màng (4). Khí"}},{"id":"s1848","kind":"pdf","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"và làm tăng áp suất trong bầu lò xo khí. Khi áp suất tăng, cầu xe dịch chuyển ra xa khung xe, con trượt đi lên và đóng đường khí đến bình tích áp (5). Ngược lại, khi tải trọng giảm, con trượt (4) đi lên và mở đường thông từ bình tích áp (5) ra khí trời, làm áp suất trong các bầu lò xo khí giảm. c) Loại liên hợp thủy lực - khí nén Xi-lanh; 6. Pít-tông; 7. Cần pít-tông. Phương pháp điều chỉnh áp suất bằng cách thêm hoặc bớt khí nén trong các bầu lò xo khí có nhược điểm là độ nhạy thấp. Mặt khác, khí lấy từ khí quyển có thể chứa tạp chất, ảnh hưởng đến độ bền của bầu khí. Bộ phận đàn hồi thủy lực - khí nén, chứa cả chất khí và chất lỏng, khắc phục được các nhược điểm này. Chất khí tạo tính đàn hồi và chỉ được nạp một lần, còn chất lỏng dùng để điều chỉnh áp suất. Citroën nổi tiếng với việc ứng dụng hệ thống treo thủy lực - khí nén trên các dòng DS, CX và XM.","pages":[132]},{"id":"s1849","kind":"pdf","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"Gần đây, Mercedes-Benz S-Class và Rolls-Royce Phantom cũng sử dụng các biến thể của hệ thống treo liên hợp thủy lực - khí nén để nâng cao độ êm dịu và tiện nghi.","pages":[132]},{"id":"s1850","kind":"figure","lesson":"11.3.2","title":"Hình 11.36. Bộ phận đàn hồi thủy lực - khí nén dùng màng đàn hồi 1. Đế; 2. Vỏ; 3. Van thủy lực; 4, 6. Màng đàn hồi; 5. Đường ống dẫn chất lỏng.","text":"Hình 11.36. Bộ phận đàn hồi thủy lực - khí nén dùng màng đàn hồi 1. Đế; 2. Vỏ; 3. Van thủy lực; 4, 6. Màng đàn hồi; 5. Đường ống dẫn chất lỏng.","pages":[133],"figure":{"number":"11.36","caption":"Hình 11.36. Bộ phận đàn hồi thủy lực - khí nén dùng màng đàn hồi 1. Đế; 2. Vỏ; 3. Van thủy lực; 4, 6. Màng đàn hồi; 5. Đường ống dẫn chất lỏng."}},{"id":"s1851","kind":"figure","lesson":"11.3.2","title":"Hình 11.36 thể hiện kết cấu bộ phận đàn hồi thủy lực - khí nén dùng màng đàn hồi. Vỏ (2) bắt với khung (hoặc vỏ) xe, còn đế (1) bắt với bánh xe. Khoang A chứa khí nén; các khoang B và C chứa chất lỏng. Chất lỏng được cấp qua đường ống (5). Giữa khoang B và C có các van nằm trong cụm van thủy lực (3). Khoang C được tạo bởi vỏ (2) và màng cao su (6). Màng (6) gắn với vỏ (2), còn màng (4) ngăn cách khoang B với khoang A. Khi bánh xe dao động, lực truyền qua đế (1) tác dụng lên màng (6), làm thay đổi áp suất trong bộ phận đàn hồi.","text":"Hình 11.36 thể hiện kết cấu bộ phận đàn hồi thủy lực - khí nén dùng màng đàn hồi. Vỏ (2) bắt với khung (hoặc vỏ) xe, còn đế (1) bắt với bánh xe. Khoang A chứa khí nén; các khoang B và C chứa chất lỏng. Chất lỏng được cấp qua đường ống (5). Giữa khoang B và C có các van nằm trong cụm van thủy lực (3). Khoang C được tạo bởi vỏ (2) và màng cao su (6). Màng (6) gắn với vỏ (2), còn màng (4) ngăn cách khoang B với khoang A. Khi bánh xe dao động, lực truyền qua đế (1) tác dụng lên màng (6), làm thay đổi áp suất trong bộ phận đàn hồi.","pages":[133],"figure":{"number":"11.36","caption":"Hình 11.36 thể hiện kết cấu bộ phận đàn hồi thủy lực - khí nén dùng màng đàn hồi. Vỏ (2) bắt với khung (hoặc vỏ) xe, còn đế (1) bắt với bánh xe. Khoang A chứa khí nén; các khoang B và C chứa chất lỏng. Chất lỏng được cấp qua đường ống (5). Giữa khoang B và C có các van nằm trong cụm van thủy lực (3). Khoang C được tạo bởi vỏ (2) và màng cao su (6). Màng (6) gắn với vỏ (2), còn màng (4) ngăn cách khoang B với khoang A. Khi bánh xe dao động, lực truyền qua đế (1) tác dụng lên màng (6), làm thay đổi áp suất trong bộ phận đàn hồi."}},{"id":"s1852","kind":"figure","lesson":"11.3.2","title":"Hình 11.37. Sơ đồ hệ thống treo thủy lực - khí nén 1. Bộ phận đàn hồi; 2. Bình chứa chất lỏng; 3. Bơm; 4. Bình tích áp; 5. Van điều khiển.","text":"Hình 11.37. Sơ đồ hệ thống treo thủy lực - khí nén 1. Bộ phận đàn hồi; 2. Bình chứa chất lỏng; 3. Bơm; 4. Bình tích áp; 5. Van điều khiển.","pages":[133],"figure":{"number":"11.37","caption":"Hình 11.37. Sơ đồ hệ thống treo thủy lực - khí nén 1. Bộ phận đàn hồi; 2. Bình chứa chất lỏng; 3. Bơm; 4. Bình tích áp; 5. Van điều khiển."}},{"id":"s1853","kind":"figure","lesson":"11.3.2","title":"Hình 11.37 thể hiện sơ đồ hệ thống treo trong đó áp suất khí của bộ phận đàn hồi được điều chỉnh gián tiếp bằng cách thay đổi áp suất chất lỏng cấp đến bộ phận này. Chất lỏng được cấp từ bình chứa (2) nhờ bơm (3). Trước khi đến bộ phận đàn hồi (1), chất lỏng đi qua bình tích áp (4). Vì áp suất của chất khí và chất lỏng trong bộ phận đàn hồi bằng nhau nên chỉ cần điều chỉnh áp suất chất lỏng. Van điều khiển (5)","text":"Hình 11.37 thể hiện sơ đồ hệ thống treo trong đó áp suất khí của bộ phận đàn hồi được điều chỉnh gián tiếp bằng cách thay đổi áp suất chất lỏng cấp đến bộ phận này. Chất lỏng được cấp từ bình chứa (2) nhờ bơm (3). Trước khi đến bộ phận đàn hồi (1), chất lỏng đi qua bình tích áp (4). Vì áp suất của chất khí và chất lỏng trong bộ phận đàn hồi bằng nhau nên chỉ cần điều chỉnh áp suất chất lỏng. Van điều khiển (5)","pages":[133],"figure":{"number":"11.37","caption":"Hình 11.37 thể hiện sơ đồ hệ thống treo trong đó áp suất khí của bộ phận đàn hồi được điều chỉnh gián tiếp bằng cách thay đổi áp suất chất lỏng cấp đến bộ phận này. Chất lỏng được cấp từ bình chứa (2) nhờ bơm (3). Trước khi đến bộ phận đàn hồi (1), chất lỏng đi qua bình tích áp (4). Vì áp suất của chất khí và chất lỏng trong bộ phận đàn hồi bằng nhau nên chỉ cần điều chỉnh áp suất chất lỏng. Van điều khiển (5)"}},{"id":"s1854","kind":"pdf","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"trong khoang C đóng vai trò đàn hồi. Vì khí chỉ được nạp một lần nên có thể chọn loại khí ít ảnh hưởng đến độ bền của màng (4) và vỏ (3). Việc điều chỉnh áp suất trong bộ phận đàn hồi thủy lực - khí nén được thực hiện bằng cách thay đổi áp suất chất lỏng (xem sơ đồ Hình 11.37).","pages":[133]},{"id":"s1855","kind":"figure","lesson":"11.3.2","title":"Hình 11.38. Van điều khiển 1. Thân van; 2, 5. Màng đàn hồi; 3. Con trượt; 4. Rô-tuyn.","text":"Hình 11.38. Van điều khiển 1. Thân van; 2, 5. Màng đàn hồi; 3. Con trượt; 4. Rô-tuyn.","pages":[134],"figure":{"number":"11.38","caption":"Hình 11.38. Van điều khiển 1. Thân van; 2, 5. Màng đàn hồi; 3. Con trượt; 4. Rô-tuyn."}},{"id":"s1856","kind":"figure","lesson":"11.3.2","title":"Hình 11.38 thể hiện van điều khiển có bộ phận làm trễ chuyển động của con trượt. Van gồm thân (1) và con trượt (3), có nhiệm vụ điều khiển chất lỏng đi vào hoặc ra khỏi bộ phận đàn hồi, tương tự van (5) trên Hình 11.37. Hai phía con trượt gắn với các màng cao su (2) và (5). Màng (2) cùng thân van (1) tạo thành khoang A; màng (5) cùng thân van (1) tạo thành khoang B. Hai khoang thông nhau qua một lỗ có đường kính được tính toán trước và đều chứa đầy chất lỏng. Thân van (1) gắn với khung xe; rô-tuyn (4) gắn với con trượt và liên kết với bánh xe qua một chi tiết đàn hồi. Khi khoảng cách giữa bánh xe với khung xe thay đổi, con trượt không dịch chuyển ngay vì bị chất lỏng trong hai khoang cản trở. Lỗ thông được tính toán sao cho dao động do mấp mô không kéo dài đủ để con trượt mở van; chỉ khi tải trọng xe thay đổi, con trượt mới có đủ thời gian dịch chuyển để đóng hoặc mở các cửa van.","text":"Hình 11.38 thể hiện van điều khiển có bộ phận làm trễ chuyển động của con trượt. Van gồm thân (1) và con trượt (3), có nhiệm vụ điều khiển chất lỏng đi vào hoặc ra khỏi bộ phận đàn hồi, tương tự van (5) trên Hình 11.37. Hai phía con trượt gắn với các màng cao su (2) và (5). Màng (2) cùng thân van (1) tạo thành khoang A; màng (5) cùng thân van (1) tạo thành khoang B. Hai khoang thông nhau qua một lỗ có đường kính được tính toán trước và đều chứa đầy chất lỏng. Thân van (1) gắn với khung xe; rô-tuyn (4) gắn với con trượt và liên kết với bánh xe qua một chi tiết đàn hồi. Khi khoảng cách giữa bánh xe với khung xe thay đổi, con trượt không dịch chuyển ngay vì bị chất lỏng trong hai khoang cản trở. Lỗ thông được tính toán sao cho dao động do mấp mô không kéo dài đủ để con trượt mở van; chỉ khi tải trọng xe thay đổi, con trượt mới có đủ thời gian dịch chuyển để đóng hoặc mở các cửa van.","pages":[134],"figure":{"number":"11.38","caption":"Hình 11.38 thể hiện van điều khiển có bộ phận làm trễ chuyển động của con trượt. Van gồm thân (1) và con trượt (3), có nhiệm vụ điều khiển chất lỏng đi vào hoặc ra khỏi bộ phận đàn hồi, tương tự van (5) trên Hình 11.37. Hai phía con trượt gắn với các màng cao su (2) và (5). Màng (2) cùng thân van (1) tạo thành khoang A; màng (5) cùng thân van (1) tạo thành khoang B. Hai khoang thông nhau qua một lỗ có đường kính được tính toán trước và đều chứa đầy chất lỏng. Thân van (1) gắn với khung xe; rô-tuyn (4) gắn với con trượt và liên kết với bánh xe qua một chi tiết đàn hồi. Khi khoảng cách giữa bánh xe với khung xe thay đổi, con trượt không dịch chuyển ngay vì bị chất lỏng trong hai khoang cản trở. Lỗ thông được tính toán sao cho dao động do mấp mô không kéo dài đủ để con trượt mở van; chỉ khi tải trọng xe thay đổi, con trượt mới có đủ thời gian dịch chuyển để đóng hoặc mở các cửa van."}},{"id":"s1857","kind":"pdf","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"thực hiện nhiệm vụ này. Van có ba cửa như trường hợp ở Hình 11.34. Vỏ van cố định trên thân xe; con trượt đóng, mở các cửa van và nối với bánh xe. Nguyên lý hoạt động của van tương tự van điều chỉnh ở Hình 11.34. Khi tải trọng xe tăng, bánh xe tiến gần khung xe, con trượt dịch chuyển sang phải để nối bình tích áp (4) với bộ phận đàn hồi (1), làm áp suất tăng. Khi áp suất tăng, bánh xe lại dịch chuyển ra xa khung xe, con trượt trong van (5) dịch chuyển sang trái và đóng đường từ bình tích áp vào bộ phận đàn hồi. Khi tải trọng xe giảm, con trượt tiếp tục dịch chuyển sang trái để nối bộ phận đàn hồi (1) với bình chứa (2), làm áp suất giảm. Sơ đồ Hình 11.37 chỉ trình bày cách điều chỉnh áp suất trong bộ phận đàn hồi theo độ võng tĩnh của xe.","pages":[134]},{"id":"s1858","kind":"pdf","lesson":"11.3.2","title":"Hệ thống treo · Bộ phận đàn hồi phi kim loại","text":"Trên thực tế, để van không hoạt động theo các dao động ngắn hạn của bánh xe, cần bố trí thêm bộ phận làm trễ chuyển động của con trượt. IV. BỘ PHẬN GIẢM CHẤN Bộ phận đàn hồi có tác dụng điều hòa dao động khi bánh xe đi trên mặt đường không bằng phẳng, giúp ô tô chuyển động êm dịu hơn. Tuy nhiên, bộ phận này không triệt tiêu năng lượng dao động. Vì vậy, cần có bộ phận giảm chấn để tiêu tán năng lượng, thường bằng cách biến đổi năng lượng dao động thành nhiệt rồi tỏa ra môi trường.","pages":[134]},{"id":"s1859","kind":"figure","lesson":"11.4.1","title":"Hình 11.39. Giảm chấn kiểu ống đơn 1. Đế; 2. Vỏ; 3. Pít-tông khí; 4. Lò xo van trả; 5. Pít-tông thủy lực; 6, 7, 8. Các nắp van;","text":"Hình 11.39. Giảm chấn kiểu ống đơn 1. Đế; 2. Vỏ; 3. Pít-tông khí; 4. Lò xo van trả; 5. Pít-tông thủy lực; 6, 7, 8. Các nắp van;","pages":[135],"figure":{"number":"11.39","caption":"Hình 11.39. Giảm chấn kiểu ống đơn 1. Đế; 2. Vỏ; 3. Pít-tông khí; 4. Lò xo van trả; 5. Pít-tông thủy lực; 6, 7, 8. Các nắp van;"}},{"id":"s1860","kind":"pdf","lesson":"11.4.1","title":"Hệ thống treo · Giảm chấn kiểu ống đơn","text":"Giảm chấn trên ô tô hiện nay chủ yếu là loại thủy lực, gồm xi-lanh, pít-tông và chất lỏng. Pít-tông chia xi-lanh thành các buồng; khi bánh xe dao động, pít-tông dịch chuyển và dồn chất lỏng từ buồng này sang buồng khác qua các lỗ van. Ma sát giữa chất lỏng với thành lỗ và giữa các lớp chất lỏng biến cơ năng dao động thành nhiệt, làm nóng vỏ giảm chấn rồi tỏa ra môi trường. Khi pít-tông giảm chấn dịch chuyển, chất lỏng tạo lực cản chuyển động. Lực cản này phụ thuộc vào vận tốc của pít-tông và hệ số cản giảm chấn. Loại được sử dụng phổ biến trên ô tô hiện nay là giảm chấn thủy lực hai chiều không đối xứng. “Hai chiều” nghĩa là giảm chấn có tác dụng ở cả hành trình nén, khi bánh xe tiến gần khung xe, và hành trình trả, khi bánh xe đi xa khung xe. “Không đối xứng” nghĩa là hệ số cản ở hành trình nén và hành trình trả khác nhau.","pages":[135]},{"id":"s1861","kind":"pdf","lesson":"11.4.1","title":"Hệ thống treo · Giảm chấn kiểu ống đơn","text":"Giảm chấn thủy lực ống kép được dùng rộng rãi trên Hyundai Santa Fe, Toyota Fortuner; giảm chấn ống đơn phổ biến trên xe tải nhẹ như Hyundai Mighty và xe du lịch dùng hệ thống treo MacPherson như Toyota Vios. Theo kết cấu, giảm chấn gồm loại ống và loại đòn. Giảm chấn ống gồm loại hai lớp vỏ (có khoang bù) và loại một lớp vỏ (không có khoang bù). 1. Giảm chấn kiểu ống đơn 9. Lò xo van nén; 10. Cần pít-tông. Giảm chấn kiểu ống đơn thường được sử dụng trên hệ thống treo MacPherson. Do cần pít-tông chiếm chỗ trong khoang trên nên thể tích khoang trên và khoang dưới pít-tông khác nhau. Ở giảm chấn hai lớp vỏ, khoang giữa hai lớp vỏ bù chênh lệch thể tích này. Đối với giảm chấn một lớp vỏ, thể tích khoang dưới pít-tông có thể thay đổi (Hình 11.39). Khoang II được giới hạn bởi pít-tông thủy lực (5), pít- tông khí (3) và vỏ (2).","pages":[135]},{"id":"s1862","kind":"pdf","lesson":"11.4.1","title":"Hệ thống treo · Giảm chấn kiểu ống đơn","text":"Khoang III chứa chất khí; khi áp suất trong khoang II thay đổi, pít-tông khí (3) dịch chuyển và làm thay đổi thể tích khoang II. Giảm chấn có","pages":[135]},{"id":"s1863","kind":"figure","lesson":"11.4.2","title":"Hình 11.40. Giảm chấn kiểu ống kép 1. Tai trên; 2. Cần pít-tông; 3. Vỏ trong; 4. Pít-tông; 5. Vỏ ngoài; 6. Đế van; 7. Tai dưới.","text":"Hình 11.40. Giảm chấn kiểu ống kép 1. Tai trên; 2. Cần pít-tông; 3. Vỏ trong; 4. Pít-tông; 5. Vỏ ngoài; 6. Đế van; 7. Tai dưới.","pages":[136],"figure":{"number":"11.40","caption":"Hình 11.40. Giảm chấn kiểu ống kép 1. Tai trên; 2. Cần pít-tông; 3. Vỏ trong; 4. Pít-tông; 5. Vỏ ngoài; 6. Đế van; 7. Tai dưới."}},{"id":"s1864","kind":"figure","lesson":"11.4.2","title":"Hình 11.40 thể hiện mặt cắt của giảm chấn thủy lực ống kép, hai chiều không đối xứng. Tai trên (1) bắt với khung xe và được nối chặt với cần pít-tông (2) bằng mối ghép tán như trên hình. Pít-tông (4) lắp chặt với cần (2) và chuyển động trong vỏ trong (3). Đầu dưới của vỏ trong (3) lắp chặt với đế van (6), còn đầu trên lắp các bộ phận làm kín. Vỏ trong (3) đặt trong vỏ ngoài (5). Vỏ ngoài (5) hàn với tai dưới (7), còn tai dưới liên kết với bánh xe (hoặc cầu xe). Với cấu tạo này, giảm chấn có ba buồng làm việc: buồng I được giới hạn bởi vỏ trong (3), pít-tông (4) và cụm làm","text":"Hình 11.40 thể hiện mặt cắt của giảm chấn thủy lực ống kép, hai chiều không đối xứng. Tai trên (1) bắt với khung xe và được nối chặt với cần pít-tông (2) bằng mối ghép tán như trên hình. Pít-tông (4) lắp chặt với cần (2) và chuyển động trong vỏ trong (3). Đầu dưới của vỏ trong (3) lắp chặt với đế van (6), còn đầu trên lắp các bộ phận làm kín. Vỏ trong (3) đặt trong vỏ ngoài (5). Vỏ ngoài (5) hàn với tai dưới (7), còn tai dưới liên kết với bánh xe (hoặc cầu xe). Với cấu tạo này, giảm chấn có ba buồng làm việc: buồng I được giới hạn bởi vỏ trong (3), pít-tông (4) và cụm làm","pages":[136],"figure":{"number":"11.40","caption":"Hình 11.40 thể hiện mặt cắt của giảm chấn thủy lực ống kép, hai chiều không đối xứng. Tai trên (1) bắt với khung xe và được nối chặt với cần pít-tông (2) bằng mối ghép tán như trên hình. Pít-tông (4) lắp chặt với cần (2) và chuyển động trong vỏ trong (3). Đầu dưới của vỏ trong (3) lắp chặt với đế van (6), còn đầu trên lắp các bộ phận làm kín. Vỏ trong (3) đặt trong vỏ ngoài (5). Vỏ ngoài (5) hàn với tai dưới (7), còn tai dưới liên kết với bánh xe (hoặc cầu xe). Với cấu tạo này, giảm chấn có ba buồng làm việc: buồng I được giới hạn bởi vỏ trong (3), pít-tông (4) và cụm làm"}},{"id":"s1865","kind":"pdf","lesson":"11.4.1","title":"Hệ thống treo · Giảm chấn kiểu ống đơn","text":"hai van. Van nén gồm lỗ B, các nắp van (6), (7), (8) và lò xo (9): nắp (8) không có lỗ, nắp (7) có lỗ nhỏ hơn lỗ B, còn nắp (6) có lỗ bằng hoặc lớn hơn lỗ B. Van trả gồm lỗ A, ba nắp van và lò xo (4); các nắp van trả có cấu tạo lỗ tương tự nắp van nén. Các van làm việc ở bốn trạng thái: nén nhẹ, nén mạnh, trả nhẹ và trả mạnh. Nén nhẹ: Bánh xe tiến gần khung xe, cần pít-tông (10) đẩy pít-tông (5) đi xuống với vận tốc nhỏ hơn 0,3 m/s. Chất lỏng trong khoang II bị nén, đi qua các lỗ B, đẩy nắp (8) lên rồi đi qua các lỗ của nắp (7) để vào khoang I. Nén mạnh: Khi vận tốc pít-tông (5) lớn hơn 0,3 m/s, áp suất chất lỏng trong khoang II tác dụng qua lỗ B đủ lớn để đẩy nắp (7) lên. Chất lỏng đi qua lỗ của nắp (6); do lỗ này lớn hơn lỗ trên nắp (7), diện tích lưu thông tăng và hệ số cản giảm chấn giảm.","pages":[136]},{"id":"s1866","kind":"pdf","lesson":"11.4.2","title":"Hệ thống treo · Giảm chấn kiểu ống kép","text":"Trả nhẹ và trả mạnh: Bánh xe đi xa khung xe, cần pít-tông (10) kéo pít-tông (5) đi lên. Lúc này, chất lỏng từ khoang I đi qua các lỗ A xuống khoang II. Các nắp van trả mở tương tự các nắp van nén, tùy theo vận tốc đi lên của pít-tông (5). 2. Giảm chấn kiểu ống kép","pages":[136]},{"id":"s1867","kind":"figure","lesson":"11.4.2","title":"Hình 11.41. Các van giảm chấn A. Lỗ van nén nhẹ; B. Lỗ van trả mạnh; C. Lỗ van nén mạnh; D. Lỗ van trả nhẹ.","text":"Hình 11.41. Các van giảm chấn A. Lỗ van nén nhẹ; B. Lỗ van trả mạnh; C. Lỗ van nén mạnh; D. Lỗ van trả nhẹ.","pages":[137],"figure":{"number":"11.41","caption":"Hình 11.41. Các van giảm chấn A. Lỗ van nén nhẹ; B. Lỗ van trả mạnh; C. Lỗ van nén mạnh; D. Lỗ van trả nhẹ."}},{"id":"s1868","kind":"pdf","lesson":"11.4.2","title":"Hệ thống treo · Giảm chấn kiểu ống kép","text":"kín phía trên; buồng II được giới hạn bởi vỏ trong (3), pít-tông (4) và đế van (6); buồng III gồm không gian dưới đế van (6) và không gian giữa vỏ trong với vỏ ngoài. Cần có buồng III vì thể tích buồng I và buồng II không bằng nhau: buồng I có cần pít-tông (2) chiếm chỗ, còn buồng II không có. Vì vậy, buồng III còn được gọi là khoang bù. Trên Hình 11.41, các lỗ A trên pít-tông (4) là lỗ van nén nhẹ, được nắp van (2) che kín và lò xo (1) giữ. Các lỗ D là lỗ van trả nhẹ, được nắp van (9) che kín và lò xo (8) giữ. Các lò xo (1), (8) có độ cứng nhỏ. Các lỗ C là lỗ van nén mạnh: ở Hình 11.41a, các lỗ C được nắp van (13) che kín và lò xo (11) giữ; ở Hình 11.41b, lỗ C nằm trên thân van (13), còn thân van được lò xo (11) giữ. 1. Lò xo van nén nhẹ; 2. Nắp van nén nhẹ; 3. Vỏ trong; 4. Pít-tông; 5. Nắp van trả mạnh; 6. Lò xo van trả mạnh; 7. Vỏ ngoài; 8.","pages":[137]},{"id":"s1869","kind":"pdf","lesson":"11.4.2","title":"Hệ thống treo · Giảm chấn kiểu ống kép","text":"Lò xo van trả nhẹ; 9. Nắp van trả nhẹ; 10. Đế van; 11. Lò xo van nén mạnh; 12. Tai dưới; 13. Nắp van nén mạnh. Các lò xo (11) được tính toán sao cho khi vận tốc pít-tông (4) lớn hơn 0,3 m/s, áp suất chất lỏng đủ nén lò xo để mở van nén mạnh. Các lỗ B là lỗ van trả mạnh, được nắp van (5) che kín và lò xo (6) giữ. Tương tự van nén mạnh, lò xo (6) được tính toán sao cho khi vận tốc pít-tông (4) lớn hơn 0,3 m/s, áp suất chất lỏng đủ nén lò xo để mở van trả mạnh. Các van nén mạnh và trả mạnh không đóng kín hoàn toàn. Trên Hình 11.41a, các nắp van (5), (13) có dạng “hoa khế” nên không thể đóng kín. Trên Hình 11.41b, giữa nắp van (5) với ống bạc có khe hở, còn thân van (13) có một lỗ nhỏ ở tâm. - Giảm chấn làm việc như sau: Hành trình nén nhẹ: Pít-tông (4) đi xuống với vận tốc nhỏ hơn 0,3 m/s.","pages":[137]},{"id":"s1870","kind":"pdf","lesson":"11.4.2","title":"Hệ thống treo · Giảm chấn kiểu ống kép","text":"Áp suất chất lỏng trong buồng II tăng, áp suất trong buồng I giảm, làm lò xo (1) bị nén và mở van nén nhẹ. Chất lỏng đi qua lỗ A lên buồng I. Đồng thời, một phần nhỏ chất lỏng từ buồng II đi qua khe hở của van trả mạnh lên buồng I và qua khe hở của van nén mạnh xuống buồng III.","pages":[137]},{"id":"s1871","kind":"figure","lesson":"11.4.2","title":"Hình 11.42. Giảm chấn thay đổi hệ số cản","text":"Hình 11.42. Giảm chấn thay đổi hệ số cản","pages":[138],"figure":{"number":"11.42","caption":"Hình 11.42. Giảm chấn thay đổi hệ số cản"}},{"id":"s1872","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Hành trình nén mạnh: Pít-tông (4) đi xuống với vận tốc lớn hơn 0,3 m/s; chất lỏng tiếp tục lưu thông như ở hành trình nén nhẹ. Đồng thời, áp suất trong buồng II tăng đủ lớn để nén lò xo (11), mở thêm van nén mạnh và cho chất lỏng từ buồng II đi qua lỗ C xuống buồng III. Do diện tích lưu thông tăng, hệ số cản ở hành trình nén mạnh giảm so với hành trình nén nhẹ. Hành trình trả nhẹ: Pít-tông (4) đi lên với vận tốc nhỏ hơn 0,3 m/s. Áp suất trong buồng II giảm, lò xo (8) bị nén và mở van trả nhẹ, cho chất lỏng từ buồng III đi qua lỗ D lên buồng II. Đồng thời, một phần nhỏ chất lỏng từ buồng I đi qua khe hở của van trả mạnh xuống buồng II và từ buồng III đi qua khe hở của van nén mạnh lên buồng II. Hành trình trả mạnh: Pít-tông (4) đi lên với vận tốc lớn hơn 0,3 m/s; chất lỏng tiếp tục lưu thông như ở hành trình trả nhẹ.","pages":[138]},{"id":"s1873","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Đồng thời, áp suất trong buồng II giảm mạnh và áp suất trong buồng I tăng đủ lớn để nén lò xo (6), mở thêm van trả mạnh và cho chất lỏng từ buồng I đi qua lỗ B xuống buồng II. Do diện tích lưu thông tăng, hệ số cản ở hành trình trả mạnh giảm so với hành trình trả nhẹ. 3. Điều chỉnh hệ số cản giảm chấn a) Sơ đồ kết cấu; b) Đường đặc tính. Đặc trưng của giảm chấn là hệ số cản. Độ êm dịu của xe phụ thuộc vào độ cứng của bộ phận đàn hồi và hệ số cản giảm chấn. Mỗi điều kiện vận hành đòi hỏi một hệ số cản thích hợp; ví dụ, tải trọng tác dụng lên hệ thống treo lớn thường đòi hỏi hệ số cản lớn hơn. Trên xe truyền thống, hệ số cản không thay đổi nên xe chỉ đạt độ êm dịu tốt trong một số điều kiện vận hành nhất định. Để bảo đảm độ êm dịu trong các điều kiện khác nhau, giảm chấn cần có khả năng thay đổi hệ số cản.","pages":[138]},{"id":"s1874","kind":"pdf","lesson":"11.4.2","title":"Hệ thống treo · Giảm chấn kiểu ống kép","text":"Hệ số cản giảm chấn phụ thuộc vào hai yếu tố: diện tích lưu thông của các lỗ van giữa các khoang và độ nhớt của chất lỏng trong giảm chấn. Vì vậy, có thể thay đổi hệ số cản giảm chấn bằng cách thay đổi diện tích lưu thông giữa các khoang hoặc thay đổi độ nhớt của chất lỏng.","pages":[138]},{"id":"s1875","kind":"figure","lesson":"11.5.1","title":"Hình 11.43. Sơ đồ kết cấu van điện từ Hình 11.42a là sơ đồ giảm chấn điều chỉnh hệ số cản bằng cách thay đổi diện tích lưu thông giữa các khoang. Giảm chấn có thêm một đường dẫn từ khoang A sang khoang C qua van tiết lưu điều chỉnh được. Diện tích lưu thông thay đổi theo độ mở của van tiết lưu. Hình 11.42b là đường đặc tính của giảm chấn. Nếu van tiết lưu chỉ có hai vị trí, “OFF” (đóng hoàn toàn) và “ON” (mở hoàn toàn), thì giảm chấn có hai đường đặc tính tương ứng. Nếu van có thể điều khiển ở nhiều vị trí, giảm chấn sẽ có một họ đường đặc tính. Hình 11.43 thể hiện van điện từ có khả năng điều chỉnh diện tích lưu thông. Dòng điện cấp cho nam châm điện làm dịch chuyển con trượt van và được ECU điều khiển.","text":"Hình 11.43. Sơ đồ kết cấu van điện từ Hình 11.42a là sơ đồ giảm chấn điều chỉnh hệ số cản bằng cách thay đổi diện tích lưu thông giữa các khoang. Giảm chấn có thêm một đường dẫn từ khoang A sang khoang C qua van tiết lưu điều chỉnh được. Diện tích lưu thông thay đổi theo độ mở của van tiết lưu. Hình 11.42b là đường đặc tính của giảm chấn. Nếu van tiết lưu chỉ có hai vị trí, “OFF” (đóng hoàn toàn) và “ON” (mở hoàn toàn), thì giảm chấn có hai đường đặc tính tương ứng. Nếu van có thể điều khiển ở nhiều vị trí, giảm chấn sẽ có một họ đường đặc tính. Hình 11.43 thể hiện van điện từ có khả năng điều chỉnh diện tích lưu thông. Dòng điện cấp cho nam châm điện làm dịch chuyển con trượt van và được ECU điều khiển.","pages":[139],"figure":{"number":"11.43","caption":"Hình 11.43. Sơ đồ kết cấu van điện từ Hình 11.42a là sơ đồ giảm chấn điều chỉnh hệ số cản bằng cách thay đổi diện tích lưu thông giữa các khoang. Giảm chấn có thêm một đường dẫn từ khoang A sang khoang C qua van tiết lưu điều chỉnh được. Diện tích lưu thông thay đổi theo độ mở của van tiết lưu. Hình 11.42b là đường đặc tính của giảm chấn. Nếu van tiết lưu chỉ có hai vị trí, “OFF” (đóng hoàn toàn) và “ON” (mở hoàn toàn), thì giảm chấn có hai đường đặc tính tương ứng. Nếu van có thể điều khiển ở nhiều vị trí, giảm chấn sẽ có một họ đường đặc tính. Hình 11.43 thể hiện van điện từ có khả năng điều chỉnh diện tích lưu thông. Dòng điện cấp cho nam châm điện làm dịch chuyển con trượt van và được ECU điều khiển."}},{"id":"s1876","kind":"figure","lesson":"11.5.1","title":"Hình 11.44. Cách tạo điện trường trong giảm chấn Độ nhớt của chất lỏng ảnh hưởng trực tiếp đến hệ số cản giảm chấn: độ nhớt càng cao thì hệ số cản càng lớn và ngược lại. Một số chất lỏng có độ nhớt nhạy với điện trường hoặc từ trường. Khi chất lỏng nằm trong điện trường hoặc từ trường, độ nhớt thay đổi theo cường độ trường. Đặc tính này được ứng dụng để chế tạo giảm chấn có hệ số cản thay đổi bằng cách tạo và điều chỉnh cường độ điện trường hoặc từ trường trong chất lỏng.","text":"Hình 11.44. Cách tạo điện trường trong giảm chấn Độ nhớt của chất lỏng ảnh hưởng trực tiếp đến hệ số cản giảm chấn: độ nhớt càng cao thì hệ số cản càng lớn và ngược lại. Một số chất lỏng có độ nhớt nhạy với điện trường hoặc từ trường. Khi chất lỏng nằm trong điện trường hoặc từ trường, độ nhớt thay đổi theo cường độ trường. Đặc tính này được ứng dụng để chế tạo giảm chấn có hệ số cản thay đổi bằng cách tạo và điều chỉnh cường độ điện trường hoặc từ trường trong chất lỏng.","pages":[139],"figure":{"number":"11.44","caption":"Hình 11.44. Cách tạo điện trường trong giảm chấn Độ nhớt của chất lỏng ảnh hưởng trực tiếp đến hệ số cản giảm chấn: độ nhớt càng cao thì hệ số cản càng lớn và ngược lại. Một số chất lỏng có độ nhớt nhạy với điện trường hoặc từ trường. Khi chất lỏng nằm trong điện trường hoặc từ trường, độ nhớt thay đổi theo cường độ trường. Đặc tính này được ứng dụng để chế tạo giảm chấn có hệ số cản thay đổi bằng cách tạo và điều chỉnh cường độ điện trường hoặc từ trường trong chất lỏng."}},{"id":"s1877","kind":"figure","lesson":"11.5.1","title":"Hình 11.44 minh họa cách tạo điện trường có cường độ thay đổi trong chất lỏng. Khi hiệu điện thế nguồn thay đổi, cường độ điện trường và độ nhớt của chất lỏng cũng thay đổi. Nguyên lý này có thể dùng để chế tạo giảm chấn có hệ số cản thay đổi thông qua độ nhớt của chất lỏng.","text":"Hình 11.44 minh họa cách tạo điện trường có cường độ thay đổi trong chất lỏng. Khi hiệu điện thế nguồn thay đổi, cường độ điện trường và độ nhớt của chất lỏng cũng thay đổi. Nguyên lý này có thể dùng để chế tạo giảm chấn có hệ số cản thay đổi thông qua độ nhớt của chất lỏng.","pages":[139],"figure":{"number":"11.44","caption":"Hình 11.44 minh họa cách tạo điện trường có cường độ thay đổi trong chất lỏng. Khi hiệu điện thế nguồn thay đổi, cường độ điện trường và độ nhớt của chất lỏng cũng thay đổi. Nguyên lý này có thể dùng để chế tạo giảm chấn có hệ số cản thay đổi thông qua độ nhớt của chất lỏng."}},{"id":"s1878","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"a) Điều chỉnh bằng cách thay đổi diện tích lưu thông giữa các khoang giảm chấn b) Điều chỉnh bằng cách thay đổi độ nhớt chất lỏng trong giảm chấn V. HỆ THỐNG TREO ĐIỀU KHIỂN ĐIỆN TỬ Hệ thống treo điều khiển điện tử là bước phát triển cao nhất của hệ thống treo ô tô, tích hợp mạng lưới cảm biến chuyển động (đo gia tốc thân xe, góc đánh lái, tốc","pages":[139]},{"id":"s1879","kind":"figure","lesson":"11.5.1","title":"Hình 11.45. Các bộ phận và hệ thống của khung gầm Hydractive Bằng cách bổ sung một số bộ phận vào khung gầm (Hình 11.45), hệ thống treo thủy lực - khí nén chủ động có các khả năng sau:","text":"Hình 11.45. Các bộ phận và hệ thống của khung gầm Hydractive Bằng cách bổ sung một số bộ phận vào khung gầm (Hình 11.45), hệ thống treo thủy lực - khí nén chủ động có các khả năng sau:","pages":[140],"figure":{"number":"11.45","caption":"Hình 11.45. Các bộ phận và hệ thống của khung gầm Hydractive Bằng cách bổ sung một số bộ phận vào khung gầm (Hình 11.45), hệ thống treo thủy lực - khí nén chủ động có các khả năng sau:"}},{"id":"s1880","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"độ xe, độ cao gầm...) và bộ điều khiển điện tử (ECU) để liên tục điều chỉnh đặc tính đàn hồi và hệ số cản giảm chấn theo thời gian thực. Hệ thống giải quyết mâu thuẫn kinh điển trong động lực học ô tô: tối ưu hóa đồng thời giữa độ êm dịu chuyển động và tính ổn định chuyển động.","pages":[140]},{"id":"s1881","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Một số ứng dụng công nghệ điển hình trên các dòng xe thương mại: - Mercedes-Benz S-Class: Trang bị hệ thống treo khí nén chủ động (AIRMATIC), tự động điều chỉnh độ cứng và hạ thấp trọng tâm theo dải tốc độ để tối ưu độ êm dịu và tính khí động học. - Audi TT và Cadillac Escalade: Ứng dụng giảm chấn chất lỏng từ lưu biến (Magnetic Ride), cho phép biến thiên độ cản giảm chấn tức thời với thời gian đáp ứng ở cỡ mili giây. - Porsche Cayenne và Tesla Model S: Tích hợp hệ thống treo khí nén thích ứng (Adaptive Air Suspension), tự động điều chỉnh khoảng sáng gầm xe để thích ứng linh hoạt giữa chế độ vận hành tốc độ cao và vượt địa hình (off-road). Nhờ khả năng kiểm soát động lực học chính xác và thích ứng đa địa hình, hệ thống treo điều khiển điện tử hiện đã trở thành cấu hình tiêu chuẩn trên các phân khúc xe cao cấp, SUV hiệu năng cao và xe điện (EV) thế hệ mới. 1.","pages":[140]},{"id":"s1882","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Hệ thống treo thủy lực - khí nén chủ động (Hydractive) - Giảm độ nghiêng của thân vỏ xe khi chuyển động trong vòng cua. - Tác động ngược lại việc đầu xe bị chúi khi phanh và đuôi xe hạ thấp khi tăng tốc. - Thay đổi tính năng đàn hồi giữa cứng và mềm, độc lập với việc lựa chọn chế độ chuyển động thể thao hay êm dịu.","pages":[140]},{"id":"s1883","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Các bộ phận chính của hệ thống treo thủy lực - khí nén chủ động (Hình 11.45) bao gồm: - Hai thanh ổn định ngang, mỗi cầu một thanh; mỗi thanh liên kết với hai xi- lanh lò xo. - Mỗi cầu trước và sau có một quả cầu lò xo trung tâm với bộ điều chỉnh độ cứng của hệ thống treo. - Cụm thủy lực. - Cảm biến đo độ cao ở cầu trước và cầu sau. - Cảm biến đo góc đánh lái, bàn đạp ga và bàn đạp phanh. Khi ô tô chuyển động trong vòng cua hoặc thực hiện thao tác đổi hướng đột ngột, thân xe thường có xu hướng nghiêng về phía ngoài cua. Khi đó, tải trọng phân bố lên các bánh xe thay đổi: bánh phía ngoài cua chịu tải lớn hơn, trong khi bánh phía trong cua giảm tải, làm lực bám đường của bánh trong giảm đáng kể. Nếu tải trọng phân bố không hợp lý, hiện tượng trượt ngang có thể xảy ra; trong trường hợp tốc độ cao hoặc xe có trọng tâm cao, nguy cơ lật xe cũng xuất hiện.","pages":[141]},{"id":"s1884","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Mức độ nghiêng ngang của thân xe phụ thuộc vào tốc độ chuyển động trong cua và khoảng cách giữa trục lăn (trục lắc ngang) với trọng tâm xe. Khoảng cách này càng lớn thì mô-men lắc ngang càng lớn, thân xe có xu hướng nghiêng nhiều hơn và tính ổn định giảm. Để hạn chế độ nghiêng thân xe khi quay vòng, người ta lắp thêm thanh ổn định (thanh cân bằng). Khi hai bánh xe trên cùng một cầu chịu độ nén khác nhau, thanh ổn định sẽ bị xoắn và hoạt động như một lò xo phụ dạng thanh xoắn. Nhờ vậy, độ cứng tổng thể của hệ thống treo tăng lên, giúp giảm độ nghiêng ngang nhưng đồng thời làm giảm bớt độ êm dịu. Trong hệ thống Hydractive, các xi-lanh lò xo phía trước bố trí thẳng đứng và nối với thanh ổn định qua thanh liên kết, trong khi các xi-lanh phía sau được đặt nằm ngang.","pages":[141]},{"id":"s1885","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Áp suất dầu trong xi-lanh có thể thay đổi, tạo ra lực bổ sung lên thanh ổn định, qua đó điều chỉnh độ cứng lò xo. Ngoài ra, mỗi cầu xe còn có thêm một quả cầu lò xo trung tâm và một cảm biến đo độ cao. Khi thân xe dao động, sự biến dạng của lò xo sẽ tạo ra xoắn trên thanh ổn định; cảm biến đo độ cao ghi nhận sự thay đổi này và gửi tín hiệu đến bộ điều khiển điện tử. Tất cả xi-lanh và quả cầu lò xo được nối với nhau qua cụm thủy lực, gồm bơm thủy lực dẫn động điện, bốn van điện từ và bộ điều khiển. Bơm cấp dầu thủy lực cho các quả cầu lò xo với áp suất làm việc 80 ÷ 140 bar. Hệ thống cho phép điều khiển độc lập: đầu xe có thể nâng hoặc hạ riêng so với đuôi xe và ngược lại, giúp xe thích ứng linh hoạt với nhiều điều kiện vận hành.","pages":[141]},{"id":"s1886","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Nguyên lý hoạt động của hệ thống Hydractive: Thông qua việc chọn chế độ “êm dịu” hoặc “thể thao”, người lái có thể lựa chọn hệ thống treo mềm hoặc cứng. Tùy theo điều kiện và trạng thái chuyển động (ví dụ, xe chạy nhanh trong vòng cua), bộ điều khiển có thể chuyển hệ thống treo sang trạng thái cứng hơn ngay cả khi người lái chọn chế độ “êm dịu”.","pages":[141]},{"id":"s1887","kind":"figure","lesson":"11.5.1","title":"Hình 11.46. Khung gầm với hệ thống Hydractive ở vị trí “êm dịu”","text":"Hình 11.46. Khung gầm với hệ thống Hydractive ở vị trí “êm dịu”","pages":[142],"figure":{"number":"11.46","caption":"Hình 11.46. Khung gầm với hệ thống Hydractive ở vị trí “êm dịu”"}},{"id":"s1888","kind":"figure","lesson":"11.5.1","title":"Hình 11.47. Bộ điều chỉnh độ cứng của bộ phận đàn hồi ở vị trí thể thao","text":"Hình 11.47. Bộ điều chỉnh độ cứng của bộ phận đàn hồi ở vị trí thể thao","pages":[142],"figure":{"number":"11.47","caption":"Hình 11.47. Bộ điều chỉnh độ cứng của bộ phận đàn hồi ở vị trí thể thao"}},{"id":"s1889","kind":"pdf","lesson":"11.5.1","title":"Hệ thống treo · Hệ thống treo khí nén-thủy lực chủ động (Hydractive)","text":"Chế độ chuyển động “êm dịu”: Ba quả cầu lò xo trên mỗi cầu được nối thông với nhau. Khi hệ thống treo bị nén, thanh đẩy pít-tông đi vào xi-lanh và đẩy dầu thủy lực sang quả cầu lò xo; dầu tác dụng lên màng ngăn và nén khí nitơ. Quả cầu thứ ba bổ sung thêm thể tích khí, làm giảm độ cứng tổng thể của bộ phận đàn hồi (Hình 11.46). Chế độ chuyển động “thể thao”: Khi bộ điều khiển cấp điện cho van điện từ tại quả cầu lò xo trung tâm, đường dầu nối với quả cầu này bị ngắt. Khi đó, chỉ còn thể tích khí của hai xi-lanh lò xo tham gia làm việc nên bộ phận đàn hồi trở nên cứng hơn.","pages":[142]},{"id":"s1890","kind":"figure","lesson":"11.5.2","title":"Hình 11.48. Sơ đồ nối mạch của bộ giảm chấn điện tử Với sự hỗ trợ của bộ điều chỉnh lực giảm chấn điện tử, đặc tính của lực giảm chấn có thể biến đổi vô cấp tùy theo sự điều khiển của người lái và trạng thái chuyển động, với các đặc điểm:","text":"Hình 11.48. Sơ đồ nối mạch của bộ giảm chấn điện tử Với sự hỗ trợ của bộ điều chỉnh lực giảm chấn điện tử, đặc tính của lực giảm chấn có thể biến đổi vô cấp tùy theo sự điều khiển của người lái và trạng thái chuyển động, với các đặc điểm:","pages":[143],"figure":{"number":"11.48","caption":"Hình 11.48. Sơ đồ nối mạch của bộ giảm chấn điện tử Với sự hỗ trợ của bộ điều chỉnh lực giảm chấn điện tử, đặc tính của lực giảm chấn có thể biến đổi vô cấp tùy theo sự điều khiển của người lái và trạng thái chuyển động, với các đặc điểm:"}},{"id":"s1891","kind":"pdf","lesson":"11.5.2","title":"Hệ thống treo · Bộ phận điều chỉnh lực giảm chấn điện tử – Continuous Damping Control (CDC)","text":"Ở chế độ “thể thao” (Hình 11.47), van điện từ của bộ điều chỉnh độ cứng được cấp điện, đường dầu hồi về bình chứa mở ra nên mặt dưới con trượt điều khiển không còn chịu áp suất. Do mặt trên vẫn chịu áp suất của bộ phận đàn hồi, con trượt bị đẩy xuống. Vì vậy, đường nối giữa các phần tử lò xo với nhau và với quả cầu lò xo trung tâm bị ngắt. Các trạng thái quay vòng, tăng tốc và phanh: khi xe quay vòng, bộ điều khiển nhận tín hiệu về tốc độ và góc quay của vành tay lái từ cảm biến góc đánh lái. Để hạn chế dao động lắc của thân xe, bộ điều khiển cấp điện cho van điện từ và đóng đường nối giữa các quả cầu lò xo. Bộ phận đàn hồi trở nên cứng hơn, làm giảm góc nghiêng của thân xe. Nếu không có tác động này, thân xe sẽ nghiêng về phía bánh xe ngoài cua và dầu thủy lực sẽ chảy về các phần tử lò xo ở phía giảm tải.","pages":[143]},{"id":"s1892","kind":"pdf","lesson":"11.5.2","title":"Hệ thống treo · Bộ phận điều chỉnh lực giảm chấn điện tử – Continuous Damping Control (CDC)","text":"Khi xe tăng tốc, bộ điều khiển sử dụng tín hiệu từ cảm biến vị trí bàn đạp ga để khóa quả cầu lò xo trung tâm của cầu sau, hạn chế đuôi xe hạ thấp. 2. Bộ phận điều chỉnh lực giảm chấn điện tử (Continuous Damping Control – CDC) - Tăng cường an toàn chuyển động nhờ cải thiện độ bám đường của bánh xe; - Giảm dao động lắc và độ nghiêng của thân vỏ, khung xe khi xe chạy trong vòng cua; - Cho phép chọn chế độ giảm chấn thể thao hoặc êm dịu bằng nút bấm. Hệ thống gồm các bộ phận cơ bản sau: - Bộ giảm chấn với lực giảm chấn có thể điều chỉnh bằng điện tử; - Cảm biến đo góc đánh lái, chuyển động của bánh xe và gia tốc ngang của thân vỏ xe;","pages":[143]},{"id":"s1893","kind":"figure","lesson":"11.5.2","title":"Hình 11.49. Giảm chấn với van tỷ lệ Giảm chấn thủy lực ống kép với van tỷ lệ (Hình 11.49): Lực giảm chấn được điều chỉnh bằng dòng điện cấp cho van điện từ. Khi cần lực giảm chấn lớn, sức cản dòng dầu phải tăng (bên trái hình). Khi cuộn dây điện từ được cấp điện, van tỷ lệ dịch chuyển ngược chiều lực đàn hồi, làm tăng tiết diện lỗ tiết lưu (bên phải hình) và giảm lực giảm chấn. Tiết diện lỗ tiết lưu được điều chỉnh vô cấp theo cường độ dòng điện cấp cho cuộn dây.","text":"Hình 11.49. Giảm chấn với van tỷ lệ Giảm chấn thủy lực ống kép với van tỷ lệ (Hình 11.49): Lực giảm chấn được điều chỉnh bằng dòng điện cấp cho van điện từ. Khi cần lực giảm chấn lớn, sức cản dòng dầu phải tăng (bên trái hình). Khi cuộn dây điện từ được cấp điện, van tỷ lệ dịch chuyển ngược chiều lực đàn hồi, làm tăng tiết diện lỗ tiết lưu (bên phải hình) và giảm lực giảm chấn. Tiết diện lỗ tiết lưu được điều chỉnh vô cấp theo cường độ dòng điện cấp cho cuộn dây.","pages":[144],"figure":{"number":"11.49","caption":"Hình 11.49. Giảm chấn với van tỷ lệ Giảm chấn thủy lực ống kép với van tỷ lệ (Hình 11.49): Lực giảm chấn được điều chỉnh bằng dòng điện cấp cho van điện từ. Khi cần lực giảm chấn lớn, sức cản dòng dầu phải tăng (bên trái hình). Khi cuộn dây điện từ được cấp điện, van tỷ lệ dịch chuyển ngược chiều lực đàn hồi, làm tăng tiết diện lỗ tiết lưu (bên phải hình) và giảm lực giảm chấn. Tiết diện lỗ tiết lưu được điều chỉnh vô cấp theo cường độ dòng điện cấp cho cuộn dây."}},{"id":"s1894","kind":"figure","lesson":"11.5.2","title":"Hình 11.50. Bộ giảm chấn với hiệu ứng từ lưu biến Giảm chấn từ lưu biến ống đơn hoạt động dựa trên hiệu ứng từ lưu biến (Magnetic Ride, Hình 11.50). Trong dầu giảm chấn tổng hợp có phân tán các hạt sắt","text":"Hình 11.50. Bộ giảm chấn với hiệu ứng từ lưu biến Giảm chấn từ lưu biến ống đơn hoạt động dựa trên hiệu ứng từ lưu biến (Magnetic Ride, Hình 11.50). Trong dầu giảm chấn tổng hợp có phân tán các hạt sắt","pages":[144],"figure":{"number":"11.50","caption":"Hình 11.50. Bộ giảm chấn với hiệu ứng từ lưu biến Giảm chấn từ lưu biến ống đơn hoạt động dựa trên hiệu ứng từ lưu biến (Magnetic Ride, Hình 11.50). Trong dầu giảm chấn tổng hợp có phân tán các hạt sắt"}},{"id":"s1895","kind":"pdf","lesson":"11.5.2","title":"Hệ thống treo · Bộ phận điều chỉnh lực giảm chấn điện tử – Continuous Damping Control (CDC)","text":"- Cảm biến đo tốc độ xe; - Cảm biến góc dùng để xác định độ cao của xe ở mỗi bên cầu xe; - Bộ điều khiển để điều chỉnh lực giảm chấn. Nguyên lý hoạt động: Lực giảm chấn được điều chỉnh phù hợp với từng hành trình nén và trả của hệ thống treo, cũng như từng trạng thái chuyển động của xe. Việc điều chỉnh được thực hiện bằng cách thay đổi cường độ dòng điện cấp cho van điện từ của bộ giảm chấn (Hình 11.48). Tùy theo thông tin của các cảm biến, bộ điều khiển sẽ tính toán dòng điện cần thiết cho van điện từ của mỗi bộ giảm chấn. Lực giảm chấn có thể thay đổi trong phạm vi rộng với thời gian đáp ứng từ 2 ms đến 4 ms. Bộ giảm chấn điện tử có các kiểu sau:","pages":[144]},{"id":"s1896","kind":"pdf","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"nhỏ với đường kính 3 ÷ 10 µm. Từ trường do cuộn dây điện từ tạo ra sẽ làm thay đổi trạng thái phân bố của các hạt và qua đó thay đổi lực cản giảm chấn. Khi cuộn dây điện từ chưa được cấp điện, các hạt sắt phân tán tự do trong dầu giảm chấn. Dầu có độ nhớt biểu kiến thấp và dễ chảy qua các lỗ trên pít-tông, nên lực cản giảm chấn nhỏ, giúp xe êm dịu hơn. Khi cuộn dây điện từ được cấp điện, từ trường làm các hạt sắt nhanh chóng sắp xếp thành chuỗi dọc theo đường sức từ. Trạng thái này làm độ nhớt biểu kiến của dầu tăng rõ rệt. Do đó, dòng dầu gặp sức cản lớn hơn khi đi qua các lỗ trên pít- tông, làm tăng lực cản giảm chấn, giúp xe ổn định và giảm dao động. Sơ đồ minh họa nguyên lý làm việc của pít-tông và dầu giảm chấn (Hình 11.50): - Bên trái: Chưa cấp điện: độ nhớt dầu và lực giảm chấn đều thấp. - Bên phải: Cấp điện: độ nhớt dầu và lực giảm chấn đều tăng.","pages":[145]},{"id":"s1897","kind":"figure","lesson":"12.1.1","title":"Hình 12.1. Vùng hấp thụ và vùng bảo vệ khối pin trên khung - vỏ xe điện 1. Vùng hấp thụ phía trước; 2. Khoang hành khách; 3. Dầm dọc; 4. Dầm ngang; 5.","text":"Hình 12.1. Vùng hấp thụ và vùng bảo vệ khối pin trên khung - vỏ xe điện 1. Vùng hấp thụ phía trước; 2. Khoang hành khách; 3. Dầm dọc; 4. Dầm ngang; 5.","pages":[146],"figure":{"number":"12.1","caption":"Hình 12.1. Vùng hấp thụ và vùng bảo vệ khối pin trên khung - vỏ xe điện 1. Vùng hấp thụ phía trước; 2. Khoang hành khách; 3. Dầm dọc; 4. Dầm ngang; 5."}},{"id":"s1898","kind":"pdf","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"Chương 12 KHUNG, VỎ VÀ THIẾT BỊ PHỤ TRÊN Ô TÔ Khung, vỏ và các thiết bị phụ là những bộ phận có vai trò quan trọng trong việc hình thành kết cấu tổng thể, bảo đảm khả năng chịu lực, bố trí các cụm hệ thống và đáp ứng yêu cầu sử dụng của ô tô. Chương này trình bày công dụng, phân loại và đặc điểm cấu tạo của khung, vỏ ô tô; các dạng kết cấu khung, khung dàn và vỏ xe được sử dụng trên những loại ô tô khác nhau. Nội dung cũng xem xét mối liên hệ giữa kết cấu khung, vỏ với việc lắp đặt các cụm tổng thành, bố trí không gian cho người và hàng hóa, cũng như yêu cầu về độ cứng và độ bền của kết cấu. 1.","pages":[146]},{"id":"s1899","kind":"pdf","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"Công dụng, phân loại a) Công dụng Khung ô tô là kết cấu chịu lực chính của xe, để lắp đặt và định vị tương quan giữa các cụm tổng thành (động cơ, hệ thống truyền lực, hệ thống treo, hệ thống lái, hệ thống phanh, buồng lái, thùng xe): - Tiếp nhận trọng lượng và tải trọng từ các cụm tổng thành, sau đó truyền xuống hệ thống treo và cầu xe; - Tiếp nhận phản lực từ mặt đường và phân phối trở lại các cụm hệ thống. Vỏ ô tô là kết cấu bao bên ngoài, tạo không gian chứa người và hàng hóa; bảo vệ hành khách trước tác nhân môi trường (mưa, nắng, bụi, gió); bảo đảm tiện nghi, thẩm mỹ và đặc tính khí động học của ô tô. Vùng hấp thụ phía sau; 6. Khối pin; F. Lực va chạm.","pages":[146]},{"id":"s1900","kind":"pdf","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"Đối với xe điện và xe hybrid, ngoài các công dụng nêu trên, khung - vỏ ô tô còn phải đáp ứng thêm các yêu cầu xuất phát từ việc bố trí khối pin cao áp và các cụm dẫn động điện (Hình 12.1): - Tiếp nhận và phân bố khối lượng của khối pin; - Tạo vùng bảo vệ cho khối pin; - Bảo đảm khả năng hấp thụ năng lượng va chạm;","pages":[146]},{"id":"s1901","kind":"figure","lesson":"12.1.1","title":"Hình 12.2. Khung dầm rời chịu lực toàn bộ - Loại thân vỏ liền khối (Hình 12.3): Đặc điểm: Vỏ đồng thời là kết cấu chịu lực; các tấm thép được dập định hình và hàn ghép thành một khối liền chịu uốn - xoắn.","text":"Hình 12.2. Khung dầm rời chịu lực toàn bộ - Loại thân vỏ liền khối (Hình 12.3): Đặc điểm: Vỏ đồng thời là kết cấu chịu lực; các tấm thép được dập định hình và hàn ghép thành một khối liền chịu uốn - xoắn.","pages":[147],"figure":{"number":"12.2","caption":"Hình 12.2. Khung dầm rời chịu lực toàn bộ - Loại thân vỏ liền khối (Hình 12.3): Đặc điểm: Vỏ đồng thời là kết cấu chịu lực; các tấm thép được dập định hình và hàn ghép thành một khối liền chịu uốn - xoắn."}},{"id":"s1902","kind":"figure","lesson":"12.1.1","title":"Hình 12.3. Loại thân vỏ liền khối - Loại khung liền vỏ (Hình 12.4): Đặc điểm: Khung và vỏ được liên kết chặt chẽ bằng bu lông hoặc đinh tán; cả hai cùng chia sẻ tải trọng tác dụng.","text":"Hình 12.3. Loại thân vỏ liền khối - Loại khung liền vỏ (Hình 12.4): Đặc điểm: Khung và vỏ được liên kết chặt chẽ bằng bu lông hoặc đinh tán; cả hai cùng chia sẻ tải trọng tác dụng.","pages":[147],"figure":{"number":"12.3","caption":"Hình 12.3. Loại thân vỏ liền khối - Loại khung liền vỏ (Hình 12.4): Đặc điểm: Khung và vỏ được liên kết chặt chẽ bằng bu lông hoặc đinh tán; cả hai cùng chia sẻ tải trọng tác dụng."}},{"id":"s1903","kind":"pdf","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"- Tạo không gian lắp đặt các cụm dẫn động điện (động cơ điện, bộ biến đổi điện, hệ thống làm mát) và cách ly rung động của các cụm này với khoang hành khách. Trên Hình 12.1, khoang hành khách (2) và khối pin (6) nằm trong vùng an toàn, được giới hạn bởi hai dầm dọc (3) và các dầm ngang (4). Vùng hấp thụ phía trước (1) và phía sau (5) có độ cứng thấp hơn nên bị hấp thụ khi xảy ra va chạm theo phương dọc, hấp thụ phần lớn năng lượng va chạm. Khi va chạm bên hông, lực va chạm F được dầm dọc tiếp nhận và phân bố sang các dầm ngang, hạn chế hấp thụ vào khối pin. b) Phân loại Theo cơ chế chịu lực, khung - vỏ ô tô được chia thành ba loại cơ bản: - Loại khung dầm rời chịu lực toàn bộ (Hình 12.2): Đặc điểm: Khung là kết cấu chịu toàn bộ tải trọng; vỏ xe được nối với khung qua các khớp đàn hồi (gối cao su) và hầu như không tham gia chịu lực.","pages":[147]},{"id":"s1904","kind":"pdf","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"Ứng dụng: Xe tải, xe khách khung rời, xe chuyên dụng và xe quân sự. Ứng dụng: Xe con, xe SUV đô thị và một số dòng xe bọc thép hạng nhẹ. Ứng dụng: Một số xe khách và xe địa hình.","pages":[147]},{"id":"s1905","kind":"figure","lesson":"12.1.1","title":"Hình 12.4. Loại khung liền vỏ Xe điện và xe hybrid cũng sử dụng ba dạng kết cấu chịu lực nêu trên: xe tải và xe buýt chủ yếu dùng khung dầm rời hoặc khung liền vỏ, xe con chủ yếu dùng thân vỏ liền khối. Điểm khác biệt so với ô tô truyền thống nằm ở vị trí bố trí khối pin trên khung - vỏ. Theo vị trí này, có các phương án bố trí cơ bản sau (Hình 12.5):","text":"Hình 12.4. Loại khung liền vỏ Xe điện và xe hybrid cũng sử dụng ba dạng kết cấu chịu lực nêu trên: xe tải và xe buýt chủ yếu dùng khung dầm rời hoặc khung liền vỏ, xe con chủ yếu dùng thân vỏ liền khối. Điểm khác biệt so với ô tô truyền thống nằm ở vị trí bố trí khối pin trên khung - vỏ. Theo vị trí này, có các phương án bố trí cơ bản sau (Hình 12.5):","pages":[148],"figure":{"number":"12.4","caption":"Hình 12.4. Loại khung liền vỏ Xe điện và xe hybrid cũng sử dụng ba dạng kết cấu chịu lực nêu trên: xe tải và xe buýt chủ yếu dùng khung dầm rời hoặc khung liền vỏ, xe con chủ yếu dùng thân vỏ liền khối. Điểm khác biệt so với ô tô truyền thống nằm ở vị trí bố trí khối pin trên khung - vỏ. Theo vị trí này, có các phương án bố trí cơ bản sau (Hình 12.5):"}},{"id":"s1906","kind":"figure","lesson":"12.1.1","title":"Hình 12.5. Các phương án bố trí khối pin trên khung - vỏ ô tô a) Dưới sàn, giữa hai cầu xe; b) Hai bên dầm dọc khung; c) Trên nóc và phía sau","text":"Hình 12.5. Các phương án bố trí khối pin trên khung - vỏ ô tô a) Dưới sàn, giữa hai cầu xe; b) Hai bên dầm dọc khung; c) Trên nóc và phía sau","pages":[148],"figure":{"number":"12.5","caption":"Hình 12.5. Các phương án bố trí khối pin trên khung - vỏ ô tô a) Dưới sàn, giữa hai cầu xe; b) Hai bên dầm dọc khung; c) Trên nóc và phía sau"}},{"id":"s1907","kind":"pdf","lesson":"12.1.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Công dụng, phân loại","text":"- Khối pin bố trí dưới sàn, giữa hai cầu xe (Hình 12.5a): khối pin dạng tấm phẳng chiếm phần lớn diện tích sàn, trọng tâm xe thấp, khối lượng phân bố đều lên hai cầu. Phương án này phổ biến trên xe con điện; thân xe; d) Dưới ghế sau trên xe hybrid 1. Cụm dẫn động điện; 2. Khối pin; 3. Khung hoặc sàn thân vỏ; 4. Động cơ đốt trong. - Khối pin bố trí hai bên hoặc giữa các dầm dọc khung (Hình 12.5b): các khối pin được gá trên khung dầm bằng giá đỡ, tận dụng khoảng trống trước đây dành cho","pages":[148]},{"id":"s1908","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"thùng nhiên liệu, hộp số và trục các-đăng. Phương án này dùng trên xe tải điện; - Khối pin bố trí trên nóc và phía sau thân xe (Hình 12.5c): giải phóng không gian dưới sàn để hạ thấp sàn khoang hành khách; khung xương nóc phải được gia cường. Phương án này dùng trên xe buýt điện; - Khối pin dung lượng nhỏ bố trí cục bộ dưới ghế sau hoặc trong khoang hành lý (Hình 12.5d): áp dụng trên xe con hybrid, khi xe vẫn giữ động cơ đốt trong và hệ thống truyền lực cơ khí. Phương án bố trí khối pin quyết định vị trí các dầm gia cường, các điểm gá và vùng bảo vệ trên khung - vỏ. Các đặc điểm này được trình bày cụ thể trong phần cấu tạo khung xe tải, khung - vỏ xe buýt và xe con dưới đây. 2.","pages":[149]},{"id":"s1909","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Cấu tạo khung xe tải Khung xe tải là kết cấu chịu lực chính của phương tiện, được thiết kế để bố trí và định vị chính xác các cụm tổng thành: động cơ, hộp số, hệ thống truyền lực, hệ thống treo, hệ thống lái, hệ thống phanh, buồng lái và thùng xe. Khung đồng thời truyền tải trọng của toàn bộ xe xuống hệ thống treo và cầu xe. Yêu cầu kỹ thuật đối với khung xe tải: - Độ bền và độ cứng vững cao để hạn chế biến dạng dưới tải lớn; - Khả năng chịu va chạm tốt; - Cho phép bố trí và lắp ráp các cụm tổng thành một cách phù hợp.","pages":[149]},{"id":"s1910","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Trong thực tế, khung xe tải hiện nay chủ yếu thuộc dạng khung dầm rời chịu lực toàn bộ do ưu thế về độ bền, độ cứng và khả năng chịu tải lớn - phù hợp với nhiệm vụ vận chuyển hàng nặng. a) Các dạng khung xe tải Theo hình dạng bố trí dầm (Hình 12.6), khung ô tô tải có các dạng cơ bản sau: Khung dạng thang dọc (Hình 12.6a): Đây là cấu tạo phổ biến nhất, gồm hai dầm dọc song song liên kết với nhau bằng các dầm ngang. Khung thang dọc có ưu điểm nổi bật là độ bền cao, cấu tạo đơn giản, dễ chế tạo và sửa chữa. Tuy nhiên, khung có nhược điểm về khả năng chống xoắn nếu không có biện pháp gia cường (thêm dầm chéo, giằng hộp, tấm tăng cứng). Khung dạng thang chéo (Hình 12.6b): Cấu tạo gồm hai dầm dọc được liên kết bởi các dầm chéo, giúp tăng cường độ cứng xoắn, hạn chế hấp thụ khi xe di chuyển trên đường gồ ghề hoặc chịu tải trọng không đối xứng.","pages":[149]},{"id":"s1911","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Nhược điểm là cấu tạo phức tạp hơn, khó bố trí một số cụm chi tiết. Khung dạng xương cá (Hình 12.6c): Cấu tạo gồm một dầm dọc chính liên kết với nhiều dầm ngang tỏa ra hai bên, tạo thành dạng xương cá. Đây là loại khung có khả năng chịu tải trọng lớn, cứng vững, thích hợp cho xe vận chuyển nặng và hoạt động ở những điều kiện khó khăn. Khung loại này được dùng trên một số xe như KamAZ 5320, Ural-375D. Khung dạng chữ X (Hình 12.6d): Gồm hai dầm chính giao nhau tạo thành chữ X, có thêm các dầm ngang xòe rộng ra để đỡ tải trọng. Loại khung này có ưu điểm chống xoắn tốt, giúp xe di chuyển ổn định. Nhược điểm là không thuận lợi cho","pages":[149]},{"id":"s1912","kind":"figure","lesson":"12.1.2","title":"Hình 12.6. Cấu tạo một số khung xe tải a) Dạng thang dọc; b) Dạng thang chéo; c) Dạng xương cá; d) Dạng chữ X","text":"Hình 12.6. Cấu tạo một số khung xe tải a) Dạng thang dọc; b) Dạng thang chéo; c) Dạng xương cá; d) Dạng chữ X","pages":[150],"figure":{"number":"12.6","caption":"Hình 12.6. Cấu tạo một số khung xe tải a) Dạng thang dọc; b) Dạng thang chéo; c) Dạng xương cá; d) Dạng chữ X"}},{"id":"s1913","kind":"figure","lesson":"12.1.2","title":"Hình 12.7. Cấu tạo khung xe tải thông dụng đã lắp ráp các cụm tổng thành","text":"Hình 12.7. Cấu tạo khung xe tải thông dụng đã lắp ráp các cụm tổng thành","pages":[150],"figure":{"number":"12.7","caption":"Hình 12.7. Cấu tạo khung xe tải thông dụng đã lắp ráp các cụm tổng thành"}},{"id":"s1914","kind":"figure","lesson":"12.1.2","title":"Hình 12.8. Cấu tạo khung ô tô tải","text":"Hình 12.8. Cấu tạo khung ô tô tải","pages":[150],"figure":{"number":"12.8","caption":"Hình 12.8. Cấu tạo khung ô tô tải"}},{"id":"s1915","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"việc lắp đặt các thùng xe có cấu tạo hình hộp dài. b) Cấu tạo khung xe tải thông dụng Cấu tạo khung xe tải đã lắp ráp các cụm tổng thành, được trình bày trên Hình 12.7. Khung là nơi lắp đặt toàn bộ cụm chi tiết thuộc khung gầm và động cơ.","pages":[150]},{"id":"s1916","kind":"figure","lesson":"12.1.2","title":"Hình 12.9. Liên kết quang dầm giữa khung xe và thùng xe","text":"Hình 12.9. Liên kết quang dầm giữa khung xe và thùng xe","pages":[151],"figure":{"number":"12.9","caption":"Hình 12.9. Liên kết quang dầm giữa khung xe và thùng xe"}},{"id":"s1917","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"a) Khung chịu lực; b) Liên kết trên khung Vật liệu và đặc điểm hình học (Hình 12.8a): Khung được chế tạo từ thép tấm dập định hình, vật liệu là thép cacbon trung bình; tiết diện dầm có thể thay đổi theo chiều dọc; chiều dày dầm dọc thông thường nằm trong khoảng 3 ÷ 7 mm, được tăng cường tại các vùng chịu tải trọng lớn (khu vực động cơ, hộp số, cầu sau, điểm đặt thùng hoặc thiết bị nặng). Mối ghép và biện pháp gia cường (Hình 12.8b): Tại các vị trí chịu tải lớn sử dụng mối ghép đinh tán hoặc bu lông cường độ cao; bố trí thêm dầm ngang và thanh giằng để phân tán tải trọng, nâng cao độ cứng theo uốn và xoắn. * Liên kết giữa khung xe và thùng xe Liên kết giữa khung xe và thùng vận tải được thực hiện gián tiếp qua khung phụ.","pages":[151]},{"id":"s1918","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Các dầm dọc của khung chính và các dầm dọc của khung phụ được kẹp chặt với nhau bằng mối ghép quang dầm (Hình 12.9), sử dụng bu lông kẹp hình chữ U hoặc đinh tán. Trong quá trình vận hành, mối ghép này chủ yếu chịu ứng suất cắt, đặc biệt khi xe xuất hiện gia tốc mạnh hoặc phanh gấp do xuất hiện lực quán tính lớn. Vì vậy, cần kiểm tra và siết chặt định kỳ các bu lông kẹp hoặc đinh tán để ngăn ngừa hiện tượng lỏng mối ghép. Các dầm ngang của khung chính được liên kết với các dầm dọc của khung phụ thông qua mối ghép đinh tán hoặc bu lông kẹp chặt. 1. Dầm dọc của khung phụ; 2. Dầm dọc của khung. * Liên kết khung xe với buồng lái Liên kết giữa khung xe và buồng lái phụ thuộc vào bố trí chung của ô tô.","pages":[151]},{"id":"s1919","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Trên ô tô tải thông dụng, có hai kiểu liên kết chính (Hình 12.10): Liên kết dạng lật (Hình 12.10a): Buồng lái có thể lật về phía trước với góc lật 50° ÷ 70°, quay quanh trục xoay đặt phía trước. Liên kết dạng lật giúp có thêm không gian phía trên động cơ, phù hợp cho việc kiểm tra và bảo dưỡng động cơ khi cần thiết. Phía sau buồng lái có khóa và cơ cấu bảo vệ khóa, giúp tránh tình trạng tự lật khi ô tô hoạt động. Liên kết dạng cố định (Hình 12.10b): Thường được sử dụng trên ô tô tải đầu dài, tạo điều kiện thuận lợi cho việc bảo dưỡng và sửa chữa động cơ. Cấu trúc này giúp cố định chắc chắn buồng lái trên khung, dễ dàng tiếp cận các cụm chi tiết khác của xe. Tại tất cả các điểm liên kết với buồng lái đều sử dụng gối đỡ đàn hồi, thông","pages":[151]},{"id":"s1920","kind":"figure","lesson":"12.1.2","title":"Hình 12.10. Liên kết khung và buồng lái a) Liên kết dạng lật; b) Liên kết dạng cố định","text":"Hình 12.10. Liên kết khung và buồng lái a) Liên kết dạng lật; b) Liên kết dạng cố định","pages":[152],"figure":{"number":"12.10","caption":"Hình 12.10. Liên kết khung và buồng lái a) Liên kết dạng lật; b) Liên kết dạng cố định"}},{"id":"s1921","kind":"figure","lesson":"12.1.2","title":"Hình 12.11. Các điểm liên kết khung xe với động cơ","text":"Hình 12.11. Các điểm liên kết khung xe với động cơ","pages":[152],"figure":{"number":"12.11","caption":"Hình 12.11. Các điểm liên kết khung xe với động cơ"}},{"id":"s1922","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"thường là gối cao su, để giảm rung động truyền từ khung lên buồng lái. Một số xe sử dụng phần tử đàn hồi bằng nhíp lá hoặc lò xo trụ, kết hợp với giảm chấn thủy lực để hạn chế rung động và nâng cao tiện nghi cho người lái. * Liên kết khung xe với các cụm tổng thành Liên kết khung xe với động cơ (Hình 12.11): Sử dụng bốn điểm treo cơ bản, qua các gối tựa cao su đàn hồi để phân cách rung động của động cơ với khung xe; đủ cứng để tiếp nhận phản lực mô men xoắn từ động cơ trong quá trình hoạt động. 1, 2, 3, 4. Các điểm treo của khung xe với động cơ. Liên kết khung xe với trục các-đăng (Hình 12.12): Áp dụng khi thân trục các-đăng dài, sử dụng gối đỡ trung gian gồm ổ xoay và ụ cao su dày. Gối đỡ trung","pages":[152]},{"id":"s1923","kind":"figure","lesson":"12.1.2","title":"Hình 12.12. Liên kết khung xe với trục các-đăng 1, 3, 5, 6, 7. Trục các-đăng; 2, 4. Gối đỡ trung gian.","text":"Hình 12.12. Liên kết khung xe với trục các-đăng 1, 3, 5, 6, 7. Trục các-đăng; 2, 4. Gối đỡ trung gian.","pages":[153],"figure":{"number":"12.12","caption":"Hình 12.12. Liên kết khung xe với trục các-đăng 1, 3, 5, 6, 7. Trục các-đăng; 2, 4. Gối đỡ trung gian."}},{"id":"s1924","kind":"figure","lesson":"12.1.2","title":"Hình 12.13. Liên kết khung xe với cầu xe a) Liên kết khung xe với cầu bị động; b) Liên kết khung xe với cầu chủ động","text":"Hình 12.13. Liên kết khung xe với cầu xe a) Liên kết khung xe với cầu bị động; b) Liên kết khung xe với cầu chủ động","pages":[153],"figure":{"number":"12.13","caption":"Hình 12.13. Liên kết khung xe với cầu xe a) Liên kết khung xe với cầu bị động; b) Liên kết khung xe với cầu chủ động"}},{"id":"s1925","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"- Tăng khả năng tự lựa của trục, giảm tải trọng động tác dụng lên thân trục; - Bảo đảm góc nghiêng của trục các-đăng không vượt quá giới hạn cho phép, duy trì sự làm việc ổn định của hệ thống truyền lực. Liên kết khung xe với cầu xe (Hình 12.13): Thực hiện thông qua hệ thống treo. Cấu trúc liên kết bao gồm: - Phần tử đàn hồi (lò xo, nhíp, buồng hơi…) cho phép bánh xe dịch chuyển tương đối với khung theo phương thẳng đứng; - Phần tử dẫn hướng (đòn ngang, đòn dọc, thanh Panhard…) bảo đảm mối quan hệ động học chính xác giữa bánh xe và khung, duy trì ổn định hướng trong quá trình vận hành. * Đặc điểm khung xe tải điện Khung xe tải điện về cơ bản vẫn giữ dạng khung thang dọc gồm hai dầm dọc","pages":[153]},{"id":"s1926","kind":"figure","lesson":"12.1.2","title":"Hình 12.14. Sơ đồ bố trí các cụm trên khung xe tải điện 1. Vị trí buồng lái; 2. Cầu trước; 3. Giá đỡ khối pin; 4. Thanh chắn bảo vệ bên","text":"Hình 12.14. Sơ đồ bố trí các cụm trên khung xe tải điện 1. Vị trí buồng lái; 2. Cầu trước; 3. Giá đỡ khối pin; 4. Thanh chắn bảo vệ bên","pages":[154],"figure":{"number":"12.14","caption":"Hình 12.14. Sơ đồ bố trí các cụm trên khung xe tải điện 1. Vị trí buồng lái; 2. Cầu trước; 3. Giá đỡ khối pin; 4. Thanh chắn bảo vệ bên"}},{"id":"s1927","kind":"figure","lesson":"12.1.2","title":"Hình 12.15. Liên kết khối pin với dầm dọc khung xe tải điện 1. Vỏ khối pin; 2. Bu lông; 3. Dầm dọc tiết diện chữ U; 4. Dầm ngang gia cường;","text":"Hình 12.15. Liên kết khối pin với dầm dọc khung xe tải điện 1. Vỏ khối pin; 2. Bu lông; 3. Dầm dọc tiết diện chữ U; 4. Dầm ngang gia cường;","pages":[154],"figure":{"number":"12.15","caption":"Hình 12.15. Liên kết khối pin với dầm dọc khung xe tải điện 1. Vỏ khối pin; 2. Bu lông; 3. Dầm dọc tiết diện chữ U; 4. Dầm ngang gia cường;"}},{"id":"s1928","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"liên kết bằng các dầm ngang, bảo đảm khả năng chịu tải lớn và thuận lợi cho việc lắp các loại thùng chuyên dùng. Sự khác biệt nằm ở cách bố trí các cụm trên khung (Hình 12.14): - Động cơ đốt trong, hộp số, trục các-đăng và thùng nhiên liệu được thay bằng cụm dẫn động điện (5) bố trí tại cầu sau; khoảng trống giữa hai cầu được dùng để gá khối pin; - Các khối pin (8) được treo hai bên ngoài dầm dọc (6) hoặc đặt giữa hai dầm dọc, qua các giá đỡ (3). Khối lượng khối pin truyền vào khung tại các điểm gá, nên tại các vị trí này bố trí thêm dầm ngang (7) và tấm gia cường; - Hai bên khung lắp thanh chắn bảo vệ (4) để hạn chế va chạm trực tiếp vào khối pin từ phía bên; - Vị trí buồng lái (1) và cầu trước (2) về cơ bản không thay đổi so với xe tải truyền thống. hông; 5. Cụm dẫn động điện; 6. Dầm dọc; 7. Dầm ngang; 8. Khối pin. 5. Giá đỡ; 6. Gối đệm đàn hồi.","pages":[154]},{"id":"s1929","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Liên kết giữa khối pin và dầm dọc khung được thể hiện trên Hình 12.15. Giá đỡ (5) được bắt chặt vào thân dầm dọc (3) bằng bu lông (2); thông thường không hàn trực tiếp giá đỡ lên dầm dọc để tránh làm giảm độ bền mỏi của dầm. Vỏ khối pin (1) đặt trên giá đỡ qua các gối đệm đàn hồi (6), có tác dụng giảm rung động và va đập truyền từ khung lên khối pin. Dầm ngang gia cường (4) bố trí tại vị trí gá,","pages":[154]},{"id":"s1930","kind":"figure","lesson":"12.1.2","title":"Hình 12.16. Cấu tạo khung dầm và khung dàn trên ô tô buýt - Cấu tạo khung dầm: Khung dầm truyền thống của xe buýt được phát triển trên cơ sở khung dầm xe tải cùng cấp tải trọng. Tuy nhiên, kiểu cấu tạo này hiện nay ít được sử dụng vì các nhược điểm:","text":"Hình 12.16. Cấu tạo khung dầm và khung dàn trên ô tô buýt - Cấu tạo khung dầm: Khung dầm truyền thống của xe buýt được phát triển trên cơ sở khung dầm xe tải cùng cấp tải trọng. Tuy nhiên, kiểu cấu tạo này hiện nay ít được sử dụng vì các nhược điểm:","pages":[155],"figure":{"number":"12.16","caption":"Hình 12.16. Cấu tạo khung dầm và khung dàn trên ô tô buýt - Cấu tạo khung dầm: Khung dầm truyền thống của xe buýt được phát triển trên cơ sở khung dầm xe tải cùng cấp tải trọng. Tuy nhiên, kiểu cấu tạo này hiện nay ít được sử dụng vì các nhược điểm:"}},{"id":"s1931","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"tăng độ cứng xoắn của khung tại khu vực chịu tải tập trung. Trên xe tải hybrid, động cơ đốt trong, hộp số và trục các-đăng vẫn được giữ lại; động cơ điện có thể bố trí giữa ly hợp và hộp số hoặc lắp trên hệ thống truyền lực. Khối pin có dung lượng nhỏ hơn xe tải điện, được gá trên một bên dầm dọc theo cách tương tự Hình 12.15. Vì vậy, kết cấu khung thay đổi ít, chủ yếu là bổ sung các giá đỡ và gia cường cục bộ tại điểm gá. c) Cấu tạo khung và vỏ xe buýt Ngoài công dụng chung của khung ô tô, kết cấu khung - vỏ trên xe buýt còn phải tạo khoang hành khách chuyên chở người, bảo đảm: - Bao kín và kiểm soát chất lượng môi trường vận tải bên trong (an toàn, thông gió, chiếu sáng); - Kiểm soát ồn và dao động; - Bố trí cửa lên xuống và lối thoát hiểm hợp lý.","pages":[155]},{"id":"s1932","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Trên xe buýt, khoang hành khách và buồng lái thường được tổ hợp thành một vỏ chung, cho phép độ cứng uốn và xoắn tổng thể cao. * Cấu tạo khung và vỏ của xe buýt tiêu chuẩn","pages":[155]},{"id":"s1933","kind":"figure","lesson":"12.1.2","title":"Hình 12.17. Cấu tạo khung dàn và xương vỏ trên ô tô buýt Vỏ xe buýt tiêu chuẩn (Hình 12.17) được thiết kế dựa trên tính năng sử dụng - bao gồm bố trí cửa lên xuống, nội thất và khoang hành khách - tùy theo mục đích","text":"Hình 12.17. Cấu tạo khung dàn và xương vỏ trên ô tô buýt Vỏ xe buýt tiêu chuẩn (Hình 12.17) được thiết kế dựa trên tính năng sử dụng - bao gồm bố trí cửa lên xuống, nội thất và khoang hành khách - tùy theo mục đích","pages":[156],"figure":{"number":"12.17","caption":"Hình 12.17. Cấu tạo khung dàn và xương vỏ trên ô tô buýt Vỏ xe buýt tiêu chuẩn (Hình 12.17) được thiết kế dựa trên tính năng sử dụng - bao gồm bố trí cửa lên xuống, nội thất và khoang hành khách - tùy theo mục đích"}},{"id":"s1934","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"+ Khối lượng bản thân lớn, làm giảm khả năng tiết kiệm nhiên liệu và tải trọng chuyên chở; + Khó bảo đảm cách âm và cách nhiệt cho khoang hành khách. Các xe buýt tiêu chuẩn phổ biến hiện nay sử dụng khung liền vỏ hoặc khung dầm kết hợp khung dàn vỏ (Hình 12.16), điển hình là dòng Thaco Town 29 chỗ. Cấu tạo này có các ưu điểm: + Giảm khối lượng xe; + Tăng khả năng cách âm, cách nhiệt; + Cho phép hạ thấp bậc lên xe và bố trí động cơ ở vị trí phù hợp; + Tối ưu hóa không gian khoang hành khách. Hệ thống treo trên xe buýt được thiết kế đạt chất lượng cao hơn xe tải, nhằm giảm rung lắc, hạn chế lắc ngang thân xe, kiểm soát biên độ dịch chuyển và gia tốc, qua đó bảo đảm sự êm dịu cho hành khách. - Cấu tạo khung dàn: Khung dàn của xe buýt tiêu chuẩn (Hình 12.16) sử dụng hệ dầm - giằng không gian làm khung xương cho thân vỏ.","pages":[156]},{"id":"s1935","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Đặc điểm: + Vật liệu thép cường độ cao, tiết diện hộp 40 × 60 mm đến 40 × 80 mm, chiều dày 2 ÷ 3 mm; + Phần đầu xe được thiết kế có khả năng đàn hồi và giảm chấn theo phương dọc để hấp thụ rung động và lực va chạm từ phía trước, bảo vệ hành khách trong tình huống va chạm nhỏ; + Phần sau xe bố trí không gian cho động cơ và hệ thống truyền lực; + Phần giữa xe được hàn liền thành dàn, nâng cao độ cứng tại khu vực sàn và gầm trung tâm. Sàn xe hiện đại được chế tạo từ thép lá dày hoặc hợp kim nhôm, có ba chức năng đồng thời: tăng độ cứng tổng thể; bao kín khoang hành khách; cách âm - cách nhiệt. Một số xe buýt gầm thấp sử dụng khung dàn thấp kết hợp khung phụ dạng hộp tại các khu vực chịu tải lớn (cụm hệ thống treo, bệ ghế, cửa) nhằm hạ trọng tâm xe, tăng ổn định khi quay vòng.","pages":[156]},{"id":"s1936","kind":"figure","lesson":"12.1.2","title":"Hình 12.18. Cấu tạo vỏ trên ô tô buýt 1, 2, 3, 7. Khung sườn; 4. Tấm nóc; 5. Tấm sau; 6. Tấm bên; 8. Phần bao kín sàn xe.","text":"Hình 12.18. Cấu tạo vỏ trên ô tô buýt 1, 2, 3, 7. Khung sườn; 4. Tấm nóc; 5. Tấm sau; 6. Tấm bên; 8. Phần bao kín sàn xe.","pages":[157],"figure":{"number":"12.18","caption":"Hình 12.18. Cấu tạo vỏ trên ô tô buýt 1, 2, 3, 7. Khung sườn; 4. Tấm nóc; 5. Tấm sau; 6. Tấm bên; 8. Phần bao kín sàn xe."}},{"id":"s1937","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"vận hành (xe buýt thành phố, liên tỉnh, đường dài). Cấu trúc vỏ gồm hai thành phần chính: + Xương vỏ: Chế tạo từ thép hộp cường độ cao, tiết diện 30 × 30 mm đến 40 × 40 mm, chiều dày 0,8 ÷ 1,5 mm; + Tấm vỏ bao kín: Liên kết với xương vỏ bằng hàn điểm, đinh tán, bu lông hoặc keo dán kết cấu, kèm bịt kín đường ghép để chống ăn mòn và cải thiện cách âm - cách nhiệt. Các vùng chịu tải hoặc dễ mỏi (bản lề cửa, khung cửa kính dài, bệ ghế, nút giao cột - đai) được gia cường cục bộ hoặc tăng bề dày tấm.","pages":[157]},{"id":"s1938","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Cấu trúc vỏ xe buýt hiện đại thường được thiết kế thành hai lớp (Hình 12.18): + Lớp ngoài: thép tấm hoặc hợp kim nhôm, liên kết với xương vỏ bằng hàn điểm, đinh tán hoặc bu lông; có nhiệm vụ tăng độ cứng vỏ, chống mài mòn, chống ăn mòn (oxy hóa) và cải thiện khí động học, thẩm mỹ; + Lớp trong (lớp bao kín): thép tấm, nhựa cứng hoặc vật liệu polymer dẻo; có nhiệm vụ bao kín khoang hành khách, tăng cách âm - cách nhiệt, tạo bề mặt hoàn thiện cho nội thất. Giữa hai lớp vỏ bố trí vật liệu cách nhiệt và keo cao su đàn hồi, vừa tạo liên kết chắc chắn vừa giảm rung và tăng tiện nghi.","pages":[157]},{"id":"s1939","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"Thành bên xe bố trí cửa lên xuống rộng, cửa phía sau thường lớn hơn cửa trước; vùng hốc bánh xe được thiết kế riêng kết hợp liên kết với phần giữa thành bên nhằm tăng độ cứng, phân tán tải trọng và bảo vệ hành khách khi xảy ra va chạm ngang. * Đặc điểm khung và vỏ xe buýt điện, xe buýt hybrid Xe buýt điện sử dụng kết cấu khung dàn và vỏ tương tự xe buýt tiêu chuẩn. Do không còn động cơ đốt trong và hệ thống truyền lực cơ khí, việc bố trí các cụm","pages":[157]},{"id":"s1940","kind":"figure","lesson":"12.1.3","title":"Hình 12.19. Sơ đồ bố trí khối pin và gia cường khung xương trên xe buýt điện","text":"Hình 12.19. Sơ đồ bố trí khối pin và gia cường khung xương trên xe buýt điện","pages":[158],"figure":{"number":"12.19","caption":"Hình 12.19. Sơ đồ bố trí khối pin và gia cường khung xương trên xe buýt điện"}},{"id":"s1941","kind":"pdf","lesson":"12.1.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung xe tải","text":"trên xe có các đặc điểm sau (Hình 12.19): - Khối pin (3) được bố trí trên nóc xe, ở khoang phía sau hoặc dưới sàn; phương án đặt trên nóc cho phép giữ sàn khoang hành khách thấp và phẳng; - Khi khối pin đặt trên nóc, khung xương nóc được bổ sung các dầm gia cường (2), các cột đứng (7) được tăng cứng để chịu thêm tải trọng và bảo đảm độ bền của thân xe khi lật; - Sàn thấp (6) liền mạch từ cửa trước đến cửa sau, phù hợp cho hành khách lên xuống qua cửa (1); - Khoang phía sau (4) dùng để bố trí một phần khối pin, bộ biến đổi điện và hệ thống làm mát; cụm dẫn động điện (5) lắp tại cầu sau. 1. Cửa lên xuống; 2. Dầm gia cường khung xương nóc; 3. Khối pin; 4. Khoang phía sau; 5. Cụm dẫn động điện; 6. Sàn thấp; 7. Cột đứng khung xương.","pages":[158]},{"id":"s1942","kind":"pdf","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"Khi khối pin đặt trên nóc, trọng tâm xe được nâng cao; vì vậy khung xương và hệ thống treo được thiết kế để hạn chế lắc ngang thân xe. Trên xe buýt hybrid, động cơ đốt trong vẫn đặt ở khoang phía sau, khối pin dung lượng nhỏ được đặt trên nóc hoặc trong khoang phía sau; kết cấu khung dàn được giữ nguyên, chỉ gia cường cục bộ tại các vị trí gá khối pin. 3. Cấu tạo khung và vỏ xe con Trên xe con, có ba dạng cấu tạo khung - vỏ tương ứng với ba mức độ tham gia chịu lực của thân vỏ. a) Cấu tạo dạng thân vỏ rời Cấu tạo thân vỏ rời là dạng kết cấu trong đó thân xe và khung dầm được chế tạo tách biệt, sau đó lắp ghép với nhau bằng bu lông - đai ốc hoặc mối hàn ghép (Hình 12.20). Đặc điểm cấu tạo: Khung dầm gồm hai dầm dọc chạy suốt chiều dài xe, liên kết bằng các dầm ngang. Tiết diện dầm dạng chữ U, chữ L hoặc hộp kín để tăng độ cứng xoắn và khả","pages":[158]},{"id":"s1943","kind":"figure","lesson":"12.1.3","title":"Hình 12.20. Cấu tạo dạng thân vỏ rời b) Cấu tạo dạng thân vỏ chịu tải một phần Đây là dạng trung gian giữa thân vỏ rời và thân vỏ chịu tải hoàn toàn (Hình 12.21). Đặc điểm cấu tạo: Phần thân vỏ khu vực giữa xe được thiết kế có độ cứng vững để trực tiếp chịu tải trọng. Hai đầu trước và sau bố trí khung phụ bằng thép để tăng cường khả năng chịu lực, đồng thời làm giá đỡ cho động cơ, hộp số, hệ thống treo và dầm cầu. Khung phụ liên kết với thân xe bằng bu lông hoặc hàn.","text":"Hình 12.20. Cấu tạo dạng thân vỏ rời b) Cấu tạo dạng thân vỏ chịu tải một phần Đây là dạng trung gian giữa thân vỏ rời và thân vỏ chịu tải hoàn toàn (Hình 12.21). Đặc điểm cấu tạo: Phần thân vỏ khu vực giữa xe được thiết kế có độ cứng vững để trực tiếp chịu tải trọng. Hai đầu trước và sau bố trí khung phụ bằng thép để tăng cường khả năng chịu lực, đồng thời làm giá đỡ cho động cơ, hộp số, hệ thống treo và dầm cầu. Khung phụ liên kết với thân xe bằng bu lông hoặc hàn.","pages":[159],"figure":{"number":"12.20","caption":"Hình 12.20. Cấu tạo dạng thân vỏ rời b) Cấu tạo dạng thân vỏ chịu tải một phần Đây là dạng trung gian giữa thân vỏ rời và thân vỏ chịu tải hoàn toàn (Hình 12.21). Đặc điểm cấu tạo: Phần thân vỏ khu vực giữa xe được thiết kế có độ cứng vững để trực tiếp chịu tải trọng. Hai đầu trước và sau bố trí khung phụ bằng thép để tăng cường khả năng chịu lực, đồng thời làm giá đỡ cho động cơ, hộp số, hệ thống treo và dầm cầu. Khung phụ liên kết với thân xe bằng bu lông hoặc hàn."}},{"id":"s1944","kind":"figure","lesson":"12.1.3","title":"Hình 12.21. Cấu tạo dạng thân vỏ chịu tải một phần","text":"Hình 12.21. Cấu tạo dạng thân vỏ chịu tải một phần","pages":[159],"figure":{"number":"12.21","caption":"Hình 12.21. Cấu tạo dạng thân vỏ chịu tải một phần"}},{"id":"s1945","kind":"pdf","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"năng chịu tải. Các cụm quan trọng (động cơ, cầu xe, hệ thống lái, hệ thống treo) được lắp đặt trực tiếp lên khung. Thân vỏ chỉ đặt lên trên khung, tạo hình dáng và bố trí khoang hành khách. Dạng này hiện ít được sử dụng cho xe con đô thị, phổ biến trên các dòng SUV cỡ lớn và xe bán tải như Toyota Land Cruiser, Mitsubishi Pajero Sport, Ford Everest, Ford Ranger, Toyota Hilux… Tải trọng được phân bố đồng thời cho cả thân vỏ và khung phụ, giúp xe bảo đảm độ bền và giảm khối lượng so với cấu tạo thân vỏ rời. Dạng này được sử dụng phổ biến trên các xe con hạng trung và xe du lịch phổ thông (Toyota Camry, Honda Accord…); một số mẫu MPV (Toyota Innova, Kia Carnival…).","pages":[159]},{"id":"s1946","kind":"figure","lesson":"12.1.3","title":"Hình 12.22. Hệ sàn xe dạng thân vỏ chịu tải hoàn toàn 1. Sàn khoang hành lý; 2. Dầm dọc trung tâm; 3, 6. Hốc bánh xe; 4. Dầm ngang;","text":"Hình 12.22. Hệ sàn xe dạng thân vỏ chịu tải hoàn toàn 1. Sàn khoang hành lý; 2. Dầm dọc trung tâm; 3, 6. Hốc bánh xe; 4. Dầm ngang;","pages":[160],"figure":{"number":"12.22","caption":"Hình 12.22. Hệ sàn xe dạng thân vỏ chịu tải hoàn toàn 1. Sàn khoang hành lý; 2. Dầm dọc trung tâm; 3, 6. Hốc bánh xe; 4. Dầm ngang;"}},{"id":"s1947","kind":"figure","lesson":"12.1.3","title":"Hình 12.23. Cấu tạo thân vỏ xe dạng chịu tải hoàn toàn 1. Dầm chống đứng D; 2. Dầm chống đứng C; 3. Tôn vỏ mui; 4. Tấm dẫn hướng gió; 5. Hốc đặt bánh xe; 6. Dầm dọc phía trước, trái; 7. Dầm chứa khóa nắp capo; 8. Cấu","text":"Hình 12.23. Cấu tạo thân vỏ xe dạng chịu tải hoàn toàn 1. Dầm chống đứng D; 2. Dầm chống đứng C; 3. Tôn vỏ mui; 4. Tấm dẫn hướng gió; 5. Hốc đặt bánh xe; 6. Dầm dọc phía trước, trái; 7. Dầm chứa khóa nắp capo; 8. Cấu","pages":[160],"figure":{"number":"12.23","caption":"Hình 12.23. Cấu tạo thân vỏ xe dạng chịu tải hoàn toàn 1. Dầm chống đứng D; 2. Dầm chống đứng C; 3. Tôn vỏ mui; 4. Tấm dẫn hướng gió; 5. Hốc đặt bánh xe; 6. Dầm dọc phía trước, trái; 7. Dầm chứa khóa nắp capo; 8. Cấu"}},{"id":"s1948","kind":"pdf","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"c) Cấu tạo dạng thân vỏ chịu tải hoàn toàn Loại thân vỏ chịu tải hoàn toàn được hình thành trên cơ sở hệ sàn xe đóng vai trò chịu lực chính thay thế cho khung dầm truyền thống (Hình 12.22). Trên sàn xe bố trí các dầm dọc, dầm ngang, ngạch cửa, hốc bánh xe và khoang hành lý, tất cả được hàn ghép thành một khối liền mạch, sau đó liên kết trực tiếp với các tấm thân vỏ như trụ A, B, C, D, mui xe và vách chắn. Nhờ vậy, toàn bộ thân xe trở thành một kết cấu đồng nhất vừa đảm nhận chức năng chịu lực, vừa tạo hình dáng tổng thể (Hình 12.23). Đặc điểm nổi bật của dạng kết cấu này là có độ cứng xoắn cao, trọng lượng giảm, tiết kiệm vật liệu và thuận lợi trong việc mở rộng không gian nội thất.","pages":[160]},{"id":"s1949","kind":"pdf","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"Kiểu cấu tạo này được sử dụng rộng rãi trên hầu hết các dòng xe du lịch phổ thông (Toyota Vios, Hyundai Accent, Honda City, Mazda 3, Kia K3…) và SUV đô thị (Honda CR-V, Mazda CX-5, Hyundai Tucson…). trúc khung trước phía dưới; 9. Dầm chống đứng A; 10. Ngạch cửa; 11. Hệ sàn xe; 12. Dầm chống đứng B; 13. Vỏ ngoài cửa; 14. Nắp bình xăng Bên cạnh đó, dạng kết cấu hệ dầm định hình cũng được ứng dụng, với đặc trưng là mạng lưới khung sườn không gian cấu tạo từ hợp kim nhôm (Hình 12.24).","pages":[160]},{"id":"s1950","kind":"figure","lesson":"12.1.3","title":"Hình 12.24. Hệ khung dầm định hình dạng chịu tải hoàn toàn * Khung - vỏ xe con điện dạng khung xe con điện Trên xe con điện, thân vỏ chịu tải hoàn toàn được phát triển thành dạng khung xe con điện (còn gọi là nền tảng dạng ván trượt – skateboard). Khối pin dạng tấm phẳng chiếm phần lớn diện tích sàn giữa hai cầu; cụm dẫn động điện, hệ thống treo và hệ thống lái được lắp trên khung phụ trước và sau (Hình 12.25). Cấu tạo gồm:","text":"Hình 12.24. Hệ khung dầm định hình dạng chịu tải hoàn toàn * Khung - vỏ xe con điện dạng khung xe con điện Trên xe con điện, thân vỏ chịu tải hoàn toàn được phát triển thành dạng khung xe con điện (còn gọi là nền tảng dạng ván trượt – skateboard). Khối pin dạng tấm phẳng chiếm phần lớn diện tích sàn giữa hai cầu; cụm dẫn động điện, hệ thống treo và hệ thống lái được lắp trên khung phụ trước và sau (Hình 12.25). Cấu tạo gồm:","pages":[161],"figure":{"number":"12.24","caption":"Hình 12.24. Hệ khung dầm định hình dạng chịu tải hoàn toàn * Khung - vỏ xe con điện dạng khung xe con điện Trên xe con điện, thân vỏ chịu tải hoàn toàn được phát triển thành dạng khung xe con điện (còn gọi là nền tảng dạng ván trượt – skateboard). Khối pin dạng tấm phẳng chiếm phần lớn diện tích sàn giữa hai cầu; cụm dẫn động điện, hệ thống treo và hệ thống lái được lắp trên khung phụ trước và sau (Hình 12.25). Cấu tạo gồm:"}},{"id":"s1951","kind":"figure","lesson":"12.1.3","title":"Hình 12.25. Cấu tạo khung của xe con điện 1. Vùng hấp thụ va chạm; 2. Khung phụ trước; 3. Dầm dọc; 4. Dầm ngang; 5. Khung bao hộp pin; 6. Cụm dẫn động điện; 7. Khung phụ sau; 8. Mô-đun pin.","text":"Hình 12.25. Cấu tạo khung của xe con điện 1. Vùng hấp thụ va chạm; 2. Khung phụ trước; 3. Dầm dọc; 4. Dầm ngang; 5. Khung bao hộp pin; 6. Cụm dẫn động điện; 7. Khung phụ sau; 8. Mô-đun pin.","pages":[161],"figure":{"number":"12.25","caption":"Hình 12.25. Cấu tạo khung của xe con điện 1. Vùng hấp thụ va chạm; 2. Khung phụ trước; 3. Dầm dọc; 4. Dầm ngang; 5. Khung bao hộp pin; 6. Cụm dẫn động điện; 7. Khung phụ sau; 8. Mô-đun pin."}},{"id":"s1952","kind":"pdf","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"Các dầm được chế tạo bằng phương pháp ép đùn hoặc dập tạo hình; tại các vị trí chịu ứng suất lớn sử dụng khối nhôm đúc. Kết cấu này có trọng lượng nhẹ, độ cứng vững cao, thường được sử dụng trên các xe du lịch cao cấp như Mercedes-Benz E- Class, BMW 5-Series, Audi Q5. - Hộp pin gồm khung bao (5) chế tạo từ các thanh định hình bằng thép cường độ cao hoặc hợp kim nhôm; bên trong chứa các mô-đun pin (8), được ngăn cách bởi các dầm ngang (4). Khung bao và các dầm ngang vừa bảo vệ mô-đun pin, vừa tham gia tăng độ cứng cho sàn xe; - Hai dầm dọc (3) chạy dọc hai bên sàn, có tiết diện hộp kín, là kết cấu chịu lực chính khi va chạm bên hông; - Khung phụ trước (2) và khung phụ sau (7) là nơi lắp cụm dẫn động điện (6), hệ thống treo và hệ thống lái, đồng thời đóng vai trò vùng hấp thụ va chạm (1) ở phía trước và phía sau.","pages":[161]},{"id":"s1953","kind":"figure","lesson":"12.1.3","title":"Hình 12.26. Mặt cắt ngang sàn xe con điện tại vị trí khối pin","text":"Hình 12.26. Mặt cắt ngang sàn xe con điện tại vị trí khối pin","pages":[162],"figure":{"number":"12.26","caption":"Hình 12.26. Mặt cắt ngang sàn xe con điện tại vị trí khối pin"}},{"id":"s1954","kind":"figure","lesson":"12.1.3","title":"Hình 12.27. Sơ đồ bố trí các cụm trên thân vỏ xe con hybrid 1. Động cơ đốt trong; 2. Dầm ngang gia cường; 3. Khoang hành lý; 4. Vùng hấp","text":"Hình 12.27. Sơ đồ bố trí các cụm trên thân vỏ xe con hybrid 1. Động cơ đốt trong; 2. Dầm ngang gia cường; 3. Khoang hành lý; 4. Vùng hấp","pages":[162],"figure":{"number":"12.27","caption":"Hình 12.27. Sơ đồ bố trí các cụm trên thân vỏ xe con hybrid 1. Động cơ đốt trong; 2. Dầm ngang gia cường; 3. Khoang hành lý; 4. Vùng hấp"}},{"id":"s1955","kind":"pdf","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"So với xe con truyền thống, khung xe con điện có trọng tâm thấp, khối lượng phân bố đều trên hai cầu và khoang hành khách rộng do sàn phẳng, không có rãnh dẫn trục các-đăng. Tuy nhiên, khối pin làm tăng khối lượng bản thân của xe, nên thân vỏ thường sử dụng thép cường độ cao và hợp kim nhôm để giảm khối lượng. Liên kết giữa hộp pin và thân vỏ có hai dạng cơ bản (Hình 12.26): - Hộp pin tách rời (Hình 12.26a): Hộp pin là một cụm độc lập, có nắp đậy riêng, được bắt bu lông (6) vào dầm dọc (7) từ phía dưới sàn xe (2). Dạng này phù hợp cho việc tháo lắp, thay thế khối pin; - Khối pin tích hợp kết cấu (Hình 12.26b): Nắp hộp pin đồng thời là sàn xe (2), khối pin trở thành một phần kết cấu chịu lực của thân vỏ.","pages":[162]},{"id":"s1956","kind":"pdf","lesson":"12.1.3","title":"Khung vỏ và thiết bị phụ trên ô tô · Cấu tạo khung và vỏ xe con","text":"Dạng này giảm số chi tiết, giảm khối lượng và tăng độ cứng xoắn của thân xe, nhưng việc sửa chữa, thay thế khối pin phức tạp hơn. a) Hộp pin tách rời; b) Khối pin tích hợp kết cấu 1. Gân gia cường; 2. Sàn xe; 3. Khung bao hộp pin; 4. Tấm bảo vệ đáy; 5. Mô-đun pin; 6. Bu lông liên kết; 7. Dầm dọc. Ở cả hai dạng, dưới đáy hộp pin có tấm bảo vệ (4) chống va đập từ mặt đường; bên trong dầm dọc bố trí các gân gia cường (1) để tăng khả năng hấp thụ năng lượng khi va chạm bên hông. thụ phía sau; 5. Thùng nhiên liệu; 6. Khối pin; 7. Động cơ điện.","pages":[162]},{"id":"s1957","kind":"figure","lesson":"12.2.1","title":"Hình 12.28. Sơ đồ bố trí hệ thống điều chỉnh áp suất hơi lốp trên xe ZIL-131 1. Phanh tay; 2. Bình chứa khí nén; 3. Hộp số phân phối; 4. Đường dẫn khí nén tới còi hơi; 5. Van khí nén điện từ điều khiển hộp số phân phối; 6. Khóa điều khiển bằng tay; 7. Tổng van phanh; 8. Còi hơi; 9. Lốp xe; 10. Bầu phanh; 11. Má phanh; 12. Công tắc đèn phanh; 13. Bàn đạp phanh; 14. Van hạn chế áp suất; 15. Đường dẫn khí nén tới van giữ hơi; 16. Máy nén khí; 17. Van điều hòa áp suất; 18. Thân van điều khiển; 19. Van khóa khí","text":"Hình 12.28. Sơ đồ bố trí hệ thống điều chỉnh áp suất hơi lốp trên xe ZIL-131 1. Phanh tay; 2. Bình chứa khí nén; 3. Hộp số phân phối; 4. Đường dẫn khí nén tới còi hơi; 5. Van khí nén điện từ điều khiển hộp số phân phối; 6. Khóa điều khiển bằng tay; 7. Tổng van phanh; 8. Còi hơi; 9. Lốp xe; 10. Bầu phanh; 11. Má phanh; 12. Công tắc đèn phanh; 13. Bàn đạp phanh; 14. Van hạn chế áp suất; 15. Đường dẫn khí nén tới van giữ hơi; 16. Máy nén khí; 17. Van điều hòa áp suất; 18. Thân van điều khiển; 19. Van khóa khí","pages":[163],"figure":{"number":"12.28","caption":"Hình 12.28. Sơ đồ bố trí hệ thống điều chỉnh áp suất hơi lốp trên xe ZIL-131 1. Phanh tay; 2. Bình chứa khí nén; 3. Hộp số phân phối; 4. Đường dẫn khí nén tới còi hơi; 5. Van khí nén điện từ điều khiển hộp số phân phối; 6. Khóa điều khiển bằng tay; 7. Tổng van phanh; 8. Còi hơi; 9. Lốp xe; 10. Bầu phanh; 11. Má phanh; 12. Công tắc đèn phanh; 13. Bàn đạp phanh; 14. Van hạn chế áp suất; 15. Đường dẫn khí nén tới van giữ hơi; 16. Máy nén khí; 17. Van điều hòa áp suất; 18. Thân van điều khiển; 19. Van khóa khí"}},{"id":"s1958","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Xe con hybrid giữ nguyên động cơ đốt trong (1), hộp số và thùng nhiên liệu (5), đồng thời bổ sung động cơ điện (7) và khối pin dung lượng nhỏ (6) (Hình 12.27). Thân vỏ vẫn là dạng chịu tải hoàn toàn của xe con truyền thống, với các điều chỉnh cục bộ sau: - Khối pin thường được bố trí dưới ghế sau hoặc trong khoang hành lý (3); khu vực này được gia cường bằng các dầm ngang (2) và giá đỡ để chịu khối lượng khối pin và bảo vệ khối pin khi va chạm; - Vùng hấp thụ phía sau (4) được thiết kế để hấp thụ năng lượng va chạm trước khi lực truyền tới khối pin và thùng nhiên liệu; - Thân vỏ bố trí thêm không gian cho đường dây cao áp, hệ thống làm mát khối pin và bộ biến đổi điện.","pages":[163]},{"id":"s1959","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Như vậy, trên xe điện và xe hybrid, các dạng kết cấu khung - vỏ cơ bản vẫn được giữ nguyên; sự khác biệt chủ yếu nằm ở việc bố trí, gá đặt và bảo vệ khối pin cao áp, kéo theo những thay đổi về vị trí dầm gia cường, vùng hấp thụ và vật liệu chế tạo. II. THIẾT BỊ PHỤ TRÊN Ô TÔ 1. Hệ thống điều chỉnh áp suất hơi lốp a) Công dụng Hệ thống điều chỉnh áp suất hơi lốp được sử dụng nhằm thay đổi áp suất khí nén trong lốp ngay khi xe đang vận hành, phù hợp với trạng thái mặt đường mà xe đang chuyển động. Đây là trang bị đặc trưng trên xe quân sự, xe bọc thép và một số xe chuyên dụng cơ động trên đa địa hình.","pages":[163]},{"id":"s1960","kind":"figure","lesson":"12.2.1","title":"Hình 12.29. Van điều khiển cùng với van hạn chế áp suất khí nén 1. Cần điều khiển; 2, 13. Giá đỡ; 3, 5. Đầu liên kết với trục điều khiển; 6. Trục điều khiển; 4. Đai ốc; 7. Nắp dẫn hướng; 8, 19. Thân van điều khiển; 9. Đường dẫn khí nén ra bánh xe và đồng hồ áp suất; 10. Màng cao su; 11. Nắp van hạn chế áp suất; 12. Bu lông điều chỉnh; 14. Đường dẫn khí nén từ van điều khiển ra khí quyển; 15. Đường dẫn khí nén từ bình chứa tới van hạn chế áp suất; 16. Lò xo hạn chế; 17. Đế chặn lò xo; 18.","text":"Hình 12.29. Van điều khiển cùng với van hạn chế áp suất khí nén 1. Cần điều khiển; 2, 13. Giá đỡ; 3, 5. Đầu liên kết với trục điều khiển; 6. Trục điều khiển; 4. Đai ốc; 7. Nắp dẫn hướng; 8, 19. Thân van điều khiển; 9. Đường dẫn khí nén ra bánh xe và đồng hồ áp suất; 10. Màng cao su; 11. Nắp van hạn chế áp suất; 12. Bu lông điều chỉnh; 14. Đường dẫn khí nén từ van điều khiển ra khí quyển; 15. Đường dẫn khí nén từ bình chứa tới van hạn chế áp suất; 16. Lò xo hạn chế; 17. Đế chặn lò xo; 18.","pages":[164],"figure":{"number":"12.29","caption":"Hình 12.29. Van điều khiển cùng với van hạn chế áp suất khí nén 1. Cần điều khiển; 2, 13. Giá đỡ; 3, 5. Đầu liên kết với trục điều khiển; 6. Trục điều khiển; 4. Đai ốc; 7. Nắp dẫn hướng; 8, 19. Thân van điều khiển; 9. Đường dẫn khí nén ra bánh xe và đồng hồ áp suất; 10. Màng cao su; 11. Nắp van hạn chế áp suất; 12. Bu lông điều chỉnh; 14. Đường dẫn khí nén từ van điều khiển ra khí quyển; 15. Đường dẫn khí nén từ bình chứa tới van hạn chế áp suất; 16. Lò xo hạn chế; 17. Đế chặn lò xo; 18."}},{"id":"s1961","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"nén; 20. Van xả khí nén; 21. Đường dẫn khí nén tới gạt mưa; 22. Van điều khiển gạt mưa; 23. Đồng hồ đo áp suất hệ thống phanh; 24. Gạt mưa; 25. Đồng hồ đo áp suất hệ thống bơm lốp; 26. Buồng khí nén điều khiển hộp số phân phối; 27. Ống thoát khí nén; 28. Van điều khiển khí nén tới rơ mooc; 29. Đầu nối khí nén tới rơ mooc; 30. Van giữ hơi; 31. Buồng chứa hơi; 32. Vành bánh xe. Trong sử dụng, hệ thống cho phép điều chỉnh áp suất ngay trong ca-bin, song đòi hỏi bảo dưỡng định kỳ, nhất là các cụm làm kín và ống dẫn khí, đồng thời luôn có cơ chế ưu tiên cho hệ thống phanh để bảo đảm an toàn. c) Cấu tạo và nguyên lý làm việc các bộ phận * Van điều khiển Đặc điểm cấu tạo: Van điều khiển kiểu con trượt được lắp trong cùng cụm với van hạn chế giảm áp (Hình 12.21).","pages":[164]},{"id":"s1962","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Bên trong thân van, các vòng bít cao su chia không gian thành ba khoang: khoang bên trái nối với bình chứa khí nén (15), khoang giữa nối với các lốp xe (9), và khoang bên phải thông với khí trời (14). Cốc dẫn hướng lò xo; 20. Vòng ép kín phớt; 21. Phớt chặn khí nén; 22. Ống chặn; 23. Nắp van hạn chế (11) được ghép với mặt bích van điều khiển qua màng (10). Khi áp suất trong bình chứa nhỏ hơn giá trị 0,53 MPa, lực khí nén tác dụng lên màng","pages":[164]},{"id":"s1963","kind":"figure","lesson":"12.2.1","title":"Hình 12.30. Chế độ bơm khí nén vào lốp 1. Lốp xe; 2. Trục điều khiển; 3. Vòng chặn; 4. Đường dẫn khí nén từ bình chứa tới van hạn chế áp suất; 5. Thân van điều khiển; 6. Đầu van cấp khí nén; 7. Lò xo; 8. Màng cao su; 9. Thân van hạn chế áp suất khí nén; 10. Đường dẫn khí nén ra bánh xe và","text":"Hình 12.30. Chế độ bơm khí nén vào lốp 1. Lốp xe; 2. Trục điều khiển; 3. Vòng chặn; 4. Đường dẫn khí nén từ bình chứa tới van hạn chế áp suất; 5. Thân van điều khiển; 6. Đầu van cấp khí nén; 7. Lò xo; 8. Màng cao su; 9. Thân van hạn chế áp suất khí nén; 10. Đường dẫn khí nén ra bánh xe và","pages":[165],"figure":{"number":"12.30","caption":"Hình 12.30. Chế độ bơm khí nén vào lốp 1. Lốp xe; 2. Trục điều khiển; 3. Vòng chặn; 4. Đường dẫn khí nén từ bình chứa tới van hạn chế áp suất; 5. Thân van điều khiển; 6. Đầu van cấp khí nén; 7. Lò xo; 8. Màng cao su; 9. Thân van hạn chế áp suất khí nén; 10. Đường dẫn khí nén ra bánh xe và"}},{"id":"s1964","kind":"figure","lesson":"12.2.1","title":"Hình 12.31. Chế độ giữ áp suất trong lốp 1. Cần điều khiển; 2. Giá đỡ; 3. Đường dẫn khí nén từ van điều khiển ra khí","text":"Hình 12.31. Chế độ giữ áp suất trong lốp 1. Cần điều khiển; 2. Giá đỡ; 3. Đường dẫn khí nén từ van điều khiển ra khí","pages":[165],"figure":{"number":"12.31","caption":"Hình 12.31. Chế độ giữ áp suất trong lốp 1. Cần điều khiển; 2. Giá đỡ; 3. Đường dẫn khí nén từ van điều khiển ra khí"}},{"id":"s1965","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"(10) không thắng được sức căng của lò xo (16), khiến màng ép chặt và đóng kín đường dẫn khí từ bình chứa tới van điều khiển. Khi áp suất đạt từ 0,53 N/mm² trở lên, màng (10) bị đẩy mở, cho phép khí nén đi vào hệ thống điều chỉnh áp suất lốp. Giá trị áp suất giới hạn có thể thay đổi bằng cách điều chỉnh sức căng lò xo (16) thông qua bu lông (12). Nguyên lý làm việc: Van điều khiển làm việc theo ba chế độ: bơm khí vào lốp, xả khí ra ngoài và giữ áp suất trong lốp.","pages":[165]},{"id":"s1966","kind":"figure","lesson":"12.2.1","title":"Hình 12.32. Chế độ xả khí nén từ lốp ra ngoài 1. Trục điều khiển; 2. Đường dẫn khí nén từ van điều khiển ra khí quyển; 3. Phớt chặn khí nén; 4. Thân van hạn chế áp suất khí nén; 5. Đường dẫn khí nén ra bánh xe và","text":"Hình 12.32. Chế độ xả khí nén từ lốp ra ngoài 1. Trục điều khiển; 2. Đường dẫn khí nén từ van điều khiển ra khí quyển; 3. Phớt chặn khí nén; 4. Thân van hạn chế áp suất khí nén; 5. Đường dẫn khí nén ra bánh xe và","pages":[166],"figure":{"number":"12.32","caption":"Hình 12.32. Chế độ xả khí nén từ lốp ra ngoài 1. Trục điều khiển; 2. Đường dẫn khí nén từ van điều khiển ra khí quyển; 3. Phớt chặn khí nén; 4. Thân van hạn chế áp suất khí nén; 5. Đường dẫn khí nén ra bánh xe và"}},{"id":"s1967","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"quyển; 4. Đầu liên kết trục điều khiển; 5. Trục điều khiển; 6. Nắp dẫn hướng; 7. Vòng chặn; 8. Ống chặn; 9. Phớt chặn khí nén; 10. Đường dẫn khí nén từ bình chứa tới van hạn chế áp suất; 11. Màng cao su; 12. Nắp van hạn chế áp suất; 13. Bu lông điều chỉnh; 14. Đồng hồ đo áp suất; 15. Van giữ hơi; 16. Đầu trục bánh xe; 17. Ống dẫn hơi vào lốp; 18. Lốp xe; 19. Buồng chứa hơi; 20. Vành bánh xe; 21. Săm xe. Chế độ bơm khí vào lốp (Hình 12.30): Khi đưa cần điều khiển về vị trí “bơm”, trục điều khiển (2) dịch chuyển sang trái. Khi đó khoang bên trái và khoang giữa của van thông nhau, đồng thời khoang giữa bị ngăn cách với khí trời. Nếu áp suất trong bình chứa lớn hơn 0,53 MN/m², màng (8) bị đẩy mở, cho phép khí nén đi từ bình chứa tới buồng A, sau đó tới buồng B và theo đường (10) vào lốp xe.","pages":[166]},{"id":"s1968","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Khi áp suất trong bình chứa nhỏ hơn giá trị này, màng (8) đóng, ngăn không cho khí nén cấp đến hệ thống điều chỉnh lốp, khí nén được ưu tiên dự trữ cho hệ thống phanh xe. Chế độ giữ áp suất trong lốp (Hình 12.31): Khi đưa cần điều khiển về vị trí trung gian, các khoang A, B, C bị ngăn cách với nhau. Áp suất khí nén trong lốp được giữ ổn định, không thay đổi. Chỉ khi áp suất bình chứa lớn hơn 0,53 MN/m² thì khoang A mới thông với hệ thống, còn nếu thấp hơn thì van tự động đóng, bảo đảm ưu tiên cho hệ thống phanh xe. Chế độ xả khí ra ngoài (Hình 12.32): Khi đưa cần điều khiển về vị trí “xả”, trục điều khiển (1) dịch chuyển sang phải. Khi đó khoang giữa B nối thông với khí trời C, còn khoang trái A bị ngăn cách. Khí nén trong lốp theo đường (5) tới buồng B, sau đó tới buồng C và thoát ra ngoài qua đường (2), làm giảm áp suất lốp.","pages":[166]},{"id":"s1969","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Nếu áp suất bình chứa nhỏ hơn 0,53 MN/m², van vẫn duy trì đóng với khoang A để không ảnh hưởng đến nguồn khí dành cho quá trình phanh. Người lái có thể kiểm tra áp suất trong lốp qua đồng hồ báo áp suất. Khi cần điều chỉnh áp suất, đưa cần điều khiển về vị trí trung gian, đóng các van giữ hơi tại các bánh xe, siết hoặc nới đai ốc điều chỉnh trên van hạn chế áp suất để duy trì áp suất ổn định trong lốp. Khi cần thay đổi áp suất hơi lốp trong quá trình chuyển động của ô tô, các van giữ hơi phải được mở trước khi xe chuyển động. * Bộ phận dẫn khí nén tới bánh xe","pages":[166]},{"id":"s1970","kind":"figure","lesson":"12.2.1","title":"Hình 12.33. Bộ phận dẫn khí nén vào bánh xe 1. Bán trục; 2. Đường ống hơi; 3. Giá đỡ; 4. Vành bánh xe; 5. Lốp xe; 6. Săm xe; 7. Đường dẫn hơi từ van giữ hơi vào bánh xe; 8. Van giữ hơi; 9. Phớt làm kín khí nén;","text":"Hình 12.33. Bộ phận dẫn khí nén vào bánh xe 1. Bán trục; 2. Đường ống hơi; 3. Giá đỡ; 4. Vành bánh xe; 5. Lốp xe; 6. Săm xe; 7. Đường dẫn hơi từ van giữ hơi vào bánh xe; 8. Van giữ hơi; 9. Phớt làm kín khí nén;","pages":[167],"figure":{"number":"12.33","caption":"Hình 12.33. Bộ phận dẫn khí nén vào bánh xe 1. Bán trục; 2. Đường ống hơi; 3. Giá đỡ; 4. Vành bánh xe; 5. Lốp xe; 6. Săm xe; 7. Đường dẫn hơi từ van giữ hơi vào bánh xe; 8. Van giữ hơi; 9. Phớt làm kín khí nén;"}},{"id":"s1971","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Đặc điểm cấu tạo: Bộ phận dẫn khí nén tới bánh xe có nhiệm vụ dẫn khí nén từ phần không quay (trục, dầm cầu) sang phần quay (bánh xe) để đảm bảo lốp luôn được cấp khí khi xe chuyển động. Đây là chi tiết quan trọng vì vừa phải bảo đảm độ kín khí, vừa chịu được điều kiện quay liên tục của bánh xe. Cấu tạo của bộ phận dẫn khí nén tới bánh xe thể hiện trên Hình 12.33, gồm các chi tiết chính sau: 10. Lò xo ép chặt phớt; 11. Vòng hãm; 12. Buồng hơi. Bên trong bán trục (1) được khoan lỗ dọc trục và lỗ hướng kính, nối thông với đường ống (2) dẫn khí đến buồng chứa hơi (12). Đầu ngoài bán trục được lắp chặt với mặt bích trên, có gắn van giữ hơi (8) và đầu nối để dẫn khí nén ra ống (7), đưa khí nén tới săm lốp. Buồng chứa hơi (12) có dạng hình trụ, lắp cố định trên dầm cầu, liên kết bằng mối ghép ren.","pages":[167]},{"id":"s1972","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Buồng chứa hơi có lỗ hướng kính nối với đầu ống dẫn khí từ van điều khiển. Hai đầu buồng chứa được làm kín bằng các phớt cao su, cố định bằng vòng giữ, đảm bảo không rò rỉ khí ra ngoài. Không gian bên trong buồng chứa và hai phớt tạo thành một khoang kín, cho phép dẫn khí từ trục (không quay) sang bánh xe (quay) một cách liên tục và không bị rò rỉ. Nguyên lý làm việc: Khi hệ thống cấp khí hoạt động, khí nén từ bình chứa đi qua van điều khiển và theo đường ống hơi (2) vào buồng chứa hơi (12). Tại đây, nhờ sự làm kín của các phớt cao su, khí được dẫn qua van giữ hơi và đường ống (7) đến săm lốp. Nhờ kết cấu này, dù bánh xe quay liên tục, khí nén vẫn được truyền từ phần không quay sang phần quay mà không bị rò rỉ.","pages":[167]},{"id":"s1973","kind":"figure","lesson":"12.2.1","title":"Hình 12.34. Van giữ hơi 1. Vòng làm kín; 2. Đệm làm kín; 3. Đai ốc; 4. Thân van; 5. Trục van","text":"Hình 12.34. Van giữ hơi 1. Vòng làm kín; 2. Đệm làm kín; 3. Đai ốc; 4. Thân van; 5. Trục van","pages":[168],"figure":{"number":"12.34","caption":"Hình 12.34. Van giữ hơi 1. Vòng làm kín; 2. Đệm làm kín; 3. Đai ốc; 4. Thân van; 5. Trục van"}},{"id":"s1974","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Đặc điểm cấu tạo: Van giữ hơi (Hình 12.34) được lắp đặt trên đường dẫn khí nén tới bánh xe, có nhiệm vụ ngăn không cho khí nén thoát ra ngoài khi đường ống hoặc phớt làm kín bị hở. Nhờ đó, áp suất khí trong lốp vẫn được duy trì ổn định, bảo đảm xe tiếp tục cơ động trong tình huống xảy ra hỏng hóc cục bộ trên hệ thống dẫn khí. a) Trạng thái khi xả khí nén; b) Trạng thái khi giữ khí nén Van giữ hơi gồm các bộ phận chính: Trục van (5) với dạng hình trụ, một đầu chế tạo chỏm cầu để bít kín cửa dẫn khí khi van đóng. Đai ốc (3) được lắp với thân van bằng mối ghép ren, vừa có nhiệm vụ cố định trục van, vừa cho phép tháo lắp bảo dưỡng. Đệm làm kín (2) bố trí giữa trục van và thân van, đảm bảo độ kín khít khi van làm việc. Vòng làm kín (1) đặt ở đầu nối đường khí, ngăn rò rỉ khi khí nén đi qua.","pages":[168]},{"id":"s1975","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Thân van (4) có dạng khối, bên trong gia công lỗ dẫn khí và lỗ lắp trục van. Nguyên lý làm việc: Khi hệ thống hoạt động bình thường, van giữ hơi ở trạng thái mở (Hình 12.34a), khí nén từ đường ống đi qua thân van tới bánh xe. Lúc này trục van (5) được giữ ở trạng thái mở, không cản trở dòng khí nén. Khi cần điều chỉnh áp suất khí nén trong hệ thống hoặc ngắt dòng khí nén vào lốp xe (Hình 12.34b), sử dụng dụng cụ siết chặt trục van (5). Đầu chỏm cầu của trục van ép sát vào bệ chặn trong thân van, đóng kín cửa van, ngăn không cho khí trong lốp thoát ra ngoài. 2. Hệ thống tời và nâng hạ thùng xe a) Hệ thống tời Tời có thể được lắp đặt ở phía trước hoặc phía sau của xe, trong đó cách bố trí phổ biến nhất là đặt trống tời ở trước đầu xe.","pages":[168]},{"id":"s1976","kind":"pdf","lesson":"12.2.1","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống điều chỉnh áp suất hơi lốp","text":"Công dụng chính của tời bao gồm: - Giúp ô tô tự thoát khỏi các địa hình phức tạp mà bánh xe không thể vượt qua bằng lực kéo thông thường. - Kéo, hỗ trợ các xe khác khi bị sa lầy hoặc gặp chướng ngại vượt quá khả năng tự khắc phục. - Kéo hoặc nâng hàng hóa lên cao khi có điểm tựa chắc chắn. Trên ô tô, thường sử dụng hai loại tời: tời cơ khí và tời điện. Tời cơ khí lấy năng lượng từ động cơ ô tô thông qua hệ thống truyền lực và được điều khiển bằng các cần kéo. Tời điện sử dụng động cơ điện một chiều, lấy nguồn từ bình ắc quy và điều khiển bằng công tắc điện.","pages":[168]},{"id":"s1977","kind":"figure","lesson":"12.2.2","title":"Hình 12.35. Sơ đồ bố trí chung hệ thống tời 1, 6, 13. Vú mỡ; 2. Vòng chặn khớp gài; 3. Khớp gài trống tời; 4. Cần điều khiển trống tời; 5. Thanh ngang trước; 7. Thanh bảo vệ; 8. Trục dẫn hướng; 9. Giá trục dẫn","text":"Hình 12.35. Sơ đồ bố trí chung hệ thống tời 1, 6, 13. Vú mỡ; 2. Vòng chặn khớp gài; 3. Khớp gài trống tời; 4. Cần điều khiển trống tời; 5. Thanh ngang trước; 7. Thanh bảo vệ; 8. Trục dẫn hướng; 9. Giá trục dẫn","pages":[169],"figure":{"number":"12.35","caption":"Hình 12.35. Sơ đồ bố trí chung hệ thống tời 1, 6, 13. Vú mỡ; 2. Vòng chặn khớp gài; 3. Khớp gài trống tời; 4. Cần điều khiển trống tời; 5. Thanh ngang trước; 7. Thanh bảo vệ; 8. Trục dẫn hướng; 9. Giá trục dẫn"}},{"id":"s1978","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"* Tời cơ khí trên xe ZIL-131 - Sơ đồ bố trí và nguyên lý làm việc chung: Hệ thống tời (Hình 12.35) gồm các bộ phận chính như: hộp trích công suất, hệ thống truyền động các-đăng dẫn động tời, hộp giảm tốc (sử dụng bộ truyền trục vít - bánh vít), phanh tang tời, tang tời cùng dây cáp, và khớp gài tang tời. hướng; 10. Dây cáp; 11. Hộp giảm tốc; 12. Trống tời; 14. Đai ốc; 15. Trục các-đăng trước; 16. Giá đỡ giữa; 17. Trục các-đăng sau; 18. Khóa cần điều khiển; 19. Cần điều khiển hộp trích công suất; 20. Hộp trích công suất; 21. Phanh trống tời; 22. Chốt; 23. Thanh ngang sau; 24. Bu lông; 25. Giá trục trống tời; 26. Ổ đỡ trục trống tời; 27. Nắp. Trong hệ thống tời ô tô ZIL-131, hộp trích công suất (20) nhận năng lượng từ hộp số chính, truyền qua hộp giảm tốc (11) và tới trống tời (12) đặt ở phía trước xe.","pages":[169]},{"id":"s1979","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Trống tời được lắp trên trục và có thể quay trơn, việc đóng - mở truyền động được điều khiển bằng khớp gài (3) trượt dọc theo trục trống tời. Khi tiến hành cuộn (nhả) tời bằng nguồn động lực, hộp số chính được gài ở số trung gian, hộp trích công suất ở vị trí làm việc, còn khớp gài (3) ở vị trí đóng, nhờ đó trống tời cố định với trục. Mô men xoắn từ hộp số chính truyền qua các trục các-đăng và hộp giảm tốc đến trống tời, làm dây cáp (10) được cuộn chặt lên trống. Trong trường hợp nhả tời bằng tay, khớp gài (3) được chuyển về vị trí mở, người sử dụng kéo dây cáp (10) ra ngoài. Lúc này, phanh trống tời (21) giữ vai trò quan trọng, đảm bảo dây cáp được nhả đều, tránh sự rối hoặc tuột đột ngột gây nguy hiểm. - Các bộ phận của hệ thống tời: + Hộp trích công suất (Hình 12.36): Hộp trích công suất bao gồm vỏ hộp (9) được lắp chặt với vỏ hộp số chính","pages":[169]},{"id":"s1980","kind":"figure","lesson":"12.2.2","title":"Hình 12.36. Hộp trích công suất 1. Càng gạt; 2. Cơ cấu định vị; 3, 5, 7, 12, 14, 19, 25, 26, 38. Bánh răng; 4, 29. Trục bị động; 6, 8, 17, 35. Trục trung gian; 9, 20, 21. Vỏ hộp trích công suất; 10. Trục trích công suất tại hộp số chính; 11. Vỏ hộp số chính; 13, 32. Chốt định vị; 15, 30. Mặt","text":"Hình 12.36. Hộp trích công suất 1. Càng gạt; 2. Cơ cấu định vị; 3, 5, 7, 12, 14, 19, 25, 26, 38. Bánh răng; 4, 29. Trục bị động; 6, 8, 17, 35. Trục trung gian; 9, 20, 21. Vỏ hộp trích công suất; 10. Trục trích công suất tại hộp số chính; 11. Vỏ hộp số chính; 13, 32. Chốt định vị; 15, 30. Mặt","pages":[170],"figure":{"number":"12.36","caption":"Hình 12.36. Hộp trích công suất 1. Càng gạt; 2. Cơ cấu định vị; 3, 5, 7, 12, 14, 19, 25, 26, 38. Bánh răng; 4, 29. Trục bị động; 6, 8, 17, 35. Trục trung gian; 9, 20, 21. Vỏ hộp trích công suất; 10. Trục trích công suất tại hộp số chính; 11. Vỏ hộp số chính; 13, 32. Chốt định vị; 15, 30. Mặt"}},{"id":"s1981","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"(11); các trục (6), (8) lắp chặt trên vỏ và trục bị động (4) lắp quay trơn trên vỏ nhờ ổ bi. Trên trục (8) lắp bánh răng (14) quay trơn qua ổ lăn kim (18), trong đó bánh răng (14) ăn khớp với bánh răng số lùi (12) của hộp số chính. Trên trục (6) có bánh răng (5) lắp quay trơn qua ổ lăn kim, còn trên trục (4) lắp bánh răng di trượt (3) bằng then hoa. Bánh răng (3) có thể ăn khớp với bánh răng (5) hoặc bánh răng (14), nhờ đó thay đổi được chế độ làm việc của tời. Đầu trục (4) được nối với hộp giảm tốc bằng mặt bích (15) để truyền công suất tới hộp giảm tốc. Phần điều khiển hộp trích công suất gồm có: cần điều khiển (33), càng gạt (1) di chuyển trên trục trượt và cơ cấu định vị bằng bi - lò xo (2).","pages":[170]},{"id":"s1982","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Trong quá trình làm việc, cần điều khiển có ba vị trí: trung gian (bánh răng 3 không ăn khớp), cuộn tời (bánh răng 3 ăn khớp với bánh răng 5), và nhả tời (bánh răng 3 ăn khớp với bánh răng 14). bích liên kết các-đăng; 16, 28. Nắp ổ đỡ; 18, 36. Ổ lăn kim; 22, 27. Ổ bi; 31. Chốt; 33. Cần điều khiển; 34. Khớp tựa; 37. Nắp châm dầu. Nguyên lý hoạt động: Khi cần điều khiển ở vị trí trung gian, bánh răng trượt (3) không ăn khớp với bánh răng nào, do đó công suất từ hộp số chính không truyền ra ngoài, tời ở trạng thái ngắt. Khi cần điều khiển được gạt sang vị trí cuộn tời, bánh răng trượt (3) ăn khớp với bánh răng (5) trên trục (6). Lúc này, công suất từ hộp số chính truyền qua cặp bánh răng số lùi đến bánh răng (7) trên trục (8), sau đó tới bánh răng (5) trên trục (6) và qua bánh răng trượt (3) trên trục (4) tới hộp giảm tốc, làm trống tời quay và cuốn dây cáp.","pages":[170]},{"id":"s1983","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Ngược lại, khi cần điều khiển ở vị trí nhả tời, bánh răng trượt (3) ăn khớp trực tiếp với bánh răng (14). Công suất từ hộp số chính khi đó truyền thẳng từ bánh răng (7) sang bánh răng (3), qua trục (4) ra hộp giảm tốc, khiến trống tời của hệ thống quay theo chiều nhả cáp.","pages":[170]},{"id":"s1984","kind":"figure","lesson":"12.2.2","title":"Hình 12.37. Hộp giảm tốc và trống tời 1, 3, 4, 43. Giá đỡ; 2, 11, 35. Dây cáp; 5. Ròng rọc; 6. Móc cáp; 7. Ống trục; 8. Trục đỡ cáp; 9, 32, 36, 39, 42. Bạc chặn; 10, 26, 40. Vú mỡ; 12, 24. Mặt bích làm kín; 13. Ổ bi côn; 14, 21. Trục vít; 15, 16. Vỏ hộp giảm tốc; 17, 20. Trống phanh; 18. Đai ốc điều chỉnh dải phanh; 22, 23. Dải phanh cơ cấu tự hãm; 25. Tấm chặn; 27, 30, 41. Ổ lăn","text":"Hình 12.37. Hộp giảm tốc và trống tời 1, 3, 4, 43. Giá đỡ; 2, 11, 35. Dây cáp; 5. Ròng rọc; 6. Móc cáp; 7. Ống trục; 8. Trục đỡ cáp; 9, 32, 36, 39, 42. Bạc chặn; 10, 26, 40. Vú mỡ; 12, 24. Mặt bích làm kín; 13. Ổ bi côn; 14, 21. Trục vít; 15, 16. Vỏ hộp giảm tốc; 17, 20. Trống phanh; 18. Đai ốc điều chỉnh dải phanh; 22, 23. Dải phanh cơ cấu tự hãm; 25. Tấm chặn; 27, 30, 41. Ổ lăn","pages":[171],"figure":{"number":"12.37","caption":"Hình 12.37. Hộp giảm tốc và trống tời 1, 3, 4, 43. Giá đỡ; 2, 11, 35. Dây cáp; 5. Ròng rọc; 6. Móc cáp; 7. Ống trục; 8. Trục đỡ cáp; 9, 32, 36, 39, 42. Bạc chặn; 10, 26, 40. Vú mỡ; 12, 24. Mặt bích làm kín; 13. Ổ bi côn; 14, 21. Trục vít; 15, 16. Vỏ hộp giảm tốc; 17, 20. Trống phanh; 18. Đai ốc điều chỉnh dải phanh; 22, 23. Dải phanh cơ cấu tự hãm; 25. Tấm chặn; 27, 30, 41. Ổ lăn"}},{"id":"s1985","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"+ Hộp giảm tốc và trống tời (Hình 12.37): Hộp giảm tốc có nhiệm vụ thay đổi mặt phẳng quay của trục trống tời và tăng mô men xoắn truyền đến trống tời. Trong hộp giảm tốc, trục vít (14) nhận công suất từ hộp trích công suất, truyền qua bánh vít (29) lắp chặt với trục trống tời (33). Trục vít có dạng lõm, được đỡ quay bằng hai ổ lăn côn; đầu trục vít liên kết với bộ truyền động các-đăng dẫn động tời và đồng thời cố định tang phanh của phanh tời. Bên ngoài tang phanh có lỗ lắp chốt an toàn, chốt này sẽ tự cắt khi lực truyền vượt quá giới hạn, nhờ đó hệ thống được bảo vệ và tránh hiện tượng nhả cáp đột ngột. kim; 28. Moay-ơ bánh vít; 29. Bánh vít; 33. Trục trống tời; 34. Trống tời; 37. Móc giữ Bánh vít được cấu tạo gồm moay-ơ bằng thép và vành bánh vít bằng đồng thanh, lắp ghép với nhau bằng hai then bán nguyệt để truyền mô men.","pages":[171]},{"id":"s1986","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Trục của bánh vít nối trực tiếp với trục trống tời (33), đảm bảo truyền động từ hộp giảm tốc đến trống tời. Toàn bộ cụm truyền động được đặt trong vỏ hộp giảm tốc. Ngoài ra, trên trục vít (14) còn bố trí cơ cấu tự hãm bằng phanh dải, giúp giữ chặt trống tời khi nâng vật lên cao mà nguồn động lực bị ngắt đột ngột, đảm bảo an toàn cho hệ thống và người vận hành. Cơ cấu tự hãm gồm: trống phanh (17) lắp chặt trên trục vít (14), dải phanh (23) có một đầu cố định vào giá đỡ, đầu còn lại được kéo căng bằng lò xo và đai ốc điều chỉnh (18).","pages":[171]},{"id":"s1987","kind":"figure","lesson":"12.2.2","title":"Hình 12.38. Dẫn động tời 1, 9, 10, 16, 20. Mặt bích; 2, 4. Vú mỡ; 3. Khớp chữ thập; 5. Đai ốc xả mỡ; 6. Rãnh dọc trục chữ thập; 7. Ổ lăn kim; 8. Đầu chụp ổ lăn kim; 11. Ổ bi đỡ; 12, 18. Giá đỡ;","text":"Hình 12.38. Dẫn động tời 1, 9, 10, 16, 20. Mặt bích; 2, 4. Vú mỡ; 3. Khớp chữ thập; 5. Đai ốc xả mỡ; 6. Rãnh dọc trục chữ thập; 7. Ổ lăn kim; 8. Đầu chụp ổ lăn kim; 11. Ổ bi đỡ; 12, 18. Giá đỡ;","pages":[172],"figure":{"number":"12.38","caption":"Hình 12.38. Dẫn động tời 1, 9, 10, 16, 20. Mặt bích; 2, 4. Vú mỡ; 3. Khớp chữ thập; 5. Đai ốc xả mỡ; 6. Rãnh dọc trục chữ thập; 7. Ổ lăn kim; 8. Đầu chụp ổ lăn kim; 11. Ổ bi đỡ; 12, 18. Giá đỡ;"}},{"id":"s1988","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Nguyên lý hoạt động: Khi cuộn tời, trục vít quay theo chiều kim đồng hồ, mô men ma sát giữa trống phanh và dải phanh có xu hướng đẩy dải phanh tách ra khỏi trống phanh, tạo khe hở giúp trục vít quay dễ dàng. Khi nhả tời, trục vít quay ngược chiều kim đồng hồ, lúc này mô men ma sát giữa trống phanh và dải phanh lại có xu hướng ép chặt dải phanh lên trống phanh. Nhờ đó, tốc độ quay của trống phanh bị hạn chế, mô men ma sát tăng lên, làm giảm tốc độ và giữ cho quá trình nhả tời an toàn, không bị tuột đột ngột. Trong trường hợp đang nâng vật lên cao mà động lực bị cắt (ví dụ động cơ chết máy hoặc chốt an toàn của dẫn động tời bị đứt), dưới tác dụng của trọng lượng vật tải, trục vít có xu hướng quay nhanh theo chiều nhả tời.","pages":[172]},{"id":"s1989","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Khi đó, mô men ma sát lớn giữa dải phanh và trống phanh kết hợp với khả năng tự hãm của bộ truyền trục vít - bánh vít sẽ giữ chặt trống tời, đảm bảo vật tải không bị rơi và an toàn được duy trì. + Dẫn động tời (Hình 12.38): Dẫn động tời trong hệ thống tời ô tô ZIL-131 (Hình 12.38) gồm trục các-đăng trước (14) và trục các-đăng sau (19), làm nhiệm vụ truyền mô men xoắn từ hộp trích công suất đến hộp giảm tốc. Tại trục các-đăng trước, nạng các-đăng nối với trục các-đăng (14) thông qua chốt an toàn (17). Khi hệ thống tời bị quá tải, chốt an toàn sẽ tự cắt để ngắt truyền động, bảo vệ an toàn cho toàn bộ hệ thống. 13. Vòng chụp; 14. Trục các-đăng trước; 15. Vòng làm kín; 17. Chốt an toàn; 19. Trục Ngoài ra, ở một số loại ô tô (như KrAZ, Ural), hệ thống tời còn được trang bị cơ cấu xếp dây nhằm tránh hiện tượng dây cáp bị rối trên trống tời (Hình 12.39).","pages":[172]},{"id":"s1990","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Đặc điểm cấu tạo của cơ cấu xếp dây tời: Cơ cấu tời có bộ xếp dây (Hình 12.39) gồm nhiều cụm chi tiết chính. Tang tời (6) được lắp trên trục tang (7) và quay nhờ bộ truyền trục vít – bánh vít, trong đó trục vít (19) ăn khớp với bánh vít (20) gắn trên trục tang. Bộ truyền này đặt trong vỏ hộp giảm tốc (18) và được đỡ bởi các nắp ổ bi (16, 21) cùng các ổ bi (2, 10, 13). Hệ","pages":[172]},{"id":"s1991","kind":"figure","lesson":"12.2.2","title":"Hình 12.39. Cơ cấu xếp dây tời 1. Vòng đệm chặn; 2. Ổ bi trục tang tời; 3. Ống lót; 4. Mặt bích đỡ tang tời; 5. Tấm chặn cáp trên; 6. Tang tời; 7. Trục tang tời; 8. Thanh ngang treo tời; 9. Phớt chắn dầu; 10. Nắp ổ bi; 11. Giá kẹp dây cáp; 12. Khớp trượt đóng ngắt tang tời; 13. Moay-ơ bánh vít trục vít; 14. Nắp hộp giảm tốc; 15. Tấm đệm điều chỉnh; 16. Nắp trước ổ bi; 17. Nút châm dầu; 18. Vỏ hộp giảm tốc; 19. Trục vít hộp giảm tốc; 20. Bánh vít trục vít; 21. Nắp sau ổ bi; 22. Tang trống tời; 23. Dải phanh; 24. Con lăn dẫn hướng trên; 25. Giá đỡ phải của trục vít dẫn động; 26. Đai ốc điều chỉnh băng phanh; 27. Đầu băng phanh; 28. Đầu đòn gạt đóng ngắt tang tời; 29. Giá đỡ đòn điều khiển; 30. Thanh truyền động đóng ngắt; 31. Khớp nối cố định; 32. Đòn gạt đóng ngắt tang tời; 33. Thanh trượt càng khớp; 34. Càng khớp đóng ngắt tang tời; 35. Trục vít dẫn động; 36. Chốt con lăn dẫn hướng; 37. Nắp đỡ chạc; 38. Con lăn","text":"Hình 12.39. Cơ cấu xếp dây tời 1. Vòng đệm chặn; 2. Ổ bi trục tang tời; 3. Ống lót; 4. Mặt bích đỡ tang tời; 5. Tấm chặn cáp trên; 6. Tang tời; 7. Trục tang tời; 8. Thanh ngang treo tời; 9. Phớt chắn dầu; 10. Nắp ổ bi; 11. Giá kẹp dây cáp; 12. Khớp trượt đóng ngắt tang tời; 13. Moay-ơ bánh vít trục vít; 14. Nắp hộp giảm tốc; 15. Tấm đệm điều chỉnh; 16. Nắp trước ổ bi; 17. Nút châm dầu; 18. Vỏ hộp giảm tốc; 19. Trục vít hộp giảm tốc; 20. Bánh vít trục vít; 21. Nắp sau ổ bi; 22. Tang trống tời; 23. Dải phanh; 24. Con lăn dẫn hướng trên; 25. Giá đỡ phải của trục vít dẫn động; 26. Đai ốc điều chỉnh băng phanh; 27. Đầu băng phanh; 28. Đầu đòn gạt đóng ngắt tang tời; 29. Giá đỡ đòn điều khiển; 30. Thanh truyền động đóng ngắt; 31. Khớp nối cố định; 32. Đòn gạt đóng ngắt tang tời; 33. Thanh trượt càng khớp; 34. Càng khớp đóng ngắt tang tời; 35. Trục vít dẫn động; 36. Chốt con lăn dẫn hướng; 37. Nắp đỡ chạc; 38. Con lăn","pages":[173],"figure":{"number":"12.39","caption":"Hình 12.39. Cơ cấu xếp dây tời 1. Vòng đệm chặn; 2. Ổ bi trục tang tời; 3. Ống lót; 4. Mặt bích đỡ tang tời; 5. Tấm chặn cáp trên; 6. Tang tời; 7. Trục tang tời; 8. Thanh ngang treo tời; 9. Phớt chắn dầu; 10. Nắp ổ bi; 11. Giá kẹp dây cáp; 12. Khớp trượt đóng ngắt tang tời; 13. Moay-ơ bánh vít trục vít; 14. Nắp hộp giảm tốc; 15. Tấm đệm điều chỉnh; 16. Nắp trước ổ bi; 17. Nút châm dầu; 18. Vỏ hộp giảm tốc; 19. Trục vít hộp giảm tốc; 20. Bánh vít trục vít; 21. Nắp sau ổ bi; 22. Tang trống tời; 23. Dải phanh; 24. Con lăn dẫn hướng trên; 25. Giá đỡ phải của trục vít dẫn động; 26. Đai ốc điều chỉnh băng phanh; 27. Đầu băng phanh; 28. Đầu đòn gạt đóng ngắt tang tời; 29. Giá đỡ đòn điều khiển; 30. Thanh truyền động đóng ngắt; 31. Khớp nối cố định; 32. Đòn gạt đóng ngắt tang tời; 33. Thanh trượt càng khớp; 34. Càng khớp đóng ngắt tang tời; 35. Trục vít dẫn động; 36. Chốt con lăn dẫn hướng; 37. Nắp đỡ chạc; 38. Con lăn"}},{"id":"s1992","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"thống phanh gồm tang phanh (22), dải phanh (23), đai ốc điều chỉnh (26), đầu băng phanh (27) và cơ cấu điều khiển phanh giúp hãm tang khi cần dừng hoặc giữ tải. Để bảo vệ khi quá tải, trên cơ cấu còn có chốt an toàn (12) có khả năng cắt đứt truyền động khi lực vượt giới hạn. Cơ cấu đóng ngắt tang tời gồm khớp trượt (12), càng gạt (34), đòn điều khiển (32) và thanh truyền (30), cho phép chuyển đổi giữa chế độ cuộn, nhả hoặc ngắt. Bộ xếp dây được dẫn động từ tang tời qua bộ truyền xích gồm đĩa xích chủ động (49), đĩa xích bị dẫn (44) và xích con lăn (46). Xích này quay trục vít dẫn động (35), trên đó có hai đường ren ngược chiều. Con chạy (2) di chuyển qua lại trên trục vít nhờ chốt định vị (36), nhờ vậy dây cáp (3) được cuộn hoặc nhả đều trên tang. Dây cáp đi qua các con lăn dẫn hướng (24, 38, 43) và puli để giảm ma sát, sau đó cố định vào móc tời.","pages":[173]},{"id":"s1993","kind":"figure","lesson":"12.2.2","title":"Hình 12.40. Hệ thống tời điện trên Toyota Land Cruiser 1. Cản trước; 2. Cáp tời; 3. Móc nối; 4. Hộp giảm tốc; 5. Tang trống tời; 6. Động","text":"Hình 12.40. Hệ thống tời điện trên Toyota Land Cruiser 1. Cản trước; 2. Cáp tời; 3. Móc nối; 4. Hộp giảm tốc; 5. Tang trống tời; 6. Động","pages":[174],"figure":{"number":"12.40","caption":"Hình 12.40. Hệ thống tời điện trên Toyota Land Cruiser 1. Cản trước; 2. Cáp tời; 3. Móc nối; 4. Hộp giảm tốc; 5. Tang trống tời; 6. Động"}},{"id":"s1994","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"ngang; 39. Ống lót; 40. Giá đỡ con lăn ngang; 41. Đai ốc trục vít dẫn động; 42. Vỏ giữ con lăn dẫn hướng; 43. Con lăn dẫn hướng; 44. Đĩa xích bị dẫn; 45. Giá đỡ trái của trục vít dẫn động; 46. Xích con lăn ống lót; 47. Tấm đệm điều chỉnh căng xích; 48. Giá đỡ trục tang tời; 49. Đĩa xích chủ động. Nguyên lý làm việc của cơ cấu xếp dây tời (Hình 12.39) Truyền công suất từ hộp số ra tời: Công suất từ hộp trích công suất được truyền qua trục các-đăng đến hộp giảm tốc trục vít – bánh vít (19, 20). Trục vít (19) quay, ăn khớp với bánh vít (20). Bánh vít lắp chặt trên trục tang tời (7), làm tang tời (6) quay. Cụm này có khả năng tự hãm nhờ kết cấu phanh dải, đảm bảo khi ngắt động lực, tang tời không tự do quay ngược. Cuộn và nhả dây cáp: Khi cuộn tời, trục vít truyền mô men qua bánh vít, kéo tang tời (6) quay và cuốn dây cáp vào tang.","pages":[174]},{"id":"s1995","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Khi nhả tời, cơ cấu điều khiển (28, 32, 34) tác động để khớp trượt (12) thay đổi trạng thái, cho phép tang tời quay theo chiều ngược, thả dây cáp ra. Trong quá trình làm việc, phanh tang tời (22, 23) có nhiệm vụ giữ hoặc hãm tang khi cần dừng hoặc khi tải vượt quá giới hạn an toàn. Nếu lực quá tải, chốt an toàn tại dẫn động tời sẽ cắt để ngắt động lực, bảo vệ toàn bộ cơ cấu.","pages":[174]},{"id":"s1996","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Do chiều quay của tang trống ngược lại nên lực ma sát có chiều gây ra khả năng tự xiết dải phanh vào tang trống để ngăn cản sự quay của tang trống * Tời điện trên xe Toyota Land Cruiser (Hình 12.40) Đặc điểm cấu tạo: Hệ thống tời điện trên ô tô (Hình 12.40) gồm các bộ phận chính sau: Động cơ điện một chiều (6) sử dụng nguồn điện từ ắc quy 12V của xe, có khả năng đảo chiều để thực hiện cả hai chức năng cuộn và nhả dây, đồng thời được điều khiển bằng công tắc hoặc bộ điều khiển từ xa trong buồng lái. Tang trống tời (5) cùng với dây cáp (2) là bộ phận trực tiếp cuộn và chứa dây, dây cáp có thể là loại thép hoặc sợi tổng hợp, thường có chiều dài 25 ÷ 40 m và đường kính trong khoảng 8 đến 12 mm.","pages":[174]},{"id":"s1997","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Hộp giảm tốc tời (4), có nhiệm vụ tăng mô men xoắn và giảm tốc độ quay của trống, bên trong được bố trí khớp an toàn với hai vị trí làm việc là cuộn và nhả tời. cơ điện; 7. Dẫn hướng tời","pages":[174]},{"id":"s1998","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Khi cuộn tời, động cơ truyền công suất qua hộp giảm tốc hành tinh làm tang trống quay để cuộn dây cáp vào tang. Khi nhả tời, mở ly hợp để tang trống có thể quay tự do cho phép kéo nhả dây tời nhanh bằng tay. Đầu ngoài dây cáp gắn móc (3) bằng thép cường độ cao có khóa an toàn để móc chặt vào điểm kéo. Cụm điều khiển đặt trong buồng lái giúp người lái thao tác cuộn hoặc nhả dây tời phù hợp. Phanh hãm tự động tích hợp trong hộp giảm tốc giữ tải khi dừng thao tác; rơ le và giới hạn dòng bảo vệ mô tơ khi quá tải hoặc quá nhiệt. Bộ dẫn hướng tời giúp cáp vào và ra thẳng, giảm mài mòn. Nguyên lý làm việc: Chế độ cuộn dây: Khi người điều khiển bật công tắc hoặc remote ở vị trí cuộn, dòng điện từ ắc quy được cấp cho động cơ điện một chiều (6) quay theo chiều cuộn.","pages":[175]},{"id":"s1999","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Mô men xoắn từ động cơ truyền qua hộp giảm tốc (4), sau đó đến tang trống (5), làm tang quay chậm nhưng với mô men lớn để kéo dây cáp (2). Trong quá trình cuộn, dây đi qua bộ phận dẫn hướng (7) và được quấn đều lên tang, còn móc nối (3) được giữ chặt vào điểm kéo. Chế độ nhả dây: Người điều khiển có thể chọn nhả bằng động cơ hoặc bằng tay. Khi nhả bằng động cơ, công tắc được bật về vị trí nhả, động cơ (6) quay ngược chiều, truyền động qua hộp giảm tốc (4) để tang trống (5) quay theo chiều nhả cáp, dây cáp (2) được nhả ra ngoài. Khi cần nhả nhanh bằng tay, gạt khớp an toàn trong hộp giảm tốc, lúc này tang trống quay tự do và dây cáp được kéo ra ngoài dễ dàng. Chế độ giữ tải: Khi ngắt công tắc điều khiển, dòng điện vào động cơ bị cắt, cơ cấu phanh tự hãm kết hợp với đặc tính tự hãm của hộp giảm tốc trục vít – bánh vít sẽ giữ tang trống đứng yên.","pages":[175]},{"id":"s2000","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Nhờ đó, tải trọng treo trên móc nối (3) không bị tuột cáp và luôn được giữ an toàn. b) Hệ thống nâng hạ thùng xe Đặc điểm cấu tạo: Sơ đồ cấu tạo hệ thống nâng hạ thùng xe KamAZ 65115 thể hiện trên Hình 12.41, gồm các bộ phận chính sau: thùng dầu thủy lực (1), hộp trích công suất từ hộp số chính (2), van điện – khí nén (3), van điều khiển thủy lực (4), xi-lanh thủy lực nhiều tầng (5) và van giới hạn nâng sàn (6). Hộp trích công suất (2) được sử dụng để truyền mô men xoắn từ hộp số chính tới bơm dầu thủy lực. Khi cần nâng thùng, hộp trích công suất được điều khiển bằng cần trong ca-bin, truyền động tới bơm dầu để hút dầu từ thùng chứa (1) và đẩy vào hệ thống. Bình dầu thủy lực (1) được chế tạo bằng phương pháp dập và hàn, trên bình có cổ đổ dầu với lưới lọc, đồng hồ đo mức dầu và lỗ thông hơi.","pages":[175]},{"id":"s2001","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Ngoài ra, một lưới lọc còn được lắp trên đường xả của bình để loại bỏ cặn bẩn và mạt kim loại, giúp hệ thống hoạt động ổn định và tăng độ bền. Hệ thống nâng hạ thùng xe trên ô tô KamAZ 65115 được trang bị xi-lanh thủy lực (5) loại ba giai đoạn, tác động đơn, dạng ống lồng, lắp phía trước thùng xe, đầu trên liên kết với đáy thùng và đầu dưới gắn với khung xe qua bản lề. Bơm dầu của hệ thống là loại bơm bánh răng, có lưu lượng 56 lít/phút ở tốc độ trục bơm 1900 ÷ 2000 vòng/phút. Bơm dầu được dẫn động bởi động cơ thông qua hộp số và hộp trích công suất (2), với tỷ số truyền động giữa động cơ và bơm là 1,26.","pages":[175]},{"id":"s2002","kind":"figure","lesson":"12.2.2","title":"Hình 12.41. Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115 1. Thùng dầu thủy lực; 2. Hộp trích công suất từ hộp số chính; 3. Van điện – khí","text":"Hình 12.41. Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115 1. Thùng dầu thủy lực; 2. Hộp trích công suất từ hộp số chính; 3. Van điện – khí","pages":[176],"figure":{"number":"12.41","caption":"Hình 12.41. Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115 1. Thùng dầu thủy lực; 2. Hộp trích công suất từ hộp số chính; 3. Van điện – khí"}},{"id":"s2003","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"nén; 4. Van điều khiển; 5. Xi-lanh thủy lực; 6. Van giới hạn nâng sàn. Van giới hạn nâng (6) có nhiệm vụ giới hạn độ nâng của sàn khi sàn đã đạt đến góc nâng tối đa, đảm bảo an toàn cho hệ thống. Van điều khiển thủy lực (4) kết hợp với van điện – khí nén (3) tạo thành cụm điều khiển trung tâm. Van điện – khí nén (3) nhận tín hiệu từ người lái, điều khiển van phân phối thay đổi vị trí để dẫn dòng dầu tới xi-lanh (5) hoặc cho dầu hồi về thùng dầu (1). Ngoài ra, trong van điều khiển (4) còn tích hợp van an toàn nhằm bảo vệ hệ thống khi áp suất vượt quá giới hạn cho phép.","pages":[176]},{"id":"s2004","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Van điện – khí nén (3) được nối với hệ thống khí nén của xe, cung cấp nguồn khí đến các buồng khí nén lắp trên hộp trích công suất để điều khiển quá trình đóng ngắt và phân phối dầu. * Cơ cấu điều chỉnh độ nâng thùng xe KamAZ 65115 (Hình 12.42): Đặc điểm cấu tạo (Hình 12.42): Cơ cấu điều chỉnh nâng hạ thùng xe KamAZ 65115 gồm các bộ phận chính sau: chốt khóa (1), giá đỡ (2), dây cáp (3), kẹp giữ cáp (4), van giới hạn nâng sàn (5), vít điều chỉnh (6), xi-lanh thủy lực (7) và đai ốc khóa (8). Chốt khóa (1) được lắp trên giá đỡ (2) hàn cố định ở khung phụ, có tác dụng khóa cơ khí để giữ thùng ở vị trí giới hạn khi nâng, đảm bảo an toàn cho hệ thống. Dây cáp (3) bằng thép bện chịu lực được nối giữa thùng và khung, có tác dụng giới hạn hành trình nâng và phòng ngừa sự cố khi thủy lực mất tác dụng.","pages":[176]},{"id":"s2005","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Để cố định và điều chỉnh chiều dài dây cáp, hệ thống sử dụng kẹp giữ cáp (4), đồng thời bảo đảm độ võng của cáp luôn nằm trong giới hạn cho phép (35 ÷ 50 mm). Để điều chỉnh góc nâng tối đa, trên thân xi-lanh thủy lực (7) bố trí van giới hạn (5). Van này được điều khiển bởi vít điều chỉnh (6), cho phép thay đổi hành trình tác động và nhờ đó có thể thiết lập góc nâng cực đại phù hợp yêu cầu sử dụng. Sau khi điều chỉnh, đai ốc khóa (8) được dùng để cố định vít, ngăn ngừa việc tự xoay trong quá trình vận hành. Xi-lanh thủy lực (7) là loại xi-lanh nhiều tầng, tác động đơn, dạng ống lồng, giữ vai trò cơ cấu chấp hành chính để nâng hạ thùng xe.","pages":[176]},{"id":"s2006","kind":"figure","lesson":"12.2.2","title":"Hình 12.42. Cơ cấu điều chỉnh nâng hạ thùng xe KamAZ 65115 1. Chốt khóa (chốt chặn); 2. Giá đỡ; 3. Dây cáp; 4. Kẹp giữ cáp; 5. Van giới hạn","text":"Hình 12.42. Cơ cấu điều chỉnh nâng hạ thùng xe KamAZ 65115 1. Chốt khóa (chốt chặn); 2. Giá đỡ; 3. Dây cáp; 4. Kẹp giữ cáp; 5. Van giới hạn","pages":[177],"figure":{"number":"12.42","caption":"Hình 12.42. Cơ cấu điều chỉnh nâng hạ thùng xe KamAZ 65115 1. Chốt khóa (chốt chặn); 2. Giá đỡ; 3. Dây cáp; 4. Kẹp giữ cáp; 5. Van giới hạn"}},{"id":"s2007","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Nguyên lý làm việc của cơ cấu: Trong quá trình vận hành, cơ cấu điều chỉnh nâng hạ thùng xe đảm bảo thùng chỉ nâng đến một góc giới hạn nhất định, đồng thời có hệ thống cáp và chốt khóa dự phòng để tăng cường an toàn. nâng sàn; 6. Vít điều chỉnh; 7. Xi-lanh thủy lực; 8. Đai ốc khóa. a) Cơ cấu điều chỉnh nâng thùng xe; b) Lắp đặt cáp an toàn Khi nâng thùng, xi-lanh thủy lực (7) tác động đơn nhiều tầng sẽ duỗi ra, đẩy thùng xe quay quanh bản lề. Khi thùng đạt đến góc nâng tối đa cho phép, thân xi-lanh thủy lực sẽ tác động vào vít điều chỉnh (6), làm mở van giới hạn (5). Lúc này, dầu thủy lực từ bơm sẽ chảy qua van về thùng chứa, quá trình nâng dừng lại. Góc nâng của thùng có thể thay đổi bằng cách điều chỉnh vị trí của vít điều chỉnh, sau đó cố định lại bằng đai ốc khóa (8) để đảm bảo chính xác và an toàn trong quá trình làm việc.","pages":[177]},{"id":"s2008","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Đồng thời, trong suốt quá trình nâng, dây cáp (3) được lắp căng giữa thùng và giá đỡ (2) luôn giữ vai trò giới hạn bổ sung. Nếu hệ thống thủy lực mất tác dụng, dây cáp sẽ ngăn thùng nâng vượt quá mức cho phép. Độ võng của dây cáp phải được duy trì trong khoảng 35 ÷ 50 mm; khi sai lệch, có thể điều chỉnh bằng kẹp giữ cáp (4). Khi thùng được nâng lên, để cố định ở vị trí cao phục vụ bảo dưỡng hoặc kiểm tra, có thể sử dụng chốt khóa (1) lắp vào các lỗ trên giá đỡ. Chốt này đảm bảo giữ thùng an toàn ngay cả khi hệ thống thủy lực mất áp suất đột ngột. * Nguyên lý làm việc của hệ thống nâng hạ thùng xe (Hình 12.43) Hệ thống nâng hạ thùng xe KamAZ 65115 hoạt động nhờ sự phối hợp của hệ thống thủy lực và hệ thống khí nén, có điều khiển bằng điện.","pages":[177]},{"id":"s2009","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Các chi tiết chính bao gồm: xi-lanh thủy lực (1), van giới hạn (2), van an toàn của lọc (3), bộ lọc dầu (4), thùng dầu (5), bơm dầu (6), hộp trích công suất (7), các buồng khí nén (8,10,17), các van điện – khí nén (9), cầu chì (11), công tắc PTO (12), tiếp điểm nâng thùng (13), đèn báo PTO (14), công tắc nâng/hạ thùng (15), van điều khiển (16), và van an toàn thủy lực (18).","pages":[177]},{"id":"s2010","kind":"figure","lesson":"12.2.2","title":"Hình 12.43. Sơ đồ nguyên lý của hệ thống nâng hạ thùng xe KamAZ 65115","text":"Hình 12.43. Sơ đồ nguyên lý của hệ thống nâng hạ thùng xe KamAZ 65115","pages":[178],"figure":{"number":"12.43","caption":"Hình 12.43. Sơ đồ nguyên lý của hệ thống nâng hạ thùng xe KamAZ 65115"}},{"id":"s2011","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Khi kích hoạt hệ thống: Trước tiên, người lái đạp ly hợp và bật công tắc PTO (12). Khi công tắc này đóng, đèn báo PTO (14) sáng để báo hiệu PTO đã được kích hoạt. Dòng điện 24V từ ắc quy qua cầu chì (11) sẽ cấp cho van điện – khí nén số 3 (9). Khi lõi van dịch chuyển, khí nén từ bình chứa đi vào buồng khí nén (17), làm cơ cấu gài của hộp trích công suất (7) tác động, kết nối bơm dầu với hộp số. Khi nhả ly hợp, bơm dầu (6) bắt đầu quay, hút dầu từ thùng dầu (5) qua bộ lọc (4) rồi đẩy tới van điều khiển (16). Ở trạng thái ban đầu, dầu chỉ tuần hoàn qua van rồi trở lại thùng, giúp làm nóng dầu trong mùa lạnh và đảm bảo hệ thống sẵn sàng làm việc. 1. Xi-lanh thủy lực; 2. Van giới hạn; 3. Van an toàn của lọc; 4. Bộ lọc dầu; 5. Thùng dầu; 6. Bơm dầu; 7. Hộp trích công suất; 8, 10, 17. Buồng khí nén; 9. Van điện – khí nén; 11. Cầu chì lấy nguồn 24V; 12.","pages":[178]},{"id":"s2012","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Công tắc PTO; 13. Tiếp điểm nâng thùng; 14.Đèn báo PTO; 15. Công tắc nâng/ hạ thùng; 16. Van điều khiển; 18. Van an toàn hệ Quá trình nâng thùng: Khi cần nâng thùng xe, người lái gạt công tắc nâng/hạ (15) sang vị trí “II”. Lúc này, dòng điện đi tới cuộn dây của van điện – khí nén số 1 và số 2 (9). Cả hai lõi van cùng dịch chuyển, mở đường khí nén từ bình chứa tới các buồng khí nén (8,10) của van điều khiển (16). Dưới tác động khí nén, van điều khiển (16) chuyển trạng thái, nối đường dầu áp suất cao từ bơm dầu (6) tới xi-lanh thủy lực (1). Dầu áp suất cao đi vào xi-lanh, lần lượt đẩy các tầng của xi-lanh ống lồng dịch chuyển, nhờ đó thùng xe quay quanh bản lề và nâng lên. Khi thùng nâng, tiếp điểm nâng thùng (13) đóng, gửi tín hiệu báo trạng thái đang nâng.","pages":[178]},{"id":"s2013","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Giới hạn nâng và an toàn: Khi thùng đạt đến góc nâng cực đại, thân xi-lanh (1) sẽ chạm vào vít điều chỉnh của van giới hạn (2). Van này mở đường hồi, dầu từ xi-lanh chảy về thùng dầu (5), nhờ đó thùng ngừng nâng để tránh quá hành trình. Trong trường hợp áp suất hệ thống vượt quá giá trị cho phép (ví dụ do kẹt cơ khí hoặc tải trọng bất thường), van an toàn thủy lực (18) và van an toàn của lọc (3) sẽ mở, xả dầu về thùng, đảm bảo an toàn cho bơm và xi-lanh.","pages":[178]},{"id":"s2014","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Giữ thùng ở vị trí trung gian: Nếu muốn dừng thùng ở vị trí bất kỳ trong quá trình nâng/hạ, người lái đưa công tắc (15) về vị trí trung gian. Lúc này, van điện – khí nén số 1 và 2 (9) mất điện, khí nén thoát ra khí quyển, các buồng khí nén (8,10) thôi tác động. Van điều khiển (16) trở về trạng thái khóa: cả đường dầu vào và đường hồi đều đóng. Do đó, dầu bị giữ trong xi-lanh (1), thùng xe được cố định ở vị trí hiện tại, không bị tụt xuống. Dầu từ bơm (6) lúc này xả qua van điều khiển (16) trở về thùng (5). Quá trình hạ thùng: Để hạ thùng, người lái gạt công tắc (15) về vị trí “I”. Trong trường hợp này, chỉ van điện – khí nén số 1 (9) được cấp điện, mở đường khí nén tới buồng khí nén “a” (10). Buồng này tác động làm van điều khiển (16) chuyển trạng thái xả, nối đường dầu từ xi-lanh (1) về thùng dầu (5).","pages":[179]},{"id":"s2015","kind":"pdf","lesson":"12.2.2","title":"Khung vỏ và thiết bị phụ trên ô tô · Hệ thống tời và nâng hạ thùng xe","text":"Dưới tác dụng trọng lực, các tầng ống lồng của xi-lanh thu lại, thùng xe được hạ xuống từ từ và an toàn. Kết thúc chu trình: Khi thùng đã hạ hoàn toàn, người lái đạp ly hợp và tắt công tắc PTO (12), hộp trích công suất (7) ngắt khỏi hộp số, bơm dầu (6) dừng hoạt động. Đồng thời, van điện – khí nén (9) cũng mất điện, toàn bộ hệ thống trở về trạng thái chờ.","pages":[179]},{"id":"s2016","kind":"figure","lesson":"9.3.1","title":"Hình 9.9 — Bố trí chung của hệ thống lái","text":"Hình 9.9 — Bố trí chung của hệ thống lái","pages":[20],"figure":{"image":"nt/figures/t2-9-9.jpg","caption":"Hình 9.9 — Bố trí chung của hệ thống lái","number":"9.9"}},{"id":"s2017","kind":"figure","lesson":"9.2.1","title":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","text":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","pages":[15],"figure":{"image":"nt/figures/t2-9-3.jpg","caption":"Hình 9.3 — Cơ cấu lái trục vít – bánh vít","number":"9.3"}},{"id":"s2018","kind":"figure","lesson":"9.2.2","title":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","text":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","pages":[16],"figure":{"image":"nt/figures/t2-9-4.jpg","caption":"Hình 9.4 — Cơ cấu lái trục vít lõm – con lăn","number":"9.4"}},{"id":"s2019","kind":"figure","lesson":"9.2.3","title":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","text":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","pages":[18],"figure":{"image":"nt/figures/t2-9-6.jpg","caption":"Hình 9.6 — Cơ cấu lái bánh răng – thanh răng trên các mẫu xe thế hệ cũ","number":"9.6"}},{"id":"s2020","kind":"figure","lesson":"9.2.4","title":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","text":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","pages":[19],"figure":{"image":"nt/figures/t2-9-8.jpg","caption":"Hình 9.8 — Cơ cấu lái trục vít – đai ốc – thanh răng – cung răng","number":"9.8"}},{"id":"s2021","kind":"figure","lesson":"9.3.3","title":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","text":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","pages":[29],"figure":{"image":"nt/figures/t2-9-23.jpg","caption":"Hình 9.23 — Các góc đặt bánh xe dẫn hướng","number":"9.23"}},{"id":"s2022","kind":"figure","lesson":"9.4.1","title":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","text":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","pages":[35],"figure":{"image":"nt/figures/t2-9-30.jpg","caption":"Hình 9.30 — Các kiểu bố trí trợ lực lái trên ô tô","number":"9.30"}},{"id":"s2023","kind":"figure","lesson":"9.4.2","title":"Hình 9.37 — Sơ đồ trợ lực lái điện","text":"Hình 9.37 — Sơ đồ trợ lực lái điện","pages":[42],"figure":{"image":"nt/figures/t2-9-37.jpg","caption":"Hình 9.37 — Sơ đồ trợ lực lái điện","number":"9.37"}},{"id":"s2024","kind":"figure","lesson":"10.2.1","title":"Hình 10.2 — Cơ cấu phanh tang trống","text":"Hình 10.2 — Cơ cấu phanh tang trống","pages":[56],"figure":{"image":"nt/figures/t2-10-2.jpg","caption":"Hình 10.2 — Cơ cấu phanh tang trống","number":"10.2"}},{"id":"s2025","kind":"figure","lesson":"10.2.2","title":"Hình 10.18 — Cấu tạo phanh đĩa","text":"Hình 10.18 — Cấu tạo phanh đĩa","pages":[64],"figure":{"image":"nt/figures/t2-10-18.jpg","caption":"Hình 10.18 — Cấu tạo phanh đĩa","number":"10.18"}},{"id":"s2026","kind":"figure","lesson":"10.3.1","title":"Hình 10.28 — Dẫn động phanh cơ khí","text":"Hình 10.28 — Dẫn động phanh cơ khí","pages":[69],"figure":{"image":"nt/figures/t2-10-28.jpg","caption":"Hình 10.28 — Dẫn động phanh cơ khí","number":"10.28"}},{"id":"s2027","kind":"figure","lesson":"10.3.2","title":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","text":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","pages":[72],"figure":{"image":"nt/figures/t2-10-34.jpg","caption":"Hình 10.34 — Sơ đồ dẫn động điều khiển phanh bằng thủy lực","number":"10.34"}},{"id":"s2028","kind":"figure","lesson":"10.3.3","title":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","text":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","pages":[82],"figure":{"image":"nt/figures/t2-10-46.jpg","caption":"Hình 10.46 — Sơ đồ nguyên lý hệ thống phanh khí nén","number":"10.46"}},{"id":"s2029","kind":"figure","lesson":"10.3.4","title":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","text":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","pages":[90],"figure":{"image":"nt/figures/t2-10-55.jpg","caption":"Hình 10.55 — Sơ đồ hệ thống phanh thủy lực – khí nén","number":"10.55"}},{"id":"s2030","kind":"figure","lesson":"10.3.5","title":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","text":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","pages":[92],"figure":{"image":"nt/figures/t2-10-58.jpg","caption":"Hình 10.58 — Sơ đồ các cụm chức năng cơ cấu ABS thủy lực","number":"10.58"}},{"id":"s2031","kind":"figure","lesson":"11.3.1","title":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","text":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","pages":[123],"figure":{"image":"nt/figures/t2-11-21.jpg","caption":"Hình 11.21 — Hệ thống treo có bộ phận đàn hồi là lò xo xoắn","number":"11.21"}},{"id":"s2032","kind":"figure","lesson":"11.2.1","title":"Hình 11.1 — Lắp nhíp trên xe","text":"Hình 11.1 — Lắp nhíp trên xe","pages":[112],"figure":{"image":"nt/figures/t2-11-1.jpg","caption":"Hình 11.1 — Lắp nhíp trên xe","number":"11.1"}},{"id":"s2033","kind":"figure","lesson":"11.2.2","title":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","text":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","pages":[120],"figure":{"image":"nt/figures/t2-11-16.jpg","caption":"Hình 11.16 — Sơ đồ hệ thống treo MacPherson","number":"11.16"}},{"id":"s2034","kind":"figure","lesson":"11.3.2","title":"Hình 11.32 — Bộ phận đàn hồi khí nén","text":"Hình 11.32 — Bộ phận đàn hồi khí nén","pages":[130],"figure":{"image":"nt/figures/t2-11-32.jpg","caption":"Hình 11.32 — Bộ phận đàn hồi khí nén","number":"11.32"}},{"id":"s2035","kind":"figure","lesson":"11.4.1","title":"Hình 11.39 — Giảm chấn kiểu ống đơn","text":"Hình 11.39 — Giảm chấn kiểu ống đơn","pages":[135],"figure":{"image":"nt/figures/t2-11-39.jpg","caption":"Hình 11.39 — Giảm chấn kiểu ống đơn","number":"11.39"}},{"id":"s2036","kind":"figure","lesson":"11.4.2","title":"Hình 11.40 — Giảm chấn kiểu ống kép","text":"Hình 11.40 — Giảm chấn kiểu ống kép","pages":[136],"figure":{"image":"nt/figures/t2-11-40.jpg","caption":"Hình 11.40 — Giảm chấn kiểu ống kép","number":"11.40"}},{"id":"s2037","kind":"figure","lesson":"11.5.1","title":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","text":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","pages":[140],"figure":{"image":"nt/figures/t2-11-45.jpg","caption":"Hình 11.45 — Các bộ phận và hệ thống của khung gầm Hydractive","number":"11.45"}},{"id":"s2038","kind":"figure","lesson":"11.5.2","title":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","text":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","pages":[143],"figure":{"image":"nt/figures/t2-11-48.jpg","caption":"Hình 11.48 — Sơ đồ nối mạch của bộ giảm chấn điện tử","number":"11.48"}},{"id":"s2039","kind":"figure","lesson":"12.1.2","title":"Hình 12.6 — Cấu tạo một số khung xe tải","text":"Hình 12.6 — Cấu tạo một số khung xe tải","pages":[150],"figure":{"image":"nt/figures/t2-12-6.jpg","caption":"Hình 12.6 — Cấu tạo một số khung xe tải","number":"12.6"}},{"id":"s2040","kind":"figure","lesson":"12.2.2","title":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","text":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","pages":[176],"figure":{"image":"nt/figures/t2-12-41.jpg","caption":"Hình 12.41 — Sơ đồ bố trí của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.41"}},{"id":"s2041","kind":"figure","lesson":"12.2.2","title":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","text":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","pages":[169],"figure":{"image":"nt/figures/t2-12-35.jpg","caption":"Hình 12.35 — Sơ đồ bố trí chung hệ thống tời","number":"12.35"}},{"id":"s2042","kind":"figure","lesson":"9.4.3","title":"Hình 9.47 — Hệ thống lái không trục lái","text":"Hình 9.47 — Hệ thống lái không trục lái","pages":[50],"figure":{"image":"nt/figures/t2-9-47.jpg","caption":"Hình 9.47 — Hệ thống lái không trục lái","number":"9.47"}},{"id":"s2043","kind":"figure","lesson":"9.4.3","title":"Hình 9.44 — Sơ đồ hệ thống lái trợ lực thủy lực điều khiển điện tử","text":"Hình 9.44 — Sơ đồ hệ thống lái trợ lực thủy lực điều khiển điện tử","pages":[47],"figure":{"image":"nt/figures/t2-9-44.jpg","caption":"Hình 9.44 — Sơ đồ hệ thống lái trợ lực thủy lực điều khiển điện tử","number":"9.44"}},{"id":"s2044","kind":"figure","lesson":"10.3.5","title":"Hình 10.61 — Van điện từ 2-vị trí có van điều khiển lưu lượng","text":"Hình 10.61 — Van điện từ 2-vị trí có van điều khiển lưu lượng","pages":[94],"figure":{"image":"nt/figures/t2-10-61.jpg","caption":"Hình 10.61 — Van điện từ 2-vị trí có van điều khiển lưu lượng","number":"10.61"}},{"id":"s2045","kind":"figure","lesson":"10.3.5","title":"Hình 10.72 — ABS ở dẫn động phanh khí nén — chế độ tăng áp","text":"Hình 10.72 — ABS ở dẫn động phanh khí nén — chế độ tăng áp","pages":[100],"figure":{"image":"nt/figures/t2-10-72.jpg","caption":"Hình 10.72 — ABS ở dẫn động phanh khí nén — chế độ tăng áp","number":"10.72"}},{"id":"s2046","kind":"figure","lesson":"10.3.5","title":"Hình 10.73 — Chế độ giữ áp và giảm áp","text":"Hình 10.73 — Chế độ giữ áp và giảm áp","pages":[100],"figure":{"image":"nt/figures/t2-10-73.jpg","caption":"Hình 10.73 — Chế độ giữ áp và giảm áp","number":"10.73"}},{"id":"s2047","kind":"figure","lesson":"12.2.1","title":"Hình 12.28 — Sơ đồ bố trí hệ thống điều chỉnh áp suất hơi lốp trên xe ZIL-131","text":"Hình 12.28 — Sơ đồ bố trí hệ thống điều chỉnh áp suất hơi lốp trên xe ZIL-131","pages":[163],"figure":{"image":"nt/figures/t2-12-28.jpg","caption":"Hình 12.28 — Sơ đồ bố trí hệ thống điều chỉnh áp suất hơi lốp trên xe ZIL-131","number":"12.28"}},{"id":"s2048","kind":"figure","lesson":"12.2.2","title":"Hình 12.42 — Cơ cấu điều chỉnh nâng hạ thùng xe KamAZ 65115","text":"Hình 12.42 — Cơ cấu điều chỉnh nâng hạ thùng xe KamAZ 65115","pages":[177],"figure":{"image":"nt/figures/t2-12-42.jpg","caption":"Hình 12.42 — Cơ cấu điều chỉnh nâng hạ thùng xe KamAZ 65115","number":"12.42"}},{"id":"s2049","kind":"figure","lesson":"12.2.2","title":"Hình 12.43 — Sơ đồ nguyên lý của hệ thống nâng hạ thùng xe KamAZ 65115","text":"Hình 12.43 — Sơ đồ nguyên lý của hệ thống nâng hạ thùng xe KamAZ 65115","pages":[178],"figure":{"image":"nt/figures/t2-12-43.jpg","caption":"Hình 12.43 — Sơ đồ nguyên lý của hệ thống nâng hạ thùng xe KamAZ 65115","number":"12.43"}},{"id":"s2050","kind":"topic","lesson":"10.3.5","title":"Hệ thống chống bó cứng bánh xe (ABS)","text":"Cảm biến cung cấp tín hiệu tốc độ quay bánh xe. ECU nhận biết xu hướng bó cứng và điều khiển bộ chấp hành thay đổi áp suất phanh ở bánh xe. Việc điều chỉnh giúp bánh xe còn khả năng truyền lực ngang, hỗ trợ giữ ổn định hướng và khả năng lái khi phanh. Quãng đường phanh và vùng trượt làm việc phụ thuộc điều kiện bám giữa lốp và mặt đường.","key":"abs","keywords":["ABS","chống bó cứng bánh xe","chống hãm cứng bánh xe","chống khóa bánh","anti lock braking system"],"pages":[92,93],"figureNumber":"10.58","more":["abs-oil","abs-air","abs-slip"]},{"id":"s2051","kind":"topic","lesson":"10.3.5","title":"Ba chế độ áp suất của ABS thủy lực","text":"Với sơ đồ ABS thủy lực hai van trong học liệu, tăng áp mở van nạp và đóng van xả. Giữ áp đóng cả hai van để cô lập mạch tại cơ cấu phanh bánh xe. Giảm áp đóng van nạp và mở van xả để dầu về bình tích áp. ECU chọn chế độ theo tín hiệu và trạng thái bánh xe. Sơ đồ minh họa hoạt động của từng van trong kết cấu đang xét.","key":"abs-oil","keywords":["ABS thủy lực","tăng áp giữ áp giảm áp","3 chế độ áp suất","điều khiển áp suất dầu","van nạp van xả","bộ chấp hành abs","xả dầu phanh"],"phases":{"tang_ap":"Trong sơ đồ ABS thủy lực hai van, van nạp mở và van xả đóng. Dầu được cấp tới cơ cấu phanh bánh xe để tăng áp suất.","giu_ap":"Trong sơ đồ ABS thủy lực hai van, cả van nạp và van xả đều đóng. Đường dầu ở cơ cấu phanh bánh xe được cô lập để duy trì áp suất.","giam_ap":"Trong sơ đồ ABS thủy lực hai van, van nạp đóng và van xả mở. Dầu từ cơ cấu phanh bánh xe có đường về bình tích áp, làm giảm áp suất tại bánh."},"pages":[93,94],"figureNumber":"10.60","more":["abs-air","abs-slip"]},{"id":"s2052","kind":"topic","lesson":"10.3.5","title":"Ba chế độ của ABS khí nén","text":"Trong sơ đồ ABS khí nén ở Tập 2, cửa A nối nguồn khí qua van phân phối, cửa B nối bầu phanh và cửa C thông khí trời. Tăng áp thông A với B để cấp khí. Giữ áp cô lập B bằng cách đóng đường cấp và đường xả. Giảm áp ngắt đường cấp và thông B với C để xả khí khỏi bầu phanh.","key":"abs-air","keywords":["ABS khí nén","ABS phanh hơi","bộ điều biến khí nén","bầu phanh ABS","cửa A B C","Hình 10.72","Hình 10.73"],"phases":{"tang_ap":"Bộ điều biến thông cửa A với cửa B để cấp khí vào bầu phanh và đóng đường xả C. Áp suất trong bầu phanh tăng.","giu_ap":"Bộ điều biến đóng cả đường cấp từ A và đường xả ra C. Cửa B nối với bầu phanh được cô lập để duy trì áp suất.","giam_ap":"Bộ điều biến đóng đường cấp từ A và thông B với C. Khí từ bầu phanh thoát ra khí trời, làm giảm áp suất trong bầu."},"pages":[100,101],"figureNumber":"10.72","more":["abs-oil","air-brake"]},{"id":"s2053","kind":"topic","lesson":"10.3.5","title":"Hệ số trượt và khả năng bám khi phanh","text":"Đường đặc tính ở Hình 10.57 cho thấy lực bám dọc tăng đến cực đại rồi có xu hướng giảm khi bánh tiến gần trạng thái bó cứng. Hệ số trượt ở cực đại thay đổi theo lốp, tải trọng, tốc độ và mặt đường. Tài liệu dùng vùng trượt thích hợp để giải thích nguyên lý ABS. Muốn xác định tần số điều áp hoặc giá trị đặt cụ thể cần dữ liệu của hệ thống đang xét.","key":"abs-slip","keywords":["hệ số trượt","độ trượt ABS","đặc tính trượt","15 20 phần trăm","15 20 lần giây","tần số ABS","quãng đường phanh ABS"],"pages":[92,93],"figureNumber":"10.57","more":["abs","abs-oil"]},{"id":"s2054","kind":"topic","lesson":"10.3.5","title":"Cảm biến tốc độ bánh xe của ABS","text":"Cảm biến tốc độ bánh xe cung cấp tín hiệu về trạng thái quay của bánh. ECU phân tích tín hiệu từ các cảm biến để đánh giá mức trượt và điều khiển bộ chấp hành. Hình 10.58 chỉ vị trí cảm biến trước và sau trong sơ đồ ABS thủy lực.","key":"wheel-sensor","keywords":["cảm biến tốc độ bánh xe","cảm biến ABS","wheel speed sensor","tín hiệu tốc độ bánh","vòng răng cảm biến"],"pages":[92,93,96],"figureNumber":"10.58","more":["abs","abs-oil"]},{"id":"s2055","kind":"topic","lesson":"10.3.5","title":"Phân phối lực phanh điện tử (EBD)","text":"EBD điều chỉnh phân bố lực phanh theo tải trọng và tình trạng bám, giúp hạn chế nguy cơ bánh sau bó cứng sớm và giữ ổn định hướng khi phanh. EBD phối hợp với ABS và dùng các tín hiệu liên quan đến tốc độ bánh xe. ABS tập trung phát hiện và điều chỉnh áp suất khi bánh có xu hướng bó cứng.","key":"ebd","keywords":["EBD","phân phối lực phanh điện tử","phân bố lực phanh","lực phanh cầu trước cầu sau"],"pages":[102,103],"figureNumber":"10.74","more":["abs","aeb"]},{"id":"s2056","kind":"topic","lesson":"10.3.5","title":"Cảnh báo va chạm phía trước (FCW) và phanh khẩn cấp tự động (AEB)","text":"FCW phát cảnh báo cho người lái khi phát hiện nguy cơ va chạm phía trước. AEB có thể yêu cầu hệ thống phanh tự động giảm tốc khi nguy cơ va chạm đáp ứng điều kiện can thiệp. Hiệu quả và mức can thiệp phụ thuộc thiết kế hệ thống và tình huống thực tế.","key":"aeb","keywords":["FCW","AEB","cảnh báo va chạm","phanh khẩn cấp tự động","phanh tự động","automatic emergency braking"],"pages":[104,105],"more":["ebd","abs"]},{"id":"s2057","kind":"topic","lesson":"10.3.5","title":"Phanh đỗ điện tử (EPB)","text":"EPB dùng bộ điều khiển và cơ cấu chấp hành điện để thực hiện chức năng phanh đỗ. Ở ví dụ trong Tập 2, cơ cấu chấp hành tạo lực ép má phanh vào đĩa phanh. ECU xử lý tín hiệu từ công tắc EPB và các cảm biến liên quan.","key":"epb","keywords":["EPB","phanh tay điện tử","phanh đỗ điện tử","auto hold"],"pages":[106,107,109],"figureNumber":"10.77","more":["abs","ebd"]},{"id":"s2058","kind":"topic","lesson":"10.3.3","title":"Nguyên lý dẫn động phanh khí nén","text":"Máy nén nạp khí vào bình chứa. Khi đạp phanh, van phanh tổng điều khiển khí nén tới bầu phanh. Màng hoặc pít-tông của bầu phanh biến áp suất khí thành lực tác dụng lên cơ cấu phanh. Khi thôi phanh, đường khí tới bầu được xả và cơ cấu hồi vị theo sơ đồ trong bài.","key":"air-brake","keywords":["phanh khí nén","phanh hơi","van phanh tổng","bầu phanh","máy nén khí","dẫn động khí nén"],"pages":[82,83,84],"figureNumber":"10.46","more":["hydraulic-brake","abs-air"]},{"id":"s2059","kind":"topic","lesson":"10.3.2","title":"Nguyên lý dẫn động phanh thủy lực","text":"Khi đạp phanh, xi lanh chính tạo áp suất trong mạch dầu. Áp suất truyền qua đường ống tới xi lanh công tác hoặc pít-tông cùm phanh. Lực tại cơ cấu phanh ép guốc hoặc má phanh để tạo mô men phanh. Khi nhả bàn đạp, áp suất giảm và các chi tiết hồi về theo kết cấu của cơ cấu.","key":"hydraulic-brake","keywords":["phanh dầu","dẫn động phanh thủy lực","dẫn động phanh bằng thủy lực","dẫn động phanh dầu","xi lanh chính truyền áp","hydraulic brake"],"pages":[72,73,74],"figureNumber":"10.34","more":["air-brake","vacuum-booster","abs-oil"]},{"id":"s2060","kind":"topic","lesson":"2.2.1","title":"Đóng và ngắt ly hợp ma sát một đĩa","text":"Khi nhả bàn đạp, lò xo ép kẹp đĩa ma sát giữa bánh đà và đĩa ép, đưa mô men tới trục sơ cấp hộp số. Khi đạp hết hành trình ngắt, dẫn động điều khiển tác động qua bạc mở để giải phóng lực kẹp và cắt đường truyền mô men. Khi nhả bàn đạp dần, lực kẹp tăng trở lại và đĩa ma sát có thể trượt trong giai đoạn tiếp nối.","key":"clutch","keywords":["ly hợp","li hợp","bộ côn","côn xe","đạp côn","nhả côn","ly hợp ma sát một đĩa","ly hợp 1 đĩa","bạc mở","lò xo màng"],"figureNumber":"2.1","more":["dct","synchro"]},{"id":"s2061","kind":"topic","lesson":"3.2.2","title":"Đường truyền trong hộp số ba trục","text":"Ở một số tiến gián tiếp của hộp số ba trục, mô men đi từ trục sơ cấp qua trục trung gian và cặp bánh răng được chọn tới trục thứ cấp. Ở số truyền thẳng của kết cấu minh họa, khớp gài nối trục sơ cấp với trục thứ cấp để hai trục quay cùng tốc độ. Trục thứ cấp đưa mô men ra khỏi hộp số.","key":"three-shaft","keywords":["hộp số ba trục","hộp số 3 trục","trục sơ cấp trung gian thứ cấp","số truyền thẳng","số tiến gián tiếp"],"more":["two-shaft","synchro"]},{"id":"s2062","kind":"topic","lesson":"3.2.3","title":"Đường truyền trong hộp số hai trục","text":"Trục sơ cấp nhận mô men từ ly hợp. Khi gài số, cơ cấu gài cố định bánh răng của cấp số đã chọn với trục. Mô men đi qua cặp bánh răng tương ứng tới trục thứ cấp. Ở dạng transaxle trong bài, hộp số và truyền lực chính được bố trí chung cụm.","key":"two-shaft","keywords":["hộp số hai trục","hộp số 2 trục","hộp số hai trục vận hành","transaxle","M5CF1"],"figureNumber":"3.26","more":["synchro","final-drive"]},{"id":"s2063","kind":"topic","lesson":"7.2.1","title":"Công dụng và đường truyền của truyền lực chính","text":"Truyền lực chính giảm tốc độ quay và tăng mô men đưa tới cầu chủ động. Trong sơ đồ bánh răng côn của bài, bánh răng chủ động truyền tới bánh răng bị động và đổi hướng đường truyền. Bánh răng bị động gắn với vỏ vi sai để truyền mô men tới các bán trục.","key":"final-drive","keywords":["truyền lực chính","bộ truyền lực chính","bánh răng côn chủ động","bánh răng côn bị động","final drive"],"figureNumber":"7.2","more":["differential","halfshaft"]},{"id":"s2064","kind":"topic","lesson":"7.2.3","title":"Công dụng của bán trục và vỏ cầu","text":"Bán trục truyền mô men từ bộ vi sai tới bánh xe chủ động. Mức tải uốn mà bán trục phải chịu phụ thuộc cách bố trí ổ đỡ ở đầu ngoài. Vỏ cầu làm giá đỡ và bao che các bộ phận của cầu. Có thể xem riêng đường truyền mô men và đường chịu tải trên sơ đồ của bài.","key":"halfshaft","keywords":["bán trục","vỏ cầu","bán trục giảm tải","tải uốn bán trục","half shaft"],"more":["differential","final-drive"]},{"id":"s2065","kind":"topic","lesson":"3.3.2","title":"Cơ cấu đồng tốc và gài số","text":"Khi thao tác gài số, ống trượt và vành ma sát dịch chuyển. Mặt côn của vành ma sát tỳ vào mặt côn bánh răng, tạo mô men ma sát để giảm chênh lệch tốc độ. Khi tốc độ đã được đồng đều, răng gài ăn khớp và ống trượt nối bánh răng đã chọn với trục.","key":"synchro","keywords":["cơ cấu đồng tốc","bộ đồng tốc","synchronizer","gài số","vành đồng tốc","ống trượt","mặt côn ma sát"],"more":["clutch","dct"]},{"id":"s2066","kind":"topic","lesson":"4.2.2","title":"Chuyển số ở hộp số ly hợp kép (DCT)","text":"Ở ví dụ chuyển từ số 2 sang số 3, ly hợp 2 đang truyền mô men qua nhánh số chẵn. Cơ cấu điều khiển chọn trước số 3 trên nhánh còn lại trong khi ly hợp 1 đang ngắt. Hệ thống giảm tác động ly hợp 2 và tăng tác động ly hợp 1 để chuyển mô men sang nhánh số lẻ.","key":"dct","keywords":["DCT","DSG","hộp số ly hợp kép","hộp số hai ly hợp","chuyển số 2 sang 3","chọn trước số"],"figureNumber":"4.1","more":["cvt","converter"]},{"id":"s2067","kind":"topic","lesson":"4.3.1","title":"Biến mô thủy lực và ly hợp khóa biến mô","text":"Động cơ dẫn động bánh bơm. Dòng dầu mang năng lượng tới bánh tua-bin để truyền mô men tới hộp số. Stato đổi hướng dòng dầu hồi và có thể được khớp một chiều giữ ở chế độ biến mô. Mức khuếch đại mô men phụ thuộc trạng thái làm việc và độ trượt. Khi ly hợp khóa biến mô đóng, đường truyền gần cơ khí trực tiếp.","key":"converter","keywords":["biến mô","bộ biến mô","biến mô thủy lực","bánh bơm","tua bin","stato","torque converter","lock up","hộp số AT"],"figureNumber":"4.3","more":["dct","cvt"]},{"id":"s2068","kind":"topic","lesson":"4.4.2","title":"Thay đổi tỷ số truyền của CVT dùng đai và puli","text":"Khi hai mặt côn sơ cấp tiến gần nhau, bán kính làm việc phía sơ cấp tăng. Puli thứ cấp phối hợp giảm bán kính làm việc. Hai bán kính thay đổi đồng thời theo ràng buộc của đai. Khi bỏ qua trượt, tỷ số truyền i = n sơ cấp / n thứ cấp = r thứ cấp / r sơ cấp. Tỷ số truyền biến thiên liên tục trong dải thiết kế của hộp số.","key":"cvt","keywords":["CVT","hộp số vô cấp","tỷ số truyền vô cấp","puli sơ cấp","puly thứ cấp","bán kính puli","dây đai CVT"],"figureNumber":"4.57","more":["converter","dct"]},{"id":"s2069","kind":"topic","lesson":"5.2.2","title":"Gài cầu và số thấp ở hộp phân phối hai cấp","text":"Trong kết cấu Hình 5.2, cơ cấu khóa hãm cho phép gài số truyền thấp sau khi đã nối cầu trước. Khi trở lại số truyền thẳng, nhả số thấp trước khi tách cầu trước. Trình tự này giải thích cơ cấu khóa hãm của mẫu hộp phân phối trong bài.","key":"transfer","keywords":["hộp số phân phối","hộp phân phối","cài cầu","gài cầu","gài số thấp","cơ cấu khóa hãm","số chậm"],"figureNumber":"5.2","more":["cardan","differential"]},{"id":"s2070","kind":"topic","lesson":"6.1.1","title":"Công dụng của truyền động các đăng","text":"Truyền động các đăng truyền mô men giữa các trục có đường tâm lệch nhau và có vị trí tương đối thay đổi. Khớp các đăng cho phép truyền mô men khi góc giữa các trục thay đổi. Liên kết then hoa trượt cho phép cụm trục thay đổi chiều dài làm việc trong giới hạn kết cấu.","key":"cardan","keywords":["các đăng","trục các đăng","truyền động các đăng","cardan","công dụng các đăng","bù chiều dài","khớp trượt","then hoa"],"figureNumber":"6.8","more":["cross-joint","constant-velocity"]},{"id":"s2071","kind":"topic","lesson":"6.2.2","title":"Cấu tạo khớp các đăng kiểu chữ thập","text":"Trục chữ thập liên kết hai nạng của khớp. Các chốt chữ thập làm việc trong ổ bi kim đặt ở lỗ trên nạng. Nắp và vòng hãm giữ ổ bi ở vị trí làm việc. Khi cần bù dịch chuyển dọc trục, thân trục dùng liên kết then hoa trượt.","key":"cross-joint","keywords":["khớp chữ thập","trục chữ thập","khớp các đăng chữ thập","cấu tạo các đăng","nạng chủ động","nắp vòng bi","ổ bi kim","vòng chặn","chạc đầu trục"],"figureNumber":"6.8","more":["cardan","constant-velocity"]},{"id":"s2072","kind":"topic","lesson":"6.2.1","title":"Điều kiện đồng tốc của hai khớp chữ thập","text":"Một khớp chữ thập làm việc với góc lệch tạo biến thiên tốc độ góc đầu ra trong một vòng quay. Hai khớp có thể bù biến thiên tốc độ khi bố trí đúng hình học, hai góc làm việc bằng nhau và lắp nạng đúng pha theo sơ đồ. Cơ cấu chữ thập kép cần duy trì điều kiện góc bằng nhau trong khi làm việc.","key":"constant-velocity","keywords":["khớp khác tốc","các đăng đồng tốc","đồng tốc chữ thập kép","lắp nạng đúng pha","góc làm việc bằng nhau","hai khớp chữ thập","hai khop cardan"],"more":["cross-joint","cardan"]},{"id":"s2073","kind":"topic","lesson":"7.2.2","title":"Vi sai đối xứng khi xe đi thẳng và quay vòng","text":"Khi đi thẳng với điều kiện hai bên như nhau, hai bán trục quay cùng tốc độ. Khi quay vòng, bánh ngoài đi quãng đường dài hơn và cần quay nhanh hơn. Bánh răng vi sai tự quay để cho phép chênh lệch tốc độ. Với vi sai đối xứng lý tưởng, tổng tốc độ hai bán trục bằng hai lần tốc độ vỏ vi sai. Mô men hai đầu ra xấp xỉ bằng nhau khi bỏ qua ma sát nội.","key":"differential","keywords":["vi sai","bộ vi sai","vi sai đối xứng","differential","bánh trong bánh ngoài","tốc độ hai bánh","mô men hai bán trục","hai bánh quay khác tốc độ khi rẽ"],"figureNumber":"7.11","more":["cardan","transfer"]},{"id":"s2074","kind":"topic","lesson":"8.2.3","title":"Cân bằng bánh xe và cân chỉnh góc đặt bánh xe","text":"Cân bằng bánh xe xử lý phân bố khối lượng không đều của cụm lốp và vành, qua đó giảm lực hoặc mô men mất cân bằng khi quay. Cân chỉnh góc đặt xử lý hình học dẫn hướng, chẳng hạn camber, caster và độ chụm. Khi đánh giá rung hoặc mòn lốp, cần xác định nguyên nhân tương ứng với từng nhóm kiểm tra.","key":"wheel-balance","keywords":["cân bằng bánh xe","cân bằng động","mất cân bằng bánh","cân chỉnh thước lái","rung bánh xe","đối trọng"],"more":["alignment","tire-pressure"]},{"id":"s2075","kind":"topic","lesson":"9.3.3","title":"Góc camber, góc caster và độ chụm","text":"Camber là góc giữa mặt phẳng bánh xe và phương thẳng đứng khi nhìn từ trước. Caster là góc nghiêng dọc của trục quay lái so với phương thẳng đứng khi nhìn từ bên. Độ chụm xét tương quan hai bánh khi nhìn từ trên. Theo quy ước đo khoảng cách của bài, độ chụm dương ứng với khoảng cách phía trước nhỏ hơn phía sau khi đo cùng độ cao.","key":"alignment","keywords":["camber","caster","toe","độ chụm","góc đặt bánh xe","góc nghiêng bánh xe","góc đặt bánh dẫn hướng"],"pages":[29,30,31,32,33,34],"figureNumber":"9.23","more":["wheel-balance","eps"]},{"id":"s2076","kind":"topic","lesson":"9.4.2","title":"Nguyên lý trợ lực lái điện (EPS)","text":"Cảm biến ghi nhận mô men tác động của người lái. ECU dùng tín hiệu này cùng tốc độ xe để tính mức trợ lực. Mô tơ điện tạo mô men hỗ trợ, truyền tới cơ cấu lái theo cách bố trí của hệ thống. Sơ đồ EPS trong bài có đường truyền cơ khí từ vành tay lái tới bánh xe.","key":"eps","keywords":["EPS","trợ lực lái điện","lái trợ lực điện","mô tơ trợ lực","cảm biến mô men lái","electric power steering"],"pages":[42,43,44,45],"figureNumber":"9.37","more":["sbw","alignment"]},{"id":"s2077","kind":"topic","lesson":"9.4.3","title":"Hệ thống lái không trục lái (Steer-by-Wire)","text":"Trong sơ đồ Tập 2, ECU nhận yêu cầu đánh lái từ tín hiệu ở vành tay lái và điều khiển bộ chấp hành tạo góc quay bánh xe. Vòng phản hồi góc thực hỗ trợ bám yêu cầu điều khiển. Một vòng riêng tạo phản hồi cảm giác cho người lái. Cách bố trí dự phòng phụ thuộc thiết kế của từng hệ thống.","key":"sbw","keywords":["SBW","steer by wire","lái không trục lái","lái bằng tín hiệu điện","hai vòng điều khiển lái","lái điện tử"],"pages":[50,51,52,53],"figureNumber":"9.47","more":["eps","alignment"]},{"id":"s2078","kind":"topic","lesson":"11.4.1","title":"Giảm chấn thủy lực kiểu ống đơn","text":"Ở Hình 11.39, khi nén, dầu đi từ khoang II sang khoang I qua van nén. Khi trả, dầu đi từ I về II qua đường van trả. Pít-tông ngăn khí dịch chuyển để bù thể tích do cần chiếm chỗ. Chiều chuyển động trên hình gắn với tư thế lắp đang minh họa.","key":"monotube","keywords":["giảm chấn ống đơn","giảm xóc ống đơn","monotube","pít tông khí","khoang khí giảm chấn"],"pages":[135,136],"figureNumber":"11.39","more":["twintube","cdc"]},{"id":"s2079","kind":"topic","lesson":"11.4.2","title":"Giảm chấn thủy lực kiểu ống kép","text":"Kết cấu ống kép có khoang bù III giữa vỏ trong và vỏ ngoài, thông qua đế van. Trong hành trình nén và trả, dầu lưu thông qua van trên pít-tông và đế van để vừa tạo lực cản, vừa bù phần thể tích do cần pít-tông đi vào hoặc đi ra. Lực cản giúp tiêu tán năng lượng dao động.","key":"twintube","keywords":["giảm chấn ống kép","giảm xóc ống kép","giảm chấn 2 ống","twin tube","khoang bù","khoang III","đế van giảm chấn"],"pages":[136,137,138],"figureNumber":"11.40","more":["monotube","cdc"]},{"id":"s2080","kind":"topic","lesson":"11.5.2","title":"Điều chỉnh lực giảm chấn điện tử (CDC)","text":"Bộ điều khiển nhận tín hiệu cảm biến dao động và lựa chọn mức cản. Trong ví dụ của bài, van tỷ lệ thay đổi điều kiện dòng dầu qua giảm chấn, qua đó thay đổi lực cản. CDC thuộc nhóm điều khiển giảm chấn bán chủ động. Các chế độ cản được chọn theo trạng thái xe và mục tiêu êm dịu hoặc ổn định.","key":"cdc","keywords":["CDC","continuous damping control","giảm chấn điện tử","giảm chấn bán chủ động","điều chỉnh lực giảm chấn","van tỷ lệ"],"pages":[143,144],"figureNumber":"11.48","more":["monotube","twintube"]},{"id":"s2081","kind":"topic","lesson":"12.2.1","title":"Điều chỉnh áp suất lốp trung tâm","text":"Ở chế độ bơm, van điều khiển thông nguồn khí với lốp. Ở chế độ giữ, đường cấp và đường xả được đóng. Ở chế độ xả, đường khí từ lốp thông ra ngoài. Trong sơ đồ dùng chung nguồn khí, van bảo vệ ưu tiên cấp khí cho hệ thống phanh khi áp suất nguồn thấp.","key":"tire-pressure","keywords":["CTIS","áp suất lốp trung tâm","điều chỉnh áp suất hơi lốp","bơm lốp tập trung","bơm giữ xả lốp","van bảo vệ nguồn khí"],"pages":[163,164,165],"figureNumber":"12.28","more":["air-brake","wheel-balance"]},{"id":"s2082","kind":"topic","lesson":"12.2.2","title":"Nâng, giữ và hạ thùng xe KamAZ 65115","text":"Hộp trích công suất dẫn động bơm dầu. Khi nâng, van điều khiển đưa dầu đến xi-lanh để nâng thùng. Khi giữ, van khóa đường dầu của xi-lanh trong sơ đồ. Khi hạ, dầu từ xi-lanh có đường hồi về thùng. Áp suất phát sinh theo tải và sức cản mạch. Các trạng thái này mô tả chức năng của sơ đồ nâng hạ.","key":"tipper","keywords":["nâng hạ thùng xe","nâng thùng","hạ thùng","thùng ben","xe ben","Kamaz 65115","xi lanh nâng thùng","van nâng giữ hạ"],"pages":[176,177,178],"figureNumber":"12.41","more":["winch","tire-pressure"]},{"id":"s2083","kind":"topic","lesson":"12.2.2","title":"Đường truyền mô men của tời cơ khí","text":"Công suất được lấy qua hộp số chính và hộp trích công suất. Trục các đăng truyền mô men tới hộp giảm tốc tời. Hộp giảm tốc truyền mô men tới trống để cuốn hoặc nhả cáp theo chế độ điều khiển.","key":"winch","keywords":["tời","tời cơ khí","trống tời","cáp tời","hộp giảm tốc tời","đường truyền tời"],"pages":[169,170,171],"figureNumber":"12.35","more":["tipper","cardan"]},{"id":"s2084","kind":"topic","lesson":"1.1.2","title":"Phân loại ô tô du lịch theo kiểu thân xe","text":"Bài 1.1.2 giới thiệu các kiểu thân xe như sedan, hatchback, coupé, MPV, SUV và crossover. Có thể nhận diện dựa trên cách bố trí khoang hành lý, hình dáng đuôi xe và mục đích sử dụng. Sedan thường có khoang hành lý tách riêng. Hatchback có cửa hậu mở cùng kính sau và thông với khoang hành khách.","key":"passenger-car-types","keywords":["phân loại ô tô du lịch","các kiểu thân xe du lịch","kiểu thân xe ô tô con","sedan hatchback coupe mpv"],"anchor":"block-1781142944871-i9l9zw09r","more":["wheel-formula","engine-purpose"]},{"id":"s2085","kind":"topic","lesson":"1.1.3","title":"Đọc công thức bánh xe A×B","text":"A là tổng số vị trí bánh xe và B là số vị trí bánh xe chủ động. Mỗi cặp bánh kép ở một đầu cầu được tính là một vị trí. Ví dụ, công thức 6×4 biểu thị sáu vị trí bánh xe, trong đó bốn vị trí nhận mô men dẫn động.","key":"wheel-formula","keywords":["công thức bánh xe","công thức bánh xe axb","ý nghĩa 6x4","công thức 6x4","công thức 6x6","công thức 4x2","công thức 4x4"],"anchor":"block-1781143377242-pl37oi9wd","more":["passenger-car-types","differential"]},{"id":"s2086","kind":"topic","lesson":"1.2.1","title":"Công dụng của động cơ trên ô tô","text":"Động cơ là nguồn động lực của ô tô. Nguồn động lực tạo mô men để hệ thống truyền lực đưa tới bánh xe chủ động. Động cơ đốt trong chuyển năng lượng của nhiên liệu thành công cơ học và có thể dẫn động một số thiết bị phụ. Ô tô điện dùng mô-tơ để chuyển điện năng thành công cơ học.","key":"engine-purpose","keywords":["động cơ là gì","công dụng động cơ","nhiệm vụ động cơ","chức năng động cơ ô tô","nguồn động lực ô tô"],"anchor":"block-1781143684121-gzmtzujgy","more":["clutch","final-drive"]},{"id":"s2087","kind":"topic","lesson":"2.2.1","title":"Bánh đà kép và giảm dao động xoắn","text":"Bánh đà kép có khối sơ cấp và khối thứ cấp liên kết với nhau qua phần tử đàn hồi. Khối sơ cấp nhận mô men từ động cơ. Liên kết đàn hồi cho phép hai khối dịch chuyển góc tương đối để giảm dao động xoắn truyền tới ly hợp và hộp số.","key":"dual-mass-flywheel","keywords":["bánh đà kép","dual mass flywheel","dmf","hai khối bánh đà"],"anchor":"block-1781145200514-484d8n5yt","figureNumber":"2.5","more":["clutch","three-shaft"]},{"id":"s2088","kind":"topic","lesson":"3.2.2","title":"Tăng số cấp bằng hộp số phụ","text":"Một số hộp số xe tải kết hợp hộp số chính với hộp số phụ để tăng số cấp truyền. Trong ví dụ ở bài 3.2.2, hộp chính có năm số tiến và hộp phụ có hai cấp, kết hợp thành mười số tiến. Vị trí lắp và cách sử dụng từng cấp phụ thuộc sơ đồ hộp số.","key":"range-gearbox","keywords":["hộp số nhiều cấp","hộp số 10 cấp","hộp chia số","hộp số phụ","bộ chia số","splitter","hộp số chính và hộp số phụ"],"anchor":"block-1781147139469-ph4xu9lrv","more":["three-shaft","synchro"]},{"id":"s2089","kind":"topic","lesson":"3.3.2","title":"Cơ cấu khóa hãm gài số","text":"Cơ cấu khóa hãm ngăn gài đồng thời hai cấp số. Trong kết cấu minh họa, tấm khóa hạn chế chuyển động của các càng chưa được chọn, để chỉ càng của cấp số đang chọn dịch chuyển theo hướng gài.","key":"gear-interlock","keywords":["cơ cấu khóa hãm hộp số chính","gài hai số cùng lúc","chống gài 2 số","khóa hãm gài số","tấm khóa càng chuyển số"],"anchor":"block-1781147738699-ludmub8ee","more":["synchro","three-shaft"]},{"id":"s2090","kind":"topic","lesson":"5.2.2","title":"Tuần hoàn công suất khi nối cứng hai cầu","text":"Khi hai cầu được nối cứng, tốc độ quy đổi của hai trục ra bị ràng buộc. Quãng đường lăn hoặc bán kính lăn khác nhau có thể gây tải xoắn tích lũy trong hệ truyền lực, nhất là trên mặt đường có độ bám cao. Bài 5.2.2 minh họa hộp phân phối đơn giản có thể tách cầu trước khi đi đường tốt.","key":"driveline-windup","keywords":["tuần hoàn công suất","gài hai cầu trên đường tốt","dẫn động hai cầu nối cứng","driveline windup"],"anchor":"block-1781161916808-3i03hre7s","more":["transfer","differential"]},{"id":"s2091","kind":"topic","lesson":"6.2.2","title":"Then hoa trượt và vú mỡ trên trục các đăng","text":"Mối ghép then hoa trượt truyền mô men đồng thời cho phép thay đổi chiều dài làm việc của cụm trục. Ở kết cấu có vú mỡ trong bài, mỡ được cấp tới mối ghép then hoa qua vú mỡ. Dấu lắp ráp trên hai nửa trục giúp đặt đúng tương quan góc giữa các nạng.","key":"cardan-spline","keywords":["mối ghép then hoa di trượt","vú mỡ bôi trơn khớp các đăng","vú mỡ trên trục các đăng","bôi trơn then hoa các đăng","dấu lắp ráp trên then hoa","bù chiều dài các đăng"],"anchor":"block-1781162713680-510vlyslf","figureNumber":"6.6","more":["cardan","cross-joint","constant-velocity"]},{"id":"s2092","kind":"topic","lesson":"8.1.1","title":"Đọc thông số trên thành lốp","text":"Trong ví dụ 195/55 R16 87V, 195 là chiều rộng danh nghĩa tính bằng milimét, 55 là tỷ lệ chiều cao tiết diện trên chiều rộng tính theo phần trăm, R chỉ kết cấu bố hướng kính và 16 là đường kính vành tính bằng inch. Mã 87 là chỉ số tải trọng và V là ký hiệu cấp tốc độ, cần tra theo bảng tương ứng.","key":"tire-markings","keywords":["chỉ số tải trọng lốp","chỉ số tốc độ lốp","ký hiệu lốp 195 55 r16 87v","195/55 R16 87V","đọc ký hiệu lốp","thông số lốp xe"],"anchor":"block-1781164047048-hgjz2k8uc","more":["wheel-balance","tire-pressure"]},{"id":"s2093","kind":"topic","lesson":"10.3.2","title":"Công dụng và nguyên lý trợ lực phanh chân không","text":"Bầu trợ lực dùng chênh lệch áp suất giữa hai khoang để tăng lực tác dụng lên pít-tông xi lanh chính. Trong sơ đồ Tập 2, khi đạp phanh, cửa nối chân không đóng và cửa khí quyển mở ở một khoang. Chênh lệch áp suất tác dụng lên màng, hỗ trợ lực đạp của người lái.","key":"vacuum-booster","keywords":["bộ trợ lực chân không","bầu trợ lực chân không","trợ lực phanh chân không","trợ lực chân không phanh","brake booster"],"pages":[77,78],"figureNumber":"10.42","more":["abs","air-brake"]},{"id":"s2094","kind":"topic","lesson":"12.1.3","title":"Khung rời và thân vỏ chịu lực","text":"Trong kết cấu thân vỏ rời, khung là bộ phận chịu tải chính và thân xe được lắp trên khung. Ở dạng thân vỏ chịu tải hoàn toàn, hệ sàn, dầm và các phần thân vỏ cùng tham gia chịu tải. Tập 2 còn minh họa dạng trung gian là thân vỏ chịu tải một phần.","key":"unibody","keywords":["khung rời","thân vỏ rời","khung liền vỏ","thân vỏ liền khối","unibody","monocoque","body on frame","so sánh khung rời và khung liền"],"pages":[159,160],"figureNumber":"12.23","more":["tire-pressure","tipper"]},{"id":"s2095","kind":"topic","lesson":"3.1.1","title":"Chức năng của hộp số chính","text":"Hộp số chính thay đổi tỷ số truyền để điều chỉnh mô men và tốc độ quay đưa tới bánh xe chủ động. Nhờ đó lực kéo và vận tốc phù hợp hơn với điều kiện chuyển động. Số lùi tạo chiều chuyển động lùi. Ở số trung gian, dòng truyền mô men qua hộp số được ngắt.","key":"gearbox-purpose","keywords":["chức năng của hộp số ô tô","công dụng hộp số","nhiệm vụ của hộp số","hộp số dùng để làm gì"],"anchor":"block-1781146415111-szni1qjv5","more":["manual-types","reverse-gear","three-shaft"]},{"id":"s2096","kind":"topic","lesson":"3.1.2","title":"Phân loại hộp số cơ khí","text":"Có thể phân loại hộp số theo trạng thái trục, theo số trục chính, theo số cấp truyền và theo phương pháp điều khiển. Hộp số hai trục có trục vào và trục ra. Hộp số ba trục có thêm trục trung gian. Cần xét riêng số trục và số cấp truyền khi đọc sơ đồ.","key":"manual-types","keywords":["phân loại hộp số cơ khí","các loại hộp số cơ khí","phân loại theo số trục hộp số","phân loại theo số cấp số truyền"],"anchor":"block-1781146472253-ozt17qsh4","more":["two-shaft","three-shaft","range-gearbox"]},{"id":"s2097","kind":"topic","lesson":"3.2.2","title":"Đường truyền khi gài số lùi","text":"Trong sơ đồ hộp số cơ khí ở bài 3.2.2, bánh răng trung gian số lùi tham gia đường truyền khi gài số lùi. Số lần ăn khớp thay đổi làm trục thứ cấp quay theo chiều ngược với trường hợp gài số tiến, nhờ đó xe có thể chuyển động lùi.","key":"reverse-gear","keywords":["nguyên tắc tạo số lùi","số lùi trong hộp số","bánh răng trung gian số lùi","số lùi đảo chiều","đường truyền số lùi","vì sao xe chạy lùi"],"anchor":"block-1781147139469-ph4xu9lrv","more":["three-shaft","gearbox-purpose"]},{"id":"s2098","kind":"topic","lesson":"3.2.2","title":"Số truyền tăng trong hộp số cơ khí","text":"Với quy ước i = tốc độ trục vào chia cho tốc độ trục ra, số truyền tăng có i nhỏ hơn 1. Trong ví dụ hộp số ba trục ở bài 3.2.2, số 5 là số truyền tăng. Việc cấp số nào có tỷ số nhỏ hơn 1 phụ thuộc thiết kế từng hộp số.","key":"overdrive","keywords":["số truyền tăng","nguyên lý tạo số truyền tăng","số 5 truyền tăng","overdrive hộp số cơ khí"],"anchor":"block-1781147139469-ph4xu9lrv","more":["three-shaft","range-gearbox"]},{"id":"s2099","kind":"topic","lesson":"4.1.1","title":"Chức năng của hộp số tự động","text":"Hộp số tự động lựa chọn tỷ số truyền phù hợp với điều kiện vận hành. Bộ điều khiển nhận thông tin về trạng thái xe và yêu cầu công suất, sau đó điều khiển các phần tử chấp hành để thay đổi đường truyền hoặc tỷ số truyền. Cách chuyển số phụ thuộc kiểu hộp số.","key":"automatic-purpose","keywords":["công dụng của hộp số tự động","chức năng hộp số tự động","hộp số tự động dùng để làm gì","tự chọn tỷ số truyền"],"anchor":"block-1781160086335-cirbkek25","more":["automatic-types","dct","cvt"]},{"id":"s2100","kind":"topic","lesson":"4.1.2","title":"Các dạng hộp số tự động trong học liệu","text":"Chương 4 trình bày hộp số cơ khí được tự động hóa, hộp số tự động có cấp dùng biến mô thủy lực và hộp số tự động vô cấp. Khi nhận diện, hãy xem cơ cấu truyền chính, cách thay đổi tỷ số truyền và cách điều khiển phần tử chấp hành.","key":"automatic-types","keywords":["phân loại các dạng hộp số tự động","hộp số tự động có những loại nào","các loại hộp số tự động","phân loại hộp số tự động"],"anchor":"block-1781160105309-xtr72k2z1","more":["dct","converter","cvt"]},{"id":"s2101","kind":"topic","lesson":"7.1.1","title":"Chức năng của cầu chủ động","text":"Cầu chủ động nhận mô men từ hệ thống truyền lực và đưa tới các bánh xe chủ động. Trong sơ đồ của bài, truyền lực chính giảm tốc độ và tăng mô men, vi sai cho phép hai bánh quay khác tốc độ khi quay vòng, còn bán trục truyền mô men tới bánh xe.","key":"drive-axle-purpose","keywords":["chức năng của cầu chủ động","công dụng cầu chủ động","các cụm chi tiết chính trong cầu chủ động","cầu chủ động gồm những gì"],"anchor":"block-1781163137301-wj2wcrxg2","more":["final-drive","differential","halfshaft"]},{"id":"s2102","kind":"topic","lesson":"7.2.2","title":"Khóa vi sai giữa hai bánh xe","text":"Trong sơ đồ khóa vi sai bằng khớp gài, khớp nối một bán trục với vỏ vi sai. Khi khóa, cơ cấu buộc hai bán trục quay cùng tốc độ và hạn chế sự chênh lệch tốc độ giữa hai bánh. Bài 7.2.2 trình bày riêng khóa giữa các bánh và khóa giữa các cầu.","key":"diff-lock","keywords":["khóa vi sai","gài khóa vi sai","differential lock","khóa cứng vi sai","vi sai khóa khi nào"],"anchor":"block-1781163690877-vk7c69gbg","more":["differential","drive-axle-purpose"]},{"id":"s2103","kind":"topic","lesson":"8.2.1","title":"Công dụng của cụm bánh xe","text":"Vành giữ lốp và liên kết cụm bánh với moay-ơ. Lốp đỡ tải, tiếp xúc mặt đường để truyền lực kéo, lực phanh và lực ngang, đồng thời góp phần giảm chấn động. Cần đối chiếu kích thước vành với quy cách lắp lốp.","key":"wheel-assembly","keywords":["công dụng của cụm bánh xe","cấu tạo tổng quát của cụm bánh xe","chức năng của cụm bánh xe","cụm bánh xe gồm những gì"],"anchor":"block-1781164522875-oo488p6ij","more":["tire-markings","wheel-balance"]}]};
